ROUTE_AWARE_CANDIDATE_INTENT_TYPES = FUNCTIONAL_ROUTE_INTENT_TYPES | ROUTE_SCOPED_EXPERIENCE_INTENT_TYPES
CANDIDATE_HINT_CACHE_TTL_SECONDS = 7 * 24 * 60 * 60
MAX_CANDIDATE_HINT_CACHE_ENTRIES = 256
