class AgentService:
    def __init__(
        self,
        db: sqlite3.Connection,
        provider=None,
        poi_resolution_service: Optional[PoiResolutionService] = None,
        timeline_mutation_service: Optional[TimelineMutationTransactionService] = None,
        provider_route_insertion_service: Optional[ProviderRouteInsertionService] = None,
        named_boundary_provider: Optional[NamedBoundaryProvider] = None,
    ):
        self.db = db
        self._execution_event_sequences: dict[str, int] = {}
        self.provider = provider or create_agent_provider()
        self.poi_resolution_service = poi_resolution_service or PoiResolutionService(db)
        self.portfolio_density_continuation = PortfolioDensityContinuationService(db)
        self.skill_service = AgentSkillService()
        self.planner_service = AgentPlannerService()
        self.autonomy_context_projector = AutonomyContextProjector()
        self.autonomy_observation_builder = AgentObservationBuilder()
        self.autonomy_arbitrator = AgentDecisionArbitrator()
        self.autonomy_stop_policy = AgentStopPolicy()
        self.action_executor_registry = AgentActionExecutorRegistry(
            [
                AskUserExecutor(self._execute_ask_user_executor),
                DraftItineraryExecutor(self._execute_draft_itinerary_executor),
                SimpleOpenDraftItineraryExecutor(self._execute_simple_open_draft_itinerary_executor),
                ReadItineraryExecutor(self._execute_read_itinerary_executor),
                ResolvePoiExecutor(self._execute_resolve_poi_executor),
                OptimizeRouteExecutor(self._execute_optimize_route_executor),
                TimelineMutationExecutor(self._execute_timeline_mutation_executor),
                ComplexPatchExecutor(self._execute_complex_patch_executor),
                VerifyExternalFactsExecutor(self._execute_verify_external_facts_executor),
                FinishExecutor(self._execute_finish_executor),
            ]
        )
        self.turn_coordinator = AgentTurnCoordinator(self.action_executor_registry)
        settings = get_settings()
        self.settings = settings
        self.named_boundary_provider = named_boundary_provider or (
            OverpassNamedBoundaryProvider(
                endpoint=settings.named_boundary_overpass_url,
                timeout_seconds=settings.named_boundary_timeout_seconds,
                max_vertices=40,
                max_deviation_meters=settings.named_boundary_simplification_max_deviation_meters,
            )
            if settings.named_boundary_provider == "osm_overpass"
            else DisabledNamedBoundaryProvider()
        )
        self.experience_grounding_v2_mode = settings.agent_experience_grounding_v2_mode
        self.soft_slot_draft_adoption_enabled = settings.agent_soft_slot_draft_adoption_enabled
        self.creative_output_quality_v2_mode = settings.agent_creative_output_quality_v2_mode
        self.initial_planning_mode = settings.agent_initial_planning_mode
        self.autonomy_controller = AgentAutonomyController(
            provider=self.provider,
            planner_service=self.planner_service,
            fallback_decision_resolver=self.autonomy_arbitrator,
            decision_timeout_seconds=settings.agent_controller_decision_timeout_seconds,
            lite_timeout_seconds=settings.agent_controller_lite_timeout_seconds,
            total_budget_seconds=settings.agent_controller_total_budget_seconds,
        )
        self.conversation_capability_resolver = ConversationCapabilityResolver(db)
        self.conversation_intent_router = ConversationIntentRouter(
            lite_classifier=self.autonomy_controller.classify_conversation_intent,
            routing_mode=settings.agent_intent_routing_mode,
        )
        self.output_parser = AgentOutputParser()
        self.output_repair_service = AgentOutputRepairService(self.provider, max_attempts=1)
        self.meal_grounding_policy = MealGroundingPolicy()
        self.campus_candidate_policy = CampusCandidatePolicy()
        self.intent_candidate_semantic_policy = IntentCandidateSemanticPolicy()
        self.itinerary_diversity_policy = ItineraryDiversityPolicy()
        self.meal_candidate_quality_policy = MealCandidateQualityPolicy()
        self.meal_diversity_policy = MealDiversityPolicy()
        self.cross_day_poi_reuse_policy = CrossDayPoiReusePolicy()
        self.meal_experience_assignment_policy = MealExperienceAssignmentPolicy()
        self.poi_trust_policy = PoiTrustPolicy()
        self.night_view_candidate_policy = NightViewCandidatePolicy()
        self.route_insertion_scorer = RouteInsertionScorer()
        self.provider_route_insertion_service = provider_route_insertion_service or ProviderRouteInsertionService()
        self.map_poi_service = MapPoiService()
        self.simple_open_itinerary_executor = SimpleOpenItineraryExecutor(
            self.map_poi_service,
            route_assignment_service=SimpleOpenRouteAssignmentService(
                route_leg_provider=self.provider_route_insertion_service
            ),
        )
        self.portfolio_route_feasibility_service = PortfolioRouteFeasibilityService(
            map_poi_service=self.map_poi_service,
            route_insertion_scorer=self.route_insertion_scorer,
        )
        self.portfolio_candidate_discovery_service = PortfolioCandidateDiscoveryService()
        self.rule_safe_draft_executor = RuleSafeDraftExecutor()
        self.timeline_command_planner = TimelineCommandPlanner()
        self.timeline_mutation_ingress = TimelineMutationIngress()
        self.timeline_mutation_service = timeline_mutation_service or TimelineMutationTransactionService(db)
        self.context_builder = AgentContextBuilder(
            db,
            requirement_analyzer=self._understand_requirements,
            preference_impact_analyzer=self._preference_impact,
        )
        self._active_run_timing: Optional[AgentRunTiming] = None
        self._pipeline_event_perf: Optional[float] = None
        self._staged_pipeline_deadline: Optional[float] = None
        self._staged_pipeline_started: Optional[float] = None

    def bind_spatial_map_selection(
        self,
        *,
        session_id: str,
        source_assistant_turn_id: str,
        checkpoint_id: str,
        checkpoint_fingerprint: str,
        amap_poi_id: str,
        label: str,
        radius_meters: float,
    ) -> dict[str, Any]:
        """Seal a map POI identity to one current clarification checkpoint.

        Browser coordinates never enter this contract. The batch answer carries
        only the opaque fingerprint; canonical coordinates are loaded from AMap
        after the user atomically submits the clarification batch.
        """

        active_rows = self.db.execute(
            """SELECT id, agent_response_json FROM conversation_turns
               WHERE session_id = ? AND role = 'assistant' AND status = 'active'
               ORDER BY turn_index DESC""",
            (session_id,),
        ).fetchall()
        current_row = next(
            (
                row
                for row in active_rows
                if isinstance(self._json_dict(row["agent_response_json"]).get("clarificationCheckpoint"), dict)
            ),
            None,
        )
        if current_row is None or str(current_row["id"]) != source_assistant_turn_id:
            raise HTTPException(
                status_code=409,
                detail={"code": "spatial_map_selection_stale", "message": "当前活动区域问题已变化，请刷新后重试。"},
            )
        payload = self._json_dict(current_row["agent_response_json"])
        checkpoint = payload.get("clarificationCheckpoint")
        if not isinstance(checkpoint, dict) or (
            str(checkpoint.get("checkpointId") or "") != checkpoint_id
            or str(checkpoint.get("fingerprint") or "") != checkpoint_fingerprint
            or str(checkpoint.get("status") or "") != "awaiting_answer"
        ):
            raise HTTPException(
                status_code=409,
                detail={"code": "spatial_map_selection_stale", "message": "当前活动区域问题已变化，请刷新后重试。"},
            )
        questions = [item for item in checkpoint.get("questions") or [] if isinstance(item, dict)]
        spatial_question = next(
            (item for item in questions if str(item.get("dimensionId") or "") == "spatial_focus"),
            None,
        )
        if spatial_question is None:
            raise HTTPException(
                status_code=409,
                detail={"code": "spatial_map_selection_not_available", "message": "当前批次没有活动区域问题。"},
            )
        identity = {
            "sessionId": session_id,
            "sourceAssistantTurnId": source_assistant_turn_id,
            "checkpointId": checkpoint_id,
            "checkpointFingerprint": checkpoint_fingerprint,
            "amapPoiId": str(amap_poi_id).strip().upper(),
            "radiusMeters": float(radius_meters),
        }
        if not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", identity["amapPoiId"]):
            raise HTTPException(
                status_code=422,
                detail={"code": "spatial_map_selection_identity_invalid", "message": "地图地点身份无效。"},
            )
        selection_fingerprint = hashlib.sha256(
            json.dumps(identity, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        option_id = f"spatial_map_{selection_fingerprint[:16]}"
        option_label = f"地图选点：{str(label).strip()} · {float(radius_meters) / 1000:g}km"
        selections = (
            checkpoint.get("spatialMapSelections") if isinstance(checkpoint.get("spatialMapSelections"), dict) else {}
        )
        selections[selection_fingerprint] = {
            **identity,
            "label": str(label).strip(),
            "boundAt": datetime.now(timezone.utc).isoformat(),
        }
        checkpoint["spatialMapSelections"] = selections
        binding_fingerprints = [
            str(item) for item in checkpoint.get("spatialMapSelectionBindingFingerprints") or [] if str(item).strip()
        ]
        if checkpoint_fingerprint not in binding_fingerprints:
            binding_fingerprints.append(checkpoint_fingerprint)
        checkpoint["spatialMapSelectionBindingFingerprints"] = binding_fingerprints
        options = [
            item
            for item in spatial_question.get("options") or []
            if isinstance(item, dict) and str(item.get("id") or "") != option_id
        ]
        options.append(
            {
                "id": option_id,
                "label": option_label,
                "semanticValue": {
                    "spatialResolutionInput": {
                        "kind": "map_selection",
                        "mapSelectionFingerprint": selection_fingerprint,
                    }
                },
            }
        )
        spatial_question["options"] = options
        checkpoint["fingerprint"] = ClarificationCheckpointService._fingerprint(
            {key: value for key, value in checkpoint.items() if key != "fingerprint"}
        )
        payload["clarificationCheckpoint"] = checkpoint
        for option in payload.get("choiceOptions") or []:
            if not isinstance(option, dict):
                continue
            if (
                str(option.get("scopeKind") or "") == "clarification"
                and str(option.get("checkpointId") or "") == checkpoint_id
            ):
                option["checkpointFingerprint"] = checkpoint["fingerprint"]
        now = datetime.now(timezone.utc).isoformat()
        self.db.execute(
            "UPDATE conversation_turns SET agent_response_json = ?, updated_at = ? WHERE id = ? AND session_id = ?",
            (
                json.dumps(payload, ensure_ascii=False, separators=(",", ":"), default=str),
                now,
                source_assistant_turn_id,
                session_id,
            ),
        )
        self.db.commit()
        return {
            "optionId": option_id,
            "label": option_label,
            "mapSelectionFingerprint": selection_fingerprint,
            "checkpoint": checkpoint,
        }

    def _start_agent_run_timing(self) -> AgentRunTiming:
        timing = AgentRunTiming(
            started_at=datetime.now(timezone.utc),
            started_perf=time.perf_counter(),
        )
        self._active_run_timing = timing
        return timing

    def _run_elapsed_ms(self, timing: Optional[AgentRunTiming] = None) -> int:
        active = timing or self._active_run_timing
        if active is None:
            return 0
        return max(0, int((time.perf_counter() - active.started_perf) * 1000))

    def _run_timing_metadata(
        self,
        metadata: Optional[dict[str, Any]] = None,
        *,
        timing: Optional[AgentRunTiming] = None,
        finished_at: Optional[datetime] = None,
    ) -> dict[str, Any]:
        active = timing or self._active_run_timing
        base = dict(metadata or {})
        if active is None:
            return base
        elapsed_ms = self._run_elapsed_ms(active)
        base.setdefault("runStartedAt", active.started_at.isoformat())
        base["runElapsedMs"] = elapsed_ms
        if finished_at is not None:
            base["runFinishedAt"] = finished_at.isoformat()
            base["runDurationMs"] = elapsed_ms
        return base

    def _event_duration_ms(self, event: dict[str, Any]) -> int:
        raw = event.get("durationMs") or event.get("duration_ms")
        if raw is not None:
            try:
                return max(0, int(float(raw)))
            except (TypeError, ValueError):
                pass
        started = self._parse_event_datetime(event.get("startedAt"))
        finished = self._parse_event_datetime(event.get("finishedAt") or event.get("timestamp"))
        if started is None or finished is None:
            return 0
        return max(0, int((finished - started).total_seconds() * 1000))

    def _parse_event_datetime(self, value: Any) -> Optional[datetime]:
        if not value:
            return None
        text = str(value)
        try:
            parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        except ValueError:
            return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed

    def _emit_execution_event(
        self,
        event_sink: Optional[AgentExecutionEventSink],
        *,
        session_id: str,
        event_type: str,
        label: str,
        detail: str,
        turn_id: Optional[str] = None,
        status: str = "querying",
        metadata: Optional[dict] = None,
        provider_name: Optional[str] = None,
        fallback_used: bool = False,
        failure_reason: Optional[str] = None,
        duration_ms: int = 0,
    ) -> None:
        if event_sink is None:
            return
        event = AgentPlanningEventResponse(
            type=event_type,
            label=label,
            status=status,
            detail=detail,
            sessionId=session_id,
            turnId=turn_id,
            providerName=provider_name,
            fallbackUsed=fallback_used,
            failureReason=self._friendly_failure_reason(failure_reason),
            durationMs=max(0, int(duration_ms or 0)),
            metadata=self._run_timing_metadata(metadata),
            timestamp=datetime.now(timezone.utc).isoformat(),
        )
        event_sink(self._sequence_stream_event(session_id, event, turn_id=turn_id))

    def _emit_tool_execution_event(
        self,
        event_sink: Optional[AgentExecutionEventSink],
        *,
        session_id: str,
        turn_id: str,
        event: dict[str, Any],
    ) -> None:
        if event_sink is None:
            return
        status = str(event.get("status") or "completed")
        if status == "succeeded":
            status = "completed"
        if status == "running":
            status = "querying"
        if status not in {"completed", "fallback", "failed", "querying", "waiting"}:
            status = "completed"
        duration_ms = self._event_duration_ms(event)
        event_metadata = self._run_timing_metadata(event.get("metadata") or {})
        event_metadata.setdefault("toolName", str(event.get("toolName") or event.get("label") or "tool"))
        planning_event = AgentPlanningEventResponse(
            type=str(event.get("type") or "tool"),
            label=str(event.get("label") or event.get("toolName") or "tool"),
            status=status,
            detail=str(event.get("detail") or event.get("outputSummary") or "工具执行完成。"),
            sessionId=session_id,
            turnId=turn_id,
            providerName=event.get("providerName"),
            fallbackUsed=bool(event.get("fallbackUsed")),
            failureReason=self._friendly_failure_reason(event.get("failureReason")),
            durationMs=duration_ms,
            metadata=event_metadata,
            timestamp=str(event.get("timestamp") or event.get("finishedAt") or datetime.now(timezone.utc).isoformat()),
        )
        event_sink(self._sequence_stream_event(session_id, planning_event, turn_id=turn_id))

    def _sequence_stream_event(
        self,
        session_id: str,
        event: AgentPlanningEventResponse,
        *,
        turn_id: Optional[str],
    ) -> AgentPlanningEventResponse:
        enriched = enrich_action_trace_events([event], goal=self._action_trace_goal(turn_id))[0]
        if bool(getattr(enriched, "user_visible", False)):
            sequence = self._execution_event_sequences.get(session_id, 0) + 1
            self._execution_event_sequences[session_id] = sequence
            enriched.sequence = sequence
            metadata = enriched.metadata if isinstance(enriched.metadata, dict) else {}
            action_trace = metadata.get("actionTrace") if isinstance(metadata.get("actionTrace"), dict) else {}
            action_trace["sequence"] = sequence
            metadata["actionTrace"] = action_trace
            enriched.metadata = metadata
        return enriched

    def send_message(
        self,
        session_id: str,
        payload: AgentMessageRequest,
        event_sink: Optional[AgentExecutionEventSink] = None,
        user_turn_sink: Optional[AgentUserTurnSink] = None,
    ) -> AgentMessageResponse:
        content = payload.content.strip()
        from src.services.agent_ingress_journal import AgentIngressJournal

        ingress = AgentIngressJournal(self.db)
        request_id = payload.request_id
        request_payload = payload.model_dump(by_alias=True, mode="json")
        if request_id:
            existing = ingress.existing(session_id, request_id, request_payload)
            if existing is not None:
                return AgentMessageResponse.model_validate(ingress.replay(session_id, existing))
        if not content and payload.context.selected_agent_choice is None:
            raise HTTPException(status_code=400, detail="Agent message content is required")
        if not self._acquire_session_run_lease(session_id):
            raise HTTPException(
                status_code=409, detail={"code": "run_in_progress", "message": "该会话已有进行中的 Agent 修改请求。"}
            )
        timing = self._start_agent_run_timing()
        self._execution_event_sequences[session_id] = 0
        user_turn_id: Optional[str] = None
        self._ingress_turn_id = None
        try:
            if request_id:
                user_turn_id, claimed = ingress.claim(session_id, request_id, request_payload)
                if not claimed:
                    return AgentMessageResponse.model_validate(ingress.replay(
                        session_id, ingress.existing(session_id, request_id, request_payload)))
                self._ingress_turn_id = user_turn_id
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                event_type="agent_run",
                label="Agent 规划计时",
                detail="Agent 已开始处理本轮规划请求。",
                metadata={"timingSource": "agent_service", "phase": "run_started"},
            )
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                event_type="context",
                label="接收用户消息",
                detail="已收到用户消息，正在准备进入 Agent 执行流程。",
            )
            replay = self._replay_succeeded_clarification_batch_before_turn(session_id, payload) if not request_id else None
            if replay is not None:
                if user_turn_sink is not None:
                    user_turn_sink(replay.user_turn)
                self._emit_agent_run_terminal_event(
                    event_sink,
                    session_id=session_id,
                    turn_id=replay.assistant_turn.id,
                    timing=timing,
                    status="completed",
                    detail="已返回原批量确认结果，未创建新会话 turn。",
                )
                return replay
            ConversationService(self.db).expire_pending_candidates(session_id)
            if user_turn_id is None:
                user_turn_id = self._insert_turn(session_id, "user", content, "active")
            if not bind_session_run_turn(session_id, user_turn_id):
                raise HTTPException(status_code=409, detail="agent_run_turn_binding_failed")
            if user_turn_sink is not None:
                user_turn_sink(self._turn_response(user_turn_id))
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="context",
                label="记录用户消息",
                detail="用户消息已写入会话，下一步构建 Agent 请求上下文。",
            )
            self.assert_session_run_active(session_id)
            response = self._generate_for_user_turn(session_id, user_turn_id, content, payload, event_sink=event_sink)
            self._complete_controller_choice_execution(session_id, user_turn_id, response)
            self.assert_session_run_active(session_id)
            self._apply_controller_memory_policy(session_id, response.assistant_turn.id)
            finalized = self._finalize_generated_response(session_id, response)
            completed = self._finalize_agent_run_timing(
                finalized,
                session_id=session_id,
                event_sink=event_sink,
                timing=timing,
                status="completed" if finalized.assistant_turn.status != "failed" else "failed",
            )
            if request_id:
                ingress.update(user_turn_id, state="completed", stage="finalized",
                    assistantTurnId=completed.assistant_turn.id,
                    activeVersionId=self._session(session_id)["active_version_id"],
                    response=completed.model_dump(by_alias=True, mode="json"))
                self.db.commit()
            return completed
        except Exception as error:
            if isinstance(error, HTTPException) and error.status_code == 499 and user_turn_id:
                self._cancel_fallback_choice_execution(session_id, user_turn_id)
            elif user_turn_id:
                self._fail_fallback_choice_execution(session_id, user_turn_id, error)
            if request_id and user_turn_id:
                ingress.update(user_turn_id, state="failed", stage="interrupted_or_failed",
                    httpStatus=error.status_code if isinstance(error, HTTPException) else 409,
                    error=error.detail if isinstance(error, HTTPException) else {
                        "code": "request_interrupted_unknown", "message": "原请求执行未完成，结果需核对；未再次执行。"})
                self.db.commit()
            self._emit_agent_run_terminal_event(
                event_sink,
                session_id=session_id,
                turn_id=None,
                timing=timing,
                status="failed",
                detail="Agent 本轮规划失败。",
                failure_reason=self._error_message(error),
            )
            raise
        finally:
            self._ingress_turn_id = None
            self._active_run_timing = None
            self._execution_event_sequences.pop(session_id, None)
            self._release_session_run_lease(session_id)

    @staticmethod
    def _acquire_session_run_lease(session_id: str) -> bool:
        return acquire_session_run(session_id)

    def _attach_turn_planning_run(self, assistant_turn_id: str, planning_run: Any) -> None:
        planning_run_id = str(getattr(planning_run, "id", "") or "").strip()
        if not planning_run_id:
            return
        self.db.execute(
            "UPDATE conversation_turns SET planning_run_id = ?, updated_at = ? WHERE id = ?",
            (planning_run_id, datetime.now(timezone.utc).isoformat(), assistant_turn_id),
        )
        self.db.commit()

    def _finalize_generated_response(
        self,
        session_id: str,
        response: AgentMessageResponse,
    ) -> AgentMessageResponse:
        self._attach_turn_planning_run(response.assistant_turn.id, response.planning_run)
        if self.conversation_intent_router.routing_mode == "active-all":
            from src.services.conversation_capability_carrier import ConversationCapabilityCarrier
            request_row = self.db.execute("SELECT agent_request_json FROM conversation_turns WHERE id = ? AND session_id = ?",
                                          (response.user_turn.id, session_id)).fetchone()
            request = self._json_dict(request_row[0]) if request_row else {}
            route = request.get("conversationIntent") or {}
            nonexecuting = (route.get("executionDisposition") in {"read_only", "no_write", "clarify"}
                            and not request.get("selectedAgentChoice") and response.version is None)
            result_row = self.db.execute("SELECT agent_response_json FROM conversation_turns WHERE id=? AND session_id=?",
                (response.assistant_turn.id, session_id)).fetchone()
            if (result_row and self._json_dict(result_row[0]).get("mode") == "clarification"
                    and response.version is None and not request.get("selectedAgentChoice")):
                # A structured preflight clarification grants no execution.
                # The carrier still checks unchanged writes and no new root.
                nonexecuting = True
            claim_id = (request.get("fallbackChoiceExecutionClaim") or {}).get("id")
            if claim_id and response.version is None:
                from src.services.conversation_operation_identity import ConversationOperationIdentity
                settled = self.db.execute("SELECT * FROM agent_choice_executions WHERE id = ? AND session_id = ?", (claim_id, session_id)).fetchone()
                nonexecuting = bool(settled and ConversationOperationIdentity.explicitly_unstarted(dict(settled)))
            try:
                ConversationCapabilityCarrier(self.db).carry(session_id, response.assistant_turn.id,
                    request.get("capabilityIngress") or {}, nonexecuting=nonexecuting)
            except ValueError:
                self.db.rollback()
        if self.initial_planning_mode == "simple_open_v1":
            try:
                SimpleOpenDirectionService(self.db).reconcile_legacy_guide_capability_carrier(
                    session_id=session_id,
                )
            except ValueError:
                # A concurrent capability rotation is safe to expose as the
                # unchanged response. Never recover by searching an older turn.
                self.db.rollback()
        persisted_user_turn = self.db.execute(
            "SELECT 1 FROM conversation_turns WHERE id = ?",
            (response.user_turn.id,),
        ).fetchone()
        if persisted_user_turn is not None:
            response.user_turn = self._turn_response(response.user_turn.id)
        response.assistant_turn = self._turn_response(response.assistant_turn.id)
        return self.finalize_agent_response_with_memory(session_id, response)

    @staticmethod
    def _release_session_run_lease(session_id: str) -> None:
        release_session_run(session_id)

    @staticmethod
    def cancel_session_run(session_id: str) -> bool:
        return request_session_run_cancel(session_id)

    @staticmethod
    def assert_session_run_active(session_id: str) -> None:
        assert_session_run_active(session_id)

    def _finalize_agent_run_timing(
        self,
        response: AgentMessageResponse,
        *,
        session_id: str,
        event_sink: Optional[AgentExecutionEventSink],
        timing: AgentRunTiming,
        status: str,
    ) -> AgentMessageResponse:
        response.execution_mode = self._response_execution_mode(response)
        response.terminal_status = self._response_terminal_status(response, status)
        response.agent_decision_count = sum(
            1 for item in response.planning_steps or [] if str(getattr(item, "type", "")) == "agent_decision"
        )
        response.outcome_statuses = self._response_outcome_statuses(response)
        detail = "Agent 本轮规划已完成。" if status == "completed" else "Agent 本轮规划失败。"
        event = self._agent_run_terminal_event(
            session_id=session_id,
            turn_id=response.assistant_turn.id,
            timing=timing,
            status=status,
            detail=detail,
            failure_reason=response.assistant_turn.failure_reason if status == "failed" else None,
        )
        event.metadata["outcomeStatuses"] = dict(response.outcome_statuses)
        existing_planning_events = list(response.planning_steps or [])
        event.sequence = max((int(item.sequence or 0) for item in existing_planning_events), default=0) + 1
        planning_events = [*existing_planning_events, event]
        response.planning_steps = planning_events
        coordinator_owned = any(
            item.type == "agent_observation" and item.provider_name == "agent-turn-coordinator"
            for item in planning_events
        )
        response.tool_events = (
            list(response.tool_events or []) if coordinator_owned else [*list(response.tool_events or []), event]
        )
        response.assistant_turn.planning_steps = planning_events
        response.assistant_turn.tool_events = response.tool_events
        self._store_planning_events(response.assistant_turn.id, planning_events)
        self._store_agent_outcome(response)
        self.db.commit()
        if event_sink is not None:
            event_sink(event)
        return response

    def _response_execution_mode(self, response: AgentMessageResponse) -> str:
        events = list(response.planning_steps or [])
        for event in events:
            metadata = event.metadata if isinstance(event.metadata, dict) else {}
            preview = metadata.get("resultPreview") if isinstance(metadata.get("resultPreview"), dict) else {}
            if (
                preview.get("deterministicInitialPlanUsed")
                or preview.get("fallbackType") == "deterministic_initial_plan"
            ):
                return "deterministic_fallback" if preview.get("fallbackUsed") else "deterministic_fast_path"
            if event.type == "initial_day_slot_provider" and preview.get("providerReturnedMode") in {
                "day_slots",
                "full_itinerary",
            }:
                return "bounded_agent"
            timeline_command = (
                preview.get("timelineCommand") if isinstance(preview.get("timelineCommand"), dict) else {}
            )
            if event.type == "timeline_edit" and (preview.get("toolLoopEntered") is False or timeline_command):
                return "deterministic_fast_path"
        run_type = str(getattr(response.planning_run, "run_type", "") or "")
        if "tool_call" in run_type:
            return "bounded_agent"
        if "staged" in run_type:
            return "deterministic_fallback" if any(event.fallback_used for event in events) else "bounded_agent"
        return "deterministic_fast_path"

    def _response_terminal_status(self, response: AgentMessageResponse, status: str) -> str:
        if status != "completed" or response.assistant_turn.status == "failed":
            return "failed"
        shared_source = getattr(response.assistant_turn, "shared_source", None)
        if isinstance(shared_source, dict):
            # Success belongs to this read-only intake, not to itinerary planning.
            return "success" if shared_source.get("status") == "completed" else "no_safe_action"
        simple_open_result = any(
            isinstance(event.metadata, dict)
            and (
                event.metadata.get("actualExecutionRoute") == "simple_open_initial_pipeline"
                or (
                    isinstance(event.metadata.get("resultPreview"), dict)
                    and event.metadata["resultPreview"].get("executionRoute") == "simple_open_initial_pipeline"
                )
            )
            for event in response.planning_steps or []
        )
        for event in reversed(response.planning_steps or []):
            metadata = event.metadata if isinstance(event.metadata, dict) else {}
            preview = metadata.get("resultPreview") if isinstance(metadata.get("resultPreview"), dict) else {}
            root_blocker = preview.get("rootGlobalBlocker")
            if isinstance(root_blocker, dict) and root_blocker.get("status") == "candidate_refresh_required":
                return "candidate_refresh_required"
        raw_terminal_status = str(getattr(response, "terminal_status", "") or "")
        if (
            simple_open_result
            and raw_terminal_status in {"needs_confirmation", "partial_success"}
            and response.version is not None
        ):
            # A simple-open persisted draft is a usable terminal result unless
            # the response carries an actual opaque selection.  It must not
            # force the user to send a second "continue" message merely to
            # acknowledge a local uncertainty.
            if not response.pending_poi_candidates:
                return "partial"
        has_candidate_selection = any(
            str(getattr(event, "type", "")) == "candidate_selection" for event in response.planning_steps or []
        )
        if (
            raw_terminal_status == "needs_confirmation"
            and response.version is not None
            and not response.pending_poi_candidates
            and not has_candidate_selection
        ):
            # A persisted draft that merely has an ungrounded gap is editable
            # and truthful, but it is not waiting for an opaque user choice.
            return "draft_pending_grounding"
        if raw_terminal_status in {
            "candidate_refresh_required",
            "draft_pending_grounding",
            "needs_confirmation",
        }:
            return raw_terminal_status
        if raw_terminal_status in {"no_change", "no_safe_action"}:
            return "no_safe_action"
        guide_advice = getattr(response.assistant_turn, "guide_advice", None)
        if isinstance(guide_advice, dict):
            return "success" if str(guide_advice.get("status") or "") == "completed" else "no_safe_action"
        mutation_outcome = getattr(response.assistant_turn, "timeline_mutation_outcome", None)
        if isinstance(mutation_outcome, dict):
            mutation_status = str(mutation_outcome.get("status") or "")
            if mutation_status == "needs_confirmation":
                return "needs_confirmation"
            if mutation_status == "no_change":
                return "no_safe_action"
            if mutation_status in {"failed", "rolled_back"}:
                return "failed"
        for event in reversed(response.planning_steps or []):
            if str(getattr(event, "type", "")) != "agent_stop":
                continue
            metadata = event.metadata if isinstance(event.metadata, dict) else {}
            preview = metadata.get("resultPreview") if isinstance(metadata.get("resultPreview"), dict) else {}
            stop_reason = str(metadata.get("stopReason") or preview.get("stopReason") or "")
            if stop_reason == "needs_confirmation":
                return "needs_confirmation"
            if stop_reason in {
                "observation_invalid",
                "no_safe_action",
                "policy_rejected",
                "policy_gate_rejected",
            }:
                return "no_safe_action"
        awaiting_choice = any(
            str(getattr(event, "type", "")) == "candidate_selection" for event in response.planning_steps or []
        )
        if response.version is None and (response.pending_poi_candidates or awaiting_choice):
            return "needs_confirmation"
        if response.version is None:
            return "no_safe_action"
        if any(self._warning_requires_partial_status(item) for item in response.warnings):
            return "partial_success"
        return "success"

    def _warning_requires_partial_status(self, value: object) -> bool:
        text = str(value or "").strip()
        if not text:
            return False
        informational_patterns = (
            "预约、风险和天气核验未在初始关键路径执行",
            "出行日期不在当前天气 forecast window 内",
            "部分地点使用了备用搜索词补充候选，结果仍按真实地图匹配与路线约束筛选",
        )
        return not any(pattern in text for pattern in informational_patterns)

    def _store_agent_outcome(self, response: AgentMessageResponse) -> None:
        row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
            (response.assistant_turn.id,),
        ).fetchone()
        if row is None:
            return
        try:
            payload = json.loads(row["agent_response_json"] or "{}")
        except json.JSONDecodeError:
            payload = {}
        payload.update(
            {
                "executionMode": response.execution_mode,
                "terminalStatus": response.terminal_status,
                "agentDecisionCount": response.agent_decision_count,
                "outcomeStatuses": response.outcome_statuses,
            }
        )
        self.db.execute(
            "UPDATE conversation_turns SET agent_response_json = ?, updated_at = ? WHERE id = ?",
            (
                json.dumps(payload, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                response.assistant_turn.id,
            ),
        )

    def _response_outcome_statuses(self, response: AgentMessageResponse) -> dict[str, str]:
        itinerary = response.itinerary
        awaiting_choice = any(
            str(getattr(event, "type", "")) == "candidate_selection" for event in response.planning_steps or []
        )
        if itinerary is None:
            return {
                "itineraryStatus": "needs_confirmation" if response.pending_poi_candidates else "not_created",
                "mapStatus": "pending" if response.pending_poi_candidates else "not_applicable",
                "routeStatus": "not_applicable",
                "reservationStatus": "not_checked",
                "sourceQualityStatus": "pending" if response.pending_poi_candidates else "not_applicable",
            }
        if getattr(response, "terminal_status", "") == "draft_pending_grounding":
            return {
                "itineraryStatus": "draft_pending_grounding",
                "mapStatus": "pending",
                "routeStatus": "pending",
                "reservationStatus": "not_checked",
                "sourceQualityStatus": "pending",
            }
        segments = [segment for day in itinerary.days for segment in day.segments]
        map_relevant = [segment for segment in segments if segment.kind in {"visit", "activity", "meal"}]
        map_ready_count = sum(1 for segment in map_relevant if bool(getattr(segment.poi, "map_ready", False)))
        map_status = (
            "ready"
            if not map_relevant or map_ready_count == len(map_relevant)
            else "partial"
            if map_ready_count
            else "pending"
        )
        route_options = list(getattr(itinerary, "route_options", None) or [])
        required_route_legs = 0
        for day in itinerary.days:
            anchors = [
                segment
                for segment in day.segments
                if segment.kind in {"visit", "activity", "meal"} and bool(getattr(segment.poi, "routeable", False))
            ]
            required_route_legs += max(0, len(anchors) - 1)
        covered_route_legs = len(
            {
                (str(getattr(route, "from_segment_id", "") or ""), str(getattr(route, "to_segment_id", "") or ""))
                for route in route_options
                if bool(getattr(route, "is_selected", False)) and not getattr(route, "error", None)
            }
        )
        route_status = (
            "not_required"
            if required_route_legs == 0
            else "ready"
            if covered_route_legs >= required_route_legs
            else "partial"
            if covered_route_legs
            else "pending"
        )
        ticket_results = list(getattr(itinerary, "ticket_lookup_results", None) or [])
        reservation_status = "not_checked"
        if ticket_results:
            reservation_status = (
                "ready" if all(not getattr(item, "failure_reason", None) for item in ticket_results) else "partial"
            )
        grounded_sources = [str(getattr(segment.poi, "source", "") or "") for segment in map_relevant]
        source_status = (
            "verified"
            if grounded_sources and all(source == AMAP_PLACE_SOURCE for source in grounded_sources)
            else "mixed"
        )
        return {
            "itineraryStatus": "accepted" if response.version is not None else "unchanged",
            "mapStatus": "candidates_ready" if awaiting_choice else map_status,
            "routeStatus": "unchanged" if awaiting_choice else route_status,
            "reservationStatus": reservation_status,
            "sourceQualityStatus": source_status,
        }

    def _emit_agent_run_terminal_event(
        self,
        event_sink: Optional[AgentExecutionEventSink],
        *,
        session_id: str,
        turn_id: Optional[str],
        timing: AgentRunTiming,
        status: str,
        detail: str,
        failure_reason: Optional[str] = None,
    ) -> None:
        if event_sink is None:
            return
        event_sink(
            self._agent_run_terminal_event(
                session_id=session_id,
                turn_id=turn_id,
                timing=timing,
                status=status,
                detail=detail,
                failure_reason=failure_reason,
            )
        )

    def _agent_run_terminal_event(
        self,
        *,
        session_id: str,
        turn_id: Optional[str],
        timing: AgentRunTiming,
        status: str,
        detail: str,
        failure_reason: Optional[str] = None,
    ) -> AgentPlanningEventResponse:
        finished_at = datetime.now(timezone.utc)
        duration_ms = self._run_elapsed_ms(timing)
        return AgentPlanningEventResponse(
            type="agent_run",
            label="Agent 规划耗时",
            status=status,
            detail=detail,
            sessionId=session_id,
            turnId=turn_id,
            providerName="agent-service",
            fallbackUsed=False,
            failureReason=self._friendly_failure_reason(failure_reason),
            durationMs=duration_ms,
            metadata=self._run_timing_metadata(
                {
                    "timingSource": "agent_service",
                    "phase": "run_finished",
                },
                timing=timing,
                finished_at=finished_at,
            ),
            timestamp=finished_at.isoformat(),
        )

    def edit_user_message(
        self, session_id: str, turn_id: str, payload: AgentMessageEditRequest
    ) -> AgentMessageEditResponse:
        if not self._acquire_session_run_lease(session_id):
            raise HTTPException(
                status_code=409,
                detail={"code": "run_in_progress", "message": "该会话已有进行中的 Agent 修改请求。"},
            )
        try:
            self.assert_session_run_active(session_id)
            response = self._edit_user_message_locked(session_id, turn_id, payload)
            self.assert_session_run_active(session_id)
            return response
        finally:
            self._release_session_run_lease(session_id)

    def _edit_user_message_locked(
        self, session_id: str, turn_id: str, payload: AgentMessageEditRequest
    ) -> AgentMessageEditResponse:
        content = payload.content.strip()
        if not content:
            raise HTTPException(status_code=400, detail="Agent message content is required")
        session = self._session(session_id)
        turn = self.db.execute(
            "SELECT * FROM conversation_turns WHERE id = ? AND session_id = ?",
            (turn_id, session_id),
        ).fetchone()
        if turn is None:
            raise HTTPException(status_code=404, detail="Conversation turn not found")
        if turn["role"] != "user":
            raise HTTPException(status_code=400, detail="Only user messages can be edited")
        if turn["status"] == "superseded":
            raise HTTPException(status_code=409, detail="Superseded messages cannot be edited in MVP")
        version = self._version_for_turn_restore(turn, session)
        now = datetime.now(timezone.utc).isoformat()
        superseded_turn_ids = [
            turn_id,
            *[
                row["id"]
                for row in self.db.execute(
                    """
                SELECT id FROM conversation_turns
                WHERE session_id = ? AND turn_index > ? AND status != 'superseded'
                ORDER BY turn_index ASC, created_at ASC
                """,
                    (session_id, turn["turn_index"]),
                ).fetchall()
            ],
        ]
        if superseded_turn_ids:
            self.db.execute(
                f"""
                UPDATE conversation_turns
                SET status = 'superseded', updated_at = ?
                WHERE id IN ({",".join("?" for _ in superseded_turn_ids)})
                """,
                (now, *superseded_turn_ids),
            )
        edited_turn_id = self._insert_turn(
            session_id,
            "user",
            content,
            "active",
            parent_turn_id=turn_id,
        )
        if version is not None:
            self._restore_session_to_version(session, version)
        else:
            self._restore_session_to_empty_plan(session)
        if payload.regenerate:
            ConversationService(self.db).expire_pending_candidates(session_id)
        self.db.commit()

        restored_version = self._version_response(version) if version is not None else None
        if not payload.regenerate:
            restored_itinerary = (
                ItineraryService(self.db).get_plan(session["active_plan_id"]) if version is not None else None
            )
            verifier_report = self._safe_verify_current_state(self._session(session_id), "agent_edit_restore")
            planning_events = self._edit_restore_trace(
                session_id, edited_turn_id, version["id"] if version is not None else None, verifier_report
            )
            return AgentMessageEditResponse(
                editedTurn=self._turn_response(edited_turn_id),
                supersededTurnIds=superseded_turn_ids,
                restoredVersionId=version["id"] if version is not None else None,
                assistantTurn=None,
                itinerary=restored_itinerary,
                version=restored_version,
                pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
                warnings=[],
                planningRun=None,
                planningSteps=planning_events,
                toolEvents=planning_events,
            )

        generated = self._finalize_generated_response(
            session_id,
            self._generate_for_user_turn(session_id, edited_turn_id, content, payload),
        )
        return AgentMessageEditResponse(
            editedTurn=generated.user_turn,
            supersededTurnIds=superseded_turn_ids,
            restoredVersionId=version["id"] if version is not None else None,
            assistantTurn=generated.assistant_turn,
            itinerary=generated.itinerary,
            version=generated.version,
            pendingPoiCandidates=generated.pending_poi_candidates,
            warnings=generated.warnings,
            planningRun=generated.planning_run,
            planningSteps=generated.planning_steps,
            toolEvents=generated.tool_events,
        )

    def _generate_for_user_turn(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        payload: Union[AgentMessageRequest, AgentMessageEditRequest],
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> AgentMessageResponse:
        session = self._session(session_id)
        user_turn = self._turn_response(user_turn_id)
        if self.conversation_intent_router.routing_mode == "active-all":
            from src.services.conversation_capability_carrier import ConversationCapabilityCarrier
            from src.services.agent_ingress_journal import AgentIngressJournal
            latest = self.conversation_capability_resolver._latest_assistant_carrier(session_id)
            captured = ConversationCapabilityCarrier(self.db).capture(session_id, latest["turnId"]) if latest else {}
            saved = self._json_dict(self.db.execute("SELECT agent_request_json FROM conversation_turns WHERE id = ?", (user_turn_id,)).fetchone()[0])
            saved["capabilityIngress"] = captured
            self.db.execute("UPDATE conversation_turns SET agent_request_json = ? WHERE id = ?", (json.dumps(saved, ensure_ascii=False), user_turn_id))
            AgentIngressJournal(self.db).update(user_turn_id, stage="interpreting")
            self.db.commit()
        payload, intent_route, capability_resolution = self._route_conversation_turn(
            session=session,
            content=content,
            payload=payload,
        )
        if (intent_route.semantic_action or {}).get("name") == "read_shared_guide" and not intent_route.requires_clarification:
            return self._execute_shared_travel_source(session, user_turn_id, content, intent_route)
        if (intent_route.semantic_action or {}).get("sharedSourceBinding") and not intent_route.requires_clarification:
            from src.services.shared_travel_source_service import SharedTravelSourceService
            SharedTravelSourceService(self.db).bind_initial_request(session_id, user_turn_id, intent_route.to_context())
        self._emit_execution_event(
            event_sink,
            session_id=session_id,
            turn_id=user_turn_id,
            event_type="context",
            label="构建 Agent 请求上下文",
            detail="正在读取当前行程、偏好、地图选择和时间轴版本上下文。",
        )
        request_context = self._build_request_context(
            session,
            content,
            payload,
            deterministic_fast_path=False,
            current_user_turn_id=user_turn_id,
            defer_agent_decision=True,
            allow_plan_expansion_rebind=False,
            conversation_intent_route=intent_route.to_context(),
            conversation_capability_resolution=capability_resolution.to_context(),
        )
        selected_choice_for_replay = (
            request_context.get("selectedAgentChoice")
            if isinstance(request_context.get("selectedAgentChoice"), dict)
            else {}
        )
        selected_option_for_replay = (
            selected_choice_for_replay.get("option")
            if isinstance(selected_choice_for_replay.get("option"), dict)
            else {}
        )
        choice_claim_for_replay = (
            request_context.get("fallbackChoiceExecutionClaim")
            if isinstance(request_context.get("fallbackChoiceExecutionClaim"), dict)
            else {}
        )
        if (
            str(selected_option_for_replay.get("kind") or "") == "simple_direction_more_plans"
            and str(choice_claim_for_replay.get("status") or "") == "succeeded"
        ):
            return self._replay_density_choice_execution(
                user_turn,
                session,
                selected_choice_for_replay,
                choice_claim_for_replay,
            )
        if (
            str(selected_option_for_replay.get("kind") or "") == "travel_guide_advice"
            and str(selected_choice_for_replay.get("action") or "") == "search_travel_guide_advice"
        ):
            if str(choice_claim_for_replay.get("status") or "") == "succeeded":
                return self._replay_density_choice_execution(
                    user_turn,
                    session,
                    selected_choice_for_replay,
                    choice_claim_for_replay,
                )
            return self._execute_travel_guide_advice(
                user_turn=user_turn,
                session=session,
                request_context=request_context,
                selected_choice=selected_choice_for_replay,
                execution=choice_claim_for_replay,
            )
        # The execution profile is a server-owned capability boundary for every
        # turn, including opaque choice continuations.  A client-projected or
        # restored Portfolio checkpoint must never select a stricter pipeline
        # while Simple Open is active.
        request_context["serverExecutionProfile"] = self.initial_planning_mode
        pre_restore_choice = (
            request_context.get("selectedAgentChoice")
            if isinstance(request_context.get("selectedAgentChoice"), dict)
            else {}
        )
        pre_restore_option = (
            pre_restore_choice.get("option") if isinstance(pre_restore_choice.get("option"), dict) else {}
        )
        pre_restore_density_replay_exists = False
        if self.portfolio_density_continuation.is_density_option(pre_restore_option):
            pre_restore_source_turn_id = str(pre_restore_choice.get("sourceAssistantTurnId") or "")
            pre_restore_choice_id = str(
                pre_restore_choice.get("persistedChoiceId") or pre_restore_choice.get("choiceId") or ""
            )
            pre_restore_action = str(pre_restore_choice.get("action") or pre_restore_option.get("action") or "")
            if pre_restore_source_turn_id and pre_restore_choice_id and pre_restore_action:
                pre_restore_density_replay_exists = (
                    self.db.execute(
                        """
                        SELECT 1 FROM agent_choice_executions
                        WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?
                          AND action = ? AND status = 'succeeded'
                        """,
                        (
                            session_id,
                            pre_restore_source_turn_id,
                            pre_restore_choice_id,
                            pre_restore_action,
                        ),
                    ).fetchone()
                    is not None
                )
        if (
            self.portfolio_density_continuation.is_density_option(pre_restore_option)
            and not session["active_version_id"]
            and not pre_restore_density_replay_exists
        ):
            # A density continuation mutates one exact slot of the current
            # persisted partial timeline.  Without that timeline, reject
            # before restoring a checkpoint, acquiring its claim, or touching
            # any provider; the opaque request remains auditable only.
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_partial_timeline_missing",
                    "message": "当前没有可安全补槽的部分时间轴，请先恢复上次规划检查点。",
                },
            )
        # This capability is server-issued only after the persisted partial
        # expansion option passes active version/root/fingerprint validation.
        request_context.pop("_partialPlanExpansionAuthorized", None)
        self._restore_request_intent_contract(session_id, request_context)
        self._restore_active_route_decision_contract(request_context)
        if request_context.get("densityChoiceSourceContextMissing") is True:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "agent_choice_source_context_missing",
                    "message": "该地点选择缺少原规划上下文，请刷新缺失地点候选后重试。",
                },
            )
        if not isinstance(request_context.get("requestIntentContract"), dict):
            request_context["requestIntentContract"] = self._request_intent_contract(
                str(request_context.get("effectiveUserMessage") or request_context.get("latestUserMessage") or ""),
                self._resolve_trip_dates_from_context(request_context),
                self._meal_grounding_policy_result(request_context),
                city=str(request_context.get("selectedCity") or ""),
                simple_open_profile=self.initial_planning_mode == "simple_open_v1",
            )
        spatial_answer = (
            request_context.get("spatialClarificationAnswer")
            if isinstance(request_context.get("spatialClarificationAnswer"), dict)
            else {}
        )
        if spatial_answer:
            source_turn_id = str(spatial_answer.get("sourceAssistantTurnId") or "")
            source_row = self.db.execute(
                "SELECT agent_request_json, agent_response_json FROM conversation_turns "
                "WHERE id = ? AND session_id = ? AND role = 'assistant' AND status = 'active'",
                (source_turn_id, session_id),
            ).fetchone()
            source_request = self._json_dict(source_row["agent_request_json"]) if source_row is not None else {}
            source_response = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
            source_checkpoint = (
                source_response.get("clarificationCheckpoint")
                if isinstance(source_response.get("clarificationCheckpoint"), dict)
                else source_request.get("clarificationCheckpoint")
                if isinstance(source_request.get("clarificationCheckpoint"), dict)
                else {}
            )
            if (
                source_row is None
                or str(source_checkpoint.get("checkpointId") or "") != str(spatial_answer.get("checkpointId") or "")
                or str(source_checkpoint.get("fingerprint") or "")
                != str(spatial_answer.get("checkpointFingerprint") or "")
            ):
                raise HTTPException(
                    status_code=409,
                    detail={"code": "spatial_clarification_stale", "message": "活动区域问题已变化，请刷新后继续。"},
                )
            questions = [item for item in source_checkpoint.get("questions") or [] if isinstance(item, dict)]
            source_question = next(
                (item for item in questions if str(item.get("dimensionId") or "") == "spatial_focus"),
                {},
            )
            normalization_context = {
                "schemaVersion": "clarification-batch-normalization-context-v1",
                "questions": [
                    {
                        "dimensionId": "spatial_focus",
                        "question": str(source_question.get("question") or "请明确活动区域。"),
                        "manualValue": str(spatial_answer.get("manualValue") or ""),
                        "allowedSemanticFields": ["spatialResolutionInput"],
                        "semanticFieldSchemas": ClarificationCheckpointService.semantic_field_schemas(
                            ["spatialResolutionInput"]
                        ),
                    }
                ],
            }
            normalized = self._normalize_clarification_batch_manual_answers(normalization_context)
            semantic_value = normalized.get("spatial_focus")
            if not ClarificationCheckpointService.valid_semantic_patch(
                semantic_value,
                allowed_fields={"spatialResolutionInput"},
            ):
                raise HTTPException(
                    status_code=422,
                    detail={
                        "code": "spatial_clarification_normalization_invalid",
                        "message": "活动区域表达未能转换为可核验类型；当前没有进入规划。",
                    },
                )
            source_contract = (
                source_request.get("requestIntentContract")
                if isinstance(source_request.get("requestIntentContract"), dict)
                else request_context["requestIntentContract"]
            )
            applied_checkpoint = copy.deepcopy(source_checkpoint)
            applied_checkpoint["resolvedAnswers"] = [
                {
                    "dimensionId": "spatial_focus",
                    "semanticValue": copy.deepcopy(semantic_value),
                    "source": "natural_language_clarification_answer",
                    "sourceUserTurnId": user_turn_id,
                }
            ]
            request_context["requestIntentContract"] = self._request_contract_after_clarification(
                source_contract,
                applied_checkpoint,
                request_context,
            )
            request_context["clarificationCheckpoint"] = applied_checkpoint
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            spatial_response = self._spatial_grounding_response_if_needed(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                content=content,
                request_context=request_context,
            )
            if spatial_response is not None:
                return spatial_response
        selected_choice = request_context.get("selectedAgentChoice")
        selected_option = (
            selected_choice.get("option")
            if isinstance(selected_choice, dict) and isinstance(selected_choice.get("option"), dict)
            else {}
        )
        selected_action = (
            str((selected_choice or {}).get("action") or selected_option.get("action") or "")
            if isinstance(selected_choice, dict)
            else ""
        )
        if selected_action == "retry_spatial_grounding":
            source_assistant_turn_id = str((selected_choice or {}).get("sourceAssistantTurnId") or "")
            source_row = self.db.execute(
                "SELECT agent_request_json, agent_response_json FROM conversation_turns "
                "WHERE id = ? AND session_id = ? AND role = 'assistant' AND status = 'active'",
                (source_assistant_turn_id, session_id),
            ).fetchone()
            source_response = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
            source_request = self._json_dict(source_row["agent_request_json"]) if source_row is not None else {}
            source_contract = (
                source_request.get("requestIntentContract")
                if isinstance(source_request.get("requestIntentContract"), dict)
                else {}
            )
            source_spatial = (
                source_contract.get("spatialPreference")
                if isinstance(source_contract.get("spatialPreference"), dict)
                else {}
            )
            pending = (
                source_spatial.get("pendingGrounding")
                if isinstance(source_spatial.get("pendingGrounding"), dict)
                else {}
            )
            checkpoint = (
                source_response.get("clarificationCheckpoint")
                if isinstance(source_response.get("clarificationCheckpoint"), dict)
                else {}
            )
            request_fingerprint = str(
                source_contract.get("fingerprint") or SpatialPreferenceService.fingerprint(source_contract)
            )
            pending_fingerprint = SpatialPreferenceService.fingerprint(pending) if pending else ""
            current_authority = self._latest_pending_spatial_clarification(session_id)
            spatial_input = self._spatial_resolution_input_for_grounding(source_contract, pending)
            if (
                source_row is None
                or current_authority is None
                or current_authority["sourceAssistantTurnId"] != source_assistant_turn_id
                or current_authority["checkpointId"] != str(checkpoint.get("checkpointId") or "")
                or current_authority["checkpointFingerprint"] != str(checkpoint.get("fingerprint") or "")
                or current_authority["planningSelectionRootTurnId"] != str(checkpoint.get("planningRootId") or "")
                or str(selected_option.get("scopeKind") or "") != "clarification"
                or str(selected_option.get("kind") or "") != "spatial_grounding_retry"
                or str(selected_option.get("checkpointId") or "") != str(checkpoint.get("checkpointId") or "")
                or str(selected_option.get("checkpointFingerprint") or "") != str(checkpoint.get("fingerprint") or "")
                or str(selected_option.get("planningSelectionRootTurnId") or "")
                != str(checkpoint.get("planningRootId") or "")
                or str(selected_option.get("requestContractFingerprint") or "") != request_fingerprint
                or str(selected_option.get("pendingGroundingFingerprint") or "") != pending_fingerprint
                or str(source_spatial.get("status") or "") not in {"unresolved", "grounding_pending"}
                or spatial_input is None
            ):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "spatial_grounding_retry_identity_mismatch",
                        "message": "活动区域核验状态已变化，请刷新后继续。",
                    },
                )
            spatial_claim = self._claim_fallback_choice_execution(session_id, user_turn_id, selected_choice)
            request_context["fallbackChoiceExecutionClaim"] = spatial_claim
            if spatial_claim["status"] == "succeeded":
                return self._replay_clarification_batch_execution(
                    user_turn,
                    session,
                    selected_choice,
                    spatial_claim,
                )
            grounding_context = copy.deepcopy(source_request)
            for key in ("selectedCity", "city", "understoodRequirements"):
                if key not in grounding_context and key in request_context:
                    grounding_context[key] = copy.deepcopy(request_context[key])
            grounding_context["requestIntentContract"] = copy.deepcopy(source_contract)
            try:
                spatial_grounding = self._ground_spatial_answer(
                    spatial_input,
                    request_context=grounding_context,
                )
            except HTTPException:
                spatial_grounding = {
                    "status": "grounding_pending",
                    "reason": "provider_unavailable",
                }
            request_context["requestIntentContract"] = copy.deepcopy(source_contract)
            spatial = request_context["requestIntentContract"]["spatialPreference"]
            candidate_resolution = spatial_grounding.get("resolution")
            if spatial_grounding.get("status") == "resolved" and SpatialPreferenceService.is_executable_resolution(
                candidate_resolution
            ):
                spatial["status"] = "resolved"
                spatial["resolution"] = copy.deepcopy(candidate_resolution)
                spatial.pop("pendingGrounding", None)
            else:
                spatial["status"] = str(spatial_grounding.get("status") or "grounding_pending")
                spatial.pop("resolution", None)
                spatial["pendingGrounding"] = {
                    **copy.deepcopy(spatial_grounding),
                    "spatialResolutionInput": copy.deepcopy(spatial_input),
                }
            spatial_resolved = str(spatial.get("status") or "") == "resolved"
            for dimension in request_context["requestIntentContract"].get("clarificationDimensions") or []:
                if isinstance(dimension, dict) and str(dimension.get("dimensionId") or "") == "spatial_focus":
                    dimension["status"] = "resolved" if spatial_resolved else str(spatial.get("status") or "unresolved")
            unresolved = [
                str(item.get("dimensionId") or "")
                for item in request_context["requestIntentContract"].get("clarificationDimensions") or []
                if isinstance(item, dict) and str(item.get("status") or "") != "resolved"
            ]
            request_context["requestIntentContract"]["clarificationRequired"] = bool(unresolved)
            request_context["requestIntentContract"]["clarificationReason"] = (
                "spatial_focus_confirmation_required"
                if spatial_grounding.get("status") == "confirmation_pending"
                else "spatial_focus_radius_required"
                if spatial_grounding.get("nextAction") == "radius_required"
                else "spatial_focus_grounding_required"
                if not spatial_resolved
                else unresolved[0]
                if unresolved
                else ""
            )
            spatial["fingerprint"] = SpatialPreferenceService.fingerprint(
                {key: value for key, value in spatial.items() if key != "fingerprint"}
            )
            request_context["clarificationCheckpoint"] = copy.deepcopy(checkpoint)
            request_context["spatialBoundaryChoice"] = copy.deepcopy(selected_choice)
            request_context.pop("selectedAgentChoice", None)
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            spatial_response = self._spatial_grounding_response_if_needed(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                content=content,
                request_context=request_context,
            )
            if spatial_response is not None:
                return spatial_response
            selected_choice = None
            selected_option = {}
            selected_action = ""
        if selected_action == "select_spatial_boundary_candidate":
            source_assistant_turn_id = str((selected_choice or {}).get("sourceAssistantTurnId") or "")
            source_row = self.db.execute(
                "SELECT agent_request_json, agent_response_json FROM conversation_turns "
                "WHERE id = ? AND session_id = ? AND role = 'assistant' AND status = 'active'",
                (source_assistant_turn_id, session_id),
            ).fetchone()
            source_response = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
            source_request = self._json_dict(source_row["agent_request_json"]) if source_row is not None else {}
            source_contract = (
                source_request.get("requestIntentContract")
                if isinstance(source_request.get("requestIntentContract"), dict)
                else {}
            )
            source_spatial = (
                source_contract.get("spatialPreference")
                if isinstance(source_contract.get("spatialPreference"), dict)
                else {}
            )
            pending = (
                source_spatial.get("pendingGrounding")
                if isinstance(source_spatial.get("pendingGrounding"), dict)
                else {}
            )
            checkpoint = (
                source_response.get("clarificationCheckpoint")
                if isinstance(source_response.get("clarificationCheckpoint"), dict)
                else {}
            )
            candidate_fingerprint = str(selected_option.get("candidateFingerprint") or "")
            candidate = next(
                (
                    item
                    for item in pending.get("boundaryCandidates") or []
                    if isinstance(item, dict) and str(item.get("candidateFingerprint") or "") == candidate_fingerprint
                ),
                None,
            )
            request_fingerprint = str(
                source_contract.get("fingerprint") or SpatialPreferenceService.fingerprint(source_contract)
            )
            candidate_material = (
                {key: value for key, value in candidate.items() if key != "candidateFingerprint"}
                if isinstance(candidate, dict)
                else {}
            )
            candidate_integrity_valid = bool(
                candidate_material and SpatialPreferenceService.fingerprint(candidate_material) == candidate_fingerprint
            )
            current_authority = self._latest_pending_spatial_clarification(session_id)
            if (
                source_row is None
                or current_authority is None
                or current_authority["sourceAssistantTurnId"] != source_assistant_turn_id
                or current_authority["checkpointId"] != str(checkpoint.get("checkpointId") or "")
                or current_authority["checkpointFingerprint"] != str(checkpoint.get("fingerprint") or "")
                or current_authority["planningSelectionRootTurnId"] != str(checkpoint.get("planningRootId") or "")
                or str(selected_option.get("scopeKind") or "") != "clarification"
                or str(selected_option.get("checkpointId") or "") != str(checkpoint.get("checkpointId") or "")
                or str(selected_option.get("checkpointFingerprint") or "") != str(checkpoint.get("fingerprint") or "")
                or str(selected_option.get("planningSelectionRootTurnId") or "")
                != str(checkpoint.get("planningRootId") or "")
                or str(selected_option.get("requestContractFingerprint") or "") != request_fingerprint
                or str(source_spatial.get("status") or "") != "grounding_pending"
                or str(pending.get("reason") or "") != "multiple_closed_boundaries"
                or not candidate_integrity_valid
            ):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "spatial_boundary_candidate_identity_mismatch",
                        "message": "活动区域候选身份已变化，请刷新后继续。",
                    },
                )
            spatial_claim = self._claim_fallback_choice_execution(session_id, user_turn_id, selected_choice)
            request_context["fallbackChoiceExecutionClaim"] = spatial_claim
            if spatial_claim["status"] == "succeeded":
                return self._replay_clarification_batch_execution(
                    user_turn,
                    session,
                    selected_choice,
                    spatial_claim,
                )
            wgs_polygon = [
                (float(point[0]), float(point[1]))
                for point in candidate.get("wgs84Polygon") or []
                if isinstance(point, (list, tuple)) and len(point) == 2
            ]
            if len(wgs_polygon) > 40 or not SpatialGeometryService.valid_closed_polygon(wgs_polygon):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "spatial_boundary_candidate_geometry_invalid",
                        "message": "活动区域候选几何已变化，请修改区域表达。",
                    },
                )
            request_context["requestIntentContract"] = copy.deepcopy(source_contract)
            spatial = request_context["requestIntentContract"]["spatialPreference"]
            try:
                converted = self.map_poi_service.convert_wgs84_coordinates(wgs_polygon)
            except HTTPException:
                pending["coordinateConversionStatus"] = "incomplete"
                spatial["pendingGrounding"] = pending
                request_context["spatialBoundaryChoice"] = copy.deepcopy(selected_choice)
                request_context.pop("selectedAgentChoice", None)
                self._persist_agent_request_context(session_id, user_turn_id, request_context)
                return self._spatial_grounding_response_if_needed(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    user_turn=user_turn,
                    session=session,
                    content=content,
                    request_context=request_context,
                )
            wgs_fingerprint = SpatialPreferenceService.fingerprint({"polygon": wgs_polygon})
            gcj_fingerprint = SpatialPreferenceService.fingerprint({"polygon": converted})
            source_entity_id = str(candidate.get("sourceEntityId") or "")
            evidence = {
                "schemaVersion": "named-boundary-evidence-v1",
                "provider": "osm_overpass",
                "sourceUrl": f"https://www.openstreetmap.org/{source_entity_id}",
                "sourceEntityId": source_entity_id,
                "sourceVersion": candidate.get("sourceVersion"),
                "retrievedAt": str(candidate.get("retrievedAt") or ""),
                "contentHash": str(candidate.get("contentHash") or ""),
                "license": "ODbL-1.0",
                "attribution": "© OpenStreetMap contributors",
                "boundaryText": str(pending.get("boundaryText") or ""),
                "canonicalName": str(candidate.get("canonicalName") or ""),
                "containment": str(pending.get("containment") or ""),
                "connectedComponentCount": int(candidate.get("connectedComponentCount") or 0),
                "closedCycleCount": int(candidate.get("closedCycleCount") or 0),
                "originalVertexCount": int(candidate.get("originalVertexCount") or 0),
                "simplifiedVertexCount": int(candidate.get("simplifiedVertexCount") or 0),
                "simplificationMaxDeviationMeters": float(candidate.get("simplificationMaxDeviationMeters") or 0),
                "wgs84GeometryFingerprint": wgs_fingerprint,
                "gcj02GeometryFingerprint": gcj_fingerprint,
                "gcj02Polygon": [[longitude, latitude] for longitude, latitude in converted],
            }
            evidence_fingerprint = SpatialPreferenceService.fingerprint(evidence)
            spatial["status"] = "confirmation_pending"
            spatial["pendingGrounding"] = {
                "status": "confirmation_pending",
                "reason": "boundary_confirmation_required",
                "boundaryEvidenceFingerprint": evidence_fingerprint,
                "boundaryEvidence": evidence,
                "resolution": {
                    "kind": "named_boundary_polygon",
                    "containment": str(pending.get("containment") or ""),
                    "boundaryEvidenceFingerprint": evidence_fingerprint,
                    "polygonGcj02": copy.deepcopy(evidence["gcj02Polygon"]),
                },
            }
            spatial["fingerprint"] = SpatialPreferenceService.fingerprint(
                {key: value for key, value in spatial.items() if key != "fingerprint"}
            )
            request_context["spatialBoundaryChoice"] = copy.deepcopy(selected_choice)
            request_context.pop("selectedAgentChoice", None)
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            return self._spatial_grounding_response_if_needed(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                content=content,
                request_context=request_context,
            )
        if selected_action in {"confirm_spatial_boundary", "change_spatial_boundary"}:
            source_assistant_turn_id = str((selected_choice or {}).get("sourceAssistantTurnId") or "")
            source_row = self.db.execute(
                "SELECT agent_request_json, agent_response_json FROM conversation_turns "
                "WHERE id = ? AND session_id = ? AND role = 'assistant' AND status = 'active'",
                (source_assistant_turn_id, session_id),
            ).fetchone()
            source_response = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
            source_request = self._json_dict(source_row["agent_request_json"]) if source_row is not None else {}
            preview = (
                source_response.get("spatialBoundaryPreview")
                if isinstance(source_response.get("spatialBoundaryPreview"), dict)
                else {}
            )
            source_contract = (
                source_request.get("requestIntentContract")
                if isinstance(source_request.get("requestIntentContract"), dict)
                else {}
            )
            source_spatial = (
                source_contract.get("spatialPreference")
                if isinstance(source_contract.get("spatialPreference"), dict)
                else {}
            )
            pending = (
                source_spatial.get("pendingGrounding")
                if isinstance(source_spatial.get("pendingGrounding"), dict)
                else {}
            )
            checkpoint = (
                source_response.get("clarificationCheckpoint")
                if isinstance(source_response.get("clarificationCheckpoint"), dict)
                else {}
            )
            boundary_fingerprint = str(pending.get("boundaryEvidenceFingerprint") or "")
            pending_fingerprint = SpatialPreferenceService.fingerprint(pending) if pending else ""
            request_fingerprint = str(
                source_contract.get("fingerprint") or SpatialPreferenceService.fingerprint(source_contract)
            )
            current_authority = self._latest_pending_spatial_clarification(session_id)
            base_identity_invalid = (
                source_row is None
                or current_authority is None
                or current_authority["sourceAssistantTurnId"] != source_assistant_turn_id
                or current_authority["checkpointId"] != str(checkpoint.get("checkpointId") or "")
                or current_authority["checkpointFingerprint"] != str(checkpoint.get("fingerprint") or "")
                or current_authority["planningSelectionRootTurnId"] != str(checkpoint.get("planningRootId") or "")
                or str(selected_option.get("scopeKind") or "") != "clarification"
                or str(selected_option.get("checkpointId") or "") != str(checkpoint.get("checkpointId") or "")
                or str(selected_option.get("checkpointFingerprint") or "") != str(checkpoint.get("fingerprint") or "")
                or str(selected_option.get("planningSelectionRootTurnId") or "")
                != str(checkpoint.get("planningRootId") or "")
                or str(selected_option.get("requestContractFingerprint") or "") != request_fingerprint
            )
            confirmation_identity_invalid = bool(
                selected_action == "confirm_spatial_boundary"
                and (
                    str(source_spatial.get("status") or "") != "confirmation_pending"
                    or not boundary_fingerprint
                    or str(selected_option.get("boundaryEvidenceFingerprint") or "") != boundary_fingerprint
                    or str(preview.get("boundaryEvidenceFingerprint") or "") != boundary_fingerprint
                )
            )
            change_identity_invalid = bool(
                selected_action == "change_spatial_boundary"
                and (
                    str(source_spatial.get("status") or "")
                    not in {"unresolved", "grounding_pending", "confirmation_pending"}
                    or (
                        str(selected_option.get("pendingGroundingFingerprint") or "")
                        and str(selected_option.get("pendingGroundingFingerprint") or "") != pending_fingerprint
                    )
                    or (
                        str(source_spatial.get("status") or "") == "confirmation_pending"
                        and (
                            str(selected_option.get("boundaryEvidenceFingerprint") or "") != boundary_fingerprint
                            or str(preview.get("boundaryEvidenceFingerprint") or "") != boundary_fingerprint
                        )
                    )
                )
            )
            if base_identity_invalid or confirmation_identity_invalid or change_identity_invalid:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "spatial_boundary_confirmation_identity_mismatch",
                        "message": "活动区域边界身份已变化，请刷新后继续。",
                    },
                )
            spatial_claim = self._claim_fallback_choice_execution(session_id, user_turn_id, selected_choice)
            request_context["fallbackChoiceExecutionClaim"] = spatial_claim
            if spatial_claim["status"] == "succeeded":
                return self._replay_clarification_batch_execution(
                    user_turn,
                    session,
                    selected_choice,
                    spatial_claim,
                )
            request_context["requestIntentContract"] = copy.deepcopy(source_contract)
            spatial = request_context["requestIntentContract"]["spatialPreference"]
            if selected_action == "confirm_spatial_boundary":
                resolution = pending.get("resolution")
                if not SpatialPreferenceService.is_executable_resolution(resolution):
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "spatial_boundary_resolution_invalid",
                            "message": "活动区域边界证据不完整，请修改区域表达。",
                        },
                    )
                spatial["status"] = "resolved"
                spatial["resolution"] = copy.deepcopy(resolution)
                spatial.pop("pendingGrounding", None)
                for dimension in request_context["requestIntentContract"].get("clarificationDimensions") or []:
                    if isinstance(dimension, dict) and str(dimension.get("dimensionId") or "") == "spatial_focus":
                        dimension["status"] = "resolved"
                unresolved = [
                    str(item.get("dimensionId") or "")
                    for item in request_context["requestIntentContract"].get("clarificationDimensions") or []
                    if isinstance(item, dict) and str(item.get("status") or "") != "resolved"
                ]
                request_context["requestIntentContract"]["clarificationRequired"] = bool(unresolved)
                request_context["requestIntentContract"]["clarificationReason"] = unresolved[0] if unresolved else ""
            else:
                spatial["status"] = "unresolved"
                spatial.pop("resolution", None)
                spatial["pendingGrounding"] = {
                    "status": "unresolved",
                    "reason": "boundary_expression_change_requested",
                }
                for dimension in request_context["requestIntentContract"].get("clarificationDimensions") or []:
                    if isinstance(dimension, dict) and str(dimension.get("dimensionId") or "") == "spatial_focus":
                        dimension["status"] = "unresolved"
                request_context["requestIntentContract"]["clarificationRequired"] = True
                request_context["requestIntentContract"]["clarificationReason"] = "spatial_focus"
            spatial["fingerprint"] = SpatialPreferenceService.fingerprint(
                {key: value for key, value in spatial.items() if key != "fingerprint"}
            )
            request_context["spatialBoundaryChoice"] = copy.deepcopy(selected_choice)
            request_context.pop("selectedAgentChoice", None)
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            if selected_action == "change_spatial_boundary":
                spatial_question = next(
                    (
                        item
                        for item in checkpoint.get("questions") or []
                        if isinstance(item, dict) and str(item.get("dimensionId") or "") == "spatial_focus"
                    ),
                    None,
                )
                if not isinstance(spatial_question, dict):
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "spatial_boundary_change_checkpoint_missing",
                            "message": "原活动区域问题已变化，请刷新后继续。",
                        },
                    )
                reusable_options = []
                for option in spatial_question.get("options") or []:
                    if not isinstance(option, dict):
                        continue
                    semantic_value = option.get("semanticValue")
                    spatial_input = (
                        semantic_value.get("spatialResolutionInput")
                        if isinstance(semantic_value, dict)
                        and isinstance(semantic_value.get("spatialResolutionInput"), dict)
                        else {}
                    )
                    if str(spatial_input.get("kind") or "") == "map_selection":
                        # A map selection is signed for exactly one checkpoint.
                        # A replacement checkpoint must obtain a fresh binding.
                        continue
                    reusable_options.append(copy.deepcopy(option))
                request_context.pop("clarificationCheckpoint", None)
                return self._preflight_clarification_response(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    user_turn=user_turn,
                    session=session,
                    content=content,
                    request_context=request_context,
                    controller_clarification={
                        "questions": [
                            {
                                "dimensionId": "spatial_focus",
                                "question": str(spatial_question.get("question") or "").strip(),
                                "whyItMatters": str(spatial_question.get("whyItMatters") or "").strip(),
                                "options": reusable_options,
                                "allowFreeText": bool(spatial_question.get("allowFreeText")),
                            }
                        ]
                    },
                )
            selected_choice = None
            selected_option = {}
            selected_action = ""
        if (
            str(selected_option.get("kind") or "") == "clarification_batch_submit"
            and str(selected_option.get("action") or "") == "submit_clarification_batch"
        ):
            source_assistant_turn_id = str((selected_choice or {}).get("sourceAssistantTurnId") or "")
            source_row = self.db.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ? AND role = 'assistant'",
                (source_assistant_turn_id, session_id),
            ).fetchone()
            source_payload = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
            checkpoint = (
                source_payload.get("clarificationCheckpoint")
                if isinstance(source_payload.get("clarificationCheckpoint"), dict)
                else {}
            )
            if str(selected_option.get("checkpointFingerprint") or "") != str(checkpoint.get("fingerprint") or ""):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "clarification_checkpoint_identity_mismatch",
                        "message": "当前批量澄清已失效或不属于此规划根，请刷新后继续。",
                    },
                )
            selections = (selected_choice or {}).get("batchSelections") or []
            manual_normalization_context = ClarificationCheckpointService.manual_normalization_context(
                checkpoint,
                checkpoint_id=str(selected_option.get("checkpointId") or ""),
                planning_root_id=str(request_context.get("planningSelectionRootTurnId") or ""),
                source_assistant_turn_id=source_assistant_turn_id,
                request_contract=request_context["requestIntentContract"],
                selections=selections,
            )
            has_manual_answers = any(
                str(item.get("manualValue") or "").strip() for item in selections if isinstance(item, dict)
            )
            if has_manual_answers and manual_normalization_context is None:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "clarification_checkpoint_identity_mismatch",
                        "message": "当前批量澄清与手填问题身份不一致，请刷新后继续。",
                    },
                )
            batch_claim = self._claim_fallback_choice_execution(
                session_id,
                user_turn_id,
                selected_choice,
            )
            request_context["fallbackChoiceExecutionClaim"] = batch_claim
            if batch_claim["status"] == "succeeded":
                return self._replay_clarification_batch_execution(
                    user_turn,
                    session,
                    selected_choice,
                    batch_claim,
                )
            normalized_manual_answers = (
                self._normalize_clarification_batch_manual_answers(manual_normalization_context)
                if has_manual_answers and manual_normalization_context is not None
                else {}
            )
            if has_manual_answers and manual_normalization_context is not None:
                request_context["clarificationManualNormalization"] = (
                    self._clarification_batch_manual_normalization_audit(manual_normalization_context)
                )
            resolved_checkpoint = ClarificationCheckpointService.resolve_batch(
                checkpoint,
                checkpoint_id=str(selected_option.get("checkpointId") or ""),
                planning_root_id=str(request_context.get("planningSelectionRootTurnId") or ""),
                source_assistant_turn_id=source_assistant_turn_id,
                request_contract=request_context["requestIntentContract"],
                selections=selections,
                source_user_turn_id=user_turn_id,
                normalized_manual_answers=normalized_manual_answers,
            )
            if resolved_checkpoint is None:
                raise HTTPException(
                    status_code=422 if has_manual_answers else 409,
                    detail={
                        "code": (
                            "clarification_batch_manual_normalization_invalid"
                            if has_manual_answers
                            else "clarification_checkpoint_identity_mismatch"
                        ),
                        "message": (
                            "手工补充内容未能转换为该问题允许的规划字段；本批选择未提交。"
                            if has_manual_answers
                            else "当前批量澄清已失效或不属于此规划根，请刷新后继续。"
                        ),
                    },
                )
            request_context["clarificationAnswers"] = copy.deepcopy(resolved_checkpoint["resolvedAnswers"])
            self._apply_resolved_clarification_checkpoint(request_context, resolved_checkpoint)
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            spatial_response = self._spatial_grounding_response_if_needed(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                content=content,
                request_context=request_context,
            )
            if spatial_response is not None:
                return spatial_response
        elif (
            str(selected_option.get("kind") or "")
            in {
                "clarification_checkpoint",
                "custom_input",
            }
            and str(selected_option.get("action") or "") == "continue_clarification"
        ):
            source_assistant_turn_id = str((selected_choice or {}).get("sourceAssistantTurnId") or "")
            source_row = self.db.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ? AND role = 'assistant'",
                (source_assistant_turn_id, session_id),
            ).fetchone()
            source_payload = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
            checkpoint = (
                source_payload.get("clarificationCheckpoint")
                if isinstance(source_payload.get("clarificationCheckpoint"), dict)
                else {}
            )
            if str(selected_option.get("kind") or "") == "custom_input":
                pending_checkpoint = ClarificationCheckpointService.prepare_free_text(
                    checkpoint,
                    checkpoint_id=str(selected_option.get("checkpointId") or ""),
                    planning_root_id=str(request_context.get("planningSelectionRootTurnId") or ""),
                    source_assistant_turn_id=source_assistant_turn_id,
                    request_contract=request_context["requestIntentContract"],
                    dimension_id=str(selected_option.get("dimensionId") or ""),
                    free_text=str((selected_choice or {}).get("manualValue") or content),
                    source_user_turn_id=user_turn_id,
                )
                if pending_checkpoint is None:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "clarification_checkpoint_identity_mismatch",
                            "message": "当前澄清问题已失效或不属于此规划根，请刷新后继续。",
                        },
                    )
                request_context["clarificationCheckpoint"] = pending_checkpoint
                request_context["clarificationFreeTextCandidate"] = copy.deepcopy(
                    pending_checkpoint["pendingFreeTextAnswer"]
                )
            else:
                semantic_value = selected_option.get("semanticValue")
                resolved_checkpoint = ClarificationCheckpointService.resolve(
                    checkpoint,
                    checkpoint_id=str(selected_option.get("checkpointId") or ""),
                    planning_root_id=str(request_context.get("planningSelectionRootTurnId") or ""),
                    source_assistant_turn_id=source_assistant_turn_id,
                    request_contract=request_context["requestIntentContract"],
                    dimension_id=str(selected_option.get("dimensionId") or ""),
                    semantic_value=semantic_value,
                    source_user_turn_id=user_turn_id,
                    answer_source="structured_option",
                )
                if resolved_checkpoint is None:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "clarification_checkpoint_identity_mismatch",
                            "message": "当前澄清问题已失效或不属于此规划根，请刷新后继续。",
                        },
                    )
                request_context["clarificationAnswer"] = copy.deepcopy(resolved_checkpoint["resolvedAnswers"][-1])
                self._apply_resolved_clarification_checkpoint(request_context, resolved_checkpoint)
            self._persist_agent_request_context(
                session_id,
                user_turn_id,
                request_context,
            )
            checkpoint_after_answer = request_context.get("clarificationCheckpoint")
            if (
                isinstance(checkpoint_after_answer, dict)
                and checkpoint_after_answer.get("status") == "awaiting_answer"
                and isinstance(checkpoint_after_answer.get("question"), dict)
            ):
                # The Controller already authored this batch.  Continue with
                # its next validated question without another Provider call;
                # the server only binds opaque identity and answer semantics.
                next_questions = [
                    copy.deepcopy(checkpoint_after_answer["question"]),
                    *[
                        copy.deepcopy(item)
                        for item in checkpoint_after_answer.get("pendingQuestions") or []
                        if isinstance(item, dict)
                    ],
                ]
                controller_batch = {
                    "type": "ask_user",
                    "questions": next_questions,
                    "checkpointId": checkpoint_after_answer.get("checkpointId"),
                    "planningRootId": checkpoint_after_answer.get("planningRootId"),
                    "requestFingerprint": checkpoint_after_answer.get("requestFingerprint"),
                    "checkpointFingerprint": checkpoint_after_answer.get("fingerprint"),
                }
                return self._preflight_clarification_response(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    user_turn=user_turn,
                    session=session,
                    content=content,
                    request_context=request_context,
                    controller_clarification=controller_batch,
                )
        density_choice = self.portfolio_density_continuation.is_density_option(selected_option)
        density_action = (
            self.portfolio_density_continuation.normalized_action(selected_option) if density_choice else ""
        )
        if density_choice and request_context.get("serverExecutionProfile") == "simple_open_v1":
            # Density options are capabilities issued by the strict Portfolio
            # pipeline.  When the server switches to Simple Open, fail closed
            # before loading or applying any persisted Portfolio checkpoint.
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "agent_choice_execution_profile_mismatch",
                    "message": "该方案补槽操作属于另一规划模式，请基于当前行程重新提出修改。",
                },
            )
        continuation_eligibility_diagnostic: dict[str, Any] = {}
        partial_plan_expansion = bool(
            selected_action == "retry_model_planning"
            and not density_choice
            and self._is_current_partial_plan_expansion_option(
                session_id=session_id,
                option=selected_option,
                source_assistant_turn_id=str((selected_choice or {}).get("sourceAssistantTurnId") or ""),
                eligibility_diagnostic=continuation_eligibility_diagnostic,
            )
        )
        recognized_portfolio_expansion = str(selected_option.get("kind") or "") in {
            "portfolio_partial_more_plans",
            "portfolio_more_plans",
        }
        if (
            selected_action == "retry_model_planning"
            and not density_choice
            and recognized_portfolio_expansion
            and not partial_plan_expansion
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_expansion_identity_mismatch",
                    "message": self._portfolio_continuation_failure_message(
                        str(
                            continuation_eligibility_diagnostic.get("reasonCode")
                            or "portfolio_continuation_identity_mismatch"
                        )
                    ),
                    "eligibilityReasonCode": str(
                        continuation_eligibility_diagnostic.get("reasonCode")
                        or "portfolio_continuation_identity_mismatch"
                    ),
                    "details": {
                        "eligibilityReasonCode": str(
                            continuation_eligibility_diagnostic.get("reasonCode")
                            or "portfolio_continuation_identity_mismatch"
                        ),
                        "authoritativeFocusBriefId": str(continuation_eligibility_diagnostic.get("focusBriefId") or ""),
                        "selectedFocusBriefId": str(selected_option.get("focusBriefId") or ""),
                        "selectedExpansionFocusMode": str(selected_option.get("expansionFocusMode") or ""),
                    },
                },
            )
        if (
            selected_action == "retry_model_planning"
            and not density_choice
            and self._active_partial_pending_snapshot(session_id) is not None
            and not partial_plan_expansion
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_partial_exact_slot_required",
                    "message": "部分时间轴只能续接一个明确的待补槽位，请使用该槽位的候选、刷新或附近检索选项。",
                },
            )
        if partial_plan_expansion:
            expansion_claim = self._partial_plan_expansion_claim_state(
                session_id=session_id,
                plan_id=str(session["active_plan_id"] or ""),
                root_portfolio_id=str(selected_option.get("rootPortfolioId") or ""),
                planning_root_id=str(selected_option.get("planningSelectionRootTurnId") or ""),
                request_fingerprint=str(selected_option.get("requestContractFingerprint") or ""),
                active_version_id=str(session["active_version_id"] or ""),
            )
            active_partial_snapshot = self._active_partial_snapshot(session_id)
            active_partial_selection = (
                PortfolioPendingSlotService.selection_context(active_partial_snapshot)
                if isinstance(active_partial_snapshot, dict)
                else {}
            )
            request_context["_partialPlanExpansionAuthorized"] = True
            request_context["explicitRuleSafeDraft"] = False
            active_partial_focus_brief_id = str(active_partial_selection.get("focusBriefId") or "")
            request_context["activePartialFocusBriefId"] = active_partial_focus_brief_id
            expansion_focus_mode = str(selected_option.get("expansionFocusMode") or "")
            if expansion_focus_mode not in {"exact", "discover_next"}:
                expansion_focus_mode = (
                    "exact"
                    if str(selected_option.get("kind") or "") == "portfolio_more_plans"
                    or str(selected_option.get("focusBriefId") or "") != active_partial_focus_brief_id
                    else "discover_next"
                )
            expansion_claim.update(
                {
                    "focusBriefId": str(selected_option.get("focusBriefId") or ""),
                    "activePartialFocusBriefId": active_partial_focus_brief_id,
                    "expansionFocusMode": expansion_focus_mode,
                }
            )
            request_context["partialPlanExpansionFocusMode"] = expansion_focus_mode
            request_context["portfolioGroundingFocusBriefId"] = str(selected_option.get("focusBriefId") or "")
            request_context["partialPlanExpansionClaim"] = expansion_claim
            selected_choice["continuationCheckpoint"] = expansion_claim
            if not isinstance(
                request_context.get("fallbackChoiceExecutionClaim"),
                dict,
            ):
                request_context["fallbackChoiceExecutionClaim"] = self._claim_fallback_choice_execution(
                    session_id,
                    user_turn_id,
                    selected_choice,
                    continuation_checkpoint=expansion_claim,
                )
            existing_execution_claim = (
                request_context.get("fallbackChoiceExecutionClaim")
                if isinstance(request_context.get("fallbackChoiceExecutionClaim"), dict)
                else {}
            )
            if str(existing_execution_claim.get("id") or ""):
                self.db.execute(
                    """UPDATE agent_choice_executions
                    SET continuation_json = json_patch(COALESCE(continuation_json, '{}'), ?), updated_at = ?
                    WHERE id = ? AND session_id = ? AND status = 'executing'""",
                    (
                        json.dumps(expansion_claim, ensure_ascii=False, default=str),
                        datetime.now(timezone.utc).isoformat(),
                        existing_execution_claim["id"],
                        session_id,
                    ),
                )
                self.db.commit()
            request_context.update(
                {
                    "planningSelectionRootTurnId": str(selected_option.get("planningSelectionRootTurnId") or ""),
                    "rootPortfolioId": str(selected_option.get("rootPortfolioId") or ""),
                    "focusBriefId": str(selected_option.get("focusBriefId") or ""),
                    "requestContractFingerprint": str(selected_option.get("requestContractFingerprint") or ""),
                    "expectedBaseVersionId": str(selected_option.get("expectedBaseVersionId") or ""),
                    "continuationContext": {
                        "kind": "retry_model_planning",
                        "planningSelectionRootTurnId": str(selected_option.get("planningSelectionRootTurnId") or ""),
                        "rootPortfolioId": str(selected_option.get("rootPortfolioId") or ""),
                        "focusBriefId": str(selected_option.get("focusBriefId") or ""),
                    },
                }
            )
            request_context["retryExecutionPlan"] = {
                "kind": "expand_partial_portfolio",
                "reasonCode": "persisted_partial_same_root_expansion",
                "controllerAllowed": False,
                "allowedActions": ["draft_itinerary", "ask_user"],
                "writeBudget": 0,
                "choiceOptions": [],
            }
            if expansion_focus_mode == "discover_next":
                # A dynamic frontier continuation must generate a new brief.  A
                # nested resume from the preceding exact direction would win the
                # staged-pipeline branch and incorrectly ground that old brief.
                request_context.pop("resumePlanningAttempt", None)
                expansion_resume = None
            else:
                expansion_resume = self._partial_plan_expansion_resume_plan(
                    session_id=session_id,
                    source_assistant_turn_id=str(selected_choice.get("sourceAssistantTurnId") or ""),
                    root_portfolio_id=str(expansion_claim.get("rootPortfolioId") or ""),
                    planning_root_id=str(expansion_claim.get("planningSelectionRootTurnId") or ""),
                    request_fingerprint=str(expansion_claim.get("requestContractFingerprint") or ""),
                    focus_brief_id=str(expansion_claim.get("focusBriefId") or ""),
                )
            if expansion_resume is not None:
                request_context["resumePlanningAttempt"] = {
                    "enabled": True,
                    "reuseInitialPlan": True,
                    **expansion_resume,
                }
            planning_directive = request_context.get("planningDirective")
            if not isinstance(planning_directive, dict) or not planning_directive.get("dayStrategies"):
                restored_directive = (
                    expansion_resume.get("planningDirective")
                    if isinstance(expansion_resume, dict)
                    else self._partial_plan_expansion_planning_directive(
                        session_id=session_id,
                        source_assistant_turn_id=str(selected_choice.get("sourceAssistantTurnId") or ""),
                    )
                )
                if isinstance(restored_directive, dict) and restored_directive.get("dayStrategies"):
                    request_context["planningDirective"] = copy.deepcopy(restored_directive)
            request_context["retryIntent"] = {
                "intentClass": "not_retry",
                "reasonCode": "persisted_partial_same_root_expansion",
            }
        if density_choice:
            source_turn_id = str(selected_choice.get("sourceAssistantTurnId") or "")
            succeeded_execution_row = self.db.execute(
                """
                SELECT * FROM agent_choice_executions
                WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?
                  AND action = ? AND status = 'succeeded'
                """,
                (
                    session_id,
                    source_turn_id,
                    str(selected_choice.get("persistedChoiceId") or selected_choice.get("choiceId") or ""),
                    selected_action,
                ),
            ).fetchone()
            if succeeded_execution_row is not None:
                succeeded_execution = dict(succeeded_execution_row)
                self._attach_choice_execution_identity(selected_choice, succeeded_execution)
                return self._replay_density_choice_execution(
                    user_turn,
                    session,
                    selected_choice,
                    succeeded_execution,
                )
            try:
                checkpoint = self.portfolio_density_continuation.load_checkpoint(
                    session_id=session_id,
                    source_assistant_turn_id=source_turn_id,
                    option=selected_option,
                )
            except PortfolioDensityContinuationError as error:
                raise HTTPException(
                    status_code=409,
                    detail={"code": error.code, "message": error.message},
                ) from error
            self.portfolio_density_continuation.apply_to_request_context(request_context, checkpoint)
            selected_choice["normalizedAction"] = density_action
            selected_choice["continuationCheckpoint"] = checkpoint.payload
            request_context["planningSelectionRootTurnId"] = str(
                request_context.get("planningSelectionRootTurnId") or source_turn_id or ""
            )
            # Persist the validated opaque choice context before a density
            # action can fail on the current partial-timeline guard. The
            # rejection remains zero itinerary writes, while the originating
            # scope stays auditable and cannot be reconstructed from a label.
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            if density_action == DENSITY_MAP_ACTION:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "portfolio_density_map_client_action",
                        "message": "请使用地图入口选择该缺失槽位的地点。",
                    },
                )
            self._dispatch_selected_agent_choice(
                session_id,
                user_turn_id,
                content,
                user_turn,
                session,
                request_context,
                selected_choice,
                event_sink=event_sink,
            )
            planning_directive = request_context.get("planningDirective")
            if not isinstance(planning_directive, dict) or planning_directive.get("type") != "draft_itinerary":
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "agent_choice_source_context_missing",
                        "message": "该地点选择缺少原规划上下文，请刷新缺失地点候选后重试。",
                    },
                )
            claim = self._claim_fallback_choice_execution(
                session_id,
                user_turn_id,
                selected_choice,
                continuation_checkpoint=checkpoint.payload,
            )
            request_context["fallbackChoiceExecutionClaim"] = claim
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
            if claim["status"] == "succeeded":
                return self._replay_density_choice_execution(user_turn, session, selected_choice, claim)
            current_session = self._session(session_id)
            if density_action == DENSITY_MANUAL_SEARCH_ACTION:
                return self._search_exact_pending_slot_candidates(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    user_turn=user_turn,
                    request_context=request_context,
                    checkpoint=checkpoint.payload,
                )
            if density_action == DENSITY_CANDIDATE_ACTION:
                if not current_session["active_version_id"]:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "portfolio_partial_timeline_missing",
                            "message": "当前没有可安全补槽的部分时间轴，请先恢复上次规划检查点。",
                        },
                    )
                intent, selected_poi = self._pending_slot_timeline_mutation(
                    session_id,
                    request_context,
                    selection_source=str(selected_option.get("selectionSource") or "user_chat_choice"),
                )
                return self._execute_local_timeline_mutation(
                    session_id,
                    user_turn_id,
                    user_turn,
                    session,
                    str(request_context.get("effectiveUserMessage") or content),
                    intent,
                    event_sink=event_sink,
                    request_context=request_context,
                    selected_poi=selected_poi,
                )
            return self._generate_with_initial_staged_pipeline(
                session_id,
                user_turn_id,
                str(request_context.get("effectiveUserMessage") or content),
                request_context,
                event_sink=event_sink,
            )
        if isinstance(selected_choice, dict) and str(selected_option.get("kind") or "") == "material_tradeoff":
            request_context["planningSelectionRootTurnId"] = str(
                request_context.get("planningSelectionRootTurnId") or selected_choice.get("sourceAssistantTurnId") or ""
            )
            self._dispatch_selected_agent_choice(
                session_id,
                user_turn_id,
                content,
                user_turn,
                session,
                request_context,
                selected_choice,
                event_sink=event_sink,
            )
            self._persist_agent_request_context(session_id, user_turn_id, request_context)
        selected_label = str(selected_option.get("label") or selected_option.get("value") or "").strip()
        if selected_label and content == "选择 Agent 选项":
            content = selected_label
            self.db.execute(
                "UPDATE conversation_turns SET content = ?, updated_at = ? WHERE id = ? AND session_id = ?",
                (content, datetime.now(timezone.utc).isoformat(), user_turn_id, session_id),
            )
            self.db.commit()
            user_turn = self._turn_response(user_turn_id)
            request_context["latestUserMessage"] = content
        # A clarification is a controller-owned turn.  Do not short-circuit it
        # here with a server-authored question: that used to make a fixed night
        # view prompt look like an Agent decision and prevented the question
        # from reflecting the persisted contract or the latest candidate gap.
        direct_typed_choice = bool(
            isinstance(selected_choice, dict)
            and (
                selected_action
                in {
                    "execute_timeline_mutation_choice",
                    "execute_timeline_mutation_manual",
                    "confirm_rule_safe_draft",
                    "select_plan_proposal",
                    "adopt_active_partial",
                    "attempt_portfolio_theme_completion",
                    "confirm_portfolio_theme_upgrade",
                    "confirm_portfolio_theme_replacement",
                    "reject_portfolio_theme_replacement",
                }
                or selected_option.get("kind") == "poi_candidate"
            )
        )
        # Retry/manual/free-text continuations are model tasks. Only persisted,
        # identity-stable atomic choices may bypass the root Coordinator.
        controller_owned_turn = not direct_typed_choice
        if controller_owned_turn:
            return self._run_coordinated_natural_language_turn(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                content=content,
                payload=payload,
                request_context=request_context,
                event_sink=event_sink,
            )
        self._apply_legacy_provider_adapter_decision(request_context)
        from src.services.agent_ingress_journal import AgentIngressJournal
        request_context = AgentIngressJournal(self.db).merge_context(user_turn_id, request_context)
        self.db.execute(
            "UPDATE conversation_turns SET agent_request_json = ?, updated_at = ? WHERE id = ? AND session_id = ?",
            (
                json.dumps(request_context, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                user_turn_id,
                session_id,
            ),
        )
        if isinstance(selected_choice, dict):
            option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
            if str(option.get("action") or "").startswith("execute_timeline_mutation_"):
                choice_response = self._dispatch_selected_agent_choice(
                    session_id,
                    user_turn_id,
                    content,
                    user_turn,
                    session,
                    request_context,
                    selected_choice,
                    event_sink=event_sink,
                )
                if choice_response is not None:
                    return choice_response
        coordinated_action = self.turn_coordinator.coordinate(request_context)
        model_mutation_intent = self._controller_timeline_mutation_intent(request_context, content)
        if (
            model_mutation_intent is not None
            and coordinated_action.accepted
            and coordinated_action.primary_action == "patch_itinerary"
        ):
            return self._execute_local_timeline_mutation(
                session_id,
                user_turn_id,
                user_turn,
                session,
                content,
                model_mutation_intent,
                event_sink=event_sink,
                request_context=request_context,
            )
        if isinstance(selected_choice, dict):
            option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
            if option.get("kind") == "retry_unresolved_slot":
                request_context["retryCandidateHints"] = True
                request_context["selectedRetrySlotId"] = option.get("slotId") or option.get("segmentId")
            # Opaque structured selections bypass the natural-language command parser.
            timeline_command = None
        else:
            accepted_patch = coordinated_action.accepted and coordinated_action.primary_action == "patch_itinerary"
            decision_state = request_context.get("agentDecisionState")
            decision_payload = (
                request_context.get("agentDecision") if isinstance(request_context.get("agentDecision"), dict) else {}
            )
            model_patch_directive = bool(
                accepted_patch
                and isinstance(decision_state, dict)
                and decision_state.get("source") == "controller"
                and decision_payload.get("schemaVersion") == "agent-decision-v2"
            )
            fallback_parser_allowed = bool(
                isinstance(decision_state, dict)
                and decision_state.get("source")
                in {
                    "planner_fallback",
                    "deterministic_arbitrator",
                    "legacy_provider_adapter",
                }
            )
            # Compatibility parser is now an executor-local compiler aid.  It
            # may enrich an accepted patch decision, but cannot choose the
            # turn's primary action before the model controller.
            if model_patch_directive:
                timeline_command = self.timeline_command_planner.compile(
                    decision_payload.get("actionDirective"),
                    request_context.get("agentObservation"),
                )
            elif fallback_parser_allowed:
                timeline_command = self.timeline_command_planner.parse(
                    content,
                    has_active_timeline=bool(session["active_version_id"]),
                )
            else:
                timeline_command = None
        if not self._resume_attempt_enabled(request_context) and self._should_infer_candidate_hint_retry(
            session, request_context
        ):
            request_context["retryCandidateHints"] = True
        self._apply_request_provider_model(request_context)
        if isinstance(selected_choice, dict):
            choice_response = self._dispatch_selected_agent_choice(
                session_id,
                user_turn_id,
                content,
                user_turn,
                session,
                request_context,
                selected_choice,
                event_sink=event_sink,
            )
            if choice_response is not None:
                return choice_response
        if timeline_command is not None:
            timeline_response = self._try_handle_timeline_command(
                session_id,
                user_turn_id,
                content,
                user_turn,
                session,
                request_context,
                timeline_command,
                event_sink=event_sink,
            )
            if timeline_response is not None:
                return timeline_response
        if coordinated_action.primary_action in {"patch_itinerary", "optimize_route", "verify_external_facts"}:
            direct_action_response = self._execute_accepted_direct_action(
                session_id,
                user_turn_id,
                content,
                user_turn,
                session,
                request_context,
            )
            if direct_action_response is not None:
                return direct_action_response
        terminal_decision = (
            self._accepted_terminal_or_read_decision(request_context)
            if coordinated_action.primary_action in {"ask_user", "read_itinerary", "finish"}
            else None
        )
        if coordinated_action.primary_action == "finish" and terminal_decision is not None:
            return self._execute_finish_action(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                terminal_decision,
            )
        if coordinated_action.primary_action == "read_itinerary" and terminal_decision is not None:
            timeline_query_response = self._try_handle_read_timeline_query(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                terminal_decision,
            )
            if timeline_query_response is not None:
                return timeline_query_response
        write_decision = (
            self._accepted_write_decision(request_context)
            if coordinated_action.primary_action in {"draft_itinerary", "patch_itinerary"}
            else None
        )
        self._emit_execution_event(
            event_sink,
            session_id=session_id,
            turn_id=user_turn_id,
            event_type="agent",
            label="判断规划路径",
            detail="正在判断本轮是否需要澄清、POI 确认、工具调用或时间轴写入。",
        )
        candidate_hint_resume = self._can_resume_candidate_hints(session, request_context)
        controller_clarification = self._accepted_clarification(request_context)
        decision_state = (
            request_context.get("agentDecisionState")
            if isinstance(request_context.get("agentDecisionState"), dict)
            else {}
        )
        if write_decision is not None and write_decision.get("primaryAction") == "draft_itinerary":
            self._apply_controller_route_policy(
                request_context,
                (
                    decision_state.get("actionDirective")
                    if isinstance(decision_state.get("actionDirective"), dict)
                    else None
                ),
            )
        controller_requested_clarification = bool(
            decision_state.get("primaryAction") == "ask_user" or decision_state.get("uncertaintyPolicy") == "ask_user"
        )
        if controller_clarification is None and controller_requested_clarification:
            raw_clarification = decision_state.get("clarification")
            controller_clarification = copy.deepcopy(raw_clarification) if isinstance(raw_clarification, dict) else None
        spatial_clarification_required = self._spatial_clarification_required(request_context)
        contract_clarification_required = bool(
            self._request_contract_requires_clarification(request_context)
            and (not session["active_version_id"] or spatial_clarification_required)
        )
        if not candidate_hint_resume and (
            controller_clarification is not None
            or controller_requested_clarification
            or contract_clarification_required
            or (terminal_decision is None and self._should_preflight_clarify(session, request_context))
        ):
            return self._preflight_clarification_response(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                content=content,
                request_context=request_context,
                controller_clarification=controller_clarification,
            )

        initial_pipeline_authorized = self._initial_staged_pipeline_entry_allowed(request_context)
        should_enter_initial_pipeline = initial_pipeline_authorized and (
            candidate_hint_resume
            or (write_decision is not None and write_decision.get("primaryAction") == "draft_itinerary")
            or self._should_use_initial_staged_pipeline(session, request_context)
        )
        if should_enter_initial_pipeline and (
            (write_decision is not None and write_decision.get("primaryAction") == "draft_itinerary")
            or candidate_hint_resume
            or hasattr(self.provider, "generate")
        ):
            return self._generate_with_initial_staged_pipeline(
                session_id,
                user_turn_id,
                content,
                request_context,
                event_sink=event_sink,
            )

        if hasattr(self.provider, "run_tool_loop") and self._generic_tool_loop_entry_allowed(request_context):
            return self._generate_with_tool_loop(
                session_id, user_turn_id, content, request_context, event_sink=event_sink
            )

        if self._provider_has_autonomy_decision():
            return self._finish_no_safe_action(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                reason=self._no_safe_action_reason(request_context),
            )

        try:
            raw_response = self.provider.generate(request_context)
            structured = self.parse_agent_output(raw_response, request_context)
        except (HTTPException, ValueError, ValidationError) as error:
            assistant_turn = self._record_failed_assistant_turn(
                session_id, self._error_message(error), request_context, None
            )
            failed_reply = self._error_message(error)
            planning_run = PlanningRunService(self.db).create_run(
                "agent_message_failed",
                user_input=content,
                preference_summary=self._preference_summary_from_context(request_context),
                itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"])
                if session["active_version_id"]
                else None,
                itinerary_version_id=session["active_version_id"],
                understood_requirements=request_context.get("understoodRequirements"),
                final_summary=f"Agent 失败：{failed_reply}。行程未被覆盖。",
            )
            verifier_report = self._safe_verify_active_version_unchanged(session, "agent_message_failed")
            self._auto_update_preference_memory(session_id, content, failed_reply)
            self.db.commit()
            return self._message_response(
                user_turn, assistant_turn, session, None, [self._error_message(error)], planning_run, verifier_report
            )

        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            structured.reply,
            "active",
            agent_request_json=request_context,
            agent_response_json=structured.model_dump(by_alias=True),
        )

        if structured.mode == "clarification":
            planning_run = PlanningRunService(self.db).create_run(
                "agent_clarification",
                user_input=content,
                preference_summary=self._preference_summary_from_context(request_context),
                itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"])
                if session["active_version_id"]
                else None,
                itinerary_version_id=session["active_version_id"],
                understood_requirements=request_context.get("understoodRequirements"),
                final_summary=structured.reply,
            )
            verifier_report = self._safe_verify_active_version_unchanged(session, "agent_clarification")
            self._auto_update_preference_memory(session_id, content, structured.reply)
            self.db.commit()
            assistant_turn = self._turn_response(assistant_turn_id)
            return self._message_response(
                user_turn, assistant_turn, session, None, structured.warnings, planning_run, verifier_report
            )

        pending_response = self._resolve_requested_pois(session, user_turn_id, structured)
        if pending_response is not None:
            planning_run = PlanningRunService(self.db).create_run(
                "agent_poi_clarification",
                user_input=content,
                preference_summary=self._preference_summary_from_context(request_context),
                itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"])
                if session["active_version_id"]
                else None,
                itinerary_version_id=session["active_version_id"],
                understood_requirements=request_context.get("understoodRequirements"),
                final_summary="POI 存在多候选或低置信，需要用户确认后再写入行程。",
            )
            verifier_report = self._safe_verify_active_version_unchanged(session, "agent_poi_clarification")
            self._auto_update_preference_memory(session_id, content, structured.reply)
            self.db.commit()
            assistant_turn = self._turn_response(assistant_turn_id)
            return self._message_response(
                user_turn, assistant_turn, session, None, structured.warnings, planning_run, verifier_report
            )

        try:
            operations = self._operations_for_output(session, structured)
            result = ItineraryPatchService(self.db).apply_patch(
                session["active_plan_id"],
                operations,
                source_type="agent",
                base_version_id=session["active_version_id"],
                source_turn_id=assistant_turn_id,
                preference_summary=self._preference_summary_from_context(request_context),
                planning_context=request_context,
            )
            verifier_report = self._verify_agent_result_or_restore(session, result)
            self.db.execute(
                """
                UPDATE conversation_turns
                SET itinerary_version_id = ?, updated_at = ?
                WHERE id IN (?, ?)
                """,
                (result.version.id, datetime.now(timezone.utc).isoformat(), user_turn_id, assistant_turn_id),
            )
            planning_run = PlanningRunService(self.db).create_run(
                "agent_message",
                user_input=content,
                preference_summary=self._preference_summary_from_context(request_context),
                itinerary=result.itinerary,
                itinerary_version_id=result.version.id,
                understood_requirements=request_context.get("understoodRequirements"),
                final_summary=self._final_summary_with_requirement_caveat(structured.reply, request_context),
            )
            ItineraryPatchService(self.db).attach_planning_run_for_source_turn(assistant_turn_id, planning_run.id)
            planning_events = self._attach_planning_events(assistant_turn_id, planning_run, verifier_report)
            self._auto_update_preference_memory(session_id, content, structured.reply)
            self.db.commit()
            return AgentMessageResponse(
                userTurn=self._turn_response(user_turn_id),
                assistantTurn=self._turn_response(assistant_turn_id),
                itinerary=result.itinerary,
                version=result.version,
                pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
                warnings=self._agent_visible_warnings(request_context, structured.warnings),
                planningRun=planning_run,
                planningSteps=planning_events,
                toolEvents=planning_events,
            )
        except HTTPException as error:
            self._mark_turn_failed(assistant_turn_id, error)
            verifier_report = self._verifier_report_from_error(error) or self._safe_verify_active_version_unchanged(
                session, "agent_patch_failed"
            )
            planning_run = PlanningRunService(self.db).create_run(
                "agent_patch_failed",
                user_input=content,
                preference_summary=self._preference_summary_from_context(request_context),
                itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"])
                if session["active_version_id"]
                else None,
                itinerary_version_id=session["active_version_id"],
                understood_requirements=request_context.get("understoodRequirements"),
                final_summary=f"Agent 修改未通过校验：{self._error_message(error)}。",
            )
            ItineraryPatchService(self.db).attach_planning_run_for_source_turn(assistant_turn_id, planning_run.id)
            self._auto_update_preference_memory(session_id, content, structured.reply)
            self.db.commit()
            return self._message_response(
                self._turn_response(user_turn_id),
                self._turn_response(assistant_turn_id),
                self._session(session_id),
                None,
                [self._error_message(error), *structured.warnings],
                planning_run,
                verifier_report,
            )

    def resume_failed_turn(
        self,
        session_id: str,
        turn_id: str,
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> AgentMessageResponse:
        if not self._acquire_session_run_lease(session_id):
            raise HTTPException(
                status_code=409,
                detail={"code": "run_in_progress", "message": "该会话已有进行中的 Agent 修改请求。"},
            )
        try:
            self.assert_session_run_active(session_id)
            response = self._resume_failed_turn_locked(
                session_id,
                turn_id,
                event_sink=event_sink,
            )
            self.assert_session_run_active(session_id)
            return response
        finally:
            self._release_session_run_lease(session_id)

    def _resume_failed_turn_locked(
        self,
        session_id: str,
        turn_id: str,
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> AgentMessageResponse:
        failed_turn = self.db.execute(
            "SELECT * FROM conversation_turns WHERE id = ? AND session_id = ?",
            (turn_id, session_id),
        ).fetchone()
        if failed_turn is None:
            raise HTTPException(status_code=404, detail="Failed assistant turn not found")
        response_json = self._json_dict(failed_turn["agent_response_json"])
        if (
            failed_turn["role"] == "assistant"
            and failed_turn["status"] == "active"
            and str(response_json.get("mode") or "") == "staged_initial_pipeline_waiting"
        ):
            return self._resume_active_planning_attempt(session_id, failed_turn, event_sink=event_sink)
        if failed_turn["role"] != "assistant" or failed_turn["status"] != "failed":
            raise HTTPException(status_code=400, detail="Only failed assistant turns can be resumed")
        error_json = self._json_dict(failed_turn["error_json"])
        mode = str(response_json.get("mode") or "")
        message = " ".join([mode, str(error_json.get("message") or ""), str(response_json.get("failureReason") or "")])
        allowed = (
            "tool_loop_failed",
            "tool_loop_no_itinerary_write",
            "staged_initial_pipeline_failed",
            "provider_rate_limited",
            "waiting_for_poi_grounding",
            "semantic_candidate_hint_missing",
        )
        if not any(marker in message for marker in allowed):
            raise HTTPException(status_code=400, detail="This failed turn is not safe to resume automatically")
        session = self._session(session_id)
        failed_base_version = failed_turn["itinerary_version_id"] or self._base_version_from_turn_context(failed_turn)
        if failed_base_version != session["active_version_id"]:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "stale_resume_version",
                    "message": "当前 activeVersionId 与失败时版本不一致，请先确认版本后再续跑。",
                    "failedBaseVersionId": failed_base_version,
                    "activeVersionId": session["active_version_id"],
                },
            )
        user_turn = self._previous_user_turn(session_id, int(failed_turn["turn_index"]))
        if user_turn is None:
            raise HTTPException(status_code=400, detail="Cannot resume because the original user turn was not found")
        self._assert_failed_portfolio_retryable(
            session_id=session_id,
            source_user_turn_id=str(user_turn["id"]),
            failed_assistant_turn_id=turn_id,
            expected_base_version_id=failed_base_version,
        )
        self._clear_tool_loop_poi_candidate_side_effects_for_turn(turn_id)
        original_context = self._json_dict(failed_turn["agent_request_json"])
        payload_context = {
            key: value
            for key, value in original_context.items()
            if key
            in {
                "selectedDayNumber",
                "selectedSegmentId",
                "candidatePoiIds",
                "preferenceCardId",
                "candidateMapPois",
                "preferenceCard",
                "timelineContext",
                "retryCandidateHints",
                "manualCandidateHints",
            }
        }
        payload_context["resumeFeedback"] = {
            "turnId": turn_id,
            "failureMode": mode,
            "failureReason": error_json.get("message") or response_json.get("failureReason"),
            "failedBaseVersionId": failed_base_version,
        }
        self.assert_session_run_active(session_id)
        retry_user_turn_id = self._insert_turn(
            session_id,
            "user",
            str(user_turn["content"]),
            "active",
            parent_turn_id=turn_id,
        )
        payload_context["resumeFeedback"].update(
            {
                "sourceUserTurnId": str(user_turn["id"]),
                "retryUserTurnId": retry_user_turn_id,
            }
        )
        self.db.commit()
        payload = AgentMessageRequest(content=user_turn["content"], context=payload_context)
        return self._finalize_generated_response(
            session_id,
            self._generate_for_user_turn(
                session_id,
                retry_user_turn_id,
                user_turn["content"],
                payload,
                event_sink=event_sink,
            ),
        )

    def _resume_active_planning_attempt(
        self,
        session_id: str,
        assistant_turn: sqlite3.Row,
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> AgentMessageResponse:
        session = self._session(session_id)
        if session["active_version_id"]:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "stale_resume_version",
                    "message": "当前会话已经有 activeVersionId，请基于现有时间轴继续编辑。",
                    "activeVersionId": session["active_version_id"],
                },
            )
        retry_content = "重新构建"
        user_turn_id = self._insert_turn(session_id, "user", retry_content, "active")
        payload = AgentMessageRequest(
            content=retry_content,
            context={
                "resumePlanningAttemptId": assistant_turn["id"],
                "retryAfterProviderRateLimit": True,
            },
        )
        return self._finalize_generated_response(
            session_id,
            self._generate_for_user_turn(session_id, user_turn_id, retry_content, payload, event_sink=event_sink),
        )

    def _previous_user_turn(self, session_id: str, before_turn_index: int) -> Optional[sqlite3.Row]:
        return self.db.execute(
            """
            SELECT * FROM conversation_turns
            WHERE session_id = ? AND role = 'user' AND turn_index < ?
            ORDER BY turn_index DESC
            LIMIT 1
            """,
            (session_id, before_turn_index),
        ).fetchone()

    def _assert_failed_portfolio_retryable(
        self,
        *,
        session_id: str,
        source_user_turn_id: str,
        failed_assistant_turn_id: str,
        expected_base_version_id: Optional[str],
    ) -> None:
        """Allow retry only when the failed root has no opaque user action.

        A Portfolio with proposals or a selection is an opaque user-facing
        capability and must never be bypassed by a generic retry.  The failed
        Portfolio itself remains immutable audit evidence; the retry receives
        a new source user turn instead of deleting or replacing this row.
        """

        row = self.db.execute(
            """SELECT p.*, source_assistant.status AS source_assistant_status,
                source_assistant.agent_response_json AS source_assistant_response_json,
                (SELECT COUNT(*) FROM agent_plan_proposals AS proposal
                 WHERE proposal.portfolio_id = p.id) AS proposal_count,
                (SELECT COUNT(*) FROM agent_choice_executions AS execution
                 WHERE execution.session_id = p.session_id
                   AND (
                     execution.source_turn_id = p.source_assistant_turn_id
                     OR execution.source_user_turn_id = p.source_user_turn_id
                   )) AS choice_execution_count
            FROM agent_plan_portfolios AS p
            LEFT JOIN conversation_turns AS source_assistant
              ON source_assistant.id = p.source_assistant_turn_id
             AND source_assistant.session_id = p.session_id
            WHERE p.session_id = ? AND p.source_user_turn_id = ?""",
            (session_id, source_user_turn_id),
        ).fetchone()
        if row is None:
            return
        source_matches = (
            str(row["source_assistant_turn_id"] or "") == failed_assistant_turn_id
            or str(row["source_assistant_status"] or "") == "superseded"
        )
        source_response = self._json_dict(row["source_assistant_response_json"])
        has_choice_options = any(isinstance(item, dict) for item in source_response.get("choiceOptions") or [])
        stored_base_version_id = str(row["expected_base_version_id"] or "") or None
        safe_to_retry = bool(
            str(row["status"] or "") == "failed"
            and row["selected_proposal_id"] is None
            and int(row["proposal_count"] or 0) == 0
            and int(row["choice_execution_count"] or 0) == 0
            and not has_choice_options
            and source_matches
            and stored_base_version_id == expected_base_version_id
        )
        if not safe_to_retry:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_resume_requires_explicit_choice",
                    "message": "该失败轮次已有不可覆盖的方案状态，请使用最新结构化选择或重新发起规划。",
                },
            )

    def _base_version_from_turn_context(self, turn: sqlite3.Row) -> Optional[str]:
        context = self._json_dict(turn["agent_request_json"])
        for key in ("activeVersionId", "baseVersionId"):
            if context.get(key):
                return str(context[key])
        snapshot = context.get("currentItinerarySnapshot")
        if isinstance(snapshot, dict):
            value = snapshot.get("activeVersionId") or snapshot.get("versionId")
            if value:
                return str(value)
        return None

    def _json_dict(self, value: Any) -> dict[str, Any]:
        if not value:
            return {}
        if isinstance(value, dict):
            return value
        try:
            parsed = json.loads(value)
        except (TypeError, json.JSONDecodeError):
            return {}
        return parsed if isinstance(parsed, dict) else {}

    def _generate_with_tool_loop(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        request_context: dict,
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> AgentMessageResponse:
        session_before = self._session(session_id)
        preference_memory_before = PreferenceService(self.db).get_memory(session_id=session_id, commit=False)
        if self._request_requires_proactive_timeline_write_contract(
            request_context, session_before["active_version_id"]
        ):
            request_context = self._timeline_write_required_context(request_context)
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            "Agent 正在调用工具规划行程。",
            "active",
            agent_request_json=request_context,
            agent_response_json={"mode": "tool_calling", "reply": "", "planningSteps": [], "toolEvents": []},
        )
        self._emit_execution_event(
            event_sink,
            session_id=session_id,
            turn_id=assistant_turn_id,
            event_type="agent",
            label="启动 Agent 工具循环",
            detail="已创建 assistant turn，正在准备 DeepSeek tool calling 与旅行工具注册表。",
        )
        run_context = AgentRunContext(
            session=session_before,
            request_context=request_context,
            source_turn_id=assistant_turn_id,
            active_version_id=session_before["active_version_id"],
            preference_memory=preference_memory_before,
            runtime_limits=self._runtime_limits_for_request(request_context),
        )
        provider_context = run_context.provider_context()
        registry = TravelToolRegistry(
            self.db,
            session_before,
            provider_context,
            source_turn_id=assistant_turn_id,
            event_sink=lambda event: self._emit_tool_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=assistant_turn_id,
                event=event,
            ),
        )
        self._emit_execution_event(
            event_sink,
            session_id=session_id,
            turn_id=assistant_turn_id,
            event_type="agent",
            label="执行 Agent 工具循环",
            detail="Agent 正在选择并调用 read_itinerary、patch_itinerary、联网查询或偏好记忆等工具。",
        )
        try:
            result = self.provider.run_tool_loop(provider_context, registry)
        except (AgentToolLoopError, HTTPException, ValueError, ValidationError, RuntimeError) as error:
            failure_reason = self._error_message(error)
            tool_events = getattr(error, "tool_events", registry.events)
            diagnostics = self._tool_loop_error_diagnostics(error, tool_events)
            self._emit_tool_loop_diagnostic_events(
                event_sink,
                session_id=session_id,
                assistant_turn_id=assistant_turn_id,
                tool_events=tool_events,
            )
            logger.error(
                "agent_tool_loop_failed",
                extra={
                    "session_id": session_id,
                    "assistant_turn_id": assistant_turn_id,
                    "failure_reason": failure_reason,
                    "diagnostics": diagnostics,
                },
            )
            planning_events = self._safe_planning_events_from_tool_events(
                tool_events,
                session_id=session_id,
                assistant_turn_id=assistant_turn_id,
                itinerary_version_id=session_before["active_version_id"],
                failed=True,
            )
            accepted_version_id = self._latest_accepted_result_version_for_turn(assistant_turn_id)
            if accepted_version_id:
                verifier_report = self._verify_tool_loop_result_or_restore(
                    session_before, assistant_turn_id, accepted_version_id
                )
                if verifier_report.passed:
                    session_after_write = self._session(session_id)
                    write_preserved_marker = self._tool_loop_retry_event(
                        assistant_turn_id,
                        "tool_loop_exceeded_after_write",
                        "工具循环超限但时间轴已写入",
                        "completed",
                        "Agent 已通过 patch_itinerary 写入时间轴，但在生成最终总结前达到工具轮次上限；系统保留已校验的时间轴版本。",
                    )
                    preserved_tool_events = [*tool_events, write_preserved_marker]
                    preserved_events = self._safe_planning_events_from_tool_events(
                        preserved_tool_events,
                        session_id=session_id,
                        assistant_turn_id=assistant_turn_id,
                        itinerary_version_id=accepted_version_id,
                        failed=False,
                        verifier_report=verifier_report,
                    )
                    reply = (
                        "已写入并保留右侧时间轴。本轮 Agent 在生成最终总结前达到工具轮次上限，"
                        "所以我用已通过校验的 itinerary 版本作为结果；请以右侧时间轴为准继续编辑或让我再细化。"
                    )
                    self.db.execute(
                        """
                        UPDATE conversation_turns
                        SET content = ?, status = 'active', itinerary_version_id = ?, agent_response_json = ?,
                            error_json = NULL, updated_at = ?
                        WHERE id = ?
                        """,
                        (
                            reply,
                            accepted_version_id,
                            json.dumps(
                                {
                                    "mode": "tool_loop_exceeded_after_write",
                                    "reply": reply,
                                    "failureReason": failure_reason,
                                    "diagnostics": diagnostics,
                                    "planningSteps": self._serialize_planning_events(preserved_events),
                                    "toolEvents": self._serialize_planning_events(preserved_events),
                                },
                                ensure_ascii=False,
                                default=str,
                            ),
                            datetime.now(timezone.utc).isoformat(),
                            assistant_turn_id,
                        ),
                    )
                    self.db.execute(
                        """
                        UPDATE conversation_turns
                        SET itinerary_version_id = ?, updated_at = ?
                        WHERE id = ?
                        """,
                        (accepted_version_id, datetime.now(timezone.utc).isoformat(), user_turn_id),
                    )
                    itinerary = ItineraryService(self.db).get_plan(session_after_write["active_plan_id"])
                    planning_run = PlanningRunService(self.db).create_run(
                        "agent_tool_loop_exceeded_after_write",
                        user_input=content,
                        preference_summary=self._preference_summary_from_context(request_context),
                        itinerary=itinerary,
                        itinerary_version_id=accepted_version_id,
                        understood_requirements=request_context.get("understoodRequirements"),
                        final_summary=reply,
                        tool_calls_override=self._planning_tool_calls_from_tool_events(preserved_tool_events),
                    )
                    self._attach_planning_run_for_result_version(
                        assistant_turn_id, accepted_version_id, planning_run.id
                    )
                    if preserved_events:
                        self._store_planning_events(assistant_turn_id, preserved_events)
                    if not self._controller_manages_memory(request_context):
                        self._auto_update_preference_memory(session_id, content, reply)
                    self.db.commit()
                    version = self._version_response(
                        self._version(accepted_version_id, session_id, session_after_write["active_plan_id"])
                    )
                    return AgentMessageResponse(
                        userTurn=self._turn_response(user_turn_id),
                        assistantTurn=self._turn_response(assistant_turn_id),
                        itinerary=itinerary,
                        version=version,
                        pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
                        warnings=[failure_reason, "Agent 已写入时间轴，但最终总结因工具轮次上限被压缩。"],
                        planningRun=planning_run,
                        planningSteps=preserved_events,
                        toolEvents=preserved_events,
                    )
            self._rollback_tool_loop_writes(session_before)
            self._clear_tool_loop_poi_candidate_side_effects_for_turn(assistant_turn_id)
            self.db.execute(
                """
                UPDATE conversation_turns
                SET content = ?, status = 'failed', itinerary_version_id = ?, agent_response_json = ?,
                    error_json = ?, updated_at = ?
                WHERE id = ?
                """,
                (
                    f"Agent 主循环失败：{failure_reason}",
                    session_before["active_version_id"],
                    json.dumps(
                        {
                            "mode": "tool_loop_failed",
                            "reply": failure_reason,
                            "failureReason": failure_reason,
                            "diagnostics": diagnostics,
                            "planningSteps": self._serialize_planning_events(planning_events),
                            "toolEvents": self._serialize_planning_events(planning_events),
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                    json.dumps(
                        {"message": failure_reason, "diagnostics": diagnostics}, ensure_ascii=False, default=str
                    ),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            planning_run = PlanningRunService(self.db).create_run(
                "agent_tool_loop_failed",
                user_input=content,
                preference_summary=self._preference_summary_from_context(request_context),
                itinerary=ItineraryService(self.db).get_plan(session_before["active_plan_id"])
                if session_before["active_version_id"]
                else None,
                itinerary_version_id=session_before["active_version_id"],
                understood_requirements=request_context.get("understoodRequirements"),
                final_summary=f"Agent 主循环失败：{failure_reason}",
                tool_calls_override=self._planning_tool_calls_from_tool_events(tool_events),
            )
            ItineraryPatchService(self.db).attach_planning_run_for_source_turn(assistant_turn_id, planning_run.id)
            verifier_report = self._safe_verify_active_version_unchanged(session_before, "agent_tool_loop_failed")
            self._restore_preference_memory(preference_memory_before)
            self.db.commit()
            events = planning_events
            if not events:
                events = self._safe_planning_events(planning_run, assistant_turn_id, verifier_report)
                if events:
                    self._store_planning_events(assistant_turn_id, events)
                    self.db.commit()
            return AgentMessageResponse(
                userTurn=self._turn_response(user_turn_id),
                assistantTurn=self._turn_response(assistant_turn_id),
                itinerary=ItineraryService(self.db).get_plan(session_before["active_plan_id"])
                if session_before["active_version_id"]
                else None,
                version=self._version_response(
                    self._version(session_before["active_version_id"], session_id, session_before["active_plan_id"])
                )
                if session_before["active_version_id"]
                else None,
                pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
                warnings=[failure_reason],
                planningRun=planning_run,
                planningSteps=events,
                toolEvents=events,
            )

        tool_events = list(result.tool_events)
        session_after = self._session(session_id)
        active_version_id = self._latest_accepted_result_version_for_turn(assistant_turn_id)
        pending_candidates = ConversationService(self.db)._pending_candidates(session_id)
        request_requires_itinerary_write = self._request_requires_itinerary_write(request_context)
        if request_requires_itinerary_write and active_version_id is None and pending_candidates:
            result.reply = self._pending_poi_selection_reply(pending_candidates)
        missing_itinerary_write = (
            request_requires_itinerary_write
            and active_version_id is None
            and not self._has_pending_poi_clarification_reply(result.reply, pending_candidates)
        )
        if missing_itinerary_write:
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=assistant_turn_id,
                event_type="agent",
                label="补写时间轴重试",
                detail="首次工具循环没有写入时间轴，正在带着明确 patch_itinerary 合约重试一次。",
            )
            result, tool_events, _retry_succeeded = self._retry_tool_loop_after_missing_itinerary_write(
                result,
                tool_events,
                session_id,
                assistant_turn_id,
                request_context,
                preference_memory_before,
                event_sink=event_sink,
            )
            session_after = self._session(session_id)
            active_version_id = self._latest_accepted_result_version_for_turn(assistant_turn_id)
            pending_candidates = ConversationService(self.db)._pending_candidates(session_id)
        if (
            request_requires_itinerary_write
            and active_version_id is None
            and not self._has_pending_poi_clarification_reply(result.reply, pending_candidates)
        ):
            failure_reason = "Agent 没有调用 patch_itinerary 写入时间轴；本轮未覆盖当前行程。"
            verifier_report = self._safe_verify_active_version_unchanged(
                session_before, "agent_tool_loop_missing_itinerary_write"
            )
            planning_events = self._safe_planning_events_from_tool_events(
                tool_events,
                session_id=session_id,
                assistant_turn_id=assistant_turn_id,
                itinerary_version_id=session_before["active_version_id"],
                failed=True,
                verifier_report=verifier_report,
            )

            self._clear_tool_loop_poi_candidate_side_effects_for_turn(assistant_turn_id)
            current_session = self._session(session_id)
            self.db.execute(
                """
                UPDATE conversation_turns
                SET content = ?, status = 'failed', itinerary_version_id = ?, agent_response_json = ?,
                    error_json = ?, updated_at = ?
                WHERE id = ?
                """,
                (
                    f"Agent 主循环失败：{failure_reason}",
                    current_session["active_version_id"],
                    json.dumps(
                        {
                            "mode": "tool_loop_no_itinerary_write",
                            "reply": failure_reason,
                            "failureReason": failure_reason,
                            "planningSteps": self._serialize_planning_events(planning_events),
                            "toolEvents": self._serialize_planning_events(planning_events),
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                    json.dumps({"message": failure_reason}, ensure_ascii=False),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            planning_run = PlanningRunService(self.db).create_run(
                "agent_tool_loop_no_itinerary_write",
                user_input=content,
                preference_summary=self._preference_summary_from_context(request_context),
                itinerary=ItineraryService(self.db).get_plan(current_session["active_plan_id"])
                if current_session["active_version_id"]
                else None,
                itinerary_version_id=current_session["active_version_id"],
                understood_requirements=request_context.get("understoodRequirements"),
                final_summary=f"Agent 主循环失败：{failure_reason}",
                tool_calls_override=self._planning_tool_calls_from_tool_events(tool_events),
            )
            ItineraryPatchService(self.db).attach_planning_run_for_source_turn(assistant_turn_id, planning_run.id)
            self._restore_preference_memory(preference_memory_before)
            self.db.commit()
            return AgentMessageResponse(
                userTurn=self._turn_response(user_turn_id),
                assistantTurn=self._turn_response(assistant_turn_id),
                itinerary=ItineraryService(self.db).get_plan(current_session["active_plan_id"])
                if current_session["active_version_id"]
                else None,
                version=self._version_response(
                    self._version(current_session["active_version_id"], session_id, current_session["active_plan_id"])
                )
                if current_session["active_version_id"]
                else None,
                pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
                warnings=[failure_reason],
                planningRun=planning_run,
                planningSteps=planning_events,
                toolEvents=planning_events,
            )
        self._emit_execution_event(
            event_sink,
            session_id=session_id,
            turn_id=assistant_turn_id,
            event_type="verify",
            label="校验时间轴写入",
            detail="Agent 已完成工具循环，正在校验 patch_itinerary 写入的版本是否覆盖当前行程且满足 grounding 约束。",
        )
        verifier_report = self._verify_tool_loop_result_or_restore(session_before, assistant_turn_id, active_version_id)
        if not verifier_report.passed:
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=assistant_turn_id,
                event_type="verify",
                label="按校验反馈重试",
                detail="首次时间轴写入未通过 verifier，正在带着结构化失败原因重新调用工具循环。",
            )
            result, verifier_report, tool_events, _retry_succeeded = self._retry_tool_loop_after_verifier_failure(
                result,
                verifier_report,
                tool_events,
                session_id,
                assistant_turn_id,
                request_context,
                preference_memory_before,
                event_sink=event_sink,
            )
            session_after = self._session(session_id)
            active_version_id = self._latest_accepted_result_version_for_turn(assistant_turn_id)
        if not verifier_report.passed:
            failure_reason = "Agent verifier rejected tool-loop itinerary write"
            session_after = self._session(session_id)
            self.db.execute(
                """
                UPDATE conversation_turns
                SET content = ?, status = 'failed', agent_response_json = ?,
                    error_json = ?, updated_at = ?
                WHERE id = ?
                """,
                (
                    "Agent 校验未通过，行程已恢复到上一个安全版本。",
                    json.dumps(
                        {
                            "mode": "tool_loop_verifier_failed",
                            "reply": failure_reason,
                            "planningSteps": [],
                            "toolEvents": [],
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                    json.dumps(
                        {"message": failure_reason, "verifierReport": verifier_report.as_metadata()}, ensure_ascii=False
                    ),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            planning_run = PlanningRunService(self.db).create_run(
                "agent_verifier_failed",
                user_input=content,
                preference_summary=self._preference_summary_from_context(request_context),
                itinerary=ItineraryService(self.db).get_plan(session_after["active_plan_id"])
                if session_after["active_version_id"]
                else None,
                itinerary_version_id=session_after["active_version_id"],
                understood_requirements=request_context.get("understoodRequirements"),
                final_summary=f"{failure_reason}: {'; '.join(verifier_report.hard_failures)}",
                tool_calls_override=self._planning_tool_calls_from_tool_events(tool_events),
            )
            events = self._safe_planning_events_from_tool_events(
                tool_events,
                session_id=session_id,
                assistant_turn_id=assistant_turn_id,
                itinerary_version_id=session_after["active_version_id"],
                failed=True,
                verifier_report=verifier_report,
            )
            if events:
                self._store_planning_events(assistant_turn_id, events)
            self._clear_tool_loop_poi_candidate_side_effects_for_turn(assistant_turn_id)
            self._restore_preference_memory(preference_memory_before)
            if not self._controller_manages_memory(request_context):
                self._auto_update_preference_memory(session_id, content, failure_reason)
            self.db.commit()
            version = (
                self._version_response(
                    self._version(session_after["active_version_id"], session_id, session_after["active_plan_id"])
                )
                if session_after["active_version_id"]
                else None
            )
            return AgentMessageResponse(
                userTurn=self._turn_response(user_turn_id),
                assistantTurn=self._turn_response(assistant_turn_id),
                itinerary=ItineraryService(self.db).get_plan(session_after["active_plan_id"])
                if session_after["active_version_id"]
                else None,
                version=version,
                pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
                warnings=[failure_reason, *verifier_report.hard_failures],
                planningRun=planning_run,
                planningSteps=events,
                toolEvents=events,
            )
        planning_events = self._safe_planning_events_from_tool_events(
            tool_events,
            session_id=session_id,
            assistant_turn_id=assistant_turn_id,
            itinerary_version_id=active_version_id,
            failed=False,
            verifier_report=verifier_report,
        )
        self.db.execute(
            """
            UPDATE conversation_turns
            SET content = ?, status = 'active', agent_response_json = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                result.reply,
                json.dumps(
                    {
                        "mode": "tool_calling",
                        "reply": result.reply,
                        "planningSteps": self._serialize_planning_events(planning_events),
                        "toolEvents": self._serialize_planning_events(planning_events),
                    },
                    ensure_ascii=False,
                    default=str,
                ),
                datetime.now(timezone.utc).isoformat(),
                assistant_turn_id,
            ),
        )
        if active_version_id:
            self.db.execute(
                """
                UPDATE conversation_turns
                SET itinerary_version_id = ?, updated_at = ?
                WHERE id IN (?, ?)
                """,
                (active_version_id, datetime.now(timezone.utc).isoformat(), user_turn_id, assistant_turn_id),
            )
        itinerary = ItineraryService(self.db).get_plan(session_after["active_plan_id"]) if active_version_id else None
        planning_run = PlanningRunService(self.db).create_run(
            "agent_tool_calling",
            user_input=content,
            preference_summary=self._preference_summary_from_context(request_context),
            itinerary=itinerary,
            itinerary_version_id=active_version_id,
            understood_requirements=request_context.get("understoodRequirements"),
            final_summary=result.reply,
            tool_calls_override=self._planning_tool_calls_from_tool_events(tool_events),
        )
        self._attach_planning_run_for_result_version(assistant_turn_id, active_version_id, planning_run.id)
        if not self._controller_manages_memory(request_context):
            self._auto_update_preference_memory(session_id, content, result.reply)
        self.db.commit()
        events = planning_events
        if not events:
            events = self._safe_planning_events(planning_run, assistant_turn_id, verifier_report)
        if events:
            self._store_planning_events(assistant_turn_id, events)
            self.db.commit()
        version = (
            self._version_response(self._version(active_version_id, session_id, session_after["active_plan_id"]))
            if active_version_id
            else None
        )
        return AgentMessageResponse(
            userTurn=self._turn_response(user_turn_id),
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=itinerary,
            version=version,
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=[],
            planningRun=planning_run,
            planningSteps=events,
            toolEvents=events,
        )

    def _generate_with_initial_staged_pipeline(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        request_context: dict,
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> AgentMessageResponse:
        self._pipeline_event_perf = time.perf_counter()
        self._staged_pipeline_started = time.monotonic()
        self._staged_pipeline_deadline = self._staged_pipeline_started + STAGED_PIPELINE_TOTAL_DEADLINE_SECONDS
        if not isinstance(request_context.get("requestIntentContract"), dict):
            request_context["requestIntentContract"] = self._request_intent_contract(
                str(request_context.get("effectiveUserMessage") or request_context.get("latestUserMessage") or ""),
                self._resolve_trip_dates_from_context(request_context),
                self._meal_grounding_policy_result(request_context),
                city=str(request_context.get("selectedCity") or ""),
                simple_open_profile=self.initial_planning_mode == "simple_open_v1",
            )
        session_before = self._session(session_id)
        preference_memory_before = PreferenceService(self.db).get_memory(session_id=session_id, commit=False)
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            "Agent 正在执行分阶段规划流程。",
            "active",
            agent_request_json=request_context,
            agent_response_json={"mode": "staged_initial_pipeline", "reply": "", "planningSteps": [], "toolEvents": []},
        )
        tool_events: list[dict[str, Any]] = _StreamingPipelineEventList(
            [
                self._autonomy_observation_pipeline_event(request_context),
                self._autonomy_decision_pipeline_event(request_context),
            ],
            on_append=(
                lambda event: self._emit_tool_execution_event(
                    event_sink,
                    session_id=session_id,
                    turn_id=assistant_turn_id,
                    event=event,
                )
            )
            if event_sink is not None
            else None,
        )
        fallback_execution = (
            request_context.get("fallbackChoiceExecution")
            if isinstance(request_context.get("fallbackChoiceExecution"), dict)
            else None
        )
        if fallback_execution is not None:
            self._append_pipeline_event(
                tool_events,
                "fallback_confirmation_selected",
                "确认安全降级选项",
                "completed",
                "已按服务端持久化的结构化 action 认领本次执行；未解析按钮文案。",
                fallback_execution,
            )
            self._append_pipeline_event(
                tool_events,
                "fallback_execution_started",
                "开始执行确认动作",
                "completed",
                "选择生命周期已进入 executing。",
                fallback_execution,
            )
        manual_hints = self._manual_candidate_hints_from_context(request_context)
        retry_candidate_hints = bool(
            request_context.get("retryCandidateHints") or request_context.get("retry_candidate_hints")
        )
        resume_attempt_plan = self._resumable_plan_from_context(request_context)
        selected_choice = (
            request_context.get("selectedAgentChoice")
            if isinstance(request_context.get("selectedAgentChoice"), dict)
            else {}
        )
        resumed_waiting_plan = resume_attempt_plan or (
            self._last_waiting_staged_plan(
                session_id,
                selected_choice.get("sourceAssistantTurnId"),
                expected_execution_profile=(
                    "simple_open_v1" if request_context.get("serverExecutionProfile") == "simple_open_v1" else None
                ),
            )
            if (manual_hints or retry_candidate_hints)
            else None
        )
        resolved_dates = self._resolve_trip_dates_from_context(request_context)
        if resumed_waiting_plan and resolved_dates.get("status") != "resolved":
            previous_context = (
                resumed_waiting_plan.get("pipelineContext")
                if isinstance(resumed_waiting_plan.get("pipelineContext"), dict)
                else {}
            )
            previous_dates = (
                previous_context.get("resolvedTripDates")
                if isinstance(previous_context.get("resolvedTripDates"), dict)
                else {}
            )
            if previous_dates.get("status") == "resolved":
                resolved_dates = dict(previous_dates)
        pipeline_context = self._initial_staged_pipeline_context(request_context, resolved_dates)
        self.db.execute(
            "UPDATE conversation_turns SET agent_request_json = ?, updated_at = ? WHERE id = ? AND session_id = ?",
            (
                json.dumps(pipeline_context, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                assistant_turn_id,
                session_id,
            ),
        )
        if resumed_waiting_plan:
            previous_context = (
                resumed_waiting_plan.get("pipelineContext")
                if isinstance(resumed_waiting_plan.get("pipelineContext"), dict)
                else {}
            )
            pipeline_context = {
                **previous_context,
                **pipeline_context,
                "resolvedTripDates": resolved_dates,
                "manualCandidateHints": manual_hints,
            }
            if resume_attempt_plan:
                previous_effective = str(
                    previous_context.get("effectiveUserMessage") or previous_context.get("latestUserMessage") or ""
                ).strip()
                current_effective = str(request_context.get("effectiveUserMessage") or "").strip()
                if current_effective:
                    pipeline_context["effectiveUserMessage"] = current_effective
                elif previous_effective:
                    pipeline_context["effectiveUserMessage"] = previous_effective
        execution_route = str(request_context.get("actualExecutionRoute") or "staged_initial_pipeline")
        if request_context.get("serverExecutionProfile") == "simple_open_v1":
            self._append_pipeline_event(
                tool_events,
                "simple_open_planning_started",
                "启动简单初始规划",
                "completed",
                "服务端 execution profile 已选择 simple_open_initial_pipeline。",
                {"executionRoute": execution_route},
            )
        self._append_pipeline_event(
            tool_events,
            "agent_action_started",
            "执行自治动作",
            "completed",
            f"已选择 {execution_route} 作为本 cycle 的唯一高层动作。",
            {"executionRoute": execution_route, "cycleIndex": 0},
        )
        self._append_pipeline_event(
            tool_events,
            "normalize_request",
            "规范化用户需求",
            "completed",
            "已抽取目的地、天数、预算、人数、交通偏好，并统一出行日期。",
            {"resolvedTripDates": resolved_dates},
        )
        self._emit_execution_event(
            event_sink,
            session_id=session_id,
            turn_id=assistant_turn_id,
            event_type="agent",
            label="解析并约束行程需求",
            detail="正在确认日期、天数、预算、人数、交通方式和地点目标。",
        )
        try:
            created_version_id: Optional[str] = None
            creative_ledger = None
            creative_portfolio: Optional[InitialCreativePortfolio] = None
            if resolved_dates.get("status") != "resolved":
                raise ValueError(
                    f"出行日期无法解析或不支持：{resolved_dates.get('reason') or '未创建 itinerary version。'}"
                )
            if resumed_waiting_plan:
                initial_plan = AgentInitialPlanOutput.model_validate(resumed_waiting_plan["initialPlan"])
                raw_ledger = resumed_waiting_plan.get("constraintLedger")
                raw_portfolio = resumed_waiting_plan.get("creativePortfolio")
                structured_portfolio_resume = bool(request_context.get("structuredPlanningChoiceResume"))
                checkpoint_portfolio_resume = self._portfolio_resume_allowed(
                    request_context,
                    resumed_waiting_plan,
                )
                if checkpoint_portfolio_resume:
                    if not isinstance(raw_ledger, dict) or not isinstance(raw_portfolio, dict):
                        raise ValueError("portfolio_density_resume_checkpoint_missing")
                    creative_ledger = ConstraintLedger.model_validate(raw_ledger)
                    creative_portfolio = InitialCreativePortfolio.model_validate(raw_portfolio)
                    pipeline_context["creativePortfolioMode"] = True
                    grounding_checkpoint = resumed_waiting_plan.get("groundingCheckpoint")
                    if isinstance(grounding_checkpoint, dict):
                        pipeline_context["portfolioGroundingCheckpoint"] = copy.deepcopy(grounding_checkpoint)
                    if not structured_portfolio_resume:
                        pipeline_context["checkpointPortfolioResume"] = True
                    for key in ("goalOccurrencePlan", "dailyCapacityPlan"):
                        if key in pipeline_context:
                            request_context[key] = copy.deepcopy(pipeline_context[key])
                added_count = 0
                hinted_pool_count = 0
                if manual_hints:
                    hints_by_pool = self._manual_candidate_hints_by_pool(initial_plan, manual_hints)
                    initial_plan, added_count, hinted_pool_count = self._apply_candidate_hints_to_initial_plan(
                        initial_plan,
                        hints_by_pool,
                        prefer_new=True,
                    )
                self._append_pipeline_event(
                    tool_events,
                    "initial_day_slot_provider",
                    "复用上次规划槽位" if resume_attempt_plan else "初始 DaySlot provider",
                    "completed",
                    "已复用上一轮未完成规划的 DaySlot/IntentPool；未重新调用 DaySlot provider。"
                    if resume_attempt_plan
                    else "已复用当前 active session 的 waiting DaySlot/IntentPool；未重新调用 DaySlot provider。",
                    {
                        "providerReturnedMode": "planning_attempt_resume"
                        if resume_attempt_plan
                        else ("manual_candidate_hints_resume" if manual_hints else "retry_candidate_hints_resume"),
                        "daySlotCount": len(initial_plan.day_slots),
                        "intentPoolCount": len(initial_plan.intent_pools),
                        "fallbackUsed": True,
                        "fallbackType": "planning_attempt_resume"
                        if resume_attempt_plan
                        else ("manual_candidate_hints_resume" if manual_hints else "retry_candidate_hints_resume"),
                        "manualCandidateHintsUsed": bool(manual_hints),
                        "retryCandidateHints": retry_candidate_hints,
                        "manualCandidateHintsAdded": added_count,
                        "hintedPoolCount": hinted_pool_count,
                        "sourceAssistantTurnId": resumed_waiting_plan.get("sourceAssistantTurnId"),
                        "resumeResultState": resumed_waiting_plan.get("resultState"),
                    },
                )
                if retry_candidate_hints and not manual_hints and not resume_attempt_plan:
                    pipeline_context["candidateHintRetryAttempted"] = True
                    retry_plan = self._retry_initial_plan_with_candidate_hints(
                        initial_plan, pipeline_context, tool_events
                    )
                    if retry_plan is not None:
                        initial_plan = retry_plan
            elif (
                self._creative_portfolio_enabled(request_context)
                and not bool(pipeline_context.get("explicitRuleSafeDraft"))
                and request_context.get("serverExecutionProfile") != "simple_open_v1"
            ):
                creative_ledger, creative_portfolio = self._generate_initial_creative_portfolio(
                    pipeline_context,
                    tool_events,
                    allow_provider=pipeline_context.get("_partialPlanExpansionAuthorized") is not True,
                )
                generated_brief_ids = [str(item.brief.brief_id or "") for item in creative_portfolio.proposals]
                expansion_claim_context = (
                    pipeline_context.get("partialPlanExpansionClaim")
                    if isinstance(pipeline_context.get("partialPlanExpansionClaim"), dict)
                    else request_context.get("partialPlanExpansionClaim")
                    if isinstance(request_context.get("partialPlanExpansionClaim"), dict)
                    else {}
                )
                expansion_focus_mode = str(
                    pipeline_context.get("partialPlanExpansionFocusMode")
                    or request_context.get("partialPlanExpansionFocusMode")
                    or expansion_claim_context.get("expansionFocusMode")
                    or ""
                )
                authorized_expansion_focus = (
                    str(
                        pipeline_context.get("focusBriefId")
                        or request_context.get("focusBriefId")
                        or expansion_claim_context.get("focusBriefId")
                        or ""
                    )
                    if pipeline_context.get("_partialPlanExpansionAuthorized") is True
                    else ""
                )
                if authorized_expansion_focus and expansion_focus_mode == "discover_next":
                    requested_focus_brief_id = authorized_expansion_focus
                    active_partial_focus_brief_id = str(
                        pipeline_context.get("activePartialFocusBriefId")
                        or request_context.get("activePartialFocusBriefId")
                        or expansion_claim_context.get("activePartialFocusBriefId")
                        or ""
                    )
                    direction_signature_by_brief = (
                        pipeline_context.get("_creativeDirectionSignatureByBriefId")
                        if isinstance(pipeline_context.get("_creativeDirectionSignatureByBriefId"), dict)
                        else {}
                    )
                    exploration_frontier = (
                        pipeline_context.get("_creativeExplorationFrontier")
                        if isinstance(pipeline_context.get("_creativeExplorationFrontier"), dict)
                        else {}
                    )
                    authorized_expansion_focus = self._next_unattempted_portfolio_brief_id(
                        generated_brief_ids,
                        active_focus_brief_id=active_partial_focus_brief_id,
                        direction_signature_by_brief=direction_signature_by_brief,
                        frontier=exploration_frontier,
                    )
                    if not authorized_expansion_focus:
                        # Replaying a previously rejected signature can only
                        # produce another novelty failure.  Exhaust this
                        # dynamic cursor truthfully instead of silently
                        # resolving discover_next back to an old direction.
                        raise ValueError("creative_frontier_semantic_exhausted:no_unattempted_direction_signature")
                    resolved_direction_signature = str(
                        direction_signature_by_brief.get(authorized_expansion_focus) or ""
                    )
                    if not resolved_direction_signature:
                        raise ValueError("creative_portfolio_resolved_direction_signature_missing")
                    resolved_claim = (
                        copy.deepcopy(pipeline_context.get("partialPlanExpansionClaim"))
                        if isinstance(pipeline_context.get("partialPlanExpansionClaim"), dict)
                        else {}
                    )
                    resolved_claim.update(
                        {
                            "requestedFocusBriefId": requested_focus_brief_id,
                            "resolvedFocusBriefId": authorized_expansion_focus,
                            "resolvedDirectionSignature": resolved_direction_signature,
                        }
                    )
                    pipeline_context["partialPlanExpansionClaim"] = resolved_claim
                    pipeline_context["focusBriefId"] = authorized_expansion_focus
                    pipeline_context["portfolioGroundingFocusBriefId"] = authorized_expansion_focus
                    request_context["partialPlanExpansionClaim"] = copy.deepcopy(resolved_claim)
                    request_context["focusBriefId"] = authorized_expansion_focus
                    request_context["portfolioGroundingFocusBriefId"] = authorized_expansion_focus
                    selected_expansion_choice = (
                        request_context.get("selectedAgentChoice")
                        if isinstance(request_context.get("selectedAgentChoice"), dict)
                        else {}
                    )
                    if selected_expansion_choice:
                        selected_expansion_choice["continuationCheckpoint"] = copy.deepcopy(resolved_claim)
                    execution_claim = (
                        request_context.get("fallbackChoiceExecutionClaim")
                        if isinstance(request_context.get("fallbackChoiceExecutionClaim"), dict)
                        else {}
                    )
                    execution_id = str(execution_claim.get("id") or "")
                    if execution_id:
                        self.db.execute(
                            """UPDATE agent_choice_executions
                            SET continuation_json = json_patch(COALESCE(continuation_json, '{}'), ?), updated_at = ?
                            WHERE id = ? AND session_id = ? AND status = 'executing'""",
                            (
                                json.dumps(resolved_claim, ensure_ascii=False, default=str),
                                datetime.now(timezone.utc).isoformat(),
                                execution_id,
                                session_id,
                            ),
                        )
                    self._persist_agent_request_context(
                        session_id,
                        user_turn_id,
                        request_context,
                    )
                    self.db.execute(
                        """UPDATE conversation_turns
                        SET agent_request_json = ?, updated_at = ?
                        WHERE id = ? AND session_id = ?""",
                        (
                            json.dumps(pipeline_context, ensure_ascii=False, default=str),
                            datetime.now(timezone.utc).isoformat(),
                            assistant_turn_id,
                            session_id,
                        ),
                    )
                focus_brief_id = (
                    self._trusted_portfolio_focus_brief_id(
                        continuation=(
                            pipeline_context.get("portfolioDensityContinuation")
                            if isinstance(pipeline_context.get("portfolioDensityContinuation"), dict)
                            else None
                        ),
                        grounding_pipeline_context=pipeline_context,
                        request_context=pipeline_context,
                        generated_brief_ids=generated_brief_ids,
                        authorized_expansion_focus_brief_id=authorized_expansion_focus,
                    )
                    if authorized_expansion_focus
                    else next(iter(generated_brief_ids), "")
                )
                grounding_portfolio = creative_portfolio
                focused_proposals = self._portfolio_grounding_proposals(
                    creative_portfolio.proposals,
                    focus_brief_id=focus_brief_id,
                    expansion_authorized=bool(authorized_expansion_focus),
                )
                if not focused_proposals:
                    # Never compile an empty portfolio.  A dynamic continuation
                    # either resolves to a new server-generated brief above or
                    # terminates as a stable exhausted frontier; forwarding an
                    # empty list would misreport this local identity failure as
                    # ``creative_portfolio_missing_proposals``.
                    if authorized_expansion_focus and expansion_focus_mode == "discover_next":
                        raise ValueError("creative_frontier_semantic_exhausted:candidate_inventory_exhausted")
                    raise ValueError("portfolio_partial_resolved_focus_invalid")
                if focused_proposals != list(creative_portfolio.proposals):
                    grounding_portfolio = creative_portfolio.model_copy(update={"proposals": focused_proposals})
                initial_plan = self._initial_plan_from_creative_portfolio(grounding_portfolio)
                pipeline_context["creativePortfolioMode"] = True
                if focus_brief_id:
                    # The server-validated same-root expansion target overrides
                    # stale focus from the active partial. Only that brief enters
                    # candidate grounding; the complete direction set remains in
                    # ``creative_portfolio`` for comparison lineage and staging.
                    pipeline_context["portfolioGroundingFocusBriefId"] = focus_brief_id
                if authorized_expansion_focus:
                    # A later-plan request must not reuse an empty first-round
                    # candidate cache for the target brief. Refresh remains
                    # bounded by the existing per-turn AMap budget.
                    pipeline_context["forceCandidateRefresh"] = True
                # Proposal snapshots need the same pure occurrence/capacity
                # contract that generated their DaySlots. This is evidence only;
                # it does not grant the staging plane write authority.
                for key in ("goalOccurrencePlan", "dailyCapacityPlan"):
                    if key in pipeline_context:
                        request_context[key] = copy.deepcopy(pipeline_context[key])
            else:
                initial_plan = self._generate_initial_day_slot_output(pipeline_context, tool_events)
            campus_constraint = (pipeline_context.get("hardConstraints") or {}).get("campusTier")
            if isinstance(campus_constraint, dict):
                intent_contract = (
                    pipeline_context.get("requestIntentContract")
                    if isinstance(pipeline_context.get("requestIntentContract"), dict)
                    else {}
                )
                expected_count = next(
                    (
                        int(item.get("target") or item.get("requiredMin") or 0)
                        for item in intent_contract.get("requiredIntents") or []
                        if isinstance(item, dict) and str(item.get("intentType") or "") == "campus_visit"
                    ),
                    0,
                )
                campus_constraint["expectedCount"] = max(1, expected_count)
            if initial_plan.mode == "cannot_plan":
                reason = (
                    "; ".join(initial_plan.warnings) or initial_plan.reply or "initial planner returned cannot_plan"
                )
                raise ValueError(f"CANNOT_PLAN: {reason}")
            if request_context.get("serverExecutionProfile") == "simple_open_v1":
                self._append_pipeline_event(
                    tool_events,
                    "simple_open_draft_created",
                    "生成简单行程草案",
                    "completed",
                    f"DaySlot Provider 已返回结构化 {len(resolved_dates.get('dates') or [])} 日草案，尚未执行正式写入。",
                    {
                        "daySlotCount": len(initial_plan.day_slots),
                        "intentPoolCount": len(initial_plan.intent_pools),
                    },
                )
            if creative_portfolio is not None:
                if isinstance(request_context.get("fallbackChoiceExecutionClaim"), dict):
                    # Carry the already-persisted opaque continuation claim into
                    # the grounding data plane.  It is an execution identity,
                    # never a seed for profile/query ordering.
                    pipeline_context["fallbackChoiceExecutionClaim"] = copy.deepcopy(
                        request_context["fallbackChoiceExecutionClaim"]
                    )
                self._bind_same_root_search_exclusions(
                    session_id=session_id,
                    assistant_turn_id=assistant_turn_id,
                    pipeline_context=pipeline_context,
                )
            if request_context.get("serverExecutionProfile") == "simple_open_v1":
                self._prepare_simple_open_direction_frontier(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    assistant_turn_id=assistant_turn_id,
                    city=str(session_before["city"] or ""),
                    active_version_id=str(session_before["active_version_id"] or "") or None,
                    request_context=request_context,
                    pipeline_context=pipeline_context,
                    initial_plan=initial_plan,
                    resolved_dates=resolved_dates,
                    tool_events=tool_events,
                )
                # The simple executor owns its bounded one-search-per-slot data
                # plane. Running the strict candidate-first compiler first would
                # duplicate Provider calls and then discard its result.
                segment_plans = self._simple_open_persistable_segment_plans(
                    initial_plan,
                    city=str(session_before["city"] or ""),
                    transport_mode=str(pipeline_context.get("transportMode") or "public_transit"),
                    tool_events=tool_events,
                    pipeline_context=pipeline_context,
                    session_id=session_id,
                )
                grounding_report = {
                    "resultState": "simple_open_grounded",
                    "poolReports": [],
                    "unresolvedSlots": [],
                    "blockingRequiredIntents": [],
                    "rateLimited": False,
                }
            else:
                segment_plans, grounding_report = self._build_candidate_first_segment_plans(
                    session_before,
                    initial_plan,
                    pipeline_context,
                    tool_events,
                    event_sink=event_sink,
                    assistant_turn_id=assistant_turn_id,
                )
            pipeline_context["candidateFirstGrounding"] = grounding_report
            material_evidence = self._persist_initial_material_tradeoff_candidates(
                session_id=session_id,
                turn_id=assistant_turn_id,
                grounding_report=grounding_report,
                pipeline_context=pipeline_context,
                persist_records=creative_portfolio is None or creative_ledger is None,
            )
            blocking_required_intents = [
                item
                for item in grounding_report.get("blockingRequiredIntents") or []
                if isinstance(item, dict) and int(item.get("missingCount") or 0) > 0
            ]
            if creative_portfolio is not None and creative_ledger is not None:
                if blocking_required_intents:
                    discoverable_required_gap = any(
                        str(report.get("requirementLevel") or "") == "required"
                        and str(report.get("coverageStatus") or "") != "covered"
                        and any(
                            str(mode or "") == "web_seed_then_amap"
                            for mode in [
                                *list(report.get("queryPlanModes") or []),
                                *[
                                    plan.get("mode")
                                    for plan in (
                                        (
                                            report.get("searchProfile")
                                            if isinstance(report.get("searchProfile"), dict)
                                            else {}
                                        ).get("queryPlans")
                                        or []
                                    )
                                    if isinstance(plan, dict)
                                ],
                            ]
                        )
                        for report in grounding_report.get("poolReports") or []
                        if isinstance(report, dict)
                    )
                    # Required goals belong to the planning root, not a
                    # creative brief. A provider-grounded exact-entity gap is
                    # terminal for this preflight, but a fuzzy experience with
                    # a compiled entity-discovery plan must reach Portfolio
                    # discovery before it can be called missing. Otherwise the
                    # strict blocker prevents the only bounded operation that
                    # can turn a generic need (for example, city night views)
                    # into named AMap identities.
                    grounding_report["rootGlobalBlocker"] = {
                        "kind": "required_goal_gap",
                        "status": (
                            "candidate_discovery_required"
                            if discoverable_required_gap
                            else "candidate_refresh_required"
                        ),
                        "goals": [
                            {
                                "goalId": str(item.get("goalId") or item.get("sourceGoalId") or ""),
                                "intentType": str(item.get("intentType") or ""),
                                "missingCount": int(item.get("missingCount") or 0),
                                "requiredCount": int(item.get("requiredCount") or item.get("targetCount") or 0),
                            }
                            for item in blocking_required_intents
                        ],
                    }
                    if (
                        not discoverable_required_gap
                        and request_context.get("serverExecutionProfile") != "simple_open_v1"
                    ):
                        grounding_report["resultState"] = "candidate_refresh_required"
                        return self._uncreated_staged_pipeline_response(
                            session_id,
                            user_turn_id,
                            assistant_turn_id,
                            content,
                            request_context,
                            session_before,
                            tool_events,
                            "candidate_refresh_required",
                            grounding_report,
                        )
                # Portfolio staging consumes the read-only candidate universe
                # directly. Do not run legacy single-plan blockers or create a
                # union skeleton for mutually exclusive briefs first.
                return self._stage_creative_portfolio_response(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    assistant_turn_id=assistant_turn_id,
                    content=content,
                    request_context=request_context,
                    session_before=session_before,
                    tool_events=tool_events,
                    initial_plan=initial_plan,
                    segment_plans=segment_plans,
                    grounding_report=grounding_report,
                    ledger=creative_ledger,
                    generated=creative_portfolio,
                    event_sink=event_sink,
                )
            if (
                material_evidence.get("allHardUnresolvedAreMaterialTradeoffs")
                and request_context.get("serverExecutionProfile") != "simple_open_v1"
            ):
                # A creative portfolio is itself the bounded way to present
                # material hard-goal trade-offs.  Do not divert to the legacy
                # one-pool-at-a-time choice flow before proposal-only staging.
                grounding_report["resultState"] = "waiting_for_poi_grounding"
                grounding_report["candidateEvidence"] = material_evidence.get("candidateEvidence", [])
                authorized_skeleton_plans = (
                    self._skeleton_segment_plans_from_initial_plan(
                        initial_plan,
                        pipeline_context,
                        grounding_report,
                    )
                    if creative_portfolio is None
                    else []
                )
                grounded_anchor_plans = [
                    plan for plan in segment_plans if plan.route_anchor and plan.selected_poi is not None
                ]
                grounded_segment_plans = [plan for plan in segment_plans if plan.selected_poi is not None]
                fallback_contract_anchor_plans = [
                    plan for plan in grounded_anchor_plans if plan.required is True or bool(plan.goal_id)
                ]
                if grounded_anchor_plans and (fallback_execution is None or fallback_contract_anchor_plans):
                    # A material gap must not hide the route anchors that are
                    # already real and usable. Publish them through the existing
                    # versioned writer and carry the exact missing slots as
                    # metadata for the read-only map/chat completion loop.
                    segment_plans = grounded_segment_plans
                    pending_slots = self._pending_slots_from_grounding_report(
                        grounding_report,
                        initial_plan=initial_plan,
                    )
                    pipeline_context["portfolioPartialTimeline"] = True
                    pipeline_context["portfolioPendingSlots"] = pending_slots
                    grounding_report["resultState"] = "partial_timeline_created"
                    grounding_report["portfolioPendingSlots"] = pending_slots
                    grounding_report["finalization"] = {
                        **dict(grounding_report.get("finalization") or {}),
                        "canCreateVersion": True,
                        "canCreateActiveVersion": True,
                        "canCreateCompleteVersion": False,
                        "draftPersistenceOverride": True,
                        "unresolvedPolicy": "persist_viable_partial_days",
                        "resultState": "partial_timeline_created",
                    }
                    pipeline_context["candidateFirstGrounding"] = grounding_report
                if authorized_skeleton_plans:
                    if not grounded_anchor_plans:
                        segment_plans = authorized_skeleton_plans
                        grounding_report = self._mark_skeleton_draft_grounding_report(
                            grounding_report,
                            segment_plans,
                        )
                        grounding_report["skeletonDraftAuthorized"] = True
                        pipeline_context["candidateFirstGrounding"] = grounding_report
                self._append_pipeline_event(
                    tool_events,
                    "persist_candidate_evidence",
                    "持久化候选证据",
                    "completed",
                    "已持久化多个安全候选；未创建 placeholder itinerary version。",
                    {
                        "candidateRecordIds": material_evidence.get("candidateRecordIds", []),
                        "candidateRecordCount": len(material_evidence.get("candidateRecordIds", [])),
                        "groundedAnchorPlanCount": len(grounded_anchor_plans),
                        "groundedSegmentPlanCount": len(grounded_segment_plans),
                        "activeVersionChanged": False,
                        "patchCreated": False,
                        "versionCreated": False,
                    },
                )
                if (
                    not authorized_skeleton_plans
                    and not grounded_anchor_plans
                    and int(grounding_report.get("routeAnchorSelectedCount") or 0) <= 0
                ):
                    return self._uncreated_staged_pipeline_response(
                        session_id,
                        user_turn_id,
                        assistant_turn_id,
                        content,
                        request_context,
                        session_before,
                        tool_events,
                        "waiting_for_poi_grounding",
                        grounding_report,
                    )
            requirements = (
                pipeline_context.get("understoodRequirements")
                if isinstance(pipeline_context.get("understoodRequirements"), dict)
                else {}
            )
            requirement_fields = requirements.get("fields") if isinstance(requirements.get("fields"), dict) else {}
            effective_message = str(
                pipeline_context.get("effectiveUserMessage") or pipeline_context.get("latestUserMessage") or ""
            )
            density_gap_days = [
                int(item.get("dayNumber") or 0)
                for item in grounding_report.get("dayReadiness") or []
                if isinstance(item, dict)
                and int(item.get("requiredRouteAnchors") or 0) > 0
                and (
                    int(item.get("selectedRouteAnchors") or 0) < int(item.get("requiredRouteAnchors") or 0)
                    or int(item.get("unresolvedRouteAnchors") or 0) > 0
                    or int(item.get("placeholderRouteAnchors") or 0) > 0
                )
            ]
            if (
                request_context.get("serverExecutionProfile") != "simple_open_v1"
                and creative_portfolio is None
                and density_gap_days
                and not grounding_report.get("rateLimited")
                and self._looks_like_complete_itinerary_spec(effective_message, requirement_fields)
                and not pipeline_context.get("portfolioPartialTimeline")
            ):
                grounded_anchor_plans = [
                    plan for plan in segment_plans if plan.route_anchor and plan.selected_poi is not None
                ]
                fallback_contract_anchor_plans = [
                    plan for plan in grounded_anchor_plans if plan.required is True or bool(plan.goal_id)
                ]
                if grounded_anchor_plans and (fallback_execution is None or fallback_contract_anchor_plans):
                    # Publish only the already grounded route anchors. Missing
                    # slots remain metadata so the map and timeline can show a
                    # truthful partial plan without inventing POIs.
                    segment_plans = [plan for plan in segment_plans if plan.selected_poi is not None]
                    pending_slots = self._pending_slots_from_grounding_report(
                        grounding_report,
                        initial_plan=initial_plan,
                    )
                    pipeline_context["portfolioPartialTimeline"] = True
                    pipeline_context["portfolioPendingSlots"] = pending_slots
                    grounding_report["resultState"] = "partial_timeline_created"
                    grounding_report["portfolioPendingSlots"] = pending_slots
                    grounding_report["finalization"] = {
                        **dict(grounding_report.get("finalization") or {}),
                        "canCreateVersion": True,
                        "canCreateActiveVersion": True,
                        "canCreateCompleteVersion": False,
                        "draftPersistenceOverride": True,
                        "unresolvedPolicy": "persist_viable_partial_days",
                        "resultState": "partial_timeline_created",
                    }
                    pipeline_context["candidateFirstGrounding"] = grounding_report
                else:
                    grounding_report["resultState"] = "waiting_for_required_intent"
                    return self._uncreated_staged_pipeline_response(
                        session_id,
                        user_turn_id,
                        assistant_turn_id,
                        content,
                        request_context,
                        session_before,
                        tool_events,
                        "waiting_for_required_intent",
                        grounding_report,
                    )
            if (
                request_context.get("serverExecutionProfile") != "simple_open_v1"
                and creative_portfolio is None
                and blocking_required_intents
                and not grounding_report.get("skeletonDraftAuthorized")
                and not pipeline_context.get("portfolioPartialTimeline")
            ):
                authorized_skeleton_plans = self._skeleton_segment_plans_from_initial_plan(
                    initial_plan,
                    pipeline_context,
                    grounding_report,
                )
                if authorized_skeleton_plans:
                    segment_plans = authorized_skeleton_plans
                    grounding_report = self._mark_skeleton_draft_grounding_report(
                        grounding_report,
                        segment_plans,
                    )
                    grounding_report["skeletonDraftAuthorized"] = True
                    pipeline_context["candidateFirstGrounding"] = grounding_report
            if (
                request_context.get("serverExecutionProfile") != "simple_open_v1"
                and creative_portfolio is None
                and blocking_required_intents
                and segment_plans
                and not grounding_report.get("skeletonDraftAuthorized")
                and not pipeline_context.get("portfolioPartialTimeline")
            ):
                # Never persist a partially grounded selection when a hard
                # intent is still missing.  When nothing was grounded, the
                # existing skeleton-draft authorization below may still create
                # an explicitly editable, non-active draft with truthful
                # placeholders.
                blocked_state = "waiting_for_required_intent"
                grounding_report["resultState"] = blocked_state
                return self._uncreated_staged_pipeline_response(
                    session_id,
                    user_turn_id,
                    assistant_turn_id,
                    content,
                    request_context,
                    session_before,
                    tool_events,
                    blocked_state,
                    grounding_report,
                )
            fallback_has_grounded_anchor = any(
                plan.route_anchor and plan.selected_poi is not None and (plan.required is True or bool(plan.goal_id))
                for plan in segment_plans
            )
            fallback_unresolved = bool(
                fallback_execution is not None
                and not fallback_has_grounded_anchor
                and (
                    blocking_required_intents
                    or density_gap_days
                    or grounding_report.get("unresolvedSlots")
                    or any(plan.route_anchor and plan.selected_poi is None for plan in segment_plans)
                    or grounding_report.get("resultState")
                    in {
                        "waiting_for_poi_grounding",
                        "waiting_for_required_intent",
                        "semantic_candidate_hint_missing",
                        "provider_rate_limited",
                    }
                )
            )
            if fallback_unresolved and request_context.get("serverExecutionProfile") != "simple_open_v1":
                # A persisted safe-fallback choice is not evidence that an
                # unresolved target became covered.  Keep a zero-anchor claim
                # retryable and preserve the zero-write contract.  Once at
                # least one real route anchor exists, the normal full/partial
                # finalizer remains authoritative and may publish it through
                # the existing single writer.
                grounding_report["resultState"] = "waiting_for_poi_grounding"
                return self._uncreated_staged_pipeline_response(
                    session_id,
                    user_turn_id,
                    assistant_turn_id,
                    content,
                    request_context,
                    session_before,
                    tool_events,
                    "waiting_for_poi_grounding",
                    grounding_report,
                )
            if (
                grounding_report.get("resultState") == "semantic_candidate_hint_missing"
                and request_context.get("serverExecutionProfile") != "simple_open_v1"
            ):
                return self._uncreated_staged_pipeline_response(
                    session_id,
                    user_turn_id,
                    assistant_turn_id,
                    content,
                    request_context,
                    session_before,
                    tool_events,
                    "semantic_candidate_hint_missing",
                    grounding_report,
                )
            if request_context.get("serverExecutionProfile") == "simple_open_v1":
                write_allowed = self.simple_open_itinerary_executor.apply_grounding_outcome(
                    segment_plans,
                    pipeline_context,
                    grounding_report,
                )
                if not write_allowed:
                    self._append_pipeline_event(
                        tool_events,
                        "simple_open_result_classified",
                        "分类简单行程结果",
                        "failed",
                        "本轮没有任何可验证的高德地点，禁止创建 active version。",
                        {"resultClass": "FAILED", "writeCount": 0},
                    )
                    self._append_pipeline_event(
                        tool_events,
                        "simple_open_terminal",
                        "终止简单初始行程",
                        "failed",
                        "未找到真实 Provider identity，本轮保持零正式写入。",
                        {"terminalStatus": "failed", "writeCount": 0},
                    )
                    frontier_execution_id = str(pipeline_context.get("simpleDirectionFrontierExecutionId") or "")
                    frontier_outcomes = [
                        item
                        for item in pipeline_context.get("simpleDirectionFrontierOutcomes") or []
                        if isinstance(item, dict)
                    ]
                    if frontier_execution_id and frontier_outcomes:
                        return self._simple_open_direction_proposal_response(
                            session_id=session_id,
                            user_turn_id=user_turn_id,
                            assistant_turn_id=assistant_turn_id,
                            content=content,
                            request_context=request_context,
                            pipeline_context=pipeline_context,
                            session_before=session_before,
                            initial_plan=initial_plan,
                            resolved_dates=resolved_dates,
                            grounding_report=grounding_report,
                            snapshot={},
                            tool_events=tool_events,
                            settle_unresolved_frontier=True,
                        )
                    return self._uncreated_staged_pipeline_response(
                        session_id,
                        user_turn_id,
                        assistant_turn_id,
                        content,
                        request_context,
                        session_before,
                        tool_events,
                        "simple_open_failed_no_real_poi",
                        grounding_report,
                    )
            if not segment_plans:
                skeleton_plans = (
                    []
                    if self._semantic_candidate_hint_shortage(grounding_report)
                    else self._skeleton_segment_plans_from_initial_plan(
                        initial_plan,
                        pipeline_context,
                        grounding_report,
                    )
                )
                if skeleton_plans:
                    segment_plans = skeleton_plans
                    grounding_report = self._mark_skeleton_draft_grounding_report(grounding_report, segment_plans)
                    pipeline_context["candidateFirstGrounding"] = grounding_report
                    self._append_pipeline_event(
                        tool_events,
                        "build_skeleton_draft_segments",
                        "构建待补全草稿日程段",
                        "completed",
                        "地图候选不足时已从 DaySlot 创建可编辑草稿段；routeAnchor 均保持待高德候选补全。",
                        {
                            "persistableSegmentCount": len(segment_plans),
                            "resultState": grounding_report.get("resultState"),
                            "finalization": grounding_report.get("finalization"),
                        },
                    )
                else:
                    state = str(
                        grounding_report.get("resultState")
                        or (
                            "provider_rate_limited"
                            if grounding_report.get("rateLimited")
                            else "waiting_for_poi_grounding"
                        )
                    )
                    return self._uncreated_staged_pipeline_response(
                        session_id,
                        user_turn_id,
                        assistant_turn_id,
                        content,
                        request_context,
                        session_before,
                        tool_events,
                        state,
                        grounding_report,
                    )
            pipeline_context.setdefault("currentUserTurnId", user_turn_id)
            pipeline_context.setdefault(
                "planningSelectionRootTurnId",
                str(
                    request_context.get("planningSelectionRootTurnId")
                    or request_context.get("currentUserTurnId")
                    or user_turn_id
                ),
            )
            if isinstance(request_context.get("requestIntentContract"), dict):
                pipeline_context.setdefault(
                    "requestIntentContract",
                    copy.deepcopy(request_context["requestIntentContract"]),
                )
            operations = self._operations_for_persistable_segment_plans(
                session_before,
                initial_plan,
                segment_plans,
                pipeline_context,
            )
            if request_context.get("serverExecutionProfile") == "simple_open_v1":
                proposal_snapshot = operations[0].full_itinerary if operations else None
                if not isinstance(proposal_snapshot, dict):
                    raise RuntimeError("SIMPLE_DIRECTION_SNAPSHOT_MISSING")
                return self._simple_open_direction_proposal_response(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    assistant_turn_id=assistant_turn_id,
                    content=content,
                    request_context=request_context,
                    pipeline_context=pipeline_context,
                    session_before=session_before,
                    initial_plan=initial_plan,
                    resolved_dates=resolved_dates,
                    grounding_report=grounding_report,
                    snapshot=proposal_snapshot,
                    tool_events=tool_events,
                )
            base_version_id = (
                session_before["active_version_id"] if self._regenerate_request_enabled(request_context) else None
            )
            try:
                if request_context.get("serverExecutionProfile") == "simple_open_v1":
                    self._append_pipeline_event(
                        tool_events,
                        "simple_open_persist_started",
                        "开始持久化简单行程",
                        "completed",
                        "正在通过 canonical ItineraryPatchService 执行本轮唯一正式写入。",
                        {"baseVersionId": base_version_id, "writeOrdinal": 1},
                    )
                self._emit_execution_event(
                    event_sink,
                    session_id=session_id,
                    turn_id=assistant_turn_id,
                    event_type="timeline",
                    label="生成可见时间轴",
                    detail="正在通过现有单写者保存已核验地点和明确待补槽位。",
                )
                result = ItineraryPatchService(self.db).apply_patch(
                    session_before["active_plan_id"],
                    operations,
                    source_type="agent",
                    base_version_id=base_version_id,
                    source_turn_id=assistant_turn_id,
                    preference_summary=self._preference_summary_from_context(request_context),
                    planning_context=pipeline_context,
                )
            except Exception as create_error:
                validation_errors = self._validation_errors_from_exception(create_error)
                if "initial_route_matrix_requires_grounded_amap_anchors" in validation_errors:
                    candidate_refresh_report = copy.deepcopy(grounding_report)
                    candidate_refresh_report["providerValidationErrors"] = validation_errors
                    candidate_refresh_report["candidateRefreshReason"] = (
                        "initial_route_matrix_requires_grounded_amap_anchors"
                    )
                    candidate_refresh_report["routeStatus"] = "waiting_for_poi_grounding"
                    candidate_refresh_report["resultState"] = "candidate_refresh_required"
                    self._emit_execution_event(
                        event_sink,
                        session_id=session_id,
                        turn_id=assistant_turn_id,
                        event_type="timeline",
                        label="生成可见时间轴",
                        detail="地点尚未完成高德身份绑定，本轮保持零写入并等待候选刷新。",
                        status="fallback",
                        failure_reason="initial_route_matrix_requires_grounded_amap_anchors",
                    )
                    return self._uncreated_staged_pipeline_response(
                        session_id,
                        user_turn_id,
                        assistant_turn_id,
                        content,
                        request_context,
                        session_before,
                        tool_events,
                        "candidate_refresh_required",
                        candidate_refresh_report,
                    )
                raise RuntimeError(
                    f"INITIAL_ITINERARY_CREATE_FAILED: {self._error_message(create_error)}"
                ) from create_error
            created_version_id = result.version.id
            if request_context.get("serverExecutionProfile") == "simple_open_v1":
                patch_metadata = result.patch.metadata if isinstance(result.patch.metadata, dict) else {}
                simple_open_route_status = str(patch_metadata.get("simpleOpenRouteStatus") or "unknown")
                simple_open_route_write_delta = int(patch_metadata.get("routeWriteDelta") or 0)
                if simple_open_route_status in {"ready", "partial", "provider_failed", "unknown"}:
                    # This flag is derived from the canonical writer response,
                    # never from client context.  It lets the verifier keep
                    # route proof non-blocking only for an authorized write.
                    pipeline_context["simpleOpenRoutePolicyAuthorized"] = True
                self._append_pipeline_event(
                    tool_events,
                    "simple_open_routes_attempted",
                    "记录路线状态",
                    "completed" if simple_open_route_status == "ready" else "fallback",
                    "已在 canonical write 内尝试相邻路线；失败或缺口不会回滚可用行程。",
                    {
                        "routeStatus": simple_open_route_status,
                        "routeWriteDelta": simple_open_route_write_delta,
                    },
                )
                self._append_pipeline_event(
                    tool_events,
                    "simple_open_persist_completed",
                    "完成简单行程持久化",
                    "completed",
                    "canonical writer 已返回一个 patch 和一个 result version。",
                    {
                        "patchId": result.patch.id,
                        "resultVersionId": result.version.id,
                        "writeCount": 1,
                    },
                )
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=assistant_turn_id,
                event_type="timeline",
                label="生成可见时间轴",
                detail="已保存可在时间轴与地图中查看的行程版本。",
                status="completed",
            )
            self._append_pipeline_event(
                tool_events,
                "create_itinerary_version",
                "创建 itinerary version",
                "completed",
                "已通过服务端 pipeline 创建新的 itinerary snapshot；未调用 patch_itinerary 工具。",
                {"activeVersionId": result.version.id, "patchId": result.patch.id, "baseVersionId": base_version_id},
            )
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=assistant_turn_id,
                event_type="verifier",
                label="校验最终时间轴",
                detail="正在核对地点身份、日期、版本谱系和路线安全边界。",
            )
            verifier_report = AgentVerifierService(self.db).verify_agent_write(
                session_before["id"],
                session_before["active_plan_id"],
                result.version.id,
                result.patch.id,
                planning_context=pipeline_context,
            )
            if not verifier_report.passed:
                self._mark_tool_loop_patch_rolled_back(
                    assistant_turn_id, result.version.id, verifier_report.hard_failures
                )
                self._restore_previous_active_state(session_before)
                self._restore_preference_memory(preference_memory_before)
                failure_reason = "Agent basic verifier rejected staged itinerary write"
                self._append_pipeline_event(
                    tool_events,
                    "basic_verifier",
                    "运行本地 basic verifier",
                    "failed",
                    "; ".join(verifier_report.hard_failures) or failure_reason,
                    verifier_report.as_metadata(),
                    failure_reason=failure_reason,
                )
                return self._failed_staged_pipeline_response(
                    session_id,
                    user_turn_id,
                    assistant_turn_id,
                    content,
                    request_context,
                    session_before,
                    tool_events,
                    failure_reason,
                    verifier_report,
                )
            self._append_pipeline_event(
                tool_events,
                "basic_verifier",
                "运行本地 basic verifier",
                "completed",
                "已完成本地基础校验：天数/日期、交通偏好、重复 POI、过密日程和预约风险。",
                verifier_report.as_metadata(),
            )
            if request_context.get("serverExecutionProfile") == "simple_open_v1":
                map_report = AgentVerifierService(self.db).verify_map_readiness(
                    session_before["active_plan_id"],
                    "simple_open_initial",
                )
                enrichment_report = self.simple_open_itinerary_executor.enrichment_report(
                    route_status=simple_open_route_status,
                    route_write_delta=simple_open_route_write_delta,
                    active_version_id=result.version.id,
                    map_verifier=map_report.as_metadata(),
                    map_ready=map_report.passed,
                )
                final_version = result.version
            elif pipeline_context.get("portfolioPartialTimeline"):
                # A partial timeline is already map-visible from its grounded
                # POIs. Do not create a second enrichment version or routes for
                # gaps that still require user confirmation.
                map_report = AgentVerifierService(self.db).verify_map_readiness(
                    session_before["active_plan_id"],
                    "partial_timeline",
                )
                partial_deadline_exceeded = self._staged_deadline_exceeded()
                enrichment_report = {
                    "state": "partial_success",
                    "mapReady": map_report.passed,
                    "routeReady": False,
                    "routeStatus": ("deadline_exceeded" if partial_deadline_exceeded else "pending_slot_confirmation"),
                    "routeWriteDelta": 0,
                    "deadlineExceeded": partial_deadline_exceeded,
                    "deadlineBudgetMs": STAGED_PIPELINE_TOTAL_DEADLINE_SECONDS * 1000,
                    "partialGrounding": True,
                    "unresolvedSlots": copy.deepcopy(pipeline_context.get("portfolioPendingSlots") or []),
                    "mapVerifier": map_report.as_metadata(),
                    "activeVersionId": result.version.id,
                    "warnings": ["未补齐时段已保留为空档；确认候选后再刷新受影响路线。"],
                }
                final_version = result.version
                self._append_pipeline_event(
                    tool_events,
                    "deterministic_enrichment",
                    "保留可见部分时间轴",
                    "fallback",
                    "已保留真实地图锚点和待补空槽；确认前不创建额外版本或路线写入。",
                    enrichment_report,
                )
            elif self._staged_deadline_exceeded():
                enrichment_report = self._deadline_safe_enrichment_report(result.version.id, tool_events)
                final_version = result.version
                self._append_pipeline_event(
                    tool_events,
                    "deterministic_enrichment",
                    "执行确定性 enrichment",
                    "fallback",
                    "总 deadline 已到；保留已通过 basic verifier 的安全可编辑版本，路线与可选核验待后续刷新。",
                    enrichment_report,
                    failure_reason="staged_pipeline_deadline_exceeded",
                )
            else:
                enrichment_report, final_version = self._run_staged_enrichment(
                    session_before,
                    result.version.id,
                    result.patch.id,
                    assistant_turn_id,
                    pipeline_context,
                    request_context,
                    tool_events,
                )
            # The transaction is not publishable until the exact persisted
            # result version passes the same strict verifier used by runtime
            # artifact/export.  The earlier basic verifier may intentionally
            # understand provisional planning context; it cannot authorize an
            # active version that the final snapshot verifier hard-rejects.
            decision_state = (
                pipeline_context.get("agentDecisionState")
                if isinstance(pipeline_context.get("agentDecisionState"), dict)
                else {}
            )
            intent_contract = (
                pipeline_context.get("requestIntentContract")
                if isinstance(pipeline_context.get("requestIntentContract"), dict)
                else {}
            )
            hard_required_intents = [
                item
                for item in intent_contract.get("requiredIntents") or []
                if isinstance(item, dict)
                and item.get("requirementLevel") not in {"soft_experience", "optional"}
                and int(item.get("requiredMin") or 0) > 0
            ]
            grounding_report = (
                pipeline_context.get("candidateFirstGrounding")
                if isinstance(pipeline_context.get("candidateFirstGrounding"), dict)
                else {}
            )
            final_verifier_context = (
                pipeline_context
                if decision_state.get("source") == "controller"
                and decision_state.get("accepted") is True
                and decision_state.get("primaryAction") == "draft_itinerary"
                and hard_required_intents
                and not self._semantic_candidate_hint_shortage(grounding_report)
                else None
            )
            verifier_report = AgentVerifierService(self.db).verify_agent_write(
                session_before["id"],
                session_before["active_plan_id"],
                final_version.id,
                result.patch.id,
                planning_context=final_verifier_context,
            )
            pending_hard_checks = [
                check
                for check in verifier_report.checks
                if check.get("name") == "hard_requirement_coverage" and check.get("status") == "pending"
            ]
            grounding_quality = (
                grounding_report.get("qualityContract")
                if isinstance(grounding_report.get("qualityContract"), dict)
                else {}
            )
            grounding_hard_failures = [
                str(item)
                for item in grounding_quality.get("hardFailures") or []
                if str(item) in {"no_minimum_viable_day"}
            ]
            if not pipeline_context.get("portfolioPartialTimeline") and (
                pending_hard_checks or grounding_hard_failures
            ):
                verifier_report = AgentVerifierReport(
                    passed=False,
                    hard_failures=[
                        *verifier_report.hard_failures,
                        *grounding_hard_failures,
                        *(
                            ["hard_requirement_coverage: pending hard requirements cannot publish an active version"]
                            if pending_hard_checks
                            else []
                        ),
                    ],
                    soft_failures=verifier_report.soft_failures,
                    checks=verifier_report.checks,
                    metadata={
                        **verifier_report.metadata,
                        "activeVersionPublicationBlocked": True,
                        "pendingHardRequirementChecks": pending_hard_checks,
                        "groundingHardFailures": grounding_hard_failures,
                    },
                )
            if not verifier_report.passed:
                self._mark_tool_loop_patch_rolled_back(
                    assistant_turn_id, final_version.id, verifier_report.hard_failures
                )
                self._restore_previous_active_state(session_before)
                self._restore_preference_memory(preference_memory_before)
                failure_reason = "Agent final verifier rejected staged itinerary write"
                self._append_pipeline_event(
                    tool_events,
                    "final_transaction_verifier",
                    "校验最终持久化快照",
                    "failed",
                    "; ".join(verifier_report.hard_failures) or failure_reason,
                    verifier_report.as_metadata(),
                    failure_reason=failure_reason,
                )
                return self._failed_staged_pipeline_response(
                    session_id,
                    user_turn_id,
                    assistant_turn_id,
                    content,
                    request_context,
                    session_before,
                    tool_events,
                    failure_reason,
                    verifier_report,
                )
            self._append_pipeline_event(
                tool_events,
                "final_transaction_verifier",
                "校验最终持久化快照",
                "completed",
                "最终持久化快照、patch lineage 与 active version 已通过同一严格校验。",
                verifier_report.as_metadata(),
            )
        except Exception as error:
            committed_partial = self._committed_partial_session_after_failure(
                session_id=session_id,
                session_before=session_before,
            )
            if committed_partial is None:
                if "created_version_id" in locals() and created_version_id:
                    self._mark_tool_loop_patch_rolled_back(
                        assistant_turn_id, created_version_id, [self._error_message(error)]
                    )
                self._restore_previous_active_state(session_before)
                self._restore_preference_memory(preference_memory_before)
                verifier_report = self._safe_verify_active_version_unchanged(
                    session_before,
                    "agent_staged_pipeline_failed",
                )
            else:
                verifier_report = AgentVerifierReport(
                    passed=True,
                    metadata={
                        "degradedVisibleResponse": True,
                        "activeVersionId": committed_partial["active_version_id"],
                        "failureClass": "post_commit_response_projection",
                    },
                )
            failure_reason = self._error_message(error)
            self._append_pipeline_event(
                tool_events,
                "staged_pipeline_failed",
                "分阶段规划失败",
                "failed",
                failure_reason,
                {"error": failure_reason},
                failure_reason=failure_reason,
            )
            return self._failed_staged_pipeline_response(
                session_id,
                user_turn_id,
                assistant_turn_id,
                content,
                request_context,
                session_before,
                tool_events,
                failure_reason,
                verifier_report,
            )

        warning_items = self._pipeline_warnings(
            pipeline_context, verifier_report, initial_plan.warnings, enrichment_report
        )
        self._append_pipeline_event(
            tool_events,
            "agent_action_outcome",
            "记录自治动作结果",
            "completed" if verifier_report.passed else "failed",
            "已从持久化 version 和 verifier 读取本 cycle 的真实结果。",
            {
                "cycleIndex": 0,
                "decisionId": (request_context.get("agentDecision") or {}).get("decisionId"),
                "action": (request_context.get("agentDecision") or {}).get("primaryAction"),
                "executionRoute": execution_route,
                "baseVersionId": base_version_id,
                "coreDraftVersionId": result.version.id,
                "finalEnrichmentVersionId": final_version.id,
                "activeVersionId": final_version.id,
                "resultVersionIds": list(dict.fromkeys([result.version.id, final_version.id])),
                "patchId": result.patch.id,
                "patchIds": [result.patch.id],
                "sourceStage": execution_route,
                "verifierPassed": verifier_report.passed,
                "rollbackPerformed": False,
            },
        )
        hard_constraint_choices = self._hard_constraint_relaxation_choices(pipeline_context, enrichment_report)
        if hard_constraint_choices:
            warning_items = list(
                dict.fromkeys(
                    [*warning_items, "985 高校硬约束尚未满足；未静默放宽，请选择减少数量、放宽层级或手动填写学校。"]
                )
            )
        current_itinerary = ItineraryService(self.db).get_plan(session_before["active_plan_id"])
        if request_context.get("serverExecutionProfile") == "simple_open_v1":
            active_after_write = self._session(session_id)
            persisted_row = self.db.execute(
                "SELECT snapshot_json FROM itinerary_versions WHERE id = ? AND session_id = ?",
                (final_version.id, session_id),
            ).fetchone()
            try:
                persisted_snapshot = json.loads(str(persisted_row["snapshot_json"] or "{}"))
                reload_mismatches = (
                    self.simple_open_itinerary_executor.persisted_reload_mismatches(
                        expected_version_id=final_version.id,
                        active_version_id=str(active_after_write["active_version_id"] or "") or None,
                        persisted_snapshot=persisted_snapshot,
                        live_snapshot=current_itinerary.model_dump(mode="json", by_alias=True),
                    )
                    if persisted_row is not None
                    else ["persistedSnapshot"]
                )
                reload_matches = not reload_mismatches
            except (TypeError, ValueError, json.JSONDecodeError):
                reload_mismatches = ["persistedSnapshot"]
                reload_matches = False
            if not reload_matches:
                failure_reason = "simple_open_persisted_reload_mismatch"
                self._mark_tool_loop_patch_rolled_back(assistant_turn_id, final_version.id, [failure_reason])
                self._restore_previous_active_state(session_before)
                self._restore_preference_memory(preference_memory_before)
                self._append_pipeline_event(
                    tool_events,
                    "simple_open_persist_reloaded",
                    "重读持久化结果",
                    "failed",
                    "active version 或 persisted snapshot 与正式写入结果不一致，已回滚。",
                    {
                        "activeVersionId": None,
                        "verifierPassed": False,
                        "mismatchKeys": reload_mismatches,
                    },
                    failure_reason=failure_reason,
                )
                return self._failed_staged_pipeline_response(
                    session_id,
                    user_turn_id,
                    assistant_turn_id,
                    content,
                    request_context,
                    session_before,
                    tool_events,
                    failure_reason,
                    verifier_report,
                )
        reply = self._staged_pipeline_reply(
            initial_plan.reply, final_version.id, warning_items, enrichment_report, pipeline_context
        )
        post_context = {
            **request_context,
            "activeVersionId": final_version.id,
            "currentItinerarySnapshot": current_itinerary.model_dump(by_alias=True),
            "autonomyVersionsCreated": list(dict.fromkeys([result.version.id, final_version.id])),
        }
        post_observation = self.autonomy_observation_builder.build(
            post_context,
            cycle_index=1,
            last_action={"action": "draft_itinerary", "executionRoute": execution_route},
            last_outcome={"verifierPassed": verifier_report.passed, "resultVersionId": final_version.id},
        )
        tool_events.append(
            self._autonomy_observation_pipeline_event(
                post_context, observation=post_observation.model_dump(by_alias=True)
            )
        )
        autonomy_choice_options = self._autonomy_unresolved_choice_options(session_id, post_observation)
        final_cycle_index = post_observation.cycle_index
        executed_followup_outcome: Optional[AgentActionOutcome] = None
        followup_decision: Optional[dict[str, Any]] = None
        initial_decision = (
            request_context.get("agentDecision") if isinstance(request_context.get("agentDecision"), dict) else {}
        )
        if (
            initial_decision.get("schemaVersion") == "agent-decision-v2"
            and self._provider_has_autonomy_decision()
            and not request_context.get("skipPostObservationController")
        ):
            post_context["agentObservation"] = post_observation.model_dump(by_alias=True)
            followup_result = self.autonomy_controller.decide(
                str(post_context.get("effectiveUserMessage") or post_context.get("latestUserMessage") or ""),
                post_context,
                self.autonomy_context_projector.project(post_context),
                available_tools={
                    "read_itinerary",
                    "resolve_poi",
                    "optimize_route",
                    "patch_itinerary",
                    "web_search",
                    "amap_weather",
                    "ticket_lookup",
                },
                runtime_budget_tools={
                    "read_itinerary",
                    "resolve_poi",
                    "optimize_route",
                    "patch_itinerary",
                    "web_search",
                    "amap_weather",
                    "ticket_lookup",
                },
                observation=post_observation,
            )
            followup_decision = followup_result.to_event_metadata()
            followup_decision["observationFingerprint"] = post_observation.state_fingerprint
            followup_decision["postObservationDecision"] = True
        elif autonomy_choice_options and not request_context.get("rootCoordinatorManaged"):
            followup_decision = {
                "source": "deterministic_arbitrator",
                "controlOwner": "safe_fallback",
                "primaryAction": "ask_user",
                "decisionId": f"{initial_decision.get('decisionId')}:cycle1",
                "decisionSummary": "仍有必需地点未完成，需要用户选择下一步。",
                "effectiveWriteRisk": "none",
                "effectiveTools": [],
                "accepted": True,
                "stopCondition": {"type": "needs_confirmation"},
                "postObservationDecision": True,
            }
        if followup_decision is not None:
            tool_events.append(
                self._autonomy_decision_pipeline_event(
                    post_context,
                    decision=followup_decision,
                    observation=post_observation.model_dump(by_alias=True),
                )
            )
        if (
            followup_decision is not None
            and followup_decision.get("accepted") is True
            and followup_decision.get("primaryAction") == "resolve_poi"
        ):
            resolve_outcome = self._execute_post_observation_resolve_poi(
                session_id=session_id,
                turn_id=assistant_turn_id,
                city=str(session_before["city"]),
                decision=followup_decision,
            )
            self._append_pipeline_event(
                tool_events,
                "agent_action_outcome",
                "执行地点候选收集",
                "completed" if resolve_outcome.status in {"success", "partial", "needs_confirmation"} else "failed",
                "已按模型 directive 调用 POI executor，并仅持久化安全候选或真实解析结果。",
                {"cycleIndex": 1, **resolve_outcome.to_context()},
            )
            post_context["pendingAmapPoiCandidates"] = [
                item.model_dump(by_alias=True) for item in ConversationService(self.db)._pending_candidates(session_id)
            ]
            post_context["runtimeLimits"] = {
                **dict(post_context.get("runtimeLimits") or {}),
                "remainingCycles": 1,
            }
            post_observation = self.autonomy_observation_builder.build(
                post_context,
                cycle_index=2,
                last_action={"action": "resolve_poi", "executionRoute": "poi_grounding"},
                last_outcome=resolve_outcome.to_context(),
            )
            tool_events.append(
                self._autonomy_observation_pipeline_event(
                    post_context,
                    observation=post_observation.model_dump(by_alias=True),
                )
            )
            post_context["agentObservation"] = post_observation.model_dump(by_alias=True)
            cycle2_result = self.autonomy_controller.decide(
                str(post_context.get("effectiveUserMessage") or post_context.get("latestUserMessage") or ""),
                post_context,
                self.autonomy_context_projector.project(post_context),
                available_tools={
                    "read_itinerary",
                    "resolve_poi",
                    "optimize_route",
                    "patch_itinerary",
                    "web_search",
                    "amap_weather",
                    "ticket_lookup",
                },
                runtime_budget_tools={
                    "read_itinerary",
                    "resolve_poi",
                    "optimize_route",
                    "patch_itinerary",
                    "web_search",
                    "amap_weather",
                    "ticket_lookup",
                },
                observation=post_observation,
            )
            followup_decision = cycle2_result.to_event_metadata()
            followup_decision["observationFingerprint"] = post_observation.state_fingerprint
            followup_decision["postObservationDecision"] = True
            if followup_decision.get("accepted") is True and followup_decision.get("primaryAction") in {
                "resolve_poi",
                "optimize_route",
                "verify_external_facts",
            }:
                followup_decision["accepted"] = False
                followup_decision["effectiveTools"] = []
                followup_decision["actualExecutionRoute"] = "no_safe_action"
                followup_decision["executionOverride"] = True
                followup_decision["executionOverrideReason"] = "action_not_executable_within_cycle_budget"
                followup_decision["policyReasonCodes"] = [
                    *list(followup_decision.get("policyReasonCodes") or []),
                    "action_not_executable_within_cycle_budget",
                ]
            tool_events.append(
                self._autonomy_decision_pipeline_event(
                    post_context,
                    decision=followup_decision,
                    observation=post_observation.model_dump(by_alias=True),
                )
            )
            autonomy_choice_options = self._autonomy_unresolved_choice_options(session_id, post_observation)
            final_cycle_index = post_observation.cycle_index
            if (
                followup_decision.get("accepted") is True
                and followup_decision.get("primaryAction") == "patch_itinerary"
            ):
                patch_outcome, patch_result, patch_verifier_report = self._execute_post_observation_candidate_patch(
                    session_id=session_id,
                    turn_id=assistant_turn_id,
                    decision=followup_decision,
                    request_context=post_context,
                )
                executed_followup_outcome = patch_outcome
                self._append_pipeline_event(
                    tool_events,
                    "timeline_edit",
                    "执行候选地点写入",
                    "completed" if patch_outcome.status == "success" else "failed",
                    "候选身份已从持久化记录原子校验后写入。"
                    if patch_outcome.status == "success"
                    else "候选地点写入未通过，当前版本保持不变。",
                    {
                        "cycleIndex": 2,
                        "decisionId": followup_decision.get("decisionId"),
                        **patch_outcome.to_context(),
                        "verifierPassed": bool(patch_verifier_report and patch_verifier_report.passed),
                    },
                    failure_reason=(
                        patch_outcome.candidate_summary.get("failureReason")
                        if patch_outcome.status != "success"
                        else None
                    ),
                )
                self._append_pipeline_event(
                    tool_events,
                    "agent_action_outcome",
                    "记录自治动作结果",
                    "completed" if patch_outcome.status == "success" else "failed",
                    "已执行 Controller 在 cycle 2 接受的 patch_itinerary，并记录真实 version、patch 与 verifier 结果。",
                    {
                        "cycleIndex": 2,
                        "decisionId": followup_decision.get("decisionId"),
                        **patch_outcome.to_context(),
                        "verifierPassed": bool(patch_verifier_report and patch_verifier_report.passed),
                    },
                    failure_reason=(
                        patch_outcome.candidate_summary.get("failureReason")
                        if patch_outcome.status != "success"
                        else None
                    ),
                )
                if patch_result is not None and patch_verifier_report is not None:
                    final_version = patch_result.version
                    current_itinerary = patch_result.itinerary
                    verifier_report = patch_verifier_report
                    post_context["activeVersionId"] = final_version.id
                    post_context["currentItinerarySnapshot"] = current_itinerary.model_dump(by_alias=True)
                    post_context["autonomyVersionsCreated"] = [
                        *list(post_context.get("autonomyVersionsCreated") or []),
                        final_version.id,
                    ]
                    post_context["pendingAmapPoiCandidates"] = [
                        item.model_dump(by_alias=True)
                        for item in ConversationService(self.db)._pending_candidates(session_id)
                    ]
                    reply = f"{reply}\n\n已将模型选定且通过持久化身份校验的地点写入时间轴。"
                post_observation = self.autonomy_observation_builder.build(
                    post_context,
                    cycle_index=3,
                    last_action={"action": "patch_itinerary", "executionRoute": "timeline_mutation_executor"},
                    last_outcome=patch_outcome.to_context(),
                )
                tool_events.append(
                    self._autonomy_observation_pipeline_event(
                        post_context,
                        observation=post_observation.model_dump(by_alias=True),
                    )
                )
                autonomy_choice_options = self._autonomy_unresolved_choice_options(session_id, post_observation)
                final_cycle_index = post_observation.cycle_index
        required_unresolved_slots = [slot for slot in post_observation.unresolved_slots if slot.required]
        optional_unresolved_slots = [slot for slot in post_observation.unresolved_slots if not slot.required]
        if autonomy_choice_options:
            reply = f"{reply}\n\n仍有 {len(required_unresolved_slots)} 个必需地点待补全，请选择重试或手动填写。"
        elif required_unresolved_slots:
            reply = (
                f"{reply}\n\n草案状态：draft_pending_grounding；仍有 "
                f"{len(required_unresolved_slots)} 个必需地点待补全。"
            )
        elif optional_unresolved_slots:
            if reply.startswith("已完成："):
                reply = reply.replace("已完成：", "已排入草案：", 1)
            reply = (
                f"{reply}\n\n草案状态：draft_pending_grounding；仍有 "
                f"{len(optional_unresolved_slots)} 个可选餐饮地点待补全，"
                f"不阻断当前 {len(resolved_dates.get('dates') or [])} 日草案。"
            )
        if request_context.get("serverExecutionProfile") == "simple_open_v1":
            simple_open_result_class = self.simple_open_itinerary_executor.classify_result(
                pipeline_context, simple_open_route_status
            )
            terminal_status = {
                "READY": "ready",
                "PARTIAL": "partial_success",
                "FAILED": "failed",
            }[simple_open_result_class]
        else:
            terminal_status = (
                "needs_confirmation"
                if autonomy_choice_options
                else "draft_pending_grounding"
                if required_unresolved_slots or optional_unresolved_slots
                else "partial_success"
            )
        stop_decision = self.autonomy_stop_policy.evaluate(
            post_observation,
            cycle_index=final_cycle_index,
            max_cycles=3,
            previous_fingerprint=str(
                (request_context.get("agentDecisionState") or {}).get("observationFingerprint") or ""
            )
            or None,
            action_signature=(
                f"{followup_decision.get('primaryAction')}:{json.dumps(followup_decision.get('targetScope') or {}, sort_keys=True)}"
                if followup_decision is not None
                else None
            ),
            previous_action_signature=(
                f"{initial_decision.get('primaryAction')}:{json.dumps(initial_decision.get('targetScope') or {}, sort_keys=True)}"
                if initial_decision
                else None
            ),
            verifier_passed=verifier_report.passed,
        )
        if request_context.get("serverExecutionProfile") == "simple_open_v1":
            stop_reason = "simple_open_terminal"
        elif stop_decision.should_stop:
            stop_reason = stop_decision.reason or "hard_stop"
        elif executed_followup_outcome is not None:
            stop_reason = "action_completed" if executed_followup_outcome.status == "success" else "action_no_change"
        elif followup_decision is not None and followup_decision.get("accepted") is True:
            stop_reason = {
                "finish": "model_finish",
                "ask_user": "needs_confirmation",
            }.get(str(followup_decision.get("primaryAction") or ""), "next_action_not_executed")
        else:
            stop_reason = "no_safe_action"
        self._append_pipeline_event(
            tool_events,
            "agent_stop",
            "自治循环停止",
            "completed",
            "已完成 action 后的真实状态观察，并根据 verifier、未完成项和路线状态停止。",
            {
                "cycleIndex": final_cycle_index,
                "stopReason": stop_reason,
                "observationFingerprint": post_observation.state_fingerprint,
            },
        )
        if request_context.get("serverExecutionProfile") == "simple_open_v1":
            simple_open_result_class = self.simple_open_itinerary_executor.classify_result(
                pipeline_context, simple_open_route_status
            )
            for spec in self.simple_open_itinerary_executor.terminal_event_specs(
                result_class=simple_open_result_class,
                active_version_id=final_version.id,
                route_status=simple_open_route_status,
                verifier_passed=verifier_report.passed,
            ):
                self._append_pipeline_event(
                    tool_events,
                    spec["eventId"],
                    spec["label"],
                    "completed",
                    spec["detail"],
                    spec["preview"],
                )
        planning_events = self._planning_events_from_staged_events(
            tool_events,
            session_id=session_id,
            assistant_turn_id=assistant_turn_id,
            failed=False,
        )
        self.db.execute(
            """
            UPDATE conversation_turns
            SET content = ?, status = 'active', itinerary_version_id = ?, agent_response_json = ?,
                error_json = NULL, updated_at = ?
            WHERE id = ?
            """,
            (
                reply,
                final_version.id,
                json.dumps(
                    {
                        "mode": execution_route,
                        "reply": reply,
                        "resolvedTripDates": resolved_dates,
                        "enrichment": enrichment_report,
                        "resultState": enrichment_report.get("state"),
                        "warnings": warning_items,
                        "choiceOptions": [*hard_constraint_choices, *autonomy_choice_options],
                        "terminalStatus": terminal_status,
                        "planningSteps": self._serialize_planning_events(planning_events),
                        "toolEvents": self._serialize_planning_events(planning_events),
                    },
                    ensure_ascii=False,
                    default=str,
                ),
                datetime.now(timezone.utc).isoformat(),
                assistant_turn_id,
            ),
        )
        self.db.execute(
            """
            UPDATE conversation_turns
            SET itinerary_version_id = ?, updated_at = ?
            WHERE id = ?
            """,
            (final_version.id, datetime.now(timezone.utc).isoformat(), user_turn_id),
        )
        planning_run = PlanningRunService(self.db).create_run(
            "agent_staged_pipeline",
            user_input=content,
            preference_summary=self._preference_summary_from_context(request_context),
            itinerary=current_itinerary,
            itinerary_version_id=final_version.id,
            understood_requirements=request_context.get("understoodRequirements"),
            final_summary=reply,
            tool_calls_override=self._planning_tool_calls_from_tool_events(tool_events),
        )
        self._attach_planning_run_for_result_version(assistant_turn_id, final_version.id, planning_run.id)
        if not self._controller_manages_memory(request_context) and not request_context.get("syntheticAgentChoice"):
            self._auto_update_preference_memory(session_id, content, reply)
        self.db.commit()
        if planning_events:
            self._store_planning_events(assistant_turn_id, planning_events)
            self.db.commit()
        return AgentMessageResponse(
            userTurn=self._turn_response(user_turn_id),
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=ItineraryService(self.db).get_plan(session_before["active_plan_id"]),
            version=final_version,
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=warning_items,
            planningRun=planning_run,
            planningSteps=planning_events,
            toolEvents=planning_events,
            terminalStatus=terminal_status,
        )

    def _autonomy_unresolved_choice_options(self, session_id: str, observation) -> list[dict[str, Any]]:
        """Expose persisted candidate identities before retry/manual fallbacks.

        Choices only use candidate rows still pending for the unresolved segment.
        Rejected candidates and provider/debug prose never become clickable POIs.
        """
        pending = ConversationService(self.db)._pending_candidates(session_id)
        blocking_slots = [slot for slot in observation.unresolved_slots if getattr(slot, "required", True)]
        unresolved_segment_ids = {slot.segment_id for slot in blocking_slots if slot.segment_id}
        options: list[dict[str, Any]] = []
        for group in pending:
            if group.source_segment_id not in unresolved_segment_ids:
                continue
            for candidate in group.candidates:
                if not isinstance(candidate, dict):
                    continue
                try:
                    poi = MapPoiResponse.model_validate(candidate)
                except ValidationError:
                    continue
                if len(options) >= 3:
                    break
                options.append(
                    {
                        "id": f"candidate:{group.id}:{poi.id}",
                        "kind": "poi_candidate",
                        "label": poi.name,
                        "candidateRecordId": group.id,
                        "selectionGroupId": group.id,
                        "segmentId": group.source_segment_id,
                        "amapId": poi.id,
                        "amapPoi": poi.model_dump(by_alias=True),
                        "allowsManualInput": False,
                    }
                )
        if not options:
            try:
                active_version_id = self._session(session_id)["active_version_id"]
            except (HTTPException, sqlite3.OperationalError):
                active_version_id = None
            for slot in blocking_slots[:3]:
                options.append(
                    {
                        "id": f"retry:{slot.slot_id}",
                        "kind": "retry_unresolved_slot",
                        "label": f"重试补全第 {slot.day_number or ''} 天 {slot.time_window or '未完成地点'}",
                        "value": f"继续补全 {slot.slot_id}",
                        "slotId": slot.slot_id,
                        "segmentId": slot.segment_id,
                        "dayNumber": slot.day_number,
                        "timeWindow": slot.time_window,
                        "reason": slot.reason,
                        "activeVersionId": active_version_id,
                        "allowsManualInput": False,
                    }
                )
        if options:
            options.append(
                {
                    "id": "manual",
                    "kind": "custom_input",
                    "label": "我自己填写",
                    "value": "我自己填写",
                    "allowsManualInput": True,
                }
            )
        return options[:4]

    def _retry_tool_loop_after_missing_itinerary_write(
        self,
        result: AgentToolLoopResult,
        tool_events: list[dict],
        session_id: str,
        assistant_turn_id: str,
        request_context: dict,
        preference_memory_before,
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> tuple[AgentToolLoopResult, list[dict], bool]:
        retry_context = self._missing_write_retry_context(request_context, tool_events)
        retry_marker = self._tool_loop_retry_event(
            assistant_turn_id,
            "missing_itinerary_write_retry",
            "补写时间轴重试",
            "completed",
            "Agent 首次只返回文字，未写入时间轴；已带着明确写入要求重试一次。",
        )
        self._clear_tool_loop_poi_candidate_side_effects_for_turn(assistant_turn_id)
        self._restore_preference_memory(preference_memory_before)
        retry_session_before = self._session(session_id)
        retry_run_context = AgentRunContext(
            session=retry_session_before,
            request_context=retry_context,
            source_turn_id=assistant_turn_id,
            active_version_id=retry_session_before["active_version_id"],
            preference_memory=preference_memory_before,
        )
        retry_provider_context = retry_run_context.provider_context()
        retry_registry = TravelToolRegistry(
            self.db,
            retry_session_before,
            retry_provider_context,
            source_turn_id=assistant_turn_id,
            event_sink=lambda event: self._emit_tool_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=assistant_turn_id,
                event=event,
            ),
        )
        try:
            retry_result = self.provider.run_tool_loop(retry_provider_context, retry_registry)
        except Exception as error:
            retry_session_failed = self._session(session_id)
            retry_failed_version_id = retry_session_failed["active_version_id"]
            if retry_failed_version_id and retry_failed_version_id != retry_session_before["active_version_id"]:
                self._mark_tool_loop_patch_rolled_back(
                    assistant_turn_id,
                    retry_failed_version_id,
                    [f"missing write retry failed before verification: {self._error_message(error)}"],
                )
            self._rollback_tool_loop_writes(retry_session_before)
            self._clear_tool_loop_poi_candidate_side_effects_for_turn(assistant_turn_id)
            self._restore_preference_memory(preference_memory_before)
            failed_marker = self._tool_loop_retry_event(
                assistant_turn_id,
                "missing_itinerary_write_retry",
                "补写时间轴重试",
                "failed",
                f"补写时间轴重试失败：{self._error_message(error)}",
                failure_reason=self._error_message(error),
            )
            return result, [*tool_events, retry_marker, *retry_registry.events, failed_marker], False

        combined_events = [*tool_events, retry_marker, *retry_result.tool_events]
        retry_result.tool_events = combined_events
        retry_succeeded = self._latest_accepted_result_version_for_turn(assistant_turn_id) is not None
        return retry_result, combined_events, retry_succeeded

    def _missing_write_retry_context(self, request_context: dict, tool_events: list[dict]) -> dict:
        retry_context = self._timeline_write_required_context(request_context)
        retry_context["missingItineraryWriteFeedback"] = {
            "attempt": 1,
            "reason": "The previous tool-loop response ended with text but did not call patch_itinerary, so no timeline version was written.",
            "instructions": [
                "This user request requires a persisted itinerary/timeline change.",
                "Call read_itinerary first to inspect the current active timeline context.",
                "Then call patch_itinerary with a valid operation, usually replace_itinerary for a new draft or a focused patch operation for an edit.",
                "If POI grounding is unavailable, do not wait for server fallback; create editable agent-text-timeline POIs with null coordinates, confidence<=0.45, and sourceNote set to a short Chinese note: 高德 POI 待校验.",
                "Do not return a final assistant reply until patch_itinerary succeeds, unless you must ask one clarification question with exactly 3 numbered options.",
            ],
            "previousToolEvents": [
                {
                    "toolName": str(item.get("toolName") or item.get("label") or ""),
                    "status": str(item.get("status") or ""),
                    "outputSummary": str(item.get("outputSummary") or item.get("detail") or "")[:240],
                }
                for item in tool_events[-6:]
            ],
        }
        return retry_context

