    def _retry_tool_loop_after_verifier_failure(
        self,
        result: AgentToolLoopResult,
        verifier_report: AgentVerifierReport,
        tool_events: list[dict],
        session_id: str,
        assistant_turn_id: str,
        request_context: dict,
        preference_memory_before,
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> tuple[AgentToolLoopResult, AgentVerifierReport, list[dict], bool]:
        retry_context = self._tool_loop_retry_context(request_context, verifier_report, tool_events)
        retry_marker = self._verifier_retry_tool_event(
            assistant_turn_id,
            "completed",
            "Verifier rejected the first tool-loop write; retrying with structured feedback.",
        )
        self._clear_tool_loop_poi_candidate_side_effects_for_turn(assistant_turn_id)
        self._restore_preference_memory(preference_memory_before)
        retry_session_before = self._session(session_id)
        retry_run_context = AgentRunContext(
            session=retry_session_before,
            request_context=retry_context,
            source_turn_id=assistant_turn_id,
            active_version_id=retry_session_before["active_version_id"],
            preference_memory=preference_memory_before,
        )
        retry_provider_context = retry_run_context.provider_context()
        retry_registry = TravelToolRegistry(
            self.db,
            retry_session_before,
            retry_provider_context,
            source_turn_id=assistant_turn_id,
            event_sink=lambda event: self._emit_tool_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=assistant_turn_id,
                event=event,
            ),
        )
        try:
            retry_result = self.provider.run_tool_loop(retry_provider_context, retry_registry)
        except Exception as error:
            retry_session_failed = self._session(session_id)
            retry_failed_version_id = retry_session_failed["active_version_id"]
            if retry_failed_version_id and retry_failed_version_id != retry_session_before["active_version_id"]:
                self._mark_tool_loop_patch_rolled_back(
                    assistant_turn_id,
                    retry_failed_version_id,
                    [f"verifier feedback retry failed before verification: {self._error_message(error)}"],
                )
            self._rollback_tool_loop_writes(retry_session_before)
            self._clear_tool_loop_poi_candidate_side_effects_for_turn(assistant_turn_id)
            self._restore_preference_memory(preference_memory_before)
            failed_marker = self._verifier_retry_tool_event(
                assistant_turn_id,
                "failed",
                f"Verifier feedback retry failed: {self._error_message(error)}",
                failure_reason=self._error_message(error),
            )
            retry_failure_report = self._retry_failure_verifier_report(verifier_report, error)
            return (
                result,
                retry_failure_report,
                [*tool_events, retry_marker, *retry_registry.events, failed_marker],
                False,
            )

        combined_events = [*tool_events, retry_marker, *retry_result.tool_events]
        retry_session_after = self._session(session_id)
        retry_report = self._verify_tool_loop_result_or_restore(
            retry_session_before,
            assistant_turn_id,
            retry_session_after["active_version_id"],
        )
        retry_result.tool_events = combined_events
        if retry_report.passed:
            return retry_result, retry_report, combined_events, True
        self._clear_tool_loop_poi_candidate_side_effects_for_turn(assistant_turn_id)
        self._restore_preference_memory(preference_memory_before)
        return retry_result, retry_report, combined_events, False

    def _tool_loop_retry_context(
        self, request_context: dict, verifier_report: AgentVerifierReport, tool_events: list[dict]
    ) -> dict:
        retry_context = dict(request_context)
        retry_context["verifierFeedback"] = {
            "attempt": 1,
            "reason": "The previous tool-loop itinerary write was rejected by the rule verifier and has been rolled back.",
            "hardFailures": verifier_report.hard_failures,
            "checks": verifier_report.checks,
            "instructions": [
                "Use read_itinerary before writing again.",
                "Do not reuse pending POI candidates as final itinerary POIs unless the user selected them.",
                "Submit a corrected patch_itinerary call or return a clarification if the request cannot be safely completed.",
            ],
            "previousToolEvents": [
                {
                    "toolName": str(item.get("toolName") or item.get("label") or ""),
                    "status": str(item.get("status") or ""),
                    "outputSummary": str(item.get("outputSummary") or item.get("detail") or "")[:240],
                }
                for item in tool_events[-6:]
            ],
        }
        return retry_context

    def _tool_loop_retry_event(
        self,
        assistant_turn_id: str,
        tool_name: str,
        label: str,
        status: str,
        detail: str,
        failure_reason: Optional[str] = None,
    ) -> dict:
        now = datetime.now(timezone.utc).isoformat()
        return {
            "id": f"{tool_name}_{uuid4().hex[:8]}",
            "toolName": tool_name,
            "type": "agent",
            "label": label,
            "status": status,
            "inputSummary": assistant_turn_id,
            "outputSummary": detail,
            "providerName": "agent-service",
            "fallbackUsed": False,
            "failureReason": failure_reason,
            "startedAt": now,
            "finishedAt": now,
            "timestamp": now,
            "detail": detail,
            "metadata": {
                "resultPreview": {
                    "status": status,
                    "detail": detail,
                    "failureReason": failure_reason,
                }
            },
        }

    def _verifier_retry_tool_event(
        self,
        assistant_turn_id: str,
        status: str,
        detail: str,
        failure_reason: Optional[str] = None,
    ) -> dict:
        return self._tool_loop_retry_event(
            assistant_turn_id,
            "verifier_feedback_retry",
            "Verifier feedback retry",
            status,
            detail,
            failure_reason=failure_reason,
        )

    def _retry_failure_verifier_report(
        self, verifier_report: AgentVerifierReport, error: Exception
    ) -> AgentVerifierReport:
        retry_failure = f"verifier feedback retry failed: {self._error_message(error)}"
        return AgentVerifierReport(
            passed=False,
            hard_failures=[*verifier_report.hard_failures, retry_failure],
            soft_failures=verifier_report.soft_failures,
            checks=[
                *verifier_report.checks,
                {
                    "name": "verifier_feedback_retry",
                    "status": "failed",
                    "failureReason": self._error_message(error),
                },
            ],
            metadata={**verifier_report.metadata, "retryFailureReason": self._error_message(error)},
        )

    def _rollback_tool_loop_writes(self, session_before: sqlite3.Row) -> None:
        current = self._session(session_before["id"])
        if current["active_version_id"] == session_before["active_version_id"]:
            return
        if session_before["active_version_id"]:
            version = self._version(
                session_before["active_version_id"], session_before["id"], session_before["active_plan_id"]
            )
            self._restore_session_to_version(current, version)
        else:
            self._restore_session_to_empty_plan(current)

    def parse_agent_output(
        self, raw_response: str, request_context: Optional[dict[str, Any]] = None
    ) -> AgentStructuredOutput:
        try:
            return self.output_parser.parse(raw_response)
        except Exception as error:
            repaired, _metadata = self.output_repair_service.repair(
                raw_response,
                error,
                "AgentStructuredOutput",
                request_context,
            )
            if repaired:
                return self.output_parser.parse(repaired)
            raise

    def normalize_agent_output(self, raw_response: str) -> dict:
        return self.output_parser.normalize(raw_response)

    def _operations_for_output(
        self, session: sqlite3.Row, output: AgentStructuredOutput
    ) -> list[ItineraryPatchOperation]:
        if output.mode == "full_itinerary":
            return [
                ItineraryPatchOperation(
                    op="replace_itinerary",
                    fullItinerary=self._snapshot_from_full_itinerary(session, output.full_itinerary),
                )
            ]
        unsupported = [operation.op for operation in output.operations if operation.op not in SUPPORTED_AGENT_PATCH_OPS]
        if unsupported:
            raise HTTPException(
                status_code=400,
                detail={
                    "code": "INVALID_PATCH_OPERATION",
                    "message": f"Unsupported Agent patch operation: {unsupported[0]}",
                    "validationErrors": [f"Unsupported Agent patch operation: {unsupported[0]}"],
                },
            )
        return output.operations

    def _operations_for_persistable_segment_plans(
        self,
        session: sqlite3.Row,
        output: AgentInitialPlanOutput,
        segment_plans: list[PersistableSegmentPlan],
        pipeline_context: dict,
    ) -> list[ItineraryPatchOperation]:
        if pipeline_context.get("portfolioPartialTimeline"):
            self._validate_partial_route_anchor_plans(segment_plans)
        snapshot = self._snapshot_from_persistable_segment_plans(
            session,
            output,
            segment_plans,
            pipeline_context,
        )
        if pipeline_context.get("portfolioPartialTimeline"):
            pending_slots = copy.deepcopy(pipeline_context.get("portfolioPendingSlots") or [])
            persisted_selection_context = (
                pipeline_context.get("portfolioSelectionContext")
                if isinstance(pipeline_context.get("portfolioSelectionContext"), dict)
                else {}
            )
            if persisted_selection_context:
                selection_context = {
                    key: str(persisted_selection_context.get(key) or "").strip()
                    for key in PortfolioPendingSlotService.CONTEXT_KEYS
                }
                if not all(selection_context.values()):
                    raise PortfolioPendingSlotError(
                        "portfolio_selection_context_missing",
                        "部分时间轴缺少已持久化的规划选择身份，本轮未写入时间轴。",
                    )
                planning_root = selection_context["planningSelectionRootTurnId"]
                root_portfolio_id = selection_context["rootPortfolioId"]
                request_contract_fingerprint = selection_context["requestContractFingerprint"]
                portfolio_row = self.db.execute(
                    """SELECT session_id, source_user_turn_id, request_contract_fingerprint
                    FROM agent_plan_portfolios WHERE id = ?""",
                    (root_portfolio_id,),
                ).fetchone()
                if (
                    portfolio_row is None
                    or str(portfolio_row["session_id"] or "") != str(session["id"] or "")
                    or str(portfolio_row["source_user_turn_id"] or "") != planning_root
                    or str(portfolio_row["request_contract_fingerprint"] or "") != request_contract_fingerprint
                ):
                    raise PortfolioPendingSlotError(
                        "portfolio_selection_root_mismatch",
                        "部分时间轴与持久化根 Portfolio 身份不一致，本轮未写入时间轴。",
                    )
                explicit_focus = str(selection_context["focusBriefId"]).strip()
                for item in pending_slots:
                    if not isinstance(item, dict):
                        continue
                    if str(item.get("briefId") or "").strip() != explicit_focus:
                        raise PortfolioPendingSlotError(
                            "portfolio_pending_slot_cross_brief",
                            "缺失槽位不属于当前冻结方案，本轮未写入时间轴。",
                        )
            else:
                # The legacy single-plan draft path predates Portfolio. A user-
                # confirmed rule-safe partial still needs a persisted root so
                # later opaque comparison choices can append verified proposals
                # without inventing identity or rerunning an unrelated plan.
                confirmed_fallback_partial = isinstance(pipeline_context.get("fallbackChoiceExecution"), dict)
                planning_root = str(
                    pipeline_context.get("planningSelectionRootTurnId")
                    or pipeline_context.get("currentUserTurnId")
                    or ""
                ).strip()
                explicit_focus = str(pipeline_context.get("portfolioGroundingFocusBriefId") or "").strip()
                fallback_focus = explicit_focus or f"partial_brief:{planning_root}"
                for item in pending_slots:
                    if not isinstance(item, dict):
                        continue
                    item["briefId"] = str(item.get("briefId") or fallback_focus)
                    item["poolId"] = str(
                        item.get("poolId")
                        or f"partial_pool:{item.get('planningSlotId') or item.get('slotId') or 'slot'}"
                    )
                request_contract = (
                    pipeline_context.get("requestIntentContract")
                    if isinstance(pipeline_context.get("requestIntentContract"), dict)
                    else {}
                )
                selection_context = {
                    "planningSelectionRootTurnId": planning_root,
                    "rootPortfolioId": f"partial:{planning_root}",
                    "focusBriefId": fallback_focus,
                    "sourceUserTurnId": str(pipeline_context.get("currentUserTurnId") or planning_root),
                    "requestContractFingerprint": hashlib.sha256(
                        json.dumps(
                            request_contract,
                            ensure_ascii=False,
                            sort_keys=True,
                            separators=(",", ":"),
                            default=str,
                        ).encode("utf-8")
                    ).hexdigest(),
                }
            pending_brief_ids = {
                str(item.get("briefId") or "").strip()
                for item in pending_slots
                if isinstance(item, dict) and str(item.get("briefId") or "").strip()
            }
            confirmed_brief_ids = {
                str(metadata.get("creativeBriefId") or "").strip()
                for day in snapshot.get("days") or []
                if isinstance(day, dict)
                for segment in day.get("segments") or []
                if isinstance(segment, dict)
                for metadata in [
                    segment.get("semanticMetadata") if isinstance(segment.get("semanticMetadata"), dict) else {}
                ]
                if str(metadata.get("creativeBriefId") or "").strip()
            }
            if explicit_focus and explicit_focus in pending_brief_ids:
                focus_brief_id = explicit_focus
            elif len(confirmed_brief_ids) == 1:
                focus_brief_id = next(iter(confirmed_brief_ids))
            else:
                focus_brief_id = sorted(pending_brief_ids)[0] if pending_brief_ids else ""
            pending_slots = [
                item
                for item in pending_slots
                if isinstance(item, dict) and str(item.get("briefId") or "").strip() == focus_brief_id
            ]
            if not focus_brief_id or not pending_slots:
                raise PortfolioPendingSlotError(
                    "portfolio_partial_focus_brief_invalid",
                    "部分时间轴缺失槽位必须属于唯一方案。",
                )
            for day in snapshot.get("days") or []:
                if not isinstance(day, dict):
                    continue
                for segment in day.get("segments") or []:
                    if not isinstance(segment, dict):
                        continue
                    metadata = (
                        segment.get("semanticMetadata") if isinstance(segment.get("semanticMetadata"), dict) else {}
                    )
                    if metadata.get("routeAnchor") is not True:
                        continue
                    existing_brief_id = str(metadata.get("creativeBriefId") or "").strip()
                    if existing_brief_id and existing_brief_id != focus_brief_id:
                        raise PortfolioPendingSlotError(
                            "portfolio_partial_anchor_scope_mismatch",
                            "部分时间轴中的真实地点不属于当前冻结方案，本轮未写入时间轴。",
                        )
                    if not existing_brief_id:
                        if persisted_selection_context:
                            raise PortfolioPendingSlotError(
                                "portfolio_partial_anchor_lineage_missing",
                                "部分时间轴中的真实地点缺少冻结方案身份，本轮未写入时间轴。",
                            )
                        # The initial single-plan/RuleSafe path creates this
                        # neutral brief identity on the server before its first
                        # write. Persisted Portfolio anchors must already carry
                        # their exact brief lineage.
                        metadata["creativeBriefId"] = focus_brief_id
                    metadata["sourceGoalId"] = str(metadata.get("sourceGoalId") or "").strip()
                    missing_lineage = [
                        key
                        for key in ("creativeBriefId", "poolId", "planningSlotId", "sourceGoalId")
                        if not str(metadata.get(key) or "").strip()
                    ]
                    if missing_lineage:
                        raise PortfolioPendingSlotError(
                            "portfolio_partial_anchor_lineage_missing",
                            "部分时间轴中的真实地点缺少完整规划谱系，本轮未写入时间轴。",
                        )
                    segment["semanticMetadata"] = metadata
            selection_context = {
                **selection_context,
                "focusBriefId": focus_brief_id,
                "sourceUserTurnId": planning_root,
            }
            if (
                not persisted_selection_context
                and confirmed_fallback_partial
                and self._creative_portfolio_enabled(pipeline_context)
            ):
                # The selection context itself is the neutral cursor. RuleSafe
                # must not construct Creative directions or Portfolio rows.
                snapshot.pop("portfolioPlanningDirections", None)
            snapshot["status"] = "partial"
            snapshot["portfolioPartialTimeline"] = {
                "status": "partial",
                "sourceProposalId": None,
                "strictProposalVerifierPassed": False,
                "pendingSlotCount": len(pending_slots),
            }
            snapshot["portfolioPendingSlots"] = pending_slots
            snapshot["portfolioSelectionContext"] = selection_context
            snapshot = PortfolioPendingSlotService.reconcile(snapshot)
            pipeline_context["portfolioSelectionContext"] = copy.deepcopy(selection_context)
            pipeline_context["portfolioPendingSlots"] = copy.deepcopy(snapshot.get("portfolioPendingSlots") or [])
            snapshot["decisionRationale"] = (
                "已先展示通过高德身份和语义校验的真实地点；未补齐时段保留为空档，待用户在对话栏确认候选后继续补全。"
            )
        return [
            ItineraryPatchOperation(
                op="replace_itinerary",
                fullItinerary=snapshot,
            )
        ]

    @staticmethod
    def _validate_partial_route_anchor_plans(
        segment_plans: list[PersistableSegmentPlan],
    ) -> None:
        """Fail closed before a partial writer can canonicalize POI payloads."""

        for plan in segment_plans:
            if not plan.route_anchor or plan.selected_poi is None:
                continue
            poi = plan.selected_poi
            if str(poi.source or "").strip() != AMAP_PLACE_SOURCE:
                raise PortfolioPendingSlotError(
                    "partial_anchor_source_invalid",
                    "部分时间轴中的地点来源未通过高德身份校验，本轮未写入时间轴。",
                )
            if not str(poi.amap_id or "").strip():
                raise PortfolioPendingSlotError(
                    "partial_anchor_amap_identity_missing",
                    "部分时间轴中的地点缺少高德身份，本轮未写入时间轴。",
                )
            try:
                longitude = float(poi.longitude)
                latitude = float(poi.latitude)
            except (TypeError, ValueError):
                longitude = latitude = float("nan")
            if not (
                math.isfinite(longitude)
                and math.isfinite(latitude)
                and -180 <= longitude <= 180
                and -90 <= latitude <= 90
                and (longitude != 0 or latitude != 0)
            ):
                raise PortfolioPendingSlotError(
                    "partial_anchor_coordinate_mismatch",
                    "部分时间轴中的地点坐标无效，本轮未写入时间轴。",
                )

    @staticmethod
    def _pending_slots_from_grounding_report(
        grounding_report: dict[str, Any],
        *,
        initial_plan: Optional[AgentInitialPlanOutput] = None,
    ) -> list[dict[str, Any]]:
        reports = [report for report in grounding_report.get("poolReports") or [] if isinstance(report, dict)]
        pending: list[dict[str, Any]] = []
        seen: set[tuple[str, str, str, int]] = set()
        covered_slot_ids = {
            str(slot_id) for report in reports for slot_id in report.get("resolvedSlotIds") or [] if str(slot_id)
        }
        planned_slots = {
            str(slot.slot_id): slot for slot in (initial_plan.day_slots if initial_plan is not None else [])
        }
        planned_pools_by_slot = {
            str(slot_id): pool
            for pool in (initial_plan.intent_pools if initial_plan is not None else [])
            for slot_id in pool.assign_to_slots
            if str(slot_id)
        }
        unresolved_rows = [
            copy.deepcopy(item) for item in grounding_report.get("unresolvedSlots") or [] if isinstance(item, dict)
        ]
        explicitly_unresolved_slot_ids = {
            str(item.get("slotId") or item.get("planningSlotId") or "")
            for item in unresolved_rows
            if str(item.get("slotId") or item.get("planningSlotId") or "")
        }
        # Grounding reports historically summarized a shared pool with only
        # one unresolved row even when multiple authoritative DaySlots remained
        # uncovered (notably ``every_allowed_day`` meals).  The DaySlot plan is
        # the cardinality truth, so project every uncovered route-anchor slot
        # back into an exact pending identity before the single writer runs.
        for slot_id, planned_slot in planned_slots.items():
            if (
                not planned_slot.route_anchor
                or slot_id in covered_slot_ids
                or slot_id in explicitly_unresolved_slot_ids
            ):
                continue
            matching_report = next(
                (
                    report
                    for report in reports
                    if slot_id
                    in {
                        str(item)
                        for item in (report.get("requiredSlotIds") or report.get("unresolvedSlotIds") or [])
                        if str(item)
                    }
                ),
                None,
            )
            planned_pool = planned_pools_by_slot.get(slot_id)
            # A hard/ordinary DaySlot needs an explicit server report before it
            # can become pending.  An every-day explicit-soft pool is the one
            # exception: its authoritative DaySlots carry the missing daily
            # cardinality even when the legacy report summarized only Day 1.
            explicit_soft_slot = bool(planned_pool is not None and planned_pool.soft_goal_id)
            if matching_report is None and not explicit_soft_slot:
                continue
            report_brief_id = (matching_report.get("briefId") if matching_report is not None else None) or (
                planned_pool.brief_id if planned_pool is not None else None
            )
            report_pool_id = (matching_report.get("poolId") if matching_report is not None else None) or (
                planned_pool.pool_id if planned_pool is not None else None
            )
            report_intent_type = (matching_report.get("intentType") if matching_report is not None else None) or (
                planned_pool.intent_type if planned_pool is not None else None
            )
            report_source_goal_id = (matching_report.get("sourceGoalId") if matching_report is not None else None) or (
                (planned_pool.goal_id or planned_pool.soft_goal_id) if planned_pool is not None else None
            )
            report_reason = (
                (matching_report.get("coverageReason") or matching_report.get("reason"))
                if matching_report is not None
                else "explicit_soft_daily_slot_unresolved"
            ) or "required_slot_unresolved"
            unresolved_rows.append(
                {
                    "slotId": slot_id,
                    "planningSlotId": slot_id,
                    "briefId": report_brief_id,
                    "poolId": report_pool_id,
                    "dayNumber": planned_slot.day_number,
                    "timeWindow": planned_slot.time_window,
                    "startTime": planned_slot.start_time,
                    "durationMinutes": planned_slot.duration_minutes,
                    "intentType": report_intent_type,
                    "goalId": report_source_goal_id,
                    "rawNeed": planned_slot.raw_need,
                    "kind": planned_slot.kind,
                    "reason": report_reason or "required_slot_unresolved",
                }
            )
        for raw in unresolved_rows:
            if not isinstance(raw, dict):
                continue
            brief_id = str(raw.get("briefId") or "")
            pool_id = str(raw.get("poolId") or "")
            slot_id = str(raw.get("slotId") or raw.get("planningSlotId") or "")
            day_number = int(raw.get("dayNumber") or 0)
            if not slot_id or slot_id in covered_slot_ids or day_number <= 0:
                continue
            matching_report = next(
                (
                    report
                    for report in reports
                    if (
                        not brief_id
                        or not str(report.get("briefId") or "")
                        or str(report.get("briefId") or "") == brief_id
                    )
                    and (
                        (pool_id and str(report.get("poolId") or "") == pool_id)
                        or slot_id
                        in {
                            str(item)
                            for item in (report.get("unresolvedSlotIds") or report.get("requiredSlotIds") or [])
                            if str(item)
                        }
                    )
                ),
                {},
            )
            brief_id = brief_id or str(matching_report.get("briefId") or "")
            pool_id = pool_id or str(matching_report.get("poolId") or "")
            scope = (brief_id, pool_id, slot_id, day_number)
            if scope in seen:
                continue
            seen.add(scope)
            planned_slot = planned_slots.get(slot_id)
            time_window = str(
                raw.get("timeWindow") or (planned_slot.time_window if planned_slot is not None else "") or ""
            )
            window_parts = time_window.replace("–", "-").split("-", 1)
            start_time = str(
                raw.get("startTime")
                or (planned_slot.start_time if planned_slot is not None else "")
                or (window_parts[0].strip() if window_parts else "")
            )
            end_time = str(raw.get("endTime") or (window_parts[1].strip() if len(window_parts) == 2 else ""))
            raw_need = str(
                raw.get("rawNeed")
                or matching_report.get("rawNeed")
                or (planned_slot.raw_need if planned_slot is not None else "")
                or "待补地点"
            )
            pending.append(
                {
                    "id": f"pending_{brief_id or 'single'}_{slot_id}",
                    "candidateRecordId": matching_report.get("candidateRecordId"),
                    "briefId": brief_id,
                    "poolId": pool_id,
                    "planningSlotId": slot_id,
                    "slotId": slot_id,
                    "dayNumber": day_number,
                    "timeWindow": time_window,
                    "startTime": start_time,
                    "endTime": end_time,
                    "durationMinutes": int(
                        raw.get("durationMinutes")
                        or (planned_slot.duration_minutes if planned_slot is not None else 0)
                        or 0
                    ),
                    "intentType": str(raw.get("intentType") or matching_report.get("intentType") or "landmark"),
                    "sourceGoalId": str(raw.get("goalId") or matching_report.get("sourceGoalId") or ""),
                    "rawNeed": raw_need,
                    "kind": str(
                        raw.get("kind") or (planned_slot.kind if planned_slot is not None else "activity") or "activity"
                    ),
                    "state": "pending",
                    "label": f"待补：{raw_need}",
                    "reason": str(raw.get("reason") or "missing_safe_candidate"),
                }
            )
        return pending

    def _selected_planning_candidate_overrides(
        self,
        session_id: str,
        pipeline_context: dict[str, Any],
    ) -> list[dict[str, Any]]:
        rows = self.db.execute(
            """
            SELECT c.id, c.turn_id, c.candidates_json, c.selected_amap_id, t.agent_request_json
            FROM amap_poi_candidates c
            LEFT JOIN conversation_turns t ON t.id = c.turn_id AND t.session_id = c.session_id
            WHERE c.session_id = ? AND c.segment_id IS NULL AND c.status IN ('pending', 'selected')
              AND c.selected_amap_id IS NOT NULL
            ORDER BY c.created_at ASC
            """,
            (session_id,),
        ).fetchall()
        current_contract = (
            pipeline_context.get("requestIntentContract")
            if isinstance(pipeline_context.get("requestIntentContract"), dict)
            else {}
        )
        current_contract_key = json.dumps(current_contract, ensure_ascii=False, sort_keys=True, default=str)
        current_root_turn_id = str(pipeline_context.get("planningSelectionRootTurnId") or "")
        if not current_root_turn_id:
            return []
        selected: dict[tuple[str, str, str, str, int], dict[str, Any]] = {}
        for row in rows:
            source_context = self._json_dict(row["agent_request_json"])
            source_root_turn_id = str(source_context.get("planningSelectionRootTurnId") or row["turn_id"] or "")
            if source_root_turn_id != current_root_turn_id:
                continue
            source_contract = (
                source_context.get("requestIntentContract")
                if isinstance(source_context.get("requestIntentContract"), dict)
                else {}
            )
            if (
                current_contract_key
                and json.dumps(source_contract, ensure_ascii=False, sort_keys=True, default=str) != current_contract_key
            ):
                continue
            try:
                raw_candidates = json.loads(row["candidates_json"] or "[]")
            except json.JSONDecodeError:
                continue
            if not isinstance(raw_candidates, list):
                continue
            selected_amap_id = str(row["selected_amap_id"] or "")
            for candidate in raw_candidates:
                if not isinstance(candidate, dict):
                    continue
                if str(candidate.get("id") or candidate.get("amapId") or "") != selected_amap_id:
                    continue
                source_goal_id = str(candidate.get("sourceGoalId") or "").strip()
                brief_id = str(candidate.get("briefId") or "").strip()
                pool_id = str(candidate.get("poolId") or "").strip()
                planning_slot_id = str(candidate.get("planningSlotId") or "").strip()
                day_number = int(candidate.get("dayNumber") or 0)
                if (not source_goal_id and not pool_id) or not planning_slot_id:
                    continue
                try:
                    poi = MapPoiResponse.model_validate(candidate)
                except ValidationError:
                    continue
                selected[
                    (
                        source_goal_id,
                        brief_id,
                        pool_id,
                        planning_slot_id,
                        day_number,
                    )
                ] = {
                    "candidateRecordId": str(row["id"] or ""),
                    "sourceGoalId": source_goal_id,
                    "briefId": brief_id,
                    "poolId": pool_id,
                    "planningSlotId": planning_slot_id,
                    "dayNumber": day_number,
                    "amapId": selected_amap_id,
                    "amapPoi": poi.model_dump(by_alias=True),
                }
        current = (
            pipeline_context.get("selectedPlanningCandidate")
            if isinstance(pipeline_context.get("selectedPlanningCandidate"), dict)
            else {}
        )
        current_goal_id = str(current.get("sourceGoalId") or "").strip()
        current_brief_id = str(current.get("briefId") or "").strip()
        current_pool_id = str(current.get("poolId") or "").strip()
        current_slot_id = str(current.get("planningSlotId") or "").strip()
        current_day_number = int(current.get("dayNumber") or 0)
        if current_slot_id and (current_goal_id or current_pool_id):
            try:
                current_poi = MapPoiResponse.model_validate(current.get("amapPoi"))
            except ValidationError:
                current_poi = None
            if current_poi is not None and str(current.get("amapId") or "") == str(current_poi.id):
                selected[
                    (
                        current_goal_id,
                        current_brief_id,
                        current_pool_id,
                        current_slot_id,
                        current_day_number,
                    )
                ] = {
                    **current,
                    "sourceGoalId": current_goal_id,
                    "briefId": current_brief_id,
                    "poolId": current_pool_id,
                    "planningSlotId": current_slot_id,
                    "dayNumber": current_day_number,
                    "amapId": current_poi.id,
                    "amapPoi": current_poi.model_dump(by_alias=True),
                    "selectionSource": "current_persisted_opaque_choice",
                }
        return list(selected.values())

    def _build_candidate_first_segment_plans(
        self,
        session: sqlite3.Row,
        initial_plan: AgentInitialPlanOutput,
        pipeline_context: dict,
        tool_events: list[dict[str, Any]],
        *,
        event_sink: Optional[AgentExecutionEventSink] = None,
        assistant_turn_id: Optional[str] = None,
    ) -> tuple[list[PersistableSegmentPlan], dict]:
        itinerary_service = ItineraryService(self.db)
        itinerary_service._force_candidate_refresh = False
        itinerary_service._expand_density_nearby = False
        expansion_claim = (
            pipeline_context.get("partialPlanExpansionClaim")
            if pipeline_context.get("_partialPlanExpansionAuthorized") is True
            and isinstance(pipeline_context.get("partialPlanExpansionClaim"), dict)
            else {}
        )
        execution_claim = (
            pipeline_context.get("fallbackChoiceExecutionClaim")
            if isinstance(pipeline_context.get("fallbackChoiceExecutionClaim"), dict)
            else {}
        )
        root_portfolio_id = str(expansion_claim.get("rootPortfolioId") or "")
        planning_root_id = str(expansion_claim.get("planningSelectionRootTurnId") or "")
        request_contract_fingerprint = str(expansion_claim.get("requestContractFingerprint") or "")
        attempt_identity = str(execution_claim.get("id") or "")
        if root_portfolio_id and planning_root_id and request_contract_fingerprint and attempt_identity:
            portfolio_store = PlanPortfolioStore(self.db)
            itinerary_service.configure_night_view_query_progress(
                scope_identity={
                    # The current schema has no tenant table.  Keep its fixed
                    # logical partition explicit and pair it with the durable
                    # session user identity; neither affects the query seed.
                    "tenantId": "default",
                    "userId": str(session["user_id"] or ""),
                    "planningRoot": planning_root_id,
                    "rootPortfolioId": root_portfolio_id,
                },
                attempt_identity=attempt_identity,
                claim_query=lambda **kwargs: portfolio_store.claim_night_view_query(
                    portfolio_id=root_portfolio_id,
                    expected_request_contract_fingerprint=request_contract_fingerprint,
                    **kwargs,
                ),
                complete_query=lambda **kwargs: portfolio_store.complete_night_view_query(
                    portfolio_id=root_portfolio_id,
                    expected_request_contract_fingerprint=request_contract_fingerprint,
                    **kwargs,
                ),
            )
        run_context = GroundingRunContext()
        pipeline_context["selectedPlanningCandidates"] = self._selected_planning_candidate_overrides(
            str(session["id"] or ""),
            pipeline_context,
        )
        day_slots = self._day_slots_from_initial_plan(initial_plan, pipeline_context)
        day_slots = self._ensure_required_repeating_day_slots(day_slots, pipeline_context)
        intent_pools = self._intent_pools_from_initial_plan(
            initial_plan, day_slots, pipeline_context, itinerary_service
        )
        if str(pipeline_context.get("serverExecutionProfile") or "") != "simple_open_v1":
            day_slots = self._align_time_sensitive_day_slots(day_slots, intent_pools)
        self._emit_execution_event(
            event_sink,
            session_id=str(session["id"]),
            turn_id=assistant_turn_id,
            event_type="planning",
            label="生成每日行程结构",
            detail="已按日期和时段拆分需要安排的参观、餐饮与夜景目标。",
        )
        density_resume_scope = self._portfolio_density_resume_scope(pipeline_context)
        checkpoint_scopes: list[dict[str, Any]] = []
        grounding_checkpoint = (
            pipeline_context.get("portfolioGroundingCheckpoint")
            if isinstance(pipeline_context.get("portfolioGroundingCheckpoint"), dict)
            else {}
        )
        density_route_context_plans: list[PersistableSegmentPlan] = []
        if density_resume_scope:
            target_slot = next(
                (
                    slot
                    for slot in day_slots
                    if self._slot_key(slot) == density_resume_scope["planningSlotId"]
                    and int(slot.day_number) == density_resume_scope["dayNumber"]
                ),
                None,
            )
            target_pool = next(
                (
                    pool
                    for pool in intent_pools
                    if str(pool.brief_id or "") == density_resume_scope["briefId"]
                    and str(pool.pool_id or "") == density_resume_scope["poolId"]
                    and target_slot is not None
                    and self._slot_key(target_slot) in pool.assign_to_slots
                ),
                None,
            )
            if target_slot is None or target_pool is None:
                raise ValueError("portfolio_density_resume_scope_missing")
            prior_target_report = next(
                (
                    report
                    for report in grounding_checkpoint.get("poolReports") or []
                    if isinstance(report, dict)
                    and str(report.get("briefId") or "") == density_resume_scope["briefId"]
                    and str(report.get("poolId") or "") == density_resume_scope["poolId"]
                ),
                None,
            )
            target_pool = self._density_resume_target_pool_with_hints(
                target_pool,
                prior_target_report,
                pipeline_context,
            )
            density_route_context_plans = self._portfolio_density_route_context_plans(
                grounding_checkpoint,
                day_slots,
                density_resume_scope,
                itinerary_service,
                pipeline_context,
            )
            # Confirmation is a continuation of one frozen consumer identity.
            # Reuse the prior union for every other pool and only recollect the
            # exact brief/pool/slot/day selected by the user.
            day_slots = [target_slot]
            intent_pools = [
                self._scoped_portfolio_density_pool(
                    target_pool,
                    self._slot_key(target_slot),
                )
            ]
        elif pipeline_context.get("checkpointPortfolioResume") or pipeline_context.get("checkpointExpansionResume"):
            checkpoint_scopes = self._portfolio_checkpoint_resume_scopes(
                grounding_checkpoint,
                pipeline_context,
            )
            if not checkpoint_scopes:
                raise ValueError("portfolio_checkpoint_resume_scope_missing")
            allowed_slot_ids = {scope["planningSlotId"] for scope in checkpoint_scopes}
            allowed_slot_days = {(scope["planningSlotId"], scope["dayNumber"]) for scope in checkpoint_scopes}
            allowed_pool_keys = {(scope["briefId"], scope["poolId"]) for scope in checkpoint_scopes}
            day_slots = [
                slot for slot in day_slots if (self._slot_key(slot), int(slot.day_number)) in allowed_slot_days
            ]
            intent_pools = [
                replace(
                    pool,
                    assign_to_slots=[slot_id for slot_id in pool.assign_to_slots if slot_id in allowed_slot_ids],
                )
                for pool in intent_pools
                if (str(pool.brief_id or ""), str(pool.pool_id or "")) in allowed_pool_keys
                and any(slot_id in allowed_slot_ids for slot_id in pool.assign_to_slots)
            ]
            if not day_slots or not intent_pools:
                raise ValueError("portfolio_checkpoint_resume_scope_missing")
            pipeline_context["checkpointResumeScope"] = copy.deepcopy(checkpoint_scopes)
        semantic_hint_needed = self._semantic_candidate_hint_needed(
            intent_pools, day_slots, pipeline_context, itinerary_service
        )
        self._append_pipeline_event(
            tool_events,
            "generate_day_slots",
            "生成 DaySlot",
            "completed",
            "已生成规划阶段 DaySlot；DaySlot 不会直接写入 itinerary_segments。",
            {"daySlotCount": len(day_slots), "dayCount": len({slot.day_number for slot in day_slots})},
        )
        self._append_pipeline_event(
            tool_events,
            "decompose_intent_pools",
            "拆解 IntentPool",
            "completed",
            "已将 routeAnchor DaySlot 归入 IntentPool；LLM 不输出最终 POI，候选由地图 API 生成。",
            {
                "intentPoolCount": len(intent_pools),
                "nonRouteSlotCount": len([slot for slot in day_slots if not slot.route_anchor]),
                "fallbackUsed": any("SERVER_GENERIC_DAY_SLOT_FALLBACK" in str(item) for item in initial_plan.warnings),
                "fallbackType": "server_generic_day_slots"
                if any("SERVER_GENERIC_DAY_SLOT_FALLBACK" in str(item) for item in initial_plan.warnings)
                else None,
                "candidateHintsAvailable": any(pool.candidate_hints for pool in intent_pools),
                "semanticCandidateHintNeeded": semantic_hint_needed,
                "implication": "generic pools use stricter threshold"
                if not any(pool.candidate_hints for pool in intent_pools)
                else "candidate hints seed structured map search",
            },
        )
        if semantic_hint_needed:
            retry_plan = None
            if not pipeline_context.get("candidateHintRetryAttempted"):
                pipeline_context["candidateHintRetryAttempted"] = True
                retry_plan = self._retry_initial_plan_with_candidate_hints(initial_plan, pipeline_context, tool_events)
            if retry_plan is None:
                return self._semantic_hint_missing_segment_report(
                    day_slots,
                    intent_pools,
                    initial_plan,
                    pipeline_context,
                    itinerary_service,
                    tool_events,
                )
            initial_plan = retry_plan
            intent_pools = self._intent_pools_from_initial_plan(
                initial_plan, day_slots, pipeline_context, itinerary_service
            )
            if checkpoint_scopes:
                allowed_slot_ids = {scope["planningSlotId"] for scope in checkpoint_scopes}
                allowed_pool_keys = {(scope["briefId"], scope["poolId"]) for scope in checkpoint_scopes}
                intent_pools = [
                    replace(
                        pool,
                        assign_to_slots=[slot_id for slot_id in pool.assign_to_slots if slot_id in allowed_slot_ids],
                    )
                    for pool in intent_pools
                    if (str(pool.brief_id or ""), str(pool.pool_id or "")) in allowed_pool_keys
                    and any(slot_id in allowed_slot_ids for slot_id in pool.assign_to_slots)
                ]
                if not intent_pools:
                    raise ValueError("portfolio_checkpoint_resume_scope_missing")
        if pipeline_context.get("creativePortfolioMode"):
            frontier_service = CreativeExplorationFrontierService(
                max_visible_comparison_cards=self.settings.agent_creative_portfolio_max_visible_proposals,
                max_generated_proposals_per_root=self.settings.agent_creative_portfolio_max_generated_proposals,
                max_continuation_rounds_per_root=self.settings.agent_creative_portfolio_max_continuation_rounds,
            )
            candidate_frontier = (
                pipeline_context.get("_creativeExplorationFrontier")
                if isinstance(pipeline_context.get("_creativeExplorationFrontier"), dict)
                else frontier_service.initial(
                    planning_root_id=str(pipeline_context.get("planningSelectionRootTurnId") or ""),
                    portfolio_id="",
                    fingerprint=str(pipeline_context.get("requestContractFingerprint") or ""),
                )
            )
            if root_portfolio_id and request_contract_fingerprint and assistant_turn_id:
                reservation = PlanPortfolioStore(self.db).reserve_candidate_amap_budget(
                    portfolio_id=root_portfolio_id,
                    execution_id=assistant_turn_id,
                    expected_request_contract_fingerprint=request_contract_fingerprint,
                )
                pipeline_context["_creativePortfolioCandidateBudgetReservation"] = {
                    "rootPortfolioId": root_portfolio_id,
                    "executionId": assistant_turn_id,
                    "status": str(reservation.get("status") or ""),
                    "providerCallAllowed": bool(reservation.get("providerCallAllowed")),
                }
                if isinstance(reservation.get("frontier"), dict):
                    candidate_frontier = copy.deepcopy(reservation["frontier"])
                    pipeline_context["_creativeExplorationFrontier"] = copy.deepcopy(candidate_frontier)
                allocation = reservation.get("allocation") if isinstance(reservation.get("allocation"), dict) else {}
                if not reservation.get("providerCallAllowed"):
                    self._append_pipeline_event(
                        tool_events,
                        "creative_candidate_budget_blocked",
                        "候选检索预算已占用或耗尽",
                        "completed",
                        "同一规划根没有可安全预留的高德候选调用额度；未调用 Provider，行程未发生变化。",
                        {
                            "status": str(reservation.get("status") or "BUDGET_EXHAUSTED"),
                            "rootPortfolioId": root_portfolio_id,
                            "writeAuthority": "none",
                        },
                    )
                    raise ValueError(
                        f"creative_candidate_budget_{str(reservation.get('status') or 'exhausted').lower()}"
                    )
                amap_budget = AmapCallBudget(
                    place_text_max=int(allocation.get("placeTextMax") or 0),
                    place_around_max=int(allocation.get("placeAroundMax") or 0),
                    route_refresh_max=0,
                    total_external_max=int(allocation.get("totalExternalMax") or 0),
                    source="creative_portfolio_candidate_grounding",
                )
            else:
                amap_budget = frontier_service.candidate_amap_budget(candidate_frontier)
        else:
            amap_budget = AmapCallBudget(source="candidate_first_grounding")
        self._emit_execution_event(
            event_sink,
            session_id=str(session["id"]),
            turn_id=assistant_turn_id,
            event_type="grounding",
            label="检索真实地点候选",
            detail="正在查询真实高德地点，并核对名称、坐标和目标语义。",
        )
        candidate_grounding_started = time.perf_counter()
        with amap_call_budget_scope(amap_budget):
            selected_plans, unresolved, pool_reports = self._select_candidate_set_for_intent_pools(
                session,
                day_slots,
                intent_pools,
                itinerary_service,
                run_context,
                pipeline_context,
                seed_route_context_plans=density_route_context_plans,
            )
        candidate_grounding_ms = round((time.perf_counter() - candidate_grounding_started) * 1000, 3)
        selected_plans = self._downgrade_high_detour_meal_plans(
            selected_plans,
            day_slots,
            unresolved,
            pipeline_context,
        )
        selected_plans = self._prune_long_route_outlier_plans(
            selected_plans,
            day_slots,
            unresolved,
            pipeline_context,
            run_context.warnings,
        )
        self._emit_execution_event(
            event_sink,
            session_id=str(session["id"]),
            turn_id=assistant_turn_id,
            event_type="planning",
            label="评估地点与路线可行性",
            detail="正在检查候选覆盖、日程密度与相邻地点路线是否可执行。",
        )
        required_intent_coverage = self._required_intent_coverage(pool_reports)
        provider_debug = self._provider_debug_from_pool_reports(pool_reports)
        self._append_pipeline_event(
            tool_events,
            "collect_candidates",
            "检索高德候选",
            "fallback" if run_context.rate_limited else "completed",
            "已按 IntentPool 检索真实高德候选；命中限流后停止本轮后续外部请求。"
            if run_context.rate_limited
            else "已按 IntentPool 检索真实高德候选，并基于 evidence score 完成集合选择。",
            {
                "rateLimited": run_context.rate_limited,
                "rateLimitReason": run_context.rate_limit_reason,
                "warnings": run_context.warnings[:8],
                "unresolvedCount": len(unresolved),
                "unresolvedSlots": unresolved[:20],
                "poolReports": self._pool_report_preview(pool_reports),
                "requiredIntentCoverage": required_intent_coverage,
                "providerDebug": provider_debug[:8],
                "amapCallBudget": amap_budget.snapshot(),
            },
        )
        portfolio_mode = bool(pipeline_context.get("creativePortfolioMode"))
        if portfolio_mode:
            # Generated briefs are mutually exclusive proposals. Applying the
            # legacy single-itinerary minimum-day gate to their union made four
            # alternatives look like one 28-anchor itinerary. Portfolio
            # staging below is the only authority that may project and verify a
            # brief, so this phase returns read-only evidence, never a union
            # timeline.
            focus_brief_id = str(pipeline_context.get("portfolioGroundingFocusBriefId") or "")
            focus_pool_ids = {
                pool.pool_id
                for pool in intent_pools
                if not focus_brief_id or str(pool.brief_id or "") == focus_brief_id
            }
            focus_slot_ids = {
                str(slot_id)
                for pool in intent_pools
                if pool.pool_id in focus_pool_ids
                for slot_id in pool.assign_to_slots
                if str(slot_id)
            }
            focus_slots = [slot for slot in day_slots if self._slot_key(slot) in focus_slot_ids and slot.route_anchor]
            focus_reports = [report for report in pool_reports if str(report.get("poolId") or "") in focus_pool_ids]
            resolved_focus_slots = {
                str(slot_id)
                for report in focus_reports
                for slot_id in report.get("resolvedSlotIds") or []
                if str(slot_id)
            }
            unresolved_focus_slots = {
                str(slot_id)
                for report in focus_reports
                for slot_id in report.get("unresolvedSlotIds") or []
                if str(slot_id)
            }
            day_readiness = []
            for day_number in sorted({slot.day_number for slot in focus_slots}):
                day_slot_ids = {self._slot_key(slot) for slot in focus_slots if slot.day_number == day_number}
                required_count = len(day_slot_ids)
                selected_count = len(day_slot_ids & resolved_focus_slots)
                unresolved_count = len(day_slot_ids & unresolved_focus_slots)
                day_readiness.append(
                    {
                        "dayNumber": day_number,
                        "requiredRouteAnchors": required_count,
                        "selectedRouteAnchors": selected_count,
                        "optionalSegments": 0,
                        "unresolvedRouteAnchors": unresolved_count,
                        "meetsMinimumViableDay": selected_count == required_count,
                        "blockingReasons": (
                            [] if selected_count == required_count else ["portfolio_brief_anchor_shortfall"]
                        ),
                    }
                )
            persistable = []
            finalization = TimelineFinalizationDecision(
                can_create_version=False,
                persistable_plans=[],
                result_state="portfolio_candidate_universe_ready",
                unresolved_policy="portfolio_brief_local_staging",
                quality_report={
                    "canCreateActiveVersion": False,
                    "qualityStatus": "portfolio_staging_read_only",
                    "hardFailures": [],
                    "softWarnings": [],
                },
            )
            route_anchor_required_count = len(focus_slots)
            route_anchor_selected_count = len(resolved_focus_slots & focus_slot_ids)
        else:
            persistable, day_readiness = self._minimum_viable_day_plans(
                day_slots, selected_plans, unresolved, pipeline_context
            )
            finalization = self._finalize_candidate_first_timeline(
                day_slots=day_slots,
                selected_plans=selected_plans,
                base_persistable=persistable,
                unresolved=unresolved,
                required_intent_coverage=required_intent_coverage,
                pipeline_context=pipeline_context,
                rate_limited=run_context.rate_limited,
            )
            persistable = finalization.persistable_plans
            route_anchor_required_count = sum(1 for slot in day_slots if slot.route_anchor)
            route_anchor_selected_count = sum(
                1 for plan in selected_plans if plan.route_anchor and plan.selected_poi is not None
            )
        self._append_pipeline_event(
            tool_events,
            "build_persistable_segment_plans",
            "构建可持久化日程段",
            "completed" if persistable or portfolio_mode else "fallback",
            (
                "Portfolio 候选证据已按单个方案边界整理，接下来逐方案执行密度与路线核验；本步不写入时间轴。"
                if portfolio_mode
                else (
                    "已将 selectedCandidate / non-route meal/rest 转成 PersistableSegmentPlan；未完成的宽泛 fallback 槽位保留为待补全元数据。"
                    if finalization.can_create_version and unresolved
                    else "已将 selectedCandidate / non-route meal/rest 转成 PersistableSegmentPlan；未达标 Day 不写入未完成 routeAnchor。"
                )
            ),
            {
                "persistableSegmentCount": len(persistable),
                "routeAnchorRequiredCount": route_anchor_required_count,
                "routeAnchorSelectedCount": route_anchor_selected_count,
                "persistableGroundedAnchorCount": sum(
                    1 for plan in persistable if plan.route_anchor and plan.selected_poi is not None
                ),
                "dayReadiness": day_readiness,
                "unresolvedDays": self._unresolved_days(unresolved),
                "minimumViableRule": "partial timelines require at least 1 verified real route anchor",
                "rateLimited": run_context.rate_limited,
                "requiredIntentCoverage": required_intent_coverage,
                "blockingRequiredIntents": finalization.blocking_required_intents,
                "finalization": self._finalization_metadata(finalization),
                "qualityContract": finalization.quality_report,
            },
        )
        planning_preview = [] if portfolio_mode else self._planning_preview(day_slots, selected_plans, unresolved)
        result_state = finalization.result_state
        report = {
            "rateLimited": run_context.rate_limited,
            "rateLimitReason": run_context.rate_limit_reason,
            "unresolvedSlots": unresolved,
            "unresolvedDays": self._unresolved_days(unresolved),
            "persistableSegmentCount": len(persistable),
            "routeAnchorRequiredCount": route_anchor_required_count,
            "routeAnchorSelectedCount": route_anchor_selected_count,
            "dayReadiness": day_readiness,
            "minimumViableRule": "partial timelines require at least 1 verified real route anchor",
            "routeStatus": "waiting_for_poi_grounding"
            if run_context.rate_limited or unresolved or not finalization.can_create_version
            else "not_generated_yet",
            "resultState": result_state,
            "warnings": list(dict.fromkeys([*run_context.warnings, *finalization.soft_warnings])),
            "poolReports": pool_reports,
            "requiredIntentCoverage": required_intent_coverage,
            "blockingRequiredIntents": finalization.blocking_required_intents,
            "finalization": self._finalization_metadata(finalization),
            "qualityContract": finalization.quality_report,
            "planningPreview": planning_preview,
            "initialPlan": initial_plan.model_dump(by_alias=True),
            "pipelineContext": self._storable_pipeline_context(pipeline_context),
            "performance": {"candidateGroundingMs": candidate_grounding_ms},
            "candidateAmapCallBudget": amap_budget.snapshot(),
        }
        if result_state == "candidate_refresh_required":
            report["rootGlobalBlocker"] = {
                "kind": "required_goal_gap",
                "status": "candidate_refresh_required",
                "goals": [
                    {
                        **copy.deepcopy(item),
                        "goalId": str(item.get("goalId") or item.get("sourceGoalId") or ""),
                        "intentType": str(item.get("intentType") or ""),
                        "missingCount": max(1, int(item.get("missingCount") or 0)),
                    }
                    for item in finalization.blocking_required_intents
                    if isinstance(item, dict)
                ],
            }
        if density_resume_scope and grounding_checkpoint:
            report = self._merge_portfolio_density_grounding_report(
                grounding_checkpoint,
                report,
                density_resume_scope,
            )
        elif pipeline_context.get("checkpointExpansionResume") and grounding_checkpoint:
            report = self._merge_portfolio_brief_grounding_report(
                grounding_checkpoint,
                report,
                str(pipeline_context.get("portfolioGroundingFocusBriefId") or ""),
            )
        return persistable, report

    def _finalization_metadata(self, finalization: TimelineFinalizationDecision) -> dict[str, Any]:
        quality_can_create_active = bool(
            finalization.quality_report.get("canCreateActiveVersion")
            and not finalization.quality_report.get("hardFailures")
        )
        draft_override = bool(finalization.quality_report.get("draftPersistenceOverride"))
        return {
            "canCreateVersion": finalization.can_create_version,
            "canCreateActiveVersion": quality_can_create_active,
            "canCreateDraftVersion": finalization.can_create_version
            and (draft_override or not quality_can_create_active),
            "canCreateCompleteVersion": quality_can_create_active,
            "draftPersistenceOverride": draft_override,
            "resultState": finalization.result_state,
            "blockingReasons": finalization.blocking_reasons,
            "softWarnings": finalization.soft_warnings,
            "unresolvedPolicy": finalization.unresolved_policy,
            "qualityContract": finalization.quality_report,
        }

    @staticmethod
    def _quality_blocking_required_intents(
        required_intent_coverage: list[dict[str, Any]],
        quality_report: dict[str, Any],
    ) -> list[dict[str, Any]]:
        blockers = [item for item in required_intent_coverage if item.get("coverageStatus") != "covered"]
        if blockers:
            return blockers
        return [dict(item) for item in quality_report.get("missingRequiredSlots") or [] if isinstance(item, dict)]

    def _can_persist_unfinished_draft(
        self,
        *,
        day_slots: list[DaySlot],
        base_persistable: list[PersistableSegmentPlan],
        unresolved: list[dict[str, Any]],
        required_intent_coverage: list[dict[str, Any]],
        quality_report: dict[str, Any],
        pipeline_context: dict[str, Any],
    ) -> bool:
        if not day_slots or not base_persistable:
            return False
        resolved_dates = (
            pipeline_context.get("resolvedTripDates")
            if isinstance(pipeline_context.get("resolvedTripDates"), dict)
            else {}
        )
        if resolved_dates and resolved_dates.get("status") not in {None, "resolved"}:
            return False
        if self._requires_complete_active_version(day_slots, pipeline_context, required_intent_coverage):
            return True
        return bool(unresolved or quality_report.get("hardFailures"))

    def _draft_persistence_quality_report(self, quality_report: dict[str, Any]) -> dict[str, Any]:
        report = dict(quality_report)
        report["draftPersistenceOverride"] = True
        report["originalCanCreateActiveVersion"] = quality_report.get("canCreateActiveVersion")
        report["canCreateDraftVersion"] = True
        report["canCreateCompleteVersion"] = False
        report.setdefault("qualityStatus", "draft_needs_completion")
        return report

    def _skeleton_segment_plans_from_initial_plan(
        self,
        initial_plan: AgentInitialPlanOutput,
        pipeline_context: dict[str, Any],
        grounding_report: dict[str, Any],
    ) -> list[PersistableSegmentPlan]:
        # A skeleton is a user-editable draft fallback, never a substitute for
        # a failed provider call or a confirmed structured choice. Those paths
        # must stay retryable and prove real grounding progress.
        if (
            grounding_report.get("rateLimited")
            or pipeline_context.get("fallbackChoiceExecution")
            or pipeline_context.get("fallbackChoiceExecutionClaim")
            or pipeline_context.get("structuredPlanningChoiceResume")
        ):
            return []
        day_slots = self._ensure_required_repeating_day_slots(
            self._day_slots_from_initial_plan(initial_plan, pipeline_context),
            pipeline_context,
        )
        if not day_slots:
            return []
        requirements = (
            pipeline_context.get("understoodRequirements")
            if isinstance(pipeline_context.get("understoodRequirements"), dict)
            else {}
        )
        fields = requirements.get("fields") if isinstance(requirements.get("fields"), dict) else {}
        message = str(pipeline_context.get("effectiveUserMessage") or pipeline_context.get("latestUserMessage") or "")
        resume_attempt = (
            pipeline_context.get("resumePlanningAttempt")
            if isinstance(pipeline_context.get("resumePlanningAttempt"), dict)
            else {}
        )
        decision_state = (
            pipeline_context.get("agentDecisionState")
            if isinstance(pipeline_context.get("agentDecisionState"), dict)
            else {}
        )
        planning_directive = (
            pipeline_context.get("planningDirective")
            if isinstance(pipeline_context.get("planningDirective"), dict)
            else {}
        )
        resolved_dates = (
            pipeline_context.get("resolvedTripDates")
            if isinstance(pipeline_context.get("resolvedTripDates"), dict)
            else {}
        )
        validated_controller_draft = bool(
            decision_state.get("source") == "controller"
            and decision_state.get("accepted") is True
            and decision_state.get("primaryAction") == "draft_itinerary"
            and planning_directive.get("type") == "draft_itinerary"
            and resolved_dates.get("status") == "resolved"
            and resolved_dates.get("dates")
        )
        complete_spec = self._looks_like_complete_itinerary_spec(message, fields)
        blocking_required_intents = [
            item
            for item in grounding_report.get("blockingRequiredIntents") or []
            if isinstance(item, dict) and int(item.get("missingCount") or 0) > 0
        ]
        if complete_spec and blocking_required_intents and not pipeline_context.get("creativePortfolioMode"):
            return []
        if not (complete_spec or resume_attempt.get("enabled") or validated_controller_draft):
            return []

        unresolved = grounding_report.setdefault("unresolvedSlots", [])
        unresolved_by_slot = {
            str(item.get("slotId") or ""): item for item in unresolved if isinstance(item, dict) and item.get("slotId")
        }
        plans: list[PersistableSegmentPlan] = []
        for slot in sorted(day_slots, key=lambda item: (item.day_number, self._minutes(item.start_time), item.slot_id)):
            if slot.route_anchor:
                reason = "skeleton_draft_pending_grounding"
                plans.append(self._degraded_route_anchor_segment_plan(slot, pipeline_context, reason))
                slot_id = self._slot_key(slot)
                existing_unresolved = unresolved_by_slot.get(slot_id)
                if existing_unresolved is not None:
                    existing_unresolved.setdefault("timeWindow", slot.time_window)
                    existing_unresolved.setdefault("rawNeed", slot.raw_need)
                    existing_unresolved.setdefault("kind", slot.kind)
                    existing_unresolved.setdefault("intentType", self._intent_type_for_slot(slot, pipeline_context))
                    existing_unresolved.setdefault("state", "waiting_for_poi_grounding")
                    existing_unresolved.setdefault("nextAction", "retry_unfinished_poi_grounding")
                    existing_unresolved["persistedPending"] = True
                else:
                    unresolved.append(
                        {
                            "slotId": slot_id,
                            "dayNumber": slot.day_number,
                            "timeWindow": slot.time_window,
                            "rawNeed": slot.raw_need,
                            "kind": slot.kind,
                            "intentType": self._intent_type_for_slot(slot, pipeline_context),
                            "reason": reason,
                            "state": "waiting_for_poi_grounding",
                            "nextAction": "retry_unfinished_poi_grounding",
                            "persistedPending": True,
                        }
                    )
                    unresolved_by_slot[slot_id] = unresolved[-1]
            else:
                plans.append(self._non_route_segment_plan(slot, pipeline_context))
        return plans

    def _mark_skeleton_draft_grounding_report(
        self,
        grounding_report: dict[str, Any],
        segment_plans: list[PersistableSegmentPlan],
    ) -> dict[str, Any]:
        report = dict(grounding_report)
        existing_finalization = report.get("finalization") if isinstance(report.get("finalization"), dict) else {}
        quality_contract = report.get("qualityContract") if isinstance(report.get("qualityContract"), dict) else {}
        report["resultState"] = "draft_created_with_pending_grounding"
        report["persistableSegmentCount"] = len(segment_plans)
        report["routeStatus"] = "waiting_for_poi_grounding"
        report["finalization"] = {
            **existing_finalization,
            "canCreateVersion": True,
            "canCreateActiveVersion": bool(quality_contract.get("canCreateActiveVersion")),
            "canCreateDraftVersion": True,
            "canCreateCompleteVersion": False,
            "resultState": "draft_created_with_pending_grounding",
            "blockingReasons": [],
            "softWarnings": list(
                dict.fromkeys(
                    [
                        *[str(item) for item in existing_finalization.get("softWarnings") or []],
                        "已先创建可编辑草稿；部分 POI/餐饮/夜景仍待地图候选补全。",
                    ]
                )
            ),
            "unresolvedPolicy": "persist_viable_partial_days",
            "draftPersistenceOverride": True,
            "qualityContract": {**quality_contract, "draftPersistenceOverride": True},
        }
        report["qualityContract"] = {**quality_contract, "draftPersistenceOverride": True}
        report["warnings"] = list(
            dict.fromkeys(
                [
                    *[str(item) for item in report.get("warnings") or []],
                    "已先创建可编辑草稿；部分 POI/餐饮/夜景仍待地图候选补全。",
                ]
            )
        )
        return report

    @staticmethod
    def _explicit_route_preference_override_requested(request_text: str) -> bool:
        """Return whether the current turn explicitly changes route policy.

        Generic itinerary adjectives such as ``轻松一点`` are intentionally
        excluded.  In overview they can change the schedule/content density,
        but they do not silently rewrite the confirmed mobility weights or
        detour provenance.  Route policy is recompiled only when the user names
        a transport mode, walking/transfer constraint, detour constraint, or
        explicitly scopes pace wording to route/transport.
        """

        folded = str(request_text or "").strip().casefold()
        if not folded:
            return False
        if re.search(r"(绕行|绕路|额外路程|detour|少走路|少换乘|换乘少|步行少)", folded):
            return True
        route_scope = r"(?:路线|路程|交通|出行|通勤)"
        route_pace = r"(?:偏好|方式|节奏|轻松|不赶|慢节奏|省力|紧凑|高强度)"
        if re.search(rf"{route_scope}.{{0,10}}{route_pace}", folded) or re.search(
            rf"{route_pace}.{{0,10}}{route_scope}", folded
        ):
            return True
        route_mode = (
            r"(?:公交地铁|公共交通|地铁|公交|步行(?!街)|走路|徒步|打车|出租车|自驾|驾车|开车|"
            r"骑行|自行车|单车|transit|public[_ -]?transit|walking|\bwalk\b|taxi|driving|"
            r"\bdrive\b|bicycling|cycling|\bbike\b)"
        )
        if re.fullmatch(rf"\s*{route_mode}\s*", folded):
            return True
        if re.search(rf"{route_scope}.{{0,10}}{route_mode}", folded) or re.search(
            rf"{route_mode}.{{0,10}}{route_scope}", folded
        ):
            return True
        if re.search(
            rf"(?:优先|采用|使用|乘坐|坐|骑|走|开|打|不要|避免|只要|主要|尽量).{{0,5}}{route_mode}",
            folded,
        ) or re.search(rf"{route_mode}.{{0,6}}(?:优先|为主|方式|偏好)", folded):
            return True
        return bool(
            re.search(
                rf"(?:改成|换成|改为).{{0,4}}{route_mode}"
                rf"(?:\s*(?:出行|交通|路线|方式|优先|为主))?\s*(?:吧|。|！|!|\.|,|，)?$",
                folded,
            )
        )

    @staticmethod
    def _route_accessibility_fallback_requested(request_text: str) -> bool:
        """Detect accessibility semantics the current route contract cannot prove.

        AMap route results do not provide an end-to-end wheelchair-accessibility
        guarantee.  These words therefore cannot be compiled into ordinary
        walking/transfer weights or silently inherit the prior policy.  The
        caller turns them into one explicit, typed fallback decision before any
        route or itinerary mutation is allowed.
        """

        folded = str(request_text or "").strip().casefold()
        if not folded:
            return False
        if re.search(r"(轮椅|wheelchair)", folded):
            return True
        return bool(
            re.search(
                r"(?:尽量|需要|要求|优先|保证|全程|路线|交通|出行|通行|适合).{0,8}无障碍"
                r"|无障碍.{0,8}(?:优先|路线|交通|出行|通行|要求|需求|保证)",
                folded,
            )
            or re.search(r"\b(?:accessible|accessibility)\b", folded)
        )

    def _restore_active_route_decision_contract(self, request_context: dict[str, Any]) -> None:
        """Carry the confirmed route policy into later direction/edit turns.

        A short follow-up such as ``再轻松一点`` does not restate transport and
        detour thresholds.  Those are versioned server facts, so recompiling
        only from the short message would incorrectly ask the same questions
        again.  Explicit route wording is still applied over the persisted
        policy by the compiler; no browser-supplied policy is accepted.
        """

        session_id = str(request_context.get("sessionId") or "")
        active_version_id = str(request_context.get("activeVersionId") or "")
        active_plan_id = str(request_context.get("activePlanId") or "")
        if not session_id or not active_version_id or not active_plan_id:
            return
        row = self.db.execute(
            "SELECT snapshot_json FROM itinerary_versions WHERE id = ? AND session_id = ? AND plan_id = ?",
            (active_version_id, session_id, active_plan_id),
        ).fetchone()
        if row is None:
            return
        snapshot = self._json_dict(row["snapshot_json"])
        persisted_route = snapshot.get("routeDecisionContract") if isinstance(snapshot, dict) else None
        if RouteInsertionScorer.normalized_route_decision_contract(persisted_route) is None:
            return
        contract = (
            request_context.get("requestIntentContract")
            if isinstance(request_context.get("requestIntentContract"), dict)
            else {}
        )
        if not contract:
            return
        request_text = str(
            request_context.get("latestUserMessage") or request_context.get("effectiveUserMessage") or ""
        )
        if self._route_accessibility_fallback_requested(request_text):
            # The Provider cannot attest an end-to-end accessible journey.  Do
            # not pretend that a higher walking penalty proves accessibility,
            # and do not retain the old policy without telling the user.  Keep
            # the confirmed detour threshold but reopen the server-owned
            # mobility dimension with an explicit limitation.
            unresolved_route = copy.deepcopy(persisted_route)
            unresolved_route.pop("fingerprint", None)
            unresolved_route.update(
                {
                    "status": "awaiting_clarification",
                    "missingFields": ["mobilityProfile"],
                    "mobilityProfile": None,
                    "accessibilityFallbackRequired": True,
                }
            )
            unresolved_route["fingerprint"] = ClarificationCheckpointService._fingerprint(unresolved_route)
            contract["routeDecisionContract"] = unresolved_route
            contract["clarificationRequired"] = True
            contract["clarificationReason"] = "route_accessibility_fallback_required"
            contract["clarificationDimensions"] = [
                *[
                    copy.deepcopy(item)
                    for item in contract.get("clarificationDimensions") or []
                    if isinstance(item, dict) and str(item.get("intentType") or "") != "route_decision"
                ],
                {
                    "dimensionId": "route_decision.mobility_profile",
                    "intentType": "route_decision",
                    "status": "unresolved",
                    "impactCode": "accessibility_provider_limit_requires_explicit_fallback",
                    "candidateScope": {
                        "routeDecisionContractFingerprint": unresolved_route["fingerprint"],
                        "missingFields": ["mobilityProfile"],
                        "providerLimitation": "end_to_end_accessibility_not_verified",
                    },
                    "allowedSemanticFields": ["mobilityProfile"],
                },
            ]
            request_context["requestIntentContract"] = contract
            request_context["routeDecisionContract"] = copy.deepcopy(unresolved_route)
            return
        if self._explicit_route_preference_override_requested(request_text):
            compiled = self._compile_route_decision_contract(
                request_text=request_text,
                experience_specs=[
                    copy.deepcopy(item)
                    for item in contract.get("experienceSpecs") or request_context.get("experienceSpecs") or []
                    if isinstance(item, dict)
                ],
                existing_contract=copy.deepcopy(persisted_route),
            )
        else:
            # The versioned envelope is the authority.  Preserve it byte-for-
            # byte at the JSON value level, including provenance and
            # fingerprint, so a vague content/schedule edit cannot invalidate
            # other persisted direction proposals that share this policy.
            compiled = copy.deepcopy(persisted_route)
        if compiled.get("status") != "ready":
            return
        contract["routeDecisionContract"] = compiled
        remaining_dimensions = [
            copy.deepcopy(item)
            for item in contract.get("clarificationDimensions") or []
            if isinstance(item, dict) and str(item.get("intentType") or "") != "route_decision"
        ]
        contract["clarificationDimensions"] = remaining_dimensions
        if not remaining_dimensions:
            contract["clarificationRequired"] = False
            if str(contract.get("clarificationReason") or "").startswith("route_"):
                contract["clarificationReason"] = None
        request_context["requestIntentContract"] = contract
        request_context["routeDecisionContract"] = copy.deepcopy(compiled)

    def _restore_request_intent_contract(self, session_id: str, request_context: dict[str, Any]) -> None:
        """Restore one persisted canonical request envelope for continuation turns."""
        current_date_resolution = (
            request_context.get("resolvedTripDates")
            if isinstance(request_context.get("resolvedTripDates"), dict)
            else {}
        )
        if str(current_date_resolution.get("status") or "") == "unresolved":
            # A conflict or invalid explicit date in the effective user request is
            # authoritative.  Restoring an older successful envelope here would
            # silently turn a typed clarification into a different trip.
            return

        latest = str(request_context.get("latestUserMessage") or "").strip()
        selected = request_context.get("selectedAgentChoice")
        turns = request_context.get("activeConversationTurns")
        conversation_route = request_context.get("conversationIntent")
        structured_route_active = isinstance(conversation_route, dict)
        route_classification = (
            conversation_route.get("classification")
            if structured_route_active and isinstance(conversation_route.get("classification"), dict)
            else {}
        )
        structured_pure_retry = str(route_classification.get("intent") or "") in {
            "adopt_plan",
            "continue_pending_slot",
            "continue_plan_expansion",
            "regenerate_from_scratch",
            "retry_current_stage",
        }
        structured_refinement = bool(
            str(route_classification.get("intent") or "") == "create_itinerary"
            and str(route_classification.get("requestedScope") or "") == "planning_root"
        )
        looks_like_new_trip = bool(re.search(r"(旅行|行程|[一二三四五六七八九十两\d]+日游|\d{1,2}月\d{1,2}日)", latest))
        continuation = bool(
            structured_refinement
            or isinstance(selected, dict)
            or re.search(r"^(重试|继续|再试|补充|确认|选择|改成|换成)", latest)
            or (not looks_like_new_trip and len(latest) <= 30 and isinstance(turns, list) and len(turns) >= 2)
        )
        if not continuation:
            return

        selected_choice = (
            request_context.get("selectedAgentChoice")
            if isinstance(request_context.get("selectedAgentChoice"), dict)
            else {}
        )
        selected_option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        density_candidate_choice = self.portfolio_density_continuation.is_density_option(selected_option)
        clarification_checkpoint_choice = bool(
            (
                (
                    str(selected_option.get("kind") or "") in {"clarification_checkpoint", "custom_input"}
                    and str(selected_option.get("action") or "") == "continue_clarification"
                )
                or (
                    str(selected_option.get("kind") or "") == "clarification_batch_submit"
                    and str(selected_option.get("action") or "") == "submit_clarification_batch"
                )
            )
            and str(selected_option.get("checkpointId") or "")
        )
        current_contract = (
            request_context.get("requestIntentContract")
            if isinstance(request_context.get("requestIntentContract"), dict)
            else {}
        )
        current_checkpoint = (
            request_context.get("clarificationCheckpoint")
            if isinstance(request_context.get("clarificationCheckpoint"), dict)
            else {}
        )
        if (
            clarification_checkpoint_choice
            and current_checkpoint.get("status") in {"answered", "awaiting_agent_resolution"}
            and (
                str(current_contract.get("clarificationCheckpointId") or "")
                == str(current_checkpoint.get("checkpointId") or "")
                or current_checkpoint.get("status") == "awaiting_agent_resolution"
            )
        ):
            canonical = request_context.get("canonicalRequestContext")
            if isinstance(canonical, dict):
                canonical["requestIntentContract"] = copy.deepcopy(current_contract)
                canonical["clarificationCheckpoint"] = copy.deepcopy(current_checkpoint)
                canonical["experienceSpecs"] = copy.deepcopy(
                    request_context.get("experienceSpecs") or current_contract.get("experienceSpecs") or []
                )
            return
        density_envelope_keys = (
            "sourceUserRequest",
            "effectiveUserMessage",
            "resolvedTripDates",
            "requestIntentContract",
            "activeVersionId",
            "planningDirective",
            "agentDecision",
            "agentDecisionState",
            "actionDirectiveSource",
            "hardConstraints",
            "canonicalRequestContext",
            "goalLedgerSource",
        )
        if density_candidate_choice:
            # A density choice resumes exactly one persisted proposal turn.
            # Clear caller-provided values so a missing source cannot mix with stale context.
            for key in density_envelope_keys:
                request_context.pop(key, None)

        def restore(
            prior: dict[str, Any],
            source: str,
            source_turn_id: str = "",
            source_user_turn_id: str = "",
            source_version_id: Optional[str] = None,
        ) -> bool:
            contract = prior.get("requestIntentContract")
            if not (isinstance(contract, dict) and isinstance(contract.get("requiredIntents"), list)):
                return False
            prior_dates = prior.get("resolvedTripDates")
            if not (isinstance(prior_dates, dict) and prior_dates.get("status") == "resolved"):
                return False
            source_user_request = str(
                prior.get("sourceUserRequest")
                or prior.get("effectiveUserMessage")
                or prior.get("latestUserMessage")
                or ""
            ).strip()
            if not source_user_request:
                return False
            density_directive: Optional[dict[str, Any]] = None
            if density_candidate_choice:
                raw_directive = prior.get("planningDirective")
                if not isinstance(raw_directive, dict):
                    decision = prior.get("agentDecision")
                    raw_directive = decision.get("actionDirective") if isinstance(decision, dict) else None
                if not isinstance(raw_directive, dict) or raw_directive.get("type") != "draft_itinerary":
                    return False
                density_directive = copy.deepcopy(raw_directive)
            source_effective_message = str(prior.get("effectiveUserMessage") or source_user_request).strip()
            selected_action = str(
                selected_choice.get("action")
                or (
                    selected_choice.get("option", {}).get("action")
                    if isinstance(selected_choice.get("option"), dict)
                    else ""
                )
                or ""
            )
            # The public path has already classified this exact turn once.
            # Never let the legacy retry classifier reinterpret it during
            # restore or Coordinator reload; route-less callers retain the
            # compatibility seam below.
            pure_retry = (
                structured_pure_retry
                if structured_route_active
                else PlanningAttemptResumeService.is_retry_intent(latest)
            )
            effective_user_message = source_effective_message
            selected_semantic_message = str(selected_choice.get("semanticMessage") or "").strip()
            selected_option_kind = str(selected_option.get("kind") or "").strip()
            clarification_contract = bool(contract.get("clarificationRequired"))
            persisted_clarification_choice = bool(
                clarification_contract
                and not selected_action
                and selected_option_kind in {"preset", "custom_input"}
                and selected_semantic_message
            )
            should_append_latest = bool(
                latest
                and not pure_retry
                and selected_action != "retry_model_planning"
                and not density_candidate_choice
                and latest not in source_effective_message
            )
            if clarification_checkpoint_choice:
                # A checkpoint option is resolved below against the exact
                # request contract that produced it.  Do not append its label
                # or reconstruct the contract from a presentation string.
                effective_user_message = source_effective_message
            elif persisted_clarification_choice:
                # ContextBuilder resolves semanticMessage from the persisted
                # opaque choice.  It is the authoritative original request +
                # clarification value; the rendered label is not a contract.
                effective_user_message = selected_semantic_message
            elif should_append_latest:
                effective_user_message = "\n".join(item for item in (source_effective_message, latest) if item)
            restored_contract = dict(contract)
            if not clarification_checkpoint_choice and (
                (structured_refinement and should_append_latest)
                or (clarification_contract and (persisted_clarification_choice or should_append_latest))
            ):
                contract_context = {
                    **request_context,
                    "effectiveUserMessage": effective_user_message,
                    "resolvedTripDates": dict(prior_dates),
                }
                recompiled_contract = self._request_intent_contract(
                    effective_user_message,
                    dict(prior_dates),
                    self._meal_grounding_policy_result(contract_context),
                    city=str(
                        request_context.get("selectedCity")
                        or ((contract.get("localExperienceConstraint") or {}).get("locality") or {}).get("city")
                        or ""
                    ),
                    simple_open_profile=self.initial_planning_mode == "simple_open_v1",
                )
                if isinstance(recompiled_contract.get("requiredIntents"), list):
                    restored_contract = recompiled_contract
            persisted_version_id = source_version_id
            if persisted_version_id is None and "activeVersionId" in prior:
                persisted_version_id = prior.get("activeVersionId")
            frozen_dates = dict(prior_dates)
            if structured_refinement:
                frozen_dates["source"] = "frozen_parent_root"
            canonical = {
                "sourceUserRequest": source_user_request,
                "effectiveUserMessage": effective_user_message,
                "resolvedTripDates": frozen_dates,
                "requestIntentContract": restored_contract,
                "activeVersionId": persisted_version_id,
            }
            # These fields form one atomic envelope. Never mix the retry text's
            # date/goal contract with a different persisted source request.
            request_context.update(canonical)
            if structured_refinement:
                request_context["derivedPlanningRootRequested"] = True
                request_context["derivedFrom"] = copy.deepcopy(request_context.get("requestRefinement") or {})
            for key in (
                "clarificationCheckpoint",
                "experienceSpecs",
                "candidateGapSummary",
            ):
                if key in prior:
                    request_context[key] = copy.deepcopy(prior[key])
            if source == "persisted_clarification_user_envelope":
                request_context["planningSelectionRootTurnId"] = str(prior.get("planningSelectionRootTurnId") or "")
            if "experienceSpecs" not in request_context and isinstance(restored_contract.get("experienceSpecs"), list):
                request_context["experienceSpecs"] = copy.deepcopy(restored_contract["experienceSpecs"])
            if clarification_checkpoint_choice:
                request_context["planningSelectionRootTurnId"] = str(
                    selected_option.get("planningSelectionRootTurnId") or source_user_turn_id or ""
                )
            if density_candidate_choice:
                request_context["planningDirective"] = density_directive
                for key in (
                    "agentDecision",
                    "agentDecisionState",
                    "actionDirectiveSource",
                    "hardConstraints",
                ):
                    if key in prior:
                        request_context[key] = copy.deepcopy(prior[key])
            request_context["latestUserMessage"] = latest
            continuation_context = {
                "kind": selected_action
                if selected_action in {"retry_model_planning", "manual_continuation"}
                else "retry_model_planning"
                if pure_retry
                else "model_continuation",
                "source": source,
                "sourceAssistantTurnId": source_turn_id or None,
                "sourceUserTurnId": source_user_turn_id or prior.get("currentUserTurnId"),
                "sourceActiveVersionId": persisted_version_id,
                "latestUserMessage": latest,
                "sourceUserRequest": source_user_request,
                "effectiveUserMessage": effective_user_message,
            }
            request_context["continuationContext"] = continuation_context
            request_context["canonicalRequestContext"] = {
                **canonical,
                "sourceAssistantTurnId": source_turn_id or None,
                "sourceUserTurnId": continuation_context["sourceUserTurnId"],
            }
            for key in (
                "clarificationCheckpoint",
                "experienceSpecs",
                "candidateGapSummary",
            ):
                if key in request_context:
                    request_context["canonicalRequestContext"][key] = copy.deepcopy(request_context[key])
            request_context["goalLedgerSource"] = source
            return True

        def persisted_turn_context(row: sqlite3.Row) -> tuple[dict[str, Any], str, Optional[str]]:
            prior = self._json_dict(row["agent_request_json"])
            source_user_turn_id = str(prior.get("currentUserTurnId") or "").strip()
            source_version_id = str(row["itinerary_version_id"] or prior.get("activeVersionId") or "").strip() or None
            return prior, source_user_turn_id, source_version_id

        source_turn_id = str(selected_choice.get("sourceAssistantTurnId") or "").strip()
        if source_turn_id:
            row = self.db.execute(
                """
                SELECT agent_request_json, itinerary_version_id FROM conversation_turns
                WHERE id = ? AND session_id = ? AND role = 'assistant' AND status != 'superseded'
                """,
                (source_turn_id, session_id),
            ).fetchone()
            if row is not None:
                prior, source_user_turn_id, source_version_id = persisted_turn_context(row)
                if restore(
                    prior,
                    "selected_choice_source_assistant_turn",
                    source_turn_id,
                    source_user_turn_id,
                    source_version_id,
                ):
                    return
            if density_candidate_choice:
                request_context["densityChoiceSourceContextMissing"] = True
                return
        if density_candidate_choice:
            request_context["densityChoiceSourceContextMissing"] = True
            return
        clarification_recovery = ConversationService(self.db).latest_clarification_recovery_envelope(
            session_id,
            unmaterialized_only=True,
        )
        if isinstance(clarification_recovery, dict):
            recovered_context = clarification_recovery.get("requestContext")
            if isinstance(recovered_context, dict) and restore(
                recovered_context,
                "persisted_clarification_user_envelope",
                str(clarification_recovery.get("sourceAssistantTurnId") or ""),
                str(clarification_recovery.get("sourceUserTurnId") or ""),
                (str(clarification_recovery.get("itineraryVersionId") or "").strip() or None),
            ):
                return
        rows = self.db.execute(
            """
            SELECT id, agent_request_json, itinerary_version_id FROM conversation_turns
            WHERE session_id = ? AND role = 'assistant' AND status IN ('active', 'failed')
            ORDER BY turn_index DESC LIMIT 12
            """,
            (session_id,),
        ).fetchall()
        for row in rows:
            prior, source_user_turn_id, source_version_id = persisted_turn_context(row)
            if restore(
                prior,
                "persisted_source_assistant_turn",
                str(row["id"] or ""),
                source_user_turn_id,
                source_version_id,
            ):
                return

    def _active_partial_snapshot(self, session_id: str) -> Optional[dict[str, Any]]:
        """Return reconciled active partial truth, including route-only partials with no pending slot."""
        row = self.db.execute(
            """
            SELECT v.snapshot_json
            FROM conversation_sessions AS s
            JOIN itinerary_versions AS v
              ON v.id = s.active_version_id AND v.session_id = s.id
            WHERE s.id = ?
            """,
            (session_id,),
        ).fetchone()
        if row is None:
            return None
        snapshot = self._json_dict(row["snapshot_json"])
        if not isinstance(snapshot.get("portfolioPartialTimeline"), dict):
            return None
        try:
            return PortfolioPendingSlotService.reconcile(snapshot)
        except PortfolioPendingSlotError:
            return None

    def _active_partial_pending_snapshot(self, session_id: str) -> Optional[dict[str, Any]]:
        """Return active partial truth only when a concrete pending slot exists."""
        reconciled = self._active_partial_snapshot(session_id)
        return reconciled if reconciled and reconciled.get("portfolioPendingSlots") else None

    @staticmethod
    def _unresolved_request_contract_clarification_dimensions(
        request_contract: dict[str, Any],
    ) -> list[str]:
        if not isinstance(request_contract, dict):
            return []
        unresolved = [
            str(item.get("dimensionId") or "").strip()
            for item in request_contract.get("clarificationDimensions") or []
            if isinstance(item, dict)
            and str(item.get("dimensionId") or "").strip()
            and str(item.get("status") or "") != "resolved"
        ]
        if bool(request_contract.get("clarificationRequired")) and not unresolved:
            fallback_reason = str(request_contract.get("clarificationReason") or "").strip()
            unresolved.append(fallback_reason or "clarification_required")
        return list(dict.fromkeys(item for item in unresolved if item))

    @classmethod
    def _retry_option_identity(
        cls,
        context: dict[str, Any],
        *,
        fallback_user_turn_id: str,
        request_contract: Optional[dict[str, Any]] = None,
    ) -> dict[str, Any]:
        canonical = (
            context.get("canonicalRequestContext") if isinstance(context.get("canonicalRequestContext"), dict) else {}
        )
        continuation = (
            context.get("continuationContext") if isinstance(context.get("continuationContext"), dict) else {}
        )
        selected_choice = (
            context.get("selectedAgentChoice") if isinstance(context.get("selectedAgentChoice"), dict) else {}
        )
        selected_option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        checkpoint = (
            context.get("clarificationCheckpoint") if isinstance(context.get("clarificationCheckpoint"), dict) else {}
        )
        claim = (
            context.get("fallbackChoiceExecutionClaim")
            if isinstance(context.get("fallbackChoiceExecutionClaim"), dict)
            else {}
        )
        contract = request_contract if isinstance(request_contract, dict) else {}
        source_user_turn_id = str(
            selected_option.get("planningSelectionRootTurnId")
            or checkpoint.get("planningRootId")
            or context.get("planningSelectionRootTurnId")
            or continuation.get("sourceUserTurnId")
            or canonical.get("sourceUserTurnId")
            or selected_option.get("sourceUserTurnId")
            or checkpoint.get("sourceUserTurnId")
            or context.get("currentUserTurnId")
            or fallback_user_turn_id
            or ""
        )
        planning_root_id = str(
            selected_option.get("planningSelectionRootTurnId")
            or checkpoint.get("planningRootId")
            or continuation.get("planningSelectionRootTurnId")
            or canonical.get("planningSelectionRootTurnId")
            or context.get("planningSelectionRootTurnId")
            or source_user_turn_id
            or ""
        )
        effective_action = str(
            selected_choice.get("action")
            or selected_option.get("action")
            or claim.get("action")
            or continuation.get("kind")
            or ""
        ).strip()
        contract_fingerprint = str(
            contract.get("fingerprint") or (ClarificationCheckpointService._fingerprint(contract) if contract else "")
        )
        inherited_request_fingerprint = str(
            selected_option.get("requestContractFingerprint")
            or checkpoint.get("requestFingerprint")
            or continuation.get("requestContractFingerprint")
            or canonical.get("requestContractFingerprint")
            or context.get("requestContractFingerprint")
            or ""
        )
        request_fingerprint = (
            inherited_request_fingerprint or contract_fingerprint
            if effective_action == "retry_model_planning"
            else contract_fingerprint or inherited_request_fingerprint
        )
        attempt_base = 0
        if effective_action == "retry_model_planning":
            for raw_value in (claim.get("attempt"), selected_option.get("attempt")):
                try:
                    attempt_base = max(attempt_base, int(raw_value or 0))
                except (TypeError, ValueError):
                    continue
        return {
            "sourceUserTurnId": source_user_turn_id,
            "planningSelectionRootTurnId": planning_root_id,
            "requestContractFingerprint": request_fingerprint,
            "attempt": attempt_base + 1 if attempt_base > 0 else 1,
        }

    @staticmethod
    def _prepare_partial_comparison_material(
        *,
        proposal_id: str,
        snapshot: dict[str, Any],
        comparison_role: str,
        origin_projection_mode: str,
        candidate: Any = None,
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
        """Build proposal material without making it visible or writing portfolio rows."""

        material = copy.deepcopy(snapshot)
        material.update(
            {
                "proposalId": proposal_id,
                "comparisonRole": comparison_role,
                "originProjectionMode": origin_projection_mode,
            }
        )
        candidate_verifier = getattr(candidate, "verifier", None)
        verifier = (
            copy.deepcopy(candidate_verifier)
            if isinstance(candidate_verifier, dict)
            else copy.deepcopy(material.get("portfolioVerifier"))
            if isinstance(material.get("portfolioVerifier"), dict)
            else {"passed": False, "hardFailures": ["portfolio_route_quality:route_evidence_incomplete"]}
        )
        material["portfolioVerifier"] = copy.deepcopy(verifier)
        readiness = ProposalReadinessService.compute(material, verifier=verifier)
        if readiness.get("themeEligible") is not True and str(readiness.get("displayTitle") or "").strip():
            material["title"] = str(readiness["displayTitle"])
        route_status = str(readiness.get("routeStatus") or "route_pending")
        status = {
            "route_provider_failed": "route_provider_failed",
            "route_partial": "route_partial",
            "route_ready": "adoption_ready" if readiness.get("adoptionReady") else "route_ready",
        }.get(route_status, "route_pending")
        candidate_brief = getattr(candidate, "brief", None)
        candidate_score = getattr(candidate, "score", None)
        generation_lineage = getattr(candidate, "generation_lineage", None)
        store_material = {
            "brief": candidate_brief if candidate_brief is not None else material.get("creativeBrief") or {},
            "verifier": verifier,
            "score": candidate_score if candidate_score is not None else {"hardConstraintPassed": False},
            "generationLineage": (
                copy.deepcopy(generation_lineage)
                if isinstance(generation_lineage, dict)
                else {"partialPreview": {"originProjectionMode": origin_projection_mode}}
            ),
            "status": status,
            "evidence": {"readiness": readiness, "routeStatus": route_status},
        }
        return material, readiness, store_material

    def _persist_partial_comparison_material(
        self,
        *,
        portfolio_id: str,
        proposal_id: str,
        choice_id: str,
        snapshot: dict[str, Any],
        comparison_role: str,
        origin_projection_mode: str,
        candidate: Any = None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        """Persist a read-only partial card through the existing proposal store.

        The card is still zero-write for itinerary state.  Persisting it gives
        route finalization and the opaque selection capability a server-side
        source of truth instead of relying on a frontend-only projection.
        """
        material, readiness, store_material = self._prepare_partial_comparison_material(
            proposal_id=proposal_id,
            snapshot=snapshot,
            comparison_role=comparison_role,
            origin_projection_mode=origin_projection_mode,
            candidate=candidate,
        )
        PlanPortfolioStore(self.db).upsert_partial_preview(
            portfolio_id=portfolio_id,
            proposal_id=proposal_id,
            choice_id=choice_id,
            snapshot=material,
            brief=store_material["brief"],
            verifier=store_material["verifier"],
            score=store_material["score"],
            generation_lineage=store_material["generationLineage"],
            status=store_material["status"],
            evidence=store_material["evidence"],
        )
        return material, readiness

    @staticmethod
    def _theme_completion_option(
        projection: dict[str, Any],
        *,
        proposal_choice_id: str,
        source_user_turn_id: str,
    ) -> Optional[dict[str, Any]]:
        action = projection.get("completionAction")
        if not isinstance(action, dict):
            return None
        completion_choice_id = str(action.get("choiceId") or "").strip()
        proposal_id = str(projection.get("proposalId") or "").strip()
        if not completion_choice_id or not proposal_id or not proposal_choice_id:
            return None
        return {
            "id": completion_choice_id,
            "action": "attempt_portfolio_theme_completion",
            "kind": "portfolio_theme_completion",
            "label": str(action.get("label") or "尝试补全主题"),
            "description": "只补证当前方案的餐饮与街区体验；单次最多 20 秒、4 次高德详情、2 次具体地点网页查询，正式行程零写入。",
            "sourceUserTurnId": source_user_turn_id,
            "planningSelectionRootTurnId": str(projection.get("planningSelectionRootTurnId") or source_user_turn_id),
            "rootPortfolioId": str(projection.get("rootPortfolioId") or ""),
            "proposalId": proposal_id,
            "proposalChoiceId": proposal_choice_id,
            "expectedBaseVersionId": projection.get("expectedBaseVersionId"),
            "requestedTheme": str(action.get("theme") or ""),
            "lifecycle": "offered",
        }

    @staticmethod
    def _theme_replacement_facts(snapshot: dict[str, Any]) -> list[dict[str, Any]]:
        hard_segments = [
            segment
            for day in snapshot.get("days") or []
            if isinstance(day, dict)
            for segment in day.get("segments") or []
            if isinstance(segment, dict)
            and str((segment.get("semanticMetadata") or {}).get("requirementLevel") or "") in {"hard", "required"}
            and str((segment.get("poi") or {}).get("amapId") or "")
        ]
        hard_coverage_count = len(hard_segments)
        facts: list[dict[str, Any]] = []
        for segment in hard_segments:
            metadata = segment.get("semanticMetadata") if isinstance(segment.get("semanticMetadata"), dict) else {}
            policy = metadata.get("replacementPolicy") if isinstance(metadata.get("replacementPolicy"), dict) else {}
            admission = (
                metadata.get("consumerAdmissionReport")
                if isinstance(metadata.get("consumerAdmissionReport"), dict)
                else {}
            )
            classification = str(admission.get("classification") or "")
            facts.append(
                {
                    "segmentId": str(segment.get("id") or ""),
                    "requirementLevel": str(metadata.get("requirementLevel") or ""),
                    "amapId": str((segment.get("poi") or {}).get("amapId") or ""),
                    "userLocked": bool(
                        metadata.get("userLocked") or metadata.get("userConfirmed") or segment.get("userLocked")
                    ),
                    "intentOccurrenceId": str(metadata.get("intentOccurrenceId") or metadata.get("occurrenceId") or ""),
                    "sameIntentOccurrence": policy.get("sameIntentOccurrence"),
                    "replacementAdmission": (
                        policy.get("replacementAdmission")
                        or (
                            "admitted"
                            if admission.get("scoreEligible") is True
                            or classification
                            in {
                                "admitted_final_anchor",
                                "admitted_anchor_set_member",
                            }
                            else ""
                        )
                    ),
                    "evidenceScore": (
                        policy.get("replacementEvidence")
                        if policy.get("replacementEvidence") is not None
                        else metadata.get("evidenceScore")
                    ),
                    "hardCoverageCount": policy.get("hardCoverageAfter", hard_coverage_count),
                    "scheduleFeasible": policy.get(
                        "scheduleStillFeasible",
                        metadata.get("scheduleFeasible"),
                    ),
                    "travelMinutesSaved": policy.get("travelMinutesSaved"),
                    "transfersReduced": policy.get("transfersReduced"),
                    "continuousWalkingKmReduced": policy.get("continuousWalkingKmReduced"),
                    "enablesThemeClosure": policy.get("enablesThemeClosure"),
                }
            )
        return facts

    def _execute_theme_completion_attempt(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict[str, Any],
        selected_choice: dict[str, Any],
    ) -> AgentMessageResponse:
        option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        source_user_turn_id = str(
            option.get("planningSelectionRootTurnId") or option.get("sourceUserTurnId") or ""
        ).strip()
        proposal_choice_id = str(option.get("proposalChoiceId") or "").strip()
        proposal_id = str(option.get("proposalId") or "").strip()
        portfolio_id = str(option.get("rootPortfolioId") or "").strip()
        requested_theme = str(option.get("requestedTheme") or "").strip()
        if (
            not source_user_turn_id
            or not proposal_choice_id
            or not proposal_id
            or not portfolio_id
            or requested_theme != CreativeOutputQualityService.THEME
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_completion_identity_invalid",
                    "message": "该主题补全操作缺少服务端方案身份，请使用最新方案。",
                },
            )
        current = self._session(session_id)
        active_version_id = str(current["active_version_id"] or "")
        expected_base = str(option.get("expectedBaseVersionId") or "")
        if expected_base != active_version_id:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_completion_base_stale",
                    "message": "该主题补全对应旧行程版本，未执行搜索或写入。",
                },
            )
        store = PlanPortfolioStore(self.db)
        loaded = store.load_choice(
            session_id=session_id,
            source_user_turn_id=source_user_turn_id,
            choice_id=proposal_choice_id,
        )
        if loaded is None:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_completion_source_missing",
                    "message": "该主题补全来源已失效，请重新生成方案。",
                },
            )
        portfolio_state, proposal = loaded
        if str(portfolio_state.get("id") or "") != portfolio_id or str(proposal.get("id") or "") != proposal_id:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_completion_identity_mismatch",
                    "message": "该主题补全与当前方案不一致，未执行搜索或写入。",
                },
            )
        claim = self._claim_fallback_choice_execution(session_id, user_turn_id, selected_choice)
        if claim["status"] == "succeeded":
            return self._replay_density_choice_execution(user_turn, current, selected_choice, claim)
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            "正在对所选方案执行一次有界主题补全。",
            "active",
            agent_request_json={
                "selectedAgentChoice": selected_choice,
                "themeCompletion": {
                    "proposalId": proposal_id,
                    "requestedTheme": requested_theme,
                },
            },
            agent_response_json={"mode": "portfolio_theme_completion", "reply": ""},
        )
        trace = AgentHarnessTrace(session_id, assistant_turn_id)
        before_version_count = int(
            self.db.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session_id,),
            ).fetchone()[0]
        )
        before_patch_count = int(
            self.db.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session_id,),
            ).fetchone()[0]
        )
        stored_snapshot = self._json_dict(proposal.get("snapshot_json"))
        if active_version_id:
            version_row = self._version(active_version_id, session_id, current["active_plan_id"])
            active_snapshot = self._json_dict(version_row["snapshot_json"])
            if str(portfolio_state.get("selected_proposal_id") or "") == proposal_id:
                # The active skeleton is authoritative after adoption, while
                # proposal-only candidate evidence remains reusable.
                candidate_material = copy.deepcopy(stored_snapshot.get("portfolioThemeCompletionCandidates") or {})
                stored_snapshot = active_snapshot
                if candidate_material:
                    stored_snapshot["portfolioThemeCompletionCandidates"] = candidate_material
        completion_candidates = (
            stored_snapshot.get("portfolioThemeCompletionCandidates")
            if isinstance(stored_snapshot.get("portfolioThemeCompletionCandidates"), dict)
            else {}
        )
        meal_candidates = completion_candidates.get("mealCandidatesBySlot")
        meal_candidates = meal_candidates if isinstance(meal_candidates, dict) else {}
        area_candidates = completion_candidates.get("areaCandidates")
        area_candidates = area_candidates if isinstance(area_candidates, list) else []
        continuation = (
            stored_snapshot.get("continuationTheme")
            if isinstance(stored_snapshot.get("continuationTheme"), dict)
            else {}
        )
        attempt_count = int(continuation.get("completionAttemptCount") or 0) + 1
        attempt_id = f"theme_completion_{uuid4().hex[:16]}"
        completion_budget = AmapCallBudget(
            place_text_max=4,
            place_around_max=0,
            route_refresh_max=8,
            total_external_max=12,
            source="portfolio_theme_completion",
        )
        admission_service = ConsumerCandidateAdmissionService()

        def detail_fetcher(candidate: dict[str, Any]) -> dict[str, Any]:
            amap_id = str(candidate.get("amapId") or candidate.get("id") or "")
            detail = self.map_poi_service.detail(amap_id)
            payload = detail.model_dump(by_alias=True)
            return {
                **candidate,
                **payload,
                "id": detail.id,
                "amapId": detail.id,
                "source": AMAP_PLACE_SOURCE,
            }

        def identity_web_fetcher(candidate: dict[str, Any]) -> dict[str, Any]:
            name = str(candidate.get("name") or "").strip()
            city = str(candidate.get("city") or current["city"] or "").strip()
            address = str(
                candidate.get("address") or candidate.get("district") or candidate.get("businessArea") or ""
            ).strip()
            if not name or not city:
                return {"identityBound": False, "amapId": candidate.get("amapId")}
            response = ResilientWebSearchProvider().search(
                " ".join(item for item in (f'"{name}"', address, city) if item),
                count=3,
                freshness="noLimit",
            )
            if not response.results and response.failure_reason:
                raise RuntimeError("identity_web_provider_failed")
            name_key = re.sub(r"\s+", "", name).casefold()
            location_terms = [
                re.sub(r"\s+", "", item).casefold()
                for item in (city, address, str(candidate.get("district") or ""))
                if len(str(item).strip()) >= 2
            ]
            matched = next(
                (
                    item
                    for item in response.results
                    if name_key in re.sub(r"\s+", "", f"{item.title} {item.snippet}").casefold()
                    and any(
                        term in re.sub(r"\s+", "", f"{item.title} {item.snippet}").casefold() for term in location_terms
                    )
                ),
                None,
            )
            return {
                "identityBound": matched is not None,
                "amapId": candidate.get("amapId"),
                "sourceName": matched.source_name if matched is not None else None,
                "claimText": str(matched.snippet or "")[:300] if matched is not None else "",
                "queriedAt": matched.queried_at.isoformat() if matched is not None else response.queried_at.isoformat(),
                "semanticClaimTtlDays": 30,
            }

        def admission(candidate: dict[str, Any]) -> bool:
            consumer = (
                candidate.get("consumerAdmissionInput")
                if isinstance(candidate.get("consumerAdmissionInput"), dict)
                else {}
            )
            if not consumer:
                return False
            report = admission_service.evaluate(candidate, consumer)
            candidate["consumerAdmissionReport"] = report
            return bool(
                report.get("scoreEligible") is True
                or str(report.get("classification") or "") in {"admitted_final_anchor", "admitted_anchor_set_member"}
            )

        replacement_before_snapshot = copy.deepcopy(stored_snapshot)
        replacement_preview: dict[str, Any] = {
            "requiresConfirmation": False,
            "hardReplacements": [],
            "blockedHardReplacements": [],
            "writeAuthority": "none",
            "versionWriteCount": 0,
            "patchWriteCount": 0,
        }
        try:
            with amap_call_budget_scope(completion_budget):
                completion_result = CreativeThemeCompletionService(ThemeCompletionBudget()).complete(
                    meal_candidates_by_slot={
                        str(slot): [dict(item) for item in rows if isinstance(item, dict)]
                        for slot, rows in meal_candidates.items()
                        if isinstance(rows, list)
                    },
                    area_candidates=[dict(item) for item in area_candidates if isinstance(item, dict)],
                    detail_fetcher=detail_fetcher,
                    identity_web_fetcher=identity_web_fetcher,
                    admission=admission,
                    attempt_id=attempt_id,
                    attempt_count=attempt_count,
                )
                completed_snapshot, added_segment_ids = CreativeThemeCompletionService.apply_admitted_additions(
                    stored_snapshot,
                    completion_result.get("admittedAdditions") or [],
                )
                if added_segment_ids:
                    route_result = self.portfolio_route_feasibility_service.prepare(
                        completed_snapshot,
                        city=str(current["city"] or ""),
                        transport_mode=str(completed_snapshot.get("portfolioTransportPreference") or "transit"),
                        allow_nearby_search=False,
                        preview_id=f"{attempt_id}_route",
                    )
                    completed_snapshot = copy.deepcopy(route_result.snapshot)
                else:
                    route_result = None
                replacement_preview = CreativeThemeCompletionService.replacement_diff(
                    before=self._theme_replacement_facts(replacement_before_snapshot),
                    after=self._theme_replacement_facts(completed_snapshot),
                )
                if replacement_preview.get("blockedHardReplacements"):
                    completed_snapshot = CreativeThemeCompletionService.reject_hard_replacements(
                        before_snapshot=replacement_before_snapshot,
                        proposed_snapshot=completed_snapshot,
                    )
                    route_result = self.portfolio_route_feasibility_service.prepare(
                        completed_snapshot,
                        city=str(current["city"] or ""),
                        transport_mode=str(completed_snapshot.get("portfolioTransportPreference") or "transit"),
                        allow_nearby_search=False,
                        preview_id=f"{attempt_id}_blocked_replacement_route",
                    )
                    completed_snapshot = copy.deepcopy(route_result.snapshot)
        except Exception as error:
            self._finish_fallback_choice_execution(claim["id"], "failed_retryable", error=error)
            self.db.execute(
                "UPDATE conversation_turns SET status = 'failed', content = ?, error_json = ?, updated_at = ? WHERE id = ?",
                (
                    "主题补全未完成，正式行程未发生变化。",
                    json.dumps(
                        {
                            "code": "portfolio_theme_completion_failed",
                            "reasonCode": "completion_runtime_failed",
                        },
                        ensure_ascii=False,
                    ),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            self.db.commit()
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_completion_failed",
                    "message": "主题补全未完成，正式行程未发生变化。",
                },
            ) from error
        verifier = self._json_dict(proposal.get("verifier_json"))
        source_row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ?",
            (str(portfolio_state.get("source_assistant_turn_id") or ""), session_id),
        ).fetchone()
        source_payload = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
        ledger_payload = source_payload.get("constraintLedger")
        if not isinstance(ledger_payload, dict):
            pipeline = (
                source_payload.get("pipelineContext") if isinstance(source_payload.get("pipelineContext"), dict) else {}
            )
            ledger_payload = pipeline.get("constraintLedger")
        try:
            if isinstance(ledger_payload, dict):
                verifier = PlanProposalVerifier(experience_grounding_v2_mode=self.experience_grounding_v2_mode).verify(
                    completed_snapshot,
                    ConstraintLedger.model_validate(ledger_payload),
                    CreativeBrief.model_validate(self._json_dict(proposal.get("brief_json"))),
                )
        except (TypeError, ValueError, ValidationError):
            verifier = self._json_dict(proposal.get("verifier_json"))
        completed_snapshot["portfolioVerifier"] = copy.deepcopy(verifier)
        completed_snapshot = self._with_verified_proposal_title(
            completed_snapshot,
            brief=self._json_dict(proposal.get("brief_json")),
            store=store,
            portfolio_id=portfolio_id,
            proposal_id=proposal_id,
        )
        quality = CreativeOutputQualityService.evaluate(completed_snapshot, requested_theme=requested_theme)
        output_contract = (
            completed_snapshot.get("portfolioOutputQuality")
            if isinstance(completed_snapshot.get("portfolioOutputQuality"), dict)
            else {"schemaVersion": "creative-output-quality-v2", "mode": self.creative_output_quality_v2_mode}
        )
        output_contract.update(copy.deepcopy(quality))
        completed_snapshot["portfolioOutputQuality"] = output_contract
        completed_snapshot["title"] = str(
            quality.get("displayTitle")
            or completed_snapshot.get("title")
            or output_contract.get("originalCreativeTitle")
            or "行程方案"
        )
        completed_snapshot["continuationTheme"] = {
            **copy.deepcopy(continuation),
            "theme": requested_theme,
            "status": "complete" if quality.get("themeEligible") is True else "selected_but_incomplete",
            "completionAttemptCount": attempt_count,
            "lastAttemptId": attempt_id,
            "lastTerminalStatus": completion_result.get("status"),
            "lastReasonCode": completion_result.get("reasonCode"),
            "lastBudget": copy.deepcopy(completion_result.get("trace") or {}),
            "continuationLineagePreserved": True,
            "originalBriefId": str((self._json_dict(proposal.get("brief_json"))).get("briefId") or ""),
            "intentFingerprint": str(
                continuation.get("intentFingerprint") or portfolio_state.get("request_contract_fingerprint") or ""
            ),
        }
        readiness = ProposalReadinessService.compute(completed_snapshot, verifier=verifier)
        status = (
            "committed"
            if active_version_id
            else "adoption_ready"
            if readiness.get("adoptionReady") is True
            else "blocked"
            if "proposal_title_generation_pending" in set(readiness.get("blockingReasons") or [])
            else "route_provider_failed"
            if readiness.get("routeStatus") == "route_provider_failed"
            else "route_partial"
            if readiness.get("routeStatus") == "route_partial"
            else "route_pending"
        )
        prior_evidence = self._json_dict(proposal.get("evidence_json"))
        completion_evidence = {
            **prior_evidence,
            "themeCompletion": {
                "attemptId": attempt_id,
                "status": completion_result.get("status"),
                "reasonCode": completion_result.get("reasonCode"),
                "trace": copy.deepcopy(completion_result.get("trace") or {}),
                "addedSegmentIds": added_segment_ids,
                "themeEligible": quality.get("themeEligible") is True,
                "replacementPreview": {
                    **copy.deepcopy(replacement_preview),
                    **(
                        {"beforeSnapshot": copy.deepcopy(replacement_before_snapshot)}
                        if replacement_preview.get("requiresConfirmation")
                        else {}
                    ),
                },
                "versionWriteCount": 0,
                "patchWriteCount": 0,
            },
            "readiness": copy.deepcopy(readiness),
        }
        store.update_proposal_material(
            portfolio_id=portfolio_id,
            proposal_id=proposal_id,
            snapshot=completed_snapshot,
            verifier=verifier,
            status=status,
            evidence=completion_evidence,
        )
        after_version_count = int(
            self.db.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session_id,),
            ).fetchone()[0]
        )
        after_patch_count = int(
            self.db.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session_id,),
            ).fetchone()[0]
        )
        if after_version_count != before_version_count or after_patch_count != before_patch_count:
            raise RuntimeError("theme_completion_formal_write_detected")
        projection = PlanComparisonPreviewService.project_snapshot(
            completed_snapshot,
            planning_selection_root_turn_id=source_user_turn_id,
            root_portfolio_id=portfolio_id,
            proposal_id=proposal_id,
            source_assistant_turn_id=assistant_turn_id,
            choice_id=proposal_choice_id,
            active_version_id=active_version_id or None,
            expected_base_version_id=active_version_id or None,
            is_partial=bool(readiness.get("isPartial")),
            is_adopted=bool(active_version_id),
            adoption_ready=bool(readiness.get("adoptionReady")),
        )
        next_choices: list[dict[str, Any]] = []
        replacement_confirmation_required = replacement_preview.get("requiresConfirmation") is True
        if replacement_confirmation_required:
            common_replacement_choice = {
                "sourceUserTurnId": source_user_turn_id,
                "planningSelectionRootTurnId": source_user_turn_id,
                "rootPortfolioId": portfolio_id,
                "proposalId": proposal_id,
                "proposalChoiceId": proposal_choice_id,
                "expectedBaseVersionId": active_version_id or None,
                "attemptId": attempt_id,
                "lifecycle": "offered",
            }
            next_choices.extend(
                [
                    {
                        **common_replacement_choice,
                        "id": f"portfolio_theme_replacement_confirm_{proposal_id}_{attempt_id}",
                        "action": "confirm_portfolio_theme_replacement",
                        "kind": "portfolio_theme_replacement_confirmation",
                        "label": "确认地点替换与主题补全",
                        "description": "先重新核验替换、路线和严格门槛；全部通过后由现有 Single-Writer exactly-one 写入。",
                    },
                    {
                        **common_replacement_choice,
                        "id": f"portfolio_theme_replacement_reject_{proposal_id}_{attempt_id}",
                        "action": "reject_portfolio_theme_replacement",
                        "kind": "portfolio_theme_replacement_rejection",
                        "label": "保留原地点",
                        "description": "撤销 hard 地点替换，保留仍兼容的已准入新增地点并重新核验路线；正式行程零写入。",
                    },
                ]
            )
        elif (
            active_version_id
            and added_segment_ids
            and quality.get("themeEligible") is True
            and readiness.get("adoptionReady") is True
        ):
            next_choices.append(
                {
                    "id": f"portfolio_theme_upgrade_{proposal_id}_{attempt_id}",
                    "action": "confirm_portfolio_theme_upgrade",
                    "kind": "portfolio_theme_upgrade_confirmation",
                    "label": "确认主题升级",
                    "description": "确认后由现有版本化写入器一次提交新增地点、路线和标题；预览阶段尚未写入。",
                    "sourceUserTurnId": source_user_turn_id,
                    "planningSelectionRootTurnId": source_user_turn_id,
                    "rootPortfolioId": portfolio_id,
                    "proposalId": proposal_id,
                    "proposalChoiceId": proposal_choice_id,
                    "expectedBaseVersionId": active_version_id,
                    "attemptId": attempt_id,
                    "lifecycle": "offered",
                }
            )
        elif not active_version_id and readiness.get("adoptionReady") is True:
            next_choices.append(
                {
                    "id": proposal_choice_id,
                    "action": "select_plan_proposal",
                    "kind": "plan_proposal",
                    "label": str(projection.get("nextActionLabel") or "采用此方案"),
                    "description": "补全结果已保存在 proposal；采用时仍由现有 Single-Writer 重新核验并 exactly-one write。",
                    "sourceUserTurnId": source_user_turn_id,
                    "planningSelectionRootTurnId": source_user_turn_id,
                    "rootPortfolioId": portfolio_id,
                    "expectedBaseVersionId": None,
                    "comparisonProjection": copy.deepcopy(projection),
                    "lifecycle": "offered",
                }
            )
        if not replacement_confirmation_required and quality.get("themeEligible") is not True:
            continuation_choice = self._theme_completion_option(
                projection,
                proposal_choice_id=proposal_choice_id,
                source_user_turn_id=source_user_turn_id,
            )
            if continuation_choice is not None:
                continuation_choice["label"] = "继续搜索同一主题"
                next_choices.append(continuation_choice)
        status_text = str(completion_result.get("status") or "precondition_failed")
        reply = {
            "completed": "主题补全证据已完成；正式行程仍未写入，请确认采用或升级。",
            "partial_but_theme_ineligible": "本轮补全保留了已通过的新地点，但主题门槛仍未完全成立；其余体验继续待选。",
            "provider_failed": "本轮具体地点补证服务失败；没有伪造地点，正式行程未变化。",
            "budget_exhausted": "本轮有界补全额度已用完；已通过的地点已保留，其余继续待选。",
            "deadline_reached": "本轮 20 秒补全截止；已通过的地点已保留，其余继续待选。",
            "precondition_failed": "当前 proposal 没有可安全补证的具体 AMap 候选；正式行程未变化。",
        }.get(status_text, "主题补全已结束；正式行程未变化。")
        events = [
            trace.event(
                "theme_completion_attempt_completed",
                "主题补全尝试结束",
                status="completed" if status_text in {"completed", "partial_but_theme_ineligible"} else "failed",
                detail=reply,
                provider_name="amap-place-search/web-search/route-service",
                metadata={
                    **copy.deepcopy(completion_result.get("trace") or {}),
                    "themeCompletionTerminalStatus": status_text,
                    "reasonCode": completion_result.get("reasonCode"),
                    "addedSegmentCount": len(added_segment_ids),
                    "themeEligible": quality.get("themeEligible") is True,
                    "proposalPreviewWriteCount": 0,
                    "themeCompletionWriteCount": 0,
                    "versionDelta": 0,
                    "patchDelta": 0,
                },
            ),
            trace.respond("completed", reply, metadata={"versionDelta": 0, "patchDelta": 0}),
        ]
        response_payload = {
            "mode": "portfolio_theme_completion",
            "reply": reply,
            "choiceOptions": next_choices,
            "comparisonProjections": [projection],
            "comparisonProjectionUpdateMode": "replace",
            "themeCompletion": completion_evidence["themeCompletion"],
            "terminalStatus": "needs_confirmation",
            "versionDelta": 0,
            "patchDelta": 0,
            "routeWriteDelta": 0,
        }
        self.db.execute(
            "UPDATE conversation_turns SET content = ?, agent_response_json = ?, updated_at = ? WHERE id = ?",
            (
                reply,
                json.dumps(response_payload, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                assistant_turn_id,
            ),
        )
        self._store_planning_events(assistant_turn_id, events)
        self._finish_fallback_choice_execution(
            claim["id"],
            "succeeded",
            execution_turn_id=assistant_turn_id,
            outcome={
                "attemptId": attempt_id,
                "proposalId": proposal_id,
                "status": status_text,
                "versionDelta": 0,
                "patchDelta": 0,
            },
        )
        self._consume_selected_agent_choice(session_id, selected_choice)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=ItineraryService(self.db).get_plan(current["active_plan_id"]),
            version=(
                self._version_response(self._version(active_version_id, session_id, current["active_plan_id"]))
                if active_version_id
                else None
            ),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=[],
            planningRun=None,
            planningSteps=events,
            toolEvents=events,
            terminalStatus="needs_confirmation",
        )

    def _theme_completion_confirmation_material(
        self,
        *,
        session_id: str,
        selected_choice: dict[str, Any],
    ) -> dict[str, Any]:
        option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        source_user_turn_id = str(
            option.get("planningSelectionRootTurnId") or option.get("sourceUserTurnId") or ""
        ).strip()
        proposal_choice_id = str(option.get("proposalChoiceId") or "").strip()
        proposal_id = str(option.get("proposalId") or "").strip()
        portfolio_id = str(option.get("rootPortfolioId") or "").strip()
        attempt_id = str(option.get("attemptId") or "").strip()
        if not all(
            (
                source_user_turn_id,
                proposal_choice_id,
                proposal_id,
                portfolio_id,
                attempt_id,
            )
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_confirmation_identity_invalid",
                    "message": "主题确认缺少服务端 proposal 身份，未执行写入。",
                },
            )
        current = self._session(session_id)
        expected_base = str(option.get("expectedBaseVersionId") or "")
        if expected_base != str(current["active_version_id"] or ""):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_confirmation_base_stale",
                    "message": "主题确认对应旧行程版本，未执行写入。",
                },
            )
        store = PlanPortfolioStore(self.db)
        loaded = store.load_choice(
            session_id=session_id,
            source_user_turn_id=source_user_turn_id,
            choice_id=proposal_choice_id,
        )
        if loaded is None:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_confirmation_source_missing",
                    "message": "主题补全 proposal 已失效，未执行写入。",
                },
            )
        portfolio_state, proposal = loaded
        if str(portfolio_state.get("id") or "") != portfolio_id or str(proposal.get("id") or "") != proposal_id:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_confirmation_identity_mismatch",
                    "message": "主题确认与当前 proposal 不一致，未执行写入。",
                },
            )
        evidence = self._json_dict(proposal.get("evidence_json"))
        completion = evidence.get("themeCompletion") if isinstance(evidence.get("themeCompletion"), dict) else {}
        if str(completion.get("attemptId") or "") != attempt_id:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_confirmation_attempt_stale",
                    "message": "已有更新的主题补全结果，本次确认未执行写入。",
                },
            )
        replacement_preview = (
            completion.get("replacementPreview") if isinstance(completion.get("replacementPreview"), dict) else {}
        )
        return {
            "option": option,
            "current": current,
            "store": store,
            "portfolio": portfolio_state,
            "proposal": proposal,
            "snapshot": self._json_dict(proposal.get("snapshot_json")),
            "evidence": evidence,
            "completion": completion,
            "replacementPreview": replacement_preview,
            "sourceUserTurnId": source_user_turn_id,
            "proposalChoiceId": proposal_choice_id,
            "proposalId": proposal_id,
            "portfolioId": portfolio_id,
            "attemptId": attempt_id,
        }

    def _with_verified_proposal_title(
        self,
        snapshot: dict[str, Any],
        *,
        brief: Union[CreativeBrief, dict[str, Any]],
        store: Optional[PlanPortfolioStore],
        portfolio_id: str,
        proposal_id: str,
    ) -> dict[str, Any]:
        """Preserve or regenerate a title only after strict re-verification."""

        verifier = snapshot.get("portfolioVerifier") if isinstance(snapshot.get("portfolioVerifier"), dict) else {}
        if verifier.get("passed") is not True:
            return snapshot
        existing_projection = snapshot.get("portfolioTitleEvidence")
        if CreativeProposalTitleService.is_valid_agent_projection(snapshot, existing_projection):
            material = copy.deepcopy(snapshot)
            material["portfolioTitleGeneration"] = {
                "schemaVersion": CreativeProposalTitleService.AGENT_GENERATION_STATUS_SCHEMA,
                "status": "succeeded",
                "retryable": False,
                "candidateCount": len(existing_projection.get("validCandidates") or []),
                "evidenceFingerprint": existing_projection.get("evidenceFingerprint"),
                "reasonCode": None,
            }
            return material

        generator = getattr(self.provider, "generate_proposal_titles", None)
        if not callable(generator):
            return CreativeProposalTitleService.with_server_fallback_title(
                snapshot,
                reason_code="title_provider_unavailable",
            )

        reserved_titles: set[str] = set()
        if store is not None and portfolio_id:
            try:
                reserved_titles = {
                    str(item.get("title") or "").strip()
                    for item in store.visible_comparison_projections(portfolio_id=portfolio_id)
                    if isinstance(item, dict)
                    and str(item.get("proposalId") or "") != proposal_id
                    and str(item.get("title") or "").strip()
                }
            except Exception:
                reserved_titles = set()

        if isinstance(brief, CreativeBrief):
            primary_axis = brief.primary_axis
            secondary_axes = brief.secondary_axes
            optional_experiences = [item.family for item in brief.optional_experiences]
        else:
            primary_axis = str(brief.get("primaryAxis") or brief.get("primary_axis") or "")
            secondary_axes = brief.get("secondaryAxes") or brief.get("secondary_axes") or []
            optional_experiences = [
                str(item.get("family") or "")
                for item in brief.get("optionalExperiences") or brief.get("optional_experiences") or []
                if isinstance(item, dict) and str(item.get("family") or "")
            ]
        context = CreativeProposalTitleService.agent_generation_context(
            snapshot,
            city=str(snapshot.get("city") or ""),
            primary_axis=primary_axis,
            secondary_axes=secondary_axes,
            optional_experiences=optional_experiences,
            reserved_titles=reserved_titles,
        )
        return CreativeProposalTitleService.generate_and_apply_agent_title(
            snapshot,
            generator=generator,
            context=context,
            reserved_titles=reserved_titles,
        )

    def _with_simple_direction_title(
        self,
        snapshot: dict[str, Any],
        *,
        store: PlanPortfolioStore,
        portfolio_id: str,
    ) -> dict[str, Any]:
        """Run one fact-bound naming attempt without making title a readiness gate."""

        material = copy.deepcopy(snapshot)
        existing = material.get("portfolioTitleEvidence")
        if CreativeProposalTitleService.is_valid_agent_projection(material, existing):
            return material
        reserved_titles: set[str] = set()
        if portfolio_id:
            reserved_titles = {
                str(item.get("title") or "").strip()
                for item in store.visible_comparison_projections(portfolio_id=portfolio_id)
                if isinstance(item, dict) and str(item.get("title") or "").strip()
            }
        if CreativeProposalTitleService.is_valid_server_fallback_title(
            material,
            reserved_titles=reserved_titles,
        ):
            return material
        intents = {
            str(metadata.get("intentType") or "").strip()
            for day in material.get("days") or []
            if isinstance(day, dict)
            for segment in day.get("segments") or []
            if isinstance(segment, dict)
            for metadata in [
                segment.get("semanticMetadata") if isinstance(segment.get("semanticMetadata"), dict) else {}
            ]
            if str(metadata.get("intentType") or "").strip()
        }
        generator = getattr(self.provider, "generate_proposal_titles", None)
        if not callable(generator):
            return CreativeProposalTitleService.with_server_fallback_title(
                material,
                reason_code="title_provider_unavailable",
                reserved_titles=reserved_titles,
            )
        context = CreativeProposalTitleService.agent_generation_context(
            material,
            city=str(material.get("city") or ""),
            primary_axis="dynamic_simple_direction",
            secondary_axes=sorted(intents),
            reserved_titles=reserved_titles,
        )
        titled = CreativeProposalTitleService.generate_and_apply_agent_title(
            material,
            generator=generator,
            context=context,
            reserved_titles=reserved_titles,
        )
        generation = (
            titled.get("portfolioTitleGeneration") if isinstance(titled.get("portfolioTitleGeneration"), dict) else {}
        )
        if generation.get("status") == "succeeded":
            return titled
        return CreativeProposalTitleService.with_server_fallback_title(
            material,
            reason_code=str(generation.get("reasonCode") or "title_candidates_invalid"),
            failure_type=str(generation.get("failureType") or ""),
            reserved_titles=reserved_titles,
        )

    def _theme_completion_reverify(
        self,
        *,
        material: dict[str, Any],
        preview_id: str,
        require_adoption_ready: bool = True,
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any]]:
        current = material["current"]
        proposal = material["proposal"]
        portfolio_state = material["portfolio"]
        snapshot = copy.deepcopy(material["snapshot"])
        route_result = self.portfolio_route_feasibility_service.verify_snapshot(
            snapshot,
            city=str(current["city"] or ""),
            transport_mode=str(snapshot.get("portfolioTransportPreference") or "transit"),
            preview_id=preview_id,
        )
        snapshot = copy.deepcopy(route_result.snapshot)
        source_row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ? AND role = 'assistant'",
            (
                str(portfolio_state.get("source_assistant_turn_id") or ""),
                str(current["id"]),
            ),
        ).fetchone()
        source_payload = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
        ledger_payload = source_payload.get("constraintLedger")
        if not isinstance(ledger_payload, dict):
            pipeline = (
                source_payload.get("pipelineContext") if isinstance(source_payload.get("pipelineContext"), dict) else {}
            )
            ledger_payload = pipeline.get("constraintLedger")
        try:
            ledger = ConstraintLedger.model_validate(ledger_payload)
            brief = CreativeBrief.model_validate(self._json_dict(proposal.get("brief_json")))
        except (TypeError, ValueError, ValidationError) as error:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_confirmation_contract_missing",
                    "message": "主题补全来源合同不完整，未执行写入。",
                },
            ) from error
        verifier = PlanProposalVerifier(experience_grounding_v2_mode=self.experience_grounding_v2_mode).verify(
            snapshot, ledger, brief
        )
        snapshot["portfolioVerifier"] = copy.deepcopy(verifier)
        snapshot = self._with_verified_proposal_title(
            snapshot,
            brief=brief,
            store=material.get("store"),
            portfolio_id=str(material.get("portfolioId") or ""),
            proposal_id=str(material.get("proposalId") or ""),
        )
        quality = CreativeOutputQualityService.evaluate(
            snapshot,
            requested_theme=CreativeOutputQualityService.THEME,
        )
        output_contract = (
            snapshot.get("portfolioOutputQuality")
            if isinstance(snapshot.get("portfolioOutputQuality"), dict)
            else {
                "schemaVersion": "creative-output-quality-v2",
                "mode": self.creative_output_quality_v2_mode,
            }
        )
        output_contract.update(copy.deepcopy(quality))
        snapshot["portfolioOutputQuality"] = output_contract
        snapshot["title"] = str(
            quality.get("displayTitle")
            or snapshot.get("title")
            or output_contract.get("originalCreativeTitle")
            or "行程方案"
        )
        readiness = ProposalReadinessService.compute(snapshot, verifier=verifier)
        if require_adoption_ready and (route_result.passed is not True or readiness.get("adoptionReady") is not True):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_confirmation_readiness_blocked",
                    "message": "主题补全的路线或严格采用条件未通过，未执行写入。",
                    "details": {
                        "routeExecutionLedger": route_result.route_execution_ledger,
                        "blockingReasons": readiness.get("blockingReasons"),
                    },
                },
            )
        return snapshot, verifier, readiness, quality

    def _execute_theme_completion_confirmation(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict[str, Any],
        selected_choice: dict[str, Any],
    ) -> AgentMessageResponse:
        del session
        claim = self._claim_fallback_choice_execution(session_id, user_turn_id, selected_choice)
        current = self._session(session_id)
        if claim["status"] == "succeeded":
            return self._replay_fallback_choice_execution(user_turn, current, selected_choice, claim)
        try:
            material = self._theme_completion_confirmation_material(
                session_id=session_id,
                selected_choice=selected_choice,
            )
            action = str(selected_choice.get("action") or "")
            replacement_preview = material["replacementPreview"]
            if action == "confirm_portfolio_theme_replacement":
                before_snapshot = replacement_preview.get("beforeSnapshot")
                if replacement_preview.get("requiresConfirmation") is not True or not isinstance(before_snapshot, dict):
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "portfolio_theme_replacement_preview_missing",
                            "message": "没有可确认的 hard 地点替换，未执行写入。",
                        },
                    )
                current_diff = CreativeThemeCompletionService.replacement_diff(
                    before=self._theme_replacement_facts(before_snapshot),
                    after=self._theme_replacement_facts(material["snapshot"]),
                )
                if current_diff.get("requiresConfirmation") is not True or current_diff.get("blockedHardReplacements"):
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "portfolio_theme_replacement_policy_failed",
                            "message": "hard 地点替换已不满足严格策略，未执行写入。",
                        },
                    )
            elif replacement_preview.get("requiresConfirmation") is True:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "portfolio_theme_upgrade_replacement_unconfirmed",
                        "message": "该升级包含 hard 地点替换，必须使用替换确认操作。",
                    },
                )

            snapshot, verifier, readiness, quality = self._theme_completion_reverify(
                material=material,
                preview_id=(f"theme_confirmation_{material['attemptId']}"),
            )
            if action == "confirm_portfolio_theme_upgrade" and quality.get("themeEligible") is not True:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "portfolio_theme_upgrade_ineligible",
                        "message": "严格主题尚未成立，未执行标题升级或写入。",
                    },
                )
            material["snapshot"] = snapshot
            material["store"].update_proposal_material(
                portfolio_id=material["portfolioId"],
                proposal_id=material["proposalId"],
                snapshot=snapshot,
                verifier=verifier,
                status=("committed" if material["current"]["active_version_id"] else "adoption_ready"),
                evidence={
                    **material["evidence"],
                    "readiness": copy.deepcopy(readiness),
                },
            )

            if not material["current"]["active_version_id"]:
                synthetic_choice = {
                    "sourceAssistantTurnId": str(material["portfolio"].get("source_assistant_turn_id") or ""),
                    "choiceId": material["proposalChoiceId"],
                    "requestChoiceId": material["proposalChoiceId"],
                    "persistedChoiceId": material["proposalChoiceId"],
                    "action": "select_plan_proposal",
                    "persistedChoiceAction": "select_plan_proposal",
                    "option": {
                        "id": material["proposalChoiceId"],
                        "action": "select_plan_proposal",
                        "sourceUserTurnId": material["sourceUserTurnId"],
                        "planningSelectionRootTurnId": material["sourceUserTurnId"],
                        "rootPortfolioId": material["portfolioId"],
                        "expectedBaseVersionId": None,
                    },
                }
                response = self._execute_selected_plan_proposal(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    user_turn=user_turn,
                    session=material["current"],
                    request_context=request_context,
                    selected_choice=synthetic_choice,
                )
                result_version_id = response.version.id if response.version is not None else None
                if not result_version_id:
                    raise RuntimeError("portfolio_theme_confirmation_missing_result_version")
                self._finish_fallback_choice_execution(
                    claim["id"],
                    "succeeded",
                    result_version_id=result_version_id,
                    execution_turn_id=response.assistant_turn.id,
                    outcome={
                        "resultVersionId": result_version_id,
                        "proposalId": material["proposalId"],
                        "attemptId": material["attemptId"],
                        "versionDelta": 1,
                        "patchDelta": 1,
                    },
                )
                self._consume_selected_agent_choice(session_id, selected_choice)
                self.db.commit()
                return response

            assistant_turn_id = self._insert_turn(
                session_id,
                "assistant",
                "正在重新核验并提交主题升级。",
                "active",
                agent_request_json={
                    "selectedAgentChoice": selected_choice,
                    "themeCompletionAttemptId": material["attemptId"],
                },
                agent_response_json={
                    "mode": "portfolio_theme_confirmation",
                    "reply": "",
                },
            )
            before = self._session(session_id)
            version_count_before = int(
                self.db.execute(
                    "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                    (session_id,),
                ).fetchone()[0]
            )
            patch_count_before = int(
                self.db.execute(
                    "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                    (session_id,),
                ).fetchone()[0]
            )
            result = None
            try:
                result = ItineraryPatchService(self.db).apply_patch(
                    before["active_plan_id"],
                    [
                        ItineraryPatchOperation(
                            op="replace_itinerary",
                            fullItinerary=snapshot,
                        )
                    ],
                    source_type="agent",
                    base_version_id=before["active_version_id"],
                    source_turn_id=assistant_turn_id,
                    preference_summary="",
                    planning_context={
                        **request_context,
                        "portfolioCommit": True,
                        "portfolioThemeUpgrade": True,
                        "portfolioAdoptionMode": readiness.get("adoptionMode"),
                        "portfolioDraftAdoptionReady": (readiness.get("draftAdoptionReady") is True),
                        "skipOptionalToolRefresh": True,
                        "compactRouteModes": True,
                        "toolRefreshPolicy": {"route": "full"},
                        "preferredRouteMode": (
                            "transit"
                            if snapshot.get("portfolioTransportPreference") == "public_transit"
                            else snapshot.get("portfolioTransportPreference")
                        ),
                    },
                )
                report = AgentVerifierService(self.db).verify_agent_write(
                    session_id,
                    before["active_plan_id"],
                    result.version.id,
                    result.patch.id,
                    planning_context={
                        **request_context,
                        "portfolioCommit": True,
                        "portfolioThemeUpgrade": True,
                        "portfolioAdoptionMode": readiness.get("adoptionMode"),
                        "portfolioDraftAdoptionReady": (readiness.get("draftAdoptionReady") is True),
                    },
                )
                if not report.passed:
                    raise ValueError(
                        "portfolio_theme_confirmation_verifier_failed:"
                        + ",".join(str(item) for item in report.hard_failures)
                    )
                version_count_after = int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                        (session_id,),
                    ).fetchone()[0]
                )
                patch_count_after = int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                        (session_id,),
                    ).fetchone()[0]
                )
                if version_count_after - version_count_before != 1 or patch_count_after - patch_count_before != 1:
                    raise RuntimeError("portfolio_theme_confirmation_write_count_invalid")
            except Exception as error:
                self._restore_previous_active_state(before)
                if result is not None:
                    self._discard_portfolio_commit_artifacts(
                        session_id=session_id,
                        plan_id=str(before["active_plan_id"]),
                        patch_id=str(result.patch.id),
                        version_id=str(result.version.id),
                        source_turn_id=assistant_turn_id,
                    )
                self.db.execute(
                    "DELETE FROM itinerary_patches WHERE source_turn_id = ? AND result_version_id IS NULL",
                    (assistant_turn_id,),
                )
                self.db.execute(
                    "UPDATE conversation_turns SET status = 'failed', content = ?, "
                    "error_json = ?, updated_at = ? WHERE id = ?",
                    (
                        "主题升级未通过最终核验，当前行程保持不变。",
                        json.dumps(
                            {
                                "code": "portfolio_theme_confirmation_failed",
                                "reasonCode": self._error_message(error),
                            },
                            ensure_ascii=False,
                        ),
                        datetime.now(timezone.utc).isoformat(),
                        assistant_turn_id,
                    ),
                )
                self._finish_fallback_choice_execution(claim["id"], "failed_retryable", error=error)
                self.db.commit()
                if isinstance(error, HTTPException):
                    raise
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "portfolio_theme_confirmation_failed",
                        "message": "主题升级未通过最终核验，当前行程保持不变。",
                    },
                ) from error

            completion = copy.deepcopy(material["completion"])
            completion["confirmedAt"] = datetime.now(timezone.utc).isoformat()
            completion["confirmationAction"] = action
            completion["versionWriteCount"] = 1
            completion["patchWriteCount"] = 1
            material["store"].update_proposal_material(
                portfolio_id=material["portfolioId"],
                proposal_id=material["proposalId"],
                snapshot=snapshot,
                verifier=verifier,
                status="committed",
                evidence={
                    **material["evidence"],
                    "themeCompletion": completion,
                    "readiness": copy.deepcopy(readiness),
                },
            )
            reply = (
                "已确认地点替换并完成主题升级；本次仅创建 1 个 patch 和 1 个版本。"
                if action == "confirm_portfolio_theme_replacement"
                else "主题升级已确认；本次仅创建 1 个 patch 和 1 个版本。"
            )
            response_payload = {
                "mode": "portfolio_theme_confirmation",
                "reply": reply,
                "terminalStatus": "success",
                "resultVersionId": result.version.id,
                "resultPatchId": result.patch.id,
                "versionDelta": 1,
                "patchDelta": 1,
                "choiceOptions": [],
            }
            self.db.execute(
                "UPDATE conversation_turns SET content = ?, agent_response_json = ?, "
                "itinerary_version_id = ?, updated_at = ? WHERE id = ?",
                (
                    reply,
                    json.dumps(response_payload, ensure_ascii=False, default=str),
                    result.version.id,
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            trace = AgentHarnessTrace(session_id, assistant_turn_id)
            events = [
                trace.apply_patch(
                    "completed",
                    "主题补全确认通过现有 ItineraryPatchService exactly-one 写入。",
                    metadata={
                        "proposalId": material["proposalId"],
                        "themeCompletionAttemptId": material["attemptId"],
                        "versionWriteCount": 1,
                        "patchWriteCount": 1,
                        "resultVersionId": result.version.id,
                        "resultPatchId": result.patch.id,
                    },
                ),
                trace.verify(
                    "completed",
                    "确认后的 active itinerary 已通过 AgentVerifierService。",
                    metadata={
                        "resultPreview": {
                            "passed": True,
                            "hardFailures": [],
                        }
                    },
                ),
                trace.respond("completed", reply),
            ]
            self._store_planning_events(assistant_turn_id, events)
            self._finish_fallback_choice_execution(
                claim["id"],
                "succeeded",
                result_version_id=result.version.id,
                execution_turn_id=assistant_turn_id,
                outcome={
                    "resultVersionId": result.version.id,
                    "resultPatchId": result.patch.id,
                    "proposalId": material["proposalId"],
                    "attemptId": material["attemptId"],
                    "versionDelta": 1,
                    "patchDelta": 1,
                },
            )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return AgentMessageResponse(
                userTurn=user_turn,
                assistantTurn=self._turn_response(assistant_turn_id),
                itinerary=ItineraryService(self.db).get_plan(before["active_plan_id"]),
                version=self._version_response(
                    self._version(
                        result.version.id,
                        session_id,
                        before["active_plan_id"],
                    )
                ),
                pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
                warnings=[],
                planningRun=None,
                planningSteps=events,
                toolEvents=events,
                terminalStatus="success",
            )
        except Exception as error:
            row = self.db.execute(
                "SELECT status FROM agent_choice_executions WHERE id = ?",
                (claim["id"],),
            ).fetchone()
            if row is not None and str(row["status"] or "") == "executing":
                self._finish_fallback_choice_execution(claim["id"], "failed_retryable", error=error)
            raise

    def _execute_theme_replacement_rejection(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict[str, Any],
        selected_choice: dict[str, Any],
    ) -> AgentMessageResponse:
        """Reject a previewed hard replacement without writing the active plan."""

        del session, request_context
        claim = self._claim_fallback_choice_execution(session_id, user_turn_id, selected_choice)
        current = self._session(session_id)
        if claim["status"] == "succeeded":
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_theme_replacement_rejection_consumed",
                    "message": "该地点替换已处理，请查看最新方案。",
                },
            )
        version_count_before = int(
            self.db.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session_id,),
            ).fetchone()[0]
        )
        patch_count_before = int(
            self.db.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session_id,),
            ).fetchone()[0]
        )
        try:
            material = self._theme_completion_confirmation_material(
                session_id=session_id, selected_choice=selected_choice
            )
            replacement_preview = material["replacementPreview"]
            before_snapshot = replacement_preview.get("beforeSnapshot")
            if replacement_preview.get("requiresConfirmation") is not True or not isinstance(before_snapshot, dict):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "portfolio_theme_replacement_preview_missing",
                        "message": "没有可拒绝的 hard 地点替换。",
                    },
                )
            material["snapshot"] = CreativeThemeCompletionService.reject_hard_replacements(
                before_snapshot=before_snapshot,
                proposed_snapshot=material["snapshot"],
            )
            snapshot, verifier, readiness, quality = self._theme_completion_reverify(
                material=material,
                preview_id=f"theme_rejection_{material['attemptId']}",
                require_adoption_ready=False,
            )
            completion = copy.deepcopy(material["completion"])
            completion["replacementPreview"] = {
                **copy.deepcopy(replacement_preview),
                "requiresConfirmation": False,
                "decision": "rejected",
                "beforeSnapshot": None,
                "versionWriteCount": 0,
                "patchWriteCount": 0,
            }
            completion.update(
                {
                    "replacementDecision": "rejected",
                    "versionWriteCount": 0,
                    "patchWriteCount": 0,
                }
            )
            evidence = {
                **material["evidence"],
                "themeCompletion": completion,
                "readiness": copy.deepcopy(readiness),
            }
            material["store"].update_proposal_material(
                portfolio_id=material["portfolioId"],
                proposal_id=material["proposalId"],
                snapshot=snapshot,
                verifier=verifier,
                status=("adoption_ready" if readiness.get("adoptionReady") is True else "partial"),
                evidence=evidence,
            )
            assistant_turn_id = self._insert_turn(
                session_id,
                "assistant",
                "已保留原 hard 地点并重新核验方案；正式行程未写入。",
                "active",
                agent_request_json={
                    "selectedAgentChoice": selected_choice,
                    "themeCompletionAttemptId": material["attemptId"],
                },
                agent_response_json={
                    "mode": "portfolio_theme_replacement_rejection",
                    "reply": "",
                },
            )
            active_version_id = str(current["active_version_id"] or "")
            projection = PlanComparisonPreviewService.project_snapshot(
                snapshot,
                planning_selection_root_turn_id=material["sourceUserTurnId"],
                root_portfolio_id=material["portfolioId"],
                proposal_id=material["proposalId"],
                source_assistant_turn_id=assistant_turn_id,
                choice_id=material["proposalChoiceId"],
                active_version_id=active_version_id or None,
                expected_base_version_id=active_version_id or None,
                is_partial=bool(readiness.get("isPartial")),
                is_adopted=bool(active_version_id),
                adoption_ready=bool(readiness.get("adoptionReady")),
            )
            next_choices: list[dict[str, Any]] = []
            common = {
                "sourceUserTurnId": material["sourceUserTurnId"],
                "planningSelectionRootTurnId": material["sourceUserTurnId"],
                "rootPortfolioId": material["portfolioId"],
                "proposalId": material["proposalId"],
                "proposalChoiceId": material["proposalChoiceId"],
                "attemptId": material["attemptId"],
                "lifecycle": "offered",
            }
            if active_version_id and quality.get("themeEligible") is True and readiness.get("adoptionReady") is True:
                next_choices.append(
                    {
                        **common,
                        "id": f"portfolio_theme_upgrade_{material['proposalId']}_{material['attemptId']}_after_reject",
                        "action": "confirm_portfolio_theme_upgrade",
                        "kind": "portfolio_theme_upgrade_confirmation",
                        "label": "确认保留新增点并升级主题",
                        "description": "原 hard 地点保持不变；严格核验后由现有 Single-Writer exactly-one 写入。",
                        "expectedBaseVersionId": active_version_id,
                    }
                )
            elif not active_version_id and readiness.get("adoptionReady") is True:
                next_choices.append(
                    {
                        **common,
                        "id": material["proposalChoiceId"],
                        "action": "select_plan_proposal",
                        "kind": "plan_proposal",
                        "label": str(projection.get("nextActionLabel") or "采用此方案"),
                        "description": "采用时重新核验并经现有 Single-Writer exactly-one 写入。",
                        "expectedBaseVersionId": None,
                        "comparisonProjection": copy.deepcopy(projection),
                    }
                )
            elif quality.get("themeEligible") is not True:
                continuation = self._theme_completion_option(
                    projection,
                    proposal_choice_id=material["proposalChoiceId"],
                    source_user_turn_id=material["sourceUserTurnId"],
                )
                if continuation is not None:
                    continuation["label"] = "继续搜索同一主题"
                    next_choices.append(continuation)
            version_count_after = int(
                self.db.execute(
                    "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                    (session_id,),
                ).fetchone()[0]
            )
            patch_count_after = int(
                self.db.execute(
                    "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                    (session_id,),
                ).fetchone()[0]
            )
            if version_count_after != version_count_before or patch_count_after != patch_count_before:
                raise RuntimeError("portfolio_theme_rejection_formal_write_detected")
            reply = "已保留原 hard 地点；兼容新增地点继续保留，路线已重新核验，正式行程零写入。"
            response_payload = {
                "mode": "portfolio_theme_replacement_rejection",
                "reply": reply,
                "choiceOptions": next_choices,
                "comparisonProjections": [projection],
                "comparisonProjectionUpdateMode": "replace",
                "themeCompletion": completion,
                "terminalStatus": "needs_confirmation",
                "versionDelta": 0,
                "patchDelta": 0,
                "routeWriteDelta": 0,
            }
            self.db.execute(
                "UPDATE conversation_turns SET content = ?, agent_response_json = ?, updated_at = ? WHERE id = ?",
                (
                    reply,
                    json.dumps(response_payload, ensure_ascii=False, default=str),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            trace = AgentHarnessTrace(session_id, assistant_turn_id)
            events = [
                trace.event(
                    "theme_replacement_rejected",
                    "拒绝 hard 地点替换",
                    status="completed",
                    detail=reply,
                    metadata={
                        "proposalId": material["proposalId"],
                        "themeCompletionAttemptId": material["attemptId"],
                        "replacementDecision": "rejected",
                        "versionWriteCount": 0,
                        "patchWriteCount": 0,
                        "versionDelta": 0,
                        "patchDelta": 0,
                    },
                ),
                trace.respond("completed", reply, metadata={"versionDelta": 0, "patchDelta": 0}),
            ]
            self._store_planning_events(assistant_turn_id, events)
            self._finish_fallback_choice_execution(
                claim["id"],
                "succeeded",
                execution_turn_id=assistant_turn_id,
                outcome={
                    "attemptId": material["attemptId"],
                    "proposalId": material["proposalId"],
                    "replacementDecision": "rejected",
                    "versionDelta": 0,
                    "patchDelta": 0,
                },
            )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return AgentMessageResponse(
                userTurn=user_turn,
                assistantTurn=self._turn_response(assistant_turn_id),
                itinerary=ItineraryService(self.db).get_plan(current["active_plan_id"]),
                version=(
                    self._version_response(self._version(active_version_id, session_id, current["active_plan_id"]))
                    if active_version_id
                    else None
                ),
                pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
                warnings=[],
                planningRun=None,
                planningSteps=events,
                toolEvents=events,
                terminalStatus="needs_confirmation",
            )
        except Exception as error:
            row = self.db.execute(
                "SELECT status FROM agent_choice_executions WHERE id = ?",
                (claim["id"],),
            ).fetchone()
            if row is not None and str(row["status"] or "") == "executing":
                self._finish_fallback_choice_execution(claim["id"], "failed_retryable", error=error)
                self.db.commit()
            raise

    def _dispatch_selected_agent_choice(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        selected_choice: dict[str, Any],
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> Optional[AgentMessageResponse]:
        """Execute a persisted structured choice through its authoritative service path."""
        option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        action = str(selected_choice.get("action") or option.get("action") or "")
        effective_action = str(selected_choice.get("normalizedAction") or action)
        if action == "select_plan_proposal":
            return self._execute_selected_plan_proposal(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                request_context=request_context,
                selected_choice=selected_choice,
            )
        if action == "adopt_active_partial":
            return self._execute_active_partial_adoption(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                request_context=request_context,
                selected_choice=selected_choice,
            )
        if action == "attempt_portfolio_theme_completion":
            return self._execute_theme_completion_attempt(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                request_context=request_context,
                selected_choice=selected_choice,
            )
        if action in {
            "confirm_portfolio_theme_upgrade",
            "confirm_portfolio_theme_replacement",
        }:
            return self._execute_theme_completion_confirmation(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                request_context=request_context,
                selected_choice=selected_choice,
            )
        if action == "reject_portfolio_theme_replacement":
            return self._execute_theme_replacement_rejection(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                request_context=request_context,
                selected_choice=selected_choice,
            )
        if action in {"execute_timeline_mutation_choice", "execute_timeline_mutation_manual"}:
            semantic_message = str(selected_choice.get("semanticMessage") or content).strip()
            selected_poi = None
            if action == "execute_timeline_mutation_manual":
                intent = self.timeline_mutation_ingress.detect(
                    semantic_message,
                    active_version_id=session["active_version_id"],
                )
                if intent is None:
                    raise HTTPException(
                        status_code=422,
                        detail={
                            "code": "timeline_mutation_manual_input_invalid",
                            "message": "无法从手动输入中唯一识别局部修改目标。",
                        },
                    )
            else:
                raw_intent = option.get("mutationIntent")
                if not isinstance(raw_intent, dict):
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "timeline_mutation_choice_invalid",
                            "message": "该局部修改选项缺少服务端意图。",
                        },
                    )
                try:
                    intent = TimelineMutationIntent.model_validate(raw_intent)
                    if option.get("kind") == "timeline_mutation_poi":
                        selected_poi = MapPoiResponse.model_validate(option.get("amapPoi"))
                except ValidationError as error:
                    raise HTTPException(
                        status_code=409,
                        detail={"code": "timeline_mutation_choice_invalid", "message": "该局部修改选项已失效。"},
                    ) from error
            response = self._execute_local_timeline_mutation(
                session_id,
                user_turn_id,
                user_turn,
                session,
                semantic_message,
                intent,
                event_sink=event_sink,
                request_context=request_context,
                selected_poi=selected_poi,
            )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return response
        if effective_action in {
            DENSITY_REFRESH_ACTION,
            DENSITY_NEARBY_ACTION,
            DENSITY_MANUAL_SEARCH_ACTION,
        }:
            retry_mode = (
                "expand_nearby"
                if effective_action == DENSITY_NEARBY_ACTION
                else "manual_exact_search"
                if effective_action == DENSITY_MANUAL_SEARCH_ACTION
                else "refresh_candidates"
            )
            continuation = (
                request_context.get("portfolioDensityContinuation")
                if isinstance(request_context.get("portfolioDensityContinuation"), dict)
                else {}
            )
            target_scope = {
                "briefId": continuation.get("briefId"),
                "poolId": continuation.get("poolId"),
                "planningSlotId": continuation.get("planningSlotId"),
                "dayNumber": continuation.get("dayNumber"),
                "intentType": continuation.get("intentType"),
            }
            density_groups = [target_scope] if target_scope["poolId"] and target_scope["planningSlotId"] else []
            request_context["retryCandidateHints"] = True
            request_context["forceCandidateRefresh"] = effective_action in {
                DENSITY_REFRESH_ACTION,
                DENSITY_NEARBY_ACTION,
                DENSITY_MANUAL_SEARCH_ACTION,
            }
            request_context["structuredRetry"] = {
                "retryMode": retry_mode,
                "densityGroups": density_groups,
                "briefId": target_scope["briefId"],
                "poolId": target_scope["poolId"],
                "planningSlotId": target_scope["planningSlotId"],
                "dayNumber": target_scope["dayNumber"],
                "intentType": target_scope["intentType"],
                "sourceAssistantTurnId": selected_choice.get("sourceAssistantTurnId"),
                "choiceId": selected_choice.get("choiceId"),
            }
            request_context["candidateRefreshScopes"] = [
                {
                    "briefId": item.get("briefId"),
                    "poolId": item.get("poolId"),
                    "planningSlotId": item.get("planningSlotId") or item.get("slotId"),
                    "dayNumber": item.get("dayNumber"),
                }
                for item in density_groups
                if isinstance(item, dict)
            ]
            if effective_action == DENSITY_NEARBY_ACTION:
                request_context["expandDensityNearby"] = True
            if effective_action == DENSITY_MANUAL_SEARCH_ACTION:
                manual_values = self._clean_candidate_hints([str(selected_choice.get("manualValue") or "")])
                if not manual_values:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "agent_choice_manual_value_missing",
                            "message": "该待补槽位缺少手动地点关键词，请重新输入。",
                        },
                    )
                manual_value = manual_values[0]
                request_context["manualCandidateHints"] = [
                    {
                        **target_scope,
                        "candidateHints": [manual_value],
                        "hintPolicy": "user_explicit_hint",
                        "manualExactSlotSearch": True,
                        "entityBindingMode": "exact_entity",
                        "exactEntity": manual_value,
                        "rawNeed": manual_value,
                    }
                ]
            return None
        if action == "retry_model_planning":
            if str(option.get("kind") or "") == "portfolio_density_retry":
                retry_mode = str(option.get("retryMode") or "refresh_candidates")
                request_context["retryCandidateHints"] = True
                request_context["forceCandidateRefresh"] = True
                request_context["structuredRetry"] = {
                    "retryMode": retry_mode,
                    "densityGroups": list(option.get("densityGroups") or []),
                    "sourceAssistantTurnId": selected_choice.get("sourceAssistantTurnId"),
                    "choiceId": selected_choice.get("choiceId"),
                }
            request_context["syntheticAgentChoice"] = True
            if effective_action != DENSITY_CANDIDATE_ACTION:
                request_context.pop("skipPostObservationController", None)
            return None
        if action == "continue_plan_expansion":
            request_context["syntheticAgentChoice"] = True
            request_context.pop("skipPostObservationController", None)
            return None
        if effective_action == DENSITY_CANDIDATE_ACTION or action == "manual_continuation":
            if str(option.get("kind") or "") == "material_tradeoff" or self._is_portfolio_density_candidate_option(
                option
            ):
                selected_candidate = self._select_planning_material_tradeoff_candidate(
                    session_id,
                    selected_choice,
                )
                request_context["selectedPlanningCandidate"] = selected_candidate
                request_context["retryCandidateHints"] = True
                request_context["manualCandidateHints"] = [
                    {
                        "poolId": selected_candidate.get("poolId") or "",
                        "intentType": selected_candidate["intentType"],
                        "candidateHints": [selected_candidate["amapPoi"]["name"]],
                        "hintPolicy": "user_explicit_hint",
                    }
                ]
            if effective_action != DENSITY_CANDIDATE_ACTION:
                request_context.pop("skipPostObservationController", None)
            return None
        if action == "confirm_rule_safe_draft":
            claimed = self._claim_fallback_choice_execution(session_id, user_turn_id, selected_choice)
            if claimed["status"] == "succeeded":
                return self._replay_fallback_choice_execution(user_turn, session, selected_choice, claimed)
            decision_state = (
                request_context.get("agentDecisionState")
                if isinstance(request_context.get("agentDecisionState"), dict)
                else {}
            )
            decision_state.update(
                {
                    "requestChoiceId": selected_choice.get("requestChoiceId"),
                    "persistedChoiceId": selected_choice.get("persistedChoiceId"),
                    "persistedChoiceAction": selected_choice.get("persistedChoiceAction"),
                    "executionChoiceId": selected_choice.get("executionChoiceId"),
                    "executionAction": selected_choice.get("executionAction"),
                }
            )
            request_context["syntheticAgentChoice"] = True
            request_context["fallbackChoiceExecution"] = {
                "executionId": claimed["id"],
                "action": action,
                "attempt": claimed["attempt"],
                "sourceAssistantTurnId": selected_choice.get("sourceAssistantTurnId"),
                "sourceUserTurnId": option.get("sourceUserTurnId"),
            }
            response = self.rule_safe_draft_executor.execute(
                request_context=request_context,
                selected_choice=selected_choice,
                execution=claimed,
                invoke=lambda authorized_context: self._run_authorized_rule_safe_draft(
                    session_id,
                    user_turn_id,
                    content,
                    authorized_context,
                ),
            )
            # The staged pipeline may return a truthful zero-write blocker.
            # Keep the choice claim in its cancellable state until that result
            # is finalized, so a concurrent cancellation cannot be overwritten
            # as a retryable no-version outcome.
            self.assert_session_run_active(session_id)
            if response.version is None:
                self._finish_fallback_choice_execution(claimed["id"], "failed_retryable")
            else:
                response.version.version_number = self._squash_confirmed_fallback_versions(
                    session_id,
                    response.assistant_turn.id,
                    response.version.id,
                    response.planning_steps,
                    expected_base_version_id=claimed.get("expected_base_version_id"),
                )
                response = self._attach_rule_safe_partial_comparison(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    response=response,
                    event_sink=event_sink,
                )
                self._finish_fallback_choice_execution(
                    claimed["id"],
                    "succeeded",
                    result_version_id=response.version.id,
                    execution_turn_id=response.assistant_turn.id,
                )
                self._consume_selected_agent_choice(session_id, selected_choice)
                self.db.commit()
            return response
        if str(option.get("kind") or "") == "retry_unresolved_slot":
            # A retry button already identifies one persisted unresolved slot.
            # Re-enter the staged, bounded POI pipeline directly instead of
            # exposing generic fact tools or the multi-round tool loop.
            option_version = str(option.get("activeVersionId") or "").strip()
            if option_version and option_version != str(session["active_version_id"] or ""):
                raise HTTPException(
                    status_code=409,
                    detail={"code": "agent_choice_version_stale", "message": "该重试选项对应的行程版本已变化。"},
                )
            segment_id = str(option.get("segmentId") or option.get("slotId") or "").strip()
            plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
            segment = next((segment for day in plan.days for segment in day.segments if segment.id == segment_id), None)
            if segment is None:
                raise HTTPException(
                    status_code=409,
                    detail={"code": "agent_choice_target_stale", "message": "该重试目标已不在当前时间轴。"},
                )
            grounding_status = str(getattr(segment.poi, "grounding_status", "") or "")
            segment_notes = str(getattr(segment, "notes", "") or "")
            if (
                grounding_status
                not in {"waiting_for_poi_grounding", "provider_rate_limited", "needs_verification", "pending"}
                and "waiting_for_poi_grounding" not in segment_notes
            ):
                raise HTTPException(
                    status_code=409,
                    detail={"code": "agent_choice_target_resolved", "message": "该目标已完成或不再需要重试。"},
                )
            request_context["retryCandidateHints"] = True
            request_context["selectedRetrySlotId"] = option.get("slotId") or option.get("segmentId")
            request_context["structuredRetry"] = {
                "sourceAssistantTurnId": selected_choice.get("sourceAssistantTurnId"),
                "choiceId": selected_choice.get("choiceId"),
                "slotId": option.get("slotId"),
                "segmentId": option.get("segmentId"),
                "dayNumber": option.get("dayNumber"),
                "timeWindow": option.get("timeWindow"),
                "reason": option.get("reason"),
                "intentType": option.get("intentType"),
            }
            request_context["allowedToolsOverride"] = ["read_itinerary", "resolve_poi", "patch_itinerary"]
            return self._generate_with_initial_staged_pipeline(
                session_id,
                user_turn_id,
                content,
                request_context,
            )
        if str(option.get("kind") or "") != "poi_candidate":
            return None
        segment_id = str(option.get("segmentId") or "").strip()
        candidate_id = str(option.get("candidateRecordId") or "").strip()
        raw_poi = option.get("amapPoi")
        if not segment_id or not candidate_id or not isinstance(raw_poi, dict):
            raise HTTPException(
                status_code=409, detail={"code": "agent_choice_invalid", "message": "该候选缺少可执行的结构化身份。"}
            )
        try:
            poi = MapPoiResponse.model_validate(raw_poi)
        except ValidationError as error:
            raise HTTPException(
                status_code=409, detail={"code": "agent_choice_invalid", "message": "该候选地点已失效。"}
            ) from error
        replay = self._replay_selected_agent_choice_if_committed(
            session_id, user_turn, session, request_context, selected_choice
        )
        if replay is not None:
            return replay
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
        day = next((item for item in plan.days if any(segment.id == segment_id for segment in item.segments)), None)
        if day is None:
            raise HTTPException(
                status_code=409, detail={"code": "agent_choice_target_stale", "message": "该候选对应的日程段已变化。"}
            )
        command = TimelineEditCommand(
            intent="accepted_action_executor",
            scope="agent_choice",
            operation="replace_segment_poi_from_candidate",
            day_number=day.day_number,
            constraints={
                "sourceAssistantTurnId": selected_choice.get("sourceAssistantTurnId"),
                "choiceId": selected_choice.get("choiceId"),
            },
        )
        operation = ItineraryPatchOperation(
            op="replace_segment_poi_from_candidate",
            segmentId=segment_id,
            candidateId=candidate_id,
            amapPoi=poi,
            notes=f"groundingStatus：agent_selected_candidate；来源为服务端结构化选项 {selected_choice.get('choiceId')}。",
        )
        response = self._timeline_command_patch_response(
            session_id,
            user_turn_id,
            content,
            user_turn,
            session,
            request_context,
            command,
            [operation],
            f"已将第 {day.day_number} 天对应日程替换为真实地图地点「{poi.name}」，其余日程未重排。",
            warnings=[],
            result_preview={
                "changedScope": "single_segment_agent_choice",
                "changedSegmentIds": [segment_id],
                "selectedPoiNames": [poi.name],
                "selectedFromStructuredCandidate": True,
                "sourceAssistantTurnId": selected_choice.get("sourceAssistantTurnId"),
                "choiceId": selected_choice.get("choiceId"),
                "toolLoopEntered": False,
                "webSearchCalls": 0,
                "ticketLookupCalls": 0,
                "amapWeatherCalls": 0,
            },
        )

        if response.version is not None:
            self._consume_selected_agent_choice(session_id, selected_choice)
        return response

    @staticmethod
    def _is_portfolio_density_candidate_option(option: Any) -> bool:
        """Recognize density completion by persisted identity, never by user wording."""
        return PortfolioDensityContinuationService.is_density_option(option)

    @staticmethod
    def _checkpoint_portfolio_resume_allowed(
        request_context: dict[str, Any],
        resumed_waiting_plan: dict[str, Any],
    ) -> bool:
        retry_plan = (
            request_context.get("retryExecutionPlan")
            if isinstance(request_context.get("retryExecutionPlan"), dict)
            else {}
        )
        return bool(
            request_context.get("serverExecutionProfile") != "simple_open_v1"
            and retry_plan.get("kind") in {"resume_incomplete_stage", "expand_partial_portfolio"}
            and (
                retry_plan.get("kind") != "expand_partial_portfolio"
                or resumed_waiting_plan.get("serverValidatedPartialExpansionCheckpoint") is True
            )
            and isinstance(resumed_waiting_plan.get("constraintLedger"), dict)
            and isinstance(resumed_waiting_plan.get("creativePortfolio"), dict)
            and isinstance(resumed_waiting_plan.get("groundingCheckpoint"), dict)
        )

    @classmethod
    def _portfolio_resume_allowed(
        cls,
        request_context: dict[str, Any],
        resumed_waiting_plan: dict[str, Any],
    ) -> bool:
        """Fail closed before either structured or checkpoint Portfolio resume."""

        if request_context.get("serverExecutionProfile") == "simple_open_v1":
            return False
        return bool(
            request_context.get("structuredPlanningChoiceResume")
            or cls._checkpoint_portfolio_resume_allowed(request_context, resumed_waiting_plan)
        )

    @staticmethod
    def _portfolio_density_resume_scope(
        pipeline_context: dict[str, Any],
    ) -> Optional[dict[str, Any]]:
        if not bool(pipeline_context.get("structuredPlanningChoiceResume")):
            return None
        continuation = (
            pipeline_context.get("portfolioDensityContinuation")
            if isinstance(pipeline_context.get("portfolioDensityContinuation"), dict)
            else {}
        )
        brief_id = str(continuation.get("briefId") or "").strip()
        pool_id = str(continuation.get("poolId") or "").strip()
        planning_slot_id = str(continuation.get("planningSlotId") or "").strip()
        day_number = continuation.get("dayNumber")
        if not brief_id or not pool_id or not planning_slot_id or day_number in (None, ""):
            return None
        return {
            "briefId": brief_id,
            "poolId": pool_id,
            "planningSlotId": planning_slot_id,
            "dayNumber": int(day_number),
            "intentType": str(continuation.get("intentType") or ""),
        }

    @staticmethod
    def _portfolio_checkpoint_resume_scopes(
        grounding_checkpoint: dict[str, Any],
        pipeline_context: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Resume only unresolved consumers from the frozen focus brief."""

        focus_brief_id = str(pipeline_context.get("portfolioGroundingFocusBriefId") or "").strip()
        if not focus_brief_id:
            return []
        scopes: list[dict[str, Any]] = []
        seen: set[tuple[str, str, str, int]] = set()
        raw_scopes = (
            pipeline_context.get("checkpointExpansionScopes")
            if pipeline_context.get("checkpointExpansionResume") is True
            and isinstance(pipeline_context.get("checkpointExpansionScopes"), list)
            else grounding_checkpoint.get("unresolvedSlots")
        ) or []
        for raw in raw_scopes:
            if not isinstance(raw, dict):
                continue
            brief_id = str(raw.get("briefId") or "").strip()
            pool_id = str(raw.get("poolId") or "").strip()
            slot_id = str(raw.get("planningSlotId") or raw.get("slotId") or "").strip()
            day_number = int(raw.get("dayNumber") or 0)
            if not brief_id or not pool_id or not slot_id or day_number <= 0 or brief_id != focus_brief_id:
                continue
            key = (brief_id, pool_id, slot_id, day_number)
            if key in seen:
                continue
            seen.add(key)
            scopes.append(
                {
                    "briefId": brief_id,
                    "poolId": pool_id,
                    "planningSlotId": slot_id,
                    "dayNumber": day_number,
                }
            )
        return sorted(
            scopes,
            key=lambda item: (
                item["dayNumber"],
                item["briefId"],
                item["poolId"],
                item["planningSlotId"],
            ),
        )

    @staticmethod
    def _scoped_portfolio_density_pool(
        target_pool: IntentPool,
        planning_slot_id: str,
    ) -> IntentPool:
        """Clone the dataclass for one continuation consumer identity."""

        return replace(
            target_pool,
            assign_to_slots=[planning_slot_id],
            target_count=1,
        )

    def _align_time_sensitive_day_slots(
        self,
        day_slots: list[DaySlot],
        intent_pools: list[IntentPool],
    ) -> list[DaySlot]:
        """Correct impossible dayparts without weakening schedule verification."""

        intent_types_by_slot: dict[str, set[str]] = {}
        for pool in intent_pools:
            for slot_id in pool.assign_to_slots:
                intent_types_by_slot.setdefault(str(slot_id), set()).add(str(pool.intent_type))
        aligned: list[DaySlot] = []
        for slot in day_slots:
            slot_intents = intent_types_by_slot.get(self._slot_key(slot), set())
            if "night_view" in slot_intents and self._minutes(slot.start_time) < 18 * 60:
                aligned.append(
                    replace(
                        slot,
                        time_window="night",
                        start_time="19:00",
                    )
                )
            else:
                aligned.append(slot)
        return aligned

    def _portfolio_density_route_context_plans(
        self,
        checkpoint: dict[str, Any],
        day_slots: list[DaySlot],
        scope: dict[str, Any],
        itinerary_service: ItineraryService,
        pipeline_context: dict[str, Any],
    ) -> list[PersistableSegmentPlan]:
        """Rehydrate previously selected same-brief anchors for scoped nearby search."""

        slots_by_id = {self._slot_key(slot): slot for slot in day_slots}
        plans: list[PersistableSegmentPlan] = []
        seen_slot_ids: set[str] = set()

        def restore_candidate(candidate_payload: dict[str, Any], report: dict[str, Any]) -> None:
            candidate_brief_id = str(
                candidate_payload.get("creativeBriefId")
                or candidate_payload.get("briefId")
                or report.get("briefId")
                or ""
            ).strip()
            candidate_pool_id = str(candidate_payload.get("poolId") or report.get("poolId") or "").strip()
            slot_id = str(
                candidate_payload.get("planningSlotId")
                or candidate_payload.get("sourcePlanningSlotId")
                or candidate_payload.get("slotId")
                or ""
            ).strip()
            slot = slots_by_id.get(slot_id)
            if (
                slot is None
                or slot_id in seen_slot_ids
                or slot_id == str(scope.get("planningSlotId") or "")
                or candidate_brief_id != str(scope.get("briefId") or "")
                or not candidate_pool_id
                or int(slot.day_number) != int(scope.get("dayNumber") or 0)
                or not slot.route_anchor
            ):
                return
            try:
                candidate = MapPoiResponse.model_validate(candidate_payload)
            except ValidationError:
                return
            if candidate.source != AMAP_PLACE_SOURCE or not itinerary_service._valid_coordinate(
                candidate.longitude,
                candidate.latitude,
            ):
                return
            intent_type = str(candidate_payload.get("intentType") or report.get("intentType") or "")
            intent = PoiIntent(
                raw_need=str(candidate_payload.get("rawNeed") or report.get("rawNeed") or slot.raw_need),
                city=str(candidate.city or pipeline_context.get("selectedCity") or ""),
                day_number=slot.day_number,
                time_window=slot.time_window,
                intent_type=intent_type or self._intent_type_for_slot(slot, pipeline_context),
                specificity="functional",
            )
            poi = itinerary_service._poi_from_ranked_candidate(intent, candidate)
            plans.append(
                self._route_anchor_segment_plan(
                    slot,
                    poi,
                    itinerary_service,
                    pipeline_context,
                    creative_brief_id=candidate_brief_id,
                    pool_id=candidate_pool_id,
                    source_goal_id=str(
                        candidate_payload.get("sourceGoalId")
                        or candidate_payload.get("goalId")
                        or report.get("sourceGoalId")
                        or report.get("goalId")
                        or report.get("softGoalId")
                        or (f"pool_goal:{candidate_pool_id}" if candidate_pool_id else "")
                    ),
                    source_requirement_level=(
                        "soft_experience"
                        if str(candidate_payload.get("softGoalId") or report.get("softGoalId") or "").strip()
                        else "required"
                        if str(candidate_payload.get("goalId") or report.get("goalId") or "").strip()
                        or str(
                            candidate_payload.get("requirementLevel") or report.get("requirementLevel") or ""
                        ).strip()
                        == "required"
                        else "optional"
                    ),
                )
            )
            seen_slot_ids.add(slot_id)

        for report in checkpoint.get("poolReports") or []:
            if not isinstance(report, dict) or str(report.get("briefId") or "") != str(scope.get("briefId") or ""):
                continue
            resolved_slot_ids = {str(item) for item in report.get("resolvedSlotIds") or [] if str(item)}
            selected_candidates = [
                copy.deepcopy(item)
                for item in report.get("selectedCandidates") or []
                if isinstance(item, dict)
                and str(item.get("planningSlotId") or "") in resolved_slot_ids
                and str(item.get("briefId") or report.get("briefId") or "") == str(report.get("briefId") or "")
                and str(item.get("poolId") or report.get("poolId") or "") == str(report.get("poolId") or "")
            ]
            for candidate_payload in selected_candidates:
                restore_candidate(candidate_payload, report)

        repair_evidence_sources = [checkpoint]
        resume = pipeline_context.get("resumePlanningAttempt")
        if isinstance(resume, dict):
            prior_pipeline = resume.get("pipelineContext")
            if isinstance(prior_pipeline, dict):
                prior_report = prior_pipeline.get("candidateGenerationReport")
                if isinstance(prior_report, dict):
                    repair_evidence_sources.append(prior_report)
        for evidence_source in repair_evidence_sources:
            for candidate_payload in evidence_source.get("routeRepairGroundingEvidence") or []:
                if isinstance(candidate_payload, dict):
                    restore_candidate(candidate_payload, {})
        return plans

    def _merge_portfolio_density_grounding_report(
        self,
        checkpoint: dict[str, Any],
        target_report: dict[str, Any],
        scope: dict[str, Any],
    ) -> dict[str, Any]:
        """Replace one slot consumer while preserving the frozen Portfolio union."""

        def report_matches(item: dict[str, Any]) -> bool:
            return (
                str(item.get("briefId") or "") == scope["briefId"] and str(item.get("poolId") or "") == scope["poolId"]
            )

        def unresolved_matches(item: dict[str, Any]) -> bool:
            return (
                str(item.get("briefId") or "") == scope["briefId"]
                and str(item.get("poolId") or "") == scope["poolId"]
                and str(item.get("slotId") or item.get("planningSlotId") or "") == scope["planningSlotId"]
                and int(item.get("dayNumber") or 0) == scope["dayNumber"]
            )

        merged = copy.deepcopy(checkpoint)
        prior_reports = [copy.deepcopy(item) for item in checkpoint.get("poolReports") or [] if isinstance(item, dict)]
        fresh_reports = [
            copy.deepcopy(item) for item in target_report.get("poolReports") or [] if isinstance(item, dict)
        ]
        fresh = next((item for item in fresh_reports if report_matches(item)), None)
        prior_index = next(
            (index for index, item in enumerate(prior_reports) if report_matches(item)),
            None,
        )
        if fresh is not None and prior_index is not None:
            previous = prior_reports[prior_index]
            slot_id = scope["planningSlotId"]
            combined = {**previous, **fresh}
            combined["targetCount"] = int(previous.get("targetCount") or fresh.get("targetCount") or 1)
            combined["requiredSlotIds"] = list(dict.fromkeys([*list(previous.get("requiredSlotIds") or []), slot_id]))
            slot_days = dict(previous.get("slotDayNumbers") or {})
            slot_days.update(dict(fresh.get("slotDayNumbers") or {}))
            slot_days[slot_id] = scope["dayNumber"]
            combined["slotDayNumbers"] = slot_days
            resolved = {str(item) for item in previous.get("resolvedSlotIds") or [] if str(item)}
            unresolved = {str(item) for item in previous.get("unresolvedSlotIds") or [] if str(item)}
            resolved.discard(slot_id)
            unresolved.discard(slot_id)
            resolved.update(str(item) for item in fresh.get("resolvedSlotIds") or [] if str(item))
            unresolved.update(str(item) for item in fresh.get("unresolvedSlotIds") or [] if str(item))
            combined["resolvedSlotIds"] = sorted(resolved)
            combined["unresolvedSlotIds"] = sorted(unresolved)
            combined["selectedCount"] = len(resolved)
            combined["selectedCandidateCount"] = len(resolved)
            combined["missingCount"] = max(0, combined["targetCount"] - len(resolved))
            combined["coverageStatus"] = self._coverage_status(
                selected_count=len(resolved),
                target_count=combined["targetCount"],
                required_intent=bool(combined.get("requiredIntent")),
                provider_state=combined.get("providerState"),
                rate_limited=bool(target_report.get("rateLimited")),
            )
            combined["coverageReason"] = self._coverage_reason(combined["coverageStatus"])
            previous_candidates = [
                item
                for item in previous.get("safeCandidates") or []
                if isinstance(item, dict) and str(item.get("planningSlotId") or "") != slot_id
            ]
            combined["safeCandidates"] = [
                *previous_candidates,
                *[item for item in fresh.get("safeCandidates") or [] if isinstance(item, dict)],
            ]
            previous_selected_candidates = [
                item
                for item in previous.get("selectedCandidates") or []
                if isinstance(item, dict) and str(item.get("planningSlotId") or "") != slot_id
            ]
            combined["selectedCandidates"] = [
                *previous_selected_candidates,
                *[item for item in fresh.get("selectedCandidates") or [] if isinstance(item, dict)],
            ]
            combined["candidateHints"] = list(
                dict.fromkeys(
                    [
                        *[str(item) for item in previous.get("candidateHints") or [] if str(item).strip()],
                        *[str(item) for item in fresh.get("candidateHints") or [] if str(item).strip()],
                    ]
                )
            )[:8]
            combined["candidateHintCount"] = len(combined["candidateHints"])
            prior_reports[prior_index] = combined
        elif fresh is not None:
            prior_reports.append(fresh)
        merged["poolReports"] = prior_reports

        prior_unresolved = [
            copy.deepcopy(item)
            for item in checkpoint.get("unresolvedSlots") or []
            if isinstance(item, dict) and not unresolved_matches(item)
        ]
        fresh_unresolved = [
            copy.deepcopy(item) for item in target_report.get("unresolvedSlots") or [] if isinstance(item, dict)
        ]
        merged["unresolvedSlots"] = [*prior_unresolved, *fresh_unresolved]
        merged["unresolvedDays"] = self._unresolved_days(merged["unresolvedSlots"])
        merged["requiredIntentCoverage"] = self._required_intent_coverage(prior_reports)
        merged["rateLimited"] = bool(target_report.get("rateLimited"))
        merged["rateLimitReason"] = str(target_report.get("rateLimitReason") or "")
        merged["warnings"] = list(
            dict.fromkeys(
                [
                    *list(checkpoint.get("warnings") or []),
                    *list(target_report.get("warnings") or []),
                ]
            )
        )
        merged["resultState"] = (
            "waiting_for_poi_grounding"
            if merged["unresolvedSlots"]
            else str(target_report.get("resultState") or "partial_success")
        )
        merged["pipelineContext"] = target_report.get("pipelineContext") or checkpoint.get("pipelineContext")
        return merged

    def _merge_portfolio_brief_grounding_report(
        self,
        checkpoint: dict[str, Any],
        fresh_report: dict[str, Any],
        focus_brief_id: str,
    ) -> dict[str, Any]:
        """Merge refreshed gaps into one frozen brief without importing sibling briefs."""

        focus = str(focus_brief_id or "").strip()
        if not focus:
            raise ValueError("portfolio_checkpoint_focus_brief_missing")
        prior_reports = [
            copy.deepcopy(item)
            for item in checkpoint.get("poolReports") or []
            if isinstance(item, dict) and str(item.get("briefId") or "") == focus
        ]
        fresh_reports = [
            copy.deepcopy(item)
            for item in fresh_report.get("poolReports") or []
            if isinstance(item, dict) and str(item.get("briefId") or "") == focus
        ]
        if not prior_reports and not fresh_reports:
            raise ValueError("portfolio_checkpoint_focus_brief_missing")
        fresh_by_pool = {str(item.get("poolId") or ""): item for item in fresh_reports}
        merged_reports: list[dict[str, Any]] = []
        seen_pools: set[str] = set()
        refreshed_scope_keys: set[tuple[str, str, int]] = set()
        for fresh in fresh_reports:
            pool_id = str(fresh.get("poolId") or "")
            slot_days = fresh.get("slotDayNumbers") if isinstance(fresh.get("slotDayNumbers"), dict) else {}
            for slot_id in fresh.get("requiredSlotIds") or fresh.get("unresolvedSlotIds") or []:
                refreshed_scope_keys.add((pool_id, str(slot_id), int(slot_days.get(str(slot_id)) or 0)))
        for prior in prior_reports:
            pool_id = str(prior.get("poolId") or "")
            fresh = fresh_by_pool.get(pool_id)
            seen_pools.add(pool_id)
            if fresh is None:
                reused = copy.deepcopy(prior)
                reused["checkpointEvidenceReused"] = True
                merged_reports.append(reused)
                continue
            refreshed_slots = {
                str(item) for item in fresh.get("requiredSlotIds") or fresh.get("unresolvedSlotIds") or [] if str(item)
            }
            combined = {**prior, **fresh}
            combined["briefId"] = focus
            combined["poolId"] = pool_id
            combined["requiredSlotIds"] = list(
                dict.fromkeys(
                    [
                        *[str(item) for item in prior.get("requiredSlotIds") or [] if str(item)],
                        *[str(item) for item in fresh.get("requiredSlotIds") or [] if str(item)],
                    ]
                )
            )
            slot_days = dict(prior.get("slotDayNumbers") or {})
            slot_days.update(dict(fresh.get("slotDayNumbers") or {}))
            combined["slotDayNumbers"] = slot_days
            prior_resolved = {str(item) for item in prior.get("resolvedSlotIds") or [] if str(item)} - refreshed_slots
            prior_unresolved = {
                str(item) for item in prior.get("unresolvedSlotIds") or [] if str(item)
            } - refreshed_slots
            resolved = prior_resolved | {str(item) for item in fresh.get("resolvedSlotIds") or [] if str(item)}
            unresolved = prior_unresolved | {str(item) for item in fresh.get("unresolvedSlotIds") or [] if str(item)}
            combined["resolvedSlotIds"] = sorted(resolved)
            combined["unresolvedSlotIds"] = sorted(unresolved)
            combined["selectedCount"] = len(resolved)
            combined["selectedCandidateCount"] = len(resolved)
            target_count = int(
                prior.get("targetCount") or fresh.get("targetCount") or len(combined["requiredSlotIds"]) or 1
            )
            combined["targetCount"] = target_count
            combined["missingCount"] = max(0, target_count - len(resolved))
            prior_safe = [
                copy.deepcopy(item)
                for item in prior.get("safeCandidates") or []
                if isinstance(item, dict) and str(item.get("planningSlotId") or "") not in refreshed_slots
            ]
            combined["safeCandidates"] = [
                *prior_safe,
                *[copy.deepcopy(item) for item in fresh.get("safeCandidates") or [] if isinstance(item, dict)],
            ]
            prior_selected = [
                copy.deepcopy(item)
                for item in prior.get("selectedCandidates") or []
                if isinstance(item, dict) and str(item.get("planningSlotId") or "") not in refreshed_slots
            ]
            combined["selectedCandidates"] = [
                *prior_selected,
                *[copy.deepcopy(item) for item in fresh.get("selectedCandidates") or [] if isinstance(item, dict)],
            ]
            combined["checkpointGapRefreshed"] = True
            merged_reports.append(combined)
        for fresh in fresh_reports:
            pool_id = str(fresh.get("poolId") or "")
            if pool_id not in seen_pools:
                fresh["checkpointGapRefreshed"] = True
                merged_reports.append(fresh)
        prior_unresolved = [
            copy.deepcopy(item)
            for item in checkpoint.get("unresolvedSlots") or []
            if isinstance(item, dict)
            and str(item.get("briefId") or "") == focus
            and (
                str(item.get("poolId") or ""),
                str(item.get("planningSlotId") or item.get("slotId") or ""),
                int(item.get("dayNumber") or 0),
            )
            not in refreshed_scope_keys
        ]
        fresh_unresolved = [
            copy.deepcopy(item)
            for item in fresh_report.get("unresolvedSlots") or []
            if isinstance(item, dict) and str(item.get("briefId") or "") == focus
        ]
        merged = copy.deepcopy(fresh_report)
        merged["poolReports"] = merged_reports
        merged["unresolvedSlots"] = [*prior_unresolved, *fresh_unresolved]
        merged["unresolvedDays"] = self._unresolved_days(merged["unresolvedSlots"])
        merged["requiredIntentCoverage"] = self._required_intent_coverage(merged_reports)
        merged["resultState"] = (
            "waiting_for_poi_grounding"
            if merged["unresolvedSlots"]
            else str(fresh_report.get("resultState") or "portfolio_candidate_universe_ready")
        )
        merged["checkpointExpansion"] = {
            "focusBriefId": focus,
            "reusedPoolCount": sum(1 for item in merged_reports if item.get("checkpointEvidenceReused") is True),
            "refreshedPoolCount": sum(1 for item in merged_reports if item.get("checkpointGapRefreshed") is True),
        }
        return merged

    @staticmethod
    def _density_retry_scope_matches(
        pipeline_context: dict[str, Any], pool: IntentPool, assigned_slots: list[DaySlot]
    ) -> bool:
        scopes = [item for item in pipeline_context.get("candidateRefreshScopes") or [] if isinstance(item, dict)]
        if not scopes:
            return False
        continuation = (
            pipeline_context.get("portfolioDensityContinuation")
            if isinstance(pipeline_context.get("portfolioDensityContinuation"), dict)
            else {}
        )
        active_brief_id = str(continuation.get("briefId") or "")
        slot_ids = {str(slot.slot_id or "") for slot in assigned_slots}
        day_numbers = {int(slot.day_number) for slot in assigned_slots}
        for scope in scopes:
            scope_brief_id = str(scope.get("briefId") or "")
            if scope_brief_id and (not active_brief_id or scope_brief_id != active_brief_id):
                continue
            if scope.get("poolId") and str(scope.get("poolId")) != str(pool.pool_id):
                continue
            if scope.get("planningSlotId") and str(scope.get("planningSlotId")) not in slot_ids:
                continue
            if scope.get("dayNumber") not in (None, "") and int(scope.get("dayNumber")) not in day_numbers:
                continue
            return True
        return False

    @staticmethod
    def _partial_plan_expansion_pool_matches(
        pipeline_context: dict[str, Any],
        pool: IntentPool,
    ) -> bool:
        """Refresh only the persisted target brief during plan expansion."""

        return bool(
            pipeline_context.get("_partialPlanExpansionAuthorized") is True
            and str(pipeline_context.get("focusBriefId") or "").strip()
            and str(pool.brief_id or "").strip() == str(pipeline_context.get("focusBriefId") or "").strip()
        )

    @classmethod
    def _density_retry_query_fingerprint(
        cls,
        pipeline_context: dict[str, Any],
        pool: IntentPool,
        assigned_slots: list[DaySlot],
    ) -> Optional[str]:
        if not cls._density_retry_scope_matches(pipeline_context, pool, assigned_slots):
            return None
        structured_retry = (
            pipeline_context.get("structuredRetry") if isinstance(pipeline_context.get("structuredRetry"), dict) else {}
        )
        continuation = (
            pipeline_context.get("portfolioDensityContinuation")
            if isinstance(pipeline_context.get("portfolioDensityContinuation"), dict)
            else {}
        )
        material = {
            "briefId": continuation.get("briefId"),
            "poolId": pool.pool_id,
            "planningSlotIds": sorted(str(slot.slot_id or "") for slot in assigned_slots),
            "dayNumbers": sorted(int(slot.day_number) for slot in assigned_slots),
            "retryMode": structured_retry.get("retryMode"),
            "forceCandidateRefresh": bool(pipeline_context.get("forceCandidateRefresh")),
            "expandDensityNearby": bool(pipeline_context.get("expandDensityNearby")),
        }
        encoded = json.dumps(material, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:24]

    def _select_planning_material_tradeoff_candidate(
        self,
        session_id: str,
        selected_choice: dict[str, Any],
    ) -> dict[str, Any]:
        """Persist one pre-version planning choice by opaque candidate identity."""
        option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        candidate_record_id = str(option.get("candidateRecordId") or "").strip()
        selected_amap_id = str(option.get("amapId") or "").strip()
        source_goal_id = str(option.get("sourceGoalId") or "").strip()
        brief_id = str(option.get("briefId") or "").strip()
        pool_id = str(option.get("poolId") or "").strip()
        planning_slot_id = str(option.get("planningSlotId") or "").strip()
        day_number = int(option.get("dayNumber") or 0)
        is_density_choice = (
            str(option.get("kind") or "") == "portfolio_density_candidate"
            or str(option.get("continuationType") or "") == "portfolio_density_completion"
        )
        if (
            not candidate_record_id
            or not selected_amap_id
            or not planning_slot_id
            or (not source_goal_id and not pool_id)
            or (is_density_choice and (not brief_id or day_number <= 0))
        ):
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_invalid", "message": "该规划候选缺少可执行的结构化身份。"},
            )
        row = self.db.execute(
            """
            SELECT * FROM amap_poi_candidates
            WHERE id = ? AND session_id = ? AND segment_id IS NULL AND status IN ('pending', 'selected')
            """,
            (candidate_record_id, session_id),
        ).fetchone()
        if row is None:
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_target_stale", "message": "该规划候选已失效，请使用最新选项。"},
            )
        try:
            raw_candidates = json.loads(row["candidates_json"] or "[]")
        except json.JSONDecodeError:
            raw_candidates = []
        candidates = raw_candidates if isinstance(raw_candidates, list) else []
        matches = [
            candidate
            for candidate in candidates
            if isinstance(candidate, dict)
            and str(candidate.get("id") or candidate.get("amapId") or "") == selected_amap_id
            and str(candidate.get("planningSlotId") or "") == planning_slot_id
            and (not source_goal_id or str(candidate.get("sourceGoalId") or "") == source_goal_id)
            and (not brief_id or str(candidate.get("briefId") or "") == brief_id)
            and (not pool_id or str(candidate.get("poolId") or "") == pool_id)
            and (day_number <= 0 or int(candidate.get("dayNumber") or 0) == day_number)
        ]
        if len(matches) != 1:
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_identity_mismatch", "message": "该规划候选身份与持久化记录不一致。"},
            )
        try:
            poi = MapPoiResponse.model_validate(matches[0])
        except ValidationError as error:
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_invalid", "message": "该规划候选地点已失效。"},
            ) from error
        if str(row["selected_amap_id"] or "") not in {"", selected_amap_id}:
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_already_selected", "message": "该候选组已选择其它地点，请刷新会话。"},
            )
        self.db.execute(
            "UPDATE amap_poi_candidates SET selected_amap_id = ? WHERE id = ?",
            (selected_amap_id, candidate_record_id),
        )
        self.db.commit()
        intent_type = {
            "goal_campus_visit": "campus_visit",
            "goal_museum": "museum",
            "goal_meal": "meal",
        }.get(source_goal_id, str(matches[0].get("intentType") or "landmark"))
        return {
            "candidateRecordId": candidate_record_id,
            "amapId": selected_amap_id,
            "amapPoi": poi.model_dump(by_alias=True),
            "sourceGoalId": source_goal_id,
            "briefId": brief_id,
            "poolId": pool_id,
            "planningSlotId": planning_slot_id,
            "dayNumber": day_number,
            "intentType": intent_type,
            "sourceAssistantTurnId": selected_choice.get("sourceAssistantTurnId"),
            "choiceId": selected_choice.get("choiceId"),
        }

    def _finalize_planning_material_choice(self, request_context: dict[str, Any], *, succeeded: bool) -> None:
        selected = (
            request_context.get("selectedPlanningCandidate")
            if isinstance(request_context.get("selectedPlanningCandidate"), dict)
            else {}
        )
        candidate_record_id = str(selected.get("candidateRecordId") or "")
        selected_amap_id = str(selected.get("amapId") or "")
        if not candidate_record_id or not selected_amap_id:
            return
        if succeeded:
            self.db.execute(
                "UPDATE amap_poi_candidates SET status = 'selected' WHERE id = ? AND selected_amap_id = ? AND segment_id IS NULL",
                (candidate_record_id, selected_amap_id),
            )
        else:
            self.db.execute(
                "UPDATE amap_poi_candidates SET status = 'pending', selected_amap_id = NULL WHERE id = ? AND selected_amap_id = ? AND segment_id IS NULL",
                (candidate_record_id, selected_amap_id),
            )

    def _run_authorized_rule_safe_draft(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        request_context: dict[str, Any],
    ) -> AgentMessageResponse:
        self._persist_agent_request_context(session_id, user_turn_id, request_context)
        return self._generate_with_initial_staged_pipeline(
            session_id,
            user_turn_id,
            str(request_context.get("effectiveUserMessage") or content),
            request_context,
        )

    def _canonical_clarification_batch_source_identity(
        self,
        *,
        session_id: str,
        source_assistant_turn_id: str,
        choice_id: str,
        selected_choice: dict[str, Any],
    ) -> tuple[str, str]:
        """Return the immutable checkpoint identity behind one batch submit option.

        The client-selected option is only a locator.  The authoritative
        checkpoint and option must be reloaded from the source assistant turn,
        so a stale or tampered payload cannot claim or replay an execution.
        """

        source_row = self.db.execute(
            """SELECT agent_response_json FROM conversation_turns
               WHERE id = ? AND session_id = ? AND role = 'assistant' AND status = 'active'""",
            (source_assistant_turn_id, session_id),
        ).fetchone()
        source_payload = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
        checkpoint = (
            source_payload.get("clarificationCheckpoint")
            if isinstance(source_payload.get("clarificationCheckpoint"), dict)
            else {}
        )
        source_options = source_payload.get("choiceOptions")
        source_options = source_options if isinstance(source_options, list) else []
        matching_options = [
            option
            for option in source_options
            if isinstance(option, dict)
            and str(option.get("id") or "") == choice_id
            and str(option.get("kind") or "") == "clarification_batch_submit"
            and str(option.get("action") or "") == "submit_clarification_batch"
        ]
        selected_option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        source_checkpoint_id = str(checkpoint.get("checkpointId") or "")
        source_checkpoint_fingerprint = str(checkpoint.get("fingerprint") or "")
        source_user_turn_id = str(checkpoint.get("sourceUserTurnId") or "")
        source_planning_root_id = str(checkpoint.get("planningRootId") or "")
        canonical_option = matching_options[0] if len(matching_options) == 1 else {}
        if (
            source_row is None
            or len(matching_options) != 1
            or not source_checkpoint_id
            or not source_checkpoint_fingerprint
            or str(checkpoint.get("status") or "") != "awaiting_answer"
            or str(checkpoint.get("sourceAssistantTurnId") or "") != source_assistant_turn_id
            or str(canonical_option.get("sourceAssistantTurnId") or "") != source_assistant_turn_id
            or str(canonical_option.get("checkpointId") or "") != source_checkpoint_id
            or str(canonical_option.get("checkpointFingerprint") or "") != source_checkpoint_fingerprint
            or str(canonical_option.get("sourceUserTurnId") or "") != source_user_turn_id
            or str(canonical_option.get("planningSelectionRootTurnId") or "") != source_planning_root_id
            or str(selected_choice.get("sourceAssistantTurnId") or "") != source_assistant_turn_id
            or str(selected_choice.get("choiceId") or "") != choice_id
            or str(selected_choice.get("persistedChoiceId") or choice_id) != choice_id
            or str(selected_choice.get("persistedChoiceAction") or canonical_option.get("action") or "")
            != "submit_clarification_batch"
            or str(selected_option.get("id") or "") != choice_id
            or str(selected_option.get("kind") or "") != "clarification_batch_submit"
            or str(selected_option.get("action") or "") != "submit_clarification_batch"
            or str(selected_option.get("sourceAssistantTurnId") or "") != source_assistant_turn_id
            or str(selected_option.get("checkpointId") or "") != source_checkpoint_id
            or str(selected_option.get("checkpointFingerprint") or "") != source_checkpoint_fingerprint
            or str(selected_option.get("sourceUserTurnId") or "") != source_user_turn_id
            or str(selected_option.get("planningSelectionRootTurnId") or "") != source_planning_root_id
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "clarification_checkpoint_identity_mismatch",
                    "message": "当前批量澄清来源身份已失效，请刷新后继续。",
                },
            )
        return source_checkpoint_id, source_checkpoint_fingerprint

    def _claim_fallback_choice_execution(
        self,
        session_id: str,
        execution_turn_id: str,
        selected_choice: dict[str, Any],
        *,
        continuation_checkpoint: Optional[dict[str, Any]] = None,
        guide_binding_requirement: Optional[dict[str, Any]] = None,
    ) -> dict[str, Any]:
        option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        source_turn_id = str(selected_choice.get("sourceAssistantTurnId") or "")
        choice_id = str(selected_choice.get("choiceId") or "")
        action = str(selected_choice.get("action") or option.get("action") or "")
        request_choice_id = str(selected_choice.get("requestChoiceId") or choice_id)
        persisted_choice_id = str(selected_choice.get("persistedChoiceId") or choice_id)
        persisted_action = str(selected_choice.get("persistedChoiceAction") or option.get("action") or "")
        # The explicit legacy rollback switch retains its original Creative
        # Portfolio selection semantics. Reissued and active-entry requests
        # always require the latest presentation before starting/retrying.
        entry_mode = getattr(getattr(self, "conversation_intent_router", None), "routing_mode", "legacy-only")
        latest_required = (entry_mode == "active-all"
                           or bool(option.get("operationOrigin")) or action != "select_plan_proposal")
        strict_recovery = (entry_mode == "active-all"
                           or bool(option.get("operationOrigin")))
        managed_action = action in {"continue_plan_expansion", "select_plan_proposal", "search_travel_guide_advice"}
        continuation = (
            continuation_checkpoint
            if isinstance(continuation_checkpoint, dict)
            else selected_choice.get("continuationCheckpoint")
            if isinstance(selected_choice.get("continuationCheckpoint"), dict)
            else {}
        )
        checkpoint_fingerprint = str(continuation.get("checkpointFingerprint") or "") or None
        # A clarification batch is not a portfolio continuation.  Its source
        # checkpoint is instead sealed into the persisted opaque option and
        # must remain the execution identity even after resolving advances the
        # request checkpoint.  Never substitute the result checkpoint here.
        if str(option.get("kind") or "") == "clarification_batch_submit" and action == "submit_clarification_batch":
            _source_checkpoint_id, checkpoint_fingerprint = self._canonical_clarification_batch_source_identity(
                session_id=session_id,
                source_assistant_turn_id=source_turn_id,
                choice_id=choice_id,
                selected_choice=selected_choice,
            )
        if (
            request_choice_id != persisted_choice_id
            or persisted_choice_id != choice_id
            or persisted_action != action
            or str(option.get("id") or "") != persisted_choice_id
            or str(option.get("action") or "") != persisted_action
        ):
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_identity_mismatch", "message": "结构化选择身份不一致，已停止执行。"},
            )
        if continuation:
            session = self._session(session_id)
            checkpoint_reason = PortfolioContinuationCheckpointService.validate(
                continuation,
                session_id=session_id,
                source_assistant_turn_id=source_turn_id,
                choice_id=choice_id,
                option=option,
                active_version_id=str(session["active_version_id"] or "") or None,
            )
            if checkpoint_reason:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": checkpoint_reason,
                        "message": self._portfolio_checkpoint_failure_message(checkpoint_reason),
                    },
                )
        if action in {"continue_plan_expansion", "select_plan_proposal", "search_travel_guide_advice"}:
            from src.services.conversation_operation_identity import ConversationOperationIdentity
            identities = ConversationOperationIdentity(self.db)
            try:
                identity = identities.resolve(session_id, source_turn_id, choice_id,
                    guide_evidence=selected_choice.get("_serverGuideEvidenceFingerprint"))
                existing_operation = identities.execution(session_id, source_turn_id, choice_id,
                    guide_evidence=selected_choice.get("_serverGuideEvidenceFingerprint"))
                # Existing claims may only recover/replay their persisted
                # outcome below. A genuinely new authorization needs latest.
                if existing_operation is None and latest_required:
                    identities.assert_latest(session_id, source_turn_id)
                selected_choice["canonicalOperationId"] = identity.operation_id
                origin = identities.origin(session_id, source_turn_id, choice_id)
                continuation = {**continuation, "operationIdentity": {
                    "schemaVersion": "execution-operation-identity-v1",
                    "sourceAssistantTurnId": origin["sourceAssistantTurnId"], "choiceId": origin["choiceId"],
                    "operationId": identity.operation_id,
                    "guideEvidenceFingerprint": selected_choice.get("_serverGuideEvidenceFingerprint"),
                }}
                source_turn_id, choice_id = identity.source_turn_id, identity.choice_id
            except ValueError as error:
                raise HTTPException(409, {"code": str(error), "message": "当前操作身份或来源已失效，未执行。"}) from error
        if guide_binding_requirement is not None and strict_recovery:
            if (action != "continue_plan_expansion" or not selected_choice.get("canonicalOperationId")
                    or guide_binding_requirement.get("evidenceFingerprint") != selected_choice.get("_serverGuideEvidenceFingerprint")):
                raise ValueError("guide_binding_dispatch_scope_invalid")
            # This deferred fence is issued only by the audited, pure guide
            # requirement binding window in _build_request_context. All other
            # claims have unknown dispatch state and cannot manufacture proof.
            continuation = {**continuation,
                "guideContinuationRequirement": copy.deepcopy(guide_binding_requirement),
                "guideBindingDispatch": {
                    "schemaVersion": "guide-binding-dispatch-v1", "state": "not_started",
                    "operationId": selected_choice["canonicalOperationId"],
                    "evidenceFingerprint": guide_binding_requirement["evidenceFingerprint"],
                    "requirementFingerprint": guide_binding_requirement.get("requirementFingerprint"),
                    "businessStateBefore": self._choice_business_state(session_id),
                }}
        now = datetime.now(timezone.utc).isoformat()
        execution_id = f"choice_exec_{uuid4().hex[:16]}"
        savepoint_name = "agent_choice_execution_claim"

        def insert_execution_claim() -> None:
            self.db.execute(f"SAVEPOINT {savepoint_name}")
            try:
                if managed_action or strict_recovery:
                    # Acquire the SQLite writer reservation before the latest
                    # check, including across independent server connections.
                    self.db.execute("UPDATE conversation_sessions SET id = id WHERE id = ?", (session_id,))
                    if latest_required and (not managed_action or existing_operation is None):
                        try:
                            from src.services.conversation_operation_identity import ConversationOperationIdentity
                            ConversationOperationIdentity(self.db).assert_latest(session_id, str(selected_choice.get("sourceAssistantTurnId") or ""))
                        except ValueError as error:
                            raise HTTPException(409, {"code": str(error), "message": "当前操作来源已变化，未开始执行。"}) from error
                self.db.execute(
                    """
                    INSERT INTO agent_choice_executions (
                        id, session_id, source_turn_id, source_user_turn_id, choice_id, action,
                        status, expected_base_version_id, execution_turn_id, request_turn_id, attempt,
                        continuation_json, checkpoint_fingerprint, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, 'executing', ?, ?, ?, 1, ?, ?, ?, ?)
                    """,
                    (
                        execution_id,
                        session_id,
                        source_turn_id,
                        str(option.get("sourceUserTurnId") or ""),
                        choice_id,
                        action,
                        option.get("expectedBaseVersionId"),
                        execution_turn_id,
                        execution_turn_id,
                        json.dumps(continuation, ensure_ascii=False, default=str) if continuation else None,
                        checkpoint_fingerprint,
                        now,
                        now,
                    ),
                )
                self.db.execute(f"RELEASE SAVEPOINT {savepoint_name}")
                self.db.commit()
            except Exception:
                self.db.execute(f"ROLLBACK TO SAVEPOINT {savepoint_name}")
                self.db.execute(f"RELEASE SAVEPOINT {savepoint_name}")
                raise

        try:
            execute_session_run_prewrite(session_id, insert_execution_claim)
        except sqlite3.IntegrityError:
            row = self.db.execute(
                "SELECT * FROM agent_choice_executions WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?",
                (session_id, source_turn_id, choice_id),
            ).fetchone()
            if row is None:
                raise
            current = dict(row)
            if (
                str(option.get("kind") or "") == "clarification_batch_submit"
                and action == "submit_clarification_batch"
                and str(current.get("checkpoint_fingerprint") or "") != str(checkpoint_fingerprint or "")
            ):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "agent_choice_result_stale",
                        "message": "原批量确认结果缺少或不匹配来源检查点身份，请刷新后继续。",
                    },
                )
            if current["status"] == "failed_retryable" and SimpleDirectionExecutionEvidenceService(
                self.db
            ).reconcile_legacy_execution(str(current.get("id") or "")):
                refreshed = self.db.execute(
                    "SELECT * FROM agent_choice_executions WHERE id = ?",
                    (current["id"],),
                ).fetchone()
                if refreshed is not None:
                    current = dict(refreshed)
            if current["status"] == "succeeded":
                self._attach_choice_execution_identity(selected_choice, current)
                return current
            if current["status"] == "executing":
                # Coordinator reloads rebuild request context within the same
                # user turn. Reusing that turn's existing CAS claim is
                # idempotent; a different turn remains a duplicate click and
                # must not join the in-flight execution.
                if str(current.get("execution_turn_id") or "") == str(execution_turn_id or ""):
                    self._attach_choice_execution_identity(selected_choice, current)
                    return current
                if (
                    action == "continue_plan_expansion"
                    and str(current.get("action") or "") == "continue_plan_expansion"
                    and self._choice_execution_lease_expired(current)
                ):
                    if strict_recovery:
                        # Lease expiry is not execution evidence. Only the
                        # durable pre-dispatch fence can prove this native
                        # operation unstarted; never let the compatibility
                        # reconciler consume/terminalize an unknown frontier.
                        execute_session_run_prewrite(session_id, lambda: self._settle_unstarted_guide_binding_failure(
                            session_id, str(current["id"]), RuntimeError("guide_binding_interrupted_before_dispatch")))
                    else:
                        SimpleDirectionExecutionEvidenceService(
                            self.db
                        ).recover_or_terminalize_expired_compatibility_execution(str(current.get("id") or ""))
                    refreshed = self.db.execute(
                        "SELECT * FROM agent_choice_executions WHERE id = ?",
                        (current["id"],),
                    ).fetchone()
                    if refreshed is not None:
                        current = dict(refreshed)
                    if current["status"] == "succeeded":
                        self._attach_choice_execution_identity(selected_choice, current)
                        return current
                if (
                    action in {"adopt_active_partial", "select_plan_proposal"}
                    and str(current.get("action") or "") in {"adopt_active_partial", "select_plan_proposal"}
                    and self._choice_execution_lease_expired(current)
                    and not strict_recovery
                ):

                    def reclaim_execution() -> int:
                        reclaimed = self.db.execute(
                            """UPDATE agent_choice_executions
                            SET action = ?, execution_turn_id = ?, request_turn_id = ?, attempt = attempt + 1, updated_at = ?
                            WHERE id = ? AND status = 'executing' AND updated_at = ?""",
                            (action, execution_turn_id, execution_turn_id, now, current["id"], current["updated_at"]),
                        )
                        self.db.commit()
                        return int(reclaimed.rowcount)

                    if execute_session_run_prewrite(session_id, reclaim_execution) == 1:
                        row = self.db.execute(
                            "SELECT * FROM agent_choice_executions WHERE id = ?", (current["id"],)
                        ).fetchone()
                        result = dict(row)
                        self._attach_choice_execution_identity(selected_choice, result)
                        return result
                if current["status"] == "executing":
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "agent_choice_execution_in_progress",
                            "message": "该选择正在执行，请稍候刷新。",
                        },
                    )
            if current["status"] != "failed_retryable":
                raise HTTPException(
                    status_code=409,
                    detail={"code": "agent_choice_execution_terminal", "message": "该选择已结束，请使用最新回复继续。"},
                )

            managed_resume = strict_recovery
            from src.services.conversation_operation_identity import ConversationOperationIdentity
            if managed_resume and not ConversationOperationIdentity.explicitly_unstarted(current):
                raise HTTPException(409, {
                    "code": "agent_choice_execution_state_unknown",
                    "message": "该操作的执行记录尚不能证明业务未开始，请核对结果后再获取有效操作；没有再次执行。",
                })
            resume_continuation = continuation
            if managed_resume:
                # Resume is not a new business attempt. Preserve the sealed
                # requirement and identity even if rebuilt UI context omits it.
                resume_continuation = {**continuation, **self._json_dict(current.get("continuation_json"))}
                if "guideBindingDispatch" not in self._json_dict(current.get("continuation_json")):
                    # Reissue/resume cannot fabricate a dispatch fence that
                    # was absent on the original persisted operation.
                    resume_continuation.pop("guideBindingDispatch", None)

            def retry_execution() -> int:
                if strict_recovery or (latest_required and managed_action):
                    try:
                        ConversationOperationIdentity(self.db).assert_latest(session_id, str(selected_choice.get("sourceAssistantTurnId") or ""))
                    except ValueError as error:
                        raise HTTPException(409, {"code": str(error), "message": "旧操作入口不能开始新的执行，请使用最新操作。"}) from error
                retry_claim = self.db.execute(
                    """
                    UPDATE agent_choice_executions
                    SET status = 'executing', attempt = attempt + ?, execution_turn_id = ?, request_turn_id = ?,
                        continuation_json = COALESCE(?, continuation_json),
                        checkpoint_fingerprint = COALESCE(?, checkpoint_fingerprint),
                        outcome_json = NULL, error_json = NULL, updated_at = ?
                    WHERE id = ? AND status = 'failed_retryable' AND updated_at = ?
                    """,
                    (
                        0 if managed_resume else 1,
                        execution_turn_id,
                        execution_turn_id,
                        json.dumps(resume_continuation, ensure_ascii=False, default=str) if resume_continuation else None,
                        checkpoint_fingerprint,
                        now,
                        current["id"],
                        current["updated_at"],
                    ),
                )
                self.db.commit()
                return int(retry_claim.rowcount)

            if execute_session_run_prewrite(session_id, retry_execution) != 1:
                raise HTTPException(
                    status_code=409,
                    detail={"code": "agent_choice_execution_in_progress", "message": "该选择正在执行，请稍候刷新。"},
                )
            row = self.db.execute("SELECT * FROM agent_choice_executions WHERE id = ?", (current["id"],)).fetchone()
            result = dict(row)
            self._attach_choice_execution_identity(selected_choice, result)
            return result
        row = self.db.execute("SELECT * FROM agent_choice_executions WHERE id = ?", (execution_id,)).fetchone()
        result = dict(row)
        self._attach_choice_execution_identity(selected_choice, result)
        return result

    @staticmethod
    def _choice_execution_lease_expired(execution: dict[str, Any], lease_seconds: int = 120) -> bool:
        try:
            updated_at = datetime.fromisoformat(str(execution.get("updated_at") or ""))
        except ValueError:
            return False
        if updated_at.tzinfo is None:
            updated_at = updated_at.replace(tzinfo=timezone.utc)
        return updated_at <= datetime.now(timezone.utc) - timedelta(seconds=lease_seconds)

    @staticmethod
    def _attach_choice_execution_identity(selected_choice: dict[str, Any], execution: dict[str, Any]) -> None:
        selected_choice["executionChoiceId"] = str(execution.get("choice_id") or "")
        selected_choice["executionAction"] = str(execution.get("action") or "")
        selected_choice["executionId"] = str(execution.get("id") or "")

    def _persist_agent_request_context(
        self,
        session_id: str,
        user_turn_id: str,
        request_context: dict[str, Any],
    ) -> None:
        from src.services.agent_ingress_journal import AgentIngressJournal
        request_context = AgentIngressJournal(self.db).merge_context(user_turn_id, request_context)
        self.db.execute(
            "UPDATE conversation_turns SET agent_request_json = ?, updated_at = ? WHERE id = ? AND session_id = ?",
            (
                json.dumps(request_context, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                user_turn_id,
                session_id,
            ),
        )
        self.db.commit()

    def _partial_plan_expansion_claim_state(
        self,
        *,
        session_id: str,
        plan_id: str,
        root_portfolio_id: str,
        planning_root_id: str,
        request_fingerprint: str,
        active_version_id: str,
    ) -> dict[str, Any]:
        portfolio = self._validated_partial_plan_expansion_root(
            session_id=session_id,
            root_portfolio_id=root_portfolio_id,
            planning_root_id=planning_root_id,
            request_fingerprint=request_fingerprint,
        )
        neutral_checkpoint = bool(
            portfolio is None
            and self._neutral_partial_expansion_checkpoint_matches(
                session_id=session_id,
                root_portfolio_id=root_portfolio_id,
                planning_root_id=planning_root_id,
                request_fingerprint=request_fingerprint,
                active_version_id=active_version_id,
            )
        )
        if portfolio is None and not neutral_checkpoint:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_partial_root_identity_mismatch",
                    "message": "当前方案的规划根标识已失效，行程未发生变化，请重新生成对比方案。",
                },
            )
        summary = self._json_dict(portfolio["summary_json"]) if portfolio is not None else {}
        proposal_ids = [
            str(row["id"])
            for row in self.db.execute(
                "SELECT id FROM agent_plan_proposals WHERE portfolio_id = ? ORDER BY rank_index ASC",
                (root_portfolio_id,),
            ).fetchall()
        ]
        visible_ids = [str(item) for item in summary.get("visibleProposalIds") or [] if str(item)]
        return {
            "kind": "expand_partial_portfolio",
            "planningSelectionRootTurnId": planning_root_id,
            "rootPortfolioId": root_portfolio_id,
            "requestContractFingerprint": request_fingerprint,
            "activeVersionId": active_version_id or None,
            "proposalIdsBefore": proposal_ids,
            "visibleProposalIdsBefore": visible_ids,
            "visibleProposalCountBefore": len(visible_ids),
            "versionCountBefore": int(
                self.db.execute(
                    "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                    (session_id,),
                ).fetchone()[0]
            ),
            "patchCountBefore": int(
                self.db.execute(
                    "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                    (session_id,),
                ).fetchone()[0]
            ),
            "routeCountBefore": int(
                self.db.execute(
                    "SELECT COUNT(*) FROM route_options WHERE plan_id = ?",
                    (plan_id,),
                ).fetchone()[0]
            ),
            "routeFingerprintBefore": self._route_content_fingerprint(plan_id),
        }

    def _route_content_fingerprint(self, plan_id: str) -> str:
        rows = self.db.execute(
            """SELECT id, from_segment_id, to_segment_id, from_poi_id, to_poi_id,
            provider, mode, label, is_selected, sort_order, transport_mode,
            distance_meters, duration_seconds, duration_minutes, cost_amount,
            cost_currency, cost_estimate, crowding_risk, source, polyline_json,
            steps_json, provider_payload_json, error_json, queried_at
            FROM route_options WHERE plan_id = ? ORDER BY id""",
            (plan_id,),
        ).fetchall()
        payload = [tuple(row) for row in rows]
        return hashlib.sha256(
            json.dumps(payload, ensure_ascii=False, separators=(",", ":"), default=str).encode("utf-8")
        ).hexdigest()

    def _partial_plan_expansion_planning_directive(
        self,
        *,
        session_id: str,
        source_assistant_turn_id: str,
    ) -> Optional[dict[str, Any]]:
        """Restore only the server-persisted draft directive for an opaque expansion choice."""

        if not source_assistant_turn_id:
            return None
        row = self.db.execute(
            """SELECT agent_request_json, agent_response_json
            FROM conversation_turns
            WHERE id = ? AND session_id = ? AND role = 'assistant' AND status != 'superseded'""",
            (source_assistant_turn_id, session_id),
        ).fetchone()
        if row is None:
            return None
        request_payload = self._json_dict(row["agent_request_json"])
        response_payload = self._json_dict(row["agent_response_json"])
        decision = (
            request_payload.get("agentDecision") if isinstance(request_payload.get("agentDecision"), dict) else {}
        )
        grounding = response_payload.get("grounding") if isinstance(response_payload.get("grounding"), dict) else {}
        pipeline = (
            response_payload.get("pipelineContext")
            if isinstance(response_payload.get("pipelineContext"), dict)
            else grounding.get("pipelineContext")
            if isinstance(grounding.get("pipelineContext"), dict)
            else {}
        )
        candidates = (
            request_payload.get("planningDirective"),
            decision.get("actionDirective"),
            pipeline.get("planningDirective"),
        )
        for candidate in candidates:
            if (
                isinstance(candidate, dict)
                and candidate.get("type") == "draft_itinerary"
                and isinstance(candidate.get("dayStrategies"), list)
                and candidate.get("dayStrategies")
            ):
                return copy.deepcopy(candidate)
        return None

    def _partial_plan_expansion_resume_plan(
        self,
        *,
        session_id: str,
        source_assistant_turn_id: str,
        root_portfolio_id: str,
        planning_root_id: str,
        request_fingerprint: str,
        focus_brief_id: str,
    ) -> Optional[dict[str, Any]]:
        """Load one server-authored brief checkpoint for a persisted expansion choice.

        The client may only submit the opaque turn/choice identity.  All planning
        skeletons and candidate evidence are reloaded from the source assistant
        turn after the persisted root, fingerprint, focus brief and option scope
        have been checked again.
        """

        def rejected(reason_code: str) -> None:
            logger.info(
                "portfolio expansion checkpoint rejected: %s",
                reason_code,
                extra={
                    "reasonCode": reason_code,
                    "sessionId": session_id,
                    "sourceAssistantTurnId": source_assistant_turn_id,
                    "rootPortfolioId": root_portfolio_id,
                    "focusBriefId": focus_brief_id,
                },
            )
            return None

        if not all(
            str(item or "").strip()
            for item in (
                source_assistant_turn_id,
                root_portfolio_id,
                planning_root_id,
                request_fingerprint,
                focus_brief_id,
            )
        ):
            return rejected("checkpoint_identity_incomplete")
        row = self.db.execute(
            """SELECT agent_response_json
            FROM conversation_turns
            WHERE id = ? AND session_id = ? AND role = 'assistant' AND status != 'superseded'""",
            (source_assistant_turn_id, session_id),
        ).fetchone()
        if row is None:
            return rejected("checkpoint_source_turn_missing")
        payload = self._json_dict(row["agent_response_json"])
        options = [item for item in payload.get("choiceOptions") or [] if isinstance(item, dict)]
        matching_option = next(
            (
                item
                for item in options
                if str(item.get("kind") or "") in {"portfolio_partial_more_plans", "portfolio_more_plans"}
                and str(item.get("rootPortfolioId") or "") == root_portfolio_id
                and str(item.get("planningSelectionRootTurnId") or "") == planning_root_id
                and str(item.get("requestContractFingerprint") or "") == request_fingerprint
                and str(item.get("focusBriefId") or "") == focus_brief_id
            ),
            None,
        )
        if matching_option is None:
            return rejected("checkpoint_option_scope_mismatch")
        raw_ledger = payload.get("constraintLedger")
        raw_portfolio = payload.get("creativePortfolio")
        grounding_checkpoint = payload.get("groundingCheckpoint")
        if not all(isinstance(item, dict) for item in (raw_ledger, raw_portfolio, grounding_checkpoint)):
            return rejected("checkpoint_payload_missing")
        try:
            ledger = ConstraintLedger.model_validate(raw_ledger)
            generated = InitialCreativePortfolio.model_validate(raw_portfolio)
        except ValidationError:
            return rejected("checkpoint_payload_invalid")
        focus_proposals = [item for item in generated.proposals if str(item.brief.brief_id or "") == focus_brief_id]
        if len(focus_proposals) != 1:
            return rejected("checkpoint_focus_brief_missing")
        focus_proposal = focus_proposals[0]
        focus_slots = {str(item.slot_id): item for item in focus_proposal.day_slots}
        checkpoint_expansion_scopes = sorted(
            [
                {
                    "briefId": focus_brief_id,
                    "poolId": str(pool.pool_id),
                    "planningSlotId": str(slot_id),
                    "dayNumber": int(focus_slots[str(slot_id)].day_number),
                }
                for pool in focus_proposal.intent_pools
                for slot_id in pool.assign_to_slots
                if str(slot_id) in focus_slots
            ],
            key=lambda item: (
                item["dayNumber"],
                item["briefId"],
                item["poolId"],
                item["planningSlotId"],
            ),
        )
        if not checkpoint_expansion_scopes:
            return rejected("checkpoint_focus_scope_missing")
        scoped_initial_plan = self._initial_plan_from_creative_portfolio(
            generated.model_copy(update={"proposals": focus_proposals})
        )
        pipeline_context = (
            copy.deepcopy(payload.get("pipelineContext")) if isinstance(payload.get("pipelineContext"), dict) else {}
        )
        pipeline_context.update(
            {
                "portfolioGroundingFocusBriefId": focus_brief_id,
                "focusBriefId": focus_brief_id,
                "planningSelectionRootTurnId": planning_root_id,
                "rootPortfolioId": root_portfolio_id,
                "requestContractFingerprint": request_fingerprint,
                "checkpointExpansionResume": True,
                "checkpointExpansionScopes": checkpoint_expansion_scopes,
                # An expansion is a new, server-scoped opportunity to replenish
                # hints for the exact frozen consumers.  Do not inherit the
                # source turn's one-shot marker and suppress that retry.
                "candidateHintRetryAttempted": False,
            }
        )
        planning_directive = self._partial_plan_expansion_planning_directive(
            session_id=session_id,
            source_assistant_turn_id=source_assistant_turn_id,
        )
        return {
            "initialPlan": scoped_initial_plan.model_dump(by_alias=True),
            "pipelineContext": pipeline_context,
            "sourceAssistantTurnId": source_assistant_turn_id,
            "sourceUserTurnId": planning_root_id,
            "resultState": payload.get("terminalStatus") or payload.get("resultState"),
            "constraintLedger": ledger.model_dump(by_alias=True),
            "creativePortfolio": generated.model_dump(by_alias=True),
            "groundingCheckpoint": copy.deepcopy(grounding_checkpoint),
            "planningDirective": copy.deepcopy(planning_directive),
            "serverValidatedPartialExpansionCheckpoint": True,
        }

    def _comparison_novelty_baseline(
        self,
        *,
        session_id: str,
        planning_root_id: str,
        root_portfolio_id: str,
        current_assistant_turn_id: str,
    ) -> dict[str, Any]:
        """Pack active cards for one exact planning root into a physical baseline."""

        prior_by_proposal_id: dict[str, dict[str, Any]] = {}
        rows = self.db.execute(
            """SELECT id, agent_response_json
            FROM conversation_turns
            WHERE session_id = ? AND role = 'assistant' AND status = 'active'
              AND id != ?
            ORDER BY turn_index ASC, created_at ASC""",
            (session_id, current_assistant_turn_id),
        ).fetchall()
        for row in rows:
            payload = self._json_dict(row["agent_response_json"])
            for projection in payload.get("comparisonProjections") or []:
                if not isinstance(projection, dict):
                    continue
                if str(projection.get("rootPortfolioId") or "") != root_portfolio_id:
                    continue
                if str(projection.get("planningSelectionRootTurnId") or "") != planning_root_id:
                    continue
                proposal_id = str(projection.get("proposalId") or "")
                if proposal_id:
                    prior_by_proposal_id[proposal_id] = copy.deepcopy(projection)
        comparison_baseline: list[dict[str, Any]] = []
        suppressed_legacy_ids: list[str] = []
        for projection in prior_by_proposal_id.values():
            proposal_id = str(projection.get("proposalId") or "")
            if not PlanComparisonPreviewService.physical_poi_ids(projection):
                if proposal_id:
                    suppressed_legacy_ids.append(proposal_id)
                continue
            if not comparison_baseline:
                comparison_baseline.append(projection)
                continue
            historical_audit = PlanComparisonPreviewService.material_novelty_audit(
                projection,
                comparison_baseline,
            )
            if historical_audit.get("passed") is True:
                comparison_baseline.append(projection)
            elif proposal_id:
                suppressed_legacy_ids.append(proposal_id)
        return {
            "projections": comparison_baseline,
            "historicalProjectionCount": len(prior_by_proposal_id),
            "comparisonBaselineProposalIds": [
                str(item.get("proposalId") or "") for item in comparison_baseline if str(item.get("proposalId") or "")
            ],
            "suppressedLegacyProjectionIds": suppressed_legacy_ids,
        }

    def _bind_same_root_search_exclusions(
        self,
        *,
        session_id: str,
        assistant_turn_id: str,
        pipeline_context: dict[str, Any],
    ) -> None:
        """Project existing cards into read-only flexible-POI search exclusions."""

        claim = (
            pipeline_context.get("partialPlanExpansionClaim")
            if isinstance(pipeline_context.get("partialPlanExpansionClaim"), dict)
            else {}
        )
        root_portfolio_id = str(claim.get("rootPortfolioId") or "").strip()
        planning_root_id = str(claim.get("planningSelectionRootTurnId") or "").strip()
        if not root_portfolio_id or not planning_root_id:
            return
        baseline = self._comparison_novelty_baseline(
            session_id=session_id,
            planning_root_id=planning_root_id,
            root_portfolio_id=root_portfolio_id,
            current_assistant_turn_id=assistant_turn_id,
        )
        visible_ids = {
            str(item).strip().upper()
            for projection in baseline.get("projections") or []
            if isinstance(projection, dict)
            for item in PlanComparisonPreviewService.physical_poi_ids(projection)
            if str(item).strip()
        }
        visible_ids.update(
            str(item).strip().upper()
            for item in pipeline_context.get("visiblePhysicalPoiIds") or []
            if str(item).strip()
        )
        excluded_ids = {
            *visible_ids,
            *{
                str(item).strip().upper()
                for item in pipeline_context.get("excludedFlexiblePhysicalPoiIds") or []
                if str(item).strip()
            },
        }
        pipeline_context.update(
            {
                "planningSelectionRootTurnId": planning_root_id,
                "rootPortfolioId": root_portfolio_id,
                "visiblePhysicalPoiIds": sorted(visible_ids),
                "excludedFlexiblePhysicalPoiIds": sorted(excluded_ids),
                "searchExclusionContext": {
                    "planningSelectionRootTurnId": planning_root_id,
                    "rootPortfolioId": root_portfolio_id,
                    "visiblePhysicalPoiCount": len(visible_ids),
                    "excludedFlexiblePhysicalPoiCount": len(excluded_ids),
                    "baselineProposalIds": list(baseline.get("comparisonBaselineProposalIds") or []),
                },
            }
        )

    def _partial_preview_novelty_audit(
        self,
        *,
        session_id: str,
        planning_root_id: str,
        root_portfolio_id: str,
        candidate_projection: dict[str, Any],
        current_assistant_turn_id: str,
    ) -> dict[str, Any]:
        """Compare a candidate with cards already visible for the same root."""

        baseline = self._comparison_novelty_baseline(
            session_id=session_id,
            planning_root_id=planning_root_id,
            root_portfolio_id=root_portfolio_id,
            current_assistant_turn_id=current_assistant_turn_id,
        )
        audit = PlanComparisonPreviewService.material_novelty_audit(
            candidate_projection,
            baseline["projections"],
        )
        return {
            **audit,
            "priorProjectionCount": baseline["historicalProjectionCount"],
            "historicalProjectionCount": baseline["historicalProjectionCount"],
            "comparisonBaselineProposalIds": baseline["comparisonBaselineProposalIds"],
            "suppressedLegacyProjectionIds": baseline["suppressedLegacyProjectionIds"],
        }

    @staticmethod
    def _qualified_partial_comparison_projection(
        projection: Any,
        *,
        root_portfolio_id: str,
        planning_root_id: str,
        request_fingerprint: str,
        focus_brief_id: str,
        expected_base_version_id: str,
        source_assistant_turn_id: str,
    ) -> Optional[str]:
        """Return the stable id of one fully audited, read-only partial preview."""

        if not isinstance(projection, dict):
            return None
        proposal_id = str(projection.get("proposalId") or "")
        evidence = (
            projection.get("partialPreviewEvidence")
            if isinstance(projection.get("partialPreviewEvidence"), dict)
            else {}
        )
        audit = evidence.get("groundingAudit") if isinstance(evidence.get("groundingAudit"), dict) else {}
        novelty = evidence.get("materialNoveltyAudit") if isinstance(evidence.get("materialNoveltyAudit"), dict) else {}
        expected_proposal_id = f"partial-preview:{root_portfolio_id}:{focus_brief_id}"
        expected_choice_id = f"preview_partial_{root_portfolio_id}_{focus_brief_id}"
        novelty_mode = str(novelty.get("noveltyMode") or "physical")
        try:
            anchor_count = int(audit.get("anchorCount") or 0)
            matched_anchor_count = int(audit.get("matchedAnchorCount") or 0)
            unmatched_anchor_count = int(audit.get("unmatchedAnchorCount") or 0)
            required_binding_count = int(evidence.get("requiredCandidateBindingActualCount") or 0)
            hard_lineage_missing = int(evidence.get("hardCandidateLineageMissingCount") or 0)
            pending_slot_count = int(evidence.get("pendingSlotCount") or 0)
            projected_anchor_count = int(evidence.get("projectedRouteAnchorCount") or 0)
            write_deltas = tuple(int(audit.get(key) or 0) for key in ("versionDelta", "patchDelta", "routeWriteDelta"))
            novelty_threshold = float(novelty.get("threshold"))
            novelty_distance = float(novelty.get("minimumDistance"))
            novelty_new_poi_count = int(novelty.get("minimumNewPoiCount") or 0)
            candidate_physical_poi_count = int(novelty.get("candidatePhysicalPoiCount") or 0)
            novelty_qualified = bool(
                novelty_mode == "physical"
                and novelty.get("passed") is True
                and novelty_threshold == PlanComparisonPreviewService.MATERIAL_NOVELTY_THRESHOLD
                and novelty_distance >= novelty_threshold
                and novelty_new_poi_count >= 1
                and candidate_physical_poi_count > 0
            )
        except (TypeError, ValueError):
            return None
        projected_physical_poi_count = len(PlanComparisonPreviewService.physical_poi_ids(projection))
        visible_segment_count = sum(
            len(day.get("segments") or []) for day in projection.get("days") or [] if isinstance(day, dict)
        )
        if not (
            projection.get("isPartial") is True
            and projection.get("adoptionReady") is False
            and projection.get("isAdopted") is not True
            and not str(projection.get("activeVersionId") or "")
            and str(projection.get("rootPortfolioId") or "") == root_portfolio_id
            and str(projection.get("planningSelectionRootTurnId") or "") == planning_root_id
            and str(projection.get("requestContractFingerprint") or "") == request_fingerprint
            and str(projection.get("focusBriefId") or "") == focus_brief_id
            and str(projection.get("expectedBaseVersionId") or "") == expected_base_version_id
            and str(projection.get("sourceAssistantTurnId") or "") == source_assistant_turn_id
            and proposal_id == expected_proposal_id
            and str(projection.get("choiceId") or "") == expected_choice_id
            and str(evidence.get("focusBriefId") or "") == focus_brief_id
            and str(audit.get("focusBriefId") or "") == focus_brief_id
            and audit.get("partialEligible") is True
            and audit.get("writeAttempted") is False
            and write_deltas == (0, 0, 0)
            and anchor_count > 0
            and matched_anchor_count == anchor_count
            and unmatched_anchor_count == 0
            and projected_anchor_count == anchor_count
            and visible_segment_count == anchor_count
            and required_binding_count > 0
            and hard_lineage_missing == 0
            and pending_slot_count > 0
            and novelty_qualified
            and projected_physical_poi_count == anchor_count
            and candidate_physical_poi_count == projected_physical_poi_count
        ):
            return None
        return proposal_id

    @staticmethod
    def _classify_partial_expansion_cursor(
        *,
        succeeded: bool,
        resolved_focus_brief_id: str,
        resolved_brief_status: str,
        next_brief_id: str,
        frontier: Optional[dict[str, Any]],
        failure_reason_codes: Optional[list[str]] = None,
        failure_reason: str = "",
    ) -> dict[str, Any]:
        """Classify one bounded attempt without treating an empty cursor as exhaustion."""

        failed_attempt = bool(not succeeded and resolved_focus_brief_id and resolved_brief_status == "failed")
        empty = {
            "cursorAdvanced": False,
            "cursorExhausted": False,
            "boundedAttemptConsumed": False,
            "continuationFocusMode": None,
        }
        if not failed_attempt:
            return empty

        failure_signals = [
            str(item or "").casefold()
            for item in [*(failure_reason_codes or []), failure_reason]
            if str(item or "").strip()
        ]
        transient_tokens = (
            "provider_timeout",
            "provider_transport",
            "provider_rate_limit",
            "rate_limited",
            "transport_error",
            "connection_timeout",
        )
        if any(token in signal for signal in failure_signals for token in transient_tokens):
            return empty

        if next_brief_id and next_brief_id != resolved_focus_brief_id:
            return {
                "cursorAdvanced": True,
                "cursorExhausted": False,
                "boundedAttemptConsumed": True,
                "continuationFocusMode": "exact",
            }

        authoritative = frontier if isinstance(frontier, dict) else {}
        continuable = CreativeExplorationFrontierService.can_continue(authoritative)
        if continuable:
            return {
                "cursorAdvanced": True,
                "cursorExhausted": False,
                "boundedAttemptConsumed": True,
                "continuationFocusMode": "discover_next",
            }
        return {
            "cursorAdvanced": False,
            "cursorExhausted": True,
            "boundedAttemptConsumed": True,
            "continuationFocusMode": None,
        }

    def _partial_plan_expansion_outcome(
        self,
        *,
        session_id: str,
        request_context: dict[str, Any],
        response: AgentMessageResponse,
    ) -> dict[str, Any]:
        claim = (
            request_context.get("partialPlanExpansionClaim")
            if isinstance(request_context.get("partialPlanExpansionClaim"), dict)
            else {}
        )
        root_portfolio_id = str(claim.get("rootPortfolioId") or "")
        planning_root_id = str(claim.get("planningSelectionRootTurnId") or "")
        request_fingerprint = str(claim.get("requestContractFingerprint") or "")
        cursor_focus_brief_id = str(claim.get("focusBriefId") or "")
        expansion_focus_mode = str(claim.get("expansionFocusMode") or "")
        resolved_focus_brief_id = str(
            claim.get("resolvedFocusBriefId")
            or (cursor_focus_brief_id if expansion_focus_mode == "exact" else "")
            or ""
        )
        active_partial_focus_brief_id = str(claim.get("activePartialFocusBriefId") or "")
        baseline_ids = {str(item) for item in claim.get("proposalIdsBefore") or [] if str(item)}
        portfolio = self.db.execute(
            """SELECT session_id, source_user_turn_id, request_contract_fingerprint,
                status, expires_at, created_at, summary_json
            FROM agent_plan_portfolios WHERE id = ?""",
            (root_portfolio_id,),
        ).fetchone()
        summary = self._json_dict(portfolio["summary_json"]) if portfolio is not None else {}
        exploration_frontier = (
            summary.get("creativeExplorationFrontier")
            if isinstance(summary.get("creativeExplorationFrontier"), dict)
            else {}
        )
        visible_ids = {str(item) for item in summary.get("visibleProposalIds") or [] if str(item)}
        visible_ids_before = {str(item) for item in claim.get("visibleProposalIdsBefore") or [] if str(item)}
        visible_ids_added = visible_ids - visible_ids_before
        visible_ids_removed = visible_ids_before - visible_ids
        brief_generation_state = {
            str(item.get("briefId") or ""): str(item.get("status") or "")
            for item in summary.get("briefGenerationState") or []
            if isinstance(item, dict) and str(item.get("briefId") or "")
        }
        brief_generation_result_type = {
            str(item.get("briefId") or ""): str(item.get("resultType") or "")
            for item in summary.get("briefGenerationState") or []
            if isinstance(item, dict) and str(item.get("briefId") or "")
        }
        brief_generation_reason_codes = {
            str(item.get("briefId") or ""): [str(reason) for reason in item.get("reasonCodes") or [] if str(reason)]
            for item in summary.get("briefGenerationState") or []
            if isinstance(item, dict) and str(item.get("briefId") or "")
        }
        next_brief_id = str(summary.get("nextBriefId") or "")
        rows = self.db.execute(
            """SELECT id, status, brief_json, snapshot_json, score_json, verifier_json
            FROM agent_plan_proposals WHERE portfolio_id = ? ORDER BY rank_index ASC""",
            (root_portfolio_id,),
        ).fetchall()
        persisted_by_id = {str(row["id"]): row for row in rows}
        new_ids = sorted(set(persisted_by_id) - baseline_ids)
        projection_ids: set[str] = set()
        route_pending_projection_ids: set[str] = set()
        partial_projection_candidates: list[dict[str, Any]] = []
        for option in response.assistant_turn.choice_options or []:
            if not isinstance(option, dict):
                continue
            projection = option.get("comparisonProjection")
            if not isinstance(projection, dict):
                continue
            synthetic_partial_preview = bool(
                isinstance(projection.get("partialPreviewEvidence"), dict)
                or str(projection.get("proposalId") or "").startswith("partial-preview:")
                or str(projection.get("choiceId") or "").startswith("preview_partial_")
            )
            if projection.get("isPartial") is True and synthetic_partial_preview:
                partial_projection_candidates.append(projection)
                continue
            if str(projection.get("rootPortfolioId") or "") != root_portfolio_id:
                continue
            if str(projection.get("planningSelectionRootTurnId") or "") != planning_root_id:
                continue
            proposal_id = str(projection.get("proposalId") or "")
            if proposal_id:
                projection_ids.add(proposal_id)
                if str(projection.get("routeStatus") or "") in {
                    "route_pending",
                    "route_partial",
                    "route_provider_failed",
                }:
                    route_pending_projection_ids.add(proposal_id)
        result_assistant_turn_id = str(getattr(response.assistant_turn, "id", "") or "")
        if result_assistant_turn_id:
            result_row = self.db.execute(
                """SELECT agent_response_json FROM conversation_turns
                WHERE id = ? AND session_id = ? AND role = 'assistant' AND status != 'superseded'""",
                (result_assistant_turn_id, session_id),
            ).fetchone()
            result_payload = self._json_dict(result_row["agent_response_json"]) if result_row is not None else {}
            for item in result_payload.get("comparisonProjections") or []:
                if isinstance(item, dict):
                    partial_projection_candidates.append(item)
            for option in result_payload.get("choiceOptions") or []:
                if not isinstance(option, dict):
                    continue
                projection = option.get("comparisonProjection")
                if isinstance(projection, dict):
                    partial_projection_candidates.append(projection)
            for event in list(result_payload.get("planningSteps") or []) + list(result_payload.get("toolEvents") or []):
                if not isinstance(event, dict):
                    continue
                metadata = event.get("metadata") if isinstance(event.get("metadata"), dict) else {}
                projection = metadata.get("comparisonProjection")
                if not isinstance(projection, dict):
                    preview = metadata.get("resultPreview")
                    projection = preview.get("comparisonProjection") if isinstance(preview, dict) else None
                if isinstance(projection, dict):
                    partial_projection_candidates.append(projection)
        qualified_ids: list[str] = []
        qualified_editable_partial_ids: list[str] = []
        for proposal_id in new_ids:
            row = persisted_by_id[proposal_id]
            score = self._json_dict(row["score_json"])
            verifier = self._json_dict(row["verifier_json"])
            proposal_brief = self._json_dict(row["brief_json"])
            snapshot = self._json_dict(row["snapshot_json"])
            readiness = ProposalReadinessService.compute(snapshot, verifier=verifier)
            if (
                proposal_id in visible_ids
                and proposal_id in projection_ids
                and bool(resolved_focus_brief_id)
                and str(proposal_brief.get("briefId") or proposal_brief.get("brief_id") or "")
                == resolved_focus_brief_id
                and self._comparison_delta_eligible(
                    status=str(row["status"] or ""),
                    score=score,
                    verifier=verifier,
                    readiness=readiness,
                )
            ):
                qualified_ids.append(proposal_id)
                if verifier.get("passed") is not True:
                    qualified_editable_partial_ids.append(proposal_id)
        qualified_partial_projection_ids = sorted(
            {
                proposal_id
                for projection in partial_projection_candidates
                for proposal_id in [
                    self._qualified_partial_comparison_projection(
                        projection,
                        root_portfolio_id=root_portfolio_id,
                        planning_root_id=planning_root_id,
                        request_fingerprint=request_fingerprint,
                        focus_brief_id=resolved_focus_brief_id,
                        expected_base_version_id=str(claim.get("activeVersionId") or ""),
                        source_assistant_turn_id=result_assistant_turn_id,
                    )
                ]
                if proposal_id
            }
        )
        session = self._session(session_id)
        plan_id = str(session["active_plan_id"] or "")
        version_delta = int(
            self.db.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session_id,),
            ).fetchone()[0]
        ) - int(claim.get("versionCountBefore") or 0)
        patch_delta = int(
            self.db.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session_id,),
            ).fetchone()[0]
        ) - int(claim.get("patchCountBefore") or 0)
        route_delta = int(
            self.db.execute(
                "SELECT COUNT(*) FROM route_options WHERE plan_id = ?",
                (plan_id,),
            ).fetchone()[0]
        ) - int(claim.get("routeCountBefore") or 0)
        route_content_changed = self._route_content_fingerprint(plan_id) != str(
            claim.get("routeFingerprintBefore") or ""
        )
        identity_matches = bool(
            portfolio is not None
            and str(portfolio["session_id"] or "") == session_id
            and bool(planning_root_id)
            and str(portfolio["source_user_turn_id"] or "") == planning_root_id
            and bool(request_fingerprint)
            and str(portfolio["request_contract_fingerprint"] or "") == request_fingerprint
        )
        active_version_unchanged = str(session["active_version_id"] or "") == str(claim.get("activeVersionId") or "")
        response_version_id = str(getattr(response.version, "id", "") or "")
        expected_active_version_id = str(claim.get("activeVersionId") or "")
        response_version_unchanged = not response_version_id or response_version_id == expected_active_version_id
        zero_write = (
            response_version_unchanged
            and version_delta == 0
            and patch_delta == 0
            and route_delta == 0
            and not route_content_changed
            and active_version_unchanged
        )
        focus_matches = bool(
            (expansion_focus_mode == "exact" and resolved_focus_brief_id == cursor_focus_brief_id)
            or (
                expansion_focus_mode == "discover_next"
                and bool(resolved_focus_brief_id)
                and resolved_focus_brief_id != active_partial_focus_brief_id
            )
        )
        resolved_brief_status = str(brief_generation_state.get(resolved_focus_brief_id) or "")
        resolved_brief_result_type = str(brief_generation_result_type.get(resolved_focus_brief_id) or "")
        qualified_id_set = set(qualified_ids)
        qualified_partial_id_set = set(qualified_partial_projection_ids)
        persisted_partial_ids = {
            proposal_id
            for proposal_id in new_ids
            if proposal_id in qualified_partial_id_set
            and proposal_id in visible_ids
            and str(persisted_by_id[proposal_id]["status"] or "")
            in {
                "partial_preview",
                "route_pending",
                "route_partial",
                "route_ready",
                "route_provider_failed",
                "adoption_ready",
                "blocked",
            }
            and str(
                self._json_dict(persisted_by_id[proposal_id]["brief_json"]).get("briefId")
                or self._json_dict(persisted_by_id[proposal_id]["brief_json"]).get("brief_id")
                or ""
            )
            == resolved_focus_brief_id
        }
        partial_delta_valid = bool(
            not qualified_partial_id_set
            or (
                len(qualified_partial_id_set) == 1
                and persisted_partial_ids == qualified_partial_id_set
                and resolved_brief_status == "completed"
                and resolved_brief_result_type == "partial_preview"
            )
        )
        qualified_delta_set = qualified_id_set | qualified_partial_id_set
        exact_qualified_delta = bool(
            qualified_delta_set
            and set(new_ids) == qualified_delta_set
            and visible_ids_added == qualified_delta_set
            and not visible_ids_removed
            and partial_delta_valid
        )
        full_success = bool(exact_qualified_delta and qualified_id_set)
        partial_success = bool(exact_qualified_delta and qualified_partial_id_set)
        succeeded = bool(identity_matches and focus_matches and zero_write and exact_qualified_delta)
        resolved_brief_reason_codes = list(brief_generation_reason_codes.get(resolved_focus_brief_id) or [])
        cursor_classification = self._classify_partial_expansion_cursor(
            succeeded=succeeded,
            resolved_focus_brief_id=resolved_focus_brief_id,
            resolved_brief_status=resolved_brief_status,
            next_brief_id=next_brief_id,
            frontier=exploration_frontier,
            failure_reason_codes=resolved_brief_reason_codes,
            failure_reason=str(getattr(response.assistant_turn, "failure_reason", "") or ""),
        )
        cursor_advanced = bool(cursor_classification["cursorAdvanced"])
        cursor_exhausted = bool(cursor_classification["cursorExhausted"])
        bounded_attempt_consumed = bool(cursor_classification["boundedAttemptConsumed"])
        novelty_rejected = "partial_preview_not_materially_distinct" in resolved_brief_reason_codes
        has_route_pending_proposal = bool(set(qualified_ids) & route_pending_projection_ids)
        has_editable_partial_proposal = bool(set(qualified_ids) & set(qualified_editable_partial_ids))
        return {
            "succeeded": succeeded,
            "reason": (
                "new_route_pending_proposal"
                if succeeded and full_success and has_route_pending_proposal
                else "new_adoption_ready_partial_proposal"
                if succeeded and full_success and has_editable_partial_proposal
                else "new_verified_proposal"
                if succeeded and full_success
                else "new_grounded_partial_preview"
                if succeeded and partial_success
                else "partial_preview_not_materially_distinct"
                if novelty_rejected
                else "no_verified_proposal_delta"
            ),
            "planningSelectionRootTurnId": planning_root_id,
            "rootPortfolioId": root_portfolio_id,
            "requestContractFingerprint": request_fingerprint,
            "focusBriefId": resolved_focus_brief_id,
            "cursorFocusBriefId": cursor_focus_brief_id,
            "resolvedFocusBriefId": resolved_focus_brief_id,
            "activePartialFocusBriefId": active_partial_focus_brief_id,
            "expansionFocusMode": expansion_focus_mode,
            "activeVersionIdBefore": claim.get("activeVersionId"),
            "activeVersionIdAfter": session["active_version_id"],
            "proposalIdsBefore": sorted(baseline_ids),
            "visibleProposalIdsBefore": list(claim.get("visibleProposalIdsBefore") or []),
            "visibleProposalCountBefore": int(claim.get("visibleProposalCountBefore") or 0),
            "newProposalIds": new_ids,
            "qualifiedProposalIds": qualified_ids,
            "qualifiedPartialProjectionIds": qualified_partial_projection_ids,
            "partialProjectionDelta": len(qualified_partial_projection_ids),
            "visibleProposalIdsAfter": sorted(visible_ids),
            "visibleProposalCountAfter": len(visible_ids),
            "proposalDelta": len(new_ids),
            "versionDelta": version_delta,
            "patchDelta": patch_delta,
            "routeWriteDelta": route_delta,
            "zeroWrite": zero_write,
            "activeVersionUnchanged": active_version_unchanged,
            "responseVersionId": response_version_id or None,
            "responseVersionUnchanged": response_version_unchanged,
            "identityMatches": identity_matches,
            "comparisonProjectionIds": sorted(projection_ids),
            "briefAttemptStatus": resolved_brief_status or None,
            "briefAttemptResultType": resolved_brief_result_type or None,
            "briefAttemptReasonCodes": resolved_brief_reason_codes,
            "nextBriefId": next_brief_id or None,
            "cursorAdvanced": cursor_advanced,
            "cursorExhausted": cursor_exhausted,
            "boundedAttemptConsumed": bounded_attempt_consumed,
            "continuationFocusMode": cursor_classification["continuationFocusMode"],
            "frontierState": str(exploration_frontier.get("frontierState") or "") or None,
            "frontierRemainingBudget": int(exploration_frontier.get("remainingBudget") or 0),
        }

    def _set_partial_plan_expansion_reply(
        self,
        response: AgentMessageResponse,
        outcome: dict[str, Any],
        *,
        recoverable_terminal: bool = False,
    ) -> None:
        """Persist a product-facing expansion result instead of a generic partial reply."""

        if outcome.get("succeeded") is True:
            partial_count = len(outcome.get("qualifiedPartialProjectionIds") or [])
            if partial_count:
                reply = f"已在行程对比中追加 {partial_count} 个真实地点已核验的部分方案；当前时间轴未发生变化。"
            else:
                proposal_count = len(outcome.get("qualifiedProposalIds") or [])
                if outcome.get("reason") == "new_route_pending_proposal":
                    reply = (
                        f"已在行程对比中追加 {proposal_count} 个地点与语义已核验、"
                        "路线待核验的新方案；当前时间轴未发生变化。"
                    )
                else:
                    reply = f"已在行程对比中追加 {proposal_count} 个通过完整校验的新方案；当前时间轴未发生变化。"
        elif (
            outcome.get("cursorAdvanced") is True and outcome.get("reason") == "partial_preview_not_materially_distinct"
        ):
            reply = (
                "该方向与已有方案的实际地点重合度过高，未追加重复方案；"
                "当前方案、已有对比卡和时间轴均未发生变化。"
                "已推进到下一个旅行方向，可在本轮新选项中继续生成。"
            )
        elif outcome.get("cursorAdvanced") is True:
            reply = (
                "当前方向暂未形成可验证方案；当前方案和时间轴未发生变化。"
                "已推进到下一个旅行方向，可在本轮新选项中继续生成。"
            )
        elif (
            outcome.get("cursorExhausted") is True
            and outcome.get("reason") == "partial_preview_not_materially_distinct"
        ):
            reply = "其余方向与已有方案的实际地点重合度过高，未追加重复方案；当前方案、已有对比卡和时间轴均未发生变化。"
        elif outcome.get("cursorExhausted") is True:
            reply = "当前已生成全部可验证方向。你可以刷新候选、放宽偏好或指定新的旅行主题。"
        else:
            reply = "本次生成因候选或服务状态未完成；当前方案和时间轴未发生变化。你可以重试当前方向。"
        row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
            (response.assistant_turn.id,),
        ).fetchone()
        payload = self._json_dict(row["agent_response_json"]) if row is not None else {}
        payload["reply"] = reply
        if recoverable_terminal:
            payload["terminalStatus"] = "needs_confirmation"
            payload.pop("failureReason", None)
        self.db.execute(
            """UPDATE conversation_turns
            SET content = ?,
                status = CASE WHEN ? THEN 'active' ELSE status END,
                error_json = CASE WHEN ? THEN NULL ELSE error_json END,
                agent_response_json = ?, updated_at = ?
            WHERE id = ?""",
            (
                reply,
                recoverable_terminal,
                recoverable_terminal,
                json.dumps(payload, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                response.assistant_turn.id,
            ),
        )
        response.assistant_turn.content = reply
        if recoverable_terminal:
            response.assistant_turn.status = "active"
            response.assistant_turn.failure_reason = None
            response.terminal_status = "needs_confirmation"

    def _complete_controller_choice_execution(
        self,
        session_id: str,
        user_turn_id: str,
        response: AgentMessageResponse,
    ) -> None:
        row = self.db.execute(
            "SELECT agent_request_json FROM conversation_turns WHERE id = ? AND session_id = ?",
            (user_turn_id, session_id),
        ).fetchone()
        if row is None:
            return
        request_context = self._json_dict(row["agent_request_json"])
        selected_choice = (
            request_context.get("selectedAgentChoice")
            if isinstance(request_context.get("selectedAgentChoice"), dict)
            else request_context.get("spatialBoundaryChoice")
            if isinstance(request_context.get("spatialBoundaryChoice"), dict)
            else {}
        )
        action = str(selected_choice.get("action") or "")
        normalized_action = str(selected_choice.get("normalizedAction") or action)
        if (
            action
            not in {
                "retry_model_planning",
                "manual_continuation",
                "continue_plan_expansion",
                "continue_clarification",
                "submit_clarification_batch",
                "search_travel_guide_advice",
                "select_spatial_boundary_candidate",
                "confirm_spatial_boundary",
                "change_spatial_boundary",
                "retry_spatial_grounding",
            }
            and normalized_action not in DENSITY_ACTIONS
        ):
            return
        claim = (
            request_context.get("fallbackChoiceExecutionClaim")
            if isinstance(request_context.get("fallbackChoiceExecutionClaim"), dict)
            else {}
        )
        execution_id = str(claim.get("id") or "")
        if not execution_id:
            return
        if action in {
            "continue_clarification",
            "submit_clarification_batch",
            "select_spatial_boundary_candidate",
            "confirm_spatial_boundary",
            "change_spatial_boundary",
            "retry_spatial_grounding",
        }:
            if response.assistant_turn.status == "failed":
                self._finish_fallback_choice_execution(
                    execution_id,
                    "failed_retryable",
                    execution_turn_id=response.assistant_turn.id,
                    outcome={
                        "reason": "clarification_turn_failed",
                        "versionDelta": 0,
                        "patchDelta": 0,
                        "routeWriteDelta": 0,
                    },
                )
                return
            checkpoint = (
                request_context.get("clarificationCheckpoint")
                if isinstance(request_context.get("clarificationCheckpoint"), dict)
                else {}
            )
            self._finish_fallback_choice_execution(
                execution_id,
                "succeeded",
                execution_turn_id=response.assistant_turn.id,
                outcome={
                    "reason": (
                        "clarification_batch_resolved"
                        if action == "submit_clarification_batch"
                        else "spatial_boundary_candidate_selected"
                        if action == "select_spatial_boundary_candidate"
                        else "spatial_boundary_confirmed"
                        if action == "confirm_spatial_boundary"
                        else "spatial_boundary_change_requested"
                        if action == "change_spatial_boundary"
                        else "spatial_grounding_retried"
                        if action == "retry_spatial_grounding"
                        else "clarification_checkpoint_advanced"
                    ),
                    "checkpointId": checkpoint.get("checkpointId"),
                    "checkpointStatus": checkpoint.get("status"),
                    "contractVersion": checkpoint.get("contractVersion"),
                    "versionDelta": 0,
                    "patchDelta": 0,
                    "routeWriteDelta": 0,
                },
            )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return
        continuation = (
            request_context.get("portfolioDensityContinuation")
            if isinstance(request_context.get("portfolioDensityContinuation"), dict)
            else {}
        )
        structured_resume = bool(request_context.get("structuredPlanningChoiceResume"))
        execution_row = self.db.execute(
            "SELECT attempt FROM agent_choice_executions WHERE id = ?",
            (execution_id,),
        ).fetchone()
        execution_attempt = max(int(execution_row["attempt"] or 1), 1) if execution_row is not None else 1
        bounded_density_provider_actions = {
            DENSITY_REFRESH_ACTION,
            DENSITY_NEARBY_ACTION,
        }
        density_provider_retry_limit = 2
        partial_expansion = request_context.get("_partialPlanExpansionAuthorized") is True
        partial_expansion_outcome = (
            self._partial_plan_expansion_outcome(
                session_id=session_id,
                request_context=request_context,
                response=response,
            )
            if partial_expansion and response.assistant_turn.status == "failed"
            else None
        )
        bounded_expansion_failure = bool(
            response.assistant_turn.status == "failed"
            and partial_expansion
            and partial_expansion_outcome.get("boundedAttemptConsumed") is True
            and partial_expansion_outcome.get("identityMatches") is True
            and partial_expansion_outcome.get("zeroWrite") is True
        )
        failure_reason = str(response.assistant_turn.failure_reason or "")
        claimed_frontier_terminalized = bool(
            response.assistant_turn.status == "failed"
            and SimpleDirectionExecutionEvidenceService(self.db).terminalize_claimed_frontier_execution(
                execution_id,
                execution_turn_id=response.assistant_turn.id,
                reason_code="simple_direction_execution_failed_after_claim",
                outcome={
                    "sourceFailureReason": failure_reason or None,
                    "checkpointFingerprint": continuation.get("checkpointFingerprint"),
                    "retryAttempt": execution_attempt,
                },
            )
        )
        if claimed_frontier_terminalized:
            if bounded_expansion_failure:
                self._set_partial_plan_expansion_reply(
                    response,
                    partial_expansion_outcome,
                    recoverable_terminal=True,
                )
            self._finalize_planning_material_choice(request_context, succeeded=False)
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return
        if bounded_expansion_failure:
            self._set_partial_plan_expansion_reply(
                response,
                partial_expansion_outcome,
                recoverable_terminal=True,
            )
            self._finalize_planning_material_choice(request_context, succeeded=False)
            self._finish_fallback_choice_execution(
                execution_id,
                "failed_terminal",
                execution_turn_id=response.assistant_turn.id,
                outcome=partial_expansion_outcome,
            )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return
        if response.assistant_turn.status == "failed":
            frontier_exhausted = failure_reason.startswith("creative_frontier_") and "exhausted" in failure_reason
            if frontier_exhausted:
                self._finalize_planning_material_choice(request_context, succeeded=False)
                self._finish_fallback_choice_execution(
                    execution_id,
                    "failed_terminal",
                    execution_turn_id=response.assistant_turn.id,
                    outcome={
                        "reason": "creative_frontier_exhausted",
                        "exhaustionReason": failure_reason,
                        "versionDelta": 0,
                        "patchDelta": 0,
                        "routeWriteDelta": 0,
                        "zeroWrite": True,
                    },
                )
                self._consume_selected_agent_choice(session_id, selected_choice)
                self.db.commit()
                return
            provider_failure = structured_resume and any(
                marker in failure_reason.casefold()
                for marker in (
                    "provider",
                    "amap",
                    "rate_limit",
                    "timeout",
                    "高德",
                    "地图",
                )
            )
            provider_retry_exhausted = bool(
                provider_failure
                and normalized_action in bounded_density_provider_actions
                and execution_attempt >= density_provider_retry_limit
            )
            self._finalize_planning_material_choice(request_context, succeeded=False)
            self._finish_fallback_choice_execution(
                execution_id,
                "failed_terminal" if provider_retry_exhausted else "failed_retryable",
                outcome={
                    "reason": ("provider_failure" if provider_failure else "assistant_turn_failed"),
                    "providerFailure": failure_reason if provider_failure else None,
                    "checkpointFingerprint": continuation.get("checkpointFingerprint"),
                    "retryAttempt": execution_attempt,
                    "retryLimit": density_provider_retry_limit if provider_failure else None,
                    "boundedAttemptConsumed": provider_retry_exhausted,
                },
            )
            if provider_retry_exhausted:
                self._consume_selected_agent_choice(session_id, selected_choice)
                self.db.commit()
            return
        selected_option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        assistant_payload_row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ?",
            (response.assistant_turn.id, session_id),
        ).fetchone()
        assistant_payload = (
            self._json_dict(assistant_payload_row["agent_response_json"]) if assistant_payload_row is not None else {}
        )
        simple_direction_reason = str(assistant_payload.get("reasonCode") or "")
        simple_direction_provider_pending = simple_direction_reason in {
            "simple_direction_frontier_provider_pending",
            "simple_direction_frontier_provider_schema_pending",
        }
        simple_direction_continuation_completion = bool(
            action == "continue_plan_expansion"
            and str(selected_option.get("kind") or "") == "simple_direction_more_plans"
            and not simple_direction_provider_pending
            and str(assistant_payload.get("mode") or "") == "simple_open_direction_proposal"
            and str(assistant_payload.get("workflowMode") or "") == SimpleOpenDirectionService.WORKFLOW_MODE
        )
        simple_direction_initial_retry_completion = bool(
            action == "retry_model_planning"
            and str(selected_option.get("kind") or "") == "safe_fallback_action"
            and not simple_direction_provider_pending
            and str(assistant_payload.get("mode") or "") == "simple_open_direction_proposal"
            and str(assistant_payload.get("workflowMode") or "") == SimpleOpenDirectionService.WORKFLOW_MODE
        )
        simple_direction_completion_evidence = (
            SimpleDirectionExecutionEvidenceService(self.db).verify(
                execution_id,
                assistant_turn_id=response.assistant_turn.id,
                expected_request_turn_id=user_turn_id,
            )
            if simple_direction_continuation_completion
            else SimpleDirectionExecutionEvidenceService(self.db).verify_initial_retry(
                execution_id,
                assistant_turn_id=response.assistant_turn.id,
                expected_request_turn_id=user_turn_id,
            )
            if simple_direction_initial_retry_completion
            else {"passed": False, "reason": "not_simple_direction_completion"}
        )
        simple_direction_choice_progress = simple_direction_completion_evidence.get("passed") is True
        if simple_direction_choice_progress:
            proposal_delta = int(simple_direction_completion_evidence.get("proposalDelta") or 0)
            initial_partial_proposal = bool(simple_direction_completion_evidence.get("partialProposal"))
            simple_direction_success_reason = (
                "new_simple_direction_partial_proposal"
                if initial_partial_proposal
                else "new_simple_direction_proposal"
                if proposal_delta > 0
                else "simple_direction_frontier_advanced_without_proposal"
            )
            self._finalize_planning_material_choice(request_context, succeeded=True)
            self._finish_fallback_choice_execution(
                execution_id,
                "succeeded",
                execution_turn_id=response.assistant_turn.id,
                outcome={
                    "reason": simple_direction_success_reason,
                    "planningSelectionRootTurnId": simple_direction_completion_evidence.get(
                        "planningSelectionRootTurnId"
                    ),
                    "rootPortfolioId": simple_direction_completion_evidence.get("rootPortfolioId"),
                    "frontierExecutionId": simple_direction_completion_evidence.get("frontierExecutionId"),
                    "frontierStatus": simple_direction_completion_evidence.get("frontierStatus"),
                    "reasonCode": simple_direction_reason or None,
                    "proposalDelta": proposal_delta,
                    "versionDelta": 0,
                    "patchDelta": 0,
                    "routeWriteDelta": 0,
                    "zeroWrite": True,
                    "boundedAttemptConsumed": True,
                    "needsMoreInput": bool(response.assistant_turn.choice_options),
                    "completionEvidence": copy.deepcopy(simple_direction_completion_evidence),
                },
            )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return
        if simple_direction_continuation_completion or simple_direction_initial_retry_completion:
            # The exact Simple Direction path was selected and returned a
            # Simple Direction result, but its persisted lineage failed the
            # action-specific evidence contract.  Do not fall through to the
            # generic no-progress retry path: that would reopen a consumed
            # frontier cursor or treat client-shaped proposal counters as
            # execution authority.
            completion_failure_reason = str(
                simple_direction_completion_evidence.get("reason") or "simple_direction_execution_evidence_invalid"
            )
            completion_failure_outcome = {
                "reason": completion_failure_reason,
                "completionEvidence": copy.deepcopy(simple_direction_completion_evidence),
                "boundedAttemptConsumed": True,
            }
            self._finalize_planning_material_choice(request_context, succeeded=False)
            claimed_frontier_terminalized = SimpleDirectionExecutionEvidenceService(
                self.db
            ).terminalize_claimed_frontier_execution(
                execution_id,
                execution_turn_id=response.assistant_turn.id,
                reason_code=completion_failure_reason,
                outcome=completion_failure_outcome,
            )
            if not claimed_frontier_terminalized:
                self._finish_fallback_choice_execution(
                    execution_id,
                    "failed_terminal",
                    execution_turn_id=response.assistant_turn.id,
                    outcome=completion_failure_outcome,
                )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return
        choice_options = list(response.assistant_turn.choice_options or [])
        partial_expansion = request_context.get("_partialPlanExpansionAuthorized") is True
        partial_expansion_outcome = (
            self._partial_plan_expansion_outcome(
                session_id=session_id,
                request_context=request_context,
                response=response,
            )
            if partial_expansion
            else None
        )
        if partial_expansion:
            self._set_partial_plan_expansion_reply(response, partial_expansion_outcome)
        if partial_expansion and not bool(partial_expansion_outcome.get("succeeded")):
            self._finalize_planning_material_choice(request_context, succeeded=False)
            bounded_attempt_consumed = bool(partial_expansion_outcome.get("boundedAttemptConsumed"))
            self._finish_fallback_choice_execution(
                execution_id,
                "failed_terminal" if bounded_attempt_consumed else "failed_retryable",
                execution_turn_id=response.assistant_turn.id,
                outcome=partial_expansion_outcome,
            )
            if bounded_attempt_consumed:
                self._consume_selected_agent_choice(session_id, selected_choice)
            else:
                execution = self.db.execute(
                    "SELECT * FROM agent_choice_executions WHERE id = ?",
                    (execution_id,),
                ).fetchone()
                if execution is not None:
                    self._unconsume_fallback_choice(execution)
                    self.db.commit()
            return
        if partial_expansion:
            self._finalize_planning_material_choice(request_context, succeeded=True)
            self._finish_fallback_choice_execution(
                execution_id,
                "succeeded",
                execution_turn_id=response.assistant_turn.id,
                outcome=partial_expansion_outcome,
            )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.commit()
            return
        candidate_gap_clarification = bool(
            action == "retry_model_planning"
            and str(selected_option.get("kind") or "") == "safe_fallback_action"
            and all(
                str(selected_option.get(key) or "").strip()
                for key in (
                    "candidateGapFingerprint",
                    "requestContractFingerprint",
                    "checkpointFingerprint",
                    "planningSelectionRootTurnId",
                    "goalId",
                    "occurrenceId",
                    "briefId",
                    "poolId",
                    "planningSlotId",
                    "attemptIdentity",
                )
            )
            and int(selected_option.get("dayNumber") or 0) > 0
            and choice_options
            and all(
                isinstance(option, dict)
                and str(option.get("kind") or "") == "clarification_checkpoint"
                and str(option.get("action") or "") == "continue_clarification"
                and str(option.get("checkpointId") or "").strip()
                and str(option.get("dimensionId") or "").strip()
                and str(option.get("planningSelectionRootTurnId") or "").strip()
                == str(selected_option.get("planningSelectionRootTurnId") or "").strip()
                for option in choice_options
            )
        )
        has_material_clarification = bool(
            candidate_gap_clarification
            or (
                choice_options
                and any(
                    str(option.get("kind") or "")
                    in {
                        "poi_candidate",
                        "material_tradeoff",
                        "portfolio_density_candidate",
                    }
                    or bool(option.get("candidateRecordId"))
                    for option in choice_options
                    if isinstance(option, dict)
                )
            )
        )
        density_progress = (
            self.portfolio_density_continuation.made_progress(response, continuation) if structured_resume else None
        )
        committed_density_slot = bool(
            structured_resume and normalized_action == DENSITY_CANDIDATE_ACTION and response.version is not None
        )
        candidate_search_actions = {
            DENSITY_REFRESH_ACTION,
            DENSITY_NEARBY_ACTION,
            DENSITY_MANUAL_SEARCH_ACTION,
        }
        new_density_candidates = bool(
            structured_resume
            and normalized_action in candidate_search_actions
            and self.portfolio_density_continuation.has_new_candidate_options(
                response,
                continuation,
            )
        )
        if new_density_candidates:
            self._finalize_planning_material_choice(request_context, succeeded=False)
            self._finish_fallback_choice_execution(
                execution_id,
                "succeeded",
                execution_turn_id=response.assistant_turn.id,
                outcome={
                    "reason": "new_candidates_awaiting_confirmation",
                    "checkpointFingerprint": continuation.get("checkpointFingerprint"),
                    "targetPlanningSlotId": continuation.get("planningSlotId"),
                    "targetScope": {
                        key: continuation.get(key)
                        for key in (
                            "planningSelectionRootTurnId",
                            "rootPortfolioId",
                            "requestContractFingerprint",
                            "expectedBaseVersionId",
                            "focusBriefId",
                            "briefId",
                            "poolId",
                            "planningSlotId",
                            "dayNumber",
                        )
                    },
                    "needsMoreInput": True,
                },
            )
            return
        provider_failure = self._structured_resume_provider_failure(response) if structured_resume else None
        if provider_failure is not None:
            provider_retry_exhausted = bool(
                normalized_action in bounded_density_provider_actions
                and execution_attempt >= density_provider_retry_limit
            )
            self._finalize_planning_material_choice(request_context, succeeded=False)
            self._finish_fallback_choice_execution(
                execution_id,
                "failed_terminal" if provider_retry_exhausted else "failed_retryable",
                execution_turn_id=response.assistant_turn.id,
                outcome={
                    "reason": "provider_failure",
                    "providerFailure": provider_failure,
                    "checkpointFingerprint": continuation.get("checkpointFingerprint"),
                    "targetPlanningSlotId": continuation.get("planningSlotId"),
                    "retryAttempt": execution_attempt,
                    "retryLimit": density_provider_retry_limit,
                    "boundedAttemptConsumed": provider_retry_exhausted,
                },
            )
            if provider_retry_exhausted:
                self._consume_selected_agent_choice(session_id, selected_choice)
                self.db.commit()
            else:
                execution = self.db.execute(
                    "SELECT * FROM agent_choice_executions WHERE id = ?",
                    (execution_id,),
                ).fetchone()
                if execution is not None:
                    self._unconsume_fallback_choice(execution)
                    self.db.commit()
            return
        if (structured_resume and not density_progress and not committed_density_slot) or (
            not structured_resume and response.version is None and not has_material_clarification
        ):
            bounded_empty_result = bool(
                (structured_resume and normalized_action in bounded_density_provider_actions)
                or (
                    not structured_resume
                    and normalized_action == "retry_model_planning"
                    and str(response.terminal_status or "") == "no_safe_action"
                )
            )
            self._finalize_planning_material_choice(request_context, succeeded=False)
            self._finish_fallback_choice_execution(
                execution_id,
                "failed_terminal" if bounded_empty_result else "failed_retryable",
                execution_turn_id=response.assistant_turn.id,
                outcome={
                    "reason": (
                        "no_new_candidates"
                        if structured_resume and normalized_action in candidate_search_actions
                        else "no_slot_progress"
                        if structured_resume
                        else "no_material_progress"
                    ),
                    "checkpointFingerprint": continuation.get("checkpointFingerprint"),
                    "targetPlanningSlotId": continuation.get("planningSlotId"),
                    "targetScope": {
                        key: continuation.get(key)
                        for key in (
                            "planningSelectionRootTurnId",
                            "rootPortfolioId",
                            "requestContractFingerprint",
                            "expectedBaseVersionId",
                            "focusBriefId",
                            "briefId",
                            "poolId",
                            "planningSlotId",
                            "dayNumber",
                        )
                    },
                    "recommendedNextActions": [
                        "refresh_density_candidates",
                        "expand_density_nearby",
                        "open_density_map",
                    ]
                    if structured_resume
                    else [],
                    "boundedAttemptConsumed": bounded_empty_result,
                    "retryAttempt": execution_attempt,
                },
            )
            if bounded_empty_result:
                self._consume_selected_agent_choice(session_id, selected_choice)
                self.db.commit()
            else:
                execution = self.db.execute(
                    "SELECT * FROM agent_choice_executions WHERE id = ?",
                    (execution_id,),
                ).fetchone()
                if execution is not None:
                    self._unconsume_fallback_choice(execution)
                    self.db.commit()
            return
        self._finalize_planning_material_choice(request_context, succeeded=True)
        self._finish_fallback_choice_execution(
            execution_id,
            "succeeded",
            result_version_id=response.version.id if response.version is not None else None,
            execution_turn_id=response.assistant_turn.id,
            outcome={
                "reason": (
                    "new_verified_proposal"
                    if partial_expansion
                    else "candidate_gap_clarification_checkpoint_created"
                    if candidate_gap_clarification
                    else "slot_covered"
                    if structured_resume
                    else "choice_completed"
                ),
                "checkpointFingerprint": continuation.get("checkpointFingerprint"),
                "targetPlanningSlotId": continuation.get("planningSlotId"),
                "versionDelta": int(response.version is not None),
                "patchDelta": int(bool((response.assistant_turn.timeline_mutation_outcome or {}).get("patchId"))),
                "routeWriteDelta": int(
                    (response.assistant_turn.timeline_mutation_outcome or {}).get("routeWriteDelta") or 0
                ),
                "needsMoreInput": bool(response.assistant_turn.choice_options),
                **(partial_expansion_outcome or {}),
            },
        )

        self._consume_selected_agent_choice(session_id, selected_choice)
        runtime = continuation.get("runtime") if isinstance(continuation.get("runtime"), dict) else {}
        event = AgentPlanningEventResponse(
            type="fallback_controller_choice_completed",
            label=(
                "完成其他方案扩展"
                if partial_expansion
                else "完成结构化规划续跑"
                if structured_resume
                else "完成模型 Controller 选择执行"
            ),
            status="completed",
            detail=(
                "已在同一规划根下追加新的持久化、验证通过方案；时间轴保持不变。"
                if partial_expansion
                else "已恢复原规划 directive 并补入所选地点；未重新解释用户文字。"
                if structured_resume
                else "已按结构化 action 仅调用一次 Controller；源选项已消费。"
            ),
            sessionId=session_id,
            turnId=response.assistant_turn.id,
            providerName="agent-controller",
            fallbackUsed=False,
            metadata={
                "executionId": execution_id,
                "action": action,
                "attempt": claim.get("attempt"),
                "controllerCalled": not structured_resume,
                "structuredPlanningChoiceResume": structured_resume,
                "executionRoute": "portfolio_density_resume" if structured_resume else "controller_choice_resume",
                "checkpointFingerprint": continuation.get("checkpointFingerprint"),
                "runtimeBuildId": runtime.get("runtimeBuildId"),
                "runtimeStartedAt": runtime.get("runtimeStartedAt"),
                "resultVersionId": response.version.id if response.version is not None else None,
                "nextConfirmationOffered": bool(response.assistant_turn.choice_options),
                "newProposalIds": (partial_expansion_outcome or {}).get("newProposalIds", []),
                "proposalDelta": (partial_expansion_outcome or {}).get("proposalDelta", 0),
            },
            timestamp=datetime.now(timezone.utc).isoformat(),
        )
        response.planning_steps = [event, *list(response.planning_steps or [])]
        response.tool_events = [event, *list(response.tool_events or [])]
        self._store_planning_events(response.assistant_turn.id, response.planning_steps)
        self.db.commit()

    def _pending_slot_timeline_mutation(
        self,
        session_id: str,
        request_context: dict[str, Any],
        *,
        selection_source: str,
    ) -> tuple[TimelineMutationIntent, MapPoiResponse]:
        selected = (
            request_context.get("selectedPlanningCandidate")
            if isinstance(request_context.get("selectedPlanningCandidate"), dict)
            else {}
        )
        session = self._session(session_id)
        active_version_id = str(session["active_version_id"] or "")
        if not active_version_id:
            raise HTTPException(
                status_code=409,
                detail={"code": "portfolio_partial_timeline_missing", "message": "当前没有可补全的部分时间轴。"},
            )
        version = self._version(active_version_id, session_id, session["active_plan_id"])
        snapshot = json.loads(version["snapshot_json"] or "{}")
        snapshot = PortfolioPendingSlotScheduleService().project(snapshot)
        selection_context = PortfolioPendingSlotService.selection_context(snapshot)
        command = {
            "planningSelectionRootTurnId": selection_context["planningSelectionRootTurnId"],
            "rootPortfolioId": selection_context["rootPortfolioId"],
            "focusBriefId": selection_context["focusBriefId"],
            "requestContractFingerprint": selection_context["requestContractFingerprint"],
            "briefId": selected.get("briefId"),
            "poolId": selected.get("poolId"),
            "planningSlotId": selected.get("planningSlotId"),
            "dayNumber": selected.get("dayNumber"),
        }
        try:
            slot = PortfolioPendingSlotService.find_exact_slot(snapshot, command)
        except PortfolioPendingSlotError as error:
            raise HTTPException(
                status_code=409,
                detail={"code": error.code, "message": error.message},
            ) from error
        if not str(slot.get("startTime") or "").strip() or int(slot.get("durationMinutes") or 0) <= 0:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_pending_slot_schedule_unresolved",
                    "message": "该待补槽位的时间仍待安排，请先刷新槽位排期后再确认地点。",
                },
            )
        amap_poi = MapPoiResponse.model_validate(selected.get("amapPoi"))
        if amap_poi.id != str(selected.get("amapId") or ""):
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_identity_mismatch", "message": "候选地点身份与持久化选择不一致。"},
            )
        intent = TimelineMutationIntent.model_validate(
            {
                "operation": "add_segment",
                "selector": {
                    "dayNumber": int(slot["dayNumber"]),
                    "intentType": str(slot.get("intentType") or selected.get("intentType") or ""),
                    "timeWindow": str(slot.get("timeWindow") or ""),
                },
                "replacement": {
                    "poiQuery": amap_poi.name,
                    "poiQueryMode": "exact_entity",
                    "startTime": str(slot.get("startTime") or ""),
                    "durationMinutes": int(slot.get("durationMinutes") or 0),
                },
                "source": "structured_ui",
                "sourceText": f"确认 Day {slot['dayNumber']}：{amap_poi.name}",
                "pendingSlotSelection": {
                    "selectionSource": selection_source,
                    "planningSelectionRootTurnId": selection_context["planningSelectionRootTurnId"],
                    "rootPortfolioId": selection_context["rootPortfolioId"],
                    "focusBriefId": selection_context["focusBriefId"],
                    "requestContractFingerprint": selection_context["requestContractFingerprint"],
                    "poolId": slot["poolId"],
                    "planningSlotId": slot["planningSlotId"],
                    "dayNumber": slot["dayNumber"],
                    "candidateRecordId": selected.get("candidateRecordId"),
                    "amapId": amap_poi.id,
                    "baseVersionId": active_version_id,
                },
            }
        )
        return intent, amap_poi

    @staticmethod
    def _structured_resume_provider_failure(
        response: AgentMessageResponse,
    ) -> Optional[dict[str, str]]:
        failure_states = {
            "provider_error",
            "provider_failure",
            "provider_unavailable",
            "rate_limited",
            "timeout",
        }

        def find(value: Any) -> Optional[tuple[str, str]]:
            if isinstance(value, dict):
                provider_state = str(value.get("providerState") or "").casefold()
                if provider_state in failure_states:
                    return provider_state, str(
                        value.get("failureReason") or value.get("reason") or value.get("message") or provider_state
                    )
                for nested in value.values():
                    found = find(nested)
                    if found is not None:
                        return found
            elif isinstance(value, list):
                for nested in value:
                    found = find(nested)
                    if found is not None:
                        return found
            return None

        for event in [*response.planning_steps, *response.tool_events]:
            found = find(event.metadata)
            if found is not None:
                return {"providerState": found[0], "failureReason": found[1]}
        return None

    def _finish_fallback_choice_execution(
        self,
        execution_id: str,
        status: str,
        *,
        result_version_id: Optional[str] = None,
        execution_turn_id: Optional[str] = None,
        error: Optional[Exception] = None,
        outcome: Optional[dict[str, Any]] = None,
    ) -> int:
        now = datetime.now(timezone.utc).isoformat()
        self.db.execute(
            """
            UPDATE agent_choice_executions
            SET status = ?, result_version_id = COALESCE(?, result_version_id),
                execution_turn_id = COALESCE(?, execution_turn_id), outcome_json = ?, error_json = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                status,
                result_version_id,
                execution_turn_id,
                json.dumps(outcome, ensure_ascii=False, default=str) if outcome is not None else None,
                json.dumps({"message": self._error_message(error)}, ensure_ascii=False) if error is not None else None,
                now,
                execution_id,
            ),
        )
        self.db.commit()

    def _choice_business_state(self, session_id: str) -> dict[str, Any]:
        from src.services.conversation_capability_carrier import ConversationCapabilityCarrier
        session = self._session(session_id)
        counts = ConversationCapabilityCarrier(self.db).counts(session_id)
        counts.pop("agent_choice_executions", None)
        portfolio_state = [tuple(row) for row in self.db.execute("""SELECT id, source_user_turn_id, source_assistant_turn_id,
            expected_base_version_id, request_contract_fingerprint, status, selected_proposal_id, summary_json
            FROM agent_plan_portfolios WHERE session_id = ? ORDER BY id""", (session_id,))]
        return {"activeVersionId": session["active_version_id"], "activePlanId": session["active_plan_id"],
                "counts": counts, "routeFingerprint": self._route_content_fingerprint(session["active_plan_id"]),
                "portfolioFingerprint": hashlib.sha256(json.dumps(portfolio_state, ensure_ascii=False).encode()).hexdigest()}

    def _finish_guide_binding_dispatch(self, session_id: str, execution_id: str) -> None:
        row = self.db.execute("SELECT * FROM agent_choice_executions WHERE id = ? AND session_id = ?", (execution_id, session_id)).fetchone()
        journal = self._json_dict(row["continuation_json"]) if row else {}
        fence = journal.get("guideBindingDispatch")
        if not fence or fence.get("state") == "dispatching":
            return
        if (fence.get("schemaVersion") != "guide-binding-dispatch-v1" or fence.get("state") != "not_started"
                or not self._guide_binding_scope_valid(dict(row), journal)):
            raise ValueError("guide_binding_dispatch_scope_invalid")
        fence["state"] = "dispatching"
        updated = self.db.execute("""UPDATE agent_choice_executions SET continuation_json = ?, updated_at = ?
            WHERE id = ? AND session_id = ? AND status = 'executing' AND continuation_json IS ?""",
            (json.dumps(journal, ensure_ascii=False), datetime.now(timezone.utc).isoformat(), execution_id, session_id, row["continuation_json"]))
        if updated.rowcount != 1:
            raise ValueError("guide_binding_dispatch_stale")
        # Durable before ANY Controller/executor path, including direct build
        # callers using defer_agent_decision=False. A crash now means unknown.
        self.db.commit()

    def _guide_binding_scope_valid(self, execution: dict[str, Any], journal: dict[str, Any]) -> bool:
        from src.services.conversation_operation_identity import ConversationOperationIdentity
        try:
            option = ConversationOperationIdentity(self.db).source_option_for_execution(execution)
            requirement = journal.get("guideContinuationRequirement") or {}
            identity = journal.get("operationIdentity") or {}
            fence = journal.get("guideBindingDispatch") or {}
            return (identity.get("schemaVersion") == "execution-operation-identity-v1"
                and requirement.get("schemaVersion") == "guide-continuation-requirement-v1"
                and requirement.get("requirementFingerprint") == GuideContinuationRequirementService.requirement_fingerprint(requirement)
                and fence.get("requirementFingerprint") == requirement.get("requirementFingerprint")
                and fence.get("operationId") == identity.get("operationId")
                and fence.get("evidenceFingerprint") == identity.get("guideEvidenceFingerprint")
                and fence.get("evidenceFingerprint") == requirement.get("evidenceFingerprint")
                and all(requirement.get(key) == option.get(key) for key in (
                    "planningSelectionRootTurnId", "rootPortfolioId", "requestContractFingerprint", "expectedBaseVersionId")))
        except (ValueError, TypeError, KeyError, AttributeError):
            return False

    def _settle_unstarted_guide_binding_failure(self, session_id: str, execution_id: str, error: Exception) -> bool:
        """Affirmative zero-business evidence, only for the audited pure window."""
        self.db.execute("SAVEPOINT guide_binding_failure")
        try:
            self.db.execute("UPDATE conversation_sessions SET id = id WHERE id = ?", (session_id,))
            row = self.db.execute("SELECT * FROM agent_choice_executions WHERE id = ? AND session_id = ? AND status = 'executing'", (execution_id, session_id)).fetchone()
            journal = self._json_dict(row["continuation_json"]) if row else {}
            fence = journal.get("guideBindingDispatch") or {}
            identity = journal.get("operationIdentity") or {}
            requirement = journal.get("guideContinuationRequirement") or {}
            eligible = (row is not None and fence.get("schemaVersion") == "guide-binding-dispatch-v1"
                and fence.get("state") == "not_started" and bool(fence.get("operationId"))
                and fence.get("operationId") == identity.get("operationId")
                and fence.get("evidenceFingerprint") == identity.get("guideEvidenceFingerprint")
                and fence.get("evidenceFingerprint") == requirement.get("evidenceFingerprint")
                and self._guide_binding_scope_valid(dict(row), journal)
                and fence.get("businessStateBefore") == self._choice_business_state(session_id))
            if eligible:
                proof = {"reason": "guide_requirement_binding_failed_before_dispatch",
                    "proofSource": "durable_guide_binding_dispatch_fence",
                    "businessExecutionStarted": False, "boundedAttemptConsumed": False, "plannerCalled": False,
                    "proposalDelta": 0, "versionDelta": 0, "patchDelta": 0, "routeWriteDelta": 0}
                updated = self.db.execute("""UPDATE agent_choice_executions SET status = 'failed_retryable', outcome_json = ?, error_json = ?, updated_at = ?
                    WHERE id = ? AND status = 'executing' AND continuation_json IS ?""",
                    (json.dumps(proof), json.dumps({"message": self._error_message(error)}, ensure_ascii=False),
                     datetime.now(timezone.utc).isoformat(), execution_id, row["continuation_json"]))
                eligible = updated.rowcount == 1
            self.db.execute("RELEASE SAVEPOINT guide_binding_failure")
            self.db.commit()
            return eligible
        except Exception:
            self.db.execute("ROLLBACK TO SAVEPOINT guide_binding_failure")
            self.db.execute("RELEASE SAVEPOINT guide_binding_failure")
            raise

    def _cancel_fallback_choice_execution(self, session_id: str, request_turn_id: str) -> None:
        execution = self.db.execute(
            """
            SELECT * FROM agent_choice_executions
            WHERE session_id = ? AND request_turn_id = ? AND status IN ('executing', 'succeeded')
            ORDER BY created_at DESC LIMIT 1
            """,
            (session_id, request_turn_id),
        ).fetchone()
        if execution is None:
            return
        session = self._session(session_id)
        expected_base_version_id = str(execution["expected_base_version_id"] or "")
        source_turn_ids = {
            str(execution["request_turn_id"] or ""),
            str(execution["execution_turn_id"] or ""),
        }
        execution_id = str(execution["id"] or "")
        if execution_id:
            linked_turns = self.db.execute(
                "SELECT id FROM conversation_turns WHERE session_id = ? AND agent_request_json LIKE ?",
                (session_id, f'%"executionId": "{execution_id}"%'),
            ).fetchall()
            source_turn_ids.update(str(row["id"] or "") for row in linked_turns)
        result_version_id = str(execution["result_version_id"] or "")
        materialized_write = bool(result_version_id)
        for source_turn_id in source_turn_ids:
            if not source_turn_id:
                continue
            if (
                self.db.execute(
                    "SELECT 1 FROM itinerary_patches WHERE session_id = ? AND source_turn_id = ? LIMIT 1",
                    (session_id, source_turn_id),
                ).fetchone()
                is not None
                or self.db.execute(
                    "SELECT 1 FROM itinerary_versions WHERE session_id = ? AND source_turn_id = ? LIMIT 1",
                    (session_id, source_turn_id),
                ).fetchone()
                is not None
            ):
                materialized_write = True
                break
        # A choice can be claimed while request context is assembled and then be
        # rejected by an identity/slot preflight before any timeline write.  In
        # that case the active (possibly partial) timeline is authoritative and
        # must not be reset merely because this choice has no expected base.
        if materialized_write:
            if expected_base_version_id:
                base = self.db.execute(
                    "SELECT * FROM itinerary_versions WHERE id = ? AND session_id = ?",
                    (expected_base_version_id, session_id),
                ).fetchone()
                if base is not None:
                    self._restore_session_to_version(session, base)
                else:
                    self._restore_session_to_empty_plan(session)
            else:
                self._restore_session_to_empty_plan(session)
        candidate_version_ids = {result_version_id} if result_version_id else set()
        for source_turn_id in source_turn_ids:
            if not source_turn_id:
                continue
            patch_rows = self.db.execute(
                "SELECT result_version_id FROM itinerary_patches WHERE session_id = ? AND source_turn_id = ?",
                (session_id, source_turn_id),
            ).fetchall()
            candidate_version_ids.update(str(row["result_version_id"] or "") for row in patch_rows)
            self.db.execute(
                "DELETE FROM itinerary_patches WHERE session_id = ? AND source_turn_id = ?",
                (session_id, source_turn_id),
            )
            self.db.execute(
                "DELETE FROM itinerary_versions WHERE session_id = ? AND source_turn_id = ?",
                (session_id, source_turn_id),
            )
        candidate_version_ids.discard("")
        candidate_version_ids.discard(expected_base_version_id)
        if candidate_version_ids:
            placeholders = ",".join("?" for _ in candidate_version_ids)
            self.db.execute(
                f"DELETE FROM itinerary_versions WHERE session_id = ? AND id IN ({placeholders})",
                (session_id, *candidate_version_ids),
            )
        self._unconsume_fallback_choice(execution)
        self.db.execute(
            """
            UPDATE agent_choice_executions
            SET status = 'cancelled', result_version_id = NULL,
                error_json = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                json.dumps({"message": "agent_run_cancelled"}, ensure_ascii=False),
                datetime.now(timezone.utc).isoformat(),
                execution["id"],
            ),
        )
        self.db.commit()

    def _unconsume_fallback_choice(self, execution: sqlite3.Row) -> None:
        source_turn_id = str(execution["source_turn_id"] or "")
        choice_id = str(execution["choice_id"] or "")
        if not source_turn_id or not choice_id:
            return
        row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
            (source_turn_id,),
        ).fetchone()
        if row is None:
            return
        payload = self._json_dict(row["agent_response_json"])
        payload["consumedChoiceIds"] = [
            str(item) for item in payload.get("consumedChoiceIds") or [] if str(item) != choice_id
        ]
        self.db.execute(
            "UPDATE conversation_turns SET agent_response_json = ?, updated_at = ? WHERE id = ?",
            (json.dumps(payload, ensure_ascii=False), datetime.now(timezone.utc).isoformat(), source_turn_id),
        )

    def _fail_fallback_choice_execution(self, session_id: str, request_turn_id: str, error: Exception) -> None:
        request_turn = self.db.execute(
            "SELECT agent_request_json FROM conversation_turns WHERE id = ? AND session_id = ?",
            (request_turn_id, session_id),
        ).fetchone()
        if request_turn is not None:
            self._finalize_planning_material_choice(
                self._json_dict(request_turn["agent_request_json"]),
                succeeded=False,
            )
        execution = self.db.execute(
            """
            SELECT id FROM agent_choice_executions
            WHERE session_id = ? AND request_turn_id = ? AND status = 'executing'
            ORDER BY updated_at DESC LIMIT 1
            """,
            (session_id, request_turn_id),
        ).fetchone()
        if execution is not None:
            if not (isinstance(error, HTTPException) and error.status_code == 499):
                try:
                    settled = execute_session_run_prewrite(session_id, lambda: self._settle_unstarted_guide_binding_failure(
                        session_id, execution["id"], error))
                    if settled:
                        return
                except HTTPException as cancellation:
                    if cancellation.status_code != 499:
                        raise
                    self._cancel_fallback_choice_execution(session_id, request_turn_id)
                    return
            self._cancel_fallback_choice_execution(session_id, request_turn_id)
            if not (isinstance(error, HTTPException) and error.status_code == 499):
                self._finish_fallback_choice_execution(execution["id"], "failed_retryable", error=error)

    def _squash_confirmed_fallback_versions(
        self,
        session_id: str,
        source_turn_id: str,
        result_version_id: str,
        planning_events: list[AgentPlanningEventResponse],
        *,
        expected_base_version_id: Optional[str],
    ) -> int:
        """Collapse one confirmed draft cycle to its single final verified snapshot."""
        rows = self.db.execute(
            """
            SELECT id, version_number FROM itinerary_versions
            WHERE session_id = ? AND source_turn_id = ?
            ORDER BY version_number ASC
            """,
            (session_id, source_turn_id),
        ).fetchall()
        obsolete_ids = [str(row["id"]) for row in rows if str(row["id"]) != result_version_id]
        if not obsolete_ids:
            return int(rows[0]["version_number"]) if rows else 1
        first_number = min(int(row["version_number"]) for row in rows)
        placeholders = ",".join("?" for _ in obsolete_ids)
        self.db.execute(
            f"UPDATE itinerary_patches SET result_version_id = ? WHERE session_id = ? AND result_version_id IN ({placeholders})",
            (result_version_id, session_id, *obsolete_ids),
        )
        self.db.execute(
            f"UPDATE itinerary_patches SET base_version_id = ? WHERE session_id = ? AND base_version_id IN ({placeholders})",
            (expected_base_version_id, session_id, *obsolete_ids),
        )
        self.db.execute(
            f"UPDATE conversation_turns SET itinerary_version_id = ? WHERE session_id = ? AND itinerary_version_id IN ({placeholders})",
            (result_version_id, session_id, *obsolete_ids),
        )
        self.db.execute(
            f"DELETE FROM itinerary_versions WHERE session_id = ? AND id IN ({placeholders})",
            (session_id, *obsolete_ids),
        )
        self.db.execute(
            "UPDATE itinerary_versions SET version_number = ? WHERE id = ? AND session_id = ?",
            (first_number, result_version_id, session_id),
        )
        for event in planning_events:
            serialized = json.dumps(event.metadata, ensure_ascii=False, default=str)
            for obsolete_id in obsolete_ids:
                serialized = serialized.replace(obsolete_id, result_version_id)
            event.metadata = json.loads(serialized)
        self._store_planning_events(source_turn_id, planning_events)
        self.db.commit()
        return first_number

    def _replay_fallback_choice_execution(
        self,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        selected_choice: dict[str, Any],
        execution: dict[str, Any],
    ) -> AgentMessageResponse:
        version_id = str(execution.get("result_version_id") or "")
        if not version_id or version_id != str(self._session(session["id"])["active_version_id"] or ""):
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_result_stale", "message": "该选择的结果版本已不再是当前版本。"},
            )
        self._consume_selected_agent_choice(session["id"], selected_choice)
        action = str(selected_choice.get("action") or "")
        is_plan_proposal = action == "select_plan_proposal"
        terminal_status = "success" if is_plan_proposal else "completed"
        reply = (
            "所选方案已提交；重复选择未创建新版本。"
            if is_plan_proposal
            else "该安全降级选择已执行完成；已恢复既有版本，未重复创建。"
        )
        assistant_turn_id = self._insert_turn(
            session["id"],
            "assistant",
            reply,
            "active",
            agent_response_json={
                "mode": "plan_proposal_choice_replay" if is_plan_proposal else "fallback_choice_replay",
                "reply": reply,
                "terminalStatus": terminal_status,
                "versionDelta": 0,
                "patchDelta": 0,
                "routeWriteDelta": 0,
                "resultVersionId": version_id,
            },
        )
        self.db.execute(
            "UPDATE conversation_turns SET itinerary_version_id = ?, updated_at = ? WHERE id = ?",
            (version_id, datetime.now(timezone.utc).isoformat(), assistant_turn_id),
        )
        self.db.commit()
        trace = AgentHarnessTrace(session["id"], assistant_turn_id)
        replay_events = [
            trace.plan(
                "Reloaded the persisted opaque proposal choice execution.",
                metadata={"choiceId": str(selected_choice.get("persistedChoiceId") or "")},
            ),
            trace.apply_patch(
                "fallback",
                "Duplicate choice reused the committed version; no patch or route write was created.",
                metadata={"versionDelta": 0, "patchDelta": 0, "routeWriteDelta": 0, "resultVersionId": version_id},
            ),
            trace.verify(
                "completed",
                "The committed choice result is still the active itinerary version.",
                metadata={
                    "resultPreview": {
                        "passed": True,
                        "checks": [{"name": "duplicate_choice_active_version", "status": "passed"}],
                        "hardFailures": [],
                        "softFailures": [],
                    }
                },
            ),
            trace.respond("completed", reply, metadata={"resultVersionId": version_id}),
        ]
        self._store_planning_events(assistant_turn_id, replay_events)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"]),
            version=self._version_response(self._version(version_id, session["id"], session["active_plan_id"])),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session["id"]),
            warnings=[] if is_plan_proposal else ["重复选择已幂等恢复，未创建新版本。"],
            planningRun=None,
            planningSteps=replay_events,
            toolEvents=replay_events,
            terminalStatus=terminal_status,
        )

    def _replay_density_choice_execution(
        self,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        selected_choice: dict[str, Any],
        execution: dict[str, Any],
    ) -> AgentMessageResponse:
        version_id = str(execution.get("result_version_id") or "")
        if version_id:
            return self._replay_fallback_choice_execution(user_turn, session, selected_choice, execution)
        current_session = self._session(session["id"])
        expected_base_version_id = str(execution.get("expected_base_version_id") or "")
        active_version_id = str(current_session["active_version_id"] or "")
        if expected_base_version_id != active_version_id:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "agent_choice_result_stale",
                    "message": "该选择的确认结果对应旧行程版本，请使用最新回复继续。",
                },
            )
        result_turn_id = str(execution.get("execution_turn_id") or "")
        result_turn = self.db.execute(
            """
            SELECT id FROM conversation_turns
            WHERE id = ? AND session_id = ? AND role = 'assistant' AND status = 'active'
            """,
            (result_turn_id, session["id"]),
        ).fetchone()
        if result_turn is None:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "agent_choice_result_stale",
                    "message": "该选择的确认结果已失效，请使用最新回复继续。",
                },
            )
        self._consume_selected_agent_choice(session["id"], selected_choice)
        self.db.commit()
        assistant_turn = self._turn_response(result_turn_id)
        events = list(assistant_turn.planning_steps or assistant_turn.tool_events or [])
        return AgentMessageResponse(
            userTurn=self._turn_response(user_turn.id),
            assistantTurn=assistant_turn,
            itinerary=ItineraryService(self.db).get_plan(current_session["active_plan_id"]),
            version=(
                self._version_response(
                    self._version(active_version_id, session["id"], current_session["active_plan_id"])
                )
                if active_version_id
                else None
            ),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session["id"]),
            warnings=["重复选择已返回原确认结果，未重复执行候选检索或创建版本。"],
            planningRun=None,
            planningSteps=events,
            toolEvents=events,
            terminalStatus="needs_confirmation",
        )

    def _execute_shared_travel_source(self, session, user_turn_id: str, content: str, route) -> AgentMessageResponse:
        from src.services.shared_travel_source_service import SharedTravelSourceService, shared_links
        from src.services.conversation_capability_carrier import ConversationCapabilityCarrier

        session_id = str(session["id"])
        urls = shared_links(content)
        request = self._json_dict(self.db.execute(
            "SELECT agent_request_json FROM conversation_turns WHERE id=?", (user_turn_id,)).fetchone()[0])
        request["conversationIntent"] = route.to_context()
        self._persist_agent_request_context(session_id, user_turn_id, request)
        if len(urls) != 1:
            source = {"schemaVersion": SharedTravelSourceService.SCHEMA, "status": "needs_user_material",
                      "failureReason": "shared_source_target_ambiguous", "imageStatus": "not_read"}
            reply = "这条消息包含多个攻略链接，请明确这次要读取哪一个。尚未读取网页或修改行程。"
        else:
            source = SharedTravelSourceService(self.db).read(session_id, user_turn_id, urls[0])
            if source["status"] == "completed":
                reply = (f"已读取《{source['title']}》的文字正文（{len(source['bodyText'])} 字）。"
                         f"笔记有 {source['imageCount']} 张图片，图片内容尚未解读；下方可核对原文。"
                         "原文是外部资料，不会覆盖你的天数、预算或其他硬要求，当前行程未修改。")
            else:
                reply = "本轮未能读取这条小红书笔记的有效正文，请粘贴攻略文字或提供可公开阅读的链接；没有用标题或网页摘要代替原文，当前行程未修改。"
        response_payload = {"mode": "shared_travel_source", "sharedSource": source, "reply": reply,
                            "terminalStatus": "completed", "versionDelta": 0, "patchDelta": 0,
                            "routeWriteDelta": 0, "proposalWriteDelta": 0}
        if source.get("status") == "completed":
            response_payload["guideAdvice"] = SharedTravelSourceService.advice(source)
        assistant_id = self._insert_turn(session_id, "assistant", reply, "active", parent_turn_id=user_turn_id,
            agent_request_json=request, agent_response_json=response_payload)
        # Import is read-only. Carry the intersection of existing lawful grants,
        # then attach the new source identity only to the surviving continuation.
        ConversationCapabilityCarrier(self.db).carry(session_id, assistant_id,
            request.get("capabilityIngress") or {}, nonexecuting=True)
        current = self._json_dict(self.db.execute("SELECT agent_response_json FROM conversation_turns WHERE id=?",
                                                  (assistant_id,)).fetchone()[0])
        if source.get("status") == "completed":
            advice = current["guideAdvice"]
            for choice in current.get("choiceOptions") or []:
                if choice.get("action") == "continue_plan_expansion":
                    choice.update(guideEvidenceSourceAssistantTurnId=assistant_id,
                        guideChoiceExecutionId=source["executionId"],
                        guideQueryFingerprint=advice["queryFingerprint"],
                        guideEvidenceFingerprint=advice["evidenceFingerprint"])
            has_continuation = any(c.get("action") == "continue_plan_expansion" for c in current.get("choiceOptions") or [])
            reply += ("\n\n可以继续要求参考这份攻略生成新方案；至少一处攻略地点须通过原需求、高德身份、新颖性和路线核验。"
                      if has_continuation else "\n\n请继续提供你的旅行需求，将参考这份正文生成符合你要求的方案；不会擅自照搬作者的行程条件。")
            current["reply"] = reply
        self.db.execute("UPDATE conversation_turns SET content=?, agent_response_json=? WHERE id=?",
                        (reply, json.dumps(current, ensure_ascii=False), assistant_id))
        self.db.commit()
        trace = AgentHarnessTrace(session_id, assistant_id)
        events = [trace.plan("Read one user-supplied public source under the admitted request identity."),
                  trace.verify("completed", "No proposal or formal itinerary writes during source intake.",
                               metadata={"versionDelta": 0, "patchDelta": 0, "routeWriteDelta": 0, "proposalWriteDelta": 0}),
                  trace.respond("completed", reply)]
        self._store_planning_events(assistant_id, events)
        return AgentMessageResponse(userTurn=self._turn_response(user_turn_id), assistantTurn=self._turn_response(assistant_id),
            itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"]),
            version=(self._version_response(self._version(session["active_version_id"], session_id, session["active_plan_id"]))
                     if session["active_version_id"] else None),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=[], planningRun=None, planningSteps=events, toolEvents=events, terminalStatus="completed")

    def _execute_travel_guide_advice(
        self,
        *,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict[str, Any],
        selected_choice: dict[str, Any],
        execution: dict[str, Any],
    ) -> AgentMessageResponse:
        option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        source_turn_id = str(selected_choice.get("sourceAssistantTurnId") or "")
        choice_id = str(selected_choice.get("choiceId") or "")
        root = SimpleOpenDirectionService(self.db).latest_root(session_id=str(session["id"]))
        source_row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ? AND role = 'assistant'",
            (source_turn_id, session["id"]),
        ).fetchone()
        source_payload = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
        canonical_options = [
            item
            for item in source_payload.get("choiceOptions") or []
            if isinstance(item, dict)
            and str(item.get("id") or "") == choice_id
            and str(item.get("kind") or "") == "travel_guide_advice"
            and str(item.get("action") or "") == "search_travel_guide_advice"
        ]
        active_version_id = str(session["active_version_id"] or "")
        if (
            root is None
            or len(canonical_options) != 1
            or str(option.get("planningSelectionRootTurnId") or "") != str(root.get("planningRootId") or "")
            or str(option.get("rootPortfolioId") or "") != str(root.get("id") or "")
            or str(option.get("requestContractFingerprint") or "") != str(root.get("requestContractFingerprint") or "")
            or str(option.get("expectedBaseVersionId") or "") != active_version_id
        ):
            raise HTTPException(
                status_code=409,
                detail={"code": "travel_guide_choice_stale", "message": "该攻略检索选项已失效，请使用最新回复。"},
            )
        execution_id = str(execution.get("id") or "")
        if not execution_id:
            raise HTTPException(
                status_code=409, detail={"code": "travel_guide_execution_missing", "message": "攻略检索未取得执行权。"}
            )
        plan_id = str(session["active_plan_id"] or "")
        portfolio_id = str(root.get("id") or "")

        def scoped_write_counts() -> dict[str, int]:
            return {
                "itinerary_versions": int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ? AND plan_id = ?",
                        (session["id"], plan_id),
                    ).fetchone()[0]
                ),
                "itinerary_patches": int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ? AND plan_id = ?",
                        (session["id"], plan_id),
                    ).fetchone()[0]
                ),
                "route_options": int(
                    self.db.execute("SELECT COUNT(*) FROM route_options WHERE plan_id = ?", (plan_id,)).fetchone()[0]
                ),
                "agent_plan_proposals": int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM agent_plan_proposals WHERE portfolio_id = ?",
                        (portfolio_id,),
                    ).fetchone()[0]
                ),
            }

        before = scoped_write_counts()
        request_contract = (
            root.get("requestIntentContract") if isinstance(root.get("requestIntentContract"), dict) else {}
        )
        advice = TravelGuideAdviceService(
            conclusion_provider=(
                self.provider if hasattr(self.provider, "synthesize_travel_guide_conclusion") else None
            )
        ).search(
            city=str(session["city"] or ""),
            request_contract=request_contract,
        )
        after = scoped_write_counts()
        if before != after:
            raise RuntimeError("travel_guide_read_only_write_invariant_failed")
        if advice["recommendations"]:
            recommendation_count = len(advice["recommendations"])
            source_count = len(advice.get("sourceRefs") or [])
            conclusion = advice.get("conclusion") if isinstance(advice.get("conclusion"), dict) else {}
            overview = str(conclusion.get("overview") or "").strip()
            reply = (
                f"已整理 {recommendation_count} 条相关攻略摘要（{source_count} 个网页来源）。{overview}当前行程未修改。"
                if overview
                else f"已找到 {recommendation_count} 条与当前目的地和体验主题匹配的普通攻略摘要；"
                "可在下方查看来源与建议，当前行程未修改。"
            )
        else:
            failure_reason = str(advice.get("failureReason") or "")
            reply = (
                "所有已配置的攻略搜索来源本轮均失败或未返回可用结果；当前行程未修改。"
                if failure_reason == "all_web_search_providers_failed_or_empty"
                else "搜索结果未通过目的地与旅行主题相关性校验；当前行程未修改。"
            )
        reply += "\n\n下方内容是搜索摘要和只读建议，不会自动写入行程。"
        response_payload = {
            "mode": "travel_guide_advice",
            "reply": reply,
            "guideAdvice": advice,
            "versionDelta": 0,
            "patchDelta": 0,
            "routeWriteDelta": 0,
            "proposalWriteDelta": 0,
            "terminalStatus": "completed",
        }
        assistant_turn_id = self._insert_turn(
            str(session["id"]),
            "assistant",
            reply,
            "active",
            parent_turn_id=user_turn.id,
            agent_request_json=request_context,
            agent_response_json=response_payload,
        )
        material = SimpleOpenDirectionService(self.db).rotate_capability_carrier(
            session_id=str(session["id"]),
            portfolio_id=portfolio_id,
            expected_source_assistant_turn_id=str(selected_choice.get("sourceAssistantTurnId") or ""),
            next_source_assistant_turn_id=assistant_turn_id,
            request_contract_fingerprint=str(root.get("requestContractFingerprint") or ""),
            retry_guide=True,
        )
        guide_place_hints = (
            TravelGuideAdviceService.extract_place_hints(advice)
            if str(advice.get("status") or "") == "completed"
            else []
        )
        if (
            guide_place_hints
            and str(advice.get("queryFingerprint") or "")
            and str(advice.get("evidenceFingerprint") or "")
        ):
            choices = [
                dict(item)
                for item in material.get("choiceOptions") or []
                if isinstance(item, dict)
            ]
            continuations = [
                item
                for item in choices
                if str(item.get("action") or "") == "continue_plan_expansion"
                and str(item.get("kind") or "") == "simple_direction_more_plans"
                and str(item.get("sourceAssistantTurnId") or "") == assistant_turn_id
            ]
            if not continuations:
                continuation = SimpleDirectionExecutionEvidenceService.build_continuation_choice(
                    portfolio_id=portfolio_id,
                    source_assistant_turn_id=assistant_turn_id,
                    planning_root_id=str(root.get("planningRootId") or ""),
                    request_fingerprint=str(root.get("requestContractFingerprint") or ""),
                    expected_base_version_id=(str(root.get("expectedBaseVersionId") or "") or None),
                )
                choices.append(continuation)
                continuations = [continuation]
            if len(continuations) != 1:
                raise RuntimeError("guide_continuation_capability_not_unique")
            continuations[0].update(
                {
                    "guideEvidenceSourceAssistantTurnId": assistant_turn_id,
                    "guideChoiceExecutionId": execution_id,
                    "guideQueryFingerprint": str(advice.get("queryFingerprint") or ""),
                    "guideEvidenceFingerprint": str(advice.get("evidenceFingerprint") or ""),
                }
            )
            material["choiceOptions"] = choices
        response_payload.update(
            {
                "workflowMode": material.get("workflowMode"),
                "planningSelectionRootTurnId": material.get("planningSelectionRootTurnId"),
                "rootPortfolioId": material.get("rootPortfolioId"),
                "comparisonProjections": material.get("comparisonProjections") or [],
                "comparisonProjectionUpdateMode": "replace",
                "choiceOptions": material.get("choiceOptions") or [],
                "comparisonSummary": material.get("comparisonSummary"),
                "frontierStatus": material.get("frontierStatus"),
            }
        )
        self.db.execute(
            "UPDATE conversation_turns SET agent_response_json = ? WHERE id = ?",
            (json.dumps(response_payload, ensure_ascii=False, default=str), assistant_turn_id),
        )
        self._finish_fallback_choice_execution(
            execution_id,
            "succeeded",
            execution_turn_id=assistant_turn_id,
            outcome=response_payload,
        )
        self._consume_selected_agent_choice(str(session["id"]), selected_choice)
        self.db.commit()
        trace = AgentHarnessTrace(str(session["id"]), assistant_turn_id)
        events = [
            trace.plan("Validated the opaque read-only guide capability."),
            trace.verify(
                "completed",
                "Guide search completed without itinerary, patch, route, or proposal writes.",
                metadata={"versionDelta": 0, "patchDelta": 0, "routeWriteDelta": 0, "proposalWriteDelta": 0},
            ),
            trace.respond("completed", reply),
        ]
        self._store_planning_events(assistant_turn_id, events)
        current_session = self._session(str(session["id"]))
        return AgentMessageResponse(
            userTurn=self._turn_response(user_turn.id),
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=ItineraryService(self.db).get_plan(current_session["active_plan_id"]),
            version=(
                self._version_response(
                    self._version(active_version_id, str(session["id"]), current_session["active_plan_id"])
                )
                if active_version_id
                else None
            ),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(str(session["id"])),
            warnings=[],
            planningRun=None,
            planningSteps=events,
            toolEvents=events,
            terminalStatus="completed",
        )

    def _replay_clarification_batch_execution(
        self,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        selected_choice: dict[str, Any],
        execution: dict[str, Any],
    ) -> AgentMessageResponse:
        """Return the first atomic batch result without invoking Controller or writers again."""

        result_turn_id = str(execution.get("execution_turn_id") or "")
        result_row = self.db.execute(
            """
            SELECT agent_response_json FROM conversation_turns
            WHERE id = ? AND session_id = ? AND role = 'assistant' AND status = 'active'
            """,
            (result_turn_id, session["id"]),
        ).fetchone()
        if result_row is None:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "agent_choice_result_stale",
                    "message": "该批量确认结果已失效，请使用最新回复继续。",
                },
            )
        current_session = self._session(session["id"])
        active_version_id = str(current_session["active_version_id"] or "")
        assistant_turn = self._turn_response(result_turn_id)
        response_payload = self._json_dict(result_row["agent_response_json"])
        terminal_status = str(response_payload.get("terminalStatus") or "completed")
        events = list(assistant_turn.planning_steps or assistant_turn.tool_events or [])
        self._consume_selected_agent_choice(session["id"], selected_choice)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=self._turn_response(user_turn.id),
            assistantTurn=assistant_turn,
            itinerary=ItineraryService(self.db).get_plan(current_session["active_plan_id"]),
            version=(
                self._version_response(
                    self._version(active_version_id, session["id"], current_session["active_plan_id"])
                )
                if active_version_id
                else None
            ),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session["id"]),
            warnings=["重复提交已返回原批量确认结果，未再次调用 Controller 或创建规划写入。"],
            planningRun=None,
            planningSteps=events,
            toolEvents=events,
            terminalStatus=terminal_status,
        )

    def _normalize_clarification_batch_manual_answers(
        self,
        normalization_context: dict[str, Any],
    ) -> dict[str, dict[str, Any]]:
        """Call the authorized, data-minimized normalizer exactly once."""

        questions = normalization_context.get("questions")
        if (
            set(normalization_context) != {"schemaVersion", "questions"}
            or normalization_context.get("schemaVersion") != "clarification-batch-normalization-context-v1"
            or not isinstance(questions, list)
            or not 1 <= len(questions) <= 3
            or any(
                not isinstance(item, dict)
                or set(item)
                != {
                    "dimensionId",
                    "question",
                    "manualValue",
                    "allowedSemanticFields",
                }
                for item in questions
            )
        ):
            raise HTTPException(
                status_code=500,
                detail={
                    "code": "clarification_batch_manual_normalization_scope_invalid",
                    "message": "手工答案规范化上下文超出授权范围；本批选择未提交。",
                },
            )
        normalizer = getattr(self.provider, "normalize_clarification_batch", None)
        if not callable(normalizer):
            raise HTTPException(
                status_code=503,
                detail={
                    "code": "clarification_batch_manual_normalization_unavailable",
                    "message": "当前模型不支持安全的手工答案规范化；本批选择未提交。",
                },
            )
        try:
            raw = normalizer(copy.deepcopy(normalization_context), timeout_seconds=8.0)
            parsed = json.loads(raw) if isinstance(raw, str) else copy.deepcopy(raw)
            if not isinstance(parsed, dict) or set(parsed) != {"schemaVersion", "answers"}:
                raise ValueError("clarification_batch_normalization_shape_invalid")
            if parsed.get("schemaVersion") != "clarification-batch-normalization-v1":
                raise ValueError("clarification_batch_normalization_schema_invalid")
            answers = parsed.get("answers")
            if not isinstance(answers, list) or not isinstance(questions, list) or len(answers) != len(questions):
                raise ValueError("clarification_batch_normalization_coverage_invalid")
            expected_dimensions = {str(item.get("dimensionId") or "") for item in questions if isinstance(item, dict)}
            normalized: dict[str, dict[str, Any]] = {}
            for answer in answers:
                if not isinstance(answer, dict) or set(answer) != {"dimensionId", "semanticValue"}:
                    raise ValueError("clarification_batch_normalization_answer_shape_invalid")
                dimension_id = str(answer.get("dimensionId") or "")
                semantic_value = answer.get("semanticValue")
                if (
                    not dimension_id
                    or dimension_id in normalized
                    or dimension_id not in expected_dimensions
                    or not isinstance(semantic_value, dict)
                ):
                    raise ValueError("clarification_batch_normalization_answer_invalid")
                normalized[dimension_id] = copy.deepcopy(semantic_value)
            if set(normalized) != expected_dimensions:
                raise ValueError("clarification_batch_normalization_dimension_mismatch")
            return normalized
        except HTTPException:
            raise
        except Exception as error:
            raise HTTPException(
                status_code=422,
                detail={
                    "code": "clarification_batch_manual_normalization_failed",
                    "message": "手工补充内容未能安全规范化；本批选择未提交，请调整后重试。",
                },
            ) from error

    def _clarification_batch_manual_normalization_audit(
        self,
        normalization_context: dict[str, Any],
    ) -> dict[str, Any]:
        """Persist redacted proof of the single external normalization call."""

        questions = [item for item in normalization_context.get("questions") or [] if isinstance(item, dict)]
        consume_audit = getattr(
            self.provider,
            "consume_clarification_batch_normalization_audit",
            None,
        )
        raw_audit = consume_audit() if callable(consume_audit) else {}
        raw_audit = raw_audit if isinstance(raw_audit, dict) else {}
        transport: dict[str, Any] = {}
        for key in (
            "payloadBytes",
            "responseBytes",
            "preHeaderWaitDurationMs",
            "readDurationMs",
            "httpStatus",
        ):
            value = raw_audit.get(key)
            if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
                transport[key] = value
        for key in ("providerInvoked", "responseHeadersReceived"):
            value = raw_audit.get(key)
            if isinstance(value, bool):
                transport[key] = value
        for key in ("startedAt", "finishedAt"):
            value = str(raw_audit.get(key) or "").strip()
            if value and len(value) <= 64:
                try:
                    datetime.fromisoformat(value.replace("Z", "+00:00"))
                except ValueError:
                    continue
                transport[key] = value
        if raw_audit.get("callKind") == "clarification_batch_normalization":
            transport["callKind"] = "clarification_batch_normalization"
        if raw_audit.get("captureState") in {"completed", "provider_failed"}:
            transport["captureState"] = raw_audit["captureState"]
        return {
            "schemaVersion": "clarification-batch-normalization-audit-v1",
            "providerName": (
                "deepseek" if self.provider.__class__.__name__ == "DeepSeekAgentProvider" else "custom_provider"
            ),
            "attemptCount": 1,
            "retryCount": 0,
            "outboundQuestionCount": len(questions),
            "outboundDimensionIds": [str(item.get("dimensionId") or "") for item in questions],
            "outboundQuestionFields": [
                "dimensionId",
                "question",
                "manualValue",
                "allowedSemanticFields",
            ],
            "transport": transport,
        }

    def _replay_succeeded_clarification_batch_before_turn(
        self,
        session_id: str,
        payload: AgentMessageRequest,
    ) -> Optional[AgentMessageResponse]:
        """Replay an identical completed batch before inserting another user turn."""

        selected_request = payload.context.selected_agent_choice
        if selected_request is None:
            return None
        selected = selected_request.model_dump(by_alias=True, exclude_none=True)
        source_turn_id = str(selected.get("sourceAssistantTurnId") or "")
        choice_id = str(selected.get("choiceId") or "")
        if not source_turn_id or not choice_id:
            return None
        execution_row = self.db.execute(
            """
            SELECT * FROM agent_choice_executions
            WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?
              AND action = 'submit_clarification_batch' AND status = 'succeeded'
            """,
            (session_id, source_turn_id, choice_id),
        ).fetchone()
        if execution_row is None:
            return None
        execution = dict(execution_row)
        request_turn_id = str(execution.get("request_turn_id") or "")
        request_row = self.db.execute(
            """
            SELECT agent_request_json FROM conversation_turns
            WHERE id = ? AND session_id = ? AND role = 'user'
            """,
            (request_turn_id, session_id),
        ).fetchone()
        if request_row is None:
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_result_stale", "message": "原批量确认结果已失效，请刷新后继续。"},
            )
        original_context = self._json_dict(request_row["agent_request_json"])
        original_selected = (
            original_context.get("selectedAgentChoice")
            if isinstance(original_context.get("selectedAgentChoice"), dict)
            else {}
        )
        original_option = original_selected.get("option") if isinstance(original_selected.get("option"), dict) else {}
        if (
            str(original_selected.get("sourceAssistantTurnId") or "") != source_turn_id
            or str(original_selected.get("choiceId") or "") != choice_id
            or str(original_option.get("kind") or "") != "clarification_batch_submit"
            or str(original_option.get("action") or "") != "submit_clarification_batch"
        ):
            raise HTTPException(
                status_code=409,
                detail={"code": "agent_choice_identity_mismatch", "message": "批量确认身份不一致，已停止重放。"},
            )
        _source_checkpoint_id, source_checkpoint_fingerprint = self._canonical_clarification_batch_source_identity(
            session_id=session_id,
            source_assistant_turn_id=source_turn_id,
            choice_id=choice_id,
            selected_choice=original_selected,
        )
        if str(execution.get("checkpoint_fingerprint") or "") != source_checkpoint_fingerprint:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "agent_choice_result_stale",
                    "message": "原批量确认结果缺少或不匹配来源检查点身份，请刷新后继续。",
                },
            )

        def canonical_selections(value: Any) -> str:
            normalized = [
                {
                    "dimensionId": str(item.get("dimensionId") or ""),
                    "optionId": str(item.get("optionId") or "") or None,
                    "manualValue": str(item.get("manualValue") or "") or None,
                }
                for item in value or []
                if isinstance(item, dict)
            ]
            normalized.sort(key=lambda item: item["dimensionId"])
            return json.dumps(normalized, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

        if canonical_selections(selected.get("batchSelections")) != canonical_selections(
            original_selected.get("batchSelections")
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "clarification_batch_replay_payload_mismatch",
                    "message": "该提交身份已执行，但本次答案与原提交不同；请使用最新回复继续。",
                },
            )
        return self._replay_clarification_batch_execution(
            self._turn_response(request_turn_id),
            self._session(session_id),
            original_selected,
            execution,
        )

    def _search_exact_pending_slot_candidates(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        user_turn: ConversationTurnResponse,
        request_context: dict[str, Any],
        checkpoint: dict[str, Any],
    ) -> AgentMessageResponse:
        """Search one persisted pending SlotKey without re-entering planning."""

        session = self._session(session_id)
        active_version_id = str(session["active_version_id"] or "")
        if not active_version_id:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_partial_timeline_missing",
                    "message": "当前没有可安全补槽的部分时间轴，请先恢复上次规划检查点。",
                },
            )
        version_row = self._version(active_version_id, session_id, session["active_plan_id"])
        snapshot = PortfolioPendingSlotService.reconcile(self._json_dict(version_row["snapshot_json"]))
        expected_scope = {
            "briefId": str(checkpoint.get("briefId") or ""),
            "poolId": str(checkpoint.get("poolId") or ""),
            "planningSlotId": str(checkpoint.get("planningSlotId") or ""),
            "dayNumber": int(checkpoint.get("dayNumber") or 0),
        }
        if not all(
            (
                expected_scope["briefId"],
                expected_scope["poolId"],
                expected_scope["planningSlotId"],
                expected_scope["dayNumber"] > 0,
            )
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_density_scope_missing",
                    "message": "该手动输入缺少完整待补槽位身份。",
                },
            )
        target_slot = next(
            (
                item
                for item in snapshot.get("portfolioPendingSlots") or []
                if isinstance(item, dict)
                and str(item.get("briefId") or "") == expected_scope["briefId"]
                and str(item.get("poolId") or "") == expected_scope["poolId"]
                and str(item.get("planningSlotId") or "") == expected_scope["planningSlotId"]
                and int(item.get("dayNumber") or 0) == expected_scope["dayNumber"]
            ),
            None,
        )
        if target_slot is None:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "portfolio_density_slot_stale",
                    "message": "该待补槽位已变化，请使用最新回复继续。",
                },
            )
        selected = (
            request_context.get("selectedAgentChoice")
            if isinstance(request_context.get("selectedAgentChoice"), dict)
            else {}
        )
        manual_value = str(selected.get("manualValue") or "").strip()
        if not manual_value:
            raise HTTPException(
                status_code=422,
                detail={
                    "code": "agent_choice_manual_value_required",
                    "message": "请输入具体地点名称。",
                },
            )

        attempt_count = self._manual_exact_slot_search_attempt_count(
            session_id,
            checkpoint,
        )
        max_attempts = 3
        search_budget_exhausted = attempt_count >= max_attempts
        provider_failure: Optional[str] = None
        manual_search_budget = AmapCallBudget(
            place_text_max=1,
            place_around_max=0,
            route_refresh_max=0,
            total_external_max=1,
            source="portfolio_density_manual_exact_search",
        )
        if search_budget_exhausted:
            raw_candidates = []
        else:
            try:
                with amap_call_budget_scope(manual_search_budget):
                    search_response = self.map_poi_service.search(
                        city=str(session["city"] or request_context.get("selectedCity") or ""),
                        keyword=manual_value,
                        category="all",
                        limit=8,
                        bypass_cache=True,
                    )
                raw_candidates = list(search_response.pois or [])
            except Exception as error:
                raw_candidates = []
                provider_failure = self._error_message(error)

        candidates: list[dict[str, Any]] = []
        for raw_candidate in raw_candidates:
            try:
                candidate = MapPoiResponse.model_validate(raw_candidate)
            except ValidationError:
                continue
            if (
                candidate.source != AMAP_PLACE_SOURCE
                or not candidate.id
                or not self._valid_timeline_candidate_coord(candidate)
            ):
                continue
            payload = candidate.model_dump(by_alias=True)
            payload.update(
                {
                    "amapId": candidate.id,
                    "briefId": expected_scope["briefId"],
                    "poolId": expected_scope["poolId"],
                    "planningSlotId": expected_scope["planningSlotId"],
                    "dayNumber": expected_scope["dayNumber"],
                    "intentType": str(checkpoint.get("intentType") or target_slot.get("intentType") or ""),
                    "sourceGoalId": str(target_slot.get("sourceGoalId") or ""),
                    "selectionPolicy": "persisted_exact_slot_confirmation_required",
                }
            )
            candidates.append(payload)

        candidate_record_id = f"cand_density_manual_{uuid4().hex[:16]}" if candidates else ""
        now = datetime.now(timezone.utc).isoformat()
        if candidates:
            self.db.execute(
                """INSERT INTO amap_poi_candidates (
                    id, session_id, turn_id, query, segment_id, city, category, status,
                    candidates_json, selected_amap_id, created_at
                ) VALUES (?, ?, ?, ?, NULL, ?, 'all', 'pending', ?, NULL, ?)""",
                (
                    candidate_record_id,
                    session_id,
                    user_turn_id,
                    manual_value,
                    str(session["city"] or request_context.get("selectedCity") or ""),
                    json.dumps(candidates, ensure_ascii=False, default=str),
                    now,
                ),
            )

        expires_at = (datetime.now(timezone.utc) + timedelta(minutes=60)).isoformat()
        source_turn_id = str(selected.get("sourceAssistantTurnId") or "")
        source_row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ?",
            (source_turn_id, session_id),
        ).fetchone()
        source_payload = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
        remaining_slots = [item for item in snapshot.get("portfolioPendingSlots") or [] if isinstance(item, dict)]
        remaining_keys = {PortfolioPendingSlotService.slot_key(item) for item in remaining_slots}
        target_key = PortfolioPendingSlotService.slot_key(target_slot)
        choices: list[dict[str, Any]] = []
        covered_keys: set[tuple[str, str, str, int]] = set()
        comparison_projection: Optional[dict[str, Any]] = None
        for source_option in source_payload.get("choiceOptions") or []:
            if not isinstance(source_option, dict):
                continue
            if isinstance(source_option.get("comparisonProjection"), dict):
                comparison_projection = copy.deepcopy(source_option["comparisonProjection"])
            try:
                source_key = PortfolioPendingSlotService.slot_key(source_option)
            except PortfolioPendingSlotError:
                continue
            if source_key not in remaining_keys or source_key == target_key:
                continue
            reissued = copy.deepcopy(source_option)
            reissued["expectedBaseVersionId"] = active_version_id
            reissued["lifecycle"] = "offered"
            choices.append(reissued)
            covered_keys.add(source_key)

        group = {
            **copy.deepcopy(target_slot),
            "slotId": expected_scope["planningSlotId"],
            "candidateRecordId": candidate_record_id or None,
            "candidates": candidates,
            "reason": (
                "manual_search_budget_exhausted"
                if search_budget_exhausted
                else "manual_exact_search"
                if candidates
                else "no_new_candidates"
            ),
        }
        for candidate in candidates[:3]:
            choices.append(
                {
                    "id": f"portfolio_density_candidate_{candidate_record_id}_{candidate['amapId']}",
                    "action": DENSITY_CANDIDATE_ACTION,
                    "kind": "portfolio_density_candidate",
                    "continuationType": "portfolio_density_completion",
                    "label": f"Day {expected_scope['dayNumber']}：{candidate.get('name') or '选择地点'}",
                    "description": (
                        f"用于补全 {target_slot.get('timeWindow') or '待安排时间'} 的"
                        f"{self._density_group_display_need(target_slot)}。"
                    ),
                    "candidateRecordId": candidate_record_id,
                    "selectionGroupId": candidate_record_id,
                    "amapId": candidate["amapId"],
                    "sourceGoalId": candidate.get("sourceGoalId") or "",
                    **expected_scope,
                    "intentType": candidate.get("intentType"),
                    "timeWindow": target_slot.get("timeWindow"),
                    "displayNeed": self._density_group_display_need(target_slot),
                    "expiresAt": expires_at,
                    "sourceUserTurnId": checkpoint.get("sourceUserTurnId"),
                    "expectedBaseVersionId": active_version_id,
                    "lifecycle": "offered",
                }
            )
        choices.extend(
            self._portfolio_density_scope_controls(
                group,
                portfolio_id=str(checkpoint.get("rootPortfolioId") or "density_manual"),
                grounding_report={"poolReports": [group]},
                partial_snapshot=snapshot,
                user_turn_id=str(checkpoint.get("sourceUserTurnId") or user_turn_id),
                expected_base_version_id=active_version_id,
                expires_at=expires_at,
            )
        )
        covered_keys.add(target_key)
        for slot in remaining_slots:
            slot_key = PortfolioPendingSlotService.slot_key(slot)
            if slot_key in covered_keys:
                continue
            choices.extend(
                self._portfolio_density_scope_controls(
                    slot,
                    portfolio_id=str(checkpoint.get("rootPortfolioId") or "density_manual"),
                    grounding_report={"poolReports": []},
                    partial_snapshot=snapshot,
                    user_turn_id=str(checkpoint.get("sourceUserTurnId") or user_turn_id),
                    expected_base_version_id=active_version_id,
                    expires_at=expires_at,
                )
            )

        if comparison_projection is not None:
            comparison_projection["activeVersionId"] = active_version_id
            comparison_projection["expectedBaseVersionId"] = active_version_id
            for choice in choices:
                choice["comparisonProjection"] = comparison_projection
        reply = (
            f"已按 Day {expected_scope['dayNumber']} "
            f"{target_slot.get('timeWindow') or '待安排时间'} 的精确槽位检索“{manual_value}”；"
            "请确认真实高德候选后再写入时间轴。"
            if candidates
            else (
                f"Day {expected_scope['dayNumber']} 的该精确槽位已达到 3 次手动检索上限；"
                "当前时间轴和待补槽位保持不变，请从已有真实候选中确认或使用定向刷新。"
                if search_budget_exhausted
                else f"未找到可验证的“{manual_value}”高德候选；"
                "当前精确槽位和其他待补槽位保持不变，可刷新、扩大附近检索或重新输入。"
            )
        )
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            reply,
            "active",
            agent_request_json=request_context,
            agent_response_json={
                "mode": "portfolio_density_manual_search",
                "reply": reply,
                "choiceOptions": choices,
                "providerFailure": provider_failure,
                "manualSearchBudget": {
                    **manual_search_budget.snapshot(),
                    "priorAttemptCount": attempt_count,
                    "maxAttempts": max_attempts,
                    "exhausted": search_budget_exhausted,
                },
                "initialPlan": checkpoint.get("initialPlan"),
                "pipelineContext": checkpoint.get("pipelineContext"),
                "creativePortfolio": checkpoint.get("creativePortfolio"),
                "groundingCheckpoint": checkpoint.get("groundingCheckpoint"),
                "constraintLedger": checkpoint.get("constraintLedger"),
                "rootPortfolioId": checkpoint.get("rootPortfolioId"),
                "planningSteps": [],
                "toolEvents": [],
            },
        )
        refreshed_checkpoint_summary = {
            "planningSelectionRootTurnId": checkpoint.get("planningSelectionRootTurnId"),
            "rootPortfolioId": checkpoint.get("rootPortfolioId"),
            "requestContractFingerprint": checkpoint.get("requestContractFingerprint"),
            "visibleProposalIds": checkpoint.get("visibleProposalIds") or [],
            "creativeExplorationFrontier": checkpoint.get("frontierCursor") or {},
        }
        choices = PortfolioContinuationCheckpointService.attach(
            choices,
            session_id=session_id,
            source_assistant_turn_id=assistant_turn_id,
            portfolio_id=str(checkpoint.get("rootPortfolioId") or ""),
            portfolio_summary=refreshed_checkpoint_summary,
            default_planning_root_id=str(checkpoint.get("planningSelectionRootTurnId") or ""),
            default_request_fingerprint=str(checkpoint.get("requestContractFingerprint") or ""),
            default_expected_base_version_id=active_version_id,
            default_proposal_id=str(checkpoint.get("proposalId") or ""),
            expires_at=expires_at,
        )
        persisted_manual_payload = self._json_dict(
            self.db.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                (assistant_turn_id,),
            ).fetchone()["agent_response_json"]
        )
        persisted_manual_payload["choiceOptions"] = choices
        self.db.execute(
            "UPDATE conversation_turns SET agent_response_json = ?, updated_at = ? WHERE id = ?",
            (
                json.dumps(persisted_manual_payload, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                assistant_turn_id,
            ),
        )
        self._consume_selected_agent_choice(session_id, selected)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=self._turn_response(user_turn.id),
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"]),
            version=self._version_response(version_row),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=[provider_failure] if provider_failure else [],
            planningRun=None,
            planningSteps=[],
            toolEvents=[],
            executionMode="deterministic_fast_path",
            terminalStatus="needs_confirmation",
            agentDecisionCount=0,
        )

    def _manual_exact_slot_search_attempt_count(
        self,
        session_id: str,
        checkpoint: dict[str, Any],
    ) -> int:
        expected_scope = (
            str(checkpoint.get("planningSelectionRootTurnId") or ""),
            str(checkpoint.get("briefId") or ""),
            str(checkpoint.get("poolId") or ""),
            str(checkpoint.get("planningSlotId") or ""),
            int(checkpoint.get("dayNumber") or 0),
        )
        count = 0
        rows = self.db.execute(
            """
            SELECT agent_request_json, agent_response_json
            FROM conversation_turns
            WHERE session_id = ? AND role = 'assistant'
            """,
            (session_id,),
        ).fetchall()
        for row in rows:
            response = self._json_dict(row["agent_response_json"])
            if response.get("mode") != "portfolio_density_manual_search":
                continue
            request = self._json_dict(row["agent_request_json"])
            continuation = (
                request.get("portfolioDensityContinuation")
                if isinstance(request.get("portfolioDensityContinuation"), dict)
                else {}
            )
            persisted_scope = (
                str(continuation.get("planningSelectionRootTurnId") or ""),
                str(continuation.get("briefId") or ""),
                str(continuation.get("poolId") or ""),
                str(continuation.get("planningSlotId") or ""),
                int(continuation.get("dayNumber") or 0),
            )
            count += int(persisted_scope == expected_scope)
        return count

    def _replay_selected_agent_choice_if_committed(
        self,
        session_id: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        selected_choice: dict[str, Any],
    ) -> Optional[AgentMessageResponse]:
        """Close the crash window after a patch committed but before choice consume."""
        source_turn_id = str(selected_choice.get("sourceAssistantTurnId") or "")
        choice_id = str(selected_choice.get("choiceId") or "")
        rows = self.db.execute(
            """
            SELECT p.id, p.result_version_id, p.operations_json, u.agent_request_json
            FROM itinerary_patches p JOIN conversation_turns u ON u.id = p.source_turn_id
            WHERE p.session_id = ? AND p.validation_status = 'accepted' AND p.result_version_id IS NOT NULL
            ORDER BY p.created_at DESC
            LIMIT 12
            """,
            (session_id,),
        ).fetchall()
        matched = None
        for row in rows:
            context = self._json_dict(row["agent_request_json"])
            previous = (
                context.get("selectedAgentChoice") if isinstance(context.get("selectedAgentChoice"), dict) else {}
            )
            if previous.get("sourceAssistantTurnId") != source_turn_id or previous.get("choiceId") != choice_id:
                continue
            try:
                operations = json.loads(row["operations_json"] or "[]")
            except (TypeError, json.JSONDecodeError):
                operations = []
            option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
            if any(
                isinstance(operation, dict)
                and operation.get("op") == "replace_segment_poi_from_candidate"
                and operation.get("segmentId") == option.get("segmentId")
                and operation.get("candidateId") == option.get("candidateRecordId")
                for operation in operations
            ):
                matched = row
                break
        if matched is None or str(session["active_version_id"] or "") != str(matched["result_version_id"]):
            return None
        self._consume_selected_agent_choice(session_id, selected_choice)
        reply = "该结构化候选已写入当前版本，已恢复该次选择结果，未重复创建 patch。"
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            reply,
            "active",
            agent_request_json=request_context,
            agent_response_json={"mode": "selected_choice_replay", "reply": reply, "replayedPatchId": matched["id"]},
        )
        self.db.commit()
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"]),
            version=self._version_response(
                self._version(str(matched["result_version_id"]), session_id, session["active_plan_id"])
            ),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=[],
            planningRun=None,
            planningSteps=[],
            toolEvents=[],
            terminalStatus="partial_success",
        )

    def _consume_selected_agent_choice(self, session_id: str, selected_choice: dict[str, Any]) -> None:
        source_turn_id = str(selected_choice.get("sourceAssistantTurnId") or "")
        choice_id = str(selected_choice.get("choiceId") or "")
        row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ? AND role = 'assistant'",
            (source_turn_id, session_id),
        ).fetchone()
        if row is None or not choice_id:
            return
        payload = self._json_dict(row["agent_response_json"])
        consumed = list(payload.get("consumedChoiceIds") or [])
        if choice_id in consumed:
            return
        payload["consumedChoiceIds"] = [*consumed, choice_id]
        self.db.execute(
            "UPDATE conversation_turns SET agent_response_json = ?, updated_at = ? WHERE id = ? AND session_id = ?",
            (
                json.dumps(payload, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                source_turn_id,
                session_id,
            ),
        )
        self.db.commit()

    def _try_handle_timeline_command(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
        event_sink: Optional[AgentExecutionEventSink] = None,
    ) -> Optional[AgentMessageResponse]:
        if command.intent != "timeline_edit":
            return None
        if command.scope == "meal" and command.operation == "offer_local_poi_options":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别餐饮候选确认",
                detail="已识别为给当前餐饮段提供真实高德候选，本轮不写版本、不进入通用 tool loop。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_local_meal_options_command(
                session_id, content, user_turn, session, request_context, command
            )
        if command.scope == "meal" and command.operation == "choose_previous_local_poi_option":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别餐饮候选选择",
                detail="已识别为选择上一轮餐饮候选，将只写入目标餐饮段并刷新受影响路线。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_choose_previous_local_poi_option_command(
                session_id, user_turn_id, content, user_turn, session, request_context, command
            )
        if command.scope == "meal" and command.operation == "remove":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别餐饮删除",
                detail="已识别为删除指定餐饮段，将只写入一个 remove_segment patch，不进入通用 tool loop。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_remove_meal_command(
                session_id, user_turn_id, content, user_turn, session, request_context, command
            )
        if command.scope == "meal" and command.operation == "replace_or_fill":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别餐饮局部编辑",
                detail="已识别为餐饮局部替换/补全，将避免通用 tool loop 和全局重排。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_meal_edit_command(
                session_id, user_turn_id, content, user_turn, session, request_context, command
            )
        if command.scope == "campus" and command.operation == "replace_kind":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别高校局部替换",
                detail="已识别为只替换高校段，不改餐饮和夜景。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_kind_replacement_command(
                session_id, user_turn_id, content, user_turn, session, request_context, command
            )
        if command.scope == "night_view" and command.operation == "offer_local_poi_options":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别夜景候选确认",
                detail="已识别为给当前夜景段提供真实高德候选，不写版本、不进入通用 tool loop。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_local_night_view_options_command(
                session_id, content, user_turn, session, request_context, command
            )
        if command.scope == "night_view" and command.operation == "choose_previous_local_poi_option":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别夜景候选选择",
                detail="已识别为选择上一轮夜景候选，将使用结构化候选或直接高德解析写入局部 patch。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_choose_previous_local_poi_option_command(
                session_id, user_turn_id, content, user_turn, session, request_context, command
            )
        if command.scope == "night_view" and command.operation in {"replace_kind", "ground_or_replace_specific_poi"}:
            concrete = bool(command.constraints.get("requireConcreteAmapPoi"))
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别夜景真实地点局部替换" if concrete else "识别夜景局部替换",
                detail=(
                    "已识别为夜景真实高德地点替换，将避免通用 tool loop、票务和网页搜索。"
                    if concrete
                    else "已识别为只替换夜景段，不改餐饮和高校。"
                ),
                metadata={"timelineCommand": command.as_dict()},
            )
            if concrete and command.constraints.get("query"):
                return self._handle_specific_night_view_grounding_command(
                    session_id, user_turn_id, content, user_turn, session, request_context, command
                )
            return self._handle_kind_replacement_command(
                session_id, user_turn_id, content, user_turn, session, request_context, command
            )
        if command.scope == "budget" and command.operation == "update_display_policy":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别费用展示偏好",
                detail="已识别为餐饮费用按人均展示的局部偏好，不重排时间轴。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_cost_display_command(session_id, user_turn, session, content, request_context, command)
        if command.scope == "route" and command.operation == "update_transport_preference":
            self._emit_execution_event(
                event_sink,
                session_id=session_id,
                turn_id=user_turn_id,
                event_type="timeline_edit",
                label="识别交通偏好编辑",
                detail="已识别为公交地铁优先的局部交通偏好，将避免全局重排。",
                metadata={"timelineCommand": command.as_dict()},
            )
            return self._handle_transport_preference_command(
                session_id, user_turn_id, content, user_turn, session, request_context, command
            )
        return None

    def _execute_active_partial_adoption(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict[str, Any],
        selected_choice: dict[str, Any],
    ) -> AgentMessageResponse:
        """Migrate a legacy active-partial choice onto route finalization.

        Older sessions persisted ``adopt_active_partial`` as a no-write
        acknowledgement.  That made a route-incomplete active draft permanent:
        the only available button could never collect its missing RouteOption
        evidence.  The choice remains an opaque server capability, but is now
        materialized in the existing proposal store and executed through the
        same route finalization + single-writer path as every other proposal.
        """
        option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        source_turn_id = str(selected_choice.get("sourceAssistantTurnId") or "").strip()
        choice_id = str(selected_choice.get("persistedChoiceId") or selected_choice.get("choiceId") or "").strip()
        source_row = self.db.execute(
            """SELECT agent_request_json, agent_response_json FROM conversation_turns
            WHERE id = ? AND session_id = ? AND role = 'assistant' AND status != 'superseded'""",
            (source_turn_id, session_id),
        ).fetchone()
        if source_row is None or not choice_id:
            raise HTTPException(
                status_code=409,
                detail={"code": "partial_adoption_source_stale", "message": "该部分方案来源已失效，请使用最新回复。"},
            )
        current = self._session(session_id)
        version_id = str(current["active_version_id"] or "")
        if not version_id:
            raise HTTPException(
                status_code=409,
                detail={"code": "portfolio_partial_timeline_missing", "message": "当前没有可采用的部分时间轴。"},
            )
        version_row = self._version(version_id, session_id, current["active_plan_id"])
        snapshot = self._json_dict(version_row["snapshot_json"])
        try:
            reconciled = PortfolioPendingSlotService.reconcile(snapshot)
            selection_context = PortfolioPendingSlotService.selection_context(reconciled)
        except PortfolioPendingSlotError as error:
            raise HTTPException(status_code=409, detail={"code": error.code, "message": error.message}) from error
        expected = str(option.get("expectedBaseVersionId") or "")
        root_id = str(option.get("planningSelectionRootTurnId") or "")
        portfolio_id = str(option.get("rootPortfolioId") or "")
        if (
            expected != version_id
            or root_id != str(selection_context.get("planningSelectionRootTurnId") or "")
            or portfolio_id != str(selection_context.get("rootPortfolioId") or "")
        ):
            succeeded = self.db.execute(
                """SELECT * FROM agent_choice_executions
                WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?
                  AND action = 'adopt_active_partial' AND status = 'succeeded'""",
                (session_id, source_turn_id, choice_id),
            ).fetchone()
            outcome = self._json_dict(succeeded["outcome_json"]) if succeeded is not None else {}
            same_adopted_root = str(outcome.get("planningSelectionRootTurnId") or "") == str(
                selection_context.get("planningSelectionRootTurnId") or ""
            )
            if not same_adopted_root:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "partial_adoption_base_stale",
                        "message": "该采用操作对应旧行程版本，请使用最新方案。",
                    },
                )
            selected_choice["executionId"] = str(succeeded["id"])
            return self._active_partial_adoption_response(
                user_turn=user_turn,
                session=current,
                selected_choice=selected_choice,
                source_row=source_row,
                result_version_id=version_id,
                duplicate=True,
            )
        return self._finalize_legacy_active_partial_choice(
            user_turn=user_turn,
            session=current,
            request_context=request_context,
            selected_choice=selected_choice,
            source_turn_id=source_turn_id,
            source_user_turn_id=root_id,
            portfolio_id=portfolio_id,
            active_version_id=version_id,
            snapshot=reconciled,
        )

    def _finalize_legacy_active_partial_choice(
        self,
        *,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict[str, Any],
        selected_choice: dict[str, Any],
        source_turn_id: str,
        source_user_turn_id: str,
        portfolio_id: str,
        active_version_id: str,
        snapshot: dict[str, Any],
    ) -> AgentMessageResponse:
        """Give a legacy partial capability authoritative proposal material.

        No browser snapshot is accepted here.  ``snapshot`` is the current
        version persisted by the server and all root/base identities have
        already been compared by the caller.
        """

        choice_id = str(selected_choice.get("persistedChoiceId") or selected_choice.get("choiceId") or "").strip()
        if not choice_id:
            raise HTTPException(
                status_code=409,
                detail={"code": "partial_adoption_source_stale", "message": "该部分方案来源已失效，请使用最新回复。"},
            )
        store = PlanPortfolioStore(self.db)
        loaded_material = store.load_choice(
            session_id=str(session["id"]),
            source_user_turn_id=source_user_turn_id,
            choice_id=choice_id,
        )
        if (
            loaded_material is not None
            and str(loaded_material[0].get("id") or "") == portfolio_id
            and str(loaded_material[1].get("id") or "")
        ):
            # Current releases already persist the partial card under this
            # opaque choice. Reuse that row; creating a second legacy row would
            # violate the portfolio/choice uniqueness boundary and split route
            # evidence across two proposal identities.
            proposal_id = str(loaded_material[1]["id"])
        else:
            proposal_id = f"legacy-partial:{portfolio_id}:{active_version_id}"
        material, readiness = self._persist_partial_comparison_material(
            portfolio_id=portfolio_id,
            proposal_id=proposal_id,
            choice_id=choice_id,
            snapshot=snapshot,
            comparison_role="current_active_draft",
            origin_projection_mode="current_active_draft",
        )
        projection = PlanComparisonPreviewService.project_snapshot(
            material,
            planning_selection_root_turn_id=source_user_turn_id,
            root_portfolio_id=portfolio_id,
            proposal_id=proposal_id,
            source_assistant_turn_id=source_turn_id,
            choice_id=choice_id,
            active_version_id=active_version_id,
            expected_base_version_id=active_version_id,
            is_partial=bool(readiness.get("isPartial")),
            is_adopted=False,
            adoption_ready=bool(readiness.get("adoptionReady")),
            comparison_role="current_active_draft",
            origin_projection_mode="current_active_draft",
        )
        normalized_option = copy.deepcopy(
            selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        )
        normalized_option.update(
            {
                "id": choice_id,
                "action": "select_plan_proposal",
                "kind": "plan_proposal",
                "sourceUserTurnId": source_user_turn_id,
                "planningSelectionRootTurnId": source_user_turn_id,
                "rootPortfolioId": portfolio_id,
                "expectedBaseVersionId": active_version_id,
                "comparisonProjection": projection,
            }
        )
        normalized_choice = copy.deepcopy(selected_choice)
        normalized_choice.update(
            {
                "action": "select_plan_proposal",
                "normalizedAction": "select_plan_proposal",
                "persistedChoiceAction": "select_plan_proposal",
                "option": normalized_option,
            }
        )
        return self._execute_selected_plan_proposal(
            session_id=str(session["id"]),
            user_turn_id=user_turn.id,
            user_turn=user_turn,
            session=session,
            request_context=request_context,
            selected_choice=normalized_choice,
        )

    def _active_partial_adoption_response(
        self,
        *,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        selected_choice: dict[str, Any],
        source_row: sqlite3.Row,
        result_version_id: str,
        duplicate: bool,
    ) -> AgentMessageResponse:
        source_request = self._json_dict(source_row["agent_request_json"])
        source_response = self._json_dict(source_row["agent_response_json"])
        persisted_directive = source_request.get("planningDirective")
        if not (
            isinstance(persisted_directive, dict)
            and persisted_directive.get("type") == "draft_itinerary"
            and isinstance(persisted_directive.get("dayStrategies"), list)
            and persisted_directive.get("dayStrategies")
        ):
            source_decision = (
                source_request.get("agentDecision") if isinstance(source_request.get("agentDecision"), dict) else {}
            )
            source_directive = source_decision.get("actionDirective")
            source_grounding = (
                source_response.get("grounding") if isinstance(source_response.get("grounding"), dict) else {}
            )
            source_pipeline = (
                source_response.get("pipelineContext")
                if isinstance(source_response.get("pipelineContext"), dict)
                else source_grounding.get("pipelineContext")
                if isinstance(source_grounding.get("pipelineContext"), dict)
                else {}
            )
            if not (
                isinstance(source_directive, dict)
                and source_directive.get("type") == "draft_itinerary"
                and isinstance(source_directive.get("dayStrategies"), list)
                and source_directive.get("dayStrategies")
            ):
                source_directive = source_pipeline.get("planningDirective")
            if (
                not isinstance(source_directive, dict)
                and (
                    isinstance(source_response.get("initialPlan"), dict)
                    or isinstance(source_grounding.get("initialPlan"), dict)
                )
                and source_pipeline
            ):
                source_directive = {"type": "draft_itinerary"}
            if (
                isinstance(source_directive, dict)
                and source_directive.get("type") == "draft_itinerary"
                and isinstance(source_directive.get("dayStrategies"), list)
                and source_directive.get("dayStrategies")
            ):
                source_request["planningDirective"] = copy.deepcopy(source_directive)
        latest_choices = [
            copy.deepcopy(option)
            for option in source_response.get("choiceOptions") or []
            if isinstance(option, dict) and str(option.get("action") or "") != "adopt_active_partial"
        ]
        for option in latest_choices:
            option["expectedBaseVersionId"] = result_version_id
            option["lifecycle"] = "offered"
        reply = (
            "该部分方案已经采用；重复操作未创建新版本、补丁或路线。"
            if duplicate
            else "已采用当前部分方案。现在可以编辑已确认行程；待补槽位仍需在对话中逐项确认。"
        )
        adoption_payload = {
            "mode": "active_partial_adoption_replay" if duplicate else "active_partial_adoption",
            "reply": reply,
            "choiceOptions": latest_choices,
            "terminalStatus": "needs_confirmation" if latest_choices else "success",
        }
        for key in (
            "initialPlan",
            "pipelineContext",
            "constraintLedger",
            "creativePortfolio",
            "groundingCheckpoint",
            "grounding",
            "rootPortfolioId",
        ):
            if source_response.get(key) is not None:
                adoption_payload[key] = copy.deepcopy(source_response[key])
        assistant_turn_id = self._insert_turn(
            session["id"],
            "assistant",
            reply,
            "active",
            agent_request_json={**source_request, "selectedAgentChoice": selected_choice},
            agent_response_json=adoption_payload,
        )
        self.db.execute(
            "UPDATE conversation_turns SET itinerary_version_id = ?, updated_at = ? WHERE id = ?",
            (result_version_id, datetime.now(timezone.utc).isoformat(), assistant_turn_id),
        )
        trace = AgentHarnessTrace(session["id"], assistant_turn_id)
        events = [
            trace.plan("Validated persisted opaque active-partial adoption identity."),
            trace.apply_patch(
                "fallback",
                "Adoption reused the current partial version without invoking a writer or route refresh.",
                metadata={
                    "versionDelta": 0,
                    "patchDelta": 0,
                    "routeWriteDelta": 0,
                    "resultVersionId": result_version_id,
                    "duplicate": duplicate,
                },
            ),
            trace.respond("completed", reply, metadata={"resultVersionId": result_version_id}),
        ]
        self._store_planning_events(assistant_turn_id, events)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=ItineraryService(self.db).get_plan(session["active_plan_id"]),
            version=self._version_response(self._version(result_version_id, session["id"], session["active_plan_id"])),
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session["id"]),
            warnings=[],
            planningRun=None,
            planningSteps=events,
            toolEvents=events,
            terminalStatus="needs_confirmation" if latest_choices else "success",
        )

    def _execute_selected_plan_proposal(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict[str, Any],
        selected_choice: dict[str, Any],
    ) -> AgentMessageResponse:
        """Commit exactly one stored proposal through the existing versioned writer.

        The browser's choice id is only an opaque capability.  Snapshot and base
        version are reloaded from the proposal store; no client proposal payload
        is ever consumed here.
        """
        option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        comparison_projection = (
            option.get("comparisonProjection") if isinstance(option.get("comparisonProjection"), dict) else {}
        )
        source_user_turn_id = str(
            comparison_projection.get("planningSelectionRootTurnId")
            or option.get("planningSelectionRootTurnId")
            or option.get("sourceUserTurnId")
            or ""
        ).strip()
        source_assistant_turn_id = str(selected_choice.get("sourceAssistantTurnId") or "").strip()
        choice_id = str(selected_choice.get("persistedChoiceId") or "").strip()
        if not source_user_turn_id or not source_assistant_turn_id or not choice_id:
            raise HTTPException(
                status_code=409, detail={"code": "plan_proposal_choice_invalid", "message": "方案选择缺少服务端身份。"}
            )
        option["sourceUserTurnId"] = source_user_turn_id
        source_context_row = self.db.execute(
            """
            SELECT agent_request_json, agent_response_json
            FROM conversation_turns
            WHERE id = ?
              AND session_id = ?
              AND role = 'assistant'
              AND status != 'superseded'
            """,
            (source_assistant_turn_id, session_id),
        ).fetchone()
        store = PlanPortfolioStore(self.db)
        loaded_choice = store.load_choice(
            session_id=session_id,
            source_user_turn_id=source_user_turn_id,
            choice_id=choice_id,
        )
        if source_context_row is None or loaded_choice is None:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "plan_proposal_source_context_missing",
                    "message": "方案来源上下文已失效，请重新生成方案。",
                },
            )
        source_request_payload = self._json_dict(source_context_row["agent_request_json"])
        source_response_payload = self._json_dict(source_context_row["agent_response_json"])
        from src.services.conversation_operation_identity import ConversationOperationIdentity
        identities = ConversationOperationIdentity(self.db)
        if option.get("operationOrigin") is not None:
            origin = identities.origin(session_id, source_assistant_turn_id, choice_id)
            original_context = self.db.execute("SELECT agent_request_json FROM conversation_turns WHERE id = ? AND session_id = ?",
                                              (origin["sourceAssistantTurnId"], session_id)).fetchone()
            if original_context is None:
                raise HTTPException(409, "operation_origin_context_missing")
            source_request_payload = self._json_dict(original_context[0])
        portfolio_state, proposal = loaded_choice
        simple_direction_workflow = (
            str(portfolio_state.get("workflow_mode") or "") == SimpleOpenDirectionService.WORKFLOW_MODE
        )
        prior_exact_execution = identities.execution(session_id, source_assistant_turn_id, choice_id)
        source_turn_is_authorized = bool(
            str(option.get("sourceAssistantTurnId") or "") == str(portfolio_state.get("source_assistant_turn_id") or "")
            or (
                prior_exact_execution is not None
                and str(prior_exact_execution["status"] or "") in {"executing", "succeeded"}
            )
        )
        if simple_direction_workflow and (
            not source_turn_is_authorized
            or not str(option.get("requestContractFingerprint") or "")
            or str(option.get("requestContractFingerprint") or "")
            != str(portfolio_state.get("request_contract_fingerprint") or "")
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "plan_proposal_request_scope_invalid",
                    "message": "该方案采用能力不属于当前请求合同，请刷新方案后重试。",
                },
            )
        self._recover_missing_portfolio_base_from_active_partial(
            session_id=session_id,
            session=session,
            portfolio_state=portfolio_state,
            option=option,
        )
        if (
            str(portfolio_state.get("status") or "") == "expired"
            or str(portfolio_state.get("failure_reason") or "") == "plan_portfolio_expired"
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "plan_proposal_expired",
                    "message": "该方案已超过可选择时限，请重新生成方案后再选择。未创建正式行程。",
                    "details": {"recommendedNextActions": ["regenerate_portfolio"]},
                },
            )
        recovered = self._recover_committing_plan_proposal_choice(
            session_id=session_id,
            source_user_turn_id=source_user_turn_id,
            source_assistant_turn_id=str(selected_choice.get("sourceAssistantTurnId") or ""),
            choice_id=choice_id,
            selected_choice=selected_choice,
        )
        if recovered is not None:
            return self._replay_fallback_choice_execution(user_turn, session, selected_choice, recovered)
        claim = self._claim_fallback_choice_execution(session_id, user_turn_id, selected_choice)
        if claim["status"] == "succeeded":
            return self._replay_fallback_choice_execution(user_turn, session, selected_choice, claim)
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            "正在核验并提交所选方案。",
            "active",
            agent_request_json={
                **(copy.deepcopy(source_request_payload) if simple_direction_workflow else {}),
                "selectedAgentChoice": selected_choice,
                "planningDirective": copy.deepcopy(source_request_payload.get("planningDirective")),
                "requestIntentContract": copy.deepcopy(source_request_payload.get("requestIntentContract")),
                **(
                    {
                        "serverExecutionProfile": "simple_open_v1",
                        "actualExecutionRoute": "simple_open_initial_pipeline",
                        "simpleOpenNonBlockingRoutes": True,
                    }
                    if simple_direction_workflow
                    else {}
                ),
            },
            agent_response_json={"mode": "plan_proposal_commit", "reply": ""},
        )
        before = self._session(session_id)
        route_row_count_before = int(
            self.db.execute(
                "SELECT COUNT(*) FROM route_options WHERE plan_id = ?",
                (before["active_plan_id"],),
            ).fetchone()[0]
        )
        route_fingerprint_before = self._route_content_fingerprint(str(before["active_plan_id"] or ""))
        created: dict[str, Any] = {}
        authoritative_readiness: dict[str, Any] = {}
        commit_route_result = None
        trace = AgentHarnessTrace(session_id, assistant_turn_id)
        stored_snapshot = self._json_dict(proposal.get("snapshot_json"))
        stored_verifier = self._json_dict(proposal.get("verifier_json"))
        stored_evidence = self._json_dict(proposal.get("evidence_json"))
        preserve_saved_simple_direction_schedule = bool(
            simple_direction_workflow and str(stored_evidence.get("savedFromActiveVersionId") or "")
        )
        readiness_before = ProposalReadinessService.compute(
            stored_snapshot,
            verifier=stored_verifier,
            route_failures_non_blocking=simple_direction_workflow,
        )
        finalization_events: list[AgentPlanningEventResponse] = [
            trace.event(
                "proposal_route_finalization_started",
                "方案路线核验开始",
                detail="已从服务端 proposal material 读取路线证据，只会补齐缺失或失效的相邻路线。",
                provider_name="route_service",
                metadata={
                    "proposalId": str(proposal.get("id") or ""),
                    "choiceId": choice_id,
                    "proposalCommitAttemptCount": 1,
                    "versionWriteCount": 0,
                    "patchWriteCount": 0,
                    "pendingSlotPreservedCount": len(stored_snapshot.get("portfolioPendingSlots") or []),
                    "routeStatusBefore": readiness_before.get("routeStatus"),
                    "readinessBefore": readiness_before.get("currentReadiness"),
                    "expectedLegCount": readiness_before.get("routeExpectedLegCount"),
                    "cachedLegCount": len(ProposalRouteEvidenceNormalizer.normalize_snapshot(stored_snapshot)),
                    "versionDelta": 0,
                    "patchDelta": 0,
                    "routeWriteDelta": 0,
                },
            )
        ]
        cached_route_pairs = {
            (str(route.get("fromSegmentId") or ""), str(route.get("toSegmentId") or ""))
            for route in ProposalRouteEvidenceNormalizer.normalize_snapshot(stored_snapshot)
            if ProposalRouteEvidenceNormalizer.is_verified(route)
        }
        for expected_pair in ProposalReadinessService.expected_route_pairs(stored_snapshot):
            pair_key = (
                str(expected_pair.get("fromSegmentId") or ""),
                str(expected_pair.get("toSegmentId") or ""),
            )
            finalization_events.append(
                trace.event(
                    "proposal_route_leg_started",
                    "方案路线段开始核验",
                    status="started",
                    detail=(
                        "复用当前 proposal 中已完整核验的 RouteOption。"
                        if pair_key in cached_route_pairs
                        else "仅为缺失或失效的相邻路线请求 RouteService。"
                    ),
                    provider_name="route_service",
                    metadata={
                        "proposalId": str(proposal.get("id") or ""),
                        "fromSegmentId": pair_key[0],
                        "toSegmentId": pair_key[1],
                        "dayNumber": expected_pair.get("dayNumber"),
                        "cached": pair_key in cached_route_pairs,
                    },
                )
            )
        source_planning_context = (
            self._json_dict(source_context_row["agent_request_json"]) if source_context_row is not None else {}
        )
        source_response_context = (
            self._json_dict(source_context_row["agent_response_json"]) if source_context_row is not None else {}
        )
        # The immutable Creative Portfolio contract is produced by the source
        # assistant response, while request JSON intentionally holds only input
        # context.  Rehydrate these server-authored fields here; never infer a
        # ledger from the browser or turn a historical verifier failure into a
        # pass merely because route evidence later succeeds.
        for key in (
            "constraintLedger",
            "creativePortfolio",
            "initialPlan",
            "pipelineContext",
            "groundingCheckpoint",
            "planningDiagnostic",
            "portfolioId",
        ):
            if source_response_context.get(key) is not None:
                source_planning_context[key] = copy.deepcopy(source_response_context[key])
        if not source_planning_context:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "plan_proposal_source_context_missing",
                    "message": "方案来源上下文已失效，请重新生成方案。",
                },
            )
        commit_planning_context = self._portfolio_choice_commit_planning_context(
            session_id=session_id,
            source_planning_context=source_planning_context,
            request_context=request_context,
        )

        def verify(snapshot: dict[str, Any]) -> bool:
            # The stored snapshot is a proposal, not automatically truthful.
            nonlocal commit_route_result, authoritative_readiness
            if not bool(snapshot.get("days")) or str(snapshot.get("id") or "") != str(before["active_plan_id"] or ""):
                return False
            if simple_direction_workflow:
                self._assert_proposal_original_time_requirements(
                    session_id=session_id, portfolio=portfolio_state, snapshot=snapshot,
                )
                # Compact Simple directions are confirmable only from the same
                # frozen AMap pair evidence that made the proposal selectable.
                # The canonical writer may refresh official route rows after
                # this gate, but it cannot turn pending proposal evidence into
                # permission to adopt.
                simple_verifier = SimpleOpenDirectionService._proposal_verifier(snapshot)
                snapshot["portfolioVerifier"] = copy.deepcopy(simple_verifier)
                authoritative_readiness = {
                    "adoptionReady": simple_verifier.get("confirmationPassed") is True,
                    "draftAdoptionReady": simple_verifier.get("draftPassed") is True,
                    "adoptionMode": "verified_compact_route",
                    "currentReadiness": (
                        "confirmation_ready" if simple_verifier.get("confirmationPassed") is True else "blocked"
                    ),
                    "routeStatus": str(simple_verifier.get("routeStatus") or "route_pending"),
                    "blockingReasons": list(simple_verifier.get("hardFailures") or []),
                }
                SimpleOpenDirectionService(self.db).update_server_verified_proposal_material(
                    portfolio_id=str(portfolio_state.get("id") or ""),
                    proposal_id=str(proposal.get("id") or ""),
                    snapshot=snapshot,
                    verifier=simple_verifier,
                    status=("adoption_ready" if simple_verifier.get("confirmationPassed") is True else "blocked"),
                    evidence={
                        "workflowMode": SimpleOpenDirectionService.WORKFLOW_MODE,
                        "readiness": copy.deepcopy(authoritative_readiness),
                        "routeRefreshDeferredToSingleWriter": True,
                    },
                )
                finalization_events.append(
                    trace.event(
                        "simple_direction_activation_verified",
                        "确认单方向可编辑材料",
                        status=("completed" if simple_verifier.get("confirmationPassed") is True else "failed"),
                        detail=(
                            "已验证服务端 AMap 地点身份、完整相邻路线证据与路线偏好合同。"
                            if simple_verifier.get("confirmationPassed") is True
                            else "方向缺少可安全激活的真实地点或路线偏好合同，未写入时间轴。"
                        ),
                        provider_name="agent-verifier-service",
                        metadata={
                            "proposalId": str(proposal.get("id") or ""),
                            "verifiedAmapRouteAnchorCount": int(
                                simple_verifier.get("verifiedAmapRouteAnchorCount") or 0
                            ),
                            "routeDecisionContractReady": bool(simple_verifier.get("routeDecisionContractReady")),
                            "versionDelta": 0,
                            "patchDelta": 0,
                            "routeWriteDelta": 0,
                        },
                    )
                )
                return simple_verifier.get("confirmationPassed") is True
            commit_route_result = self.portfolio_route_feasibility_service.verify_snapshot(
                snapshot,
                city=str(before["city"] or ""),
                transport_mode=str(snapshot.get("portfolioTransportPreference") or "transit"),
                preview_id=f"portfolio_commit_{choice_id}",
            )
            # The preflight is authoritative for the proposal snapshot too: the
            # writer must persist the exact route evidence and projected times
            # that were just re-verified, not the stale preview copy.
            finalized_snapshot = copy.deepcopy(commit_route_result.snapshot)
            snapshot.clear()
            snapshot.update(finalized_snapshot)
            strict_verifier = copy.deepcopy(stored_verifier)
            try:
                strict_ledger = ConstraintLedger.model_validate(source_planning_context.get("constraintLedger"))
                strict_brief = CreativeBrief.model_validate(self._json_dict(proposal.get("brief_json")))
                strict_verifier = PlanProposalVerifier(
                    experience_grounding_v2_mode=self.experience_grounding_v2_mode
                ).verify(snapshot, strict_ledger, strict_brief)
            except (TypeError, ValueError, ValidationError):
                # Legacy cards can still be finalized by the established final
                # AgentVerifierService.  Their missing historical contract is
                # recorded below rather than being treated as an implicit pass.
                strict_verifier = copy.deepcopy(stored_verifier)
            snapshot["portfolioVerifier"] = copy.deepcopy(strict_verifier)
            readiness = ProposalReadinessService.compute(snapshot, verifier=strict_verifier)
            authoritative_readiness = copy.deepcopy(readiness)
            route_ledger = copy.deepcopy(commit_route_result.route_execution_ledger)
            for route in ProposalRouteEvidenceNormalizer.normalize_snapshot(snapshot):
                pair_metadata = {
                    "proposalId": str(proposal.get("id") or ""),
                    "fromSegmentId": route.get("fromSegmentId"),
                    "toSegmentId": route.get("toSegmentId"),
                    "status": route.get("status"),
                    "provider": route.get("provider"),
                }
                finalization_events.append(
                    trace.event(
                        "proposal_route_leg_succeeded"
                        if ProposalRouteEvidenceNormalizer.is_verified(route)
                        else "proposal_route_leg_failed",
                        "方案路线段核验",
                        status="completed" if ProposalRouteEvidenceNormalizer.is_verified(route) else "failed",
                        detail="已保留完整 RouteOption 路线证据。"
                        if ProposalRouteEvidenceNormalizer.is_verified(route)
                        else "该路线段仍需刷新，不会被当作已核验路线。",
                        provider_name=str(route.get("provider") or "route_service"),
                        metadata=pair_metadata,
                    )
                )
            worker_failure_class = str(route_ledger.get("workerFailureClass") or "").strip()
            if worker_failure_class:
                finalization_events.append(
                    trace.event(
                        "proposal_route_worker_failed",
                        "方案路线 worker 失败",
                        status="failed",
                        detail="路线 worker 未完整返回；已保留成功路线段并提供可重试状态。",
                        failure_reason=worker_failure_class,
                        provider_name="route_service",
                        metadata={
                            "proposalId": str(proposal.get("id") or ""),
                            "workerFailureClass": worker_failure_class,
                            "sanitizedWorkerFailureMessage": str(
                                route_ledger.get("sanitizedWorkerFailureMessage") or ""
                            ),
                        },
                    )
                )
            material_status = {
                "route_provider_failed": "route_provider_failed",
                "route_partial": "route_partial",
                "route_ready": "adoption_ready" if readiness.get("adoptionReady") else "route_ready",
            }.get(str(readiness.get("routeStatus") or ""), "route_pending")
            store.update_proposal_material(
                portfolio_id=str(portfolio_state.get("id") or ""),
                proposal_id=str(proposal.get("id") or ""),
                snapshot=snapshot,
                verifier=strict_verifier,
                status=material_status,
                evidence={
                    "readiness": readiness,
                    "routeExecutionLedger": route_ledger,
                    "routeProviderState": commit_route_result.provider_state,
                },
            )
            finalization_events.extend(
                [
                    trace.event(
                        "proposal_route_evidence_normalized",
                        "方案路线证据规范化",
                        detail="已将 routeOptions、portfolioRouteEvidence 和 day evidence 统一为完整 RouteOption DTO。",
                        provider_name="route_service",
                        metadata={
                            "proposalId": str(proposal.get("id") or ""),
                            "retainedEvidenceCount": len(ProposalRouteEvidenceNormalizer.normalize_snapshot(snapshot)),
                            **route_ledger,
                        },
                    ),
                    trace.event(
                        "proposal_route_evidence_persisted",
                        "方案路线证据已保存",
                        detail="只更新 proposal material；尚未创建正式行程版本。",
                        provider_name="sqlite",
                        metadata={
                            "proposalId": str(proposal.get("id") or ""),
                            "routeWriteDelta": 0,
                            "versionDelta": 0,
                            "patchDelta": 0,
                        },
                    ),
                    trace.event(
                        "proposal_readiness_recomputed",
                        "方案采用资格已重算",
                        detail="采用资格来自完整路线、严格 verifier 和待补时段，不由前端布尔值决定。",
                        provider_name="agent-verifier-service",
                        metadata={
                            "proposalId": str(proposal.get("id") or ""),
                            "routeStatusAfter": readiness.get("routeStatus"),
                            "readinessAfter": readiness.get("currentReadiness"),
                            "nextAction": readiness.get("nextAction"),
                            "blockingReasons": readiness.get("blockingReasons"),
                        },
                    ),
                ]
            )
            if readiness.get("promotionStatus") == "promoted":
                finalization_events.append(
                    trace.event(
                        "partial_proposal_promoted",
                        "部分方案已提升为可采用方案",
                        detail="partial_preview 只保留谱系；严格路线和方案校验已重新通过。",
                        provider_name="agent-verifier-service",
                        metadata={"proposalId": str(proposal.get("id") or "")},
                    )
                )
            editable_draft_commit_allowed = self._editable_draft_commit_allowed(
                readiness,
                strict_verifier,
            )
            if not commit_route_result.passed and not editable_draft_commit_allowed:
                finalization_events.append(
                    trace.event(
                        "proposal_route_finalization_completed",
                        "方案路线核验未完成",
                        status="failed",
                        detail="路线证据不完整或 Provider 暂不可用；正式时间轴未发生变化。",
                        provider_name="route_service",
                        metadata={
                            "proposalId": str(proposal.get("id") or ""),
                            "routeStatusAfter": readiness.get("routeStatus"),
                            "readinessAfter": readiness.get("currentReadiness"),
                            "nextAction": readiness.get("nextAction"),
                            "versionDelta": 0,
                            "patchDelta": 0,
                            "routeWriteDelta": 0,
                            **route_ledger,
                        },
                    )
                )
                self._store_planning_events(assistant_turn_id, finalization_events)
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "plan_proposal_route_quality_failed",
                        "message": "所选方案的路线尚未完整核验，未创建正式行程；可重试路线核验。",
                        "details": {
                            "routeQualityIssues": commit_route_result.route_quality_issues,
                            "recommendedNextActions": commit_route_result.recommended_next_actions,
                            "providerState": commit_route_result.provider_state,
                            "routeExecutionLedger": commit_route_result.route_execution_ledger,
                            "nextAction": readiness.get("nextAction"),
                        },
                    },
                )
            if readiness.get("adoptionReady") is not True:
                finalization_events.append(
                    trace.event(
                        "proposal_route_finalization_completed",
                        "方案路线核验完成但采用条件未满足",
                        status="completed",
                        detail="路线证据已返回，但严格 verifier 或待补时段仍阻止正式写入。",
                        provider_name="agent-verifier-service",
                        metadata={
                            "proposalId": str(proposal.get("id") or ""),
                            "routeStatusAfter": readiness.get("routeStatus"),
                            "readinessAfter": readiness.get("currentReadiness"),
                            "nextAction": readiness.get("nextAction"),
                            "versionDelta": 0,
                            "patchDelta": 0,
                            "routeWriteDelta": 0,
                            **route_ledger,
                        },
                    )
                )
                self._store_planning_events(assistant_turn_id, finalization_events)
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "plan_proposal_readiness_blocked",
                        "message": "路线已返回，但方案仍未满足严格采用条件；正式行程未更新。",
                        "details": {
                            "blockingReasons": readiness.get("blockingReasons"),
                            "nextAction": readiness.get("nextAction"),
                            "routeExecutionLedger": commit_route_result.route_execution_ledger,
                        },
                    },
                )
            return True

        def persist(snapshot: dict[str, Any]) -> str:
            finalization_events.append(
                trace.event(
                    "proposal_adoption_started",
                    "方案采用事务开始",
                    detail="路线、严格 verifier 和采用资格均已通过，开始现有版本化单写入事务。",
                    provider_name="itinerary_patch_service",
                    metadata={"proposalId": str(proposal.get("id") or ""), "choiceId": choice_id},
                )
            )
            candidate_claims = self._claim_portfolio_snapshot_candidate_records(
                session_id=session_id,
                snapshot=snapshot,
            )
            result = None
            try:
                result = ItineraryPatchService(self.db).apply_patch(
                    before["active_plan_id"],
                    [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=snapshot)],
                    source_type="agent",
                    base_version_id=before["active_version_id"],
                    source_turn_id=assistant_turn_id,
                    preference_summary="",
                    planning_context={
                        **commit_planning_context,
                        "portfolioCommit": not simple_direction_workflow,
                        "simpleDirectionCommit": simple_direction_workflow,
                        "simpleDirectionSavedSnapshotRestore": preserve_saved_simple_direction_schedule,
                        "simpleOpenNonBlockingRoutes": (
                            True
                            if simple_direction_workflow
                            else commit_planning_context.get("simpleOpenNonBlockingRoutes")
                        ),
                        "portfolioAdoptionMode": authoritative_readiness.get("adoptionMode"),
                        "portfolioDraftAdoptionReady": authoritative_readiness.get("draftAdoptionReady") is True,
                        "choiceId": choice_id,
                        "skipOptionalToolRefresh": True,
                        "compactRouteModes": True,
                        "toolRefreshPolicy": {
                            **(
                                commit_planning_context.get("toolRefreshPolicy")
                                if isinstance(commit_planning_context.get("toolRefreshPolicy"), dict)
                                else {}
                            ),
                            "route": "full",
                        },
                        "preferredRouteMode": (
                            "transit"
                            if snapshot.get("portfolioTransportPreference") == "public_transit"
                            else snapshot.get("portfolioTransportPreference")
                        ),
                    },
                    preserve_server_snapshot_schedule=preserve_saved_simple_direction_schedule,
                    allow_server_sealed_zero_target_days=simple_direction_workflow,
                )
                report = AgentVerifierService(self.db).verify_agent_write(
                    before["id"],
                    before["active_plan_id"],
                    result.version.id,
                    result.patch.id,
                    planning_context={
                        **commit_planning_context,
                        "portfolioCommit": not simple_direction_workflow,
                        "simpleDirectionCommit": simple_direction_workflow,
                        "simpleDirectionSavedSnapshotRestore": preserve_saved_simple_direction_schedule,
                        "simpleOpenRoutePolicyAuthorized": simple_direction_workflow,
                        "portfolioAdoptionMode": authoritative_readiness.get("adoptionMode"),
                        "portfolioDraftAdoptionReady": authoritative_readiness.get("draftAdoptionReady") is True,
                    },
                )
                if not report.passed:
                    route_failures = [
                        str(item)
                        for item in report.hard_failures
                        if "route_quality:" in str(item) or "meal_detour" in str(item)
                    ]
                    if route_failures:
                        self._restore_previous_active_state(before)
                        self._discard_portfolio_commit_artifacts(
                            session_id=str(before["id"]),
                            plan_id=str(before["active_plan_id"]),
                            patch_id=str(result.patch.id),
                            version_id=str(result.version.id),
                            source_turn_id=assistant_turn_id,
                        )
                        result = None
                        self.db.commit()
                        raise HTTPException(
                            status_code=409,
                            detail={
                                "code": "plan_proposal_route_quality_failed",
                                "message": "所选方案中的餐饮与相邻路线偏绕，未创建正式行程。",
                                "details": {
                                    "routeQualityIssues": route_failures,
                                    "recommendedNextActions": [
                                        "choose_nearby_meal",
                                        "retry_route_verification",
                                        "open_map_selection",
                                    ],
                                },
                            },
                        )
                    self._mark_tool_loop_patch_rolled_back(assistant_turn_id, result.version.id, report.hard_failures)
                    self._restore_previous_active_state(before)
                    self._discard_portfolio_commit_artifacts(
                        session_id=str(before["id"]),
                        plan_id=str(before["active_plan_id"]),
                        patch_id=str(result.patch.id),
                        version_id=str(result.version.id),
                        source_turn_id=assistant_turn_id,
                    )
                    result = None
                    self.db.commit()
                    raise ValueError(
                        "plan_proposal_final_verifier_failed:" + ",".join(str(item) for item in report.hard_failures)
                    )
                route_row_count_after = int(
                    self.db.execute(
                        "SELECT COUNT(*) FROM route_options WHERE plan_id = ?",
                        (before["active_plan_id"],),
                    ).fetchone()[0]
                )
                route_fingerprint_after = self._route_content_fingerprint(str(before["active_plan_id"] or ""))
                route_content_changed = route_fingerprint_after != route_fingerprint_before
                route_write_delta = route_row_count_after - route_row_count_before
                if route_write_delta == 0 and route_content_changed:
                    route_write_delta = 1
                created.update(
                    {
                        "version": result.version,
                        "patch": result.patch,
                        "verifier": report,
                        "routeRowCountBefore": route_row_count_before,
                        "routeRowCountAfter": route_row_count_after,
                        "routeWriteDelta": route_write_delta,
                        "routeContentChanged": route_content_changed,
                    }
                )
                return result.version.id
            except Exception:
                finalization_events.append(
                    trace.event(
                        "proposal_adoption_rolled_back",
                        "方案采用事务已回滚",
                        status="failed",
                        detail="最终写入未完成，已恢复原 active itinerary，proposal 仍可按真实状态重试。",
                        provider_name="itinerary_patch_service",
                        metadata={
                            "proposalId": str(proposal.get("id") or ""),
                            "proposalCommitAttemptCount": 1,
                            "versionWriteCount": 0,
                            "patchWriteCount": 0,
                            "pendingSlotPreservedCount": len(stored_snapshot.get("portfolioPendingSlots") or []),
                            "versionDelta": 0,
                            "patchDelta": 0,
                            "routeWriteDelta": 0,
                        },
                    )
                )
                self._restore_previous_active_state(before)
                if result is not None:
                    self._discard_portfolio_commit_artifacts(
                        session_id=str(before["id"]),
                        plan_id=str(before["active_plan_id"]),
                        patch_id=str(result.patch.id),
                        version_id=str(result.version.id),
                        source_turn_id=assistant_turn_id,
                    )
                    result = None
                self._restore_portfolio_snapshot_candidate_records(candidate_claims)
                self.db.execute(
                    """
                    DELETE FROM itinerary_patches
                    WHERE source_turn_id = ?
                      AND result_version_id IS NULL
                    """,
                    (assistant_turn_id,),
                )
                self.db.commit()
                raise

        try:
            if (
                int(
                    readiness_before.get("blockingPendingHardSlotCount")
                    if readiness_before.get("blockingPendingHardSlotCount") is not None
                    else readiness_before.get("hardPendingSlotCount") or 0
                )
                > 0
            ):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "plan_proposal_readiness_blocked",
                        "message": str(
                            readiness_before.get("nextActionLabel") or "该方案仍有必选地点待补齐，尚不可采用。"
                        ),
                    },
                )
            ProposalVisitFactsService(self.db).assert_adoption_allowed(
                proposal_id=str(proposal.get("id") or ""),
            )
            version_id = PlanProposalCommitService(store).commit(
                session_id=session_id,
                source_user_turn_id=source_user_turn_id,
                choice_id=choice_id,
                active_version_id=str(before["active_version_id"] or "") or None,
                verify=verify,
                persist=persist,
            )
            ProposalVisitFactsService(self.db).copy_to_adopted_plan(
                proposal_id=str(proposal.get("id") or ""),
                plan_id=str(before["active_plan_id"] or ""),
            )
        except HTTPException as error:
            if error.status_code == 499:
                # Preserve the cooperative-cancel contract for the outer run
                # owner. It will unconsume the reversible choice claim and
                # must not receive a synthetic proposal-commit 409 instead.
                raise
            finalization_events.append(
                trace.event(
                    "proposal_adoption_rolled_back",
                    "方案采用未提交",
                    status="failed",
                    detail="路线或严格校验未通过，active itinerary 保持不变。",
                    provider_name="agent-verifier-service",
                    metadata={
                        "proposalId": str(proposal.get("id") or ""),
                        "proposalCommitAttemptCount": 1,
                        "versionWriteCount": 0,
                        "patchWriteCount": 0,
                        "pendingSlotPreservedCount": len(stored_snapshot.get("portfolioPendingSlots") or []),
                        "versionDelta": 0,
                        "patchDelta": 0,
                        "routeWriteDelta": 0,
                    },
                )
            )
            self._store_planning_events(assistant_turn_id, finalization_events)
            self._finish_fallback_choice_execution(claim["id"], "failed_retryable", error=error)
            detail = error.detail if isinstance(error.detail, dict) else {"message": str(error.detail or error)}
            self.db.execute(
                "UPDATE conversation_turns SET content = ?, status = 'failed', error_json = ?, updated_at = ? WHERE id = ?",
                (
                    str(detail.get("message") or "所选方案未通过核验，行程未更新。"),
                    json.dumps(detail, ensure_ascii=False),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            self.db.commit()
            if isinstance(detail, dict) and detail.get("code") in {
                "plan_proposal_route_quality_failed",
                "plan_proposal_readiness_blocked",
                "plan_proposal_expired",
                "plan_proposal_source_context_missing",
                "plan_proposal_base_version_stale",
            }:
                raise
            raise HTTPException(
                status_code=409,
                detail={"code": "plan_proposal_commit_failed", "message": "所选方案已失效或未通过核验。"},
            ) from error
        except Exception as error:
            finalization_events.append(
                trace.event(
                    "proposal_adoption_rolled_back",
                    "方案采用异常回滚",
                    status="failed",
                    detail="采用事务出现异常，active itinerary 已保持原版本。",
                    provider_name="itinerary_patch_service",
                    metadata={
                        "proposalId": str(proposal.get("id") or ""),
                        "exceptionClass": type(error).__name__,
                        "proposalCommitAttemptCount": 1,
                        "versionWriteCount": 0,
                        "patchWriteCount": 0,
                        "pendingSlotPreservedCount": len(stored_snapshot.get("portfolioPendingSlots") or []),
                        "versionDelta": 0,
                        "patchDelta": 0,
                        "routeWriteDelta": 0,
                    },
                )
            )
            self._store_planning_events(assistant_turn_id, finalization_events)
            self._finish_fallback_choice_execution(claim["id"], "failed_retryable", error=error)
            error_message = self._error_message(error)
            final_verifier_prefix = "plan_proposal_final_verifier_failed:"
            if error_message == "plan_proposal_expired":
                detail = {
                    "code": "plan_proposal_expired",
                    "message": "该方案已超过可选择时限，请重新生成方案后再选择。未创建正式行程。",
                    "details": {"recommendedNextActions": ["regenerate_portfolio"]},
                }
            elif error_message.startswith(final_verifier_prefix):
                validation_errors = [
                    item for item in error_message.removeprefix(final_verifier_prefix).split(",") if item
                ]
                detail = {
                    "code": "plan_proposal_final_verifier_failed",
                    "message": "所选方案未通过最终写入校验，行程未更新。",
                    "details": {"validationErrors": validation_errors},
                }
            else:
                detail = {"code": "plan_proposal_commit_failed", "message": "所选方案已失效或未通过核验。"}
            self.db.execute(
                "UPDATE conversation_turns SET content = ?, status = 'failed', error_json = ?, updated_at = ? WHERE id = ?",
                (
                    str(detail["message"]),
                    json.dumps({**detail, "cause": error_message}, ensure_ascii=False),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            self.db.commit()
            raise HTTPException(status_code=409, detail=detail) from error
        version = created["version"]
        patch = created["patch"]
        report = created["verifier"]
        active_snapshot_row = self.db.execute(
            "SELECT snapshot_json FROM itinerary_versions WHERE id = ? AND session_id = ?",
            (version_id, session_id),
        ).fetchone()
        active_snapshot = (
            self._json_dict(active_snapshot_row["snapshot_json"])
            if active_snapshot_row is not None
            else stored_snapshot
        )
        editable_adopted = (
            readiness_before.get("draftAdoptionReady") is True
            and readiness_before.get("adoptionMode") in {"editable_draft", "editable_partial"}
            and bool(active_snapshot.get("portfolioPendingSlots"))
        )
        reply = (
            "已采用为当前可编辑草案；硬目标已保留，待选软体验可继续补充。"
            if editable_adopted
            else "已按你选择的方案创建正式行程，并完成版本与地点校验。"
        )
        committed_choice = store.load_choice(
            session_id=session_id,
            source_user_turn_id=source_user_turn_id,
            choice_id=choice_id,
        )
        committed_proposal = committed_choice[1] if committed_choice is not None else proposal
        committed_snapshot = self._json_dict(committed_proposal.get("snapshot_json"))
        origin_projection_mode = str(
            committed_snapshot.get("originProjectionMode")
            or (
                "partial_preview"
                if readiness_before.get("originProjectionMode") == "partial_preview"
                else "full_proposal"
            )
        )
        adopted_projection = PlanComparisonPreviewService.project_snapshot(
            active_snapshot,
            planning_selection_root_turn_id=source_user_turn_id,
            root_portfolio_id=str(portfolio_state.get("id") or ""),
            proposal_id=str(committed_proposal.get("id") or proposal.get("id") or ""),
            source_assistant_turn_id=assistant_turn_id,
            choice_id=choice_id,
            active_version_id=version_id,
            expected_base_version_id=version_id,
            is_partial=(
                origin_projection_mode == "partial_preview"
                or isinstance(active_snapshot.get("portfolioPartialTimeline"), dict)
            ),
            is_adopted=True,
            adoption_ready=True,
            comparison_role="candidate_proposal",
            origin_projection_mode=origin_projection_mode,
        )
        persisted_comparison_projections: list[dict[str, Any]] = []
        committed_proposal_id = str(committed_proposal.get("id") or proposal.get("id") or "")
        persisted_membership = store.visible_comparison_projections(
            portfolio_id=str(portfolio_state.get("id") or ""),
        )
        for membership in persisted_membership:
            visible_proposal_id = str(membership.get("proposalId") or "")
            if visible_proposal_id == committed_proposal_id:
                persisted_comparison_projections.append(adopted_projection)
                continue
            visible_row = self.db.execute(
                """SELECT choice_id, status, snapshot_json, verifier_json
                FROM agent_plan_proposals
                WHERE id = ? AND portfolio_id = ?""",
                (
                    visible_proposal_id,
                    str(portfolio_state.get("id") or ""),
                ),
            ).fetchone()
            if visible_row is None:
                continue
            visible_snapshot = self._json_dict(visible_row["snapshot_json"])
            visible_verifier = self._json_dict(visible_row["verifier_json"])
            visible_readiness = ProposalReadinessService.compute(
                visible_snapshot,
                verifier=visible_verifier,
            )
            readonly_projection = PlanComparisonPreviewService.project_snapshot(
                visible_snapshot,
                planning_selection_root_turn_id=source_user_turn_id,
                root_portfolio_id=str(portfolio_state.get("id") or ""),
                proposal_id=visible_proposal_id,
                source_assistant_turn_id=str(portfolio_state.get("source_assistant_turn_id") or assistant_turn_id),
                choice_id=str(visible_row["choice_id"] or ""),
                active_version_id=None,
                expected_base_version_id=version_id,
                is_partial=bool(visible_readiness.get("isPartial")),
                is_adopted=False,
                adoption_ready=bool(visible_readiness.get("adoptionReady")),
                comparison_role="comparison_only",
                origin_projection_mode=str(visible_readiness.get("originProjectionMode") or "full_proposal"),
            )
            readonly_projection["proposalLifecycleStatus"] = str(visible_row["status"] or "comparison_only")
            persisted_comparison_projections.append(readonly_projection)
        if not persisted_comparison_projections:
            persisted_comparison_projections = [adopted_projection]

        post_adoption_choices: list[dict[str, Any]] = []
        if editable_adopted:
            adopted_projection["nextAction"] = "complete_pending_slots"
            adopted_projection["nextActionLabel"] = "继续补充软体验"
            expires_at = str(portfolio_state.get("expires_at") or "")
            for pending_slot in active_snapshot.get("portfolioPendingSlots") or []:
                if not isinstance(pending_slot, dict):
                    continue
                post_adoption_choices.extend(
                    self._portfolio_density_scope_controls(
                        pending_slot,
                        portfolio_id=str(portfolio_state.get("id") or ""),
                        grounding_report={},
                        partial_snapshot=active_snapshot,
                        user_turn_id=user_turn.id,
                        expected_base_version_id=version_id,
                        expires_at=expires_at,
                    )
                )
            for item in post_adoption_choices:
                item["comparisonProjection"] = adopted_projection
            completion_option = self._theme_completion_option(
                adopted_projection,
                proposal_choice_id=choice_id,
                source_user_turn_id=source_user_turn_id,
            )
            if completion_option is not None:
                post_adoption_choices.append(completion_option)
        else:
            adopted_projection["nextAction"] = "none"
            adopted_projection["nextActionLabel"] = "已采用"
        comparison_projection_update_mode: Optional[str] = None
        if simple_direction_workflow:
            simple_direction_service = SimpleOpenDirectionService(self.db)
            simple_direction_service._sync_portfolio_source_assistant_turn(
                portfolio_id=str(portfolio_state.get("id") or ""),
                source_assistant_turn_id=assistant_turn_id,
            )
            simple_material = simple_direction_service.response_material(
                portfolio_id=str(portfolio_state.get("id") or ""),
                source_assistant_turn_id=assistant_turn_id,
                expected_base_version_id=version_id,
                update_mode="replace",
            )
            persisted_comparison_projections = list(simple_material.get("comparisonProjections") or [])
            post_adoption_choices = list(simple_material.get("choiceOptions") or [])
            comparison_projection_update_mode = "replace"
            reply = (
                "已确认该方向并创建可编辑行程。你可以继续在行程总览中修改；"
                "切回行程对比时会先保存当前编辑，之后仍可确认编辑任一可见方向。"
            )
            active_projection = next(
                (
                    item
                    for item in persisted_comparison_projections
                    if isinstance(item, dict) and str(item.get("proposalId") or "") == str(proposal.get("id") or "")
                ),
                {},
            )
            required_pending_slots = [
                slot
                for slot in active_projection.get("pendingSlots") or []
                if isinstance(slot, dict) and str(slot.get("requirementLevel") or "required") in {"hard", "required"}
            ]
            if required_pending_slots:
                pending_labels = list(
                    dict.fromkeys(
                        "夜景"
                        if str(slot.get("intentType") or "") == "night_view"
                        else str(slot.get("displayNeed") or "待补地点")
                        for slot in required_pending_slots
                    )
                )
                reply = (
                    f"{reply}\n\n仍有 {len(required_pending_slots)} 个必选地点"
                    f"（{'、'.join(pending_labels)}）待补充；已确认地点和待补槽位均已保留。"
                )
        persisted_commit_request = None
        if simple_direction_workflow:
            persisted_commit_request = {
                **copy.deepcopy(source_request_payload),
                "selectedAgentChoice": selected_choice,
                "activeVersionId": version_id,
                "serverExecutionProfile": "simple_open_v1",
                "actualExecutionRoute": "simple_open_initial_pipeline",
                "simpleOpenNonBlockingRoutes": True,
            }
        try:
            self._finish_fallback_choice_execution(
                claim["id"],
                "succeeded",
                result_version_id=version_id,
                execution_turn_id=assistant_turn_id,
            )
            self._consume_selected_agent_choice(session_id, selected_choice)
            self.db.execute(
                "UPDATE conversation_turns SET content = ?, itinerary_version_id = ?, "
                "agent_request_json = COALESCE(?, agent_request_json), agent_response_json = ?, "
                "updated_at = ? WHERE id = ?",
                (
                    reply,
                    version_id,
                    (
                        json.dumps(persisted_commit_request, ensure_ascii=False, default=str)
                        if persisted_commit_request is not None
                        else None
                    ),
                    json.dumps(
                        {
                            "mode": "plan_proposal_commit",
                            **(
                                {
                                    "workflowMode": SimpleOpenDirectionService.WORKFLOW_MODE,
                                    "comparisonProjectionUpdateMode": comparison_projection_update_mode,
                                }
                                if simple_direction_workflow
                                else {}
                            ),
                            "reply": reply,
                            "resultVersionId": version_id,
                            "patchId": patch.id,
                            "verifier": report.as_metadata(),
                            "comparisonProjections": persisted_comparison_projections,
                            "choiceOptions": post_adoption_choices,
                            **(
                                {
                                    "planningSelectionRootTurnId": source_user_turn_id,
                                    "rootPortfolioId": str(portfolio_state.get("id") or ""),
                                    "visibleProposalCount": len(persisted_comparison_projections),
                                    "terminalStatus": "needs_confirmation",
                                }
                                if simple_direction_workflow
                                else {}
                            ),
                            "initialPlan": copy.deepcopy(source_response_payload.get("initialPlan")),
                            "pipelineContext": copy.deepcopy(source_response_payload.get("pipelineContext")),
                            "grounding": copy.deepcopy(source_response_payload.get("grounding")),
                        },
                        ensure_ascii=False,
                    ),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
            self.db.commit()
        except Exception:
            # The authoritative writer already committed.  Bookkeeping or
            # response projection must not hide the active itinerary version.
            self.db.rollback()
            current = self._session(session_id)
            committed_version_id = str(current["active_version_id"] or version_id)
            committed_version = self._version(
                committed_version_id,
                session_id,
                current["active_plan_id"],
            )
            return self._message_response(
                user_turn,
                self._turn_response(assistant_turn_id),
                current,
                self._version_response(committed_version),
                [],
                verifier_report=report,
                terminal_status="success",
            )
        trace = AgentHarnessTrace(session_id, assistant_turn_id)
        finalization_events.extend(
            [
                trace.event(
                    "proposal_route_finalization_completed",
                    "方案路线核验完成",
                    detail="完整 RouteOption 证据已通过严格路线覆盖校验。",
                    provider_name="route_service",
                    metadata={
                        "proposalId": str(proposal.get("id") or ""),
                        "routeStatusAfter": "route_ready",
                        "readinessAfter": "route_ready",
                        "versionDelta": 0,
                        "patchDelta": 0,
                        "routeWriteDelta": 0,
                    },
                ),
                trace.event(
                    "proposal_adoption_committed",
                    "方案采用事务已提交",
                    detail="版本、补丁和路线均由现有单写入事务一次提交。",
                    provider_name="itinerary_patch_service",
                    metadata={
                        "proposalId": str(proposal.get("id") or ""),
                        "resultVersionId": version_id,
                        "patchId": patch.id,
                        "proposalCommitAttemptCount": 1,
                        "versionWriteCount": 1,
                        "patchWriteCount": 1,
                        "pendingSlotPreservedCount": len(committed_snapshot.get("portfolioPendingSlots") or []),
                        "versionDelta": 1,
                        "patchDelta": 1,
                        "routeWriteDelta": int(created.get("routeWriteDelta") or 0),
                        "routeRowCountBefore": int(created.get("routeRowCountBefore") or 0),
                        "routeRowCountAfter": int(created.get("routeRowCountAfter") or 0),
                    },
                ),
            ]
        )
        commit_events = [
            *finalization_events,
            trace.plan(
                "Reloaded the selected proposal from the server-side portfolio store.",
                metadata={"choiceId": choice_id},
            ),
            trace.apply_patch(
                "completed",
                "Committed the selected proposal through the versioned itinerary writer and refreshed adjacent routes.",
                metadata={
                    "choiceId": choice_id,
                    "patchId": patch.id,
                    "resultVersionId": version_id,
                    "versionDelta": 1,
                },
            ),
            self._verifier_event(trace, report),
            trace.respond("completed", reply, metadata={"resultVersionId": version_id}),
        ]
        return self._message_response(
            user_turn,
            self._turn_response(assistant_turn_id),
            self._session(session_id),
            version if isinstance(version, ItineraryVersionResponse) else self._version_response(version),
            [],
            verifier_report=report,
            planning_events_override=commit_events,
        )

    def _recover_missing_portfolio_base_from_active_partial(
        self,
        *,
        session_id: str,
        session: sqlite3.Row,
        portfolio_state: dict[str, Any],
        option: dict[str, Any],
    ) -> None:
        """Bind a legacy root only to its exact active partial snapshot."""
        if str(portfolio_state.get("expected_base_version_id") or ""):
            return
        active_version_id = str(session["active_version_id"] or "")
        if not active_version_id or str(option.get("expectedBaseVersionId") or "") != active_version_id:
            return
        projection = option.get("comparisonProjection") if isinstance(option.get("comparisonProjection"), dict) else {}
        portfolio_id = str(portfolio_state.get("id") or "")
        planning_root_id = str(portfolio_state.get("source_user_turn_id") or "")
        if (
            not portfolio_id
            or str(projection.get("rootPortfolioId") or "") != portfolio_id
            or str(projection.get("planningSelectionRootTurnId") or "") != planning_root_id
        ):
            return
        version_row = self.db.execute(
            "SELECT snapshot_json FROM itinerary_versions WHERE id = ? AND session_id = ?",
            (active_version_id, session_id),
        ).fetchone()
        snapshot = self._json_dict(version_row["snapshot_json"]) if version_row is not None else {}
        selection_context = (
            snapshot.get("portfolioSelectionContext")
            if isinstance(snapshot.get("portfolioSelectionContext"), dict)
            else {}
        )
        if (
            not isinstance(snapshot.get("portfolioPartialTimeline"), dict)
            or str(selection_context.get("rootPortfolioId") or "") != portfolio_id
            or str(selection_context.get("planningSelectionRootTurnId") or "") != planning_root_id
        ):
            return
        updated = self.db.execute(
            """UPDATE agent_plan_portfolios
            SET expected_base_version_id = ?, updated_at = ?
            WHERE id = ? AND session_id = ?
              AND (expected_base_version_id IS NULL OR expected_base_version_id = '')""",
            (active_version_id, datetime.now(timezone.utc).isoformat(), portfolio_id, session_id),
        )
        if updated.rowcount == 1:
            self.db.commit()
            portfolio_state["expected_base_version_id"] = active_version_id

    def _portfolio_choice_commit_planning_context(
        self,
        *,
        session_id: str,
        source_planning_context: dict[str, Any],
        request_context: dict[str, Any],
    ) -> dict[str, Any]:
        """Rebind persisted proposal context to the current choice-run budget.

        Monotonic deadlines are process- and turn-local capabilities. Persisting
        one is useful for trace attribution, but reusing it after the user has
        reviewed the portfolio makes every later commit immediately expire.
        """
        limits = self._runtime_limits_for_request(request_context)
        remaining_run_seconds = float(limits.max_run_seconds) - (self._run_elapsed_ms() / 1000.0)
        if remaining_run_seconds <= 0:
            raise HTTPException(
                status_code=408,
                detail="plan_proposal_commit_deadline_exceeded: choice run budget exhausted before patch",
            )
        now = time.monotonic()
        context = dict(source_planning_context)
        context["sessionId"] = session_id
        context["runtimeDeadlineMonotonic"] = now + min(
            float(limits.max_patch_seconds),
            remaining_run_seconds,
        )
        context["runtimeLimits"] = {
            "maxRunSeconds": limits.max_run_seconds,
            "maxPatchSeconds": limits.max_patch_seconds,
        }
        return context

    def _claim_portfolio_snapshot_candidate_records(
        self,
        *,
        session_id: str,
        snapshot: dict[str, Any],
    ) -> list[tuple[str, str, Optional[str]]]:
        """Promote only server-persisted pending evidence selected by a proposal.

        A portfolio choice confirms the complete server-side snapshot, not an
        arbitrary client POI.  Existing candidate groups predate portfolio
        selection and can represent several map entities; their single legacy
        ``selected_amap_id`` remains an audit pointer while the authoritative
        final evidence is the immutable proposal snapshot.
        """

        # Portfolio bindings are authoritative; a pending group can be promoted
        # only when the candidate agrees on the full proposal-local identity.
        # A shared AMap POI may legitimately appear in other briefs, so its
        # physical ID alone is never enough to cross the single-writer boundary.
        def binding_key(item: dict[str, Any]) -> tuple[str, str, str, str, str]:
            return (
                str(item.get("amapId") or item.get("id") or item.get("amap_id") or "").strip(),
                str(item.get("briefId") or item.get("creativeBriefId") or "").strip(),
                str(item.get("poolId") or "").strip(),
                str(item.get("sourceGoalId") or item.get("goalId") or "").strip(),
                str(item.get("planningSlotId") or item.get("slotId") or "").strip(),
            )

        bindings = [
            item
            for item in snapshot.get("portfolioRequiredCandidateBindings") or []
            if isinstance(item, dict) and all(binding_key(item))
        ]
        if not bindings:
            return []

        def candidate_matches_binding(candidate: dict[str, Any]) -> bool:
            """Require every persisted provenance field, while accepting legacy raw evidence.

            Candidate groups are collected before a brief is selected, so older AMap
            evidence legitimately has no brief/pool fields.  The immutable proposal
            binding supplies those fields.  If a raw record does contain either field,
            it must agree exactly; this prevents a scoped record from being promoted
            through another brief or pool.
            """
            candidate_key = binding_key(candidate)
            for binding in bindings:
                expected = binding_key(binding)
                if candidate_key[0] != expected[0]:
                    continue
                if candidate_key[3] != expected[3] or candidate_key[4] != expected[4]:
                    continue
                if candidate_key[1] and candidate_key[1] != expected[1]:
                    continue
                if candidate_key[2] and candidate_key[2] != expected[2]:
                    continue
                return True
            return False

        amap_ids = {
            str((segment.get("poi") or {}).get("amapId") or "").strip()
            for day in snapshot.get("days") or []
            if isinstance(day, dict)
            for segment in day.get("segments") or []
            if isinstance(segment, dict)
        }
        amap_ids.discard("")
        if not amap_ids:
            return []
        rows = self.db.execute(
            """SELECT id, status, selected_amap_id, candidates_json
            FROM amap_poi_candidates WHERE session_id = ? AND status = 'pending'""",
            (session_id,),
        ).fetchall()
        claims: list[tuple[str, str, Optional[str]]] = []
        for row in rows:
            try:
                parsed_candidates = json.loads(str(row["candidates_json"] or "[]"))
            except (TypeError, ValueError):
                parsed_candidates = []
            candidates = parsed_candidates if isinstance(parsed_candidates, list) else []
            matching_ids = sorted(
                {
                    str(item.get("id") or item.get("amapId") or item.get("amap_id") or "").strip()
                    for item in candidates
                    if isinstance(item, dict)
                    and str(item.get("id") or item.get("amapId") or item.get("amap_id") or "").strip() in amap_ids
                    and candidate_matches_binding(item)
                }
            )
            if not matching_ids:
                continue
            self.db.execute(
                """UPDATE amap_poi_candidates
                SET status = 'selected', selected_amap_id = ?
                WHERE id = ? AND session_id = ? AND status = 'pending'""",
                (matching_ids[0], row["id"], session_id),
            )
            claims.append((str(row["id"]), str(row["status"]), row["selected_amap_id"]))
        return claims

    def _restore_portfolio_snapshot_candidate_records(
        self,
        claims: list[tuple[str, str, Optional[str]]],
    ) -> None:
        if not claims:
            return
        for candidate_id, status, selected_amap_id in claims:
            self.db.execute(
                """UPDATE amap_poi_candidates
                SET status = ?, selected_amap_id = ?
                WHERE id = ?""",
                (status, selected_amap_id, candidate_id),
            )

    def _recover_committing_plan_proposal_choice(
        self,
        *,
        session_id: str,
        source_user_turn_id: str,
        source_assistant_turn_id: str,
        choice_id: str,
        selected_choice: dict[str, Any],
    ) -> Optional[dict[str, Any]]:
        """Reconcile the narrow post-write/pre-CAS crash window from persisted evidence.

        The itinerary patch is authoritative: a committed proposal is recovered
        only when its opaque choice appears in the writer's persisted context,
        the patch was accepted, and the result remains this session's active
        version.  Otherwise the existing CAS remains fail-closed.
        """
        store = PlanPortfolioStore(self.db)
        loaded = store.load_choice(
            session_id=session_id,
            source_user_turn_id=source_user_turn_id,
            choice_id=choice_id,
        )
        if loaded is None:
            return None
        portfolio, proposal = loaded
        if portfolio["status"] != "committing" or str(portfolio.get("selected_proposal_id") or "") != str(
            proposal["id"]
        ):
            return None
        patch = self.db.execute(
            """SELECT p.result_version_id
            FROM itinerary_patches p
            JOIN conversation_turns t ON t.id = p.source_turn_id
            WHERE p.session_id = ? AND p.validation_status = 'accepted'
              AND t.session_id = ? AND t.role = 'assistant'
              AND t.agent_request_json LIKE ?
            ORDER BY p.created_at DESC LIMIT 1""",
            (session_id, session_id, f'%"persistedChoiceId": "{choice_id}"%'),
        ).fetchone()
        active_version_id = str(self._session(session_id)["active_version_id"] or "")
        result_version_id = str(patch["result_version_id"] or "") if patch is not None else ""
        if not result_version_id or result_version_id != active_version_id:
            if not result_version_id and store.release_stale_selection(
                portfolio_id=str(portfolio["id"]),
                reason="plan_proposal_selection_lease_expired",
            ):
                execution = self.db.execute(
                    """SELECT id, status FROM agent_choice_executions
                    WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?
                    ORDER BY created_at DESC LIMIT 1""",
                    (session_id, source_assistant_turn_id, choice_id),
                ).fetchone()
                if execution is not None and str(execution["status"] or "") == "executing":
                    self._finish_fallback_choice_execution(
                        str(execution["id"]),
                        "failed_retryable",
                        error=ValueError("plan_proposal_selection_lease_expired"),
                    )
            return None
        execution = self.db.execute(
            """SELECT * FROM agent_choice_executions
            WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?
            ORDER BY created_at DESC LIMIT 1""",
            (session_id, source_assistant_turn_id, choice_id),
        ).fetchone()
        if execution is None or str(execution["status"] or "") not in {"executing", "succeeded"}:
            return None
        store.reconcile_committed_selection(
            portfolio_id=str(portfolio["id"]),
            proposal_id=str(proposal["id"]),
            result_version_id=result_version_id,
        )
        if str(execution["status"]) != "succeeded":
            self._finish_fallback_choice_execution(
                str(execution["id"]),
                "succeeded",
                result_version_id=result_version_id,
            )
        recovered = dict(
            self.db.execute("SELECT * FROM agent_choice_executions WHERE id = ?", (execution["id"],)).fetchone()
        )
        self._attach_choice_execution_identity(selected_choice, recovered)
        return recovered

    def _execute_local_timeline_mutation(
        self,
        session_id: str,
        user_turn_id: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        content: str,
        intent: TimelineMutationIntent,
        *,
        event_sink: Optional[AgentExecutionEventSink] = None,
        request_context: Optional[dict[str, Any]] = None,
        selected_poi: Optional[MapPoiResponse] = None,
    ) -> AgentMessageResponse:
        controller_bypassed = not bool(
            isinstance(request_context, dict) and isinstance(request_context.get("agentDecision"), dict)
        )
        request_context = {
            **(request_context or {}),
            "schemaVersion": "agent-request-context-v1",
            "effectiveUserMessage": content,
            "actualExecutionRoute": "local_timeline_mutation",
            "timelineMutationIntent": intent.model_dump(by_alias=True),
            "controllerBypassed": controller_bypassed,
            "genericToolLoopEntered": False,
        }
        from src.services.agent_ingress_journal import AgentIngressJournal
        request_context = AgentIngressJournal(self.db).merge_context(user_turn_id, request_context)
        self.db.execute(
            "UPDATE conversation_turns SET agent_request_json = ?, updated_at = ? WHERE id = ? AND session_id = ?",
            (
                json.dumps(request_context, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                user_turn_id,
                session_id,
            ),
        )

        outcome = self.timeline_mutation_service.execute(
            session_id,
            intent,
            source_turn_id=user_turn_id,
            selected_poi=selected_poi,
        )
        transaction_row = self.db.execute(
            "SELECT transaction_json FROM timeline_mutation_transactions WHERE mutation_id = ?",
            (outcome.mutation_id,),
        ).fetchone()
        mutation_transaction = self._json_dict(transaction_row["transaction_json"]) if transaction_row else {}
        decision_state = (
            request_context.get("agentDecisionState")
            if isinstance(request_context.get("agentDecisionState"), dict)
            else {}
        )
        mutation_transaction.update(
            {
                "decisionId": decision_state.get("decisionId"),
                "cycleIndex": int(decision_state.get("cycleIndex") or 0),
                "executionRoute": "timeline_mutation_executor",
            }
        )
        if transaction_row is not None:
            self.db.execute(
                "UPDATE timeline_mutation_transactions SET transaction_json = ?, updated_at = ? WHERE mutation_id = ?",
                (
                    json.dumps(mutation_transaction, ensure_ascii=False, default=str),
                    datetime.now(timezone.utc).isoformat(),
                    outcome.mutation_id,
                ),
            )
        reply = self._timeline_mutation_reply(outcome)
        events = self._timeline_mutation_events(session_id, user_turn_id, outcome)
        for event in events:
            event.metadata.update(
                {
                    "decisionId": decision_state.get("decisionId"),
                    "cycleIndex": int(decision_state.get("cycleIndex") or 0),
                }
            )
        for event in events:
            if event_sink is not None:
                event_sink(event)
        assistant_payload = {
            "mode": "local_timeline_mutation",
            "reply": reply,
            "terminalStatus": self._timeline_mutation_terminal_status(outcome),
            "actualExecutionRoute": "timeline_mutation_executor",
            "versionDelta": int(bool(outcome.result_version_id) and not outcome.existing_outcome),
            "patchDelta": int(bool(outcome.patch_id) and not outcome.existing_outcome),
            "routeWriteDelta": int(outcome.route_write_delta or 0),
            "timelineMutationOutcome": outcome.model_dump(by_alias=True),
            "timelineMutationTransaction": mutation_transaction,
            "choiceOptions": outcome.options,
            "planningSteps": [event.model_dump(by_alias=True) for event in events],
            "toolEvents": [event.model_dump(by_alias=True) for event in events],
        }
        resume_attempt = (
            request_context.get("resumePlanningAttempt")
            if isinstance(request_context.get("resumePlanningAttempt"), dict)
            else {}
        )
        if isinstance(resume_attempt.get("initialPlan"), dict):
            assistant_payload["initialPlan"] = resume_attempt["initialPlan"]
        if isinstance(resume_attempt.get("pipelineContext"), dict):
            assistant_payload["pipelineContext"] = resume_attempt["pipelineContext"]
        for key in (
            "constraintLedger",
            "creativePortfolio",
            "groundingCheckpoint",
            "rootPortfolioId",
        ):
            if resume_attempt.get(key) is not None:
                assistant_payload[key] = resume_attempt[key]
        current_session = self._session(session_id)
        current_itinerary = ItineraryService(self.db).get_plan(current_session["active_plan_id"])
        planning_run = PlanningRunService(self.db).create_run(
            "agent_timeline_mutation",
            user_input=content,
            preference_summary=self._preference_summary_from_context(request_context),
            itinerary=current_itinerary,
            itinerary_version_id=outcome.result_version_id,
            understood_requirements=request_context.get("understoodRequirements"),
            final_summary=reply,
            tool_calls_override=self._planning_tool_calls_from_tool_events(
                [event.model_dump(by_alias=True) for event in events]
            ),
        )
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            reply,
            "active",
            agent_request_json=request_context,
            agent_response_json=assistant_payload,
        )
        if outcome.result_version_id:
            reissued_choices, comparison_projection = self._reissue_remaining_pending_slot_choices(
                session_id=session_id,
                request_context=request_context,
                result_version_id=outcome.result_version_id,
                reissued_assistant_turn_id=assistant_turn_id,
            )
            if comparison_projection is not None:
                projection_event = AgentPlanningEventResponse(
                    type="portfolio_plan_visible",
                    label="待补槽位已更新",
                    status="completed",
                    detail="已重新读取提交后的 active version，并按新的 base version 展示剩余槽位。",
                    sessionId=session_id,
                    turnId=user_turn_id,
                    providerName="portfolio-pending-slot-continuation",
                    fallbackUsed=False,
                    userVisible=True,
                    metadata={"comparisonProjection": comparison_projection},
                    timestamp=datetime.now(timezone.utc).isoformat(),
                )
                events.append(projection_event)
                assistant_payload["planningSteps"] = [event.model_dump(by_alias=True) for event in events]
                assistant_payload["toolEvents"] = [event.model_dump(by_alias=True) for event in events]
            if reissued_choices:
                assistant_payload["choiceOptions"] = reissued_choices
                remaining_slots = comparison_projection.get("pendingSlots") if comparison_projection else []
                reply = f"{reply} 已重新读取当前版本；还剩 {len(remaining_slots)} 个待补槽位，请继续逐项确认。"
                assistant_payload["reply"] = reply
                assistant_payload["terminalStatus"] = "needs_confirmation"
                self.db.execute(
                    "UPDATE conversation_turns SET content = ?, agent_response_json = ? WHERE id = ? AND session_id = ?",
                    (
                        reply,
                        json.dumps(assistant_payload, ensure_ascii=False, default=str),
                        assistant_turn_id,
                        session_id,
                    ),
                )
        self.db.execute(
            "UPDATE conversation_turns SET planning_run_id = ? WHERE id IN (?, ?)",
            (planning_run.id, user_turn_id, assistant_turn_id),
        )
        if outcome.patch_id:
            self.db.execute(
                "UPDATE itinerary_patches SET planning_run_id = ? WHERE id = ?",
                (planning_run.id, outcome.patch_id),
            )
        if outcome.result_version_id:
            self.db.execute(
                "UPDATE conversation_turns SET itinerary_version_id = ?, updated_at = ? WHERE id = ?",
                (outcome.result_version_id, datetime.now(timezone.utc).isoformat(), assistant_turn_id),
            )
        self.db.commit()
        version = None
        if outcome.result_version_id:
            version = self._version_response(
                self._version(outcome.result_version_id, session_id, current_session["active_plan_id"])
            )
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=current_itinerary,
            version=version,
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=outcome.warnings,
            planningRun=planning_run,
            planningSteps=events,
            toolEvents=events,
            executionMode="local_timeline_mutation",
            terminalStatus=str(
                assistant_payload.get("terminalStatus") or self._timeline_mutation_terminal_status(outcome)
            ),
            agentDecisionCount=0,
            outcomeStatuses={
                "timelineMutation": outcome.status,
                "postconditionPassed": outcome.postcondition_passed,
                "structuralVerifierPassed": outcome.structural_verifier_passed,
            },
        )

    def _attach_rule_safe_partial_comparison(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        response: AgentMessageResponse,
        event_sink: Optional[AgentExecutionEventSink],
    ) -> AgentMessageResponse:
        """Project a committed rule-safe partial without another timeline write."""

        if response.version is None:
            return response
        current = self._session(session_id)
        version_id = str(response.version.id)
        version_row = self._version(version_id, session_id, current["active_plan_id"])
        try:
            snapshot = PortfolioPendingSlotService.reconcile(self._json_dict(version_row["snapshot_json"]))
            pending_slots = [
                copy.deepcopy(item) for item in snapshot.get("portfolioPendingSlots") or [] if isinstance(item, dict)
            ]
            selection_context = PortfolioPendingSlotService.selection_context(snapshot)
        except PortfolioPendingSlotError:
            return response
        if (
            str(snapshot.get("status") or "") != "partial"
            or not pending_slots
            or str(current["active_version_id"] or "") != version_id
        ):
            return response

        root_turn_id = str(selection_context["planningSelectionRootTurnId"])
        root_portfolio_id = str(selection_context["rootPortfolioId"])
        focus_brief_id = str(selection_context["focusBriefId"])
        request_fingerprint = str(selection_context["requestContractFingerprint"])
        assistant_turn_id = response.assistant_turn.id
        row = self.db.execute(
            "SELECT agent_request_json, agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ?",
            (assistant_turn_id, session_id),
        ).fetchone()
        payload = self._json_dict(row["agent_response_json"]) if row is not None else {}
        request_payload = self._json_dict(row["agent_request_json"]) if row is not None else {}
        root_row = self._portfolio_continuation_root_row(root_portfolio_id)
        root_summary = self._json_dict(root_row["summary_json"]) if root_row is not None else {}
        neutral_checkpoint = bool(
            root_row is None
            and self._neutral_partial_expansion_checkpoint_matches(
                session_id=session_id,
                root_portfolio_id=root_portfolio_id,
                planning_root_id=root_turn_id,
                request_fingerprint=request_fingerprint,
                active_version_id=version_id,
            )
        )
        persisted_visible_proposal_ids: list[str] = []
        continuation_status: Optional[str] = None
        continuation_expires_at = ""
        continuation_expired = False
        continuation_session_matches = False
        if neutral_checkpoint:
            continuation_summary = self._neutral_partial_continuation_summary(
                selection_context=selection_context,
            )
            continuation_status = "awaiting_selection"
            continuation_expires_at = (
                datetime.now(timezone.utc) + timedelta(minutes=PlanPortfolioStore.PORTFOLIO_TTL_MINUTES)
            ).isoformat()
            continuation_session_matches = True
        elif root_row is not None:
            continuation_summary = {
                **root_summary,
                "planningSelectionRootTurnId": str(root_row["source_user_turn_id"] or ""),
                "rootPortfolioId": root_portfolio_id,
                "requestContractFingerprint": str(root_row["request_contract_fingerprint"] or ""),
            }
            continuation_status = str(root_row["status"] or "")
            continuation_expires_at = self._persisted_continuation_expires_at(
                expires_at=root_row["expires_at"],
                created_at=root_row["created_at"],
            )
            continuation_expired = PlanPortfolioStore._is_expired(continuation_expires_at)
            continuation_session_matches = str(root_row["session_id"] or "") == session_id
            persisted_visible_proposal_ids = [
                str(proposal_row["id"])
                for proposal_row in self.db.execute(
                    """SELECT id FROM agent_plan_proposals
                    WHERE portfolio_id = ? AND status IN (
                        'offered', 'committed', 'comparison_only', 'partial_preview',
                        'route_pending', 'route_partial', 'route_ready',
                        'route_provider_failed', 'adoption_ready', 'blocked'
                    )""",
                    (root_portfolio_id,),
                ).fetchall()
            ]
        else:
            continuation_summary = {}
        continuation_reconciliation = PortfolioContinuationCapabilityReconciler.reconcile(
            active_version_id=version_id,
            portfolio_summary=continuation_summary,
            raw_candidates=(),
            has_active_partial=True,
            persisted_visible_proposal_ids=persisted_visible_proposal_ids,
            portfolio_status=continuation_status,
            portfolio_expired=continuation_expired,
            session_matches=continuation_session_matches,
            continuation_expires_at=continuation_expires_at,
            require_expiry=True,
        )
        adoption_id = f"portfolio_partial_adopt_{root_portfolio_id}_{version_id}"
        projection = PlanComparisonPreviewService.project_snapshot(
            snapshot,
            planning_selection_root_turn_id=root_turn_id,
            root_portfolio_id=root_portfolio_id,
            proposal_id=f"partial:{root_portfolio_id}",
            source_assistant_turn_id=assistant_turn_id,
            choice_id=adoption_id,
            active_version_id=version_id,
            expected_base_version_id=version_id,
            is_partial=True,
            is_adopted=False,
        )
        expires_at = (datetime.now(timezone.utc) + timedelta(minutes=30)).isoformat()
        choices: list[dict[str, Any]] = [
            {
                "id": adoption_id,
                "kind": "portfolio_comparison_readonly",
                "label": "当前草稿路线状态",
                "description": "当前草稿已经是活动版本；此项只承载服务端对比投影，不执行采用写入。",
                "sourceUserTurnId": user_turn_id,
                "expectedBaseVersionId": version_id,
                "planningSelectionRootTurnId": root_turn_id,
                "rootPortfolioId": root_portfolio_id,
                "comparisonProjection": projection,
                "lifecycle": "hidden",
            },
        ]
        choices.extend(
            {
                **copy.deepcopy(capability),
                "description": "保留当前可见部分方案，并在同一行程对比中追加后续已验证方案。",
                "sourceUserTurnId": user_turn_id,
            }
            for capability in continuation_reconciliation.capabilities
        )
        scoped_identity = {
            "planningSelectionRootTurnId": root_turn_id,
            "rootPortfolioId": root_portfolio_id,
            "focusBriefId": focus_brief_id,
            "requestContractFingerprint": request_fingerprint,
        }
        for slot in pending_slots:
            group = {
                **slot,
                "slotId": slot.get("planningSlotId"),
                "displayNeed": slot.get("displayNeed") or slot.get("rawNeed") or slot.get("intentType"),
            }
            controls = self._portfolio_density_scope_controls(
                group,
                portfolio_id=root_portfolio_id,
                grounding_report={},
                partial_snapshot=snapshot,
                user_turn_id=user_turn_id,
                expected_base_version_id=version_id,
                expires_at=expires_at,
            )
            for control in controls:
                control.update(scoped_identity)
                choices.append(control)

        reply = (
            f"已生成可见的部分时间轴；当前还有 {len(pending_slots)} 个待补时段。"
            "你可以先在行程对比中查看并采用，也可以逐项刷新或手动搜索真实地点。"
        )
        event = AgentPlanningEventResponse(
            type="portfolio_plan_visible",
            label="部分行程已可预览",
            status="completed",
            detail="已复用提交后的 active version 进入只读对比；待补槽位保持精确作用域。",
            sessionId=session_id,
            turnId=assistant_turn_id,
            providerName="rule-safe-partial-comparison",
            fallbackUsed=True,
            userVisible=True,
            metadata={"comparisonProjection": projection},
            timestamp=datetime.now(timezone.utc).isoformat(),
        )
        if event_sink is not None:
            event_sink(event)
        events = [*response.planning_steps, event]
        request_payload.update(scoped_identity)
        request_payload.setdefault("planningDirective", {"type": "draft_itinerary"})
        continuation_day_slots: list[dict[str, Any]] = []
        continuation_intent_pools: list[dict[str, Any]] = []
        for slot in pending_slots:
            slot_id = str(slot.get("planningSlotId") or "")
            time_window = str(slot.get("timeWindow") or "")
            start_time = str(slot.get("startTime") or "")
            if not start_time and re.fullmatch(r"\d{2}:\d{2}-\d{2}:\d{2}", time_window):
                start_time = time_window.split("-", 1)[0]
            duration_minutes = int(slot.get("durationMinutes") or 0)
            if duration_minutes <= 0 and re.fullmatch(r"\d{2}:\d{2}-\d{2}:\d{2}", time_window):
                start_text, end_text = time_window.split("-", 1)
                start_hour, start_minute = (int(value) for value in start_text.split(":"))
                end_hour, end_minute = (int(value) for value in end_text.split(":"))
                duration_minutes = max(0, (end_hour * 60 + end_minute) - (start_hour * 60 + start_minute))
            continuation_day_slots.append(
                {
                    "slotId": slot_id,
                    "dayNumber": int(slot.get("dayNumber") or 0),
                    "date": slot.get("date"),
                    "timeWindow": time_window,
                    "startTime": start_time,
                    "durationMinutes": duration_minutes,
                    "kind": str(slot.get("kind") or slot.get("intentType") or "visit"),
                    "rawNeed": str(slot.get("rawNeed") or slot.get("displayNeed") or slot.get("intentType") or ""),
                    "routeAnchor": True,
                    "priority": int(slot.get("priority") or 0),
                    "notes": "由已提交 partial snapshot 的 exact pending slot 恢复。",
                }
            )
            continuation_intent_pools.append(
                {
                    "poolId": str(slot.get("poolId") or ""),
                    "briefId": str(slot.get("briefId") or ""),
                    "rawNeed": str(slot.get("rawNeed") or slot.get("displayNeed") or ""),
                    "city": str(current["city"] or ""),
                    "intentType": str(slot.get("intentType") or ""),
                    "targetCount": 1,
                    "requirementLevel": "optional",
                    "softGoalId": str(slot.get("sourceGoalId") or "") or None,
                    "assignToSlots": [slot_id],
                    "candidateHints": [],
                    "hintPolicy": "no_hint",
                    "entityBindingMode": "category",
                }
            )
        payload["initialPlan"] = {
            "reply": "从已提交的部分时间轴恢复待补槽位。",
            "mode": "initial_plan",
            "daySlots": continuation_day_slots,
            "intentPools": continuation_intent_pools,
            "warnings": [],
        }
        persisted_pipeline_context = (
            copy.deepcopy(payload.get("pipelineContext")) if isinstance(payload.get("pipelineContext"), dict) else {}
        )
        payload["pipelineContext"] = {
            **persisted_pipeline_context,
            **scoped_identity,
            "portfolioGroundingFocusBriefId": focus_brief_id,
            "activePartialContinuation": True,
        }
        choices = PortfolioContinuationCheckpointService.attach(
            choices,
            session_id=session_id,
            source_assistant_turn_id=assistant_turn_id,
            portfolio_id=root_portfolio_id,
            portfolio_summary=continuation_summary,
            default_planning_root_id=root_turn_id,
            default_request_fingerprint=request_fingerprint,
            default_expected_base_version_id=version_id,
            default_proposal_id=f"partial:{root_portfolio_id}",
            expires_at=continuation_expires_at or expires_at,
        )
        serialized_events = [item.model_dump(by_alias=True) for item in events]
        payload.update(
            {
                "reply": reply,
                "terminalStatus": "needs_confirmation",
                "choiceOptions": choices,
                "comparisonProjections": [projection],
                "partialTimeline": True,
                "resultVersionId": version_id,
                "planningSteps": serialized_events,
                "toolEvents": serialized_events,
            }
        )
        self.db.execute(
            """UPDATE conversation_turns
            SET content = ?, status = 'active', itinerary_version_id = ?,
                agent_request_json = ?, agent_response_json = ?, updated_at = ?
            WHERE id = ? AND session_id = ?""",
            (
                reply,
                version_id,
                json.dumps(request_payload, ensure_ascii=False, default=str),
                json.dumps(payload, ensure_ascii=False, default=str),
                datetime.now(timezone.utc).isoformat(),
                assistant_turn_id,
                session_id,
            ),
        )
        response.assistant_turn = self._turn_response(assistant_turn_id)
        response.planning_steps = events
        response.tool_events = events
        response.terminal_status = "needs_confirmation"
        return response

    def _is_current_partial_plan_expansion_option(
        self,
        *,
        session_id: str,
        option: dict[str, Any],
        source_assistant_turn_id: str = "",
        eligibility_diagnostic: Optional[dict[str, Any]] = None,
    ) -> bool:
        """Allow only the persisted same-root option to append comparison plans."""

        def rejected(reason_code: str) -> bool:
            if eligibility_diagnostic is not None:
                eligibility_diagnostic["reasonCode"] = reason_code
            return False

        # Persisted opaque capabilities remain executable across a rollout-gate
        # restart. Root/fingerprint/base/frontier validation below is the
        # authority; a transient feature flag must not turn a valid capability
        # into an identity mismatch or route it to the ordinary writer.

        option_kind = str(option.get("kind") or "")
        if option_kind not in {"portfolio_partial_more_plans", "portfolio_more_plans"}:
            return rejected("portfolio_continuation_kind_mismatch")
        if option_kind == "portfolio_partial_more_plans" and not self._creative_portfolio_enabled({}):
            return rejected("portfolio_continuation_feature_disabled")
        if option_kind == "portfolio_more_plans":
            current = self._session(session_id)
            active_version_id = str(current["active_version_id"] or "")
            root_portfolio_id = str(option.get("rootPortfolioId") or "")
            planning_root_id = str(option.get("planningSelectionRootTurnId") or "")
            request_fingerprint = str(option.get("requestContractFingerprint") or "")
            if active_version_id:
                active_snapshot = self._active_partial_snapshot(session_id)
                if active_snapshot is None:
                    return rejected("portfolio_continuation_active_snapshot_missing")
                try:
                    active_scope = PortfolioPendingSlotService.selection_context(active_snapshot)
                except PortfolioPendingSlotError:
                    return rejected("portfolio_continuation_active_scope_invalid")
                if any(
                    str(active_scope.get(key) or "") != expected
                    for key, expected in (
                        ("planningSelectionRootTurnId", planning_root_id),
                        ("rootPortfolioId", root_portfolio_id),
                        ("requestContractFingerprint", request_fingerprint),
                    )
                ):
                    return rejected("portfolio_continuation_active_scope_mismatch")
            return self._persisted_portfolio_continuation_is_eligible(
                session_id=session_id,
                active_version_id=active_version_id,
                option=option,
                eligibility_diagnostic=eligibility_diagnostic,
            )
        snapshot = self._active_partial_snapshot(session_id)
        if snapshot is None:
            return False
        try:
            selection_context = PortfolioPendingSlotService.selection_context(snapshot)
        except PortfolioPendingSlotError:
            return rejected("portfolio_continuation_active_scope_invalid")
        option_focus_brief_id = str(option.get("focusBriefId") or "")
        active_focus_brief_id = str(selection_context["focusBriefId"])
        expansion_focus_mode = str(option.get("expansionFocusMode") or "")
        if expansion_focus_mode not in {"exact", "discover_next"}:
            # Backward-compatible inference is allowed only after the persisted
            # option and active snapshot have been loaded server-side.
            expansion_focus_mode = "discover_next" if option_focus_brief_id == active_focus_brief_id else "exact"
        root_portfolio_id = str(selection_context["rootPortfolioId"])
        root_portfolio_exists = self._portfolio_continuation_root_exists(root_portfolio_id)
        neutral_checkpoint = bool(
            not root_portfolio_exists
            and self._neutral_partial_expansion_checkpoint_matches(
                session_id=session_id,
                root_portfolio_id=root_portfolio_id,
                planning_root_id=str(selection_context["planningSelectionRootTurnId"]),
                request_fingerprint=str(selection_context["requestContractFingerprint"]),
            )
        )
        current = self._session(session_id)
        active_version_id = str(current["active_version_id"] or "")
        option_matches_snapshot_identity = bool(
            active_version_id
            and str(option.get("expectedBaseVersionId") or "") == active_version_id
            and str(option.get("planningSelectionRootTurnId") or "")
            == str(selection_context["planningSelectionRootTurnId"])
            and str(option.get("rootPortfolioId") or "") == root_portfolio_id
            and str(option.get("requestContractFingerprint") or "")
            == str(selection_context["requestContractFingerprint"])
        )
        if not option_matches_snapshot_identity:
            return rejected("portfolio_continuation_active_scope_mismatch")
        if neutral_checkpoint:
            continuation_expires_at, source_turn_matches = self._neutral_partial_continuation_expiry(
                session_id=session_id,
                source_assistant_turn_id=source_assistant_turn_id,
                option=option,
            )
            decision = PortfolioContinuationCapabilityReconciler.evaluate_eligibility(
                active_version_id=active_version_id,
                portfolio_summary=self._neutral_partial_continuation_summary(
                    selection_context=selection_context,
                ),
                selected_option=option,
                persisted_visible_proposal_ids=(),
                portfolio_status="awaiting_selection",
                session_matches=source_turn_matches,
                continuation_expires_at=continuation_expires_at,
                require_expiry=True,
            )
            if eligibility_diagnostic is not None:
                eligibility_diagnostic.update(
                    {
                        "reasonCode": decision.reason_code,
                        "planningSelectionRootTurnId": decision.planning_selection_root_turn_id,
                        "rootPortfolioId": decision.root_portfolio_id,
                        "focusBriefId": decision.focus_brief_id,
                        "visibleProposalIds": list(decision.visible_proposal_ids),
                        "expiresAt": decision.expires_at,
                    }
                )
            return decision.eligible
        if not root_portfolio_exists:
            return rejected("portfolio_continuation_root_not_found")
        return self._persisted_portfolio_continuation_is_eligible(
            session_id=session_id,
            active_version_id=active_version_id,
            option=option,
            eligibility_diagnostic=eligibility_diagnostic,
            fallback_focus_brief_id=active_focus_brief_id,
        )

    def _portfolio_continuation_root_exists(self, root_portfolio_id: str) -> bool:
        return bool(
            self.db.execute(
                "SELECT 1 FROM agent_plan_portfolios WHERE id = ?",
                (root_portfolio_id,),
            ).fetchone()
        )

    def _portfolio_continuation_root_row(
        self,
        root_portfolio_id: str,
    ) -> Optional[sqlite3.Row]:
        return self.db.execute(
            """SELECT session_id, source_user_turn_id, request_contract_fingerprint,
                status, expires_at, created_at, summary_json
            FROM agent_plan_portfolios WHERE id = ?""",
            (root_portfolio_id,),
        ).fetchone()

    @staticmethod
    def _neutral_partial_continuation_summary(
        *,
        selection_context: dict[str, Any],
    ) -> dict[str, Any]:
        focus_brief_id = str(selection_context.get("focusBriefId") or "")
        return {
            "planningSelectionRootTurnId": str(selection_context.get("planningSelectionRootTurnId") or ""),
            "rootPortfolioId": str(selection_context.get("rootPortfolioId") or ""),
            "requestContractFingerprint": str(selection_context.get("requestContractFingerprint") or ""),
            "focusBriefId": focus_brief_id,
            "generationState": "degraded_has_more",
            "visibleProposalIds": [],
            "creativeExplorationFrontier": {
                "frontierState": "has_more",
                "currentFocusBriefId": focus_brief_id,
                "remainingBudget": 1,
            },
        }

    def _neutral_partial_continuation_expiry(
        self,
        *,
        session_id: str,
        source_assistant_turn_id: str,
        option: dict[str, Any],
    ) -> tuple[str, bool]:
        explicit_expires_at = str(option.get("expiresAt") or "").strip()
        source_turn_id = str(source_assistant_turn_id or "").strip()
        if not source_turn_id:
            return explicit_expires_at, True
        source_row = self.db.execute(
            """SELECT session_id, created_at FROM conversation_turns
            WHERE id = ? AND role = 'assistant' AND status != 'superseded'""",
            (source_turn_id,),
        ).fetchone()
        if source_row is None or str(source_row["session_id"] or "") != session_id:
            return explicit_expires_at, False
        if explicit_expires_at:
            return explicit_expires_at, True
        issued_at = self._parse_event_datetime(source_row["created_at"])
        if issued_at is None:
            return "", True
        return (
            (issued_at + timedelta(minutes=PlanPortfolioStore.PORTFOLIO_TTL_MINUTES)).isoformat(),
            True,
        )

    def _persisted_continuation_expires_at(
        self,
        *,
        expires_at: Any,
        created_at: Any,
    ) -> str:
        explicit_expires_at = str(expires_at or "").strip()
        if explicit_expires_at:
            return explicit_expires_at
        issued_at = self._parse_event_datetime(created_at)
        if issued_at is None:
            return ""
        return (issued_at + timedelta(minutes=PlanPortfolioStore.PORTFOLIO_TTL_MINUTES)).isoformat()

    def _persisted_portfolio_continuation_is_eligible(
        self,
        *,
        session_id: str,
        active_version_id: str,
        option: dict[str, Any],
        eligibility_diagnostic: Optional[dict[str, Any]],
        fallback_focus_brief_id: str = "",
    ) -> bool:
        root_portfolio_id = str(option.get("rootPortfolioId") or "")
        portfolio = self._portfolio_continuation_root_row(root_portfolio_id)
        if portfolio is None:
            if eligibility_diagnostic is not None:
                eligibility_diagnostic["reasonCode"] = "portfolio_continuation_root_not_found"
            return False

        summary = self._json_dict(portfolio["summary_json"])
        summary.update(
            {
                "planningSelectionRootTurnId": str(portfolio["source_user_turn_id"] or ""),
                "rootPortfolioId": root_portfolio_id,
                "requestContractFingerprint": str(portfolio["request_contract_fingerprint"] or ""),
                "expectedBaseVersionId": active_version_id or None,
            }
        )
        if fallback_focus_brief_id and not str(summary.get("nextBriefId") or ""):
            frontier = (
                dict(summary.get("creativeExplorationFrontier"))
                if isinstance(summary.get("creativeExplorationFrontier"), dict)
                else {}
            )
            frontier.setdefault("currentFocusBriefId", fallback_focus_brief_id)
            summary["creativeExplorationFrontier"] = frontier
            summary.setdefault("focusBriefId", fallback_focus_brief_id)

        visible_statuses = {
            "offered",
            "committed",
            "comparison_only",
            "partial_preview",
            "route_pending",
            "route_partial",
            "route_ready",
            "route_provider_failed",
            "adoption_ready",
            "blocked",
        }
        persisted_visible_ids = {
            str(row["id"])
            for row in self.db.execute(
                "SELECT id, status FROM agent_plan_proposals WHERE portfolio_id = ?",
                (root_portfolio_id,),
            ).fetchall()
            if str(row["status"] or "") in visible_statuses
        }
        continuation_expires_at = self._persisted_continuation_expires_at(
            expires_at=portfolio["expires_at"],
            created_at=portfolio["created_at"],
        )
        portfolio_expired = PlanPortfolioStore._is_expired(continuation_expires_at)
        decision = PortfolioContinuationCapabilityReconciler.evaluate_eligibility(
            active_version_id=active_version_id,
            portfolio_summary=summary,
            selected_option=option,
            persisted_visible_proposal_ids=persisted_visible_ids,
            portfolio_status=str(portfolio["status"] or ""),
            portfolio_expired=portfolio_expired,
            session_matches=str(portfolio["session_id"] or "") == session_id,
            continuation_expires_at=continuation_expires_at,
            require_expiry=True,
        )
        if portfolio_expired and str(portfolio["session_id"] or "") == session_id:
            PlanPortfolioStore(self.db)._expire_portfolio(
                root_portfolio_id,
                "plan_portfolio_expired",
            )
        if eligibility_diagnostic is not None:
            eligibility_diagnostic.update(
                {
                    "reasonCode": decision.reason_code,
                    "planningSelectionRootTurnId": decision.planning_selection_root_turn_id,
                    "rootPortfolioId": decision.root_portfolio_id,
                    "focusBriefId": decision.focus_brief_id,
                    "visibleProposalIds": list(decision.visible_proposal_ids),
                }
            )
        return decision.eligible

    @staticmethod
    def _portfolio_continuation_failure_message(reason_code: str) -> str:
        if reason_code == "portfolio_continuation_base_version_mismatch":
            return "当前行程版本已变化，旧的继续生成操作不能执行；请使用最新方案卡上的继续生成按钮。"
        if reason_code == "portfolio_continuation_expired":
            return "当前对比方案已超过可继续探索的有效期，行程未发生变化；请重新生成对比方案。"
        if reason_code in {
            "portfolio_continuation_expiry_missing",
            "portfolio_continuation_expiry_invalid",
            "portfolio_continuation_expiry_mismatch",
        }:
            return "当前继续生成操作的有效期信息无效，行程未发生变化；请使用最新按钮或重新生成对比方案。"
        if reason_code == "portfolio_continuation_frontier_exhausted":
            return "当前已生成全部可验证方向。你可以刷新候选、放宽偏好或指定新的旅行主题。"
        if reason_code == "portfolio_continuation_visible_membership_mismatch":
            return "当前对比卡片与已保存方案不一致，行程未发生变化；请刷新页面后重试。"
        if reason_code == "portfolio_continuation_session_mismatch":
            return "该继续生成操作不属于当前会话，行程未发生变化；请使用当前会话中的最新按钮。"
        if reason_code in {
            "portfolio_continuation_root_not_found",
            "portfolio_continuation_root_portfolio_mismatch",
            "portfolio_continuation_planning_root_mismatch",
        }:
            return "继续生成操作绑定的规划根与当前对比方案不一致，行程未发生变化；请刷新后重试。"
        if reason_code == "portfolio_continuation_request_fingerprint_mismatch":
            return "当前旅行需求已变化，旧的继续生成操作不能执行；请基于最新需求重新生成。"
        if reason_code in {
            "portfolio_continuation_status_ineligible",
            "portfolio_continuation_active_snapshot_missing",
            "portfolio_continuation_active_scope_invalid",
            "portfolio_continuation_active_scope_mismatch",
        }:
            return "当前方案状态已变化，行程未发生变化；请刷新页面并使用最新按钮重试。"
        if reason_code in {
            "portfolio_continuation_focus_mismatch",
            "portfolio_continuation_focus_mode_mismatch",
        }:
            return "继续生成操作绑定的下一方案方向已变化，行程未发生变化；请使用最新按钮重试。"
        return "当前继续生成操作与已保存的规划上下文不一致，行程未发生变化；请刷新后重试。"

    @staticmethod
    def _portfolio_checkpoint_failure_message(reason_code: str) -> str:
        if reason_code == "portfolio_checkpoint_expired":
            return "该待补或继续生成操作已过期，行程未发生变化；请使用当前方案上的最新按钮。"
        if reason_code == "portfolio_checkpoint_base_version_mismatch":
            return "当前行程版本已变化，旧操作不能恢复；请使用当前方案上的最新按钮。"
        if reason_code == "portfolio_checkpoint_session_mismatch":
            return "该操作不属于当前会话，行程未发生变化。"
        if reason_code == "portfolio_checkpoint_request_fingerprint_mismatch":
            return "旅行需求已变化，旧操作不能恢复；请基于最新需求继续。"
        if reason_code in {
            "portfolio_checkpoint_planning_root_mismatch",
            "portfolio_checkpoint_portfolio_mismatch",
            "portfolio_checkpoint_proposal_mismatch",
        }:
            return "该操作绑定的原方案已变化，行程未发生变化；请使用当前方案上的最新按钮。"
        return "该操作的恢复身份与已保存记录不一致，行程未发生变化；请使用最新按钮。"

    def _neutral_partial_expansion_checkpoint_matches(
        self,
        *,
        session_id: str,
        root_portfolio_id: str,
        planning_root_id: str,
        request_fingerprint: str,
        active_version_id: str = "",
    ) -> bool:
        """Validate a RuleSafe turn/snapshot cursor before Portfolio exists."""

        if not all(
            str(item or "").strip() for item in (session_id, root_portfolio_id, planning_root_id, request_fingerprint)
        ):
            return False
        if root_portfolio_id != f"partial:{planning_root_id}":
            return False
        if (
            self.db.execute(
                "SELECT 1 FROM agent_plan_portfolios WHERE id = ?",
                (root_portfolio_id,),
            ).fetchone()
            is not None
        ):
            return False
        current = self._session(session_id)
        current_version_id = str(current["active_version_id"] or "")
        if not current_version_id or (active_version_id and active_version_id != current_version_id):
            return False
        snapshot = self._active_partial_snapshot(session_id)
        if snapshot is None:
            return False
        try:
            selection_context = PortfolioPendingSlotService.selection_context(snapshot)
        except PortfolioPendingSlotError:
            return False
        if any(
            str(selection_context.get(key) or "") != expected
            for key, expected in (
                ("planningSelectionRootTurnId", planning_root_id),
                ("rootPortfolioId", root_portfolio_id),
                ("requestContractFingerprint", request_fingerprint),
            )
        ):
            return False
        partial = (
            snapshot.get("portfolioPartialTimeline")
            if isinstance(snapshot.get("portfolioPartialTimeline"), dict)
            else {}
        )
        return bool(
            str(snapshot.get("status") or "") == "partial"
            and partial.get("sourceProposalId") in {None, ""}
            and partial.get("strictProposalVerifierPassed") is False
            and bool(snapshot.get("portfolioPendingSlots"))
        )

    def _validated_partial_plan_expansion_root(
        self,
        *,
        session_id: str,
        root_portfolio_id: str,
        planning_root_id: str,
        request_fingerprint: str,
    ) -> Optional[sqlite3.Row]:
        """Return the persisted same-root Portfolio identity or fail closed."""

        if not all(
            (
                str(session_id).strip(),
                str(root_portfolio_id).strip(),
                str(planning_root_id).strip(),
                str(request_fingerprint).strip(),
            )
        ):
            return None
        row = self.db.execute(
            """SELECT session_id, source_user_turn_id, request_contract_fingerprint,
                status, expires_at, summary_json
            FROM agent_plan_portfolios WHERE id = ?""",
            (root_portfolio_id,),
        ).fetchone()
        if row is None:
            return None
        if (
            str(row["session_id"] or "") != session_id
            or str(row["source_user_turn_id"] or "") != planning_root_id
            or str(row["request_contract_fingerprint"] or "") != request_fingerprint
        ):
            return None
        if str(row["status"] or "") not in {"awaiting_selection", "failed"}:
            return None
        if PlanPortfolioStore._is_expired(row["expires_at"]):
            PlanPortfolioStore(self.db)._expire_portfolio(
                root_portfolio_id,
                "plan_portfolio_expired",
            )
            return None
        return row

    def _reissue_remaining_pending_slot_choices(
        self,
        *,
        session_id: str,
        request_context: dict[str, Any],
        result_version_id: str,
        reissued_assistant_turn_id: str,
    ) -> tuple[list[dict[str, Any]], Optional[dict[str, Any]]]:
        selected = (
            request_context.get("selectedAgentChoice")
            if isinstance(request_context.get("selectedAgentChoice"), dict)
            else {}
        )
        option = selected.get("option") if isinstance(selected.get("option"), dict) else {}
        if not self.portfolio_density_continuation.is_density_option(option):
            return [], None
        source_turn_id = str(selected.get("sourceAssistantTurnId") or "")
        source_row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ?",
            (source_turn_id, session_id),
        ).fetchone()
        version_row = self._version(result_version_id, session_id, self._session(session_id)["active_plan_id"])
        snapshot = PortfolioPendingSlotService.reconcile(self._json_dict(version_row["snapshot_json"]))
        selection_context = PortfolioPendingSlotService.selection_context(snapshot)
        remaining_keys = {
            PortfolioPendingSlotService.slot_key(slot)
            for slot in snapshot.get("portfolioPendingSlots") or []
            if isinstance(slot, dict)
        }
        source_payload = self._json_dict(source_row["agent_response_json"]) if source_row is not None else {}
        reissued: list[dict[str, Any]] = []
        prior_projection: Optional[dict[str, Any]] = None
        for source_option in source_payload.get("choiceOptions") or []:
            if not isinstance(source_option, dict):
                continue
            if isinstance(source_option.get("comparisonProjection"), dict):
                prior_projection = source_option["comparisonProjection"]
            try:
                option_slot_key = PortfolioPendingSlotService.slot_key(source_option)
            except PortfolioPendingSlotError:
                continue
            if option_slot_key not in remaining_keys:
                continue
            copy_option = copy.deepcopy(source_option)
            copy_option["expectedBaseVersionId"] = result_version_id
            copy_option["lifecycle"] = "offered"
            try:
                copy_option["continuationCheckpoint"] = self.portfolio_density_continuation.issue_reissued_checkpoint(
                    source_assistant_turn_id=reissued_assistant_turn_id,
                    option=copy_option,
                    active_snapshot=snapshot,
                    expected_base_version_id=result_version_id,
                )
            except PortfolioPendingSlotError:
                # A remaining option must bind to exactly one active slot; do
                # not carry a broad or stale source option into the new turn.
                continue
            reissued.append(copy_option)
        adopted_row = self.db.execute(
            """SELECT id FROM agent_choice_executions
            WHERE session_id = ? AND action = 'adopt_active_partial' AND status = 'succeeded'
              AND outcome_json LIKE ? ORDER BY updated_at DESC LIMIT 1""",
            (
                session_id,
                f'%"planningSelectionRootTurnId": "{selection_context["planningSelectionRootTurnId"]}"%',
            ),
        ).fetchone()
        projection = PlanComparisonPreviewService.project_snapshot(
            snapshot,
            planning_selection_root_turn_id=selection_context["planningSelectionRootTurnId"],
            root_portfolio_id=selection_context["rootPortfolioId"],
            proposal_id=str(
                (prior_projection or {}).get("proposalId") or f"partial:{selection_context['rootPortfolioId']}"
            ),
            source_assistant_turn_id=reissued_assistant_turn_id,
            choice_id=str((prior_projection or {}).get("choiceId") or selected.get("choiceId") or ""),
            active_version_id=result_version_id,
            expected_base_version_id=result_version_id,
            is_partial=True,
            is_adopted=adopted_row is not None,
        )
        for item in reissued:
            item["comparisonProjection"] = projection
        return reissued, projection

    @staticmethod
    def _preserve_coordinator_request_lineage(
        previous: dict[str, Any],
        reloaded: dict[str, Any],
    ) -> None:
        """Carry immutable request evidence across one persisted coordinator reload."""

        for key in (
            "selectedAgentChoice",
            "fallbackChoiceExecutionClaim",
            "continuationContext",
            "guideContinuationRequirement",
            "canonicalRequestContext",
            "sourceUserRequest",
            "effectiveUserMessage",
            "resolvedTripDates",
            "requestIntentContract",
            "planningSelectionRootTurnId",
            "rootPortfolioId",
            "focusBriefId",
            "requestContractFingerprint",
            "expectedBaseVersionId",
            "retryExecutionPlan",
            "retryIntent",
            "conversationIntent",
            "conversationCapability",
            "_partialPlanExpansionAuthorized",
            "activePartialFocusBriefId",
            "partialPlanExpansionClaim",
            "partialPlanExpansionFocusMode",
            "clarificationCheckpoint",
            "clarificationManualNormalization",
            "experienceSpecs",
            "candidateGapSummary",
            "viewResolution",
            "_simpleDirectionGenerationAuthorized",
            "_simpleDirectionRequestContractFingerprint",
        ):
            if key in previous:
                reloaded[key] = copy.deepcopy(previous[key])

    def _run_coordinated_natural_language_turn(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        content: str,
        payload: Union[AgentMessageRequest, AgentMessageEditRequest],
        request_context: dict[str, Any],
        event_sink: Optional[AgentExecutionEventSink],
    ) -> AgentMessageResponse:
        """Run ordinary language through the one model-owned control loop."""

        request_context.update(
            {
                "sessionId": session_id,
                "currentUserTurnId": user_turn_id,
                "rootCoordinatorManaged": True,
                "skipPostObservationController": True,
                "serverExecutionProfile": self.initial_planning_mode,
            }
        )
        self.simple_open_itinerary_executor.prepare_initial_context(request_context)
        self._restore_request_intent_contract(session_id, request_context)
        self._restore_active_route_decision_contract(request_context)
        # Restoring a request contract can rehydrate strict-only ambiguity
        # flags from a prior projection, so normalize once more at the exact
        # boundary before the Controller builds its allowed action set.
        self.simple_open_itinerary_executor.prepare_initial_context(request_context)

        available_tools = {
            "read_itinerary",
            "resolve_poi",
            "optimize_route",
            "patch_itinerary",
            "web_search",
            "amap_weather",
            "ticket_lookup",
        }

        def observe(context: dict[str, Any], cycle_index: int, last_outcome: Optional[AgentActionOutcome]) -> Any:
            return self.autonomy_observation_builder.build(
                context,
                cycle_index=cycle_index,
                last_action=(
                    {"action": last_outcome.action, "executionRoute": last_outcome.execution_route}
                    if last_outcome is not None
                    else None
                ),
                last_outcome=last_outcome.to_context() if last_outcome is not None else None,
            )

        def decide(context: dict[str, Any], observation: Any, cycle_index: int) -> Any:
            context["agentObservation"] = observation.model_dump(by_alias=True)
            autonomy_context = self.autonomy_context_projector.project(context)
            context["autonomyContext"] = autonomy_context
            intent_decision = self._conversation_intent_decision(
                context,
                cycle_index=cycle_index,
            )
            if intent_decision is not None:
                return intent_decision
            if self._retry_recovery_preempts_controller(context, cycle_index=cycle_index):
                return self._retry_recovery_decision(context)
            self._apply_request_provider_model(context)
            result = self.autonomy_controller.decide(
                self._coordinator_decision_message(context, content),
                context,
                autonomy_context,
                available_tools=available_tools,
                runtime_budget_tools=available_tools,
                observation=observation,
            )
            result = self.simple_open_itinerary_executor.adapt_initial_decision(context, result)
            route_context = context.get("conversationIntent") if isinstance(context.get("conversationIntent"), dict) else {}
            invocation_ledger = dict(route_context.get("invocationLedger") or {})
            invocation_ledger.update(
                {
                    "fullControllerCallCount": int(result.controller_full_called),
                    "fallbackControllerLiteCallCount": int(result.controller_lite_called),
                    "plannerCallCount": int(result.planner_called),
                }
            )
            return replace(result, invocation_ledger=invocation_ledger)

        def reload_context(previous: dict[str, Any], outcome: AgentActionOutcome, cycle_index: int) -> dict[str, Any]:
            current_session = self._session(session_id)
            reload_payload = payload
            if isinstance(previous.get("selectedAgentChoice"), dict):
                # The persisted choice was already identity/version checked and
                # CAS-claimed at turn entry. Re-validating it after its own
                # successful write would compare the offered base version with
                # the newly committed result version and falsely report stale.
                reload_payload = payload.model_copy(
                    update={"context": payload.context.model_copy(update={"selected_agent_choice": None})}
                )
            reloaded = self._build_request_context(
                current_session,
                content,
                reload_payload,
                current_user_turn_id=user_turn_id,
                defer_agent_decision=True,
                allow_plan_expansion_rebind=False,
                conversation_intent_route=(
                    previous.get("conversationIntent") if isinstance(previous.get("conversationIntent"), dict) else None
                ),
                conversation_capability_resolution=(
                    previous.get("conversationCapability")
                    if isinstance(previous.get("conversationCapability"), dict)
                    else None
                ),
            )
            self._restore_request_intent_contract(session_id, reloaded)
            self._restore_active_route_decision_contract(reloaded)
            self._preserve_coordinator_request_lineage(previous, reloaded)
            # The reload boundary is authoritative for write lineage. Canonical
            # request facts remain restored, while the version advances only
            # from the persisted session after an executor commits.
            reloaded["activeVersionId"] = current_session["active_version_id"]
            canonical = (
                reloaded.get("canonicalRequestContext")
                if isinstance(reloaded.get("canonicalRequestContext"), dict)
                else None
            )
            if canonical is not None:
                canonical["activeVersionId"] = current_session["active_version_id"]
            previous_effective = str(previous.get("effectiveUserMessage") or "").strip()
            if previous_effective and previous_effective != content.strip():
                reloaded["effectiveUserMessage"] = previous_effective
            reloaded.update(
                {
                    "sessionId": session_id,
                    "currentUserTurnId": user_turn_id,
                    "rootCoordinatorManaged": True,
                    "skipPostObservationController": True,
                    "coordinatorReloadedPersistedState": True,
                    "coordinatorPreviousCycle": cycle_index,
                    "coordinatorLastOutcome": outcome.to_context(),
                }
            )
            if outcome.goal_delta.get("planningAttemptPersisted") is True:
                persisted_attempt = PlanningAttemptResumeService(self.db).latest_resumable_attempt(session_id)
                if persisted_attempt is not None:
                    reloaded["resumePlanningAttempt"] = {
                        "enabled": True,
                        **persisted_attempt,
                        "reason": "root_coordinator_reload_persisted_planning_attempt",
                        "resumeFromStage": "collect_candidates",
                        "reuseInitialPlan": True,
                        "retryOnlyUnresolvedSlots": True,
                    }
            if isinstance(outcome.terminal_payload, AgentMessageResponse):
                reloaded["_coordinatorPriorResponse"] = outcome.terminal_payload
            return reloaded

        result = self.turn_coordinator.run(
            request_context,
            observe=observe,
            decide=decide,
            reload_context=reload_context,
            event_sink=event_sink,
            max_cycles=4,
        )
        response = next(
            (
                outcome.terminal_payload
                for outcome in reversed(result.outcomes)
                if isinstance(outcome.terminal_payload, AgentMessageResponse)
            ),
            None,
        )
        if response is None:
            terminal = result.terminal_decision
            terminal_action = str(terminal.get("primaryAction") or "")
            terminal_context = result.final_context
            terminal_context["agentDecisionState"] = terminal
            if terminal_action == "ask_user":
                raw_clarification = terminal.get("clarification")
                response = self._preflight_clarification_response(
                    session_id=session_id,
                    user_turn_id=user_turn_id,
                    user_turn=user_turn,
                    session=self._session(session_id),
                    content=content,
                    request_context=terminal_context,
                    controller_clarification=(
                        copy.deepcopy(raw_clarification) if isinstance(raw_clarification, dict) else None
                    ),
                )
            elif terminal_action == "finish" and terminal.get("accepted") is True:
                response = self._execute_finish_action(
                    session_id, user_turn, self._session(session_id), content, terminal_context, terminal
                )
            else:
                response = self._finish_no_safe_action(
                    session_id,
                    user_turn,
                    self._session(session_id),
                    content,
                    terminal_context,
                    reason=f"agent_coordinator:{result.stop_reason}",
                )
        if result.stop_reason == "partial_timeline_needs_confirmation":
            response = response.model_copy(update={"terminal_status": "needs_confirmation"})
        current_session = self._session(session_id)
        current_version_id = str(current_session["active_version_id"] or "")
        verified_result_ids = {
            str(outcome.result_version_id)
            for outcome in result.outcomes
            if outcome.result_version_id
            and outcome.status in {"success", "partial", "needs_confirmation"}
            and outcome.verifier.get("passed") is not False
        }
        if (
            current_version_id
            and current_version_id in verified_result_ids
            and (response.version is None or response.version.id != current_version_id)
        ):
            response = response.model_copy(
                update={
                    "itinerary": ItineraryService(self.db).get_plan(current_session["active_plan_id"]),
                    "version": self._version_response(
                        self._version(
                            current_version_id,
                            session_id,
                            current_session["active_plan_id"],
                        )
                    ),
                }
            )
        # The root coordinator owns the turn lifecycle, so executor-internal
        # paths deliberately suppress their legacy auto-memory side effect.
        # Apply it once, after the verified terminal response is known.
        explicit_memory_policy = any(
            str(cycle.decision.get("memoryPolicy") or "none") != "none" and bool(cycle.decision.get("memoryCandidates"))
            for cycle in result.cycles
        )
        if not explicit_memory_policy:
            self._auto_update_preference_memory(session_id, content, response.assistant_turn.content)
        response = response.model_copy(update={"preference_memory": self._current_preference_memory(session_id)})
        return self._attach_coordinator_trace(response, result, user_turn_id, event_sink)

    @staticmethod
    def _coordinator_decision_message(context: dict[str, Any], fallback: str) -> str:
        return controller_decision_message(context, fallback)

    @staticmethod
    def _retry_recovery_preempts_controller(
        context: dict[str, Any],
        *,
        cycle_index: int,
    ) -> bool:
        """Keep legacy retry recovery from shadowing an exact continuation capability."""

        if cycle_index != 0:
            return False
        recovery = context.get("retryExecutionPlan") if isinstance(context.get("retryExecutionPlan"), dict) else {}
        recovery_kind = str(recovery.get("kind") or "")
        if recovery.get("controllerAllowed") is not False or recovery_kind not in {
            "resume_portfolio",
            "repair_last_failure",
            "continue_partial_slot",
            "resume_incomplete_stage",
            "ask_retry_scope",
            "expand_partial_portfolio",
        }:
            return False
        # RetryExecutionPlanService still classifies this natural-language
        # continuation as a generic retry. Once the latest-turn opaque choice
        # is independently validated, that older projection is not execution
        # authority and must not short-circuit the real expansion pipeline.
        return not (
            recovery_kind == "ask_retry_scope"
            and str(recovery.get("reasonCode") or "") == "persisted_portfolio_expansion_capability_required"
            and simple_direction_generation_authorized(context)
        )

    def _conversation_intent_decision(
        self,
        context: dict[str, Any],
        *,
        cycle_index: int,
    ) -> Optional[AgentDecisionResult]:
        if cycle_index != 0:
            return None
        route = context.get("conversationIntent") if isinstance(context.get("conversationIntent"), dict) else {}
        capability = (
            context.get("conversationCapability") if isinstance(context.get("conversationCapability"), dict) else {}
        )
        classification = route.get("classification") if isinstance(route.get("classification"), dict) else {}
        intent = str(classification.get("intent") or "")
        disposition = str(route.get("executionDisposition") or "")
        capability_status = str(capability.get("status") or "")
        terminal_direction = (
            self._simple_direction_terminal_continuation_state(context)
            if intent == "continue_plan_expansion" and capability_status == "none"
            else None
        )
        if terminal_direction is not None:
            disposition = "read_only"
        choice_required = intent in {
            "continue_plan_expansion",
            "adopt_plan",
            "continue_pending_slot",
            "manual_candidate_search",
            "search_travel_guide_advice",
        }
        must_ask = terminal_direction is None and (
            bool(route.get("requiresClarification"))
            or (choice_required and capability_status != "unique")
            or capability_status in {"none", "ambiguous"}
        )
        if not must_ask and disposition not in {"read_only", "no_write"}:
            return None

        capability_unavailable = bool(choice_required and capability_status == "none" and terminal_direction is None)
        if capability_unavailable:
            reason_code = str(capability.get("reasonCode") or "current_capability_unavailable")
            reply = (
                "当前继续探索能力已失效；行程未发生变化。请加载最新规划状态后再继续。"
                if intent == "continue_plan_expansion"
                else "当前操作能力已失效；行程未发生变化。请使用最新回复中的结构化操作。"
            )
            primary_action = "finish"
            action_directive = {"type": "finish", "assistantReply": reply}
            stop_condition = {"type": "executor_terminal"}
            clarification = None
        elif must_ask:
            route_reason = str(route.get("reasonCode") or "")
            semantic_action = route.get("semanticAction") or {}
            if route_reason == "proposal_confirmation_required":
                reply = "已理解你想采用方案。请通过最新回复中对应方案的确认操作提交；当前尚未修改正式行程。"
                reason_code = route_reason
            elif semantic_action.get("name") == "unavailable":
                missing = str(semantic_action.get("guideUnavailableReason") or "")
                reply = (
                    "当前没有可核验的有效攻略证据或攻略续规划能力；请重新搜索攻略并获取有效操作。尚未调用规划器，也没有生成无关方案。"
                    if missing
                    else "已理解请求，但当前状态缺少对应的合法操作或目标。请先获取有效操作；尚未调用规划器，行程未发生变化。"
                )
                reason_code = missing or route_reason
            elif route_reason.startswith("semantic_action_"):
                reply = "入口语义提案未通过安全校验；尚未调用规划器，行程未发生变化。请使用最新有效操作或补充目标。"
                reason_code = route_reason
            elif capability_status == "ambiguous":
                reply = "当前有多个可执行目标，未自动选择。请使用对应的结构化按钮明确要继续的操作。"
                reason_code = "multiple_matching_capabilities"
            elif route_reason in {
                "intent_target_unresolved",
                "intent_target_ambiguous",
                "intent_target_stale",
            }:
                reply = {
                    "intent_target_unresolved": "没有找到与这句话唯一对应的当前目标；行程未发生变化。请明确具体方案、日期或时段。",
                    "intent_target_ambiguous": "这句话可对应多个当前目标，系统没有替你选择；行程未发生变化。请明确具体方案、日期或时段。",
                    "intent_target_stale": "你引用的目标已不属于最新规划状态；行程未发生变化。请基于最新回复重新选择。",
                }[route_reason]
                reason_code = route_reason
            elif route_reason in {"intent_provider_unavailable", "intent_model_contract_invalid"}:
                reply = (
                    "通用意图解释服务本轮不可用；尚未调用规划控制器，且行程未发生变化。请稍后重试。"
                    if route_reason == "intent_provider_unavailable"
                    else "通用意图解释结果不符合安全契约；尚未调用规划控制器，且行程未发生变化。请换一种说法。"
                )
                reason_code = route_reason
            elif route_reason in {"intent_semantic_ambiguity", "intent_confidence_below_risk_threshold"}:
                reply = (
                    "这句话存在多个合理解释，系统未自动执行；行程未发生变化。请明确要继续哪个阶段或修改哪个对象。"
                    if route_reason == "intent_semantic_ambiguity"
                    else "系统对这次高风险操作的理解置信度不足，未自动执行；行程未发生变化。请明确目标。"
                )
                reason_code = route_reason
            elif choice_required:
                reply = "当前没有唯一、仍有效的可执行目标，行程未发生变化。请使用最新回复中的结构化按钮继续。"
                reason_code = str(capability.get("reasonCode") or "no_matching_capability")
            else:
                reply = (
                    "我无法以足够置信度确定这次要执行的操作，行程未发生变化。请明确要创建、修改、重试还是仅查看说明。"
                )
                reason_code = str(route.get("reasonCode") or "intent_requires_clarification")
            primary_action = "ask_user"
            action_directive = {
                "type": "ask_user",
                "question": reply,
                "choiceIds": [],
            }
            stop_condition = {"type": "needs_confirmation"}
            clarification = {"question": reply, "choiceIds": []}
        else:
            if terminal_direction is not None:
                frontier_status = str(terminal_direction.get("frontierStatus") or "")
                if frontier_status == "poi_exhausted":
                    reply = (
                        "当前方向探索已达到服务器冻结的地点分页上限；没有新的继续探索能力，"
                        "行程未发生变化。已有方向仍保留在行程对比中；你可以补全现有方向，"
                        "或明确提出新的筛选条件以创建新的规划根。"
                    )
                elif frontier_status == "qualification_exhausted":
                    reply = (
                        "当前方向探索的资格实体前沿已经耗尽；没有新的继续探索能力，行程未发生变化。"
                        "已有方向仍保留在行程对比中；如需扩大范围，请明确提出新的筛选条件。"
                    )
                else:
                    reply = (
                        "当前方向探索的路线可行前沿已经耗尽；没有新的继续探索能力，行程未发生变化。"
                        "已有方向仍保留在行程对比中；可先补全现有方向或明确调整路线约束。"
                    )
                reason_code = str(terminal_direction.get("reasonCode") or "simple_direction_frontier_exhausted")
            elif intent == "cancel_action":
                reply = "已取消本轮动作；没有执行规划、版本、补丁或路线写入。"
                reason_code = "conversation_action_cancelled"
            else:
                recovery = (
                    context.get("retryExecutionPlan") if isinstance(context.get("retryExecutionPlan"), dict) else {}
                )
                recovery_reason = str(recovery.get("reasonCode") or "").strip()
                reply = "这是对当前规划状态的询问，本轮未继续生成或写入行程。" + (
                    f" 当前服务端状态为：{recovery_reason}。" if recovery_reason else ""
                )
                reason_code = "conversation_inspection_read_only"
            primary_action = "finish"
            action_directive = {
                "type": "finish",
                "assistantReply": reply,
            }
            stop_condition = {"type": "executor_terminal"}
            clarification = None

        decision = AgentDecision(
            schemaVersion="agent-decision-v3",
            primaryAction=primary_action,
            confidence=1.0,
            decisionSummary=f"conversation intent: {intent or 'uncertain'}",
            userVisibleReason=reply,
            reasonCodes=["server_authoritative_conversation_intent", reason_code],
            actionDirective=action_directive,
            proposedWriteRisk="none",
            targetScope={},
            uncertaintyPolicy="ask_user" if must_ask and not capability_unavailable else "none",
            clarification=clarification,
            expectedOutcome={
                "taskRoute": "conversation_intent",
                "intent": intent or None,
                "writeBudget": 0,
            },
            stopCondition=stop_condition,
            fallbackAction="ask_user" if must_ask and not capability_unavailable else "finish",
            sideEffects={"conversation": True, "itinerary": False},
        )
        gated = GatedAgentDecision(
            decision=decision,
            effectiveWriteRisk="none",
            effectiveTools=[],
            policyReasonCodes=["server_authoritative_conversation_intent"],
            accepted=True,
        )
        route_source = str(route.get("source") or "safe_fallback")
        model_attempted = bool(route.get("modelAttempted"))
        model_called = bool(route.get("modelCalled"))
        model_succeeded = bool(route.get("modelSucceeded"))
        if route_source in {"lite_controller", "state_aware_lite"} and model_succeeded:
            decision_source = "controller"
            decision_path = "lite"
        elif route_source in {"deterministic_fast_path", "legacy_fallback"}:
            decision_source = "deterministic_fast_path"
            decision_path = "deterministic"
        else:
            decision_source = "safe_fallback"
            decision_path = "fallback"
        performance_evidence = tuple(
            dict(item) for item in route.get("modelPerformanceEvidence") or [] if isinstance(item, dict)
        )
        return AgentDecisionResult(
            decision=decision,
            gated_decision=gated,
            source=decision_source,
            controller_error=(
                str(route.get("reasonCode") or "intent_model_failed")
                if model_attempted and not model_succeeded
                else None
            ),
            planner_plan={},
            decision_path=decision_path,
            controller_full_called=False,
            controller_lite_called=(model_called if route_source == "lite_controller" else False),
            controller_lite_succeeded=(model_succeeded if route_source == "lite_controller" else False),
            controller_performance=performance_evidence,
            configured_lite_timeout_seconds=(self.autonomy_controller.lite_timeout_seconds),
            decision_contract_version="conversation-intent-v2",
            invocation_ledger=dict(route.get("invocationLedger") or {}),
        )

    def _simple_direction_terminal_continuation_state(
        self,
        context: dict[str, Any],
    ) -> Optional[dict[str, Any]]:
        """Return a frozen terminal frontier instead of inventing an empty clarification."""

        session_id = str(context.get("sessionId") or "").strip()
        if not session_id:
            return None
        service = SimpleOpenDirectionService(self.db)
        planning_root_id = str(context.get("planningSelectionRootTurnId") or "").strip()
        root = (
            service.root_for_planning_root(session_id=session_id, planning_root_id=planning_root_id)
            if planning_root_id
            else service.latest_root(session_id=session_id)
        )
        if not isinstance(root, dict):
            return None
        compatibility_attempts = root.get("simpleDirectionCompatibilityAttempts")
        latest_compatibility = max(
            (
                item
                for item in (compatibility_attempts or {}).values()
                if isinstance(item, dict) and str(item.get("status") or "") in {"reconciled", "no_progress"}
            ),
            key=lambda item: str(item.get("updatedAt") or item.get("claimedAt") or ""),
            default={},
        )
        frontier = root.get("simpleDirectionFrontier") if isinstance(root.get("simpleDirectionFrontier"), dict) else {}
        frontier_status = str(
            latest_compatibility.get("frontierStatus")
            or frontier.get("frontierStatus")
            or root.get("simpleDirectionFrontierStatus")
            or ""
        )
        if frontier_status not in {
            "poi_exhausted",
            "qualification_exhausted",
            "route_feasible_exhausted",
        }:
            return None
        return {
            "frontierStatus": frontier_status,
            "reasonCode": str(
                latest_compatibility.get("reasonCode")
                or frontier.get("terminalReasonCode")
                or "simple_direction_frontier_exhausted"
            ),
            "rootPortfolioId": str(root.get("id") or ""),
        }

    def _retry_recovery_decision(self, context: dict[str, Any]) -> AgentDecisionResult:
        """Keep checkpoint-aware retry inside the existing root coordinator."""
        plan = context.get("retryExecutionPlan") if isinstance(context.get("retryExecutionPlan"), dict) else {}
        kind = str(plan.get("kind") or "ask_retry_scope")
        options = [
            item for item in plan.get("choiceOptions") or [] if isinstance(item, dict) and str(item.get("id") or "")
        ]
        if kind in {"resume_incomplete_stage", "expand_partial_portfolio"}:
            directive = context.get("planningDirective") if isinstance(context.get("planningDirective"), dict) else {}
            if not directive and kind == "resume_incomplete_stage":
                attempt = (
                    context.get("resumePlanningAttempt")
                    if isinstance(context.get("resumePlanningAttempt"), dict)
                    else {}
                )
                attempt_context = (
                    attempt.get("pipelineContext") if isinstance(attempt.get("pipelineContext"), dict) else {}
                )
                directive = (
                    attempt_context.get("planningDirective")
                    if isinstance(attempt_context.get("planningDirective"), dict)
                    else {}
                )
            is_expansion = kind == "expand_partial_portfolio"
            if not directive and is_expansion:
                autonomy_context = (
                    context.get("autonomyContext") if isinstance(context.get("autonomyContext"), dict) else {}
                )
                normalization_context = self.autonomy_controller._normalization_context(autonomy_context)
                fallback_decision = self.autonomy_controller._deterministic_cardinality_draft_decision(
                    normalization_context
                )
                if fallback_decision is not None:
                    directive = fallback_decision.model_dump(by_alias=True, exclude_none=True).get(
                        "actionDirective",
                        {},
                    )
            if not directive:
                decision = AgentDecision(
                    schemaVersion="agent-decision-v3",
                    primaryAction="ask_user",
                    confidence=1.0,
                    decisionSummary=f"checkpoint-aware retry unavailable: {kind}",
                    userVisibleReason="当前方案缺少可验证的原规划指令，未生成新方案；请重新进入行程对比后再试。",
                    reasonCodes=["portfolio_partial_source_directive_missing"],
                    actionDirective={
                        "type": "ask_user",
                        "question": "当前方案缺少可验证的原规划指令，是否重新进入行程对比？",
                        "choiceIds": [],
                    },
                    proposedWriteRisk="none",
                    targetScope={},
                    uncertaintyPolicy="ask_user",
                    stopCondition={"type": "needs_confirmation"},
                    sideEffects={"conversation": True, "itinerary": False},
                )
                gated = GatedAgentDecision(
                    decision=decision,
                    effectiveWriteRisk="none",
                    effectiveTools=[],
                    policyReasonCodes=["server_authoritative_retry_recovery"],
                    accepted=True,
                )
                return AgentDecisionResult(
                    decision=decision,
                    gated_decision=gated,
                    source="deterministic_fast_path",
                    controller_error=None,
                    planner_plan={},
                    decision_path="deterministic",
                    controller_full_called=False,
                    controller_lite_called=False,
                    decision_contract_version="retry-execution-plan-v1",
                )
            decision = AgentDecision(
                schemaVersion="agent-decision-v3",
                primaryAction="draft_itinerary",
                confidence=1.0,
                decisionSummary=f"checkpoint-aware retry: {kind}",
                userVisibleReason=(
                    "正在沿用当前规划根生成所选方向的新方案，不重新理解旅行需求。"
                    if is_expansion
                    else "正在从上次安全检查点继续，不重新理解需求或生成方案骨架。"
                ),
                reasonCodes=[
                    "server_authoritative_retry_recovery",
                    str(plan.get("reasonCode") or "persisted_incomplete_stage_available"),
                ],
                actionDirective=directive,
                proposedWriteRisk="medium",
                targetScope={},
                uncertaintyPolicy="ask_user",
                expectedOutcome={
                    "taskRoute": "portfolio_expansion" if is_expansion else "checkpoint_recovery",
                    "retryExecutionKind": kind,
                    "writeBudget": int(plan["writeBudget"]) if plan.get("writeBudget") is not None else 1,
                },
                stopCondition={"type": "terminal_or_needs_confirmation"},
                fallbackAction="ask_user",
                sideEffects={"conversation": True, "itinerary": True},
            )
            gated = GatedAgentDecision(
                decision=decision,
                effectiveWriteRisk="medium",
                effectiveTools=[],
                policyReasonCodes=["server_authoritative_retry_recovery"],
                accepted=bool(directive.get("type") == "draft_itinerary"),
            )
            return AgentDecisionResult(
                decision=decision,
                gated_decision=gated,
                source="deterministic_fast_path",
                controller_error=None,
                planner_plan={},
                decision_path="deterministic",
                controller_full_called=False,
                controller_lite_called=False,
                decision_contract_version="retry-execution-plan-v1",
            )
        if kind == "resume_portfolio":
            question = "上次已有通过校验的方案，未重新搜索地点。请从下面的原方案中确认一套。"
        elif kind == "continue_partial_slot":
            question = "当前是部分时间轴；请选择具体待补槽位及其持久化候选后继续。"
        elif kind == "repair_last_failure":
            question = "已定位上次失败组件；请确认对应的修复候选后继续，当前时间轴未修改。"
        else:
            question = "没有可安全自动执行的重试目标。请选择具体待补项，或明确说“全部从头重新生成”。"
        decision = AgentDecision(
            schemaVersion="agent-decision-v3",
            primaryAction="ask_user",
            confidence=1.0,
            decisionSummary=f"checkpoint-aware retry: {kind}",
            userVisibleReason=question,
            reasonCodes=[
                "server_authoritative_retry_recovery",
                str(plan.get("reasonCode") or "retry_scope_required"),
            ],
            actionDirective={
                "type": "ask_user",
                "question": question,
                "choiceIds": [str(item.get("id")) for item in options],
            },
            proposedWriteRisk="none",
            targetScope={},
            uncertaintyPolicy="ask_user",
            clarification={
                "question": question,
                "choiceIds": [str(item.get("id")) for item in options],
            },
            expectedOutcome={
                "taskRoute": "checkpoint_recovery",
                "retryExecutionKind": kind,
                "writeBudget": 0,
            },
            stopCondition={"type": "needs_confirmation"},
            fallbackAction="ask_user",
            sideEffects={"conversation": True, "itinerary": False},
        )
        gated = GatedAgentDecision(
            decision=decision,
            effectiveWriteRisk="none",
            effectiveTools=[str(item) for item in plan.get("allowedTools") or [] if str(item)],
            policyReasonCodes=["server_authoritative_retry_recovery"],
            accepted=True,
        )
        return AgentDecisionResult(
            decision=decision,
            gated_decision=gated,
            source="deterministic_fast_path",
            controller_error=None,
            planner_plan={},
            decision_path="deterministic",
            controller_full_called=False,
            controller_lite_called=False,
            decision_contract_version="retry-execution-plan-v1",
        )

    def _coordinator_executor_inputs(
        self, request: AgentActionExecutionRequest
    ) -> tuple[dict[str, Any], dict[str, Any], str, str, str, sqlite3.Row, ConversationTurnResponse]:
        context = request.request_context
        decision_state = request.decision_state
        decision = request.decision
        context["agentDecisionState"] = decision_state
        context["agentDecisionShadow"] = decision_state
        context["agentDecision"] = decision
        context["agentPlan"] = self._agent_plan_from_decision(decision_state)
        self._apply_read_executor_context(context)
        self._apply_write_executor_context(context)
        session_id = str(context.get("sessionId") or "")
        user_turn_id = str(context.get("currentUserTurnId") or "")
        content = str(context.get("latestUserMessage") or context.get("effectiveUserMessage") or "")
        session = self._session(session_id)
        user_turn = self._turn_response(user_turn_id)
        return context, decision_state, session_id, user_turn_id, content, session, user_turn

    def _executor_response_outcome(
        self,
        request: AgentActionExecutionRequest,
        response: Optional[AgentMessageResponse],
        *,
        execution_route: str,
    ) -> AgentActionOutcome:
        action = str(request.decision_state.get("primaryAction") or "")
        if response is None:
            return AgentActionOutcome(
                action=action or "finish",
                execution_route=execution_route,
                status="failed",
                base_version_id=str(
                    self._session(str(request.request_context.get("sessionId") or ""))["active_version_id"] or ""
                )
                or None,
                candidate_summary={"failureReason": "accepted_action_executor_returned_no_result"},
                safe_to_continue=False,
            )
        return self._coordinator_outcome_from_response(action, response, execution_route=execution_route)

    def _prepare_failed_component_repair(
        self,
        *,
        session_id: str,
        retry_execution_plan: dict[str, Any],
    ) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
        """Repair one persisted meal blocker in memory, then offer it only."""
        scope = (
            retry_execution_plan.get("preconditions")
            if isinstance(retry_execution_plan.get("preconditions"), dict)
            else {}
        )
        source_assistant_turn_id = str(scope.get("sourceAssistantTurnId") or "")
        telemetry: dict[str, Any] = {
            "status": "rejected",
            "failureCode": str(scope.get("failureCode") or ""),
            "portfolioId": str(scope.get("portfolioId") or ""),
            "proposalId": str(scope.get("proposalId") or ""),
            "briefId": str(scope.get("briefId") or ""),
            "poolId": str(scope.get("poolId") or ""),
            "planningSlotId": str(scope.get("planningSlotId") or ""),
            "dayNumber": int(scope.get("dayNumber") or 0),
            "segmentId": str(scope.get("segmentId") or ""),
            "amapId": str(scope.get("amapId") or ""),
            "controllerFullCallCount": 0,
            "controllerLiteCallCount": 0,
            "stagedPipelineCallCount": 0,
            "versionDelta": 0,
            "patchDelta": 0,
            "routeWriteDelta": 0,
        }

        def reject(reason: str) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
            telemetry["reason"] = reason
            return (
                [],
                "已保留上次方案，但无法安全定位或替换偏绕午餐；请指定该天午餐，或明确要求整套从头重新生成。",
                telemetry,
            )

        if not source_assistant_turn_id:
            return reject("repair_source_assistant_turn_missing")
        row = self.db.execute(
            """SELECT agent_response_json FROM conversation_turns
            WHERE id = ? AND session_id = ? AND role = 'assistant'
              AND status = 'active'""",
            (source_assistant_turn_id, session_id),
        ).fetchone()
        if row is None:
            return reject("repair_source_assistant_turn_not_found")
        try:
            source_payload = json.loads(row["agent_response_json"] or "{}")
        except (TypeError, ValueError):
            return reject("repair_source_payload_invalid")
        recovery = (
            source_payload.get("failedComponentRecoveryState")
            if isinstance(source_payload.get("failedComponentRecoveryState"), dict)
            else {}
        )
        checkpoint = (
            source_payload.get("failedComponentCheckpoint")
            if isinstance(source_payload.get("failedComponentCheckpoint"), dict)
            else {}
        )
        exact_keys = (
            "failureCode",
            "portfolioId",
            "proposalId",
            "briefId",
            "poolId",
            "planningSlotId",
            "dayNumber",
            "segmentId",
            "amapId",
            "sourceUserTurnId",
            "requestContractFingerprint",
            "repairScopeCertificateFingerprint",
        )
        if any(str(checkpoint.get(key) or "") != str(scope.get(key) or "") for key in exact_keys):
            return reject("repair_checkpoint_identity_mismatch")
        snapshot = (
            copy.deepcopy(recovery.get("proposalSnapshot"))
            if isinstance(recovery.get("proposalSnapshot"), dict)
            else {}
        )
        try:
            brief = CreativeBrief.model_validate(recovery.get("brief"))
            ledger = ConstraintLedger.model_validate(source_payload.get("constraintLedger"))
        except (TypeError, ValueError):
            return reject("repair_contract_invalid")
        if (
            str(recovery.get("portfolioId") or "") != str(scope.get("portfolioId") or "")
            or str(recovery.get("proposalId") or "") != str(scope.get("proposalId") or "")
            or brief.brief_id != str(scope.get("briefId") or "")
            or ledger.source_fingerprint != str(scope.get("requestContractFingerprint") or "")
        ):
            return reject("repair_recovery_state_identity_mismatch")
        portfolio_row = self.db.execute(
            """SELECT expected_base_version_id, request_contract_fingerprint,
                source_user_turn_id, status
            FROM agent_plan_portfolios WHERE id = ? AND session_id = ?""",
            (str(scope.get("portfolioId") or ""), session_id),
        ).fetchone()
        if portfolio_row is None:
            return reject("repair_portfolio_missing")
        if str(portfolio_row["status"] or "") not in {
            "awaiting_selection",
            "failed",
        }:
            return reject("repair_portfolio_not_repairable")
        active_version_id = str(self._session(session_id)["active_version_id"] or "")
        if (
            str(portfolio_row["expected_base_version_id"] or "") != active_version_id
            or str(portfolio_row["request_contract_fingerprint"] or "") != ledger.source_fingerprint
            or str(portfolio_row["source_user_turn_id"] or "") != str(checkpoint.get("sourceUserTurnId") or "")
        ):
            return reject("repair_portfolio_stale")
        target_segment = next(
            (
                segment
                for day in snapshot.get("days") or []
                if isinstance(day, dict)
                for segment in day.get("segments") or []
                if isinstance(segment, dict) and str(segment.get("id") or "") == str(scope.get("segmentId") or "")
            ),
            None,
        )
        target_semantic = (
            target_segment.get("semanticMetadata")
            if isinstance(target_segment, dict) and isinstance(target_segment.get("semanticMetadata"), dict)
            else {}
        )
        target_poi = (
            target_segment.get("poi")
            if isinstance(target_segment, dict) and isinstance(target_segment.get("poi"), dict)
            else {}
        )
        if (
            not isinstance(target_segment, dict)
            or str(target_semantic.get("creativeBriefId") or "") != str(scope.get("briefId") or "")
            or str(target_semantic.get("poolId") or "") != str(scope.get("poolId") or "")
            or str(target_semantic.get("planningSlotId") or "") != str(scope.get("planningSlotId") or "")
            or str(target_poi.get("amapId") or target_poi.get("id") or "") != str(scope.get("amapId") or "")
        ):
            return reject("repair_target_segment_identity_mismatch")
        transport_mode = self._route_repair_transport_mode_from_snapshot(snapshot)
        if not transport_mode:
            return reject("repair_snapshot_transport_mode_missing")
        repair_scope_certificate = self._validated_route_repair_scope_certificate(
            checkpoint,
            source_user_turn_id=str(portfolio_row["source_user_turn_id"] or ""),
            source_assistant_turn_id=source_assistant_turn_id,
            portfolio_id=str(scope.get("portfolioId") or ""),
            request_contract_fingerprint=str(ledger.source_fingerprint or ""),
            expected_base_version_id=(str(portfolio_row["expected_base_version_id"] or "") or None),
            brief_id=brief.brief_id,
            pool_id=str(target_semantic.get("poolId") or ""),
            planning_slot_id=str(target_semantic.get("planningSlotId") or ""),
            day_number=int(scope.get("dayNumber") or 0),
            target_poi=target_poi,
            snapshot=snapshot,
            transport_mode=transport_mode,
            route_feasibility_service=self.portfolio_route_feasibility_service,
        )
        if repair_scope_certificate is None:
            return reject("repair_scope_certificate_missing_or_invalid")
        if str(
            repair_scope_certificate.get("terminalStatus") or ""
        ) == "no_progress" or self._route_repair_scope_is_no_progress(snapshot, repair_scope_certificate):
            return reject("repair_no_progress_previous_scope_evidence")
        telemetry["repairScopeFingerprint"] = str(repair_scope_certificate.get("scopeFingerprint") or "")
        telemetry["repairScopeCertificateFingerprint"] = str(
            repair_scope_certificate.get("certificateFingerprint") or ""
        )
        if self._route_repair_scope_already_offered(
            portfolio_id=str(scope.get("portfolioId") or ""),
            certificate_fingerprint=str(repair_scope_certificate.get("certificateFingerprint") or ""),
        ):
            return reject("repair_no_progress_scope_already_offered")
        # An exact route-component retry still has to obtain a complete
        # Provider matrix.  Reuse the bounded preflight envelope rather than
        # inventing a smaller retry budget that cannot cover the two baseline
        # and two replacement-adjacent legs of an interior slot.
        repair_budget = AmapCallBudget.for_creative_portfolio_route_preflight()
        with amap_call_budget_scope(repair_budget):
            route_result = self.portfolio_route_feasibility_service.prepare(
                snapshot,
                candidate_pools=[],
                city=ledger.city,
                transport_mode=transport_mode,
                allow_nearby_search=True,
                allow_web_discovery=True,
                preview_id=(f"retry_repair_{str(repair_scope_certificate.get('scopeFingerprint') or '')[:24]}"),
            )
        telemetry.update(
            {
                "routePreflightStatus": route_result.status,
                "routeProviderState": route_result.provider_state,
                "candidateRepairs": copy.deepcopy(route_result.candidate_repairs),
                "routeQualityIssues": copy.deepcopy(route_result.route_quality_issues),
                "amapCallBudget": repair_budget.snapshot(),
            }
        )
        if not route_result.passed:
            terminal_no_progress = bool(
                route_result.provider_state == "no_progress"
                or self._route_repair_scope_is_no_progress(
                    route_result.snapshot,
                    repair_scope_certificate,
                )
            )
            telemetry["repairTerminalReason"] = str(
                (route_result.repair_attempt_ledger or {}).get("terminalReason") or ""
            )
            route_repair_handoff = self._route_repair_reissue_handoff(
                checkpoint=checkpoint,
                recovery=recovery,
                latest_snapshot=route_result.snapshot,
                certificate=repair_scope_certificate,
                terminal_no_progress=terminal_no_progress,
            )
            route_repair_handoff["constraintLedger"] = ledger.model_dump(by_alias=True)
            telemetry["_routeRepairHandoff"] = route_repair_handoff
            return reject(
                "repair_no_progress_same_scope" if terminal_no_progress else "repair_no_safe_grounded_candidate"
            )
        store = PlanPortfolioStore(self.db)
        staging = CreativePortfolioStagingService(
            store,
            route_feasibility_service=self.portfolio_route_feasibility_service,
            experience_grounding_v2_mode=self.experience_grounding_v2_mode,
            soft_slot_draft_adoption_enabled=self.soft_slot_draft_adoption_enabled,
            creative_output_quality_v2_mode=self.creative_output_quality_v2_mode,
        )
        verifier = staging.verifier.verify(route_result.snapshot, ledger, brief)
        repaired_proposal_id = f"proposal_repair_{uuid4().hex[:12]}"
        repaired_portfolio_id = str(scope.get("portfolioId") or "")
        verified_snapshot = copy.deepcopy(route_result.snapshot)
        verified_snapshot["portfolioVerifier"] = copy.deepcopy(verifier)
        titled_snapshot = self._with_verified_proposal_title(
            verified_snapshot,
            brief=brief,
            store=store,
            portfolio_id=repaired_portfolio_id,
            proposal_id=repaired_proposal_id,
        )
        readiness = ProposalReadinessService.compute(titled_snapshot, verifier=verifier)
        if not self._repaired_proposal_offer_allowed(readiness, verifier):
            telemetry["proposalVerifier"] = verifier
            return reject("repair_proposal_verifier_failed")
        score = staging.scorer.score(
            snapshot=titled_snapshot,
            ledger=ledger,
            brief=brief,
            verifier=verifier,
        )
        repaired_brief = brief.model_copy(update={"title": str(titled_snapshot.get("title") or brief.title)})
        proposal = PlanCandidate(
            proposalId=repaired_proposal_id,
            portfolioId=repaired_portfolio_id,
            brief=repaired_brief,
            itinerarySnapshot=titled_snapshot,
            score=score,
            verifier=verifier,
            canonicalSignature=canonical_fingerprint(route_result.snapshot),
            generationLineage={
                "repairType": "meal_detour_exact_component",
                "sourceProposalId": str(scope.get("proposalId") or ""),
                "sourceAssistantTurnId": source_assistant_turn_id,
                "failureCode": str(scope.get("failureCode") or ""),
                "targetSegmentId": str(scope.get("segmentId") or ""),
                "repairScopeCertificateFingerprint": str(repair_scope_certificate.get("certificateFingerprint") or ""),
                "externalDiscoveryAllowed": True,
                "itineraryWriteCount": 0,
            },
        )
        try:
            choice_id, proposal_id, inserted = store.offer_repaired_proposal(
                portfolio_id=proposal.portfolio_id,
                proposal=proposal,
            )
        except ValueError as error:
            return reject(str(error))
        if not inserted:
            return reject("repair_no_progress_duplicate_verified_proposal")
        telemetry.update(
            {
                "status": "offered",
                "reason": "repair_proposal_verified",
                "repairedProposalId": proposal_id,
                "offeredProposalDelta": 1 if inserted else 0,
                "proposalVerifierPassed": bool(verifier.get("passed")),
                "draftVerifierPassed": bool(verifier.get("draftPassed")),
                "adoptionMode": readiness.get("adoptionMode"),
                "mealDetourHighCount": 0,
                "timelineWriteBeforeExplicitSelection": 0,
            }
        )
        choice = {
            "id": choice_id,
            "choiceId": choice_id,
            "action": "select_plan_proposal",
            "kind": "plan_proposal",
            "label": f"使用已修复方案：{proposal.brief.title}",
            "description": "偏绕午餐已通过真实路线预检；点击后才提交正式时间轴。",
            "sourceUserTurnId": str(portfolio_row["source_user_turn_id"] or ""),
            "expectedBaseVersionId": str(portfolio_row["expected_base_version_id"] or "") or None,
            "summary": {
                "checkpointReused": True,
                "repairType": "meal_detour_exact_component",
            },
        }
        return (
            [choice],
            "偏绕午餐已定向替换并重新通过路线与方案校验；请确认该修复方案后再创建正式时间轴。",
            telemetry,
        )

    def _execute_ask_user_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        context, decision_state, session_id, _user_turn_id, content, session, user_turn = (
            self._coordinator_executor_inputs(request)
        )
        clarification = self._controller_clarification_payload(decision_state) or {}
        reply = str(
            clarification.get("question")
            or decision_state.get("userVisibleReason")
            or "需要你补充或确认后才能继续，当前行程未修改。"
        ).strip()
        retry_execution_plan = (
            context.get("retryExecutionPlan") if isinstance(context.get("retryExecutionPlan"), dict) else {}
        )
        failed_component_repair: dict[str, Any] = {}
        route_repair_handoff: dict[str, Any] = {}
        if retry_execution_plan.get("kind") == "repair_last_failure":
            (
                repair_choices,
                repair_reply,
                failed_component_repair,
            ) = self._prepare_failed_component_repair(
                session_id=session_id,
                retry_execution_plan=retry_execution_plan,
            )
            route_repair_handoff = (
                failed_component_repair.pop("_routeRepairHandoff", {})
                if isinstance(failed_component_repair, dict)
                else {}
            )
            retry_execution_plan = {
                **retry_execution_plan,
                "choiceOptions": repair_choices,
            }
            context["retryExecutionPlan"] = retry_execution_plan
            reply = repair_reply
        retry_choice_options = [
            dict(item)
            for item in retry_execution_plan.get("choiceOptions") or []
            if isinstance(item, dict) and str(item.get("id") or "")
        ]
        date_contract_clarification = bool(
            decision_state.get("primaryAction") == "ask_user"
            and "date_contract_clarification_required"
            in {str(item) for item in decision_state.get("reasonCodes") or [] if str(item)}
        )
        date_contract_choice_options = (
            [
                {
                    "id": str(option.get("id") or f"date-contract:{_user_turn_id}:{index}"),
                    "index": index,
                    "label": str(option.get("label") or "补充明确日期"),
                    "kind": "safe_fallback_action",
                    "action": str(option.get("action") or "manual_continuation"),
                    "sourceUserTurnId": str(context.get("currentUserTurnId") or _user_turn_id),
                    "allowsManualInput": bool(option.get("allowsManualInput", True)),
                }
                for index, option in enumerate(clarification.get("options") or [], start=1)
                if isinstance(option, dict)
                and str(option.get("action") or "manual_continuation") == "manual_continuation"
            ]
            if date_contract_clarification
            else []
        )
        non_controller_choice_options = (
            retry_choice_options
            or date_contract_choice_options
            or self._planning_material_tradeoff_choice_options(
                session_id,
                context,
                str(context.get("currentUserTurnId") or ""),
            )
        )
        request_contract = (
            context.get("requestIntentContract") if isinstance(context.get("requestIntentContract"), dict) else {}
        )
        selected_choice = (
            context.get("selectedAgentChoice") if isinstance(context.get("selectedAgentChoice"), dict) else {}
        )
        selected_option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
        fallback_choice_claim = (
            context.get("fallbackChoiceExecutionClaim")
            if isinstance(context.get("fallbackChoiceExecutionClaim"), dict)
            else {}
        )
        selected_action = str(
            selected_choice.get("action")
            or fallback_choice_claim.get("action")
            or (selected_option.get("action") if isinstance(selected_option, dict) else "")
            or ""
        ).strip()
        canonical_request_context = (
            context.get("canonicalRequestContext") if isinstance(context.get("canonicalRequestContext"), dict) else {}
        )
        authoritative_request_contract = (
            canonical_request_context.get("requestIntentContract")
            if isinstance(canonical_request_context.get("requestIntentContract"), dict)
            else request_contract
        )
        retry_option_identity = self._retry_option_identity(
            context,
            fallback_user_turn_id=str(context.get("currentUserTurnId") or _user_turn_id),
            request_contract=authoritative_request_contract,
        )
        prior_checkpoint = (
            context.get("clarificationCheckpoint") if isinstance(context.get("clarificationCheckpoint"), dict) else None
        )
        # A clarification answer or retry is a continuation of the durable
        # checkpoint, not a new planning root.  The checkpoint service still
        # validates the full lineage/fingerprint below; preferring its root
        # here prevents a fresh user-turn id from invalidating an otherwise
        # valid controller-generated next question.
        clarification_planning_root_id = str(
            (prior_checkpoint or {}).get("planningRootId")
            or context.get("planningSelectionRootTurnId")
            or context.get("currentUserTurnId")
            or _user_turn_id
        )
        created_checkpoint = (
            ClarificationCheckpointService.create(
                planning_root_id=clarification_planning_root_id,
                request_contract=request_contract,
                controller_question=clarification,
                source_user_turn_id=str(context.get("currentUserTurnId") or _user_turn_id),
                prior_checkpoint=prior_checkpoint,
                candidate_gap_summary=(
                    context.get("candidateGapSummary") if isinstance(context.get("candidateGapSummary"), dict) else None
                ),
            )
            if not non_controller_choice_options
            and "request_activity_coverage_incomplete" not in (decision_state.get("reasonCodes") or [])
            else None
        )
        checkpoint = created_checkpoint or copy.deepcopy(prior_checkpoint)
        clarification_contract_pending = bool(
            self._unresolved_request_contract_clarification_dimensions(authoritative_request_contract)
        )
        clarification_is_complete = not clarification_contract_pending
        route_policy_retry_required = bool(
            str(decision_state.get("source") or "") == "safe_fallback"
            and "route_clarification_controller_retry_required"
            in {str(item) for item in decision_state.get("reasonCodes") or [] if str(item)}
        )
        choice_options = non_controller_choice_options
        visible_failure_code: Optional[str] = None
        terminal_status = "needs_confirmation"
        if "request_activity_coverage_incomplete" in (decision_state.get("reasonCodes") or []):
            controller_unavailable = "controller_provider_unavailable" in str(decision_state.get("controllerError") or "")
            visible_failure_code = "controller_action_unavailable" if controller_unavailable else "request_activity_coverage_incomplete"
            reply = (
                "规划控制器当前不可用；尚未完成原始需求的活动覆盖校验，没有检索地点或修改行程。"
                if controller_unavailable else str(decision_state.get("userVisibleReason") or "")
            )
            checkpoint = None
            choice_options = []
        elif created_checkpoint is not None:
            reply, choice_options = self._clarification_choice_material(
                created_checkpoint,
                source_user_turn_id=str(context.get("currentUserTurnId") or _user_turn_id),
            )
        elif not choice_options and route_policy_retry_required:
            # This is a server-owned zero-write recovery path, not a rejected
            # Controller-authored clarification question. Preserve that
            # distinction so a route-policy producer failure is never shown as
            # "澄清问题未通过合同" and the user retains both bounded recovery
            # actions emitted by the safe fallback.
            reply = str(
                clarification.get("question")
                or decision_state.get("userVisibleReason")
                or "规划控制器未能把当前路线约束转换为可验证策略；当前没有创建或修改行程。"
            ).strip()
            route_recovery_actions = {"retry_model_planning", "manual_continuation"}
            choice_options = [
                {
                    "id": str(option.get("id") or f"controller-route-retry:{_user_turn_id}:{index}"),
                    "index": index,
                    "label": str(option.get("label") or "重试生成路线策略"),
                    "kind": "safe_fallback_action",
                    "action": str(option.get("action") or "retry_model_planning"),
                    "sourceUserTurnId": str(context.get("currentUserTurnId") or _user_turn_id),
                    "allowsManualInput": bool(option.get("allowsManualInput")),
                }
                for index, option in enumerate(clarification.get("options") or [], start=1)
                if isinstance(option, dict) and str(option.get("action") or "") in route_recovery_actions
            ]
            if not choice_options:
                choice_options = [
                    {
                        "id": f"controller-route-retry:{context.get('currentUserTurnId') or _user_turn_id}",
                        "index": 1,
                        "label": "重试生成路线策略",
                        "kind": "safe_fallback_action",
                        "action": "retry_model_planning",
                        "sourceUserTurnId": str(context.get("currentUserTurnId") or _user_turn_id),
                        "allowsManualInput": False,
                    }
                ]
        elif (
            not choice_options
            and decision_state.get("controllerFullCalled") is False
            and "server_authoritative_conversation_intent" in (decision_state.get("reasonCodes") or [])
        ):
            # The entry already supplied a server-owned clarification.  An
            # empty choice list is valid here; it is not a malformed Full
            # Controller clarification and must not be rewritten as one.
            routed_intent = context.get("conversationIntent") or {}
            visible_failure_code = str(routed_intent.get("reasonCode") or "intent_requires_clarification")
        elif not choice_options:
            routed_intent = (
                context.get("conversationIntent")
                if isinstance(context.get("conversationIntent"), dict)
                else {}
            )
            intent_route_not_bound = bool(
                str(routed_intent.get("reasonCode") or "") == "intent_confidence_below_threshold"
                and decision_state.get("controllerFullCalled") is not True
            )
            controller_failure_class = str(decision_state.get("controllerFailureClass") or "").strip()
            controller_error = str(decision_state.get("controllerError") or "")
            repair_action_unresolved = "controller_repair_action_unresolved" in controller_error
            controller_error_folded = controller_error.casefold()
            if "route" in controller_error_folded and "budget" in controller_error_folded:
                visible_failure_code = "provider_route_budget_exhausted"
            elif "route" in controller_error_folded and any(
                token in controller_error_folded for token in ("evidence", "matrix", "coverage", "incomplete")
            ):
                visible_failure_code = "route_evidence_incomplete"
            elif any(
                token in controller_error_folded
                for token in ("validation", "schema", "normalization", "contract", "requiredgoalcounts")
            ):
                visible_failure_code = (
                    "controller_contract_invalid" if clarification_is_complete else "controller_clarification_invalid"
                )
            else:
                visible_failure_code = "controller_action_unavailable"
            if intent_route_not_bound:
                visible_failure_code = "intent_route_not_bound"
                reply = (
                    "尚未调用规划控制器：本轮会话意图没有安全绑定到可执行能力；"
                    "当前没有修改行程，请补充需求或使用最新回复中的操作。"
                )
            elif repair_action_unresolved:
                reply = "规划控制器本轮未形成符合当前安全约束的可执行动作；当前没有修改行程，请重试本轮。"
            elif controller_failure_class in {"timeout", "provider_timeout", "request_timeout"}:
                reply = "规划控制器本轮超时；当前没有修改行程，请重试生成行程。"
            elif controller_failure_class == "provider_unavailable":
                reply = (
                    "规划控制器当前不可用；已保留已确认需求，当前没有修改行程，请在服务恢复或配置就绪后重试生成行程。"
                )
            elif visible_failure_code == "controller_contract_invalid":
                reply = "规划控制器返回的行程草案不符合严格数据合同（controller_contract_invalid）；当前没有修改行程，请重试生成行程。"
            elif visible_failure_code == "provider_route_budget_exhausted":
                reply = "真实路线核验已用完本轮有界预算（provider_route_budget_exhausted）；当前没有修改行程。"
            elif visible_failure_code == "route_evidence_incomplete":
                reply = "地点草案已形成，但真实相邻路线证据不完整（route_evidence_incomplete）；当前没有修改行程。"
            elif visible_failure_code == "controller_clarification_invalid":
                reply = "规划控制器给出的澄清问题未通过当前需求合同校验；当前没有修改行程，请重试本轮。"
            else:
                reply = (
                    "已保留当前需求，但规划控制器本轮未形成可执行规划；当前没有修改行程，请重试生成行程。"
                    if clarification_is_complete
                    else "规划控制器给出的澄清问题未通过当前需求合同校验；当前没有修改行程，请重试本轮。"
                )
            repeated_retry_no_progress = bool(
                selected_action == "retry_model_planning"
                and int(retry_option_identity.get("attempt") or 1) > 1
                and clarification_is_complete
                and visible_failure_code in {"controller_contract_invalid", "controller_action_unavailable"}
            )
            if repeated_retry_no_progress:
                reply = (
                    "已按相同已确认需求重试一次，仍未形成可执行规划；当前没有修改行程。"
                    "如需继续，请调整需求后重新发起规划。"
                )
                choice_options = []
                visible_failure_code = "controller_no_progress"
                terminal_status = "no_safe_action"
            else:
                choice_options = [
                    {
                        "id": f"controller-retry:{context.get('currentUserTurnId') or _user_turn_id}",
                        "index": 1,
                        "label": (
                            "重试生成行程"
                            if repair_action_unresolved
                            or controller_failure_class
                            in {"timeout", "provider_timeout", "request_timeout", "provider_unavailable"}
                            or clarification_is_complete
                            else "重试生成澄清问题"
                        ),
                        "kind": "safe_fallback_action",
                        "action": "retry_model_planning",
                        "sourceUserTurnId": retry_option_identity["sourceUserTurnId"],
                        "planningSelectionRootTurnId": retry_option_identity["planningSelectionRootTurnId"],
                        "requestContractFingerprint": retry_option_identity["requestContractFingerprint"],
                        "attempt": retry_option_identity["attempt"],
                        "allowsManualInput": False,
                    }
                ]
        response_payload = {
            "mode": "clarification",
            "reply": reply,
            "choiceOptions": choice_options,
            "clarificationCheckpoint": checkpoint,
            "experienceSpecs": copy.deepcopy(
                (checkpoint or {}).get("experienceSpecs") or context.get("experienceSpecs") or []
            ),
            "candidateGapSummary": copy.deepcopy(
                (checkpoint or {}).get("candidateGapSummary") or context.get("candidateGapSummary") or {}
            ),
            "terminalStatus": terminal_status,
            "failureReasonCode": visible_failure_code,
            "retryIntent": context.get("retryIntent"),
            "retryExecutionPlan": retry_execution_plan or None,
            "failedComponentRepair": failed_component_repair or None,
            "failedComponentCheckpoint": (
                copy.deepcopy(route_repair_handoff.get("checkpoint"))
                if isinstance(route_repair_handoff.get("checkpoint"), dict)
                else None
            ),
            "failedComponentRecoveryState": (
                copy.deepcopy(route_repair_handoff.get("recovery"))
                if isinstance(route_repair_handoff.get("recovery"), dict)
                else None
            ),
            "constraintLedger": (
                copy.deepcopy(route_repair_handoff.get("constraintLedger"))
                if isinstance(route_repair_handoff.get("constraintLedger"), dict)
                else None
            ),
            "controllerFullCallCount": 0
            if retry_execution_plan and not retry_execution_plan.get("controllerAllowed")
            else None,
            "controllerLiteCallCount": 0
            if retry_execution_plan and not retry_execution_plan.get("controllerAllowed")
            else None,
            "stagedPipelineCallCount": 0
            if retry_execution_plan and not retry_execution_plan.get("controllerAllowed")
            else None,
            "newPortfolioDelta": 0
            if retry_execution_plan and not retry_execution_plan.get("controllerAllowed")
            else None,
            "newProposalDelta": int(failed_component_repair.get("offeredProposalDelta") or 0),
            "amapPlaceCallDelta": 0
            if retry_execution_plan.get("kind") in {"resume_portfolio", "continue_partial_slot", "ask_retry_scope"}
            else None,
            "amapRouteCallDelta": 0
            if retry_execution_plan.get("kind") in {"resume_portfolio", "continue_partial_slot", "ask_retry_scope"}
            else None,
            "webSearchCallDelta": 0
            if retry_execution_plan.get("kind") in {"resume_portfolio", "continue_partial_slot", "ask_retry_scope"}
            else None,
            "versionDelta": 0,
            "patchDelta": 0,
            "routeWriteDelta": 0,
        }
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            reply,
            "active",
            agent_request_json=context,
            agent_response_json=response_payload,
        )
        bound_route_repair_handoff = self._bind_route_repair_handoff_to_assistant_turn(
            route_repair_handoff,
            assistant_turn_id,
        )
        if bound_route_repair_handoff is not None:
            response_payload["failedComponentCheckpoint"] = copy.deepcopy(bound_route_repair_handoff["checkpoint"])
            response_payload["failedComponentRecoveryState"] = copy.deepcopy(bound_route_repair_handoff["recovery"])
            response_payload["constraintLedger"] = copy.deepcopy(route_repair_handoff.get("constraintLedger") or {})
        if created_checkpoint is not None:
            self._bind_clarification_checkpoint_identity(
                created_checkpoint,
                choice_options,
                assistant_turn_id,
            )
            response_payload["clarificationCheckpoint"] = created_checkpoint
            response_payload["choiceOptions"] = choice_options
        if created_checkpoint is not None or bound_route_repair_handoff is not None:
            self.db.execute(
                "UPDATE conversation_turns SET agent_response_json = ?, updated_at = ? WHERE id = ?",
                (
                    json.dumps(response_payload, ensure_ascii=False, default=str),
                    datetime.now(timezone.utc).isoformat(),
                    assistant_turn_id,
                ),
            )
        planning_run = PlanningRunService(self.db).create_run(
            "agent_clarification",
            user_input=content,
            preference_summary=self._preference_summary_from_context(context),
            itinerary=(
                ItineraryService(self.db).get_plan(session["active_plan_id"]) if session["active_version_id"] else None
            ),
            itinerary_version_id=session["active_version_id"],
            understood_requirements=context.get("understoodRequirements"),
            final_summary=reply,
        )
        verifier_report = self._safe_verify_active_version_unchanged(session, "agent_clarification")
        if decision_state.get("controllerError") and len(choice_options) == 3:
            clarification_events = self._fallback_confirmation_events(
                session_id, assistant_turn_id, context, verifier_report
            )
        else:
            clarification_events = [
                AgentPlanningEventResponse(
                    type="active_version_unchanged",
                    label="确认 active version 未变化",
                    status="completed",
                    detail="澄清动作未创建 patch 或 itinerary version。",
                    sessionId=session_id,
                    turnId=assistant_turn_id,
                    providerName="ask-user-executor",
                    category="internal",
                    metadata={"versionChanged": False, "verifier": verifier_report.as_metadata()},
                    timestamp=datetime.now(timezone.utc).isoformat(),
                )
            ]
        self.db.commit()
        prior_response = context.get("_coordinatorPriorResponse")
        current_turn_version = (
            prior_response.version
            if isinstance(prior_response, AgentMessageResponse)
            and prior_response.version is not None
            and prior_response.version.id == str(session["active_version_id"] or "")
            else None
        )
        response = self._message_response(
            user_turn,
            self._turn_response(assistant_turn_id),
            session,
            current_turn_version,
            [],
            planning_run,
            verifier_report,
            planning_events_override=clarification_events,
        )
        response = response.model_copy(update={"terminal_status": terminal_status})
        outcome = self._coordinator_outcome_from_response("ask_user", response, execution_route="clarification")
        outcome_status = "completed" if terminal_status == "no_safe_action" else "needs_confirmation"
        return AgentActionOutcome(
            **{
                **outcome.__dict__,
                "status": outcome_status,
                "base_version_id": None,
                "result_version_id": None,
                "observed_active_version_id": str(session["active_version_id"] or "") or None,
                "patch_ids": [],
                "changed_segment_ids": [],
                "candidate_summary": {**outcome.candidate_summary, "choiceOptions": choice_options},
                "verifier": {
                    "passed": None,
                    "notApplicable": True,
                    "reason": "no_itinerary_write",
                },
                "rollback_performed": False,
                "goal_delta": {},
                "recommended_next_actions": [],
                "safe_to_continue": False,
            }
        )

    def _execute_finish_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        context, decision_state, session_id, _user_turn_id, content, session, user_turn = (
            self._coordinator_executor_inputs(request)
        )
        prior_response = context.get("_coordinatorPriorResponse")
        if isinstance(prior_response, AgentMessageResponse):
            current_session = self._session(session_id)
            prior_terminal_status = str(prior_response.terminal_status or "")
            previous_outcome = (
                context.get("coordinatorLastOutcome") if isinstance(context.get("coordinatorLastOutcome"), dict) else {}
            )
            previous_verifier = (
                previous_outcome.get("verifier") if isinstance(previous_outcome.get("verifier"), dict) else {}
            )
            verifier_report = self._safe_verify_active_version_unchanged(
                current_session, "agent_finish_persisted_snapshot_unchanged"
            )
            if previous_verifier.get("passed") is False:
                verifier_report = AgentVerifierReport(
                    passed=False,
                    hard_failures=["previous_action_verifier_failed"],
                    checks=[{"name": "previous_action_verifier", "status": "failed"}],
                    metadata={"sessionId": session_id, "reason": "finish_requires_verified_prior_outcome"},
                )
            reply = self._finish_reply_from_persisted_snapshot(
                current_session,
                context,
                verifier_passed=verifier_report.passed,
                prior_reply=prior_response.assistant_turn.content,
            )
            terminal_status = (
                prior_terminal_status
                if verifier_report.passed
                and prior_terminal_status
                in {
                    "draft_pending_grounding",
                    "needs_confirmation",
                    "no_safe_action",
                    "no_change",
                    "partial_success",
                }
                else "success"
                if verifier_report.passed
                else "failed"
            )
            assistant_payload_row = self.db.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                (prior_response.assistant_turn.id,),
            ).fetchone()
            assistant_payload = (
                self._json_dict(assistant_payload_row["agent_response_json"])
                if assistant_payload_row is not None
                else {}
            )
            assistant_payload.update(
                {
                    "reply": reply,
                    "terminalStatus": terminal_status,
                    "finishSnapshotVerifier": verifier_report.as_metadata(),
                }
            )
            self.db.execute(
                "UPDATE conversation_turns SET content = ?, status = ?, agent_response_json = ?, updated_at = ? WHERE id = ?",
                (
                    reply,
                    "active" if verifier_report.passed else "failed",
                    json.dumps(assistant_payload, ensure_ascii=False, default=str),
                    datetime.now(timezone.utc).isoformat(),
                    prior_response.assistant_turn.id,
                ),
            )
            self.db.commit()
            refreshed_response = prior_response.model_copy(
                update={
                    "assistant_turn": self._turn_response(prior_response.assistant_turn.id),
                    "terminal_status": terminal_status,
                }
            )
            return AgentActionOutcome(
                action="finish",
                execution_route="terminal_response",
                status="success" if verifier_report.passed else "failed",
                base_version_id=None,
                result_version_id=None,
                observed_active_version_id=str(current_session["active_version_id"] or "") or None,
                patch_ids=[],
                changed_segment_ids=[],
                candidate_summary={"terminalStatus": terminal_status},
                verifier={
                    "passed": None,
                    "notApplicable": True,
                    "reason": "no_itinerary_write",
                },
                rollback_performed=False,
                safe_to_continue=False,
                terminal_payload=refreshed_response,
            )
        response = self._execute_finish_action(session_id, user_turn, session, content, context, decision_state)
        outcome = self._coordinator_outcome_from_response("finish", response, execution_route="terminal_response")
        current_session = self._session(session_id)
        return AgentActionOutcome(
            **{
                **outcome.__dict__,
                "base_version_id": None,
                "result_version_id": None,
                "observed_active_version_id": str(current_session["active_version_id"] or "") or None,
                "patch_ids": [],
                "changed_segment_ids": [],
                "verifier": {
                    "passed": None,
                    "notApplicable": True,
                    "reason": "no_itinerary_write",
                },
                "rollback_performed": False,
                "goal_delta": {},
                "safe_to_continue": False,
            }
        )

    def _simple_open_persistable_segment_plans(
        self,
        initial_plan: AgentInitialPlanOutput,
        *,
        city: str,
        transport_mode: str,
        tool_events: list[dict[str, Any]],
        pipeline_context: dict[str, Any],
        session_id: Optional[str] = None,
    ) -> list[PersistableSegmentPlan]:
        slot_lineage = self._simple_open_slot_occurrence_lineage(initial_plan, pipeline_context)
        formal_plan = (
            pipeline_context.get("simpleOpenGoalOccurrencePlan")
            if isinstance(pipeline_context.get("simpleOpenGoalOccurrencePlan"), dict)
            else {}
        )
        authoritative_lineage_required = bool(
            formal_plan.get("schemaVersion") == "goal-occurrence-plan-v1"
            or pipeline_context.get("simpleOpenSupplementalOccurrences")
        )
        prior_direction_aliases = self._simple_open_prior_direction_physical_aliases(
            session_id=session_id,
            pipeline_context=pipeline_context,
        )
        prior_required_candidates = self._simple_open_prior_direction_required_candidates(
            session_id=session_id,
            pipeline_context=pipeline_context,
        )
        request_contract = (
            pipeline_context.get("requestIntentContract")
            if isinstance(pipeline_context.get("requestIntentContract"), dict)
            else {}
        )
        required_goals = {
            str(item.get("intentType") or "").strip(): item
            for item in request_contract.get("requiredIntents") or []
            if isinstance(item, dict) and str(item.get("intentType") or "").strip()
        }
        experience_policies_by_intent: dict[str, dict[str, Any]] = {}
        for raw_spec in request_contract.get("experienceSpecs") or []:
            if not isinstance(raw_spec, dict):
                continue
            intent_type = str(raw_spec.get("intentType") or "").strip()
            if not intent_type or intent_type in experience_policies_by_intent:
                continue
            policy = self._experience_spec_policy_for_intent(
                request_contract,
                intent_type,
                required_goals.get(intent_type),
            )
            if policy:
                experience_policies_by_intent[intent_type] = policy
        frontier_assignment = (
            copy.deepcopy(pipeline_context.get("simpleDirectionFrontierAssignment"))
            if isinstance(pipeline_context.get("simpleDirectionFrontierAssignment"), dict)
            else None
        )
        adjacent_scope_claimer = None
        if isinstance(frontier_assignment, dict) and frontier_assignment.get("deferredSlotScopeClaim") is True:
            root_portfolio_id = str(frontier_assignment.get("rootPortfolioId") or "")
            frontier_execution_id = str(frontier_assignment.get("executionId") or "")
            frontier_request_fingerprint = str(frontier_assignment.get("requestContractFingerprint") or "")
            if not all((root_portfolio_id, frontier_execution_id, frontier_request_fingerprint)):
                raise ValueError("simple_direction_current_scope_claim_identity_missing")
            direction_service = SimpleOpenDirectionService(self.db)

            def claim_current_adjacent_scope(scopes: list[dict[str, Any]]) -> dict[str, Any]:
                normalized_scopes = SimpleDirectionFrontierService.normalize_remaining_query_scopes(scopes)
                slot_ids = {str(item.get("slotId") or "") for item in normalized_scopes}
                if len(slot_ids) != 1 or "" in slot_ids:
                    raise ValueError("simple_direction_current_scope_claim_slot_invalid")
                updated_attempt = direction_service.claim_compatibility_current_scopes(
                    portfolio_id=root_portfolio_id,
                    execution_id=frontier_execution_id,
                    request_contract_fingerprint=frontier_request_fingerprint,
                    slot_query_scopes=normalized_scopes,
                )
                slot_id = next(iter(slot_ids))
                slot_queries = (
                    updated_attempt.get("slotQueries") if isinstance(updated_attempt.get("slotQueries"), dict) else {}
                )
                claimed_query = slot_queries.get(slot_id)
                if not isinstance(claimed_query, dict):
                    raise ValueError("simple_direction_current_scope_claim_missing")
                frontier_assignment["slotQueries"] = copy.deepcopy(slot_queries)
                frontier_assignment["slotFrontierSnapshot"] = copy.deepcopy(
                    updated_attempt.get("slotFrontierSnapshot") or {}
                )
                frontier_assignment["remainingQueryScopes"] = copy.deepcopy(
                    updated_attempt.get("remainingQueryScopes") or []
                )
                pipeline_context["simpleDirectionFrontierAssignment"] = copy.deepcopy(frontier_assignment)
                pipeline_context["simpleDirectionCompatibilityAttempt"] = copy.deepcopy(updated_attempt)
                return copy.deepcopy(claimed_query)

            adjacent_scope_claimer = claim_current_adjacent_scope

        plans, events = self.simple_open_itinerary_executor.build_segment_plans(
            initial_plan,
            city=city,
            transport_mode=transport_mode,
            slot_lineage=slot_lineage,
            authoritative_lineage_required=authoritative_lineage_required,
            excluded_physical_aliases=prior_direction_aliases,
            prior_required_candidates_by_occurrence=prior_required_candidates,
            route_decision_contract=(
                request_contract.get("routeDecisionContract") if isinstance(request_contract, dict) else None
            ),
            spatial_preference=(
                request_contract.get("spatialPreference") if isinstance(request_contract, dict) else None
            ),
            experience_policies_by_intent=experience_policies_by_intent,
            route_budget=self.settings.simple_open_route_provider_budget,
            route_plan_id=f"simple-direction:{session_id or 'proposal'}",
            route_gap_supplement_hints=self._simple_open_route_gap_supplement_hints(pipeline_context),
            frontier_assignment=frontier_assignment,
            adjacent_scope_claimer=adjacent_scope_claimer,
            request_contract_fingerprint=str(
                pipeline_context.get("_simpleDirectionRequestContractFingerprint")
                or request_contract.get("requestContractFingerprint")
                or hashlib.sha256(
                    json.dumps(
                        request_contract,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                        default=str,
                    ).encode("utf-8")
                    ).hexdigest()
            ),
            guide_place_hints=(
                copy.deepcopy(pipeline_context["guideContinuationRequirement"].get("placeHints") or [])
                if isinstance(pipeline_context.get("guideContinuationRequirement"), dict)
                else None
            ),
        )
        frontier_event = next(
            (
                event
                for event in reversed(events)
                if isinstance(event, dict) and str(event.get("type") or "") == "simple_direction_frontier_outcomes"
            ),
            None,
        )
        slot_frontier_outcomes: list[dict[str, Any]] = []
        remaining_query_scopes: list[dict[str, Any]] = []
        if isinstance(frontier_event, dict):
            metadata = frontier_event.get("metadata") if isinstance(frontier_event.get("metadata"), dict) else {}
            pipeline_context["simpleDirectionFrontierOutcomes"] = [
                copy.deepcopy(item) for item in metadata.get("outcomes") or [] if isinstance(item, dict)
            ]
            slot_frontier_outcomes = [
                copy.deepcopy(item) for item in metadata.get("slotQueryOutcomes") or [] if isinstance(item, dict)
            ]
            remaining_query_scopes = [
                copy.deepcopy(item) for item in metadata.get("remainingQueryScopes") or [] if isinstance(item, dict)
            ]
            pipeline_context["simpleDirectionRemainingQueryScopes"] = remaining_query_scopes
        frontier_assignment = (
            pipeline_context.get("simpleDirectionFrontierAssignment")
            if isinstance(pipeline_context.get("simpleDirectionFrontierAssignment"), dict)
            else {}
        )
        claimed_slot_queries = frontier_assignment.get("slotQueries")
        if isinstance(claimed_slot_queries, dict):
            exact_outcome_slots = {
                str((item.get("query") or {}).get("slotId") or item.get("slotId") or "")
                for item in slot_frontier_outcomes
                if isinstance(item, dict)
            }
            for slot_id, query in claimed_slot_queries.items():
                slot_identity = str(slot_id or "")
                if not slot_identity or slot_identity in exact_outcome_slots or not isinstance(query, dict):
                    continue
                provider_event = next(
                    (
                        item
                        for item in events
                        if isinstance(item, dict)
                        and str(item.get("type") or "") == "simple_open_tool_call"
                        and isinstance(item.get("metadata"), dict)
                        and str(item["metadata"].get("slotKey") or "") == slot_identity
                        and str(item["metadata"].get("providerOutcome") or "") in {"success", "failure"}
                    ),
                    None,
                )
                if provider_event is None:
                    continue
                event_metadata = provider_event["metadata"]
                selected_amap_id = str(event_metadata.get("selectedAmapId") or "")
                slot_frontier_outcomes.append(
                    {
                        "query": copy.deepcopy(query),
                        "providerOutcome": str(event_metadata.get("providerOutcome") or ""),
                        "admittedPhysicalGroups": [selected_amap_id] if selected_amap_id else [],
                        "rejectedPhysicalGroups": [],
                        "selectedAmapId": selected_amap_id or None,
                        "reasonCode": str(event_metadata.get("errorType") or "") or None,
                    }
                )
        if slot_frontier_outcomes or isinstance(claimed_slot_queries, dict):
            pipeline_context["simpleDirectionSlotFrontierOutcomes"] = slot_frontier_outcomes
        tool_events.extend(events)
        return plans

    def _prepare_simple_open_direction_frontier(
        self,
        *,
        session_id: str,
        user_turn_id: str,
        assistant_turn_id: str,
        city: str,
        active_version_id: Optional[str],
        request_context: dict[str, Any],
        pipeline_context: dict[str, Any],
        initial_plan: AgentInitialPlanOutput,
        resolved_dates: dict[str, Any],
        tool_events: list[dict[str, Any]],
    ) -> None:
        """Freeze and claim the server-side qualification frontier pre-Provider."""

        if isinstance(pipeline_context.get("simpleDirectionFrontierPreparation"), dict):
            expected_proof = ((request_context.get("conversationIntent") or {}).get("semanticAction") or {}).get("sharedSourceBinding")
            if expected_proof is not None:
                from src.services.shared_travel_source_service import SharedTravelSourceService
                root = SimpleOpenDirectionService(self.db).latest_root(session_id=session_id) or {}
                checked = SharedTravelSourceService(self.db).initial_requirement(session_id, user_turn_id, root,
                    expected_proof=expected_proof)
                if checked != pipeline_context.get("guideContinuationRequirement"):
                    raise ValueError("shared_initial_source_binding_invalid")
            return
        request_contract = (
            copy.deepcopy(request_context.get("requestIntentContract"))
            if isinstance(request_context.get("requestIntentContract"), dict)
            else {}
        )
        service = SimpleOpenDirectionService(self.db)
        latest_root = service.latest_root(session_id=session_id)
        conversation_intent = (
            request_context.get("conversationIntent")
            if isinstance(request_context.get("conversationIntent"), dict)
            else {}
        )
        classification = (
            conversation_intent.get("classification")
            if isinstance(conversation_intent.get("classification"), dict)
            else {}
        )
        explicit_new_root = bool(
            str(classification.get("intent") or "") == "regenerate_from_scratch"
            or request_context.get("derivedPlanningRootRequested") is True
        )
        planning_root_id = (
            str(user_turn_id)
            if explicit_new_root
            else str(
                request_context.get("planningSelectionRootTurnId")
                or (latest_root.get("planningRootId") if latest_root is not None else "")
                or user_turn_id
            )
        )
        existing_root = service.root_for_planning_root(
            session_id=session_id,
            planning_root_id=planning_root_id,
        )
        if existing_root is None or explicit_new_root:
            dates = [str(item) for item in resolved_dates.get("dates") or [] if str(item)]
            envelope_contract_fingerprint = ClarificationCheckpointService._fingerprint(request_contract)
            request_contract = {
                **request_contract,
                "planningRequestEnvelope": {
                    "schemaVersion": "planning-request-envelope-v1",
                    "sourcePlanningRootTurnId": planning_root_id,
                    "city": str(pipeline_context.get("city") or pipeline_context.get("destination") or city),
                    "resolvedTripDates": {
                        "status": "resolved",
                        "startDate": str(resolved_dates.get("startDate") or (dates[0] if dates else "")),
                        "endDate": str(resolved_dates.get("endDate") or (dates[-1] if dates else "")),
                        "dates": dates,
                        "source": str(resolved_dates.get("source") or "literal_current_turn"),
                    },
                    "requestContractFingerprint": envelope_contract_fingerprint,
                    **(
                        {"derivedFrom": copy.deepcopy(request_context.get("derivedFrom") or {})}
                        if explicit_new_root
                        else {}
                    ),
                },
            }
        else:
            frozen_contract = existing_root.get("requestIntentContract")
            frozen_material_fingerprint = str(existing_root.get("requestIntentContractMaterialFingerprint") or "")
            if (
                not isinstance(frozen_contract, dict)
                or not frozen_contract
                or not frozen_material_fingerprint
                or ClarificationCheckpointService._fingerprint(frozen_contract) != frozen_material_fingerprint
            ):
                raise ValueError("simple_direction_request_contract_fingerprint_mismatch")
            request_contract = copy.deepcopy(frozen_contract)
        if SimpleOpenDirectionService.route_contract_requires_clarification(request_contract):
            raise RuntimeError("SIMPLE_DIRECTION_ROUTE_CONTRACT_NOT_READY")
        request_fingerprint = (
            str(existing_root.get("requestContractFingerprint") or "")
            if existing_root is not None and not explicit_new_root
            else ClarificationCheckpointService._fingerprint(request_contract)
        )
        observation = (
            request_context.get("agentObservation") if isinstance(request_context.get("agentObservation"), dict) else {}
        )
        observation_fingerprint = str(observation.get("stateFingerprint") or "") or (
            ClarificationCheckpointService._fingerprint(
                {
                    "sessionId": session_id,
                    "planningRootId": planning_root_id,
                    "requestContractFingerprint": request_fingerprint,
                    "activeVersionId": str(active_version_id or ""),
                }
            )
        )
        root = service.ensure_root(
            session_id=session_id,
            planning_root_id=planning_root_id,
            source_assistant_turn_id=assistant_turn_id,
            expected_base_version_id=active_version_id,
            source_observation_fingerprint=observation_fingerprint,
            request_contract_fingerprint=request_fingerprint,
            request_contract=request_contract,
            locality=str(pipeline_context.get("city") or pipeline_context.get("destination") or city),
            max_pages_per_query=self.settings.simple_open_max_pages_per_query,
            allow_exploration_ordering=not any(
                str(pool.intent_type or "") == "campus_visit"
                and str(pool.entity_binding_mode or "") == "exact_entity"
                for pool in initial_plan.intent_pools
            ),
        )
        requested_portfolio_id = str(request_context.get("rootPortfolioId") or "")
        if requested_portfolio_id and requested_portfolio_id != str(root.get("id") or ""):
            raise ValueError("simple_direction_frontier_root_identity_mismatch")
        request_context["requestIntentContract"] = copy.deepcopy(request_contract)
        request_context["planningSelectionRootTurnId"] = planning_root_id
        request_context["rootPortfolioId"] = str(root.get("id") or "")
        request_context["_simpleDirectionRequestContractFingerprint"] = request_fingerprint
        pipeline_context["requestIntentContract"] = copy.deepcopy(request_contract)
        pipeline_context["planningSelectionRootTurnId"] = planning_root_id
        pipeline_context["rootPortfolioId"] = str(root.get("id") or "")
        for context_view in (request_context, pipeline_context):
            self._sync_controller_route_policy_context(context_view, copy.deepcopy(request_contract))
            context_view["requestContractFingerprint"] = request_fingerprint
            canonical_view = context_view.get("canonicalRequestContext")
            if isinstance(canonical_view, dict):
                canonical_view["requestContractFingerprint"] = request_fingerprint
        from src.services.shared_travel_source_service import SharedTravelSourceService
        initial_source_requirement = SharedTravelSourceService(self.db).initial_requirement(session_id, user_turn_id, root,
            expected_proof=(conversation_intent.get("semanticAction") or {}).get("sharedSourceBinding"))
        if initial_source_requirement is not None:
            request_context["guideContinuationRequirement"] = copy.deepcopy(initial_source_requirement)
            pipeline_context["guideContinuationRequirement"] = copy.deepcopy(initial_source_requirement)
        preparation = {
            "schemaVersion": "simple-direction-frontier-preparation-v1",
            "planningSelectionRootTurnId": planning_root_id,
            "rootPortfolioId": str(root.get("id") or ""),
            "requestContractFingerprint": request_fingerprint,
            "frontierStatus": str(root.get("simpleDirectionFrontierStatus") or ""),
        }
        frontier = root.get("simpleDirectionFrontier")
        view_resolution = (
            request_context.get("viewResolution") if isinstance(request_context.get("viewResolution"), dict) else {}
        )
        repair_direction = str(view_resolution.get("resolvedAction") or "") == "repair_comparison_direction"
        if isinstance(frontier, dict) and frontier and not repair_direction:
            pool_by_slot = {
                str(slot_id): pool
                for pool in initial_plan.intent_pools
                if str(pool.intent_type or "") == "campus_visit"
                for slot_id in pool.assign_to_slots
            }
            campus_slots = [
                {"dayNumber": int(slot.day_number), "slotId": str(slot.slot_id or "")}
                for slot in initial_plan.day_slots
                if str(slot.slot_id or "") in pool_by_slot
            ]
            if not campus_slots:
                raise ValueError("simple_direction_qualification_campus_slots_missing")
            choice_execution = (
                request_context.get("fallbackChoiceExecutionClaim")
                if isinstance(request_context.get("fallbackChoiceExecutionClaim"), dict)
                else {}
            )
            frontier_execution_id = str(choice_execution.get("id") or f"initial:{assistant_turn_id}")
            assignment = service.claim_frontier_assignment(
                portfolio_id=str(root.get("id") or ""),
                execution_id=frontier_execution_id,
                campus_slots=campus_slots,
                request_contract_fingerprint=request_fingerprint,
            )
            assignments = [item for item in assignment.get("campusAssignments") or [] if isinstance(item, dict)]
            if len(assignments) != len(campus_slots):
                raise ValueError("simple_direction_qualification_frontier_exhausted")
            pipeline_context["simpleDirectionFrontierAssignment"] = copy.deepcopy(assignment)
            pipeline_context["simpleDirectionFrontierExecutionId"] = frontier_execution_id
            preparation["frontierExecutionId"] = frontier_execution_id
            preparation["assignedCampusCount"] = len(assignments)
        elif repair_direction:
            preparation["frontierClaimSkippedReason"] = "repair_comparison_direction"
        elif request_context.get("_simpleDirectionGenerationAuthorized") is True:
            selected_choice = (
                request_context.get("selectedAgentChoice")
                if isinstance(request_context.get("selectedAgentChoice"), dict)
                else {}
            )
            selected_option = selected_choice.get("option") if isinstance(selected_choice.get("option"), dict) else {}
            choice_execution = (
                request_context.get("fallbackChoiceExecutionClaim")
                if isinstance(request_context.get("fallbackChoiceExecutionClaim"), dict)
                else {}
            )
            compatibility_execution_id = str(choice_execution.get("id") or "")
            if compatibility_execution_id:
                persisted_execution = self.db.execute("SELECT * FROM agent_choice_executions WHERE id = ? AND session_id = ?", (compatibility_execution_id, session_id)).fetchone()
                choice_execution = dict(persisted_execution) if persisted_execution is not None else {}
            if (
                str(selected_choice.get("action") or "") != "continue_plan_expansion"
                or str(selected_option.get("kind") or "") != "simple_direction_more_plans"
                or not compatibility_execution_id
            ):
                raise ValueError("simple_direction_compatibility_attempt_identity_missing")
            compatibility_attempt = service.claim_compatibility_continuation(
                portfolio_id=str(root.get("id") or ""),
                execution_id=compatibility_execution_id,
                source_assistant_turn_id=str(choice_execution.get("source_turn_id") or ""),
                request_turn_id=user_turn_id,
                choice_id=str(choice_execution.get("choice_id") or ""),
                request_contract_fingerprint=request_fingerprint,
                max_pages_per_query=self.settings.simple_open_max_pages_per_query,
                defer_slot_scope_claim=True,
            )
            provider_page = int(compatibility_attempt.get("providerPage") or 0)
            page_offset = int(compatibility_attempt.get("pageOffset") or 5)
            slot_queries = {
                str(slot_id): copy.deepcopy(item)
                for slot_id, item in (compatibility_attempt.get("slotQueries") or {}).items()
                if isinstance(item, dict) and str(slot_id or "")
            }
            pipeline_context["simpleDirectionFrontierAssignment"] = {
                "schemaVersion": "simple-direction-compatibility-query-pages-v2",
                "executionId": compatibility_execution_id,
                "providerPage": provider_page,
                "pageOffset": page_offset,
                "maxPagesPerQuery": int(compatibility_attempt.get("maxPagesPerQuery") or 0),
                "slotQueries": slot_queries,
                "slotFrontierSnapshot": copy.deepcopy(compatibility_attempt.get("slotFrontierSnapshot") or {}),
                "remainingQueryScopes": copy.deepcopy(compatibility_attempt.get("remainingQueryScopes") or []),
                "deferredSlotScopeClaim": True,
                "rootPortfolioId": str(root.get("id") or ""),
                "requestContractFingerprint": request_fingerprint,
            }
            pipeline_context["simpleDirectionFrontierExecutionId"] = compatibility_execution_id
            pipeline_context["simpleDirectionCompatibilityAttempt"] = copy.deepcopy(compatibility_attempt)
            preparation["frontierExecutionId"] = compatibility_execution_id
            preparation["attemptKind"] = "compatibility_continuation"
            preparation["providerPage"] = provider_page
            preparation["maxPagesPerQuery"] = int(compatibility_attempt.get("maxPagesPerQuery") or 0)
        pipeline_context["simpleDirectionFrontierPreparation"] = preparation
        self._append_pipeline_event(
            tool_events,
            "simple_direction_frontier_claimed",
            "冻结资格高校候选前沿",
            "completed",
            (
                "已在任何地点检索前冻结请求合同，并从服务端候选前沿领取本轮高校实体。"
                if int(preparation.get("assignedCampusCount") or 0) > 0
                else "已在任何地点检索前冻结请求合同；本轮不推进资格高校前沿。"
            ),
            {
                "rootPortfolioId": str(root.get("id") or ""),
                "frontierStatus": preparation.get("frontierStatus"),
                "frontierExecutionId": preparation.get("frontierExecutionId"),
                "attemptKind": preparation.get("attemptKind") or "qualification_frontier",
                "assignedCampusCount": int(preparation.get("assignedCampusCount") or 0),
                "providerCalled": False,
            },
        )

    def _simple_open_prior_direction_physical_aliases(
        self,
        *,
        session_id: Optional[str],
        pipeline_context: dict[str, Any],
    ) -> frozenset[str]:
        """Bind ``avoidRecentEntities`` to persisted physical proposal truth."""

        directive = (
            pipeline_context.get("planningDirective")
            if isinstance(pipeline_context.get("planningDirective"), dict)
            else {}
        )
        selection_policy = (
            directive.get("candidateSelectionPolicy")
            if isinstance(directive.get("candidateSelectionPolicy"), dict)
            else {}
        )
        if not (
            selection_policy.get("avoidRecentEntities") is True
            and simple_direction_generation_authorized(pipeline_context)
            and self._simple_open_server_authoritative_draft_applicable(pipeline_context)
        ):
            return frozenset()
        resolution = pipeline_context["viewResolution"]
        root_portfolio_id = str(resolution.get("rootPortfolioId") or "")
        if not session_id or not root_portfolio_id:
            raise ValueError("simple_direction_physical_exclusion_scope_invalid")
        return SimpleOpenDirectionService(self.db).prior_direction_physical_aliases(
            session_id=str(session_id),
            portfolio_id=root_portfolio_id,
        )

    def _simple_open_prior_direction_required_candidates(
        self,
        *,
        session_id: Optional[str],
        pipeline_context: dict[str, Any],
    ) -> dict[str, tuple[POI, ...]]:
        """Return same-occurrence verified POIs for hard-slot completeness only."""

        directive = (
            pipeline_context.get("planningDirective")
            if isinstance(pipeline_context.get("planningDirective"), dict)
            else {}
        )
        selection_policy = (
            directive.get("candidateSelectionPolicy")
            if isinstance(directive.get("candidateSelectionPolicy"), dict)
            else {}
        )
        if not (
            selection_policy.get("avoidRecentEntities") is True
            and simple_direction_generation_authorized(pipeline_context)
            and self._simple_open_server_authoritative_draft_applicable(pipeline_context)
        ):
            return {}
        resolution = pipeline_context.get("viewResolution")
        root_portfolio_id = str(resolution.get("rootPortfolioId") or "") if isinstance(resolution, dict) else ""
        if not session_id or not root_portfolio_id:
            raise ValueError("simple_direction_prior_candidate_scope_invalid")
        return SimpleOpenDirectionService(self.db).prior_required_occurrence_candidates(
            session_id=str(session_id),
            portfolio_id=root_portfolio_id,
        )

    def _execute_draft_itinerary_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        context, _decision, session_id, user_turn_id, content, session, user_turn = self._coordinator_executor_inputs(
            request
        )
        self._apply_controller_route_policy(
            context,
            (_decision.get("actionDirective") if isinstance(_decision.get("actionDirective"), dict) else None),
        )
        if request_context_requires_clarification(context):
            response = self._preflight_clarification_response(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                content=content,
                request_context=context,
                controller_clarification=None,
            )
            return self._executor_response_outcome(
                request,
                response,
                execution_route="pending_clarification_write_guard",
            )
        context["skipPostObservationController"] = True
        response = self._generate_with_initial_staged_pipeline(
            session_id, user_turn_id, content, context, event_sink=request.event_sink
        )
        return self._executor_response_outcome(request, response, execution_route="staged_initial_pipeline")

    def _execute_simple_open_draft_itinerary_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        """Reuse the canonical initial writer while bypassing Portfolio-only admission.

        The executor is an action-owned adapter: it does not create a second
        conversation loop or write path.  The server profile selects the
        non-Portfolio branch inside the established transaction/reload
        pipeline while the model still supplies the DaySlot skeleton.
        """
        context, _decision, session_id, user_turn_id, content, session, user_turn = self._coordinator_executor_inputs(
            request
        )
        self._apply_controller_route_policy(
            context,
            (_decision.get("actionDirective") if isinstance(_decision.get("actionDirective"), dict) else None),
        )
        if request_context_requires_clarification(context):
            response = self._preflight_clarification_response(
                session_id=session_id,
                user_turn_id=user_turn_id,
                user_turn=user_turn,
                session=session,
                content=content,
                request_context=context,
                controller_clarification=None,
            )
            return self._executor_response_outcome(
                request,
                response,
                execution_route="simple_open_initial_pipeline",
            )
        context.update(
            {
                "skipPostObservationController": True,
                "serverExecutionProfile": "simple_open_v1",
                "actualExecutionRoute": "simple_open_initial_pipeline",
                "simpleOpenNonBlockingRoutes": True,
            }
        )
        simple_open_budget = self._simple_open_amap_call_budget()
        with amap_call_budget_scope(simple_open_budget):
            response = self._generate_with_initial_staged_pipeline(
                session_id, user_turn_id, content, context, event_sink=request.event_sink
            )
        outcome = self._executor_response_outcome(request, response, execution_route="simple_open_initial_pipeline")
        if response is not None:
            response_row = self.db.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                (response.assistant_turn.id,),
            ).fetchone()
            response_payload = self._json_dict(response_row["agent_response_json"]) if response_row else {}
            if response_payload.get("workflowMode") == SimpleOpenDirectionService.WORKFLOW_MODE:
                return replace(
                    outcome,
                    status="needs_confirmation",
                    result_version_id=None,
                    patch_ids=[],
                    changed_segment_ids=[],
                    candidate_summary={
                        **outcome.candidate_summary,
                        "terminalStatus": "needs_confirmation",
                        "proposalOnly": True,
                        "visibleProposalCount": int(response_payload.get("visibleProposalCount") or 0),
                    },
                    verifier={
                        "passed": True,
                        "proposalOnly": True,
                        "itineraryWriteNotApplicable": True,
                    },
                    control_loop_disposition="terminal_needs_confirmation",
                    safe_to_continue=False,
                    safe_for_future_user_continuation=True,
                )
        if outcome.status in {"success", "partial"} and outcome.result_version_id:
            return replace(
                outcome,
                candidate_summary={**outcome.candidate_summary, "terminalStatus": "simple_open_terminal"},
                control_loop_disposition="terminal_success",
                safe_for_future_user_continuation=True,
            )
        return outcome

    def _simple_open_amap_call_budget(self) -> AmapCallBudget:
        """Allow bounded daily-completion grounding without starving formal goals."""

        route_refresh_max = int(self.settings.simple_open_route_provider_budget)
        place_search_max = MAX_SIMPLE_OPEN_POI_SEARCHES + MAX_SIMPLE_OPEN_DAILY_COMPLETION_SEARCHES
        return AmapCallBudget(
            place_text_max=place_search_max,
            place_around_max=place_search_max,
            route_refresh_max=route_refresh_max,
            total_external_max=place_search_max + route_refresh_max,
            source="simple_open_initial_pipeline_with_daily_completion",
        )

    def _execute_timeline_mutation_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        context, _decision, session_id, user_turn_id, content, session, user_turn = self._coordinator_executor_inputs(
            request
        )
        compiled_candidate_decision = self._compile_unique_selected_candidate_patch(
            request.decision_state, context.get("agentObservation")
        )
        if compiled_candidate_decision is not None:
            outcome, _result, _report = self._execute_post_observation_candidate_patch(
                session_id=session_id,
                turn_id=user_turn_id,
                decision=compiled_candidate_decision,
                request_context=context,
            )
            return outcome
        mutation_intent = self._controller_timeline_mutation_intent(context, content)
        response = (
            self._execute_local_timeline_mutation(
                session_id,
                user_turn_id,
                user_turn,
                session,
                content,
                mutation_intent,
                request_context=context,
            )
            if mutation_intent is not None
            else None
        )
        if response is None:
            directive = request.decision.get("actionDirective")
            directive_payload = (
                directive.model_dump(by_alias=True, exclude_none=True)
                if hasattr(directive, "model_dump")
                else directive
                if isinstance(directive, dict)
                else {}
            )
            if directive_payload.get("operationIntent") == "timeline_command":
                # The model has already selected patch_itinerary. Parsing here
                # is only an executor-local compiler aid and cannot choose the
                # primary action or bypass the policy gate.
                parsed_command = self.timeline_command_planner.parse(
                    content, has_active_timeline=bool(session["active_version_id"])
                )
                if parsed_command is not None:
                    response = self._try_handle_timeline_command(
                        session_id,
                        user_turn_id,
                        content,
                        user_turn,
                        session,
                        context,
                        parsed_command,
                    )
        if response is None:
            command = self.timeline_command_planner.compile(
                request.decision.get("actionDirective"), context.get("agentObservation")
            )
            if command is not None:
                directive_base_version = str(command.constraints.get("baseVersionId") or "")
                if directive_base_version and directive_base_version != str(session["active_version_id"] or ""):
                    response = self._execute_accepted_direct_action(
                        session_id, user_turn_id, content, user_turn, session, context
                    )
                else:
                    compiled_intent = self._compiled_timeline_mutation_intent(
                        command, context.get("agentObservation"), content
                    )
                    if compiled_intent is not None:
                        response = self._execute_local_timeline_mutation(
                            session_id,
                            user_turn_id,
                            user_turn,
                            session,
                            content,
                            compiled_intent,
                            request_context=context,
                        )
                    else:
                        response = self._execute_accepted_direct_action(
                            session_id, user_turn_id, content, user_turn, session, context
                        )
        return self._executor_response_outcome(request, response, execution_route="timeline_mutation_executor")

    @staticmethod
    def _compile_unique_selected_candidate_patch(
        decision: dict[str, Any], observation: Any
    ) -> Optional[dict[str, Any]]:
        """Compile an accepted generic POI patch only from persisted typed identity."""
        directive = decision.get("actionDirective") if isinstance(decision.get("actionDirective"), dict) else {}
        scope = decision.get("targetScope") if isinstance(decision.get("targetScope"), dict) else {}
        if decision.get("primaryAction") != "patch_itinerary" or directive.get("operationIntent") not in {
            "replace_segment_poi",
            "replace_segment_poi_from_candidate",
        }:
            return None
        segment_ids = [str(item) for item in scope.get("segmentIds") or [] if str(item)]
        if len(segment_ids) != 1 or not isinstance(observation, dict):
            return None
        candidate_state = (
            observation.get("candidateState") if isinstance(observation.get("candidateState"), dict) else {}
        )
        matches: list[tuple[str, str]] = []
        for group in candidate_state.get("pendingGroups") or []:
            if not isinstance(group, dict) or str(group.get("sourceSegmentId") or "") != segment_ids[0]:
                continue
            candidates = [item for item in group.get("safeCandidates") or [] if isinstance(item, dict)]
            selected_amap_id = str(group.get("selectedAmapId") or "")
            if len(candidates) != 1 or not selected_amap_id:
                continue
            candidate_amap_id = str(candidates[0].get("id") or "")
            if candidate_amap_id != selected_amap_id:
                continue
            candidate_record_id = str(group.get("id") or "")
            if candidate_record_id:
                matches.append((candidate_record_id, selected_amap_id))
        if len(set(matches)) != 1:
            return None
        candidate_record_id, amap_poi_id = matches[0]
        compiled = dict(decision)
        compiled["targetScope"] = {
            "baseVersionId": scope.get("baseVersionId"),
            "segmentIds": segment_ids,
            "operationScope": "replace_segment_poi_from_candidate",
            "candidateId": candidate_record_id,
            "amapPoiId": amap_poi_id,
            "preserve": [str(item) for item in scope.get("preserve") or [] if str(item)],
        }
        compiled["executorCompilation"] = {
            "source": "unique_persisted_selected_candidate",
            "originalOperationScope": directive.get("operationIntent"),
        }
        return compiled

    @staticmethod
    def _segment_duration_minutes_for_itinerary(plan: Any, segment_id: str) -> Optional[int]:
        for day in plan.days:
            for segment in day.segments:
                if segment.id != segment_id:
                    continue
                try:
                    start_hour, start_minute = str(segment.start_time).split(":", 1)
                    end_hour, end_minute = str(segment.end_time).split(":", 1)
                    start = int(start_hour) * 60 + int(start_minute)
                    end = int(end_hour) * 60 + int(end_minute)
                except (AttributeError, TypeError, ValueError):
                    return None
                return max(end - start, 0)
        return None

    def _candidate_patch_operations(
        self,
        *,
        plan: Any,
        segment_id: str,
        operation_scope: str,
        candidate_id: Optional[str],
        amap_poi: MapPoiResponse,
        preserve: list[str],
        notes: Optional[str] = None,
    ) -> list[ItineraryPatchOperation]:
        operations = [
            ItineraryPatchOperation(
                op=operation_scope,
                segmentId=segment_id,
                candidateId=candidate_id or None,
                amapPoi=amap_poi,
                notes=notes,
            )
        ]
        if "target_duration" in {str(item) for item in preserve if str(item)}:
            duration = self._segment_duration_minutes_for_itinerary(plan, segment_id)
            if duration and duration > 0:
                operations.append(
                    ItineraryPatchOperation(
                        op="replace_segment_duration",
                        segmentId=segment_id,
                        durationMinutes=duration,
                    )
                )
        return operations

    def _execute_complex_patch_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        context, decision_state, session_id, user_turn_id, content, session, user_turn = (
            self._coordinator_executor_inputs(request)
        )
        response: Optional[AgentMessageResponse] = None
        if self._model_selected_complex_patch(context):
            context["genericToolLoopEntered"] = True
            response = self._generate_with_tool_loop(session_id, user_turn_id, content, context)
        if response is None:
            command = self.timeline_command_planner.compile(
                request.decision.get("actionDirective"), context.get("agentObservation")
            )
            if command is not None:
                response = self._try_handle_timeline_command(
                    session_id, user_turn_id, content, user_turn, session, context, command
                )
        if response is None and decision_state.get("accepted") is True:
            response = self._execute_accepted_direct_action(
                session_id, user_turn_id, content, user_turn, session, context
            )
        return self._executor_response_outcome(request, response, execution_route="complex_patch_executor")

    def _execute_read_itinerary_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        context, decision_state, session_id, user_turn_id, content, session, user_turn = (
            self._coordinator_executor_inputs(request)
        )
        response = self._try_handle_read_timeline_query(
            session_id, user_turn, session, content, context, decision_state
        )
        return self._executor_response_outcome(request, response, execution_route="read_only")

    def _execute_direct_action_executor(
        self, request: AgentActionExecutionRequest, *, execution_route: str
    ) -> AgentActionOutcome:
        context, _decision, session_id, user_turn_id, content, session, user_turn = self._coordinator_executor_inputs(
            request
        )
        response = self._execute_accepted_direct_action(session_id, user_turn_id, content, user_turn, session, context)
        return self._executor_response_outcome(request, response, execution_route=execution_route)

    def _execute_resolve_poi_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        context, decision_state, session_id, user_turn_id, _content, session, _user_turn = (
            self._coordinator_executor_inputs(request)
        )
        return self._execute_post_observation_resolve_poi(
            session_id=session_id,
            turn_id=user_turn_id,
            city=str(session["city"] or context.get("selectedCity") or ""),
            decision=decision_state,
            observation=request.observation.model_dump(by_alias=True),
        )

    def _execute_optimize_route_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        return self._execute_direct_action_executor(request, execution_route="route_optimization")

    def _execute_verify_external_facts_executor(self, request: AgentActionExecutionRequest) -> AgentActionOutcome:
        return self._execute_direct_action_executor(request, execution_route="derived_facts_only")

    @staticmethod
    def _model_selected_complex_patch(request_context: dict[str, Any]) -> bool:
        decision = (
            request_context.get("agentDecision") if isinstance(request_context.get("agentDecision"), dict) else {}
        )
        directive = decision.get("actionDirective") if isinstance(decision.get("actionDirective"), dict) else {}
        if directive.get("type") != "patch_itinerary" or isinstance(directive.get("mutationIntent"), dict):
            return False
        operation = str(directive.get("operationIntent") or "")
        local_operations = {
            "replace_segment_start_time",
            "replace_segment_duration",
            "replace_segment_poi",
            "replace_segment_poi_from_candidate",
            "remove_segment",
            "replace_transport_mode",
        }
        tools = {
            str(item)
            for item in (request_context.get("agentDecisionState") or {}).get("effectiveTools") or []
            if str(item)
        }
        return operation not in local_operations and bool(
            tools & {"read_itinerary", "resolve_poi", "optimize_route", "web_search", "ticket_lookup", "amap_weather"}
        )

    def _coordinator_outcome_from_response(
        self,
        action: str,
        response: AgentMessageResponse,
        *,
        execution_route: Optional[str] = None,
    ) -> AgentActionOutcome:
        assistant_row = self.db.execute(
            "SELECT session_id, agent_response_json FROM conversation_turns WHERE id = ?",
            (response.assistant_turn.id,),
        ).fetchone()
        assistant_payload = self._json_dict(assistant_row["agent_response_json"]) if assistant_row else {}
        waiting_draft = self._persisted_waiting_draft_payload(action, assistant_payload)
        if waiting_draft is not None:
            unresolved = [item for item in waiting_draft.get("unresolvedSlots") or [] if isinstance(item, dict)]
            raw_next_actions = [str(item) for item in waiting_draft.get("nextActions") or [] if str(item)]
            recommended: list[str] = []
            if unresolved or any("poi" in item or "candidate" in item for item in raw_next_actions):
                recommended.append("resolve_poi")
            if any("ask_user" in str(item.get("nextAction") or "") for item in unresolved):
                recommended.append("ask_user")
            return AgentActionOutcome(
                action=action,
                execution_route=execution_route or "staged_initial_pipeline",
                status="partial",
                base_version_id=None,
                result_version_id=None,
                patch_ids=[],
                changed_segment_ids=[],
                external_call_counts=self._external_call_counts_from_steps(response.planning_steps),
                candidate_summary={
                    "terminalStatus": "planning_pending",
                    "planningAttemptTurnId": response.assistant_turn.id,
                    "resultState": waiting_draft.get("resultState"),
                    "unresolvedSlotCount": len([item for item in unresolved if item.get("slotId")]),
                    "unresolvedSlots": unresolved[:8],
                    "persisted": True,
                },
                verifier={"passed": None, "notApplicable": True, "reason": "no_itinerary_write"},
                rollback_performed=False,
                goal_delta={"planningAttemptPersisted": True},
                recommended_next_actions=list(dict.fromkeys(recommended or ["ask_user"])),
                safe_to_continue=True,
                terminal_payload=response,
            )
        mutation = (
            assistant_payload.get("timelineMutationOutcome")
            if isinstance(assistant_payload.get("timelineMutationOutcome"), dict)
            else {}
        )
        summary = mutation.get("changeSummary") if isinstance(mutation.get("changeSummary"), dict) else {}
        patch_ids = [str(mutation.get("patchId"))] if mutation.get("patchId") else []
        transaction = (
            assistant_payload.get("timelineMutationTransaction")
            if isinstance(assistant_payload.get("timelineMutationTransaction"), dict)
            else {}
        )
        changed_segment_ids = [str(summary.get("segmentId"))] if summary.get("segmentId") else []
        if not changed_segment_ids:
            transaction_outcome = transaction.get("outcome") if isinstance(transaction.get("outcome"), dict) else {}
            changed_segment_ids = [
                str(item)
                for item in (
                    transaction.get("directChangedSegmentIds")
                    or transaction_outcome.get("directChangedSegmentIds")
                    or mutation.get("directChangedSegmentIds")
                    or mutation.get("changedSegmentIds")
                    or mutation.get("targetSegmentIds")
                    or []
                )
                if str(item)
            ]
        has_pending_timeline_slots = bool(
            response.itinerary is not None and any(day.pending_slots for day in response.itinerary.days)
        )
        status = "success"
        if response.terminal_status == "needs_confirmation":
            status = (
                "partial"
                if action == "draft_itinerary" and response.version is not None and has_pending_timeline_slots
                else "success"
                if action in {"draft_itinerary", "patch_itinerary", "optimize_route"} and response.version is not None
                else "needs_confirmation"
            )
        elif response.terminal_status in {"failed", "error"}:
            status = "failed"
        elif response.terminal_status == "no_change":
            status = "no_change"
        if action == "draft_itinerary" and response.version is not None and has_pending_timeline_slots:
            status = "partial"
        result_version_id = (
            str(mutation.get("resultVersionId") or "")
            or (response.version.id if response.version is not None else "")
            or None
        )
        if not patch_ids and result_version_id:
            patch_ids = [
                str(row["id"])
                for row in self.db.execute(
                    "SELECT id FROM itinerary_patches WHERE result_version_id = ? "
                    "AND validation_status = 'accepted' ORDER BY created_at",
                    (result_version_id,),
                ).fetchall()
            ]
        if not changed_segment_ids:
            for event in response.planning_steps:
                metadata = event.metadata if isinstance(event.metadata, dict) else {}
                preview = metadata.get("resultPreview") if isinstance(metadata.get("resultPreview"), dict) else {}
                event_ids = [str(item) for item in preview.get("changedSegmentIds") or [] if str(item)]
                if event_ids:
                    changed_segment_ids = event_ids
                    break
        base_version_id = str(mutation.get("baseVersionId") or "") or None
        is_write_action = action in {"draft_itinerary", "patch_itinerary", "optimize_route"}
        if response.assistant_turn.failure_reason or (
            is_write_action and status == "success" and not result_version_id
        ):
            status = "failed"
        transaction_recorded = bool(transaction)
        mutation_status = str(mutation.get("status") or "")
        verifier_passed = (
            bool(mutation.get("postconditionPassed")) and bool(mutation.get("structuralVerifierPassed"))
            if mutation_status == "success"
            else transaction_recorded
            if mutation_status in {"no_change", "needs_confirmation"}
            else False
            if mutation
            else not bool(response.assistant_turn.failure_reason) and (not is_write_action or bool(result_version_id))
        )
        if is_write_action and status == "success" and not verifier_passed:
            status = "failed"
        verifier = {
            "postconditionPassed": mutation.get("postconditionPassed"),
            "structuralVerifierPassed": mutation.get("structuralVerifierPassed"),
            "passed": verifier_passed,
        }
        observed_active_version_id: Optional[str] = None
        pending_slot_truth_valid = False
        pending_slot_truth_error: Optional[str] = None
        pending_slot_truth_missing_context: list[str] = []
        pending_slot_count = 0
        if result_version_id and assistant_row is not None:
            session_row = self.db.execute(
                "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
                (assistant_row["session_id"],),
            ).fetchone()
            observed_active_version_id = (
                str(session_row["active_version_id"] or "") or None if session_row is not None else None
            )
        if status == "partial" and result_version_id and observed_active_version_id == result_version_id:
            version_row = self.db.execute(
                "SELECT snapshot_json FROM itinerary_versions WHERE id = ?",
                (result_version_id,),
            ).fetchone()
            if version_row is not None:
                try:
                    raw_persisted_snapshot = self._json_dict(version_row["snapshot_json"])
                    raw_selection_context = (
                        raw_persisted_snapshot.get("portfolioSelectionContext")
                        if isinstance(raw_persisted_snapshot.get("portfolioSelectionContext"), dict)
                        else {}
                    )
                    pending_slot_truth_missing_context = [
                        key
                        for key in PortfolioPendingSlotService.CONTEXT_KEYS
                        if not str(raw_selection_context.get(key) or "").strip()
                    ]
                    persisted_snapshot = PortfolioPendingSlotService.reconcile(raw_persisted_snapshot)
                    persisted_slots = [
                        item for item in persisted_snapshot.get("portfolioPendingSlots") or [] if isinstance(item, dict)
                    ]
                    response_slot_ids = {
                        str(slot.planning_slot_id)
                        for day in (response.itinerary.days if response.itinerary is not None else [])
                        for slot in day.pending_slots
                    }
                    persisted_slot_ids = {str(item.get("planningSlotId") or "") for item in persisted_slots}
                    pending_slot_count = len(persisted_slots)
                    pending_slot_truth_valid = bool(persisted_slots) and (response_slot_ids == persisted_slot_ids)
                except PortfolioPendingSlotError as error:
                    pending_slot_truth_error = error.code
                    pending_slot_truth_valid = False
        verifier["pendingSlotTruthValid"] = pending_slot_truth_valid
        if pending_slot_truth_error:
            verifier["pendingSlotTruthError"] = pending_slot_truth_error
        if pending_slot_truth_missing_context:
            verifier["pendingSlotTruthMissingContext"] = pending_slot_truth_missing_context
        partial_terminal = bool(
            action == "draft_itinerary"
            and status == "partial"
            and result_version_id
            and patch_ids
            and verifier_passed
            and pending_slot_truth_valid
            and observed_active_version_id == result_version_id
            and not bool(mutation.get("rollbackPerformed"))
        )
        verified_local_timeline_terminal = bool(
            action == "patch_itinerary"
            and str(assistant_payload.get("mode") or "") == "local_timeline_mutation"
            and response.terminal_status == "completed"
            and mutation_status == "success"
            and status == "success"
            and result_version_id
            and patch_ids
            and observed_active_version_id == result_version_id
            and verifier_passed
            and mutation.get("postconditionPassed") is True
            and mutation.get("structuralVerifierPassed") is True
            and not bool(mutation.get("rollbackPerformed"))
        )
        return AgentActionOutcome(
            action=action,
            execution_route=execution_route or self.action_executor_registry.ROUTES.get(action, "no_safe_action"),
            status=status,
            base_version_id=base_version_id,
            result_version_id=result_version_id,
            observed_active_version_id=observed_active_version_id,
            patch_ids=patch_ids,
            changed_segment_ids=changed_segment_ids,
            external_call_counts=self._external_call_counts_from_steps(response.planning_steps),
            candidate_summary={
                "terminalStatus": (
                    "needs_confirmation"
                    if status == "partial" and has_pending_timeline_slots
                    else response.terminal_status or ("failed" if status == "failed" else "")
                ),
                "changeSummary": summary,
                "transactionRecorded": transaction_recorded,
                "pendingSlotCount": pending_slot_count,
            },
            verifier=verifier,
            rollback_performed=bool(mutation.get("rollbackPerformed")),
            goal_delta={"verifiedChange": summary} if summary else {},
            recommended_next_actions=["ask_user"]
            if response.terminal_status == "needs_confirmation"
            else ["finish"]
            if status == "success"
            else ["ask_user"],
            control_loop_disposition=(
                "terminal_needs_confirmation"
                if partial_terminal
                else "terminal_success"
                if verified_local_timeline_terminal
                else "terminal_failure"
                if status == "failed"
                else "continue"
            ),
            safe_for_future_user_continuation=partial_terminal or verified_local_timeline_terminal,
            safe_to_continue=(
                not verified_local_timeline_terminal
                and status in {"success", "partial", "needs_confirmation", "no_change"}
                and verifier_passed
            ),
            terminal_payload=response,
        )

    @staticmethod
    def _persisted_waiting_draft_payload(action: str, payload: dict[str, Any]) -> Optional[dict[str, Any]]:
        """Recognize only a structurally persisted, resumable pre-version draft."""
        if action != "draft_itinerary" or str(payload.get("mode") or "") != "staged_initial_pipeline_waiting":
            return None
        state = str(payload.get("resultState") or payload.get("planningStatus") or "")
        if state not in {
            "draft_needs_completion",
            "quality_contract_failed",
            "no_minimum_viable_day",
            "provider_rate_limited",
            "required_intent_unresolved",
            "waiting_for_poi_grounding",
            "waiting_for_required_intent",
            "candidate_refresh_required",
        }:
            return None
        grounding = payload.get("grounding") if isinstance(payload.get("grounding"), dict) else {}
        initial_plan = payload.get("initialPlan") or grounding.get("initialPlan")
        pipeline_context = payload.get("pipelineContext") or grounding.get("pipelineContext")
        unresolved = payload.get("unresolvedSlots") or grounding.get("unresolvedSlots") or []
        planning_preview = payload.get("planningPreview") or grounding.get("planningPreview")
        if not isinstance(initial_plan, dict) or not isinstance(pipeline_context, dict):
            return None
        if not unresolved and not isinstance(planning_preview, dict):
            return None
        return {
            "resultState": state,
            "initialPlan": initial_plan,
            "pipelineContext": pipeline_context,
            "unresolvedSlots": unresolved if isinstance(unresolved, list) else [],
            "planningPreview": planning_preview if isinstance(planning_preview, dict) else {},
            "nextActions": payload.get("nextActions") or grounding.get("nextActions") or [],
        }

    @staticmethod
    def _external_call_counts_from_steps(steps: list[AgentPlanningEventResponse]) -> dict[str, int]:
        counts = {"amapPlaceText": 0, "amapRoute": 0, "webSearch": 0, "ticketLookup": 0, "amapWeather": 0}
        nested_aliases = {
            "amapPlaceText": {"usedPlaceText", "amapPoiTextSearchCalls", "amapPlaceTextCalls"},
            "amapRoute": {"usedRoute", "amapRouteCalls"},
            "webSearch": {"webSearchCalls"},
            "ticketLookup": {"ticketLookupCalls"},
            "amapWeather": {"amapWeatherCalls"},
        }

        def nested_max(value: Any, aliases: set[str]) -> int:
            found = 0
            if isinstance(value, dict):
                for key, item in value.items():
                    if key in aliases and isinstance(item, int):
                        found = max(found, item)
                    found = max(found, nested_max(item, aliases))
            elif isinstance(value, list):
                for item in value:
                    found = max(found, nested_max(item, aliases))
            return found

        for step in steps:
            metadata = step.metadata or {}
            for key in tuple(counts):
                value = metadata.get(f"{key}Calls")
                if isinstance(value, int):
                    counts[key] += value
                counts[key] = max(counts[key], nested_max(metadata, nested_aliases[key]))
        return counts

    def _attach_coordinator_trace(
        self,
        response: AgentMessageResponse,
        result: CoordinatedTurnResult,
        user_turn_id: str,
        event_sink: Optional[AgentExecutionEventSink],
    ) -> AgentMessageResponse:
        now = datetime.now(timezone.utc).isoformat()
        trace_events: list[AgentPlanningEventResponse] = []
        sequence = 0
        coordinator_types = {
            "agent_observation",
            "agent_decision",
            "agent_policy_gate",
            "agent_action_started",
            "agent_action_outcome",
            "agent_stop",
        }
        executor_events_by_cycle: dict[int, list[AgentPlanningEventResponse]] = {}
        root_causal_executor_types = {
            "tool",
            "timeline_edit",
            "understanding",
            "plan",
            "initial_day_slot_provider",
            "deterministic_slot_fallback",
            "server_generic_day_slots",
            "decompose_intent_pools",
            "generate_day_slots",
            "collect_candidates",
            "candidate_selection",
            "build_persistable_segment_plans",
            "build_skeleton_draft_segments",
            "normalize_request",
            "create_itinerary_version",
            "basic_verifier",
            "patch_itinerary",
            "route_optimization",
            "deterministic_enrichment",
            "resolve_poi",
            "apply_patch",
            "verify",
            "respond",
            "timeline_mutation_detected",
            "timeline_target_bound",
            "timeline_target_ambiguous",
            "timeline_target_not_found",
            "timeline_replacement_resolved",
            "timeline_replacement_unresolved",
            "timeline_patch_compiled",
            "timeline_patch_started",
            "route_refresh_started",
            "route_refresh_completed",
            "schedule_recomputed",
            "structural_verifier",
            "mutation_postcondition_verifier",
            "timeline_mutation_committed",
            "timeline_mutation_no_change",
            "timeline_mutation_failed",
            "rollback_completed",
            "active_version_restored",
            "active_version_unchanged",
            "simple_open_planning_started",
            "simple_open_draft_created",
            "simple_open_tool_call",
            "simple_open_slot_grounded",
            "simple_open_slot_provisional",
            "simple_open_slot_unresolved",
            "simple_open_routes_attempted",
            "simple_open_result_classified",
            "simple_direction_proposal_persisted",
            "simple_open_persist_started",
            "simple_open_persist_completed",
            "simple_open_persist_reloaded",
            "simple_open_terminal",
        }
        outcome_index = 0
        for coordinated_cycle in result.cycles:
            if coordinated_cycle.outcome is None or outcome_index >= len(result.outcomes):
                continue
            outcome = result.outcomes[outcome_index]
            outcome_index += 1
            payload = outcome.terminal_payload
            if not isinstance(payload, AgentMessageResponse):
                continue
            primary_action = str(coordinated_cycle.decision.get("primaryAction") or "")
            causal_types = (
                {"active_version_unchanged"} if primary_action in {"finish", "ask_user"} else root_causal_executor_types
            )
            executor_events_by_cycle[coordinated_cycle.cycle_index] = [
                event.model_copy(
                    update={
                        "metadata": {
                            **(event.metadata or {}),
                            "coordinatorCycleIndex": coordinated_cycle.cycle_index,
                        }
                    }
                )
                for event in payload.planning_steps
                if event.type in causal_types
            ]
        for cycle in result.cycles:
            sequence += 1
            observation_event = AgentPlanningEventResponse(
                type="agent_observation",
                label="读取持久化状态观察",
                status="completed",
                detail="已从当前 session、active version 与时间轴快照构建 canonical observation。",
                turnId=response.assistant_turn.id,
                providerName="agent-turn-coordinator",
                sequence=sequence,
                category="internal",
                metadata={
                    "cycleIndex": cycle.cycle_index,
                    "stateFingerprint": cycle.observation.get("stateFingerprint"),
                    "versionLineage": cycle.observation.get("versionLineage"),
                    "segmentRefs": cycle.observation.get("segmentRefs") or [],
                    "reloadedPersistedState": cycle.cycle_index > 0,
                    "observation": cycle.observation,
                },
                timestamp=cycle.observed_at or now,
            )
            trace_events.append(observation_event)
            if not cycle.decision:
                continue
            if cycle.decision.get("controllerFullCalled"):
                sequence += 1
                trace_events.append(
                    AgentPlanningEventResponse(
                        type="controller_full_started",
                        label="Controller Full 决策开始",
                        status="querying",
                        detail="Full Controller 已接收 canonical observation。",
                        turnId=response.assistant_turn.id,
                        providerName=type(self.provider).__name__,
                        sequence=sequence,
                        category="internal",
                        metadata={
                            "cycleIndex": cycle.cycle_index,
                            "observationFingerprint": cycle.observation.get("stateFingerprint"),
                        },
                        timestamp=cycle.decision_started_at or cycle.observed_at or now,
                    )
                )
                sequence += 1
                trace_events.append(
                    AgentPlanningEventResponse(
                        type=(
                            "controller_full_succeeded"
                            if cycle.decision.get("controllerFullSucceeded")
                            else "controller_full_failed"
                        ),
                        label="Controller Full 决策完成",
                        status="completed" if cycle.decision.get("controllerFullSucceeded") else "fallback",
                        detail="Full Controller 已返回 V3 decision。"
                        if cycle.decision.get("controllerFullSucceeded")
                        else "Full Controller 未形成可执行 V3 decision。",
                        turnId=response.assistant_turn.id,
                        providerName=type(self.provider).__name__,
                        fallbackUsed=not bool(cycle.decision.get("controllerFullSucceeded")),
                        failureReason=cycle.decision.get("controllerError"),
                        durationMs=int(cycle.decision.get("decisionDurationMs") or 0),
                        sequence=sequence,
                        category="internal",
                        metadata={"cycleIndex": cycle.cycle_index},
                        timestamp=cycle.decided_at or now,
                    )
                )
            sequence += 1
            decision_metadata = {
                **cycle.decision,
                "cycleIndex": cycle.cycle_index,
                "postObservationDecision": cycle.cycle_index > 0,
                "legacyAdapterCalled": False,
                "preControllerDomainRouterCount": int(
                    (cycle.decision.get("invocationLedger") or {}).get("intentModelAttemptCount") or 0
                ),
                "localMutationBypassCount": 0,
            }
            fallback_reason_codes = [str(item) for item in cycle.decision.get("reasonCodes") or [] if str(item)]
            fallback_failure_reason = str(
                cycle.decision.get("controllerError") or next(iter(fallback_reason_codes), "") or "controller_fallback"
            )
            decision_event = AgentPlanningEventResponse(
                type="agent_decision",
                label="Controller 模型决策",
                status=(
                    "fallback"
                    if cycle.decision.get("source") != "controller"
                    else "completed"
                    if cycle.decision.get("accepted") is True
                    else "failed"
                ),
                detail=str(cycle.decision.get("decisionSummary") or "模型已返回结构化决策。"),
                turnId=response.assistant_turn.id,
                providerName=type(self.provider).__name__,
                fallbackUsed=cycle.decision.get("source") != "controller",
                failureReason=(fallback_failure_reason if cycle.decision.get("source") != "controller" else None),
                sequence=sequence,
                category="decision",
                metadata=decision_metadata,
                durationMs=int(cycle.decision.get("decisionDurationMs") or 0),
                timestamp=cycle.decided_at or now,
            )
            trace_events.append(decision_event)
            action = str(cycle.decision.get("primaryAction") or "")
            sequence += 1
            trace_events.append(
                AgentPlanningEventResponse(
                    type="agent_policy_gate",
                    label="Policy Gate 安全裁决",
                    status="completed" if cycle.decision.get("accepted") is True else "failed",
                    detail="已校验 action directive、目标范围、工具与写入风险。",
                    turnId=response.assistant_turn.id,
                    providerName="agent-decision-policy-gate",
                    sequence=sequence,
                    category="decision",
                    metadata={
                        "cycleIndex": cycle.cycle_index,
                        "decisionId": cycle.decision.get("decisionId"),
                        "accepted": cycle.decision.get("accepted") is True,
                        "policyReasonCodes": cycle.decision.get("policyReasonCodes") or [],
                    },
                    timestamp=cycle.policy_gate_at or cycle.decided_at or now,
                )
            )
            if cycle.outcome is not None:
                sequence += 1
                trace_events.append(
                    AgentPlanningEventResponse(
                        type="agent_action_started",
                        label="Executor 开始执行",
                        status="querying",
                        detail="Registry 已将 accepted decision 交给唯一 concrete executor。",
                        turnId=response.assistant_turn.id,
                        providerName="agent-action-executor-registry",
                        sequence=sequence,
                        category="write" if cycle.outcome.get("patchIds") else "internal",
                        metadata={
                            "cycleIndex": cycle.cycle_index,
                            "decisionId": cycle.decision.get("decisionId"),
                            "primaryAction": action,
                            "executionRoute": cycle.outcome.get("executionRoute"),
                        },
                        timestamp=cycle.action_started_at or cycle.policy_gate_at or now,
                    )
                )
                trace_events.extend(executor_events_by_cycle.pop(cycle.cycle_index, []))
                execution_event_labels = {
                    "candidate_patch_started": "候选替换事务开始",
                    "candidate_patch_applied": "候选替换 patch 已写入待验证版本",
                    "candidate_patch_verifier": "候选替换 verifier",
                    "candidate_patch_committed": "候选替换事务已提交",
                }
                for execution_event in cycle.outcome.get("executionEvents") or []:
                    if not isinstance(execution_event, dict):
                        continue
                    event_name = str(execution_event.get("name") or "candidate_patch_event")
                    event_metadata = {
                        key: value
                        for key, value in execution_event.items()
                        if key not in {"name", "status", "timestamp", "durationMs"}
                    }
                    trace_events.append(
                        AgentPlanningEventResponse(
                            type=event_name,
                            label=execution_event_labels.get(event_name, event_name),
                            status=str(execution_event.get("status") or "completed"),
                            detail="记录 candidate patch executor 的真实事务边界。",
                            turnId=response.assistant_turn.id,
                            providerName="candidate-patch-executor",
                            durationMs=int(execution_event.get("durationMs") or 0),
                            sequence=0,
                            category="write"
                            if event_name in {"candidate_patch_started", "candidate_patch_committed"}
                            else "internal",
                            metadata={
                                "cycleIndex": cycle.cycle_index,
                                "decisionId": cycle.decision.get("decisionId"),
                                "executionRoute": cycle.outcome.get("executionRoute"),
                                **event_metadata,
                            },
                            timestamp=str(execution_event.get("timestamp") or cycle.outcome_at or now),
                        )
                    )
                sequence += 1
                verifier = cycle.outcome.get("verifier") if isinstance(cycle.outcome.get("verifier"), dict) else {}
                result_preview = {
                    **cycle.outcome,
                    "cycleIndex": cycle.cycle_index,
                    "verifierPassed": verifier.get("passed"),
                    "postconditionPassed": verifier.get("postconditionPassed"),
                    "structuralVerifierPassed": verifier.get("structuralVerifierPassed"),
                }
                trace_events.append(
                    AgentPlanningEventResponse(
                        type="agent_action_outcome",
                        label="Executor 真实结果",
                        status="completed"
                        if cycle.outcome.get("status") == "success"
                        else str(cycle.outcome.get("status") or "failed"),
                        detail="已记录 executor 的 version、patch、verifier 与外部调用证据。",
                        turnId=response.assistant_turn.id,
                        providerName="agent-action-executor-registry",
                        sequence=sequence,
                        category="write" if cycle.outcome.get("patchIds") else "internal",
                        metadata={
                            "cycleIndex": cycle.cycle_index,
                            "decisionId": cycle.decision.get("decisionId"),
                            "resultPreview": result_preview,
                        },
                        timestamp=cycle.outcome_at or now,
                    )
                )
        for remaining_events in executor_events_by_cycle.values():
            trace_events.extend(remaining_events)
        partial_outcome = next(
            (
                cycle.outcome
                for cycle in result.cycles
                if isinstance(cycle.outcome, dict)
                and cycle.outcome.get("controlLoopDisposition") == "terminal_needs_confirmation"
            ),
            None,
        )
        controller_decisions = [cycle.decision for cycle in result.cycles if cycle.decision]
        decision_ledgers = [
            item.get("invocationLedger")
            for item in controller_decisions
            if isinstance(item.get("invocationLedger"), dict)
        ]
        entry_ledger = (result.final_context.get("conversationIntent") or {}).get("invocationLedger")
        if isinstance(entry_ledger, dict):
            decision_ledgers.append(entry_ledger)
        invocation_ledger = {
            "semanticActionCallCount": max(
                (int(item.get("semanticActionCallCount") or 0) for item in decision_ledgers), default=0,
            ),
            "intentModelAttemptCount": max(
                (int(item.get("intentModelAttemptCount") or 0) for item in decision_ledgers),
                default=0,
            ),
            "intentProviderCallCount": max(
                (int(item.get("intentProviderCallCount") or 0) for item in decision_ledgers),
                default=0,
            ),
            "fullControllerCallCount": sum(bool(item.get("controllerFullCalled")) for item in controller_decisions),
            "fallbackControllerLiteCallCount": sum(
                bool(item.get("controllerLiteCalled")) for item in controller_decisions
            ),
            "plannerCallCount": sum(bool(item.get("plannerCalled")) for item in controller_decisions),
        }
        planner_provider_called = any(
            event.type == "initial_day_slot_provider"
            and event.status in {"querying", "completed", "fallback", "failed"}
            for event in trace_events
        )
        control_metrics = {
            # Controller ownership metadata keeps ``plannerCalled`` scoped to
            # the autonomy fallback planner.  The terminal run metric is
            # broader: it must also report the real DaySlot planning provider
            # invoked by the accepted Simple Open execution route.
            "plannerCalled": planner_provider_called
            or any(bool(item.get("plannerCalled")) for item in controller_decisions),
            "deterministicArbitratorCalled": any(
                bool(item.get("deterministicArbitratorCalled")) for item in controller_decisions
            ),
            "legacyAdapterCalled": False,
            "preControllerDomainRouterCount": invocation_ledger["intentModelAttemptCount"],
            "localMutationBypassCount": 0,
            "controllerFullCallCount": invocation_ledger["fullControllerCallCount"],
            "semanticActionCallCount": invocation_ledger["semanticActionCallCount"],
            "controllerLiteCallCount": (
                max(0, invocation_ledger["intentProviderCallCount"] - invocation_ledger["semanticActionCallCount"])
                + invocation_ledger["fallbackControllerLiteCallCount"]
            ),
            "invocationLedger": invocation_ledger,
            "controllerFallbackCount": sum(item.get("source") != "controller" for item in controller_decisions),
            "partialResultTerminal": partial_outcome is not None,
            "partialResultVersionId": (partial_outcome or {}).get("resultVersionId"),
            "partialPendingSlotCount": ((partial_outcome or {}).get("candidateSummary") or {}).get(
                "pendingSlotCount", 0
            ),
            "controlLoopDisposition": (partial_outcome or {}).get("controlLoopDisposition") or "continue",
            "postObservationControllerCalled": any(
                cycle.cycle_index > 0 and bool(cycle.decision) for cycle in result.cycles
            ),
            "finalResponseSource": "partial_executor_terminal" if partial_outcome is not None else "control_loop",
        }
        stop_event = AgentPlanningEventResponse(
            type="agent_stop",
            label="Agent 控制循环停止",
            status="completed",
            detail="已根据模型终止决策、policy gate 或 executor 真实结果停止。",
            turnId=response.assistant_turn.id,
            providerName=type(self.provider).__name__,
            sequence=sequence + 1,
            category="internal",
            metadata={
                "stopReason": result.stop_reason,
                "cycleCount": len(result.cycles),
                **control_metrics,
            },
            timestamp=now,
        )
        trace_events.append(stop_event)
        for final_sequence, event in enumerate(trace_events, start=1):
            event.sequence = final_sequence
        for event in trace_events:
            if event_sink is not None:
                event_sink(event)
        tool_trace_events = [event for event in trace_events if event.type == "tool"]
        response = response.model_copy(
            update={
                "planning_steps": trace_events,
                "tool_events": tool_trace_events,
                "agent_decision_count": len(result.cycles),
                "outcome_statuses": {
                    **response.outcome_statuses,
                    "agentControlStopReason": result.stop_reason,
                    "agentControlCycleCount": len(result.cycles),
                    **control_metrics,
                },
            }
        )
        assistant_row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
            (response.assistant_turn.id,),
        ).fetchone()
        payload = self._json_dict(assistant_row["agent_response_json"]) if assistant_row else {}
        payload["agentControlLoop"] = {
            "cycles": [
                {
                    "cycleIndex": cycle.cycle_index,
                    "observation": cycle.observation,
                    "decision": cycle.decision,
                    "outcome": cycle.outcome,
                }
                for cycle in result.cycles
            ],
            "stopReason": result.stop_reason,
            "controlMetrics": control_metrics,
        }
        payload["cycleTrace"] = payload["agentControlLoop"]["cycles"]
        payload["beforeAfter"] = next(
            (
                (cycle.outcome or {}).get("goalDelta", {}).get("verifiedChange")
                for cycle in result.cycles
                if isinstance((cycle.outcome or {}).get("goalDelta"), dict)
                and (cycle.outcome or {}).get("goalDelta", {}).get("verifiedChange")
            ),
            {},
        )
        payload["planningRun"] = (
            response.planning_run.model_dump(by_alias=True) if response.planning_run is not None else None
        )
        payload["planningSteps"] = [item.model_dump(by_alias=True) for item in response.planning_steps]
        payload["toolEvents"] = [item.model_dump(by_alias=True) for item in response.tool_events]
        self.db.execute(
            "UPDATE conversation_turns SET agent_response_json = ?, updated_at = ? WHERE id = ?",
            (json.dumps(payload, ensure_ascii=False, default=str), now, response.assistant_turn.id),
        )
        final_request = dict(result.final_context)
        final_request.pop("_coordinatorPriorResponse", None)
        final_request["agentControlLoop"] = payload["agentControlLoop"]
        from src.services.agent_ingress_journal import AgentIngressJournal
        final_request = AgentIngressJournal(self.db).merge_context(user_turn_id, final_request)
        self.db.execute(
            "UPDATE conversation_turns SET agent_request_json = ?, updated_at = ? WHERE id = ?",
            (json.dumps(final_request, ensure_ascii=False, default=str), now, user_turn_id),
        )
        self._store_planning_events(response.assistant_turn.id, response.planning_steps)
        stored_row = self.db.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
            (response.assistant_turn.id,),
        ).fetchone()
        stored_payload = self._json_dict(stored_row["agent_response_json"]) if stored_row else payload
        stored_payload["toolEvents"] = [item.model_dump(by_alias=True) for item in response.tool_events]
        self.db.execute(
            "UPDATE conversation_turns SET agent_response_json = ?, updated_at = ? WHERE id = ?",
            (
                json.dumps(stored_payload, ensure_ascii=False, default=str),
                now,
                response.assistant_turn.id,
            ),
        )
        self.db.commit()
        return response.model_copy(update={"assistant_turn": self._turn_response(response.assistant_turn.id)})

    @staticmethod
    def _controller_timeline_mutation_intent(
        request_context: dict[str, Any], source_text: str
    ) -> Optional[TimelineMutationIntent]:
        decision = (
            request_context.get("agentDecision") if isinstance(request_context.get("agentDecision"), dict) else {}
        )
        directive = decision.get("actionDirective") if isinstance(decision.get("actionDirective"), dict) else {}
        scope = decision.get("targetScope") if isinstance(decision.get("targetScope"), dict) else {}
        raw = (
            directive.get("mutationIntent")
            if isinstance(directive.get("mutationIntent"), dict)
            else scope.get("mutationIntent")
        )
        if not isinstance(raw, dict):
            return None
        try:
            intent = TimelineMutationIntent.model_validate(raw)
        except ValidationError:
            return None
        return intent.model_copy(update={"source": "model_semantic_extractor", "source_text": source_text})

    @staticmethod
    def _compiled_timeline_mutation_intent(
        command: TimelineEditCommand, observation: Any, source_text: str
    ) -> Optional[TimelineMutationIntent]:
        if command.intent != "directive_patch" or command.scope != "segment":
            return None
        operation = {
            "replace_segment_start_time": "set_start_time",
            "remove_segment": "remove_segment",
        }.get(command.operation)
        if operation is None:
            return None
        target_ids = [str(item) for item in command.constraints.get("targetSegmentIds") or [] if str(item)]
        if len(target_ids) != 1 or not isinstance(observation, dict):
            return None
        segment_refs = [item for item in observation.get("segmentRefs") or [] if isinstance(item, dict)]
        descriptor = next(
            (item for item in segment_refs if str(item.get("segmentId") or "") == target_ids[0]),
            None,
        )
        if descriptor is None:
            return None
        return TimelineMutationIntent.model_validate(
            {
                "operation": operation,
                "selector": {
                    "dayNumber": descriptor.get("dayNumber"),
                    "intentType": descriptor.get("intentType"),
                    "currentText": descriptor.get("poiName"),
                    "kind": descriptor.get("kind"),
                },
                "replacement": {"startTime": command.constraints.get("startTime")},
                "preserve": list(command.constraints.get("preserve") or ["other_segments", "other_days"]),
                "confidence": 1.0,
                "source": "model_semantic_extractor",
                "sourceText": source_text,
            }
        )

    def _timeline_mutation_events(
        self, session_id: str, turn_id: str, outcome: TimelineMutationOutcome
    ) -> list[AgentPlanningEventResponse]:
        labels = {
            "timeline_mutation_detected": "识别局部时间轴修改",
            "timeline_target_bound": "绑定当前版本目标",
            "timeline_target_ambiguous": "目标存在歧义",
            "timeline_target_not_found": "未找到修改目标",
            "timeline_replacement_resolved": "解析真实高德地点",
            "timeline_replacement_unresolved": "地点解析未形成唯一安全结果",
            "timeline_patch_compiled": "编译局部 patch",
            "timeline_patch_started": "开始事务写入",
            "route_refresh_started": "刷新受影响路线",
            "route_refresh_completed": "受影响路线刷新完成",
            "schedule_recomputed": "重新计算受影响排期",
            "structural_verifier": "结构约束校验",
            "mutation_postcondition_verifier": "修改后置条件校验",
            "timeline_mutation_committed": "局部修改已提交",
            "timeline_mutation_no_change": "当前结果无需修改",
            "timeline_mutation_failed": "局部修改失败",
            "rollback_completed": "已回滚局部修改",
            "active_version_restored": "已恢复原活动版本",
            "active_version_unchanged": "活动版本保持不变",
        }
        result = []
        previous_timestamp: Optional[datetime] = None
        for sequence, item in enumerate(outcome.events, start=1):
            name = str(item.get("name") or "timeline_mutation")
            status = str(item.get("status") or "completed")
            item_timestamp = str(item.get("timestamp") or datetime.now(timezone.utc).isoformat())
            parsed_timestamp = self._parse_event_datetime(item_timestamp)
            duration_ms = (
                max(0, int((parsed_timestamp - previous_timestamp).total_seconds() * 1000))
                if parsed_timestamp is not None and previous_timestamp is not None
                else 0
            )
            if parsed_timestamp is not None:
                previous_timestamp = parsed_timestamp
            result.append(
                AgentPlanningEventResponse(
                    type=name,
                    label=labels.get(name, name),
                    status=status,
                    detail=self._timeline_mutation_event_detail(name, outcome),
                    sessionId=session_id,
                    turnId=turn_id,
                    providerName="timeline-mutation-service",
                    fallbackUsed=False,
                    durationMs=duration_ms,
                    sequence=sequence,
                    category="write"
                    if name in {"timeline_patch_started", "timeline_mutation_committed"}
                    else "internal",
                    userVisible=name
                    in {
                        "timeline_target_ambiguous",
                        "timeline_target_not_found",
                        "timeline_mutation_committed",
                        "timeline_mutation_failed",
                    },
                    metadata={
                        "mutationId": outcome.mutation_id,
                        "baseVersionId": outcome.base_version_id,
                        "resultVersionId": outcome.result_version_id,
                        "patchId": outcome.patch_id,
                        "actualExecutionRoute": "timeline_mutation_executor",
                    },
                    timestamp=item_timestamp,
                )
            )
        if outcome.status == "success":
            operation = {
                "add_segment": "add",
                "remove_segment": "remove",
                "replace_poi": "replace",
                "set_start_time": "set_start_time",
                "set_duration": "set_duration",
                "set_transport_mode": "set_transport_mode",
            }[outcome.operation]
            result.append(
                AgentPlanningEventResponse(
                    type="timeline_edit",
                    label="时间轴局部修改兼容摘要",
                    status="completed",
                    detail="事务化局部修改已通过结构校验和后置条件校验。",
                    sessionId=session_id,
                    turnId=turn_id,
                    providerName="timeline-mutation-service",
                    sequence=len(result) + 1,
                    category="write",
                    metadata={
                        "resultPreview": {
                            "timelineCommand": {"operation": operation},
                            "changedScope": (
                                "target_day_add_only"
                                if outcome.operation == "add_segment"
                                else "day_meal_remove_only"
                                if outcome.operation == "remove_segment"
                                else "bound_timeline_target_only"
                            ),
                            "executorOwner": "timeline_mutation_executor",
                            "changedSegmentIds": list(outcome.direct_changed_segment_ids),
                            "toolLoopEntered": False,
                            "mutationId": outcome.mutation_id,
                        }
                    },
                    timestamp=datetime.now(timezone.utc).isoformat(),
                )
            )
        return result

    @staticmethod
    def _timeline_mutation_event_detail(name: str, outcome: TimelineMutationOutcome) -> str:
        if name == "timeline_mutation_committed":
            return f"已提交 patch {outcome.patch_id} 并保存版本 {outcome.result_version_id}；后置条件已通过。"
        if name in {"active_version_unchanged", "active_version_restored"}:
            return f"活动版本为 {outcome.base_version_id}，未产生错误成功声明。"
        if name == "timeline_mutation_failed":
            return "局部修改未通过事务门禁，不会向用户声明写入成功。"
        return "局部时间轴修改事务步骤已完成。"

    def _timeline_mutation_reply(self, outcome: TimelineMutationOutcome) -> str:
        if outcome.status == "success":
            summary = outcome.change_summary
            day = summary.get("dayNumber") or "?"
            before_window = f"{summary.get('beforeStartTime') or '?'}-{summary.get('beforeEndTime') or '?'}"
            after_window = f"{summary.get('afterStartTime') or '?'}-{summary.get('afterEndTime') or '?'}"
            operation_labels = {
                "replace_poi": "地点替换",
                "remove_segment": "删除",
                "set_start_time": "开始时间修改",
                "set_duration": "停留时长修改",
                "set_transport_mode": "交通方式修改",
            }
            if outcome.operation == "replace_poi":
                verified_change = (
                    f"已将第 {day} 天 {before_window} 的「{summary.get('beforePoiName') or '原地点'}」"
                    f"替换为「{summary.get('afterPoiName') or '新地点'}」；校验后时间为 {after_window}"
                )
            elif outcome.operation == "remove_segment":
                verified_change = (
                    f"已删除第 {day} 天 {before_window} 的「{summary.get('beforePoiName') or '目标项目'}」"
                )
            elif outcome.operation == "set_start_time":
                verified_change = f"已将第 {day} 天「{summary.get('beforePoiName') or '目标项目'}」从 {before_window} 调整为 {after_window}"
            elif outcome.operation == "set_duration":
                verified_change = (
                    f"已将第 {day} 天「{summary.get('beforePoiName') or '目标项目'}」调整为 {after_window}"
                )
            else:
                verified_change = (
                    f"已将第 {day} 天「{summary.get('beforePoiName') or '目标项目'}」交通方式从 "
                    f"{summary.get('beforeTransportMode') or '?'} 调整为 {summary.get('afterTransportMode') or '?'}"
                )
            return f"{verified_change}，并保存为新版本。本轮只处理绑定目标及必要的相邻路线/排期，其它地点未被直接修改。"
        if outcome.status == "needs_confirmation":
            if outcome.error_code == "ambiguous":
                return "当前版本中有多个符合描述的时间轴项目，请从下面的项目中选择；本轮未写入新版本。"
            if outcome.error_code == "target_not_found":
                return "当前活动版本中没有找到符合描述的时间轴项目，请重新描述或手动选择；本轮未写入。"
            return "找到多个实质不同的真实地点候选，请先选择一个；本轮未写入新版本。"
        if outcome.status == "no_change":
            if outcome.error_code == "mutation_already_applied":
                return "当前时间轴已经是该结果，没有重复创建 patch 或版本。"
            return "没有得到可安全执行的唯一结果，当前活动版本保持不变。"
        return "局部修改未通过校验，已恢复修改前版本；没有保存不完整结果。"

    @staticmethod
    def _timeline_mutation_terminal_status(outcome: TimelineMutationOutcome) -> str:
        if outcome.status == "success":
            return "completed"
        if outcome.status == "needs_confirmation":
            return "needs_confirmation"
        if outcome.status == "no_change":
            return "no_change"
        return "failed"

