    def _handle_transport_preference_command(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
    ) -> AgentMessageResponse:
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
        operations = [
            ItineraryPatchOperation(op="replace_transport_mode", segmentId=segment.id, value="public_transit")
            for day in plan.days
            for segment in day.segments
            if segment.kind not in {"rest", "note", "buffer"}
        ]
        if not operations:
            return self._timeline_command_noop_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "当前时间轴没有可更新交通偏好的日程段，未修改当前版本。",
                preview={"changed": False, "reason": "no_transport_segments"},
            )
        patch_response = ItineraryPatchService(self.db).apply_patch(
            session["active_plan_id"],
            operations,
            source_type="agent",
            base_version_id=session["active_version_id"],
            source_turn_id=user_turn_id,
            preference_summary=self._preference_summary_from_context(request_context),
            planning_context=self._timeline_command_planning_context(
                command, request_context=request_context, session_id=session_id
            ),
        )
        patched_session = self._session(session_id)
        reply = "已把当前时间轴的出行偏好改为公交/地铁，未重排景点；已有路线候选未在本轮全量重算，后续刷新路线时会继续优先公交地铁。"
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            reply,
            "active",
            agent_request_json={**request_context, "timelineCommand": command.as_dict()},
            agent_response_json={
                "mode": "timeline_edit",
                "reply": reply,
                "timelineCommand": command.as_dict(),
                "operations": [operation.model_dump(by_alias=True, exclude_none=True) for operation in operations],
                "warnings": ["已有路线候选未在本轮全量重算。"],
            },
        )
        planning_run = PlanningRunService(self.db).create_run(
            "agent_timeline_edit",
            user_input=content,
            preference_summary=self._preference_summary_from_context(request_context),
            itinerary=patch_response.itinerary,
            itinerary_version_id=patch_response.version.id,
            understood_requirements=request_context.get("understoodRequirements"),
            final_summary=reply,
        )
        ItineraryPatchService(self.db).attach_planning_run(patch_response.patch.id, planning_run.id)
        verifier_report = self._safe_verify_current_state(patched_session, "agent_timeline_edit")
        tool_events: list[dict[str, Any]] = []
        self._append_pipeline_event(
            tool_events,
            "timeline_edit",
            "精确时间轴编辑",
            "completed",
            "已识别局部交通偏好命令，只更新当前时间轴段的交通偏好，没有重排其它日期。",
            {
                "timelineCommand": command.as_dict(),
                "operationCount": len(operations),
                "changedSegmentIds": [operation.segment_id for operation in operations if operation.segment_id],
                "transportMode": "public_transit",
                "changedScope": "route_preference_only",
                "globalReorder": False,
                "externalRouteRefresh": False,
                "toolLoopEntered": False,
                "webSearchCalls": 0,
                "ticketLookupCalls": 0,
                "amapWeatherCalls": 0,
            },
        )
        self._append_pipeline_event(
            tool_events,
            "patch_itinerary",
            "写入交通偏好 patch",
            "completed",
            "已通过 replace_transport_mode 写入公交地铁偏好，并保留后续路线刷新 caveat。",
            {
                "patchId": patch_response.patch.id,
                "activeVersionId": patch_response.version.id,
                "operationCount": len(operations),
                "transportMode": "public_transit",
                "globalReorder": False,
                "externalRouteRefresh": False,
            },
        )
        planning_events = self._safe_planning_events_from_tool_events(
            tool_events,
            session_id,
            assistant_turn_id,
            patch_response.version.id,
            verifier_report=verifier_report,
        )
        self._store_planning_events(assistant_turn_id, planning_events)
        self._auto_update_preference_memory(session_id, content, reply)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=patch_response.itinerary,
            version=patch_response.version,
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=["已有路线候选未在本轮全量重算。"],
            planningRun=planning_run,
            planningSteps=planning_events,
            toolEvents=planning_events,
        )

    def _fallback_confirmation_events(
        self,
        session_id: str,
        assistant_turn_id: str,
        request_context: dict[str, Any],
        verifier_report: AgentVerifierReport,
    ) -> list[AgentPlanningEventResponse]:
        now = datetime.now(timezone.utc).isoformat()
        decision = (
            request_context.get("agentDecisionState")
            if isinstance(request_context.get("agentDecisionState"), dict)
            else {}
        )
        observation = (
            request_context.get("agentObservation") if isinstance(request_context.get("agentObservation"), dict) else {}
        )

        def make_event(
            event_type: str,
            label: str,
            status: str,
            detail: str,
            metadata: Optional[dict[str, Any]] = None,
            *,
            fallback_used: bool = False,
            failure_reason: Optional[str] = None,
        ) -> AgentPlanningEventResponse:
            return AgentPlanningEventResponse(
                type=event_type,
                label=label,
                status=status,
                detail=detail,
                sessionId=session_id,
                turnId=assistant_turn_id,
                providerName="agent-controller",
                fallbackUsed=fallback_used,
                failureReason=failure_reason,
                metadata=metadata or {},
                timestamp=now,
            )

        return enrich_action_trace_events(
            [
                make_event(
                    "agent_observation",
                    "读取安全确认上下文",
                    "completed",
                    "已读取空时间轴、当前 activeVersionId 与原始用户目标。",
                    {
                        "stateFingerprint": observation.get("stateFingerprint"),
                        "activeVersionId": request_context.get("activeVersionId"),
                    },
                ),
                make_event(
                    "agent_decision",
                    "Controller 决策",
                    "fallback",
                    "Controller 不可用；本轮只提供显式安全降级选项，不执行写入。",
                    decision,
                    fallback_used=True,
                    failure_reason=str(decision.get("controllerError") or "controller_unavailable"),
                ),
                make_event(
                    "fallback_confirmation_offered",
                    "提供安全降级确认",
                    "waiting",
                    "等待用户选择重试模型、规则安全草稿或手动补充。",
                    {"choiceCount": 3, "sourceDecisionId": decision.get("decisionId")},
                ),
                make_event(
                    "active_version_unchanged",
                    "确认 active version 未变化",
                    "completed",
                    "本轮未创建 patch 或 itinerary version；activeVersionId 保持不变。",
                    {"versionChanged": False, "verifier": verifier_report.as_metadata()},
                ),
                make_event(
                    "agent_stop",
                    "停止并等待确认",
                    "waiting",
                    "已在 needs_confirmation 终止本轮，不进入规划 executor。",
                    {"stopReason": "needs_confirmation"},
                ),
            ],
            goal=self._action_trace_goal(assistant_turn_id),
        )

    def _hard_constraint_relaxation_choices(
        self, pipeline_context: dict, enrichment_report: dict
    ) -> list[dict[str, str]]:
        message = str(pipeline_context.get("effectiveUserMessage") or pipeline_context.get("latestUserMessage") or "")
        unresolved = (
            enrichment_report.get("unresolvedSlots")
            if isinstance(enrichment_report.get("unresolvedSlots"), list)
            else []
        )
        campus_unresolved = any(
            str(item.get("intentType") or "") == "campus_visit" for item in unresolved if isinstance(item, dict)
        )
        if "985" not in message or not campus_unresolved:
            return []
        return [
            {
                "id": "keep_985_reduce_count",
                "label": "保持 985，减少学校数量",
                "value": "保持985硬约束，只减少学校数量",
            },
            {"id": "relax_211_double_first", "label": "放宽到 211/双一流", "value": "放宽到211或双一流高校"},
            {"id": "relax_any_campus", "label": "放宽为普通高校", "value": "放宽为普通高校"},
            {"id": "manual_campus", "label": "我自己填写学校", "value": "我自己填写要去的学校"},
        ]

    def _handle_remove_meal_command(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
    ) -> AgentMessageResponse:
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
        day = self._timeline_command_day(plan, command.day_number)
        target = self._timeline_target_meal_segment(day, command.time_window or "auto") if day is not None else None
        if day is None or target is None:
            return self._timeline_command_noop_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                f"没有找到第 {command.day_number or '?'} 天对应的餐饮段，当前版本未修改。",
                preview={
                    "changed": False,
                    "changedScope": "day_meal_remove_no_target",
                    "toolLoopEntered": False,
                },
            )
        operation = ItineraryPatchOperation(op="remove_segment", segmentId=getattr(target, "id", ""))
        return self._timeline_command_patch_response(
            session_id,
            user_turn_id,
            content,
            user_turn,
            session,
            request_context,
            command,
            [operation],
            f"已删除第 {day.day_number} 天对应餐饮段，其他日期和日程未重排。",
            warnings=[],
            result_preview={
                "changedScope": "day_meal_remove_only",
                "changedSegmentIds": [getattr(target, "id", "")],
                "toolLoopEntered": False,
                "webSearchCalls": 0,
                "ticketLookupCalls": 0,
                "amapWeatherCalls": 0,
                "globalReorder": False,
            },
        )

    def _handle_meal_edit_command(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
    ) -> AgentMessageResponse:
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
        day = self._timeline_command_day(plan, command.day_number)
        if day is None:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                f"没有找到第 {command.day_number or '?'} 天，未修改当前时间轴。",
            )
        target = self._timeline_target_meal_segment(
            day,
            command.time_window or "auto",
            str(command.constraints.get("targetMealText") or command.constraints.get("foodIntent") or ""),
        )
        if target is None:
            return self._handle_fill_dinner_command(
                session_id, user_turn_id, content, user_turn, session, request_context, command
            )

        requested_food_intent = str(command.constraints.get("foodIntent") or "餐厅").strip() or "餐厅"
        food_intent, assigned_dish_family = self._timeline_meal_search_intent(
            plan,
            day,
            target,
            command,
            content,
            session_id=session_id,
            requested_food_intent=requested_food_intent,
        )
        pending_candidate = self._pending_candidate_for_segment(
            session_id, getattr(target, "id", ""), food_intent, command.scope
        )
        provider_debug: list[dict[str, Any]] = []
        selected_poi: Optional[MapPoiResponse] = None
        selected_candidate_id: Optional[str] = None
        amap_budget = AmapCallBudget(
            place_text_max=1, place_around_max=4, total_external_max=4, source="timeline_command_executor"
        )
        with amap_call_budget_scope(amap_budget):
            if pending_candidate is not None:
                selected_candidate_id, selected_poi = pending_candidate
                if self.meal_diversity_policy.matches_user_explicit_exclusion(
                    selected_poi,
                    {str(item) for item in command.constraints.get("excludeDishFamilies") or [] if str(item)},
                ):
                    selected_candidate_id, selected_poi = None, None
            else:
                selected_poi, provider_debug = self._timeline_meal_replacement_candidate(
                    plan,
                    day,
                    target,
                    food_intent,
                    area_intent=str(command.constraints.get("areaIntent") or ""),
                    excluded_dish_families={
                        str(item) for item in command.constraints.get("excludeDishFamilies") or [] if str(item)
                    },
                )

        if selected_poi is not None:
            operation = ItineraryPatchOperation(
                op="replace_segment_poi_from_candidate" if selected_candidate_id else "replace_segment_poi",
                segmentId=getattr(target, "id", ""),
                candidateId=selected_candidate_id,
                amapPoi=selected_poi,
                notes=self._append_memory_rule_note(
                    f"groundingStatus：agent_selected_candidate；intentType=meal；foodIntent={food_intent}。",
                    self._meal_cost_note_for_existing_segment(target, request_context),
                ),
            )
            reply = f"已只把第 {day.day_number} 天餐饮改为「{selected_poi.name}」，没有重排其它景点或日期。"
            return self._timeline_command_patch_response(
                session_id,
                user_turn_id,
                content,
                user_turn,
                session,
                request_context,
                command,
                [operation],
                reply,
                warnings=[],
                result_preview={
                    "changedScope": "day_meal_only",
                    "changedSegmentIds": [getattr(target, "id", "")],
                    "selectedPoiName": selected_poi.name,
                    "requestedFoodIntent": food_intent,
                    "originalRequestedFoodIntent": requested_food_intent,
                    "selectedDishFamily": assigned_dish_family or self.meal_diversity_policy.dish_family(selected_poi),
                    "selectedFromPendingCandidate": bool(selected_candidate_id),
                    "toolLoopEntered": False,
                    "webSearchCalls": 0,
                    "ticketLookupCalls": 0,
                    "amapWeatherCalls": 0,
                    "amapCallBudget": amap_budget.snapshot(),
                    "providerDebug": provider_debug[:4],
                },
            )

        reply = f"已识别第 {day.day_number} 天餐饮想改为「{food_intent}」，但本轮没有拿到可靠高德餐饮候选；原时间轴未改动，也没有进入通用工具循环。"
        return self._timeline_command_noop_response(
            session_id,
            user_turn,
            session,
            content,
            request_context,
            command,
            reply,
            preview={
                "changed": False,
                "changedScope": "day_meal_no_candidate",
                "targetSegmentId": getattr(target, "id", ""),
                "requestedFoodIntent": food_intent,
                "originalRequestedFoodIntent": requested_food_intent,
                "selectedDishFamily": assigned_dish_family,
                "needsVerification": True,
                "toolLoopEntered": False,
                "webSearchCalls": 0,
                "ticketLookupCalls": 0,
                "amapWeatherCalls": 0,
                "amapCallBudget": amap_budget.snapshot(),
                "providerDebug": provider_debug[:4],
            },
        )

    def _timeline_meal_search_intent(
        self,
        plan: Any,
        day: Any,
        target: Any,
        command: TimelineEditCommand,
        content: str,
        *,
        session_id: str,
        requested_food_intent: str,
    ) -> tuple[str, str]:
        excluded = {str(item) for item in command.constraints.get("excludeDishFamilies") or [] if str(item)}
        city_name = str(getattr(plan, "city", "") or "").strip()
        normalized_food_intent = requested_food_intent
        if city_name and normalized_food_intent.startswith(city_name):
            normalized_food_intent = normalized_food_intent[len(city_name) :]
        generic_request = bool(
            re.fullmatch(
                r"(?:当地|本地)?(?:特色)?(?:美食|餐饮|餐厅|菜|风味)?",
                normalized_food_intent,
            )
            or normalized_food_intent in {"当地特色美食", "餐厅"}
        )
        if not excluded or not generic_request:
            return requested_food_intent, ""
        start_time = str(getattr(target, "start_time", "") or "12:00")
        slot = DaySlot(
            slot_id=f"timeline_edit_{getattr(target, 'id', 'meal')}",
            day_number=int(getattr(day, "day_number", 1) or 1),
            date=str(getattr(day, "date", "") or ""),
            time_window=str(command.time_window or "auto"),
            start_time=start_time,
            duration_minutes=max(
                45,
                self._minutes(getattr(target, "end_time", "00:00")) - self._minutes(start_time),
            ),
            kind="meal",
            raw_need=f"{self._meal_label_for_command(command)} 当地特色美食",
            route_anchor=True,
        )
        assignments = self.meal_experience_assignment_policy.assign(
            str(getattr(plan, "city", "") or ""),
            [slot],
            request_text=content,
            seed=session_id,
        )
        assignment = assignments.get(slot.slot_id)
        if assignment is None or not assignment.search_terms:
            return requested_food_intent, ""
        return assignment.search_terms[0], assignment.dish_family

    @staticmethod
    def _mark_candidate_options_execution_route(request_context: dict[str, Any]) -> None:
        decision_state = request_context.get("agentDecisionState")
        if isinstance(decision_state, dict):
            decision_state.update(
                {
                    "proposedExecutionRoute": "candidate_options",
                    "executionOverrideReason": "explicit_candidate_options_command",
                }
            )

    def _candidate_options_autonomy_events(
        self,
        *,
        request_context: dict[str, Any],
        session: sqlite3.Row,
        plan: Any,
        command: TimelineEditCommand,
        state: dict[str, Any],
        pending_candidates: list[Any],
        verifier_report: AgentVerifierReport,
        tool_event: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Record candidate-state mutation as a bounded, no-version autonomy action."""
        self._mark_candidate_options_execution_route(request_context)
        pending_payload = [
            item.model_dump(by_alias=True) if hasattr(item, "model_dump") else item for item in pending_candidates
        ]
        observation_context = {
            **request_context,
            "activeVersionId": session["active_version_id"],
            "currentItinerarySnapshot": plan.model_dump(by_alias=True),
            "pendingAmapPoiCandidates": pending_payload,
        }
        events = [
            self._autonomy_observation_pipeline_event(observation_context),
            self._autonomy_decision_pipeline_event(observation_context),
        ]
        self._append_pipeline_event(
            events,
            "agent_action_started",
            "执行自治动作",
            "completed",
            "开始生成可确认的地图候选；不会修改 itinerary version。",
            {"executionRoute": "candidate_options", "cycleIndex": 0, "allowedTools": ["resolve_poi"]},
        )
        events.append(tool_event)
        self._append_pipeline_event(
            events,
            "agent_action_outcome",
            "记录自治动作结果",
            "completed" if verifier_report.passed else "failed",
            "已持久化候选状态，active itinerary version 未变化。",
            {
                "cycleIndex": 0,
                "decisionId": (request_context.get("agentDecision") or {}).get("decisionId"),
                "action": "ask_user",
                "executionRoute": "candidate_options",
                "baseVersionId": session["active_version_id"],
                "resultVersionIds": [session["active_version_id"]] if session["active_version_id"] else [],
                "patchIds": [],
                "changedSegmentIds": [],
                "changedScope": "pending_candidate_state",
                "pendingCandidateIds": [
                    str(item.get("candidateRecordId") or "")
                    for item in state.get("options") or []
                    if isinstance(item, dict)
                ],
                "verifierPassed": verifier_report.passed,
                "rollbackPerformed": False,
                "toolLoopEntered": False,
            },
        )
        post_observation = self.autonomy_observation_builder.build(
            observation_context,
            cycle_index=1,
            last_action={"action": "ask_user", "executionRoute": "candidate_options"},
            last_outcome={"verifierPassed": verifier_report.passed, "resultVersionId": session["active_version_id"]},
        )
        events.append(
            self._autonomy_observation_pipeline_event(
                observation_context, observation=post_observation.model_dump(by_alias=True)
            )
        )
        self._append_pipeline_event(
            events,
            "agent_stop",
            "自治循环停止",
            "completed",
            "候选存在歧义，已停止并等待用户确认。",
            {
                "cycleIndex": 1,
                "stopReason": "needs_confirmation",
                "observationFingerprint": post_observation.state_fingerprint,
            },
        )
        return events

    def _order_autonomy_outcome_after_verifier(
        self,
        events: list[AgentPlanningEventResponse],
        assistant_turn_id: str,
    ) -> list[AgentPlanningEventResponse]:
        """Keep the emitted evidence in the same causal order as persisted state."""
        deferred_types = {"agent_action_outcome", "agent_stop"}

        def defer_until_after_verifier(event: AgentPlanningEventResponse) -> bool:
            if event.type in deferred_types:
                return True
            metadata = event.metadata if isinstance(event.metadata, dict) else {}
            return event.type == "agent_observation" and int(metadata.get("cycleIndex") or 0) > 0

        deferred_events = [event for event in events if defer_until_after_verifier(event)]
        if not deferred_events:
            return events
        response_events = [event for event in events if event.type == "respond"]
        ordered = [event for event in events if not defer_until_after_verifier(event) and event.type != "respond"]
        ordered.extend(deferred_events)
        ordered.extend(response_events)
        return enrich_action_trace_events(ordered, goal=self._action_trace_goal(assistant_turn_id))

    def _handle_local_meal_options_command(
        self,
        session_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
    ) -> AgentMessageResponse:
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"]) if session["active_plan_id"] else None
        if plan is None:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "当前没有可编辑时间轴，未生成餐饮候选。",
            )
        day = self._timeline_command_day(plan, command.day_number)
        target = (
            self._timeline_target_meal_segment(
                day,
                command.time_window or "auto",
                str(command.constraints.get("targetMealText") or command.constraints.get("foodIntent") or ""),
            )
            if day is not None
            else None
        )
        if day is None or target is None:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "没有找到可确认的餐饮段，当前版本未修改。",
            )
        food_intent = str(command.constraints.get("foodIntent") or "餐厅").strip() or "餐厅"
        amap_budget = AmapCallBudget(
            place_text_max=1, place_around_max=2, total_external_max=3, source="local_meal_options"
        )
        with amap_call_budget_scope(amap_budget):
            options, provider_debug = self._local_meal_options(
                plan, day, target, food_intent, str(command.constraints.get("areaIntent") or "")
            )
        if not options:
            return self._timeline_command_noop_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "本轮没有拿到可靠的真实餐饮候选，当前版本未修改，也没有进入通用工具循环。",
                preview={
                    "changed": False,
                    "toolLoopEntered": False,
                    "webSearchCalls": 0,
                    "ticketLookupCalls": 0,
                    "amapWeatherCalls": 0,
                    "amapCallBudget": amap_budget.snapshot(),
                    "providerDebug": provider_debug[:4],
                },
            )
        pending_records = self._record_timeline_pending_poi_candidates(
            session_id,
            user_turn.id,
            plan,
            command,
            [target],
            [poi for option in options if (poi := self._map_meal_poi_from_option(option)) is not None],
            reason="local_meal_options",
        )
        candidate_record_id = str((pending_records[0] if pending_records else {}).get("candidateRecordId") or "")
        if candidate_record_id:
            options = [
                {
                    **option,
                    "candidateRecordId": candidate_record_id,
                    "selectionGroupId": candidate_record_id,
                    "segmentId": getattr(target, "id", ""),
                }
                for option in options
            ]
        state = {
            "kind": "local_poi_options",
            "scope": "meal",
            "intentType": "meal",
            "foodIntent": food_intent,
            "targetDayNumber": getattr(day, "day_number", command.day_number),
            "targetSegmentId": getattr(target, "id", ""),
            "candidateRecordId": candidate_record_id or None,
            "includeCustomOption": True,
            "options": options,
        }
        custom_option_index = self._local_poi_custom_option_index(options)
        reply = (
            f"第 {getattr(day, 'day_number', command.day_number) or '?'} 天「{food_intent}」可选真实地图餐饮如下；选一个后才会替换当前餐饮段：\n"
            + "\n".join(f"{option['index']}. {option['label']}" for option in options)
            + f"\n{custom_option_index}. 我自己填写具体地点"
        )
        self._mark_candidate_options_execution_route(request_context)
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            reply,
            "active",
            agent_request_json={**request_context, "timelineCommand": command.as_dict()},
            agent_response_json={
                "mode": "local_poi_options",
                "reply": reply,
                "timelineCommand": command.as_dict(),
                "localPoiOptions": state,
            },
        )
        planning_run = PlanningRunService(self.db).create_run(
            "agent_local_poi_options",
            user_input=content,
            preference_summary=self._preference_summary_from_context(request_context),
            itinerary=plan,
            itinerary_version_id=session["active_version_id"],
            understood_requirements=request_context.get("understoodRequirements"),
            final_summary=reply,
        )
        verifier_report = self._safe_verify_active_version_unchanged(session, "agent_local_poi_options")
        tool_event = {
            "id": "local_meal_options",
            "toolName": "local_poi_options",
            "type": "timeline_edit",
            "label": "生成餐饮候选选项",
            "status": "completed",
            "detail": "已生成结构化真实高德餐饮候选；本轮不写 itinerary version。",
            "providerName": "agent-service",
            "metadata": {
                "resultPreview": {
                    "timelineCommand": command.as_dict(),
                    "localPoiOptions": state,
                    "toolLoopEntered": False,
                    "pendingCandidateRecords": pending_records,
                    "webSearchCalls": 0,
                    "ticketLookupCalls": 0,
                    "amapWeatherCalls": 0,
                    "amapCallBudget": amap_budget.snapshot(),
                    "providerDebug": provider_debug[:4],
                }
            },
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }
        pending_candidates = ConversationService(self.db)._pending_candidates(session_id)
        tool_events = self._candidate_options_autonomy_events(
            request_context=request_context,
            session=session,
            plan=plan,
            command=command,
            state=state,
            pending_candidates=pending_candidates,
            verifier_report=verifier_report,
            tool_event=tool_event,
        )
        planning_events = self._safe_planning_events_from_tool_events(
            tool_events, session_id, assistant_turn_id, None, verifier_report=verifier_report
        )
        planning_events = self._order_autonomy_outcome_after_verifier(planning_events, assistant_turn_id)
        self._store_planning_events(assistant_turn_id, planning_events)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=plan,
            version=None,
            pendingPoiCandidates=pending_candidates,
            warnings=[],
            planningRun=planning_run,
            planningSteps=planning_events,
            toolEvents=planning_events,
            executionMode="deterministic_fast_path",
            terminalStatus="needs_confirmation",
            outcomeStatuses={
                "itineraryStatus": "unchanged",
                "mapStatus": "candidates_ready",
                "routeStatus": "unchanged",
                "reservationStatus": "not_checked",
                "sourceQualityStatus": "verified",
            },
        )

