    def _handle_choose_previous_local_poi_option_command(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
    ) -> AgentMessageResponse:
        state = self._latest_local_poi_choice_state(session_id)
        option = self._match_local_poi_option(command, state)
        if str(state.get("scope") or "") == "meal":
            return self._handle_selected_local_meal_option(
                session_id, user_turn_id, content, user_turn, session, request_context, command, state, option
            )
        selected_text = str(command.constraints.get("selectedOptionText") or "").strip()
        if option and option.get("custom") and not selected_text:
            return self._timeline_command_noop_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "请输入高德可检索的具体地点名称。本轮未修改当前时间轴，也没有进入通用工具循环。",
                preview={"changed": False, "requiresCustomInput": True, "toolLoopEntered": False},
            )
        query = str(
            selected_text
            if option and option.get("custom")
            else (option or {}).get("query") or (option or {}).get("label") or selected_text or ""
        ).strip()
        if not query:
            return self._timeline_command_noop_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "没有找到上一轮可选择的夜景候选；请先让我生成候选，或直接输入具体地点名称。本轮未修改当前时间轴。",
                preview={"changed": False, "missingPreviousLocalPoiOptions": True, "toolLoopEntered": False},
            )
        option_command = TimelineEditCommand(
            intent="timeline_edit",
            scope="night_view",
            operation="ground_or_replace_specific_poi",
            day_number=int(state.get("targetDayNumber"))
            if isinstance(state.get("targetDayNumber"), int)
            else command.day_number,
            segment_kind="visit",
            time_window="evening",
            constraints={
                **command.constraints,
                "query": query,
                "targetSegmentId": state.get("targetSegmentId"),
                "allowHighRouteCostIfUserExplicit": True,
                "selectedLocalPoiOption": {**option, "query": query, "customInput": selected_text}
                if option and option.get("custom")
                else option,
                "requireConcreteAmapPoi": True,
                "avoidTicketLookup": True,
                "avoidWebSearch": True,
            },
        )
        return self._handle_specific_night_view_grounding_command(
            session_id, user_turn_id, content, user_turn, session, request_context, option_command
        )

    def _handle_selected_local_meal_option(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
        state: dict[str, Any],
        option: Optional[dict[str, Any]],
    ) -> AgentMessageResponse:
        selected_text = str(command.constraints.get("selectedOptionText") or "").strip()
        if option and option.get("custom"):
            if not selected_text:
                return self._timeline_command_noop_response(
                    session_id,
                    user_turn,
                    session,
                    content,
                    request_context,
                    command,
                    "请直接输入具体餐厅名称；本轮未修改当前时间轴。",
                    preview={"changed": False, "requiresCustomInput": True, "toolLoopEntered": False},
                )
            try:
                plan_for_resolution = ItineraryService(self.db).get_plan(session["active_plan_id"])
                response = MapPoiService().search(
                    city=str(getattr(plan_for_resolution, "city", "") or "北京"),
                    keyword=selected_text,
                    category="food",
                    limit=8,
                )
            except HTTPException as error:
                return self._timeline_command_noop_response(
                    session_id,
                    user_turn,
                    session,
                    content,
                    request_context,
                    command,
                    "未能解析你填写的餐厅，请稍后重试；当前版本未修改。",
                    preview={"changed": False, "providerError": str(error.detail), "toolLoopEntered": False},
                )
            option = next(
                (
                    {
                        "label": candidate.name,
                        "amapPoi": candidate.model_dump(by_alias=True),
                        "foodIntent": state.get("foodIntent"),
                    }
                    for candidate in response.pois
                    if self._best_timeline_candidate([candidate], "meal", selected_text, excluded_names=set())
                    is not None
                ),
                None,
            )
        poi = self._map_meal_poi_from_option(option) if option else None
        if poi is None:
            return self._timeline_command_noop_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "没有找到上一轮可选择的餐饮候选；请先让我生成候选。当前版本未修改。",
                preview={"changed": False, "missingPreviousLocalPoiOptions": True, "toolLoopEntered": False},
            )
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
        day = self._timeline_command_day(
            plan, state.get("targetDayNumber") if isinstance(state.get("targetDayNumber"), int) else command.day_number
        )
        target_id = str(state.get("targetSegmentId") or "")
        target = (
            next((segment for segment in getattr(day, "segments", []) if getattr(segment, "id", "") == target_id), None)
            if day
            else None
        )
        if day is None or target is None or getattr(target, "kind", "") != "meal":
            return self._timeline_command_noop_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "时间轴餐饮段已变化，请基于最新行程重新选择候选。",
                preview={"changed": False, "targetChanged": True, "toolLoopEntered": False},
            )
        food_intent = str(state.get("foodIntent") or "餐饮")
        candidate_id = (
            str(option.get("candidateRecordId") or state.get("candidateRecordId") or "").strip() if option else ""
        )
        operation = ItineraryPatchOperation(
            op="replace_segment_poi_from_candidate" if candidate_id else "replace_segment_poi",
            segmentId=target_id,
            candidateId=candidate_id or None,
            amapPoi=poi,
            notes=f"groundingStatus：agent_selected_candidate；intentType=meal；foodIntent={food_intent}；来源为上一轮结构化高德候选。",
        )
        return self._timeline_command_patch_response(
            session_id,
            user_turn_id,
            content,
            user_turn,
            session,
            request_context,
            command,
            [operation],
            f"已将第 {getattr(day, 'day_number', '?')} 天餐饮替换为真实地图地点「{poi.name}」，其余日程不重排。",
            warnings=[],
            result_preview={
                "changedScope": "day_meal_only",
                "changedSegmentIds": [target_id],
                "selectedPoiNames": [poi.name],
                "selectedFromStructuredCandidate": True,
                "toolLoopEntered": False,
                "webSearchCalls": 0,
                "ticketLookupCalls": 0,
                "amapWeatherCalls": 0,
            },
        )

    def _handle_specific_night_view_grounding_command(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
    ) -> AgentMessageResponse:
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"]) if session["active_plan_id"] else None
        if plan is None:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "当前没有可编辑时间轴，未修改夜景地点。",
            )
        day, target = self._target_night_view_segment(plan, command)
        if day is None or target is None:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                f"没有找到第 {command.day_number or '?'} 天可更新的夜景段，未修改当前时间轴。",
            )
        query = str(command.constraints.get("query") or command.constraints.get("selectedOptionText") or "").strip()
        option = (
            command.constraints.get("selectedLocalPoiOption")
            if isinstance(command.constraints.get("selectedLocalPoiOption"), dict)
            else None
        )
        option_poi = self._map_poi_from_option(option) if option else None
        provider_debug: list[dict[str, Any]] = []
        amap_budget = AmapCallBudget(
            place_text_max=3, place_around_max=0, total_external_max=3, source="local_night_view_grounding"
        )
        with amap_call_budget_scope(amap_budget):
            selected_poi = option_poi or self._resolve_specific_night_view_poi(plan, query, provider_debug)
        if selected_poi is None:
            return self._handle_local_night_view_options_command(
                session_id, content, user_turn, session, request_context, command
            )
        route_impact = self._local_night_view_route_impact(day, target, selected_poi)
        route_caveat = self._route_impact_caveat(route_impact)
        notes = (
            "groundingStatus：agent_selected_candidate；intentType=night_view；needsConcretePoi=false；"
            f"局部替换为高德解析地点；routeImpact={route_impact.get('level') or 'unknown'}；"
            "开放时间、门票、预约和节假日管控待出行前核验。"
        )
        if route_caveat:
            notes = f"{notes} {route_caveat}"
        operation = ItineraryPatchOperation(
            op="replace_segment_poi",
            segmentId=getattr(target, "id", ""),
            amapPoi=selected_poi,
            notes=notes,
        )
        reply = (
            f"已将第 {getattr(day, 'day_number', command.day_number) or '?'} 天夜景替换为真实地图地点「{selected_poi.name}」。"
            f"{route_caveat or ''}本轮只确认地图地点；开放时间、门票、预约和节假日管控需要出行前再核验。"
        )
        return self._timeline_command_patch_response(
            session_id,
            user_turn_id,
            content,
            user_turn,
            session,
            request_context,
            command,
            [operation],
            reply,
            warnings=[],
            result_preview={
                "changedScope": "night_view_concrete_grounding",
                "changedSegmentIds": [getattr(target, "id", "")],
                "selectedPoiNames": [selected_poi.name],
                "routeImpact": route_impact,
                "toolLoopEntered": False,
                "webSearchCalls": 0,
                "ticketLookupCalls": 0,
                "amapWeatherCalls": 0,
                "amapCallBudget": amap_budget.snapshot(),
                "providerDebug": provider_debug[:4],
            },
        )

    def _target_night_view_segment(
        self, plan: Any, command: TimelineEditCommand
    ) -> tuple[Optional[Any], Optional[Any]]:
        target_segment_id = str(command.constraints.get("targetSegmentId") or "").strip()
        scored: list[tuple[int, Any, Any]] = []
        for day in getattr(plan, "days", []) or []:
            if command.day_number is not None and getattr(day, "day_number", None) != command.day_number:
                continue
            for segment in getattr(day, "segments", []) or []:
                if target_segment_id and getattr(segment, "id", "") == target_segment_id:
                    return day, segment
                if not self._timeline_segment_is_night_view(segment):
                    continue
                score = 0
                text = self._timeline_segment_text(segment)
                if re.search(r"(waiting_for_poi_grounding|needsConcretePoi|夜景观景点|待核验)", text, re.IGNORECASE):
                    score += 4
                if self._minutes(getattr(segment, "start_time", "")) >= 18 * 60:
                    score += 2
                if getattr(getattr(segment, "poi", None), "source", "") != AMAP_PLACE_SOURCE:
                    score += 1
                scored.append((score, day, segment))
        if not scored:
            return None, None
        scored.sort(
            key=lambda item: (
                -item[0],
                getattr(item[1], "day_number", 0),
                self._minutes(getattr(item[2], "start_time", "")),
            )
        )
        _score, day, segment = scored[0]
        return day, segment

    def _latest_local_poi_choice_state(self, session_id: str) -> dict[str, Any]:
        rows = self.db.execute(
            """
            SELECT content, agent_response_json
            FROM conversation_turns
            WHERE session_id = ? AND role = 'assistant'
            ORDER BY created_at DESC
            LIMIT 12
            """,
            (session_id,),
        ).fetchall()
        for row in rows:
            try:
                payload = json.loads(row["agent_response_json"] or "{}")
            except (TypeError, json.JSONDecodeError):
                payload = {}
            state = payload.get("localPoiOptions") if isinstance(payload, dict) else None
            if isinstance(state, dict) and isinstance(state.get("options"), list):
                return state
            fallback = self._local_poi_choice_state_from_text(str(row["content"] or ""))
            if fallback:
                return fallback
        return {}

    def _local_poi_choice_state_from_text(self, content: str) -> dict[str, Any]:
        options: list[dict[str, Any]] = []
        for match in re.finditer(r"^\s*(\d+)[\.\、]\s*([^\n]+)", content or "", re.MULTILINE):
            index = int(match.group(1))
            label = re.sub(r"[（(].*?[）)]", "", match.group(2)).strip()
            if "我自己填写具体地点" in label:
                options.append({"index": index, "label": "我自己填写具体地点", "custom": True})
            elif label:
                options.append({"index": index, "label": label, "query": label})
        if len(options) >= 2:
            return {"kind": "local_poi_options", "scope": "night_view", "options": options}
        return {}

    def _match_local_poi_option(self, command: TimelineEditCommand, state: dict[str, Any]) -> Optional[dict[str, Any]]:
        options = state.get("options") if isinstance(state, dict) else []
        if not isinstance(options, list):
            options = []
        selected_index = command.constraints.get("selectedOptionIndex")
        try:
            selected_index = int(selected_index) if selected_index is not None else None
        except (TypeError, ValueError):
            selected_index = None
        if selected_index is not None:
            for option in options:
                if isinstance(option, dict) and option.get("index") == selected_index:
                    return option
            if state.get("includeCustomOption") and selected_index == self._local_poi_custom_option_index(options):
                return {"index": selected_index, "label": "我自己填写具体地点", "custom": True}
        selected_text = self._normalize_timeline_entity(command.constraints.get("selectedOptionText"))
        if not selected_text:
            return None
        for option in options:
            if not isinstance(option, dict):
                continue
            text = self._normalize_timeline_entity(
                " ".join(str(option.get(key) or "") for key in ("label", "query", "name"))
            )
            amap_poi = option.get("amapPoi")
            if isinstance(amap_poi, dict):
                text += self._normalize_timeline_entity(amap_poi.get("name"))
            if selected_text and (selected_text in text or text in selected_text):
                return option
        return None

    @staticmethod
    def _local_poi_custom_option_index(options: list[dict[str, Any]]) -> int:
        indexes: list[int] = []
        for option in options:
            if not isinstance(option, dict) or option.get("custom"):
                continue
            try:
                indexes.append(int(option.get("index")))
            except (TypeError, ValueError):
                continue
        return max(indexes, default=0) + 1

    def _map_poi_from_option(self, option: Optional[dict[str, Any]]) -> Optional[MapPoiResponse]:
        if not isinstance(option, dict):
            return None
        raw = option.get("amapPoi") or option.get("poi")
        if not isinstance(raw, dict):
            return None
        try:
            poi = MapPoiResponse.model_validate(raw)
        except Exception:
            return None
        return (
            poi
            if self._valid_local_night_view_candidate(poi, str(option.get("query") or option.get("label") or ""))
            else None
        )

    def _map_meal_poi_from_option(self, option: Optional[dict[str, Any]]) -> Optional[MapPoiResponse]:
        if not isinstance(option, dict):
            return None
        raw = option.get("amapPoi") or option.get("poi")
        if not isinstance(raw, dict):
            return None
        try:
            poi = MapPoiResponse.model_validate(raw)
        except Exception:
            return None
        return self._best_timeline_candidate([poi], "meal", str(option.get("foodIntent") or ""), excluded_names=set())

    def _resolve_specific_night_view_poi(
        self,
        plan: Any,
        query: str,
        provider_debug: list[dict[str, Any]],
    ) -> Optional[MapPoiResponse]:
        city = str(getattr(plan, "city", "") or "北京")
        queries = [query]
        seen_queries: set[str] = set()
        for item in queries:
            keyword = str(item or "").strip()
            if not keyword or keyword in seen_queries:
                continue
            seen_queries.add(keyword)
            try:
                response = MapPoiService().search(city=city, keyword=keyword, category="scenic", limit=8)
            except HTTPException as error:
                self._append_timeline_provider_debug(provider_debug, error)
                if self._timeline_should_stop_provider_attempts(error):
                    break
                continue
            for candidate in response.pois:
                if self._valid_local_night_view_candidate(
                    candidate,
                    query,
                ) and self._exact_place_candidate_matches(candidate, query):
                    return candidate
        return None

    def _local_night_view_options(
        self,
        plan: Any,
        day: Any,
        target: Any,
        command: TimelineEditCommand,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        city = str(getattr(plan, "city", "") or "北京")
        raw_queries = self._night_view_semantic_search_strategies(
            city,
            {
                "experienceSpecs": [
                    {
                        "intentType": "night_view",
                        "experienceFamily": "public_city_view",
                    }
                ],
                "dayNumber": getattr(day, "day_number", None),
            },
        )
        provider_debug: list[dict[str, Any]] = []
        candidates: list[MapPoiResponse] = []
        seen_candidate_keys: set[str] = set()
        option_count = max(1, min(int(command.constraints.get("optionCount") or 3), 3))
        for query in raw_queries:
            if len(candidates) >= option_count:
                break
            try:
                response = MapPoiService().search(city=city, keyword=query, category="scenic", limit=8)
            except HTTPException as error:
                self._append_timeline_provider_debug(provider_debug, error)
                if self._timeline_should_stop_provider_attempts(error):
                    break
                continue
            for candidate in response.pois:
                if not self._valid_local_night_view_candidate(candidate, query):
                    continue
                key = str(candidate.id or "") or self._normalize_timeline_entity(candidate.name)
                if not key or key in seen_candidate_keys:
                    continue
                seen_candidate_keys.add(key)
                candidates.append(candidate)
                if len(candidates) >= option_count:
                    break
        ranked: list[tuple[float, MapPoiResponse, dict[str, Any]]] = []
        for candidate in candidates:
            route_impact = self._local_night_view_route_impact(day, target, candidate)
            try:
                confidence = float(candidate.confidence or 0)
            except (TypeError, ValueError):
                confidence = 0.0
            distance = route_impact.get("distanceKm")
            distance_penalty = float(distance) if isinstance(distance, (int, float)) else 6.0
            ranked.append((distance_penalty - confidence, candidate, route_impact))
        ranked.sort(key=lambda item: (item[0], self._normalize_timeline_entity(item[1].name)))
        options: list[dict[str, Any]] = []
        for _score, candidate, route_impact in ranked:
            option = {
                "index": len(options) + 1,
                "label": candidate.name,
                "query": candidate.name,
                "amapPoi": candidate.model_dump(by_alias=True),
                "routeImpact": route_impact,
                "nightViewReason": self._night_view_reason(candidate),
            }
            warning = route_impact.get("warning")
            if warning:
                option["warning"] = warning
            options.append(option)
            if len(options) >= 3:
                break
        for index, option in enumerate(options, start=1):
            option["index"] = index
        return options, provider_debug

    def _valid_local_night_view_candidate(self, candidate: MapPoiResponse, query: str = "") -> bool:
        if candidate.source != AMAP_PLACE_SOURCE:
            return False
        if not self._valid_timeline_candidate_coord(candidate):
            return False
        text = " ".join([candidate.name or "", candidate.type or "", candidate.category or "", candidate.address or ""])
        normalized_query = self._normalize_timeline_entity(query)
        normalized_text = self._normalize_timeline_entity(text)
        normalized_name = self._normalize_timeline_entity(candidate.name)
        explicit_match = bool(
            normalized_query
            and (normalized_query in normalized_text or (normalized_name and normalized_name in normalized_query))
        )
        if self.night_view_candidate_policy.reject_reason(
            candidate,
            amap_identity=candidate.id,
            structured_hint=query if explicit_match else None,
        ):
            return False
        if self.night_view_candidate_policy.placeholder_reject_reason(candidate.name, text):
            return False
        if re.search(r"(小区|社区|停车场|出入口|公交站|地铁站|公司|写字楼办公室|楼门|便利店)", text):
            return False
        try:
            confidence = float(candidate.confidence or 0)
        except (TypeError, ValueError):
            confidence = 0.0
        if confidence < 0.8 and not explicit_match:
            return False
        return True

    def _exact_place_candidate_matches(self, candidate: MapPoiResponse, query: str) -> bool:
        expected = self._normalize_timeline_entity(query)
        actual = self._normalize_timeline_entity(candidate.name)
        if not expected or not actual:
            return False
        return expected == actual or expected in actual or actual in expected

    def _night_view_reason(self, candidate: MapPoiResponse) -> str:
        del candidate
        # Candidate-specific copy is supplied by the controller from provider
        # evidence.  The server must not turn entity keywords into a fixed
        # night-view recommendation or a fixed clarification answer.
        return "候选已保留 Provider 身份；开放与可达性仍需按当前证据核验。"

    def _local_night_view_route_impact(self, day: Any, target: Any, poi: MapPoiResponse) -> dict[str, Any]:
        anchor = self._previous_route_anchor(day, target)
        if anchor is None:
            return {"level": "unknown", "distanceKm": None, "durationMinutes": None, "warning": ""}
        distance_km = round(
            self._haversine_km(
                float(anchor["latitude"]),
                float(anchor["longitude"]),
                float(poi.latitude),
                float(poi.longitude),
            ),
            1,
        )
        duration_minutes = None
        if distance_km <= self.route_insertion_scorer.COARSE_DISTANCE_BANDS_KM[0]:
            level = "low"
            warning = ""
        elif distance_km <= self.route_insertion_scorer.COARSE_DISTANCE_BANDS_KM[1]:
            level = "medium"
            warning = ""
        else:
            level = "high"
            warning = "直线距离仅用于候选排序，采用前仍需路线 Provider 核验。"
        return {
            "level": level,
            "distanceKm": distance_km,
            "durationMinutes": duration_minutes,
            "fromSegmentId": anchor.get("segmentId"),
            "fromPoiName": anchor.get("name"),
            "warning": warning,
            "networkVerified": False,
            "reason": "geometry_precheck",
        }

    def _previous_route_anchor(self, day: Any, target: Any) -> Optional[dict[str, Any]]:
        target_start = self._minutes(getattr(target, "start_time", ""))
        candidates: list[tuple[int, Any]] = []
        for segment in getattr(day, "segments", []) or []:
            if getattr(segment, "id", "") == getattr(target, "id", ""):
                continue
            if getattr(segment, "kind", "") == "meal":
                continue
            start = self._minutes(getattr(segment, "start_time", ""))
            if target_start and start >= target_start:
                continue
            coord = self._timeline_segment_coord(segment)
            if coord is None:
                continue
            candidates.append((start, segment))
        if not candidates:
            return None
        _start, segment = sorted(candidates, key=lambda item: item[0])[-1]
        coord = self._timeline_segment_coord(segment) or {}
        poi = getattr(segment, "poi", None)
        return {
            "segmentId": getattr(segment, "id", ""),
            "name": getattr(poi, "name", "") or getattr(segment, "title", ""),
            "longitude": coord.get("longitude"),
            "latitude": coord.get("latitude"),
        }

    def _route_impact_caveat(self, route_impact: dict[str, Any]) -> str:
        level = str(route_impact.get("level") or "")
        if level == "high":
            return "路线提示：当前仅完成几何粗排，写入前会以 Provider 路线矩阵核验。"
        return ""

    def _local_night_view_options_reply(self, day_number: Optional[int], options: list[dict[str, Any]]) -> str:
        visible_options = options[:3]
        lines = [
            f"第 {day_number or '?'} 天夜景找到 {len(visible_options)} 个符合当前证据门槛的真实高德地点候选，"
            "当前时间轴暂不改。请选择一个选项："
        ]
        for option in visible_options:
            route_impact = option.get("routeImpact") if isinstance(option.get("routeImpact"), dict) else {}
            reason = str(option.get("nightViewReason") or "").strip()
            suffix = ""
            if route_impact.get("level") in {"high", "unacceptable"}:
                suffix = f"（{route_impact.get('warning') or '路线偏远'}）"
            reason_text = f"；{reason}" if reason else ""
            lines.append(f"{option.get('index')}. {option.get('label')}{suffix}{reason_text}")
        lines.append(f"{self._local_poi_custom_option_index(visible_options)}. 我自己填写具体地点")
        lines.append("开放时间、门票、预约和节假日管控待出行前核验。")
        return "\n".join(lines)

    def _handle_kind_replacement_command(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
    ) -> AgentMessageResponse:
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
        target_segments = self._timeline_target_kind_segments(plan, command)
        if not target_segments:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                "当前时间轴没有找到可局部替换的目标段，未进入通用工具循环。",
            )
        amap_budget = AmapCallBudget(
            place_text_max=2, place_around_max=0, total_external_max=2, source="timeline_command_executor"
        )
        with amap_call_budget_scope(amap_budget):
            candidates, provider_debug = self._timeline_kind_replacement_candidates(plan, command)
        operations: list[ItineraryPatchOperation] = []
        selected_poi_names: list[str] = []
        concrete_night_view = command.scope == "night_view" and bool(command.constraints.get("requireConcreteAmapPoi"))
        used_keys: set[str] = set()
        excluded_names = {
            self._normalize_timeline_entity(getattr(getattr(segment, "poi", None), "name", ""))
            for segment in target_segments
        }
        excluded_names.update(
            self._normalize_timeline_entity(name) for name in command.constraints.get("excludeNames", []) or []
        )
        keep_names = {self._normalize_timeline_entity(name) for name in command.constraints.get("keepNames", []) or []}
        for segment in target_segments:
            current_name = self._normalize_timeline_entity(getattr(getattr(segment, "poi", None), "name", ""))
            if keep_names and current_name in keep_names:
                continue
            replacement = self._next_replacement_candidate(candidates, used_keys, command, excluded_names)
            if replacement is None:
                continue
            note = (
                "groundingStatus：agent_selected_candidate；intentType=night_view；needsConcretePoi=false；"
                "局部替换为高德解析地点；开放时间、门票、预约和节假日管控待出行前核验。"
                if concrete_night_view
                else f"groundingStatus：agent_selected_candidate；intentType={command.constraints.get('intentType') or command.scope}；局部替换，不重排其它类型。"
            )
            operations.append(
                ItineraryPatchOperation(
                    op="replace_segment_poi",
                    segmentId=getattr(segment, "id", ""),
                    amapPoi=replacement,
                    notes=note,
                )
            )
            selected_poi_names.append(replacement.name)
        if not operations:
            pending_records = []
            if concrete_night_view:
                pending_records = self._record_timeline_pending_poi_candidates(
                    session_id,
                    user_turn_id,
                    plan,
                    command,
                    target_segments,
                    candidates,
                    reason="no_unique_reliable_night_view_candidate",
                )
            reply = (
                "本轮没有唯一可靠的夜景地点可直接写入，已返回候选供你确认；未修改当前时间轴，也没有进入通用工具循环。"
                if pending_records
                else "本轮没有找到足够可靠的替换候选，未修改当前时间轴，也没有进入通用工具循环。"
            )
            return self._timeline_command_noop_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                reply,
                preview={
                    "changed": False,
                    "toolLoopEntered": False,
                    "amapCallBudget": amap_budget.snapshot(),
                    "providerDebug": provider_debug[:4],
                    "pendingCandidateRecords": pending_records,
                },
            )
        scope_label = "高校" if command.scope == "campus" else "夜景"
        if concrete_night_view:
            selected_label = "、".join(name for name in selected_poi_names if name) or "高德地点"
            reply = (
                f"已将当前时间轴中的夜景段替换为真实地图地点「{selected_label}」。"
                "本轮只确认地图地点；开放时间、门票、预约和节假日管控需要出行前再核验。"
            )
        else:
            reply = f"已只替换当前时间轴中的{scope_label}段，餐饮和其它类型日程未重排。"
        return self._timeline_command_patch_response(
            session_id,
            user_turn_id,
            content,
            user_turn,
            session,
            request_context,
            command,
            operations,
            reply,
            warnings=[],
            result_preview={
                "changedScope": "night_view_concrete_grounding" if concrete_night_view else f"{command.scope}_only",
                "changedSegmentIds": [operation.segment_id for operation in operations if operation.segment_id],
                "selectedPoiNames": selected_poi_names[:8],
                "toolLoopEntered": False,
                "webSearchCalls": 0,
                "ticketLookupCalls": 0,
                "amapWeatherCalls": 0,
                "amapCallBudget": amap_budget.snapshot(),
                "providerDebug": provider_debug[:4],
            },
        )

    def _timeline_command_patch_response(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
        operations: list[ItineraryPatchOperation],
        reply: str,
        *,
        warnings: list[str],
        result_preview: dict[str, Any],
        auto_update_memory: bool = True,
    ) -> AgentMessageResponse:
        route_preflight_passed, route_insertion_proofs, route_failure = self._preflight_timeline_patch_route_matrix(
            session=session,
            operations=operations,
            request_context=request_context,
            command=command,
        )
        if not route_preflight_passed:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                (
                    "路线 Provider 尚未证明该地点在当前交通方式和时间窗内可行，"
                    f"本轮保持原行程不变（{route_failure or 'route_matrix_pending'}）。"
                ),
                terminal_status="needs_confirmation",
            )
        if route_insertion_proofs:
            request_context = {
                **request_context,
                "routeInsertionProofs": copy.deepcopy(route_insertion_proofs),
            }
            result_preview = {
                **result_preview,
                "routeInsertionProofs": copy.deepcopy(route_insertion_proofs),
            }
        patch_response = ItineraryPatchService(self.db).apply_patch(
            session["active_plan_id"],
            operations,
            source_type="agent",
            base_version_id=session["active_version_id"],
            source_turn_id=user_turn_id,
            preference_summary=self._preference_summary_from_context(request_context),
            planning_context=self._timeline_command_planning_context(
                command, request_context=request_context, session_id=session_id
            ),
        )
        verifier_report = (
            self._verify_agent_result_or_restore(session, patch_response)
            if command.intent == "accepted_action_executor"
            else self._safe_verify_current_state(self._session(session_id), "agent_timeline_edit")
        )
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            reply,
            "active",
            agent_request_json={**request_context, "timelineCommand": command.as_dict()},
            agent_response_json={
                "mode": "timeline_edit",
                "reply": reply,
                "timelineCommand": command.as_dict(),
                "operations": [operation.model_dump(by_alias=True, exclude_none=True) for operation in operations],
                "warnings": warnings,
            },
        )
        planning_run = PlanningRunService(self.db).create_run(
            "agent_timeline_edit",
            user_input=content,
            preference_summary=self._preference_summary_from_context(request_context),
            itinerary=patch_response.itinerary,
            itinerary_version_id=patch_response.version.id,
            understood_requirements=request_context.get("understoodRequirements"),
            final_summary=reply,
        )
        ItineraryPatchService(self.db).attach_planning_run(patch_response.patch.id, planning_run.id)
        tool_events: list[dict[str, Any]] = [
            self._autonomy_observation_pipeline_event(request_context),
            self._autonomy_decision_pipeline_event(request_context),
        ]
        preview = {"timelineCommand": command.as_dict(), "operationCount": len(operations), **result_preview}
        self._append_pipeline_event(
            tool_events,
            "timeline_edit",
            "精确时间轴编辑",
            "completed",
            "已通过服务端确定性局部编辑写入 patch，没有进入通用 tool loop。",
            preview,
        )
        self._append_pipeline_event(
            tool_events,
            "patch_itinerary",
            "写入局部时间轴 patch",
            "completed",
            "已通过合法 ItineraryPatchOperation 写入当前版本。",
            {
                "patchId": patch_response.patch.id,
                "activeVersionId": patch_response.version.id,
                "operationCount": len(operations),
                "changedScope": result_preview.get("changedScope"),
                "changedSegmentIds": list(result_preview.get("changedSegmentIds") or []),
                "globalReorder": False,
            },
        )
        changed_segment_ids = [str(item) for item in result_preview.get("changedSegmentIds") or [] if str(item)]
        self._append_pipeline_event(
            tool_events,
            "agent_action_outcome",
            "记录自治动作结果",
            "completed" if verifier_report.passed else "failed",
            "已从实际 patch、version 和 verifier 读取时间轴编辑结果。",
            {
                "cycleIndex": 0,
                "decisionId": (request_context.get("agentDecision") or {}).get("decisionId"),
                "action": "patch_itinerary",
                "executionRoute": "deterministic_timeline_patch",
                "baseVersionId": session["active_version_id"],
                "resultVersionIds": [patch_response.version.id],
                "patchIds": [patch_response.patch.id],
                "changedSegmentIds": changed_segment_ids,
                "changedScope": result_preview.get("changedScope") or command.operation,
                "verifierPassed": verifier_report.passed,
                "rollbackPerformed": not verifier_report.passed,
                "toolLoopEntered": False,
            },
        )
        post_observation = self.autonomy_observation_builder.build(
            {
                **request_context,
                "activeVersionId": patch_response.version.id,
                "currentItinerarySnapshot": patch_response.itinerary.model_dump(by_alias=True),
            },
            cycle_index=1,
            last_action={"action": "patch_itinerary", "executionRoute": "deterministic_timeline_patch"},
            last_outcome={
                "verifierPassed": verifier_report.passed,
                "resultVersionId": patch_response.version.id,
                "patchId": patch_response.patch.id,
            },
        )
        tool_events.append(
            self._autonomy_observation_pipeline_event(
                request_context,
                observation=post_observation.model_dump(by_alias=True),
            )
        )
        stop_reason = self.autonomy_stop_policy.evaluate(
            post_observation,
            cycle_index=1,
            max_cycles=2,
            verifier_passed=verifier_report.passed,
        ).reason or ("verified_patch" if verifier_report.passed else "verifier_failed_and_rolled_back")
        self._append_pipeline_event(
            tool_events,
            "agent_stop",
            "自治循环停止",
            "completed",
            "时间轴局部编辑已完成；本轮不会额外执行未授权动作。",
            {
                "cycleIndex": 1,
                "stopReason": stop_reason,
                "observationFingerprint": post_observation.state_fingerprint,
            },
        )
        planning_events = self._safe_planning_events_from_tool_events(
            tool_events,
            session_id,
            assistant_turn_id,
            patch_response.version.id,
            verifier_report=verifier_report,
        )
        planning_events = self._order_autonomy_outcome_after_verifier(planning_events, assistant_turn_id)
        self._store_planning_events(assistant_turn_id, planning_events)
        if auto_update_memory:
            self._auto_update_preference_memory(session_id, content, reply)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=patch_response.itinerary,
            version=patch_response.version,
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=warnings,
            planningRun=planning_run,
            planningSteps=planning_events,
            toolEvents=planning_events,
        )

    def _preflight_timeline_patch_route_matrix(
        self,
        *,
        session: sqlite3.Row,
        operations: list[ItineraryPatchOperation],
        request_context: dict[str, Any],
        command: TimelineEditCommand,
    ) -> tuple[bool, list[dict[str, Any]], Optional[str]]:
        """Verify every concrete POI replacement before the shared writer."""

        replacements = {
            str(operation.segment_id or ""): operation.amap_poi
            for operation in operations
            if operation.op == "replace_segment_poi" and operation.segment_id and operation.amap_poi is not None
        }
        if not replacements:
            return True, [], None
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
        (
            tolerance,
            mobility_profile,
            route_decision_contract,
            tolerance_source,
        ) = self._route_detour_tolerance(
            request_context,
            command=command,
        )
        if tolerance is None or mobility_profile is None or route_decision_contract is None:
            return False, [], tolerance_source
        proofs: list[dict[str, Any]] = []
        for segment_id, candidate in replacements.items():
            located = next(
                (
                    (day, index, segment)
                    for day in plan.days
                    for index, segment in enumerate(day.segments)
                    if str(segment.id) == segment_id
                ),
                None,
            )
            if located is None:
                return False, proofs, "route_matrix_target_missing"
            day, target_index, target = located

            def final_point(index: int) -> Optional[dict[str, Any]]:
                segment = day.segments[index]
                replacement = replacements.get(str(segment.id))
                if replacement is not None:
                    return self._route_matrix_point(
                        segment,
                        day_id=str(day.id),
                        replacement=replacement,
                    )
                return self._route_matrix_point(segment, day_id=str(day.id))

            previous = next(
                (point for index in range(target_index - 1, -1, -1) if (point := final_point(index)) is not None),
                None,
            )
            following = next(
                (
                    point
                    for index in range(target_index + 1, len(day.segments))
                    if (point := final_point(index)) is not None
                ),
                None,
            )
            candidate_point = self._route_matrix_point(
                target,
                day_id=str(day.id),
                replacement=candidate,
            )
            if candidate_point is None:
                return False, proofs, "route_matrix_candidate_invalid"
            baseline = self._route_matrix_point(target, day_id=str(day.id))
            start = self._minutes(getattr(target, "start_time", ""))
            end = self._minutes(getattr(target, "end_time", ""))
            duration = max(0, end - start) if end >= start else 0
            transport_mode = str(
                getattr(target, "transport_mode", "") or request_context.get("transportMode") or "transit"
            )
            result = self.provider_route_insertion_service.evaluate(
                plan_id=f"timeline_patch_preflight_{segment_id}",
                previous=previous,
                candidate=candidate_point,
                following=following,
                baseline_candidate=baseline,
                transport_mode=transport_mode,
                detour_tolerance=tolerance,
                candidate_duration_minutes=duration,
                mobility_profile=mobility_profile,
                route_decision_contract=route_decision_contract,
            )
            proof = {
                **result.to_dict(),
                "operation": "replace_poi",
                "segmentId": segment_id,
                "baseVersionId": str(session["active_version_id"] or ""),
                "candidateAmapId": str(candidate.id or ""),
                "toleranceSource": tolerance_source,
            }
            proofs.append(proof)
            if not result.passed:
                return False, proofs, result.failure_reason
        return True, proofs, None

    @staticmethod
    def _route_matrix_point(
        segment: Any,
        *,
        day_id: str,
        replacement: Optional[MapPoiResponse] = None,
    ) -> Optional[dict[str, Any]]:
        poi = replacement or getattr(segment, "poi", None)
        if poi is None:
            return None
        source = str(getattr(poi, "source", "") or "")
        amap_id = str(
            getattr(poi, "id", "") if replacement is not None else getattr(poi, "amap_id", "") or getattr(poi, "id", "")
        )
        try:
            longitude = float(getattr(poi, "longitude", None))
            latitude = float(getattr(poi, "latitude", None))
        except (TypeError, ValueError):
            return None
        if source != AMAP_PLACE_SOURCE or not amap_id:
            return None
        return {
            "segmentId": str(getattr(segment, "id", "")),
            "dayId": day_id,
            "amapId": amap_id,
            "name": str(getattr(poi, "name", "") or amap_id),
            "city": str(getattr(poi, "city", "") or ""),
            "type": str(getattr(poi, "type", "") or "route_anchor"),
            "source": source,
            "longitude": longitude,
            "latitude": latitude,
            "startTime": str(getattr(segment, "start_time", "") or ""),
            "endTime": str(getattr(segment, "end_time", "") or ""),
        }

    @staticmethod
    def _route_detour_tolerance(
        request_context: dict[str, Any],
        *,
        command: TimelineEditCommand,
    ) -> tuple[
        Optional[dict[str, float]],
        Optional[dict[str, Any]],
        Optional[dict[str, Any]],
        str,
    ]:
        """Resolve one server-owned route contract without policy defaults.

        The command scope is retained in the proof provenance, but it cannot
        select a looser per-call tolerance.  The canonical request contract is
        the only authority for both the Provider matrix and the downstream
        writer/verifier replay.
        """

        request_contract = (
            request_context.get("requestIntentContract")
            if isinstance(request_context.get("requestIntentContract"), dict)
            else {}
        )
        raw_contract = request_contract.get("routeDecisionContract")
        if not isinstance(raw_contract, dict):
            raw_contract = request_context.get("routeDecisionContract")
        normalized = RouteInsertionScorer.normalized_route_decision_contract(raw_contract)
        if normalized is None:
            return (
                None,
                None,
                None,
                "route_decision_contract_missing_or_invalid",
            )
        source = (
            "requestIntentContract.routeDecisionContract"
            if isinstance(request_contract.get("routeDecisionContract"), dict)
            else "requestContext.routeDecisionContract"
        )
        return (
            copy.deepcopy(normalized["detourTolerance"]),
            copy.deepcopy(normalized["mobilityProfile"]),
            copy.deepcopy(normalized),
            f"{source}:{str(command.scope or 'timeline_edit')}",
        )

    def _timeline_command_planning_context(
        self,
        command: TimelineEditCommand,
        *,
        request_context: Optional[dict[str, Any]] = None,
        session_id: Optional[str] = None,
    ) -> dict[str, Any]:
        context = {
            "timelineCommand": command.as_dict(),
            "stagedPlanningPipeline": {"enabled": True, "mode": "timeline_edit"},
            "toolRefreshPolicy": {
                "route": "touched_pairs_only",
                "weather": "skip",
                "ticket": "skip",
                "risk": "skip",
            },
            "refreshTouchedRoutes": True,
            "skipWeatherRefresh": True,
            "skipTicketRefresh": True,
            "skipRiskRefresh": True,
        }
        if session_id:
            context["sessionId"] = session_id
        deadline = (request_context or {}).get("runtimeDeadlineMonotonic")
        if isinstance(deadline, (int, float)):
            context["runtimeDeadlineMonotonic"] = deadline
        proofs = (request_context or {}).get("routeInsertionProofs")
        if isinstance(proofs, list):
            context["routeInsertionProofs"] = copy.deepcopy(proofs)
        request_contract = (
            (request_context or {}).get("requestIntentContract")
            if isinstance((request_context or {}).get("requestIntentContract"), dict)
            else {}
        )
        route_decision_contract = request_contract.get("routeDecisionContract")
        if not isinstance(route_decision_contract, dict):
            route_decision_contract = (request_context or {}).get("routeDecisionContract")
        normalized_route_contract = RouteInsertionScorer.normalized_route_decision_contract(route_decision_contract)
        if normalized_route_contract is not None:
            # Normalization is a validation boundary only.  The writer must
            # receive the exact server-owned envelope so schema/status/missing
            # metadata survives a topology edit and subsequent save-back.
            context["routeDecisionContract"] = copy.deepcopy(route_decision_contract)
        return context

    def _record_timeline_pending_poi_candidates(
        self,
        session_id: str,
        user_turn_id: str,
        plan: Any,
        command: TimelineEditCommand,
        target_segments: list[Any],
        candidates: list[MapPoiResponse],
        *,
        reason: str,
    ) -> list[dict[str, Any]]:
        if not target_segments or not candidates:
            return []
        pending_candidates: list[MapPoiResponse] = []
        seen: set[str] = set()
        for candidate in candidates:
            key = str(candidate.id or "") or self._normalize_timeline_entity(candidate.name)
            if not key or key in seen:
                continue
            if candidate.source != AMAP_PLACE_SOURCE:
                continue
            if command.scope == "meal" and self.poi_trust_policy.is_mock_or_synthetic_candidate(candidate):
                continue
            if not self._valid_timeline_candidate_coord(candidate):
                continue
            if command.scope == "night_view":
                text = " ".join(
                    [candidate.name or "", candidate.type or "", candidate.category or "", candidate.address or ""]
                )
                if self.night_view_candidate_policy.placeholder_reject_reason(candidate.name, text):
                    continue
            seen.add(key)
            pending_candidates.append(candidate)
            if len(pending_candidates) >= 5:
                break
        if not pending_candidates:
            return []
        segment_id = str(getattr(target_segments[0], "id", "") or "")
        city = str(getattr(plan, "city", "") or "")
        query = "夜景具体地点" if command.scope == "night_view" else command.scope
        category = "scenic" if command.scope == "night_view" else command.scope
        candidate_id = f"cand_{uuid4().hex[:12]}"
        self.db.execute(
            """
            INSERT INTO amap_poi_candidates (
                id, session_id, turn_id, query, segment_id, city, category, status,
                candidates_json, selected_amap_id, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                candidate_id,
                session_id,
                user_turn_id,
                query,
                segment_id,
                city,
                category,
                "pending",
                json.dumps([poi.model_dump(by_alias=True) for poi in pending_candidates], ensure_ascii=False),
                None,
                datetime.now(timezone.utc).isoformat(),
            ),
        )
        return [
            {
                "candidateRecordId": candidate_id,
                "query": query,
                "reason": reason,
                "segmentId": segment_id,
                "candidateCount": len(pending_candidates),
                "candidateNames": [poi.name for poi in pending_candidates[:5]],
            }
        ]

    @staticmethod
    def _remaining_runtime_after_io(remaining_ms: int, started_perf: float) -> int:
        """Charge ingress I/O to the existing run; never start a new budget."""
        return max(0, remaining_ms - max(0, int((time.perf_counter() - started_perf) * 1000)))

    def _runtime_limits_for_request(self, request_context: dict[str, Any]) -> AgentRuntimeLimits:
        agent_plan = request_context.get("agentPlan") if isinstance(request_context.get("agentPlan"), dict) else {}
        if agent_plan.get("taskType") == "local_modification":
            return AgentRuntimeLimits(
                max_tool_rounds=3,
                max_tool_calls_per_round=2,
                max_run_seconds=30,
                max_tool_seconds=12,
                max_patch_seconds=8,
            )
        return AgentRuntimeLimits()

    def _handle_fill_dinner_command(
        self,
        session_id: str,
        user_turn_id: str,
        content: str,
        user_turn: ConversationTurnResponse,
        session: sqlite3.Row,
        request_context: dict,
        command: TimelineEditCommand,
    ) -> AgentMessageResponse:
        plan = ItineraryService(self.db).get_plan(session["active_plan_id"])
        day = self._timeline_command_day(plan, command.day_number)
        if day is None:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                f"没有找到第 {command.day_number or '?'} 天，未修改当前时间轴。",
            )
        existing_dinner = next(
            (
                segment
                for segment in day.segments
                if segment.kind == "meal" and self._minutes(segment.start_time) >= 17 * 60
            ),
            None,
        )
        if (command.time_window in {None, "auto", "dinner"}) and existing_dinner is not None:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                f"第 {day.day_number} 天已有晚餐段，未重复新增。",
            )
        meal_label = self._meal_label_for_command(command)
        food_intent = str(command.constraints.get("foodIntent") or "当地特色美食").strip() or "当地特色美食"
        start_time = self._meal_insert_start_time(day, command)
        if not start_time:
            return self._timeline_command_failed_response(
                session_id,
                user_turn,
                session,
                content,
                request_context,
                command,
                f"第 {day.day_number} 天{meal_label}没有可用空档，未修改当前时间轴。",
            )
        duration = 75
        slot = DaySlot(
            slot_id=f"day{day.day_number}_{meal_label}_manual_fill",
            day_number=day.day_number,
            date=day.date or "",
            time_window=f"{start_time}-{self._format_minutes(self._minutes(start_time) + duration)}",
            start_time=start_time,
            duration_minutes=duration,
            kind="meal",
            raw_need=f"{meal_label} {food_intent}",
            route_anchor=False,
        )
        notes = self._append_memory_rule_note(
            "groundingStatus：waiting_for_poi_grounding；intentType=meal；高德 POI 待校验；可展开附近餐饮候选。",
            self._meal_cost_note(slot, request_context),
        )
        operation = ItineraryPatchOperation(
            op="add_segment",
            dayId=day.id,
            startTime=start_time,
            title=f"{meal_label} {food_intent}",
            kind="meal",
            notes=notes,
            durationMinutes=duration,
            estimatedCost=self._meal_estimated_cost(slot, request_context),
            transportMode=self._transport_mode_from_context(request_context) or "walk",
            allowUnresolved=True,
        )
        patch_response = ItineraryPatchService(self.db).apply_patch(
            session["active_plan_id"],
            [operation],
            source_type="agent",
            base_version_id=session["active_version_id"],
            source_turn_id=user_turn_id,
            preference_summary=self._preference_summary_from_context(request_context),
            planning_context=self._timeline_command_planning_context(command),
        )
        patched_session = self._session(session_id)
        reply = f"已只补第 {day.day_number} 天{meal_label}，放在 {start_time}，其他日期和已有地点未重排。餐饮地点仍待高德候选补全。"
        assistant_turn_id = self._insert_turn(
            session_id,
            "assistant",
            reply,
            "active",
            agent_request_json={**request_context, "timelineCommand": command.as_dict()},
            agent_response_json={
                "mode": "timeline_edit",
                "reply": reply,
                "timelineCommand": command.as_dict(),
                "operations": [operation.model_dump(by_alias=True, exclude_none=True)],
                "warnings": ["餐饮地点仍待展开附近餐饮候选。"],
            },
        )
        planning_run = PlanningRunService(self.db).create_run(
            "agent_timeline_edit",
            user_input=content,
            preference_summary=self._preference_summary_from_context(request_context),
            itinerary=patch_response.itinerary,
            itinerary_version_id=patch_response.version.id,
            understood_requirements=request_context.get("understoodRequirements"),
            final_summary=reply,
        )
        ItineraryPatchService(self.db).attach_planning_run(patch_response.patch.id, planning_run.id)
        verifier_report = self._safe_verify_current_state(patched_session, "agent_timeline_edit")
        tool_events: list[dict[str, Any]] = []
        self._append_pipeline_event(
            tool_events,
            "timeline_edit",
            "精确时间轴编辑",
            "completed",
            "已识别局部编辑命令，只新增目标日期餐饮，没有重排其它日期。",
            {
                "timelineCommand": command.as_dict(),
                "operation": operation.model_dump(by_alias=True, exclude_none=True),
                "activeVersionId": patch_response.version.id,
                "changedScope": "day_meal_insert_only",
                "toolLoopEntered": False,
                "webSearchCalls": 0,
                "ticketLookupCalls": 0,
                "amapWeatherCalls": 0,
            },
        )
        self._append_pipeline_event(
            tool_events,
            "patch_itinerary",
            "写入局部时间轴 patch",
            "completed",
            "已通过 add_segment 写入待补全晚餐段，并保留高德候选展开入口。",
            {
                "patchId": patch_response.patch.id,
                "activeVersionId": patch_response.version.id,
                "changedDayNumber": day.day_number,
                "changedSegmentKind": "meal",
                "globalReorder": False,
            },
        )
        planning_events = self._safe_planning_events_from_tool_events(
            tool_events,
            session_id,
            assistant_turn_id,
            patch_response.version.id,
            verifier_report=verifier_report,
        )
        self._store_planning_events(assistant_turn_id, planning_events)
        self._auto_update_preference_memory(session_id, content, reply)
        self.db.commit()
        return AgentMessageResponse(
            userTurn=user_turn,
            assistantTurn=self._turn_response(assistant_turn_id),
            itinerary=patch_response.itinerary,
            version=patch_response.version,
            pendingPoiCandidates=ConversationService(self.db)._pending_candidates(session_id),
            warnings=["餐饮地点仍待展开附近餐饮候选。"],
            planningRun=planning_run,
            planningSteps=planning_events,
            toolEvents=planning_events,
        )

